P.entries["quest:94896"] = {n="Aid For The Refugees",s="Aid For The Refugees se concentra nos sobreviventes deslocados de Ban'aethal, um assentamento nas profundezas da Floresta Umbréola que foi evacuado repentinamente no meio da noite. Com seu lar caindo em direção ao céu e a região selvagem ao redor tendo se tornado perigosa demais para adentrar, os refugiados dependem de viajantes corajosos para recuperar os pertences que tiveram de deixar para trás.",h="Aid For The Refugees se concentra nos sobreviventes deslocados de Ban'aethal, um assentamento nas profundezas...",kw={"aid for the refugees","ban'aethal","banaethal","pertences","ealaane","refugiados","floresta umbréola"},sec={{t="Um Apelo Desesperado",b="Aid for the Refugees é um apelo de assistência de Ealaane e de seus companheiros aldeões desabrigados. Tendo escapado por pouco de seus lares nas profundezas da Floresta Umbréola, os sobreviventes reuniram-se quase sem nada em suas posses, na esperança de que um viajante de passagem enfrente os perigos deixados para trás."},{t="A Calamidade de Ban'aethal",b="O assentamento de Ban'aethal teve um destino impensável na calada da noite, quando a vila subitamente começou a cair no céu. A calamidade bizarra e aterrorizante deu aos habitantes meros instantes para fugir, forçando-os a abandonar seus pertences pessoais enquanto os bosques ao redor tornavam-se hostis e perigosos."}},faq={{q="Quem é Ealaane?",a="Ealaane é uma refugiada de Ban'aethal que fugiu com outros quando seu assentamento começou a ruir. Ela pede a aventureiros de passagem que viajam em direção à Floresta Umbréola que recuperem pertences pessoais deixados para trás nas ruínas.",al={"quem deu aid for the refugees","concedente da missão aid for the refugees","ealaane"}},{q="O que aconteceu com Ban'aethal?",a="Ban'aethal era um assentamento situado nas profundezas da Floresta Umbréola. Seus residentes foram forçados recentemente a evacuar no meio da noite devido a uma catástrofe repentina e bizarra.",al={"o que é banaethal","onde fica banaethal","vila de ban aethal"}},{q="Por que os aldeões tiveram que evacuar Ban'aethal?",a="A evacuação foi desencadeada repentinamente no meio da noite quando Ban'aethal começou a cair no céu. A vila e a floresta ao redor tornaram-se perigosas demais para que os moradores ficassem ou retornassem.",al={"por que evacuar banaethal","caindo no céu","desastre de ban aethal"}},{q="Por que os aldeões estão pedindo para que seus pertences sejam recuperados?",a="A catástrofe ocorreu repentinamente no meio da noite, forçando os aldeões a fugir para salvar suas vidas praticamente sem nada. Com a floresta e as ruínas agora tomadas pelo perigo, eles dependem de aventureiros capazes para recuperar o que foi deixado para trás.",al={"por que precisam de pertences","pertences abandonados","por que recuperar pertences"}},{q="O que é a Floresta Umbréola?",a="A Floresta Umbréola é a região arborizada que abriga o assentamento de Ban'aethal. Após o desastre bizarro que despedaçou a vila, a floresta tornou-se extremamente perigosa para as pessoas comuns.",al={"onde fica a floresta umbréola","história da floresta umbréola"}},{q="Os refugiados podem retornar aos seus lares?",a="Não. De acordo com Ealaane, tanto a Floresta Umbréola quanto as Ruínas de Ban'aethal são perigosas demais para que os moradores deslocados consigam retornar por conta própria.",al={"refugiados podem voltar","banaethal é segura"}}},fp="20,237,16.174.0,26.196.0,15.173.0,28.138.0,50.180.0,66.227.0,26.166.0,39.121.0"}
P.entries["quest:94897"] = {n="The Fate of a Loved One",s="The Fate of a Loved One é uma missão sobre Resaan, que se aventurou nas perigosas Ruínas de Ban'aethal para buscar suprimentos e nunca mais voltou. Mais de uma semana depois, seu parceiro em luto pede aos viajantes que vão para as ruínas que descubram seu paradeiro e o tragam para casa ou recuperem sua querida relíquia de família.",h="The Fate of a Loved One é uma missão sobre Resaan, que se aventurou nas perigosas Ruínas de Ban'aethal para...",kw={"ban'aethal","relíquia de família","resaan","ruínas de ban'aethal","suprimentos","the fate of a loved one"},sec={{t="Um Apelo Desesperado",b="The Fate of a Loved One gira em torno de um apelo desesperado de alguém cujo parceiro, Resaan, aventurou-se de volta às Ruínas de Ban'aethal. Apesar dos pedidos sinceros para que ficasse, Resaan sentiu-se compelido a enfrentar as ruínas em busca de suprimentos, deixando para trás alguém que agora espera em uma incerteza angustiante."},{t="Desaparecido nas Ruínas",b="Mais de uma semana se passou desde que Resaan partiu, superando em muito qualquer expectativa razoável de um retorno rápido. Viajantes a caminho de Ban'aethal recebem súplicas para procurá-lo entre as ruínas — para guiá-lo de volta se ainda restar vida, ou para recuperar sua relíquia de família se apenas uma tragédia restar para ser encontrada."}},faq={{q="Quem é Resaan?",a="Resaan é um indivíduo que se aventurou de volta às Ruínas de Ban'aethal para reunir suprimentos, apesar de receberem súplicas para ficar. Após mais de uma semana sem notícias, seu parceiro teme que ele tenha encontrado um fim trágico entre as ruínas.",al={"quem é resaan","onde está resaan","encontrar resaan"}},{q="O que são as Ruínas de Ban'aethal?",a="As Ruínas de Ban'aethal são um local perigoso onde Resaan se aventurou em busca de suprimentos necessários. Seu parceiro considera a jornada perigosa o suficiente para que sobreviver uma semana lá sozinho seja improvável.",al={"o que é banaethal","história das ruínas de banaethal","onde fica banaethal"}},{q="Por que Resaan retornou a Ban'aethal?",a="Resaan retornou a Ban'aethal especificamente para buscar suprimentos. Ele decidiu fazer a perigosa jornada mesmo com seu parceiro implorando para que ele não fosse.",al={"por que resaan voltou","por que resaan está em banaethal"}},{q="O que o doador da missão pede para você trazer de volta?",a="Se Resaan ainda estiver vivo, o doador da missão pede que ele seja trazido em segurança para casa. Se ele tiver morrido nas ruínas, o doador da missão implora pela recuperação de sua relíquia de família como uma lembrança final.",al={"o que o doador da missão quer","o que acontece se resaan estiver morto"}},{q="Há quanto tempo Resaan está desaparecido?",a="Resaan está desaparecido há mais de uma semana desde que partiu para as Ruínas de Ban'aethal. Diante dos perigos da área, esse silêncio prolongado leva seu parceiro a temer o pior.",al={"há quanto tempo resaan está desaparecido","há quanto tempo resaan se foi"}},{q="Quem oferece esta missão?",a="A missão é oferecida pelo parceiro ou companheiro em luto de Resaan, que continua desesperado por um desfecho e disposto a pedir ajuda aos viajantes que passam em direção a Ban'aethal.",al={"quem dá the fate of a loved one","doador da missão the fate of a loved one"}}},fp="23,187,16.187.0,21.250.0,14.178.0,33.131.0,36.92.0,47.155.0,33.146.0,22.123.0"}
P.entries["quest:949"] = {n="O Acampamento do Crepúsculo",s="O Acampamento do Crepúsculo é uma missão de reconhecimento da Aliança voltada para os cultistas sigilosos acampados ao redor da Glaive do Mestre, no sul de Costa Negra. Após vislumbrarem o local do ritual por meio de uma tigela de vidência, os investigadores devem se infiltrar na escavação para descobrir o que o Martelo do Crepúsculo busca desenterrar.",h="O Acampamento do Crepúsculo é uma missão de reconhecimento da Aliança voltada para os cultistas sigilosos...",kw={"costa negra","glaive do mestre","onu","scrying bowl","o acampamento do crepusculo","twilight tome","martelo do crepusculo"},ang={["class:Druid"]="Descobrir as pesquisas do culto é essencial para que os guardiões cenarianos mantenham entidades ancestrais corruptoras devidamente sepultadas.",["faction:Alliance"]="Interromper as estranhas escavações do culto impede que uma ameaça crescente desestabilize o norte de Kalimdor.",["race:NightElf"]="O Martelo do Crepúsculo profana as terras sagradas de Kalimdor com feitiçarias sombrias bem sob as copas dos antigos arvoredos de Costa Negra."},sec={{t="Sondando a Escavação",b="A Glaive do Mestre há muito se ergue como um mistério petrificado e sinistro ao longo das colinas escarpadas do sul de Costa Negra, mas a chegada repentina do culto do Martelo do Crepúsculo transformou uma antiga curiosidade em uma ameaça ativa. Depois de usar uma tigela de vidência para perscrutar suas fortificações, batedores são enviados para o meio do acampamento para determinar seus verdadeiros planos antes que medidas defensivas possam ser tomadas."},{t="O Tomo Ilustrado",b="Vasculhar o acampamento revela que os cultistas não são meros saqueadores ou bandidos; sua operação é guiada por um profundo estudo ocultista. Bem no interior do acampamento ao norte repousa um tomo antigo, meticulosamente impresso à mão e ilustrado com uma arte magistral, porém perturbadora. Esse texto serve como prova de que o Martelo do Crepúsculo está deliberadamente investigando a entidade colossal enterrada sob a terra."}},faq={{q="Qual é o objetivo da missão O Acampamento do Crepúsculo?",a="Você deve se infiltrar no acampamento do Martelo do Crepúsculo perto da Glaive do Mestre, no sul de Costa Negra, e recuperar uma pista detalhando seus motivos — especificamente um livro ritual impresso à mão que se encontra no acampamento.",al={"objetivo da missao o acampamento do crepusculo","o que fazer em o acampamento do crepusculo"}},{q="Quem envia você para investigar o acampamento?",a="A missão é obtida diretamente na Scrying Bowl no mirante acima da Glaive do Mestre, dando continuidade à investigação iniciada em nome do antigo protetor Onu.",al={"quem da o acampamento do crepusculo","doador da missao o acampamento do crepusculo"}},{q="Onde a pista é encontrada no acampamento?",a="A pista válida é o Twilight Tome situado na parte norte do acampamento. Outros tomos no acampamento podem ser perigosas iscas que liberam magia de proteção contra invasores.",al={"onde fica o livro","localizacao do twilight tome","encontrar pista o acampamento do crepusculo"}},{q="Por que o Martelo do Crepúsculo está na Glaive do Mestre?",a="Os cultistas são obcecados pelos poderes sombrios e ancestrais dos Deuses Antigos e de seus servos. Eles estão escavando a enorme carcaça petrificada cravada pela lâmina de pedra gigante para estudar ou despertar qualquer mal ancestral que permaneça ali.",al={"por que cultistas estao na glaive do mestre","objetivo do martelo do crepusculo em costa negra"}},{q="O que acontece após encontrar o tomo?",a="Recuperar o tomo leva à missão A volta a Onu, instruindo você a levar os escritos descobertos para o norte, até o antigo anciente no Bosque dos Ancientes.",al={"proxima missao depois de o acampamento do crepusculo","para onde ir depois do twilight tome"}}},fx={["8554815a"]={q="Por que a Tigela de Vidência manda você investigar o acampamento?",a="A tigela de vidência de Onu revela que sectários do Martelo do Crepúsculo se reuniram ao redor da Glaive do Mestre, onde um antigo senhor caiu há muito tempo. Ninguém sabe o que eles procuram ali, mas Onu tem certeza de que suas intenções são sombrias. Antes que ele e os defensores do bosque possam traçar um plano, precisam obter algo do acampamento que revele as intenções do culto.",al={"por que investigar o acampamento do crepúsculo","para que serve a tigela de vidência","por que vasculhar o acampamento do crepúsculo"}}},fp="17,240,15.204.0,20.195.1,44.149.0,38.146.0,36.119.0,52.204.0,36.121.0"}
P.entries["quest:94907"] = {n="A Small Favor",s="Pedem a uma druida que leve a magia do Martelo do Crepúsculo até sua origem no Twilight Shroud. Amberhall quer capturar um lacaio do culto para interrogá-lo.",h="Pedem a uma druida que leve a magia do Martelo do Crepúsculo até sua origem no Twilight Shroud.",kw={"um pequeno favor","amberhall","conduto","druida","reagentes","pedra da alma","ritual de invocação","twilight shroud","martelo do crepúsculo","thrall do crepúsculo"},ang={["class:Druid"]="Como druida, você é quem Amberhall chama de boa druida obediente antes de pedir esse favor."},sec={{t="Um Favor da Druida",b="Amberhall pede sua ajuda no Twilight Shroud. Os reagentes que você reuniu estão sintonizados com a magia do Martelo do Crepúsculo, e Amberhall diz que podem ser usados em um ritual de invocação. Para chegar à origem desse poder, pedem que você use um conduto para chamar um Thrall do Crepúsculo e capturá-lo com a Pedra da Alma de Amberhall."}},faq={{q="O que Amberhall quer que eu faça?",a="Amberhall pede que você invoque um Thrall do Crepúsculo por um conduto no Twilight Shroud e o capture com a Pedra da Alma de Amberhall.",al={"favor de amberhall","pequeno favor","o que fazer"}},{q="Por que os reagentes são úteis?",a="Os reagentes estão sintonizados com a magia do Martelo do Crepúsculo, o que os torna adequados para um ritual de invocação.",al={"para que servem os reagentes","por que os reagentes","reagentes para magia do crepúsculo"}},{q="Onde uso o conduto?",a="O conduto fica no Twilight Shroud.",al={"localização do conduto","onde invocar o lacaio","conduto no twilight shroud"}},{q="Por que capturar o lacaio?",a="Amberhall quer que o Thrall do Crepúsculo seja capturado para interrogatório.",al={"por que usar a pedra da alma","por que capturar o lacaio","interrogatório do thrall"}}},fp="13,143,15.307.0,34.129.0,28.97.0,27.42.0,23.63.0"}
P.entries["quest:94911"] = {n="Child of Nature",s="Um membro dos Skyborne vê potencial em suas artes druídicas e indica Turak Runa Totem, no Penhasco do Trovão. Ele pode ensinar você a chegar à fortaleza do Círculo Cenariano, na Clareira da Lua.",h="Um membro dos Skyborne vê potencial em suas artes druídicas e indica Turak Runa Totem, no Penhasco do Trovão.",kw={"círculo cenariano","filho da natureza","druida","clareira da lua","skyborne","penhasco do trovão","turak runa totem"},ang={["class:Druid"]="Como druida, você é encaminhado a Turak Runa Totem, que pode ensinar você a chegar ao Círculo Cenariano, na Clareira da Lua.",["race:Skyborne"]="Como membro dos Skyborne, você é informado de que os druidas do Círculo Cenariano vão acolher você e compartilhar seus conhecimentos."},sec={{t="Boas-vindas a um Druida",b="Seu mestre acredita que os druidas do Círculo Cenariano vão acolher você e compartilhar seus conhecimentos. Turak Runa Totem, no Penhasco do Trovão, pode ensinar você a chegar à fortaleza deles, na Clareira da Lua."}},faq={{q="Com quem devo falar?",a="Fale com Turak Runa Totem, no Penhasco do Trovão. Ele pode ensinar você a chegar à Clareira da Lua.",al={"com quem falar","turak runa totem","quem é turak"}},{q="Onde fica a fortaleza do Círculo Cenariano?",a="A fortaleza do Círculo Cenariano fica na Clareira da Lua, em Kalimdor.",al={"onde fica o círculo","localização do círculo cenariano","clareira da lua"}},{q="Por que estão me enviando à Clareira da Lua?",a="Os druidas do Círculo Cenariano podem transmitir seus conhecimentos a você.",al={"por que clareira da lua","aprender druidismo","treinamento de druida"}}},fp="15,186,19.189.0,24.85.0,44.63.0,33.69.0"}
P.entries["quest:94912"] = {n="Child of Nature",s="Sheldras Moontree, em Ventobravo, pode ensinar você a chegar à Clareira da Lua, reduto do Círculo Cenariano. Os druidas da ordem antiga têm sabedoria para compartilhar com um filho da natureza.",h="Sheldras Moontree, em Ventobravo, pode ensinar você a chegar à Clareira da Lua, reduto do Círculo Cenariano.",kw={"círculo cenariano","filho da natureza","druida","kalimdor","clareira da lua","sheldras moontree","skyborne","ventobravo"},ang={["class:Druid"]="Como druida, você é enviado ao Círculo Cenariano, uma ordem antiga cujos membros praticam as artes druídicas.",["race:Skyborne"]="Como Skyborne, você é recebido entre os primeiros de seu povo a chegar a Azeroth."},sec={{t="Um Reduto Distante",b="Você é enviado até Sheldras Moontree, um elfo noturno em Ventobravo. Ele pode ensinar você a chegar à Clareira da Lua, em Kalimdor, onde fica o reduto do Círculo Cenariano. O Círculo é uma ordem antiga de naturalistas e praticantes das artes druídicas, com muito a ensinar a você."}},faq={{q="Quem é Sheldras Moontree?",a="Sheldras Moontree é um elfo noturno em Ventobravo que pode ensinar você a chegar à Clareira da Lua.",al={"sheldras","elfo noturno em ventobravo","quem me ensina a chegar à clareira da lua"}},{q="O que é o Círculo Cenariano?",a="O Círculo Cenariano é uma ordem antiga de naturalistas e praticantes das artes druídicas.",al={"círculo cenariano","ordem druídica","círculo da natureza"}},{q="Onde fica o reduto do Círculo Cenariano?",a="O reduto do Círculo Cenariano fica na Clareira da Lua, em Kalimdor.",al={"reduto cenariano","onde fica a clareira da lua","clareira da lua"}},{q="O que posso aprender com o Círculo Cenariano?",a="Os druidas do Círculo Cenariano têm muita sabedoria para transmitir a você.",al={"ensinamentos cenarianos","o que podem ensinar","sabedoria druídica"}}},fp="15,149,16.215.0,25.86.0,28.93.0,42.66.0,42.66.0"}
P.entries["quest:94914"] = {n="Clareira da Lua",s="Um instrutor druida oferece a você um meio de chegar à Clareira da Lua e encontrar Dendrite Stellardor. Lá, você pode conversar com ele sobre o caminho que começou a trilhar.",h="Um instrutor druida oferece a você um meio de chegar à Clareira da Lua e encontrar Dendrite Stellardor.",kw={"forma de urso","dendrite stellardor","druida","guardião remulos","clareira da lua","refúgio noturno","teleporte"},ang={["class:Druid"]="Como druida, você é recebido por seu instrutor na Clareira da Lua e aprende uma magia para viajar até lá."},sec={{t="Uma Primeira Lição",b="Seu instrutor recebe todos os druidas na Clareira da Lua, onde o Guardião Remulos cuida de quem descansa ali. Você recebe a magia Teleporte: Clareira da Lua, que permite viajar até lá quando busca conhecimento ou consolo. Sua primeira lição é conversar com Dendrite Stellardor no Refúgio Noturno sobre o caminho que você está trilhando."},{t="A Forma de Urso",b="Dendrite percebe que você já dominou a forma de urso. Ele considera que você está no caminho certo."}},faq={{q="Com quem devo conversar na Clareira da Lua?",a="Converse com Dendrite Stellardor no vilarejo do Refúgio Noturno sobre o caminho que você está trilhando.",al={"com quem conversar","dendrite stellardor","druida do refúgio noturno"}},{q="Como chego à Clareira da Lua?",a="Seu instrutor ensina a magia Teleporte: Clareira da Lua, que transporta você até lá.",al={"teleporte para clareira da lua","como chegar à clareira da lua","magia de teleporte"}},{q="Quem cuida dos druidas na Clareira da Lua?",a="O Guardião Remulos é o protetor da Clareira da Lua e cuida dos druidas que descansam ali.",al={"guardião remulos","protetor da clareira da lua","quem protege a clareira da lua"}},{q="O que Dendrite diz sobre meu progresso?",a="Dendrite percebe que você já dominou a forma de urso.",al={"forma de urso","dominei a forma de urso","resposta de dendrite"}}},fp="9,132,14.290.0,13.112.1,35.70.0,26.75.0,37.57.0,41.72.0"}
P.entries["quest:94923"] = {n="Hats Off",s="Robbie pede que você encontre o chapéu de aniversário que perdeu perto do rio, junto aos murlocs. Ele teme que a família descubra que esteve lá.",h="Robbie pede que você encontre o chapéu de aniversário que perdeu perto do rio, junto aos murlocs.",kw={"chapéu de aniversário","ellie","chapéu","chapéu perdido","murlocs","rio","robbie"},sec={{t="Um Chapéu Perdido",b="Robbie perdeu o chapéu que a irmã lhe deu de aniversário enquanto brincava perto do rio. Ele não pode se aproximar dos murlocs, então não pode pedir ajuda ao pai nem a Ellie. Ele suspeita que um dos murlocs encontrou o chapéu. Pedem que você procure por ele em algum lugar ao longo do rio."}},faq={{q="Quem é Robbie?",a="Robbie é um garoto que perdeu o chapéu de aniversário que a irmã lhe deu enquanto brincava perto do rio.",al={"robbie","quem é robbie"}},{q="O que Robbie perdeu?",a="Robbie perdeu um chapéu que a irmã lhe deu de aniversário.",al={"chapéu de robbie","chapéu perdido"}},{q="Onde Robbie perdeu o chapéu?",a="Robbie perdeu o chapéu enquanto brincava no rio e pede que você procure por ele em algum lugar ao longo do rio, perto dos murlocs.",al={"local do chapéu","onde está o chapéu"}},{q="Por que Robbie não pode pedir ajuda à família?",a="Robbie não pode se aproximar dos murlocs, e pedir ajuda ao pai ou a Ellie revelaria onde ele esteve.",al={"por que não pedir ao pai","por que esconder isso"}},{q="Robbie sabe se algum murloc pegou o chapéu?",a="Robbie imagina que um dos murlocs encontrou e ficou com o chapéu.",al={"chapéu de murloc","os murlocs pegaram o chapéu"}}},fp="8,125,10.268.0,14.89.0,21.55.0,30.111.0,41.111.0,42.62.0"}
P.entries["quest:94925"] = {n="A Fur Trade",s="O Vigia Terral procura peles de leão para o comércio de Farholde com um negociante no Porto Detonapavio. Em troca, o assentamento recebe munições especiais.",h="O Vigia Terral procura peles de leão para o comércio de Farholde com um negociante no Porto Detonapavio.",kw={"um comércio de peles","negociante","farholde","pele de leão","porto detonapavio","prized lion hides","munições especiais","vigia terral"},sec={{t="O comércio de Farholde",b="Farholde depende do comércio para obter alguns produtos, embora valorize sua independência. O Vigia Terral diz que o assentamento organizou uma troca com um negociante no Porto Detonapavio. Farholde fornece produtos perigosos de obter, e o negociante oferece munições especiais. Agora, o negociante quer pele de leão, e Terral pede que você traga oito Prized Lion Hides do bando que vive no alto de uma grande colina no centro das planícies."}},faq={{q="Do que o Vigia Terral precisa?",a="O Vigia Terral precisa de oito Prized Lion Hides para o comércio de Farholde com um negociante no Porto Detonapavio.",al={"o que terral quer","peles para terral","pele de leão"}},{q="Com quem Farholde está negociando?",a="Farholde organizou uma troca com um negociante no Porto Detonapavio.",al={"quem é o negociante","comércio no porto detonapavio","negociante de peles"}},{q="O que Farholde recebe na troca?",a="O negociante fornece munições especiais a Farholde.",al={"para que servem as munições","munições especiais","o que o negociante fornece"}},{q="Onde estão os leões?",a="Um bando de leões vive no alto de uma grande colina no centro das planícies.",al={"colina dos leões","onde está o bando","leões nas planícies"}}},fp="11,144,18.415.0,30.101.0,29.67.0,36.54.0,20.69.0"}
P.entries["quest:94930"] = {n="Lost Shipping Crate",s="O caixote de carga de Friz Frazzlespark está marcado para voltar ao Porto Detonapavio, nas Sendas do Rio. A etiqueta avisa para não abri-lo sem supervisão.",h="O caixote de carga de Friz Frazzlespark está marcado para voltar ao Porto Detonapavio, nas Sendas do Rio.",kw={"etiqueta do caixote","friz frazzlespark","caixote de carga perdido","porto detonapavio","círculo vermelho no mapa","sendas do rio"},sec={{t="Um Caixote Marcado",b="Uma etiqueta escrita à mão identifica o caixote como propriedade de Friz Frazzlespark, no Porto Detonapavio. Ela avisa você para não mexer nem abrir o caixote sem supervisão. Se encontrá-lo perdido, a etiqueta indica Friz, no Porto Detonapavio, nas Sendas do Rio, como destino."}},faq={{q="Quem é o dono do caixote?",a="A etiqueta identifica Friz Frazzlespark como dono.",al={"dono do caixote","quem é friz","caixote de friz"}},{q="Para onde o caixote deve ir?",a="A etiqueta diz para devolver o caixote a Friz Frazzlespark, no Porto Detonapavio, nas Sendas do Rio.",al={"local do caixote","para onde devolver o caixote","caixote no porto detonapavio"}},{q="Posso abrir o caixote?",a="A etiqueta avisa para não abrir o caixote sem supervisão.",al={"abrir caixote","o que tem dentro","aviso do caixote"}},{q="O que o mapa no caixote mostra?",a="O mapa mostra um grande círculo vermelho numa costa a sudeste, ao norte de um templo cercado por água e de algumas criaturas aladas.",al={"mapa do caixote","círculo vermelho no mapa","o que diz a etiqueta"}}},fp="19,152,14.260.0,19.52.0,26.94.0,21.62.0,36.124.0"}
P.entries["quest:94931"] = {n="Stolen Saws",s="No moinho de madeira, Halligan Turner pede que você recupere lâminas de serra roubadas por gnolls. O moinho precisa delas de volta.",h="No moinho de madeira, Halligan Turner pede que você recupere lâminas de serra roubadas por gnolls.",kw={"colinas cerdosas","gnolls","halligan turner","serraria","lâminas de serra","southern watch","serras roubadas"},sec={{t="Lâminas desaparecidas",b="A Southern Watch mantém a maioria dos gnolls afastados, mas alguns ainda conseguem entrar no acampamento à noite e roubar lâminas de serra. Halligan Turner, no moinho de madeira, pede que você procure por elas nos acampamentos dos gnolls nas Colinas Cerdosas, onde as lâminas podem estar guardadas. O moinho de madeira precisa receber de volta o metal afiado."}},faq={{q="Quem quer as lâminas de serra de volta?",a="Halligan Turner, da serraria, quer que as lâminas de serra roubadas sejam devolvidas.",al={"quem pediu as lâminas de serra","serras de halligan turner"}},{q="De onde as lâminas de serra foram roubadas?",a="Alguns gnolls conseguem passar pela Southern Watch e se esgueiram para o acampamento madeireiro à noite para levá-las.",al={"onde os gnolls roubaram serras","onde estão as serras roubadas"}},{q="Onde os gnolls podem guardar as lâminas?",a="Os acampamentos dos gnolls nas Colinas Cerdosas são onde as lâminas podem estar escondidas.",al={"acampamentos dos gnolls com lâminas de serra","onde estão as serras"}},{q="Por que as lâminas de serra são úteis para os gnolls?",a="É provável que os gnolls usem o metal afiado para fabricar armas.",al={"o que os gnolls fazem com serras","gnolls fabricando armas"}},{q="Por que a serraria precisa das lâminas?",a="Halligan diz que a devolução das lâminas pouparia tempo e recursos à serraria.",al={"por que recuperar lâminas de serra","serraria precisa de serras"}}},fp="11,110,14.280.0,30.72.0,38.90.0,39.69.0,44.54.0,41.81.0"}
P.entries["quest:94946"] = {n="The Magical City of Dalaran",s="Um Mago em Valanaar envia você da Ilha de Zefras à Cidade de Dalaran, onde Magos aguardam a chegada do seu povo. A cidade é um ponto de partida para explorar Azeroth, mas as terras além dela são perigosas sem preparo e experiência.",h="Um Mago em Valanaar envia você da Ilha de Zefras à Cidade de Dalaran, onde Magos aguardam a chegada do seu...",kw={"culto","dalaran","cidade de dalaran","danaaris stargale","magos","cortacéu","valanaar","ilha de zefras"},ang={["race:Skyborne"]="Como Nascido dos Céus, você está viajando da Ilha de Zefras para se juntar aos Magos que aguardam a chegada do seu povo em Dalaran."},sec={{t="Chegada a Dalaran",b="Acontecimentos recentes envolvendo o culto mantiveram quem fala em Valanaar, enquanto vários Magos aguardam seu povo em Dalaran. Você é enviado ao cais, do lado de fora da hospedaria, para embarcar em um navio cortacéu rumo à Cidade de Dalaran. Ao chegar, fale com Danaaris Stargale. Seu povo ainda está se estabelecendo na cidade, e o território além de sua proteção pode ser perigoso."}},faq={{q="Quem está esperando em Dalaran?",a="Vários Magos aguardam a chegada do seu povo em Dalaran. Ao chegar, você deve falar com Danaaris Stargale.",al={"magos em dalaran","quem está em dalaran","magos de dalaran"}},{q="De onde devo partir?",a="Você viaja da Ilha de Zefras à Cidade de Dalaran a bordo do navio cortacéu que está no cais, do lado de fora da hospedaria.",al={"como chegar a dalaran","partindo de zefras","cortacéu"}},{q="Por que quem fala vai ficar em Valanaar?",a="Acontecimentos recentes envolvendo o culto mudaram os planos de quem fala, que pretende ficar em Valanaar por algum tempo.",al={"por que ficar em valanaar","culto mudou os planos","mago de valanaar"}},{q="É seguro sair de Dalaran?",a="As terras além de Dalaran podem ser perigosas sem o preparo e a experiência adequados.",al={"é seguro sair de dalaran","perigo perto de dalaran","arredores de dalaran"}}},fp="27,238,18.368.0,26.125.0,23.96.0,39.105.0,27.83.0"}
P.entries["quest:94947"] = {n="Welcome to Azeroth",s="'Welcome to Azeroth' marca a chegada de viajantes Skyborne à capital humana de Ventobravo através do Skyborne Portal. Apresentando-se na Bastilha Ventobravo, os recém-chegados recebem reconhecimento formal e permissão do Grão-lorde Bolvar Fordragon para viajar livremente por todas as terras da Aliança.",h="'Welcome to Azeroth' marca a chegada de viajantes Skyborne à capital humana de Ventobravo através do Skyborne...",kw={"bolvar fordragon","alto-elfo","alta ordem","kirin tor","portal","skyborne","bastilha ventobravo","welcome to azeroth"},ang={["faction:Alliance"]="O Grão-lorde Bolvar Fordragon recebe oficialmente a Alta Ordem em nome do Rei Anduin Wrynn, concedendo-lhes permissão para percorrer livremente as terras da Aliança.",["race:Skyborne"]="Para os Skyborne, esta audiência abre formalmente os portões de Ventobravo e do território da Aliança aos viajantes altos-elfos que chegam pelo portal."},sec={{t="Chegada à Capital",b="Chegando através do místico Skyborne Portal, os viajantes entram diretamente na movimentada capital de Ventobravo. Encarregados de se apresentar à sede da liderança humana, os recém-chegados sobem pelas grandes vias da cidade até a Bastilha Ventobravo para comparecer perante a regência."},{t="Uma Audiência com o Regente",b="De pé no grande salão do trono, o Grão-lorde Bolvar Fordragon cumprimenta os membros da Alta Ordem que chegam após aviso prévio de um mensageiro do Kirin Tor. Notando que já faz bastante tempo desde que altos-elfos caminharam pelos salões da Bastilha Ventobravo, o Regente graciosamente os aceita como convidados e lhes concede livre passagem por todos os territórios da Aliança em nome do Rei."}},faq={{q="Sobre o que é esta missão?",a="'Welcome to Azeroth' é uma missão introdutória na qual um viajante atravessa o Skyborne Portal até Ventobravo e se apresenta perante o Grão-lorde Bolvar Fordragon na Bastilha Ventobravo.",al={"o que é welcome to azeroth","missão welcome to azeroth"}},{q="Quem é Bolvar Fordragon?",a="O Grão-lorde Bolvar Fordragon atua como regente do trono de Ventobravo, governando o reino na Bastilha Ventobravo em nome do jovem Rei Anduin Wrynn enquanto o Rei Varian permanece desaparecido.",al={"quem é bolvar fordragon","regente de ventobravo"}},{q="Por que Bolvar está recebendo os Skyborne?",a="Um mensageiro do Kirin Tor alertou Bolvar Fordragon de que membros da Alta Ordem estariam chegando. Bolvar os acolhe como convidados da coroa, concedendo-lhes permissão para explorar e viajar livremente pelas terras da Aliança.",al={"por que os skyborne estão em ventobravo","altos-elfos ventobravo"}},{q="O que é a Alta Ordem?",a="A Alta Ordem representa a facção ou grupo associado aos altos-elfos Skyborne cuja chegada foi anunciada à liderança de Ventobravo pelo Kirin Tor.",al={"quem é a alta ordem","história da alta ordem"}},{q="Para onde o Skyborne Portal leva?",a="O Skyborne Portal leva os viajantes diretamente à cidade capital humana de Ventobravo, permitindo que os recém-chegados sigam direto para a Bastilha Ventobravo em busca de uma audiência com a coroa.",al={"destino do skyborne portal","para onde o portal leva"}},{q="Os Skyborne têm permissão para circular por todo o território da Aliança?",a="Bolvar Fordragon dá as boas-vindas formais aos Skyborne como convidados em nome do Rei e lhes concede explicitamente permissão para viajar sem impedimentos por todas as terras da Aliança.",al={"os skyborne são da aliança","boas-vindas aos skyborne aliança"}}},fp="18,159,22.196.0,27.336.0,25.120.0,24.159.0,37.190.0,23.130.0,36.163.0,55.129.0"}
P.entries["quest:94961"] = {n="Biting the Hand",s="Fuzzle oferece um acordo a quem o ajudar a se vingar. Ele promete mostrar um tesouro quando você lhe trouxer Twilight Finger Bones.",h="Fuzzle oferece um acordo a quem o ajudar a se vingar.",kw={"morder a mão","fuzzle","gnoll","vingança","tesouro","twilight finger bones"},sec={{t="A oferta de Fuzzle",b="Um pouco de ouro muda de mãos enquanto Fuzzle lhe oferece um acordo. O gnoll promete mais tesouros se você o ajudar a se vingar. Ele pede que você lhe traga vinte Twilight Finger Bones antes de mostrar o que tem."}},faq={{q="Quem é Fuzzle?",a="Fuzzle é um gnoll que oferece ouro e promete tesouros em troca de ajuda para se vingar.",al={"fuzzle","gnoll com ouro"}},{q="O que Fuzzle quer?",a="Fuzzle pede que você lhe traga vinte Twilight Finger Bones para ajudá-lo a se vingar.",al={"o que ele quer","vingança de fuzzle"}},{q="Para que servem os Twilight Finger Bones?",a="Fuzzle quer vinte Twilight Finger Bones antes de mostrar o tesouro.",al={"ossos de dedos","ossos crepusculares"}}},fp="15,131,14.208.0,14.97.0,22.82.0,39.75.0"}
P.entries["quest:94962"] = {n="Bloodmaster's Ring",s="Uma luta contra Bonegnaw é o próximo combate rumo ao título de campeão no Bloodmaster's Ring. Os ogros esperam para ver se você lhes dará uma batalha que valha a pena assistir.",h="Uma luta contra Bonegnaw é o próximo combate rumo ao título de campeão no Bloodmaster's Ring.",kw={"bloodmaster","bloodmaster's ring","bonegnaw","combate","campeão","luta","ogros"},sec={{t="O Próximo Combate",b="Suas vitórias ainda não fizeram de você um campeão, e o goblin do ringue já tem outra batalha em mente. Bonegnaw será seu oponente, e o goblin promete uma surpresa. Os ogros estão assistindo, e a próxima luta deve diverti-los."},{t="Depois da Luta",b="O goblin está insatisfeito com a forma como a luta o retrata. Os ogros, porém, parecem entretidos, e ele alerta você para não se orgulhar do resultado."}},faq={{q="Quem é meu oponente?",a="Bonegnaw é seu oponente no Bloodmaster's Ring.",al={"luta com bonegnaw","com quem eu luto"}},{q="Já sou campeão?",a="O goblin do ringue diz que suas vitórias ainda não fizeram de você um campeão.",al={"campeão bloodmaster","tornar-se campeão"}},{q="Quem está assistindo à luta?",a="Ogro está assistindo ao combate no Bloodmaster's Ring.",al={"ogros assistindo","quem está entretido"}}},fp="18,170,13.226.0,15.151.1,19.52.0,20.66.0,26.54.0"}
P.entries["quest:94963"] = {n="Biting the Hand",s="Fuzzle pede que você fuja com ele e promete uma recompensa quando estiverem a salvo. Ele rosna, ameaçando qualquer um que tente persegui-los.",h="Fuzzle pede que você fuja com ele e promete uma recompensa quando estiverem a salvo.",kw={"mordendo a mão","fuzzle","gnoll","ouro","partir","recompensa","a salvo"},sec={{t="Fugindo com Fuzzle",b="Fuzzle está pronto para partir e pede que você vá com ele. Ele avisa que vai despedaçar qualquer um que tente impedi-los. Sua segurança vem primeiro; ele promete uma recompensa quando vocês estiverem a salvo."}},faq={{q="Quem está me pedindo para partir?",a="Fuzzle pede que você fuja com ele.",al={"quem é fuzzle","fuzzle?","quem quer partir"}},{q="O que Fuzzle ameaça fazer?",a="Fuzzle ameaça despedaçar qualquer um que tente impedi-los.",al={"o que fuzzle diz","ameaça de fuzzle","quem ele vai atacar"}},{q="Quando Fuzzle vai me dar uma recompensa?",a="Fuzzle diz que vai dar uma recompensa a você quando estiver a salvo.",al={"recompensa de fuzzle","quando vem a recompensa","o que ele promete"}},{q="Qual é a recompensa?",a="Fuzzle juntou uma boa quantia em ouro, que agora será sua.",al={"o que vou receber","ouro de fuzzle","recompensa de fuzzle"}}},fp="15,125,19.190.0,26.34.0,26.60.0,34.56.0,19.60.0"}
P.entries["quest:94964"] = {n="Bloodmaster's Ring",s="Um locutor de ringue chama você para enfrentar Mog’thar no Bloodmaster’s Ring. A plateia espera o próximo desafiante.",h="Um locutor de ringue chama você para enfrentar Mog’thar no Bloodmaster’s Ring.",kw={"locutor","bloodmaster’s ring","desafiante","plateia","mog’thar","ringue"},sec={{t="O próximo desafiante",b="O locutor manteve a plateia animada e agora apresenta Mog’thar como o próximo desafiante. Você é chamado ao Bloodmaster’s Ring, enquanto a plateia espera para ver o que acontece."}},faq={{q="Quem vou enfrentar no Bloodmaster’s Ring?",a="Você é chamado para enfrentar Mog’thar no Bloodmaster’s Ring.",al={"luta contra mog’thar","quem é o próximo desafiante","oponente no bloodmaster’s ring"}},{q="O que o locutor diz sobre Mog’thar?",a="O locutor diz que Mog’thar não é brincadeira.",al={"quem é mog’thar","próximo desafiante","mog’thar é brincadeira"}},{q="Por que estão me mandando para o ringue?",a="O locutor quer manter a empolgação da plateia apresentando outro desafiante.",al={"por que lutar contra mog’thar","motivo da luta no ringue","o que o locutor quer"}}},fp="18,123,18.181.0,42.62.0,45.41.0,34.91.0"}
P.entries["quest:94965"] = {n="Bloodmaster's Ring",s="Um ogro pede que você prove seu valor diante de seu povo enfrentando Snufflesnout no Bloodmaster's Ring. O petisco favorito dela a atrairá para a luta, embora Chub'chob talvez não goste do resultado.",h="Um ogro pede que você prove seu valor diante de seu povo enfrentando Snufflesnout no Bloodmaster's Ring.",kw={"ringue do bloodmaster","chub'chob","ogros","snufflesnout","petisco"},sec={{t="Um teste para você",b="O ogro deixa um petisco antes de você entrar no Bloodmaster's Ring. Snufflesnout gosta muito dele, e só de vê-lo já fica agitada. Seu desafio é enfrentar a companheira de Chub'chob e provar seu valor aos ogros."},{t="Depois da luta",b="A companheira de Chub'chob é Snufflesnout, e derrotá-la deixa uma situação complicada entre você e os ogros. Tenha cuidado com eles agora."}},faq={{q="Quem é Snufflesnout?",a="Snufflesnout é a companheira de Chub'chob e gosta muito de um petisco específico.",al={"snufflesnout","focinho farejador","animal de estimação de chubchob"}},{q="Para que serve o petisco?",a="O ogro usa o petisco favorito de Snufflesnout para atraí-la ao Bloodmaster's Ring.",al={"petisco de snufflesnout","para que serve o petisco","alimentar snufflesnout"}},{q="O que é o Bloodmaster's Ring?",a="É o ringue onde você enfrenta Snufflesnout para provar seu valor aos ogros.",al={"ringue do bloodmaster","o ringue","onde lutar contra snufflesnout"}},{q="Por que estou lutando contra Snufflesnout?",a="Os ogros consideram importante que você prove seu valor a eles, e enfrentar Snufflesnout é seu desafio.",al={"luta contra snufflesnout","por que lutar contra ela","provar meu valor aos ogros"}}},fp="18,199,14.207.0,15.124.1,20.72.0,21.84.0,31.74.0,31.93.0"}
P.entries["quest:94968"] = {n="Eye of Mugg",s="Krom'rosh envia você à Fortaleza de Krol'Dok, onde a presença do culto do Crepúsculo é maior do que o esperado. Ele pede uma prova da morte do líder.",h="Krom'rosh envia você à Fortaleza de Krol'Dok, onde a presença do culto do Crepúsculo é maior do que o...",kw={"caverna","líder do culto","eye of mugg","fortaleza de krol'dok","krom'rosh","sacrifícios","culto do crepúsculo"},sec={{t="Fortaleza de Krol'Dok",b="Krom'rosh teme que mais aliados sejam sacrificados se o culto do Crepúsculo continuar devastando estas terras. Poucos sobreviveram à entrada na caverna, e a presença do culto é maior do que ele imaginava. Agora, você deve entrar na Fortaleza de Krol'Dok e voltar com uma prova da morte do líder."}},faq={{q="Quem está me pedindo para entrar na Fortaleza de Krol'Dok?",a="Krom'rosh envia você à Fortaleza de Krol'Dok para trazer uma prova de que o líder do culto do Crepúsculo está morto.",al={"quem me enviou","pedido de krom'rosh"}},{q="O que está acontecendo na fortaleza?",a="O culto do Crepúsculo tem uma presença maior do que Krom'rosh esperava e vem devastando as terras e sacrificando aliados.",al={"o que está acontecendo lá","problema com o culto do crepúsculo"}},{q="Por que Krom'rosh quer que eu entre?",a="Krom'rosh quer deter o culto antes que ele continue devastando as terras e sacrificando aliados.",al={"por que entrar","por que entrar na fortaleza"}},{q="Que prova Krom'rosh está pedindo?",a="Ele pede uma prova de que o líder do culto do Crepúsculo está morto.",al={"prova necessária","o que devo trazer de volta"}},{q="Muitos dos que entraram na caverna sobreviveram?",a="Poucos dos que conseguiram entrar na caverna sobreviveram.",al={"sobreviventes da caverna","quem conseguiu sair"}}},fp="11,150,19.268.0,46.105.0,32.119.0,36.98.0,34.58.0,38.43.0"}
P.entries["quest:94973"] = {n="Krol'dok Moulding",s="Um molde encontrado perto de Rog'mar parece fazer parte de uma chave. Alguém no assentamento talvez saiba o que ele abre.",h="Um molde encontrado perto de Rog'mar parece fazer parte de uma chave.",kw={"chave","krol'dok moulding","molde","rog'mar","fortaleza"},sec={{t="Um molde curioso",b="Você tem um molde que parece feito para uma chave. Em Rog'mar, alguém talvez saiba para que serve essa peça. Se veio da fortaleza, pode ser importante."}},faq={{q="Para que serve o molde?",a="O molde parece ser para uma chave.",al={"peça de molde","o que é este molde","molde de chave"}},{q="Quem pode identificar o molde?",a="Alguém em Rog'mar talvez saiba algo sobre o molde.",al={"quem sabe sobre o molde","perguntar sobre o molde","onde levar o molde"}},{q="Por que isso pode ser importante?",a="Se o molde veio da fortaleza, deve ser importante.",al={"o molde é importante","molde da fortaleza","por que se importar com o molde"}}},fp="17,108,15.151.0,25.37.0,30.44.0,20.61.0"}
P.entries["quest:94974"] = {n="Key Ingredients",s="Kreza Darkthorn precisa de couro e ferro para moldar uma chave. Você reúne os materiais enquanto ela mantém as brasas quentes.",h="Kreza Darkthorn precisa de couro e ferro para moldar uma chave.",kw={"brasas","iron bar","chave","ingredientes da chave","kreza darkthorn","moldagem","thick leather"},sec={{t="Materiais para a moldagem",b="Kreza Darkthorn tem uma moldagem gasta que pode ser usada para fazer uma chave. Você leva a ela quatro Thick Leather e doze Iron Bar enquanto ela mantém as brasas quentes. A moldagem deve aguentar, e Kreza está pronta para ver o que pode ser feito."}},faq={{q="Do que Kreza precisa?",a="Kreza pede que você traga quatro Thick Leather e doze Iron Bar.",al={"quais materiais","ingredientes da chave","do que kreza precisa"}},{q="Para que servem os materiais?",a="Os materiais servem para fazer uma chave usando uma moldagem rudimentar e gasta.",al={"por que couro e ferro","chave para quê","materiais para a moldagem"}},{q="Quem está mantendo as brasas quentes?",a="Kreza Darkthorn diz que manterá as brasas quentes enquanto você reúne os materiais.",al={"quem cuida das brasas","brasas de kreza","brasas quentes"}},{q="O que Kreza diz sobre a moldagem?",a="Kreza diz que a moldagem é rudimentar e gasta, mas ainda pode ser usada para fazer uma chave.",al={"estado da moldagem","a moldagem ainda serve","molde de chave"}}},fp="15,115,26.225.0,21.63.0,27.67.0,30.81.0,39.82.0"}
P.entries["quest:94975"] = {n="A Token of Vengeance",s="Um aliado pede que você encontre o Twilight’s Hammer, escondido em uma rede de cavernas perto da Fortaleza de Krol'Dok. Seus ataques feriram seus aliados e ameaçam a região.",h="Um aliado pede que você encontre o Twilight’s Hammer, escondido em uma rede de cavernas perto da Fortaleza de...",kw={"um símbolo de vingança","orelhas de cultista","cultistas","caverna escondida","fortaleza de krol'dok","twilight's hammer"},sec={{t="As cavernas ocultas",b="Os batedores relataram que cultistas do Twilight’s Hammer estão se movendo sob o terreno acidentado perto da Fortaleza de Krol'Dok. Seu aliado diz que os ataques deles causaram grande sofrimento aos seus aliados e que os cultistas estão reivindicando a região. Você deve encontrar o esconderijo deles e trazer de volta quinze orelhas de cultista como mensagem de vingança."}},faq={{q="Quem estou procurando?",a="Você está procurando cultistas do Twilight’s Hammer escondidos em uma rede de cavernas perto da Fortaleza de Krol'Dok.",al={"quem são os cultistas","twilight hammer aqui","orelhas de cultista"}},{q="Por que os cultistas estão sendo caçados?",a="Quem oferece a missão diz que os cultistas causaram sofrimento aos seus aliados e estão reivindicando a região.",al={"por que vingança","por que lutar contra eles","o que eles fizeram"}},{q="O que os batedores sabem?",a="Os batedores relataram movimentação de cultistas sob o terreno acidentado, em uma rede de cavernas escondida ao norte.",al={"relato dos batedores","onde estão os cultistas","movimentação dos cultistas"}},{q="O que devo trazer de volta?",a="Você deve coletar quinze Cultist Ears dos membros do Twilight’s Hammer na Fortaleza de Krol'Dok.",al={"o que devo coletar","missão das orelhas","quantas orelhas"}}},fp="20,158,16.328.0,21.99.0,34.90.0,24.99.0,30.98.0"}
P.entries["quest:94978"] = {n="Taming the Beast",s="Quel'ana Quickgale ensina a você o vínculo entre fera e mestre. Seu primeiro desafio é adestrar um Windsong Crawler perto das águas de Zephras.",h="Quel'ana Quickgale ensina a você o vínculo entre fera e mestre.",kw={"adestramento de feras","quel'ana quickgale","bastão de adestramento","taming the beast","valanaar","windsong crawler","zephras"},sec={{t="Primeiro vínculo",b="Você começa com o Bastão de Adestramento e um Windsong Crawler. Adestre um perto de um corpo d'água, pratique suas habilidades e depois devolva o bastão a Quel'ana Quickgale em Valanaar. Por enquanto, seu caminho rumo à maestria começa com essa criatura."}},faq={{q="O que Quel'ana me pede para adestrar?",a="Quel'ana pede a você que adestre um Windsong Crawler perto de um corpo d'água em Zephras.",al={"qual fera","alvo do adestramento","missão do crawler"}},{q="Para que serve o Bastão de Adestramento?",a="O Bastão de Adestramento é usado para adestrar um Windsong Crawler.",al={"como funciona o bastão","ferramenta de adestramento","missão do bastão"}},{q="Onde encontro um Windsong Crawler?",a="Windsong Crawlers são encontrados perto de corpos d'água em Zephras.",al={"localização do crawler","onde encontrar crawler","fera de zephras"}},{q="Quem me deu o Bastão de Adestramento?",a="Quel'ana Quickgale, em Valanaar, dá a você o Bastão de Adestramento.",al={"doador da missão","quem é quelana","quelana quickgale"}},{q="Por que estou aprendendo a adestrar uma fera?",a="Aprender o vínculo entre fera e mestre é o primeiro passo rumo à maestria da sua classe.",al={"por que adestrar crawler","maestria das feras","primeiro adestramento"}}},fp="16,132,10.215.0,34.77.0,27.50.0,35.55.0,27.56.0,34.90.0"}
P.entries["quest:94979"] = {n="Taming the Beast",s="Quel'ana Quickgale pede que você adestre um galestrider nos Baixios dos Lufopomos. Sua habilidade em terreno aberto vai prepará-lo para as provações que virão.",h="Quel'ana Quickgale pede que você adestre um galestrider nos Baixios dos Lufopomos.",kw={"galestrider","baixios dos lufopomos","ornery galestrider","quel'ana quickgale","bastão de adestramento","taming the beast","valanaar","zephras"},sec={{t="Pelas planícies",b="Você já mostrou que consegue adestrar o rastejante do rio. Quel'ana Quickgale agora lhe entrega um Bastão de Adestramento e pede que procure um galestrider nos baixios de Zephras. A orgulhosa criatura alada corre veloz pelas planícies. Conquiste sua confiança, pratique sua habilidade e devolva o bastão a Quel'ana em Valanaar."}},faq={{q="O que Quel'ana quer que eu adestre?",a="Quel'ana pede que você adestre um Ornery Galestrider nos Baixios dos Lufopomos.",al={"adestrar o quê","adestrar galestrider","que fera"}},{q="Onde encontro o galestrider?",a="O Ornery Galestrider fica nos Baixios dos Lufopomos, nas planícies de Zephras.",al={"onde fica o galestrider","localização do galestrider","onde ficam os baixios"}},{q="Para que serve o Bastão de Adestramento?",a="Quel'ana lhe entrega o Bastão de Adestramento para adestrar um Ornery Galestrider.",al={"uso do bastão de adestramento","para que serve o bastão","como adestrar uma fera"}},{q="Quem me deu esta missão?",a="Quel'ana Quickgale, de Valanaar, pede que você adestre um Ornery Galestrider e devolva o Bastão de Adestramento.",al={"quem me enviou","quem é quel'ana","quickgale"}}},fp="16,138,17.298.0,35.74.0,32.88.0,27.72.0,28.100.0"}
P.entries["quest:94980"] = {n="Krol'dok Moulding",s="O Krol'dok moulding parece ser de uma chave. Alguém na Bastilha de Ermoforte pode saber mais sobre ele.",h="O Krol'dok moulding parece ser de uma chave.",kw={"bastilha de ermoforte","chave","molde de krol'dok","molde"},sec={{t="Molde de chave",b="Você tem um molde que parece ser de uma chave. Alguém na Bastilha de Ermoforte talvez saiba para que serve, e você o leva até lá para descobrir mais."}},faq={{q="O que é o Krol'dok moulding?",a="O Krol'dok moulding parece ser de uma chave.",al={"molde de kroldok","molde de krol'dok","o que é este molde"}},{q="Quem pode saber sobre o molde?",a="Alguém na Bastilha de Ermoforte talvez saiba sobre o molde.",al={"quem sabe sobre o molde","especialista em moldes","perguntar sobre o molde"}},{q="O que acontece quando levo o molde?",a="A pessoa a quem você o leva diz que vai ver o que pode ser feito com ele.",al={"resultado do molde","o que dizem","molde de chave"}}},fp="17,107,13.146.0,30.46.0,31.50.0,39.71.0"}
P.entries["quest:94981"] = {n="Key Ingredients",s="Alphonse Dumas precisa de materiais para fazer uma chave a partir de um molde rudimentar. Você deve levar Thick Leather e Iron Bars para ele.",h="Alphonse Dumas precisa de materiais para fazer uma chave a partir de um molde rudimentar.",kw={"alphonse dumas","brasas","barras de ferro","chave","ingredientes da chave","molde","couro grosso"},sec={{t="Materiais para a Chave",b="Alphonse Dumas mantém as brasas quentes enquanto você reúne o que ele precisa. O molde é rudimentar, mas os materiais certos podem ajudá-lo a fazer uma chave."}},faq={{q="Do que Alphonse precisa?",a="Alphonse Dumas pede que você leve quatro Thick Leather e doze Iron Bars.",al={"materiais necessários","o que levar","ingredientes da chave"}},{q="O que Alphonse está fazendo?",a="Alphonse espera fazer uma chave a partir de um molde rudimentar usando os materiais certos.",al={"o que ele está fabricando","para que serve a chave","molde da chave"}},{q="Onde levo os materiais?",a="Leve Thick Leather e Iron Bars para Alphonse Dumas.",al={"quem recebe os ingredientes","para quem levar os materiais"}}},fp="15,126,21.141.0,24.73.0,24.80.0,30.56.0"}
P.entries["quest:94982"] = {n="Eye of Mugg",s="Commander Brant pede que você encontre a presença do Twilight na Fortaleza de Krol'Dok e traga provas da morte de seu líder. As cavernas representam uma ameaça aos esforços para expulsar o Twilight destas terras.",h="Commander Brant pede que você encontre a presença do Twilight na Fortaleza de Krol'Dok e traga provas da...",kw={"cavernas","commander brant","eye of mugg","fortaleza de krol'dok","batedores desaparecidos","montanhas","twilight"},sec={{t="As cavernas escondidas",b="Commander Brant soube que batedores encontraram cavernas a noroeste, ao longo das montanhas, escondidas pela paisagem natural. Muitos que entraram para descobrir mais não voltaram, e Brant teme que estejam perdidos. Observadores também viram figuras do Twilight entrando e saindo das cavernas durante a noite. Você deve localizar a fortaleza e voltar com provas da morte de seu líder."}},faq={{q="Quem me envia à Fortaleza de Krol'Dok?",a="Commander Brant pede que você localize a fortaleza do Twilight e volte com provas da morte de seu líder.",al={"quem é commander brant","brant me enviou","quem me deu esta missão"}},{q="Onde fica a Fortaleza de Krol'Dok?",a="As cavernas ficam a noroeste, ao longo das montanhas, escondidas pela paisagem natural.",al={"onde fica krol'dok","localização de krol'dok","onde ficam as cavernas"}},{q="Por que Commander Brant está preocupado com as cavernas?",a="Muitos que entraram nas cavernas em busca de informações não voltaram, e Brant teme que estejam perdidos.",al={"por que encontrar as cavernas","o que está acontecendo lá","batedores desaparecidos"}},{q="Quem foi visto perto das cavernas?",a="Observadores relataram uma presença do Twilight entrando e saindo das cavernas, muitas vezes durante a noite.",al={"twilight nas cavernas","quem está em krol'dok","presença do twilight"}},{q="O que Brant me pede para trazer?",a="Brant pede que você volte com provas de que o líder da fortaleza está morto.",al={"que prova preciso trazer","prova sobre o líder","o que trazer de volta"}}},fp="11,196,16.376.0,36.103.0,29.76.0,49.101.0,33.93.0,37.73.0"}
P.entries["quest:94983"] = {n="Twilight Mementos",s="O sargento Riftan envia você ao norte, à Fortaleza de Krol'Dok, após batedores confirmarem um esconderijo do Martelo do Crepúsculo. Ele pede que você traga provas da derrota dos cultistas.",h="O sargento Riftan envia você ao norte, à Fortaleza de Krol'Dok, após batedores confirmarem um esconderijo do...",kw={"caverna","braceletes dos cultistas","esconderijo dos cultistas","fortaleza de krol'dok","batedores","sargento riftan","lembranças do crepúsculo","martelo do crepúsculo"},sec={{t="Relatos dos Batedores",b="Os batedores trouxeram relatos preocupantes ao sargento Riftan sobre um esconderijo de cultistas. Seus relatos confirmam o que outros disseram. Há uma caverna ao norte, escondida pelos arredores, e Riftan acredita que ela serve de base para o culto nas profundezas das montanhas. Ele envia você à Fortaleza de Krol'Dok para trazer provas de que os cultistas do Martelo do Crepúsculo foram derrotados."}},faq={{q="Quem está me enviando ao norte?",a="O sargento Riftan pede que você procure os cultistas do Martelo do Crepúsculo na Fortaleza de Krol'Dok e volte com provas da derrota deles.",al={"quem me enviou","sargento riftan"}},{q="O que os batedores encontraram?",a="Os relatos dos batedores confirmaram as informações sobre um esconderijo de cultistas, com uma caverna escondida ao norte.",al={"relato dos batedores","o que descobriram"}},{q="Onde fica o esconderijo?",a="O esconderijo fica numa caverna ao norte, oculta pelos arredores. Riftan acredita que ela serve de base nas profundezas das montanhas.",al={"caverna dos cultistas","onde estão os cultistas"}},{q="Que provas Riftan quer?",a="Riftan pede que você traga provas de que os cultistas na Fortaleza de Krol'Dok foram derrotados.",al={"quais provas","provas dos cultistas"}},{q="Quem são os cultistas?",a="Eles são membros do Martelo do Crepúsculo, cujo esconderijo foi confirmado pelos relatos dos batedores.",al={"culto do crepúsculo","martelo do crepúsculo"}}},fp="17,161,15.350.0,29.129.0,25.96.0,21.125.0,28.96.0,21.99.0"}
P.entries["quest:94984"] = {n="Tome of Twilight",s="As forças do Crepúsculo persistem, e uma pista aponta para o norte de Solclaro. Pedem que você encontre Nar'gurk e recupere informações da fortaleza dele.",h="As forças do Crepúsculo persistem, e uma pista aponta para o norte de Solclaro.",kw={"fortaleza de krol'dok","nar'gurk","shadow magic","solclaro","tome of twilight","crepúsculo","forças do crepúsculo"},sec={{t="Uma Trilha ao Norte",b="As forças do Crepúsculo ainda vêm de algum lugar desconhecido, então enviam você à Fortaleza de Krol'Dok. Uma criatura do Crepúsculo mencionou Shadow Magic e um ogro chamado Nar'gurk por lá. Pedem que você o mate e recupere qualquer informação valiosa que possa explicar de onde vêm essas forças."}},faq={{q="O que estou procurando?",a="Você está procurando Nar'gurk na Fortaleza de Krol'Dok e qualquer informação valiosa que encontrar por lá.",al={"nar gurk","informações do tomo","fortaleza do crepúsculo"}},{q="Onde fica a Fortaleza de Krol'Dok?",a="A Fortaleza de Krol'Dok fica ao norte de Solclaro.",al={"onde fica a fortaleza","localização da fortaleza de krol'dok"}},{q="Por que estou procurando Nar'gurk?",a="Uma criatura do Crepúsculo mencionou Nar'gurk e Shadow Magic quando perguntaram de onde vinham seus antigos mestres.",al={"por que nar'gurk","pista do crepúsculo"}},{q="Que informações podem estar lá?",a="As informações procuradas podem ajudar a explicar de onde vêm as persistentes forças do Crepúsculo.",al={"quais informações","informações de tome of twilight"}}},fp="16,143,13.279.0,22.87.0,29.43.0,30.109.0,32.93.0"}
P.entries["quest:94992"] = {n="Rescue Roundup",s="Uma égua perdida chamada Biscuit cutuca você, pronta para seguir você de volta a Wheeler's Grange. A volta dela significa que a propriedade voltou a funcionar.",h="Uma égua perdida chamada Biscuit cutuca você, pronta para seguir você de volta a Wheeler's Grange.",kw={"biscuit","demar","égua","égua perdida","resgate em grupo","companheiras de estábulo","wheeler's grange"},sec={{t="Biscuit volta",b="O cavalo perdido de Wheeler se chama Biscuit, e ela abaixa a cabeça antes de cutucar seu braço. Você a leva de volta a Wheeler's Grange. Wheeler agradece por ter Biscuit em casa, embora ela fique sozinha por um tempo. A propriedade voltou a funcionar."}},faq={{q="Quem é Biscuit?",a="Biscuit é a égua de Wheeler, que se perdeu e precisa ser levada de volta a Wheeler's Grange.",al={"égua biscuit","égua perdida","quem é biscuit"}},{q="Para onde Biscuit precisa ir?",a="Biscuit precisa ser levada de volta a Wheeler's Grange.",al={"onde levar a égua","localização de biscuit","destino da égua"}},{q="Por que Wheeler agradece?",a="Wheeler agradece porque você leva Biscuit de volta à fazenda.",al={"por que agradece","biscuit resgatada","agradecimento de wheeler"}},{q="Biscuit está sozinha?",a="Wheeler diz que Biscuit ficará sozinha por um tempo e espera encontrar algumas companheiras de estábulo dela.",al={"biscuit sozinha","onde estão as companheiras de estábulo","outras éguas"}},{q="Wheeler's Grange está aberta?",a="Com Biscuit de volta, Wheeler's Grange voltou a funcionar.",al={"fazenda aberta","negócio de wheeler","fazenda reaberta"}}},fp="14,133,15.248.0,15.95.0,30.53.0,24.65.0,17.90.0,25.56.0"}
P.entries["quest:94997"] = {n="Lingering Essence",s="Riftan pede que você leve uma bolsa de lembranças amaldiçoadas para Ashe Amberhall, na Bastilha de Ermoforte. Ele espera que os estudos dela revelem as energias contidas nos objetos.",h="Riftan pede que você leve uma bolsa de lembranças amaldiçoadas para Ashe Amberhall, na Bastilha de Ermoforte.",kw={"ashe amberhall","cultistas","lembranças amaldiçoadas","energias","bastilha de ermoforte","essência persistente","riftan","satchel of cursed mementos"},sec={{t="Na Bastilha",b="Na Bastilha de Ermoforte, Ashe Amberhall recebe a bolsa e fica sabendo que Riftan a enviou. Ela diz que a longa luta dele contra os cultistas a preocupa, pois o cansaço pode estar afetando seu julgamento. Ainda assim, admite que as preocupações dele podem ter fundamento e volta sua atenção para os objetos."}},faq={{q="Quem me pediu para levar a bolsa?",a="Riftan pede que você leve a Satchel of Cursed Mementos para Ashe Amberhall.",al={"quem me enviou","bolsa de riftan","quem é riftan"}},{q="Quem é Ashe Amberhall?",a="Ashe Amberhall é uma estudiosa respeitada, e sua área de estudo pode ajudá-la a examinar as energias dos objetos.",al={"ashe quem","quem é ashe","amberhall"}},{q="Onde devo levar as lembranças?",a="Leve a Satchel of Cursed Mementos para Ashe Amberhall, na Bastilha de Ermoforte.",al={"onde levar a bolsa","bastilha de ermoforte","destino da bolsa"}},{q="O que há na bolsa?",a="A bolsa contém lembranças amaldiçoadas, e Riftan quer que Ashe examine as energias que elas contêm.",al={"o que tem na bolsa","lembranças amaldiçoadas","conteúdo da bolsa"}},{q="Por que Riftan quer que Ashe as examine?",a="Riftan espera que os estudos de Ashe revelem quais energias estão contidas nos objetos.",al={"por que ashe","para que serve a bolsa","essência persistente"}},{q="O que Ashe pensa da preocupação de Riftan?",a="Ashe teme que o cansaço da longa luta de Riftan contra os cultistas esteja afetando seu julgamento, embora diga que as preocupações dele podem ter fundamento.",al={"ashe confia em riftan","riftan cansado","opinião de ashe"}}},fp="17,153,11.279.0,38.73.0,22.108.0,29.72.0,23.95.0,42.86.0,41.132.0"}
P.entries["quest:94998"] = {n="Curios of Curiosity",s="Você leva uma bolsa com lembranças incomuns para Melanie Sable. O fino trabalho artesanal talvez as torne úteis.",h="Você leva uma bolsa com lembranças incomuns para Melanie Sable.",kw={"trabalho artesanal","curiosidades peculiares","melanie sable","lembranças","vestígios","bolsa com lembranças"},sec={{t="Uma bolsa para Melanie",b="Alguém que examinou as lembranças manda você levar a bolsa para Melanie Sable. A pessoa acredita que os objetos são seguros, embora sua origem continue desconhecida. O trabalho artesanal deles é incomum, e Melanie talvez encontre uma utilidade para eles."}},faq={{q="A quem devo levar as lembranças?",a="Leve a bolsa com as lembranças para Melanie Sable, como pede a pessoa que as examinou.",al={"onde levar a bolsa","quem é melanie sable"}},{q="O que são as lembranças?",a="São vestígios de alguma coisa, mas a pessoa que os examinou não sabe exatamente do quê.",al={"o que há na bolsa","o que são essas curiosidades"}},{q="Por que as lembranças são incomuns?",a="Dizem que o trabalho artesanal delas é bastante singular e intrincado.",al={"o que elas têm de especial","trabalho artesanal das curiosidades"}},{q="As lembranças são seguras?",a="A pessoa que as examinou pede que você diga a Melanie que as lembranças são seguras.",al={"a bolsa é segura","elas são perigosas"}}},fp="19,104,21.217.0,34.68.0,22.76.0,29.63.0,22.65.0"}
P.entries["quest:95"] = {n="A vingança de Noel",s="Movido pela dor e pelo desejo de vingança, o eremita Noel pede aos viajantes que retornem à sua fazenda em ruínas, no sul da Floresta do Crepúsculo. Após passar anos perseguindo os cavalgantes sombrios que mataram sua família, ele se lembra de uma figura suspeita que enterrou algo perto do celeiro. Talvez isso traga respostas.",h="Movido pela dor e pelo desejo de vingança, o eremita Noel pede aos viajantes que retornem à sua fazenda em...",kw={"cavalgantes negros","trilha do vento morto","floresta do crepúsculo","monte de terra solta","toco","noel","a vingança de noel","fazenda dos noel"},ang={["class:Paladin"]="O massacre de inocentes por forças sinistras vindas da Trilha do Vento Morto exige justiça e uma punição merecida pelos mortos.",["faction:Alliance"]="O massacre da família Noel é mais um sinal do isolamento da Floresta do Crepúsculo, mostrando até onde as forças sombrias chegam sem patrulhas regulares do exército de Ventobravo."},sec={{t="Tragédia na fazenda",b="Noel era um simples fazendeiro que trabalhava nos campos do sudeste da Floresta do Crepúsculo. Sua vida foi destruída quando cavaleiros encapuzados vindos da Trilha do Vento Morto atacaram sua propriedade e massacraram sua família enquanto ele estava fora. Ao retornar e encontrar todos mortos, Noel avistou uma figura desconhecida rondando o celeiro e enterrando algo às pressas. Tomado pela sede de vingança, partiu imediatamente em busca dos assassinos e deixou para trás o objeto escondido."},{t="Desenterrando segredos",b="Agora acampado nas colinas do oeste e consumido pela ira, Noel precisa que alguém retorne à Fazenda do Noel. Atrás de um velho cepo de árvore, entre a casa e o celeiro arruinado, há um monte de terra solta, amontoada às pressas. Recuperar o que foi enterrado ali é o primeiro passo para descobrir por que os cavalgantes sombrios atacaram um pacato fazendeiro da Floresta do Crepúsculo."}},faq={{q="Quem é Noel?",a="Noel era um fazendeiro comum que vivia no sudeste da Floresta do Crepúsculo, perto da fronteira com o Trilha do Vento Morto. Ao voltar para casa e descobrir que sua família havia sido assassinada por cavaleiros sinistros, abandonou a fazenda e se tornou um recluso obcecado em se vingar dos responsáveis.",al={"quem é noel","história de noel","passado de noel"}},{q="O que aconteceu com a fazenda de Noel?",a="A fazenda de Noel foi atacada pelos misteriosos Cavalgantes Negros vindos da Trilha do Vento Morto. Eles massacraram toda a família e deixaram a propriedade em ruínas antes que Noel pudesse voltar para defendê-los.",al={"tragédia na fazenda dos noel","o que aconteceu na fazenda de noel","por que a fazenda foi destruída"}},{q="Quem enterrou algo atrás do celeiro?",a="Noel viu uma figura sombria perto do celeiro, enterrando um objeto logo após o massacre. Ele partiu em perseguição aos Cavalgantes Negros antes de conseguir capturar o desconhecido ou desenterrar o que havia sido escondido.",al={"quem enterrou o objeto","figura sombria na fazenda de noel","quem cavou o monte de terra"}},{q="Onde fica o monte de terra solta?",a="O monte de terra solta fica na Fazenda do Noel, no sudeste da Floresta do Crepúsculo, atrás de um velho cepo de árvore entre o celeiro e a casa em ruínas.",al={"onde fica o monte de terra","localização da terra solta","onde fica o toco"}},{q="Quem são os Cavalgantes Negros?",a="Os Cavalgantes Negros são cavaleiros encapuzados e ameaçadores que surgem da Trilha do Vento Morto. Pouco se sabe sobre suas origens, mas suas incursões violentas na Floresta do Crepúsculo deixam apenas morte e destruição.",al={"quem são os cavalgantes negros","história dos cavalgantes negros","cavaleiros do trilha do vento morto"}},{q="Por que Noel não desenterrou o objeto?",a="Ao voltar para casa e ver a figura enterrando o objeto, Noel ficou transtornado pela dor e perseguiu imediatamente os Cavalgantes Negros em retirada. Quando estabeleceu seu esconderijo, a fazenda já estava tomada por inimigos, e retornar àquele lugar era doloroso demais.",al={"por que noel não examinou a terra","por que noel foi embora"}}},fx={e064b97c={q="Por que Noel Figueira quer que o objeto enterrado seja recuperado?",a="Noel Figueira busca vingança pelo brutal massacre de sua família pelos misteriosos Cavaleiros Negros da Trilha do Vento Morto. Quando ele descobriu o massacre, testemunhou uma figura sombria enterrando algo apressadamente perto de seu celeiro antes de fugir. Movido pela raiva e pela necessidade de respostas, Noel acredita que o que quer que esteja sob o solo contém a chave para descobrir por que sua fazenda foi alvo e quem ajudou na destruição de sua família.",al={"por que noel quer isso","motivo de noel figueira","motivo da missão de vingança de noel"}}},fp="14,234,24.320.0,18.307.0,19.181.0,29.133.0,37.168.0,41.140.0,24.145.0,47.164.0"}
P.entries["quest:950"] = {n="Retorno a Onu",s="Retorno a Onu é uma missão da Aliança que conclui uma investigação inicial sobre os cultistas acampados ao longo da costa de Costa Negra. Após atacar o acampamento dos cultistas e tentar ler o Twilight Tome, um aventureiro recupera uma única página de rabiscos enlouquecedores para entregar ao Ancient of Lore Onu, no Bosque dos Anciãos.",h="Retorno a Onu é uma missão da Aliança que conclui uma investigação inicial sobre os cultistas acampados ao...",kw={"costa negra","bosque dos ancientes","rabiscos malucos","antigos","onu","twilight tome","martelo do crepúsculo"},ang={["class:Druid"]="A ressonância caótica e antinatural dos rabiscos representa uma afronta à ordem natural que os druidas servem para preservar ao lado de árvores como Onu.",["faction:Alliance"]="Investigar a atividade do culto ao longo da costa de Costa Negra garante que assentamentos de elfos noturnos como Auberdine permaneçam seguros contra ameaças ocultas.",["race:NightElf"]="A profanação das costas de Costa Negra por cultistas sombrios ameaça o equilíbrio guardado pelos Ancients of Lore, tornando os avisos de Onu profundamente pessoais para os kaldorei."},sec={{t="Um Vislumbre da Loucura",b="Ao descobrir o Twilight Tome dentro do acampamento do Martelo do Crepúsculo, qualquer pessoa que espreite suas páginas sofre um ataque imediato aos sentidos. O texto escrito nada e dança pelo pergaminho, e os ornamentos que antes pareciam elaborados transformam-se em figuras grotescas. A tensão mental é tão esmagadora que arrancar uma única página de notas rabiscadas é tudo o que uma mente mortal consegue suportar antes de sucumbir à vertigem."},{t="Suspeitas Ancestrais",b="Ao ser entregue a Onu, o imponente Ancião reconhece a aura antinatural que impregna o fragmento. O pergaminho irradia uma magia caótica e primordial que Onu atribui diretamente ao trabalho das forças antigas e sombrias enterradas sob a terra. Embora os rabiscos sejam difíceis de decifrar, eles confirmam que a presença do Martelo do Crepúsculo em Costa Negra não é mero banditismo, mas parte de um desígnio mais profundo e blasfemo."}},faq={{q="Qual é a página retirada do Twilight Tome?",a="A página, conhecida simplesmente como Rabiscos Malucos, é uma folha arrancada do livro sagrado do culto. Olhar para ela causa grave sofrimento mental, pois a escrita se contorce em padrões grotescos e mutáveis ligados à magia primordial do vazio.",al={"rabiscos malucos","o que são os rabiscos","página do twilight tome"}},{q="Quem é Onu?",a="Onu é um Ancient of Lore enraizado no Bosque dos Anciãos, no sul de Costa Negra. Ele atua como um guardião ancião e estudioso, guiando elfos noturnos e aliados da Aliança contra corrupções emergentes na floresta.",al={"quem é onu","onu costa negra","treant onu"}},{q="O que Onu descobre com os rabiscos?",a="Onu sente energias caóticas e primordiais emanando da página, identificando a influência de entidades antigas e malévolas. Os escritos sugerem que os cultistas do Martelo do Crepúsculo estão buscando ativamente locais com relíquias e poderes enterrados por toda Costa Negra.",al={"o que onu encontrou","significado dos rabiscos"}},{q="Por que o Martelo do Crepúsculo está em Costa Negra?",a="O culto é atraído a Costa Negra para escavar locais élficos arruinados e descobrir vestígios de um poder antigo ligado à escuridão primordial e aos Deuses Antigos, usando o caos da terra para mascarar seus rituais.",al={"cultistas em costa negra","por que o martelo do crepúsculo está aqui"}},{q="Para onde essa investigação segue?",a="Após a descoberta da presença do culto, Onu volta sua atenção para as antigas ruínas élficas de Mathistra, ao norte, orientando os aventureiros a garantir relíquias antigas antes que os cultistas possam tomá-las.",al={"qual é a próxima missão","o que vem depois de return to onu"}},{q="Por que ler o tomo causa tontura?",a="O Twilight Tome está inscrito com magia sombria e enlouquecedora do vazio e do caos. Os glifos confundem ativamente as mentes mortais, causando alucinações e desmaios para impedir que estranhos desvendem seus segredos.",al={"por que o tomo causa tontura","efeitos do twilight tome"}}},fp="13,134,22.216.0,18.276.1,46.130.0,11.190.0,39.209.0,42.194.0,40.157.1,42.166.0"}
P.entries["quest:95033"] = {n="On the Other Side",s="Tan'jani envia você à Aldeia Mojache, em Feralas, para buscar a ajuda do Mandingueiro Uzer'i. Conhecido por sua magia, Uzer'i também é caçador.",h="Tan'jani envia você à Aldeia Mojache, em Feralas, para buscar a ajuda do Mandingueiro Uzer'i.",kw={"aldeia mojache","feralas","caçador","magia","do outro lado","tan'jani","mandingueiro uzer'i"},sec={{t="Amigo de Tan'jani",b="Em Feralas, você encontra o Mandingueiro Uzer'i na Aldeia Mojache. Ele é um velho amigo de Tan'jani. Tan'jani conta que Uzer'i pratica magia, mas também é caçador. Você deve falar com ele e deixar para trás as vastas planícies abertas."}},faq={{q="Quem me enviou até Uzer'i?",a="Tan'jani envia você ao Mandingueiro Uzer'i, um velho amigo.",al={"tan'jani me enviou","quem é o velho tanjani"}},{q="Onde posso encontrar Uzer'i?",a="O Mandingueiro Uzer'i está na Aldeia Mojache, em Feralas.",al={"localização de uzer'i","onde fica o mandingueiro"}},{q="Por que devo ir até Uzer'i?",a="Tan'jani diz que Uzer'i está procurando ajuda e pede que você fale com ele.",al={"por que falar com uzer'i","o que tanjani quer"}},{q="O que Uzer'i faz?",a="O Mandingueiro Uzer'i pratica magia e também é caçador.",al={"profissão de uzer'i","mandingueiro caçador"}}},fp="17,137,17.228.0,22.57.0,24.50.0,30.72.0,20.58.0"}
P.entries["quest:95034"] = {n="The Debt",s="Lumina Windsinger, no Sepulcro, relata o ataque que deixou Banon gravemente ferido. Seu relato aponta um worgen como a criatura que os atacou na estrada.",h="Lumina Windsinger, no Sepulcro, relata o ataque que deixou Banon gravemente ferido.",kw={"banon","gnolls","lumina windsinger","ataque na estrada","o sepulcro","the debt","worgen"},sec={{t="Um ferimento na estrada",b="Lumina Windsinger, no Sepulcro, conta a você o que aconteceu na estrada. Um worgen gigante, semelhante a um lobo, atacou seu grupo e matou os guardas. Banon se colocou entre a criatura e Lumina, que a afugentou com um feitiço. Àquela altura, Banon já havia sofrido mordidas graves. Ele insistiu para que ela o deixasse, mas ela ficou, e os dois seguiram mancando antes que gnolls os encontrassem."},{t="Os últimos momentos de Banon",b="Banon, no Sepulcro, foi perfurado por muitas lâminas de gnolls antes de se voltar contra Lumina. Ela viu que ele ainda a reconhecia, embora não conseguisse se controlar. Lumina acredita que o worgen o condenou e jura matá-lo para que ele não possa infligir o mesmo horror a outro ser vivo."}},faq={{q="Quem atacou Lumina e Banon na estrada?",a="Um worgen gigante, semelhante a um lobo, atacou Lumina e Banon na estrada.",al={"o que os atacou","ataque de worgen","agressor da estrada"}},{q="O que aconteceu com os guardas?",a="O worgen matou os guardas que acompanhavam Lumina e Banon.",al={"destino dos guardas","o que houve com os guardas","guardas da estrada"}},{q="Como Lumina afugentou o worgen?",a="Lumina conseguiu lançar um feitiço que assustou o worgen e o fez fugir.",al={"como o worgen fugiu","feitiço de lumina","o que o assustou"}},{q="Por que Banon foi mordido?",a="Banon se jogou no caminho do worgen para proteger Lumina, e a criatura o feriu gravemente com suas mordidas.",al={"mordida em banon","como banon se feriu","o que aconteceu com banon"}},{q="Onde Lumina conta a você o que aconteceu?",a="Lumina Windsinger conta seu relato a você no Sepulcro.",al={"onde encontrar lumina","localização de lumina","o sepulcro"}}},fp="8,160,19.344.0,20.277.1,42.64.0,28.66.0,36.78.0,21.91.0,41.57.0"}
P.entries["quest:95036"] = {n="A Moon-Kissed Blade",s="Trevan alerta que os worgens ameaçam a Floresta de Pinhaprata e aponta Old Fire-Eye como um inimigo que resiste à morte por meio de magia desconhecida. Ele pede que você descubra o necessário para uma lâmina especial.",h="Trevan alerta que os worgens ameaçam a Floresta de Pinhaprata e aponta Old Fire-Eye como um inimigo que...",kw={"uma lâmina beijada pela lua","materiais da lâmina","old fire-eye","floresta de pinhaprata","arma especial","trevan","worgen"},sec={{t="A lista do ferreiro",b="Old Fire-Eye é o worgen que atacou Trevan e seus companheiros. Trevan lhe dará uma lista dos materiais necessários para forjar uma arma contra ele. Os materiais são reunidos, e Trevan acredita conhecer um ferreiro capaz de fabricar a lâmina."}},faq={{q="Quem é Old Fire-Eye?",a="Old Fire-Eye é o maior e mais cruel dos worgens, e atacou Trevan e seus companheiros.",al={"old fire-eye","worgen fire-eye","worgen grande"}},{q="Por que Old Fire-Eye sempre volta?",a="Uma magia desconhecida impede que Old Fire-Eye permaneça morto.",al={"por que fire-eye não morre","magia de old fire-eye","worgen que não permanece morto"}},{q="O que Trevan precisa de mim?",a="Trevan lhe dará uma lista dos materiais necessários para forjar uma arma especial.",al={"o que trevan quer","lista de trevan","materiais da lâmina"}},{q="Por que é necessária uma lâmina especial?",a="Old Fire-Eye resiste à morte por meio de magia desconhecida, então Trevan diz que é necessária uma arma especial para acabar com ele.",al={"por que lâmina beijada pela lua","arma para old fire-eye","matar fire-eye"}},{q="Quem pode fabricar a lâmina?",a="Trevan acredita conhecer um ferreiro capaz de fabricar a lâmina.",al={"ferreiro para a lâmina","quem faz a lâmina lunar","ferreiro da lâmina"}}},fp="19,185,14.239.0,20.97.0,39.51.0,30.74.0,30.108.0,24.57.0"}
P.entries["quest:95041"] = {n="Acumuladores de dados",s="Acumuladores de dados é uma tarefa concedida por Jemma Quikswitch, uma gnoma exilada que reside em Altaforja. Durante a evacuação desesperada de Gnomeregan, ela copiou os arquivos mais preciosos de sua família em cartões perfurados, apenas para perder vários nos montes de neve congelantes do lado de fora dos portões da cidade. Recuperar esses cartões de dados perdidos significa resgatar desde esquemas avançados de engenharia naval até receitas de família insubstituíveis.",h="Acumuladores de dados é uma tarefa concedida por Jemma Quikswitch, uma gnoma exilada que reside em Altaforja.",kw={"data hoarders","dun morogh","gnomeregan","altaforja","jemma quikswitch","cartões perfurados","segunda guerra","casco de submarino"},ang={["faction:Alliance"]="A Aliança depende muito da engenhosidade dos gnomos; ajudar refugiados deslocados a preservar registros de engenharia dos tempos de guerra garante que o valioso conhecimento técnico da Aliança não se perca para sempre.",["profession:Cooking"]="Guardada ao lado de esquemas de engenharia de primeira linha está a receita pessoal de chili da Vovó Quikswitch, provando que a boa comida possui tanto valor sentimental quanto a ciência militar.",["profession:Engineering"]="Engenheiros conseguem reconhecer o imenso valor escondido nesses cartões, que contêm projetos autênticos de cascos de submarino da Segunda Guerra e equações arcanotécnicas complexas.",["race:Gnome"]="Para aventureiros gnomos, recuperar esses cartões perfurados é uma questão de preservação cultural, garantindo que invenções vitais e memórias de família não se percam nas ruínas radioativas de sua terra natal."},sec={{t="Uma Corrida na Neve",b="Quando a invasão trogg e o subsequente desastre de radiação forçaram os gnomos a saírem de Gnomeregan, milhares fugiram com quaisquer pertences que conseguiram pegar no caos. Jemma Quikswitch tomou a prudente medida de transcrever gerações de conhecimento familiar em arquivos físicos de cartões perfurados. Tragicamente, uma bolsa danificada espalhou vários cartões cruciais pelos campos de neve que cercam a cidade caída. Sem esses cartões perfurados perdidos, os dados restantes constam como jargões indecifráveis, ameaçando apagar o legado intelectual de sua família."},{t="Equações e Chili",b="Os arquivos de dados dos gnomos refletem a amplitude peculiar das prioridades de sua civilização. Os registros da família Quikswitch incluem profundas equações de campo arcanotécnicas, plantas vitais do casco de submarinos da Segunda Guerra e a receita secreta de chili da Vovó Quikswitch. Para quem vê de fora, combinar engenharia militar com culinária caseira pode parecer estranho, mas para os refugiados sobreviventes em Altaforja, preservar os confortos domésticos importa tanto quanto preservar maravilhas tecnológicas."}},faq={{q="Quem é Jemma Quikswitch?",a="Jemma Quikswitch é uma refugiada gnoma que conseguiu escapar da queda de Gnomeregan e agora reside em segurança entre os salões anões de Altaforja.",al={"jemma quikswitch","quem dá data hoarders","concedente da missão data hoarders"}},{q="Quais dados estão armazenados nos cartões perdidos?",a="Os cartões perfurados guardam os arquivos da família Quikswitch, incluindo equações arcanotécnicas, esquemas de cascos de submarino que remontam à Segunda Guerra e a receita de chili da Vovó Quikswitch.",al={"o que são os cartões perfurados","o que havia nos cartões","arquivos dos quikswitch"}},{q="Onde os cartões de dados foram perdidos?",a="Eles escorregaram por um buraco na mochila de Jemma enquanto ela fugia de Gnomeregan, deixando-os enterrados no terreno nevado nos arredores dos portões da cidade subterrânea em Dun Morogh.",al={"onde estão os cartões","localização dos cartões de dados","onde ela os deixou cair"}},{q="Por que Jemma não consegue ler os cartões sobreviventes sem os que estão faltando?",a="Jemma afirma que os dados estão embaralhados demais para serem recuperados sem os cartões perfurados que faltam. A missão não explica como os cartões codificam ou organizam essa informação.",al={"por que precisa de todos os cartões","dados embaralhados","dados dos cartões perfurados"}},{q="Qual papel os gnomos desempenharam na Segunda Guerra em relação aos submarinos?",a="Durante a Segunda Guerra, os gnomos contribuíram fortemente para o esforço militar da Aliança por meio de engenharia avançada, projetando e pilotando especificamente embarcações submersíveis para combater as forças navais da Horda.",al={"submarinos de gnomos na segunda guerra","projetos de casco de submarino"}},{q="Por que os refugiados gnomos estão vivendo em Altaforja?",a="Após a queda repentina de Gnomeregan para invasores troggs e a radiação catastrófica, os gnomos sobreviventes fugiram de seu lar subterrâneo e receberam santuário do Rei Magni Barbabronze na cidade anã vizinha de Altaforja.",al={"por que há gnomos em altaforja","gnomos morando com anões"}}},fp="13,256,22.294.0,19.259.0,24.95.0,38.177.0,34.125.0,66.158.0,65.158.0,45.172.0"}
P.entries["quest:95042"] = {n="Seeking the Kor Gem",s="Ulric Frostveil, um Renegado no Vale Gris, vê sua busca por uma Kor Gem como um trabalho familiar para os conjuradores da Aliança. Ele indica as Profundezas Negras, onde os naga ainda usam as gemas.",h="Ulric Frostveil, um Renegado no Vale Gris, vê sua busca por uma Kor Gem como um trabalho familiar para os...",kw={"vale gris","profundezas negras","renegados","kor gem","naga","ulric frostveil"},sec={{t="Uma gema no Vale Gris",b="Ulric pede que você traga uma Kor Gem das ruínas das Profundezas Negras, ao norte do Vale Gris. Ele diz que os naga lá embaixo ainda usam as gemas, que podem fortalecer armas e instrumentos mágicos. Ele alerta você para não ir sozinho."},{t="O interesse de Ulric",b="Ulric reconhece a corrupção na gema e diz que pode dissipar o mal que as bruxas naga infundiram nela. Ele pergunta se você a venderia para ele, para suas pesquisas acadêmicas."}},faq={{q="Quem é Ulric Frostveil?",a="Ulric Frostveil é um Renegado no Vale Gris que pede que você lhe traga uma Kor Gem.",al={"ulric frostveil","quem é ulric","renegado no vale gris"}},{q="Onde posso encontrar uma Kor Gem?",a="Ulric indica que você siga para o norte, até as Profundezas Negras, onde os naga ainda usam Kor Gems.",al={"localização da kor gem","onde encontrar gema","gema das profundezas negras"}},{q="Para que servem as Kor Gems?",a="Às vezes, as Kor Gems são usadas para fortalecer armas e instrumentos mágicos.",al={"uso da kor gem","magia da gema","o que a kor gem faz"}},{q="Por que Ulric quer uma Kor Gem?",a="Ulric pede que você lhe traga uma Kor Gem e diz que ela pode ser valiosa para suas pesquisas acadêmicas.",al={"ulric quer gema","por que a gema","gema frostveil"}},{q="Quem ainda usa Kor Gems?",a="Os naga das Profundezas Negras ainda usam Kor Gems.",al={"gemas naga","quem usa kor gems","naga das profundezas negras"}}},fp="19,177,18.215.0,16.190.1,23.79.0,27.76.0,27.52.0,30.89.0,24.49.0"}
P.entries["quest:95059"] = {n="Frazzlespark's Crate",s="Um goblin tem uma entrega para Knight Commander Demar Brant na Bastilha de Ermoforte. Pedem a você que leve o caixote de Frazzlespark até ele.",h="Um goblin tem uma entrega para Knight Commander Demar Brant na Bastilha de Ermoforte.",kw={"caixa","demar brant","bastilha de ermoforte","frazzlespark","frazzlespark's crate","entrega do goblin","comandante cavaleiro"},sec={{t="Uma entrega para a Bastilha",b="Frazzlespark envia você para sudoeste, até a Bastilha de Ermoforte, onde Knight Commander Demar Brant está esperando. O caixote é destinado a ele, e o goblin faz questão de usar o nome completo dele. Na bastilha, Demar chama o goblin de mero meio para atingir um fim, parte das negociações que, segundo ele, mantêm seu próprio povo seguro e próspero."}},faq={{q="Quem está esperando pela caixa?",a="O Comandante Cavaleiro Demar Brant está esperando por Frazzlespark's Crate na Bastilha de Ermoforte.",al={"quem quer a caixa","entrega para demar brant"}},{q="Onde devo levar Frazzlespark's Crate?",a="Leve Frazzlespark's Crate ao Comandante Cavaleiro Demar Brant na Bastilha de Ermoforte, a sudoeste de Frazzlespark.",al={"localização da caixa","onde fica a bastilha de ermoforte"}},{q="Por que Demar quer que usem seu nome completo?",a="Frazzlespark comenta que Demar sempre faz o goblin usar seu nome completo, mas não explica o motivo.",al={"nome completo de demar","por que comandante cavaleiro"}},{q="Por que Frazzlespark chama isso de entrega especial?",a="Frazzlespark chama isso de entrega especial e diz que Demar Brant está esperando por ela na Bastilha de Ermoforte.",al={"entrega da caixa","o que há de especial na caixa"}},{q="Por que essa entrega é importante?",a="Demar Brant diz que certas negociações precisam ser feitas para garantir a segurança e o sucesso de seu povo, e chama o goblin de nada além de um meio para atingir um fim.",al={"por que entregar a caixa","segurança dos goblins"}}},fp="20,126,19.303.0,29.82.0,37.102.0,39.95.0,49.98.0,30.152.0"}
P.entries["quest:95062"] = {n="Frazzlespark's Crate",s="Uma entrega de Frazzlespark está a caminho de Old Krom'rosh, em Rog'mar. Leve a caixa até lá com rapidez e cuidado.",h="Uma entrega de Frazzlespark está a caminho de Old Krom'rosh, em Rog'mar.",kw={"caixa","entrega","frazzlespark","caixa de frazzlespark","krom'rosh","old krom'rosh","pacote","rog'mar"},sec={{t="Uma Entrega Cuidadosa",b="Frazzlespark tem um pacote para Old Krom'rosh, que está esperando em Rog'mar, logo a oeste daqui. Pedem que você o leve com rapidez e cuidado, mas não dizem o motivo. Os negócios de Krom'rosh ajudam a alcançar os objetivos do grupo."}},faq={{q="Quem está esperando pela caixa de Frazzlespark?",a="Old Krom'rosh está esperando pela caixa de Frazzlespark em Rog'mar.",al={"quem recebe a caixa","caixa para krom'rosh","pacote para kromrosh"}},{q="Onde fica Rog'mar?",a="Rog'mar fica logo a oeste de Frazzlespark.",al={"onde fica rog'mar","localização de rog'mar","lugar rog'mar"}},{q="O que devo fazer com a caixa?",a="Leve a caixa de Frazzlespark até Old Krom'rosh, em Rog'mar, com rapidez e cuidado.",al={"entregar a caixa","entrega de frazzlespark","o que fazer"}},{q="Por que a caixa precisa ser entregue com cuidado?",a="Frazzlespark aconselha você a fazer a entrega com rapidez e cuidado, mas não explica o motivo.",al={"por que ter cuidado","por que apressar a entrega da caixa","motivo da caixa"}},{q="Por que Krom'rosh faz esse tipo de negócio?",a="Krom'rosh diz que esses negócios ajudam a alcançar seus objetivos.",al={"negócios de krom'rosh","por que as relações","para que servem os negócios"}}},fp="20,112,18.231.0,40.61.0,17.37.0,32.78.0,41.81.0,48.57.0"}
P.entries["quest:95064"] = {n="Preventative Measures",s="Watcher Cornelius, em Terral's Watch, teme que os orcs avancem cada vez mais pelas planícies. Ele pede que você contenha a presença crescente deles.",h="Watcher Cornelius, em Terral's Watch, teme que os orcs avancem cada vez mais pelas planícies.",kw={"orcs","planícies","medidas preventivas","recrutas de rog'mar","terral's watch","watcher cornelius"},sec={{t="Orcs nas planícies",b="Em Terral's Watch, Watcher Cornelius vê os orcs ocupando terras às margens do rio e avançando pelas planícies. Ele pede que você mate recrutas de Rog'mar, na esperança de deter o avanço deles."}},faq={{q="Quem pede ajuda?",a="Watcher Cornelius, em Terral's Watch, pede que você detenha a presença crescente dos orcs.",al={"quem precisa de ajuda","pedido de cornelius"}},{q="Por que Cornelius está preocupado com os orcs?",a="Os orcs ocuparam terras às margens do rio, e sua presença está crescendo nas planícies.",al={"por que lutar contra orcs","orcs nas planícies"}},{q="Quais orcs Cornelius quer que você mate?",a="Cornelius pede que você mate recrutas de Rog'mar.",al={"recrutas de rog'mar","quais orcs"}},{q="Onde Cornelius pede ajuda?",a="Cornelius pede ajuda em Terral's Watch.",al={"terral's watch","onde fica cornelius"}}},fp="21,132,18.176.0,18.80.0,42.85.0,38.44.0,34.42.0"}
P.entries["quest:95065"] = {n="Hora da pesca",s="Hora da pesca é um favor simples para Gilbertoo Cinéreo, um pescador idoso que aprecia a paisagem costeira no porto de Ventobravo. Quando a isca acaba justamente na hora em que os peixes começam a morder, ele pede a quem passa que vá aos canais da cidade comprar mais suprimentos de pesca.",h="Hora da pesca é um favor simples para Gilbertoo Cinéreo, um pescador idoso que aprecia a paisagem costeira no...",kw={"canais","catarina gurjão","hora da pesca","gilberto cinéreo","reptantes","miçanga brilhosa","porto de ventobravo","distrito comercial"},ang={["faction:Alliance"]="Reservar um tempo para ajudar um cidadão idoso como Gilbertoo Cinéreo reflete os pequenos afazeres cotidianos que sustentam a vida e o ânimo da população de Ventobravo.",["race:Human"]="Para os humanos que chamam Ventobravo de lar, ajudar um idoso do bairro a desfrutar de uma tarde tranquila de pesca é uma pausa bem-vinda na política do reino."},sec={{t="Um dia à beira d'água",b="Nem todo mundo em Ventobravo está envolvido com política, guerras ou conspirações iminentes. Na beira do porto, Gilbertoo Cinéreo passa seus dias tranquilos aproveitando a brisa do mar e observando a boia dançar sobre as ondas. Mas um pescador entusiasmado pode facilmente perder a conta dos suprimentos, e uma sequência repentina de fisgadas esgota até o pote de iscas mais bem abastecido. Para não abandonar seu lugar favorito, o velho recorre a aventureiros dispostos a repor seus materiais."},{t="Suprimentos nos canais",b="Os pescadores de Ventobravo contam com Catarina Gurjão, que mantém uma conhecida loja de artigos de pesca junto aos canais de pedra, a oeste do movimentado Distrito Comercial. Ao vender anzóis, iscas e outros equipamentos pela cidade, Gurjão garante que clientes antigos como Gilbertoo Cinéreo não precisem recolher as linhas antes da hora por falta de uma isca brilhante ou de uma minhoca."}},faq={{q="Quem é Gilbertoo Cinéreo?",a="Gilbertoo Cinéreo é um pescador idoso que fica à beira d'água no porto de Ventobravo. Feliz em passar os dias lançando a linha ao mar, ele pede aos aventureiros que tragam iscas e materiais de pesca quando seus próprios suprimentos acabam.",al={"gilberto cinéreo","velho cinéreo","quem oferece esta missão"}},{q="Quem é Catarina Gurjão?",a="Catarina Gurjão é uma comerciante de artigos de pesca de Ventobravo. Sua loja fica junto aos canais da cidade, a oeste do Distrito Comercial, onde ela vende equipamentos e iscas aos pescadores do reino.",al={"catarina gurjão","vendedora de pesca em ventobravo","gurjão ventobravo"}},{q="Onde Gilbertoo Cinéreo pesca?",a="Gilbertoo Cinéreo fica perto da água no porto de Ventobravo, de onde aprecia a vista do mar aberto, longe das ruas movimentadas da cidade.",al={"localização de gilberto cinéreo","onde fica gilberto cinéreo","pescador do porto"}},{q="De quais suprimentos Gilbertoo Cinéreo precisa?",a="Gilbertoo Cinéreo precisa de reptantes como isca e de uma miçanga brilhosa para atrair os peixes. Ambos os itens podem ser comprados com Catarina Gurjão, junto aos canais.",al={"itens da missão hora da pesca","que isca cinéreo quer"}},{q="Por que Gilbertoo Cinéreo não busca os suprimentos pessoalmente?",a="Os peixes estão mordendo a isca quando você fala com ele, e o pescador não quer perder seu lugar nem deixar escapar uma boa pescaria para atravessar a cidade em busca de suprimentos.",al={"por que cinéreo não compra iscas","por que cinéreo precisa de ajuda"}},{q="Onde fica a loja de Catarina Gurjão nos canais?",a="A loja fica junto à água, a oeste do Distrito Comercial, com acesso direto pelas passarelas de pedra que cruzam a rede de canais da cidade.",al={"localização de catarina gurjão","onde fica a loja de gurjão","canais do distrito comercial"}}},fp="12,206,18.235.0,25.223.0,20.167.0,24.160.0,29.82.0,37.118.0,52.132.0,58.129.0"}
P.entries["quest:951"] = {n="Relíquias de Mathistra",s="Esta missão envia aventureiros da Aliança para o norte, ao longo da costa de Costa Negra, para vasculhar as tomadas pela vegetação Ruínas de Mathistra. Onu, um Ancião dos Saberes enraizado no Bosque dos Ancientes, busca esses antigos artefatos kaldorei para entender como o Martelo do Crepúsculo está manipulando a feitiçaria dos elfos noturnos em seus ritos sinistros.",h="Esta missão envia aventureiros da Aliança para o norte, ao longo da costa de Costa Negra, para vasculhar as...",kw={"costa negra","bosque dos ancientes","glaive do mestre","mathistra","onu","relíquias","ruínas de mathistra","martelo do crepúsculo"},ang={["class:Druid"]="Ajudar Onu permite que os druidas sirvam a uma das maiores sentinelas anciãs da natureza, protegendo a história ancestral de Costa Negra de ser distorcida por sectários sombrios.",["faction:Alliance"]="Impedir que o Martelo do Crepúsculo use a magia antiga como arma é essencial para proteger o norte de Kalimdor contra forças sombrias e subterrâneas.",["race:NightElf"]="Para os elfos noturnos, ver relíquias de sua glória anterior à Cisão serem desenterradas da terra é uma lembrança sombria da queda de sua civilização — e um aviso alarmante de que as potentes artes de seus ancestrais estão sendo exploradas por loucos apocalípticos."},sec={{t="Uma Descoberta Perturbadora",b="Após aventureiros recuperarem um pergaminho maculado dos sectários que espreitavam ao redor do monumento colossal conhecido como a Glaive do Mestre, Onu decifrou uma revelação perturbadora. O texto não era uma escritura nativa do culto, mas um fragmento amaldiçoado de antigos escritos élficos noturnos. Corrompido pelo Martelo do Crepúsculo, o pergaminho revelou que esses fanáticos apocalípticos estão aproveitando a magia élfica esquecida para despertar ou evocar seus antigos mestres de volta ao mundo mortal."},{t="O Bastião Caído",b="Para combater essa empreitada sombria, Onu direciona os heróis às Ruínas de Mathistra, localizadas ao longo da costa nordeste de Costa Negra. Há muito tempo, Mathistra foi um radiante bastião da civilização altaneira antes de se despedaçar durante a Cisão. Embora a cidade tenha desmoronado em escombros, ervas daninhas e uma infestação de nagas, poderosos resquícios de seus encantamentos arcanos e espirituais originais ainda perduram em urnas despedaçadas e relíquias antigas espalhadas pelas fundações de pedra."},{t="Adivinhando Desígnios Sombrios",b="Ao coletar artefatos sobreviventes dos detritos cobertos de grama das ruínas, os defensores de Costa Negra esperam desvendar as técnicas específicas que os sectários pretendem explorar. Onu estuda a magia residual impregnada nas relíquias, correndo contra o tempo para decifrar os planos do culto antes que o Martelo do Crepúsculo consiga subjugar completamente a antiga feitiçaria kaldorei para libertar seus mestres subterrâneos."}},faq={{q="O que são as Relíquias de Mathistra?",a="São fragmentos de cerâmica encantada, urnas e artefatos deixados para trás nas Ruínas de Mathistra. Criados durante o ápice da antiga civilização dos elfos noturnos antes da Grande Cisão, eles ainda vibram com uma energia mágica persistente.",al={"o que são as relíquias","história das relíquias de mathistra","relíquias élficas mathistra"}},{q="Por que Onu quer essas relíquias?",a="Onu descobriu que o Martelo do Crepúsculo está usando a antiga magia élfica para tentar trazer seus mestres sombrios de volta ao mundo. Ao estudar relíquias intactas de Mathistra, Onu espera compreender como o culto pretende manipular esse poder ancestral.",al={"por que onu quer relíquias","propósito das relíquias de mathistra"}},{q="Onde ficavam as Ruínas de Mathistra?",a="As ruínas ficam ao longo da costa nordeste de Costa Negra, ao norte das ruínas de Ameth'Aran e Bashal'Aran, logo após A Torre de Althalaxx.",al={"onde fica mathistra","localização de mathistra"}},{q="Quem o Martelo do Crepúsculo está tentando trazer de volta?",a="O culto é dedicado a mestres antigos e malévolos; Onu adverte que eles estão usando a antiga magia élfica para trazer esses velhos mestres de volta a Azeroth.",al={"quem são os mestres do martelo do crepúsculo","mestres do culto costa negra"}},{q="O que era Mathistra antes de se tornar uma ruína?",a="Mathistra já foi um grande bastião e cidade dos elfos noturnos há milhares de anos. Ela caiu em ruínas durante a Grande Cisão e, desde então, foi dominada pela natureza selvagem, fantasmas e vis criaturas costeiras, como as nagas.",al={"história de mathistra","o que era mathistra"}},{q="Quem concede a missão 'Relíquias de Mathistra'?",a="A missão é concedida por Onu, um antigo arvoroso enraizado no Bosque dos Ancientes, no centro-sul de Costa Negra, após a investigação da Glaive do Mestre.",al={"quem inicia relíquias de mathistra","doador da missão relíquias de mathistra"}}},fp="16,215,22.360.1,18.296.0,21.293.1,30.220.0,31.222.0,42.138.0,50.154.0,43.204.0,39.177.0"}
P.entries["quest:95111"] = {n="An Underrated Talent",s="Trevan Rol, na Floresta de Pinhaprata, pede que você leve materiais a Ott, na Serraria Tarren, e lhe ofereça uma encomenda personalizada. Suas lâminas simples impressionaram os ferreiros da Cidade Baixa, e essa encomenda lhe dá a chance de mostrar o que sabe fazer.",h="Trevan Rol, na Floresta de Pinhaprata, pede que você leve materiais a Ott, na Serraria Tarren, e lhe ofereça...",kw={"encomenda","lâmina personalizada","ott","ferreiro","serraria tarren","cidade baixa","ferreiro de armas"},sec={{t="Uma Chance para um Ferreiro",b="Trevan Rol pede que você leve materiais a Ott, na Serraria Tarren, e lhe ofereça uma encomenda. Ott é conhecido por vender lâminas simples a viajantes. Trevan comprou uma e depois a levou à Cidade Baixa para manutenção, onde os ferreiros locais se surpreenderam com sua qualidade. Eles acharam que era obra de um mestre famoso, mas foi Ott quem a fez. Agora você lhe oferece a chance de forjar uma lâmina conforme suas especificações."},{t="A Resposta de Ott",b="Ott diz que ninguém nunca lhe pediu uma encomenda personalizada. Ele costuma fabricar armas humildes e funcionais, do seu jeito, e diz que não busca reconhecimento. Está disposto a tentar, embora se pergunte por que você o escolheu, já que os ferreiros da Cidade Baixa também aceitam encomendas personalizadas."}},faq={{q="Quem é Ott?",a="Ott é um ferreiro de armas na Serraria Tarren que vende lâminas simples a viajantes.",al={"ferreiro ott","quem é ott","ferreiro da serraria tarren"}},{q="Por que o ferreiro da Cidade Baixa quer que eu encontre Ott?",a="O ferreiro comprou uma das lâminas de Ott e se surpreendeu quando os ferreiros da Cidade Baixa elogiaram sua qualidade. Ele quer dar a Ott a chance de fazer algo especial.",al={"por que ott","encomenda de ferreiro da cidade baixa","encomenda para ott"}},{q="O que estou levando para Ott?",a="Você está levando materiais para Ott, na Serraria Tarren, e oferecendo a ele uma encomenda para forjar sua lâmina.",al={"materiais para ott","o que levar","materiais de ott"}},{q="Ott faz armas personalizadas?",a="Ott diz que ninguém nunca lhe pediu uma encomenda personalizada, mas ele aceita tentar.",al={"lâmina personalizada de ott","ott pode forjar para mim","encomendas de ott"}},{q="Por que Ott pergunta por que o escolhi?",a="Ott diz que há ferreiros na Cidade Baixa que aceitam encomendas personalizadas e se pergunta por que você procurou justamente por ele.",al={"por que escolher ott","ott se pergunta por quê","por que não um ferreiro da cidade baixa"}}},fp="20,155,16.348.0,12.255.1,11.73.0,49.163.0,26.97.0,29.87.0,33.90.0"}
P.entries["quest:95118"] = {n="Saltwater Savages",s="Um responsável pelo porto pede que você reduza o número de Murlocs ao longo de Eastwind Shore. Eles se tornaram uma reclamação constante entre marinheiros, pescadores e seus filhos.",h="Um responsável pelo porto pede que você reduza o número de Murlocs ao longo de Eastwind Shore.",kw={"eastwind shore","pescadores","murloc","oráculo murloc","guerreiro murloc","responsável pelo porto","marinheiros","saltwater savages"},sec={{t="Reclamações no Porto",b="O responsável pelo porto já ouviu reclamações suficientes de marinheiros, pescadores e até dos próprios filhos. Os Murlocs o incomodam, mas ele ainda precisa cuidar do porto. Ele pede que você mate alguns ao longo de Eastwind Shore, na esperança de ter um pouco de paz em meio a todo aquele barulho."}},faq={{q="Por que o responsável pelo porto quer que os Murlocs sejam mortos?",a="Os marinheiros, pescadores e filhos do responsável pelo porto não param de reclamar deles. Ele os considera uma praga e quer um pouco de paz enquanto cuida do porto.",al={"por que matar murlocs","murlocs incomodam o porto"}},{q="De quais Murlocs ele está falando?",a="Ele pede que você mate Oráculos Murloc e Guerreiros Murloc ao longo de Eastwind Shore.",al={"tipos de murloc","oráculos e guerreiros"}},{q="Onde estão os Murlocs?",a="O responsável pelo porto indica Eastwind Shore.",al={"murlocs de eastwind shore","onde estão os murlocs"}},{q="Matar esses Murlocs resolve o problema?",a="O responsável pelo porto espera que mais Murlocs voltem em breve, mas torce para que as mortes deles lhe deem um pouco de paz até lá.",al={"murlocs voltam","acabou"}}},fp="17,152,22.244.0,49.149.0,33.76.0,22.45.0,45.118.0"}
P.entries["quest:95119"] = {n="Unfriendly Competition",s="Um comerciante do Porto Detonapavio pede que você contenha os ataques da tripulação Eastsea a cargas e navios. Os membros mais próximos estão ao longo da Costa Eastwind.",h="Um comerciante do Porto Detonapavio pede que você contenha os ataques da tripulação Eastsea a cargas e navios.",kw={"roubo de carga","bucaneiros eastsea","tripulação eastsea","mosqueteiros eastsea","costa eastwind","porto detonapavio","navios afundando","concorrência hostil"},sec={{t="Ao longo da costa",b="Navios afundam e cargas desaparecem, prejudicando os negócios do comerciante no Porto Detonapavio. Os bucaneiros e mosqueteiros da tripulação Eastsea são os mais próximos do porto, ao longo da Costa Eastwind, ao norte. O comerciante quer que você cuide deles primeiro; o restante das operações da tripulação continua sendo uma preocupação."}},faq={{q="Quem está pedindo ajuda?",a="Um comerciante do Porto Detonapavio pede que você cuide da tripulação Eastsea.",al={"quem deu isso","dono do porto","sujeito do detonapavio"}},{q="Quem é a tripulação Eastsea?",a="A tripulação Eastsea é descrita como destrutiva e sanguinária, e rouba cargas e afunda navios.",al={"piratas eastsea","sujeitos eastsea","quem é eastsea"}},{q="Por que o comerciante quer que eles sejam detidos?",a="A tripulação rouba cargas e afunda navios, causando prejuízo ao comerciante.",al={"por que lutar contra eastsea","roubo de carga","por que os navios estão afundando"}},{q="Onde os membros da tripulação Eastsea estão mais próximos do porto?",a="Os membros da tripulação mais próximos do Porto Detonapavio estão ao longo da Costa Eastwind, ao norte.",al={"costa eastwind","onde estão os piratas","praia ao norte"}}},fp="22,142,15.313.0,23.71.0,25.100.0,42.68.0,47.86.0"}
P.entries["quest:95120"] = {n="WANTED: Old Rot-Chum",s="O mestre do cais Whizzbuzz oferece uma recompensa por provas da morte de Old Rot-Chum. O murloc agressivo tem atacado pequenas embarcações nas águas do sul.",h="O mestre do cais Whizzbuzz oferece uma recompensa por provas da morte de Old Rot-Chum.",kw={"murloc","ilhas de murlocs","old rot-chum","botes a remo","pequenas embarcações","águas do sul","mestre do cais whizzbuzz"},sec={{t="Uma ameaça no mar",b="Marinheiros e nadadores nas águas ao sul sofrem ataques a botes a remo e outras pequenas embarcações. Os pescadores locais chamam o murloc agressivo por trás dos ataques de Old Rot-Chum. O mestre do cais Whizzbuzz oferece uma recompensa por provas de que a criatura está morta e pede que você a leve até ele."}},faq={{q="Quem é Old Rot-Chum?",a="Old Rot-Chum é o apelido que os pescadores locais dão a um murloc especialmente agressivo.",al={"old rot-chum","rot-chum","quem é rot-chum"}},{q="Onde Old Rot-Chum foi visto?",a="Old Rot-Chum foi visto nas águas ao sul, perto de ilhas infestadas de murlocs.",al={"onde fica old rot-chum","localização de rot-chum","onde está o murloc"}},{q="O que Old Rot-Chum tem atacado?",a="Old Rot-Chum tem atacado botes a remo e outras pequenas embarcações.",al={"o que rot-chum está atacando","ataques a barcos","murloc e botes a remo"}},{q="Quem oferece a recompensa?",a="O mestre do cais Whizzbuzz oferece uma recompensa em troca de provas da morte de Old Rot-Chum.",al={"quem quer provas de rot-chum","recompensa do mestre do cais","quem paga por old rot-chum"}},{q="Que prova Whizzbuzz pede?",a="O mestre do cais Whizzbuzz pede que você leve provas da morte de Old Rot-Chum.",al={"que prova de rot-chum","levar provas","proof of demise"}}},fp="20,154,15.274.0,20.82.0,33.90.0,37.65.0,22.87.0,34.73.0"}
P.entries["quest:95121"] = {n="A Taste of the Sea",s="Fimbo Greasemitz quer frutos do mar frescos para um ensopado novo em seu café à beira-mar. Você reúne ingredientes locais para renovar o cardápio.",h="Fimbo Greasemitz quer frutos do mar frescos para um ensopado novo em seu café à beira-mar.",kw={"praia","café","fimbo greasemitz","peixe","olhos de múrloc","javali assado","carne de sand crawler","ensopado de frutos do mar"},ang={["profession:Cooking"]="Como cozinheiro, você percebe que Fimbo está procurando ingredientes locais frescos para preparar um ensopado de frutos do mar."},sec={{t="Um Prato Novo",b="Fimbo Greasemitz administra um café à beira-mar, onde javali assado e peixe compõem o cardápio diário. Ele quer experimentar um ensopado de frutos do mar e pede que você traga olhos de múrloc e carne de Sand Crawler das praias próximas."}},faq={{q="Quem é Fimbo Greasemitz?",a="Fimbo Greasemitz administra um café à beira-mar e quer acrescentar ensopado de frutos do mar ao cardápio.",al={"quem é fimbo","café do fimbo","fimbo greasemitz"}},{q="De quais ingredientes Fimbo precisa?",a="Fimbo pede olhos de múrloc e carne de Sand Crawler para seu ensopado de frutos do mar.",al={"ingredientes do ensopado","qual carne","olhos de múrloc"}},{q="Por que Fimbo quer frutos do mar?",a="Ele quer uma receita nova de ensopado de frutos do mar para variar o cardápio diário do café, que oferece javali assado e peixe.",al={"por que ensopado","cardápio novo","comida do café"}},{q="Onde você pode encontrar os ingredientes?",a="Fimbo diz que os olhos de múrloc e a carne de Sand Crawler podem ser encontrados nas praias próximas.",al={"onde encontrar carne","onde encontrar ingredientes","coisas da praia"}}},fp="18,129,10.206.0,24.84.0,33.70.0,28.94.0,35.87.0"}
P.entries["quest:95123"] = {n="A Blast Ye Scurvy Dogs!",s="Wharfmaster Whizzbuzz quer pólvora para destruir os navios piratas de Eastsea. Você é enviado para procurar barris de pólvora perto de Winstead, recém-demolida.",h="Wharfmaster Whizzbuzz quer pólvora para destruir os navios piratas de Eastsea.",kw={"piratas de eastsea","pólvora","navios piratas","barris de pólvora","wharfmaster whizzbuzz","winstead"},sec={{t="Pólvora para o mestre do cais",b="Os navios são a próxima preocupação de Whizzbuzz, depois dos próprios piratas de Eastsea. Ele acredita que eles podem ter armazenado pólvora perto de Winstead, recém-demolida, ao norte. Você é enviado para encontrar os barris de pólvora; ele explicará seu plano mais tarde."}},faq={{q="Quem está pedindo a pólvora?",a="Wharfmaster Whizzbuzz quer pólvora para um plano contra os navios de Eastsea.",al={"quem quer os barris","pólvora de whizzbuzz","quem me enviou"}},{q="Por que Whizzbuzz quer pólvora?",a="Ele quer destruir os navios de Eastsea para que não possam fugir em busca de reforços.",al={"por que pólvora","para que serve a pólvora","plano contra os navios de eastsea"}},{q="Onde os piratas podem ter armazenado a pólvora?",a="Whizzbuzz acha que os piratas podem ter armazenado pólvora perto de Winstead, recém-demolida, ao norte.",al={"localização da pólvora","onde estão os barris","pólvora em winstead"}},{q="Qual é o plano de Whizzbuzz?",a="Whizzbuzz diz que explicará o plano mais tarde; por enquanto, quer que você encontre a pólvora.",al={"qual é o plano dele","plano de whizzbuzz","o que vai acontecer"}}},fp="23,137,26.241.0,29.75.0,34.78.0,47.105.0,25.88.0"}
P.entries["quest:95125"] = {n="Ott's Masterwork",s="Ott está pronto para forjar uma lâmina para você com materiais de qualidade. Você está convidado a acompanhar o trabalho dele.",h="Ott está pronto para forjar uma lâmina para você com materiais de qualidade.",kw={"ferreiro","lâmina","forja","obra-prima","materiais","ott"},sec={{t="Na forja",b="Ott considera os materiais excelentes e espera que o trabalho dele atenda às suas expectativas. Ele forja a lâmina para você e, em seguida, a oferece para suas viagens."}},faq={{q="Quem está fazendo minha lâmina?",a="Ott está forjando sua lâmina com os materiais de qualidade que você forneceu.",al={"quem forja","lâmina de ott","ott ferreiro"}},{q="Posso assistir Ott forjá-la?",a="Ott pede que você fique afastado enquanto começa a forjar, e a etapa solicitada é observá-lo trabalhar.",al={"assistir ott forjar","ver a lâmina sendo feita","processo de forja"}},{q="O que Ott diz quando a lâmina fica pronta?",a="Ott chama a lâmina de sua melhor obra e espera que ela seja útil em suas viagens.",al={"conclusão de ott","o que ott diz","lâmina pronta"}}},fp="16,85,12.137.0,23.63.0,25.81.0,45.81.0"}
P.entries["quest:95126"] = {n="The Moonsilver Blade",s="Trevan Rol pede que você leve a Obra-prima de Ott até ele, na Floresta de Pinhaprata. A lâmina é a última parte do trabalho dele antes de enfrentar uma fera.",h="Trevan Rol pede que você leve a Obra-prima de Ott até ele, na Floresta de Pinhaprata.",kw={"fera","lumina","lâmina de luaprata","ott","obra-prima de ott","floresta de pinhaprata","trevan rol"},sec={{t="A lâmina",b="Ott agradece pela oportunidade e pede que você transmita sua gratidão a Trevan. Você leva a Obra-prima de Ott de volta para Trevan Rol, na Floresta de Pinhaprata."},{t="A aprovação de Trevan",b="Trevan examina a lâmina e aprova o trabalho de Ott. Ele diz que só falta matar a fera e orienta você a falar com Lumina quando estiver pronto."}},faq={{q="Quem fez a Obra-prima de Ott?",a="Ott fez a lâmina e a enviou com você para Trevan Rol.",al={"quem fez a lâmina","lâmina de ott","criador da obra-prima"}},{q="Quem é Trevan Rol?",a="Trevan Rol é quem recebe e examina a Obra-prima de Ott na Floresta de Pinhaprata.",al={"quem é trevan","lâmina de trevan","trevan rol"}},{q="Onde devo levar a lâmina?",a="Leve a Obra-prima de Ott até Trevan Rol, na Floresta de Pinhaprata.",al={"para onde levar a lâmina","onde levar a obra-prima de ott","destino da lâmina"}},{q="O que Trevan acha da lâmina?",a="Trevan examina a lâmina e diz que ela servirá muito bem.",al={"trevan gostou da lâmina","a lâmina de ott é boa","aprovação de trevan"}},{q="Com quem devo falar depois de Trevan?",a="Trevan orienta você a falar com Lumina quando estiver pronto.",al={"o que fazer em seguida","quem é lumina","falar com lumina"}}},fp="20,102,9.152.0,17.138.1,26.61.0,18.71.0,27.58.0,36.57.0,37.64.0"}
P.entries["quest:95140"] = {n="Old Fire-Eye",s="Lumina Windsinger pede que você cace Old Fire-Eye na Floresta de Pinhaprata com a Lâmina de Luaprata. Os Moldavento aguardam sua morte, e Lumina espera que a lâmina lhe seja útil.",h="Lumina Windsinger pede que você cace Old Fire-Eye na Floresta de Pinhaprata com a Lâmina de Luaprata.",kw={"banon","guilnéas","lumina windsinger","lâmina de luaprata","old fire-eye","floresta de pinhaprata","moldavento"},sec={{t="O Propósito de uma Lâmina",b="Você recebeu a Lâmina de Luaprata dos Moldavento. Os moradores dizem que Old Fire-Eye caça por uma vasta área ao sul daqui, geralmente perto dos portões de Guilnéas. Lumina pede que você o encontre e use a lâmina para acabar com ele. A gratidão dos Moldavento depende disso."},{t="Depois da Caçada",b="Quando você retorna, Lumina agradece e diz que Banon pode descansar em paz. Então, ela imbui a lâmina ensanguentada com uma pequena parcela da magia de seu povo, na esperança de que os ventos a guiem bem."}},faq={{q="Quem está me pedindo para caçar Old Fire-Eye?",a="Lumina Windsinger pede que você cace Old Fire-Eye com a Lâmina de Luaprata.",al={"quem me enviou","tarefa de lumina","windsinger"}},{q="Onde posso encontrar Old Fire-Eye?",a="Os moradores dizem que Old Fire-Eye caça por uma vasta área ao sul de Lumina e costuma ficar perto dos portões de Guilnéas.",al={"localização de fire-eye","onde está old fire-eye","portões de guilnéas"}},{q="O que devo usar contra Old Fire-Eye?",a="Lumina pede que você use a Lâmina de Luaprata para acabar com Old Fire-Eye.",al={"lâmina contra fire-eye","arma de luaprata","qual arma"}},{q="Por que Lumina quer que Old Fire-Eye seja morto?",a="Lumina diz que os Moldavento ficarão gratos quando Old Fire-Eye estiver morto.",al={"por que matar fire-eye","por que caçá-lo","motivo de fire-eye"}},{q="Quem é Banon?",a="Lumina diz que Banon poderá descansar em paz depois que Old Fire-Eye for morto.",al={"quem é banon","banon em paz"}},{q="O que Lumina faz com a lâmina?",a="Lumina imbui a Lâmina de Luaprata ensanguentada com uma pequena parcela da magia de seu povo.",al={"magia da lâmina","lumina encanta a lâmina","magia dos ventos"}}},fp="12,175,17.261.0,14.186.1,38.74.0,30.100.0,39.64.0,40.71.0,13.64.0,35.89.0"}
P.entries["quest:95141"] = {n="Report to Rog'mar",s="Um Orc envia você a Rog'mar, um posto avançado nas disputadas Sendas do Rio. Apresente-se a Krom'rosh, cuja experiência tem ajudado o posto a resistir a repetidos ataques.",h="Um Orc envia você a Rog'mar, um posto avançado nas disputadas Sendas do Rio.",kw={"ataques","costa leste","krom'rosh","posto avançado","sendas do rio","rog'mar","pedregal"},sec={{t="Um posto resiste",b="As Sendas do Rio ficam a nordeste de Pedregal, ao longo da costa leste. Muitos tentaram conquistar essas terras, mas poucos conseguiram. Rog'mar é um pequeno posto avançado que sobreviveu a incontáveis ataques. Você é enviado para lá para se apresentar a Krom'rosh, um antigo aliado cuja experiência em batalha tem ajudado o posto a resistir."}},faq={{q="Onde fica Rog'mar?",a="Rog'mar fica nas Sendas do Rio, a nordeste de Pedregal, ao longo da costa leste.",al={"localização de rog'mar","onde fica rogmar","posto avançado de rog'mar"}},{q="A quem devo me apresentar?",a="Você deve se apresentar a Krom'rosh no posto avançado de Rog'mar.",al={"a quem se apresentar","quem é krom'rosh","kromrosh"}},{q="O que é Rog'mar?",a="Rog'mar é um pequeno posto avançado nas Sendas do Rio que tem resistido a incontáveis ataques.",al={"o que é rogmar","posto avançado das sendas do rio","pequeno posto avançado"}},{q="Por que Krom'rosh está em Rog'mar?",a="A experiência de Krom'rosh no combate a inimigos tem ajudado o posto avançado a resistir.",al={"por que kromrosh está lá","função de krom'rosh","quem comanda rogmar"}},{q="Como são as terras das Sendas do Rio?",a="As Sendas do Rio são terras disputadas ao longo da costa leste, a nordeste de Pedregal.",al={"sendas do rio","como são as sendas do rio","terras disputadas"}}},fp="17,157,18.302.0,17.78.0,22.54.0,16.81.0,28.70.0,38.84.0"}
P.entries["quest:95143"] = {n="Finding Tan'jani",s="Um viajante pede que você encontre seu irmão Tan'jani. As mensagens o situam ao sul de Loch Modan, e a mais recente aponta para Rog'mar, nas Sendas do Rio.",h="Um viajante pede que você encontre seu irmão Tan'jani.",kw={"carta manchada de sangue","loch modan","irmão desaparecido","sendas do rio","rog'mar","tan jani","tan'jani"},sec={{t="Um Irmão Desaparecido",b="O irmão de um viajante, Tan'jani, partiu em busca de algo desconhecido. Uma mensagem o situa em algum lugar ao sul de Loch Modan. Uma carta manchada de sangue menciona as Sendas do Rio e Rog'mar, mais ao sul, e o viajante pede que você o encontre lá."}},faq={{q="Quem é Tan'jani?",a="Tan'jani é o irmão do viajante que pede que você o encontre.",al={"tan'jani","tan jani","irmão desaparecido"}},{q="Onde Tan'jani foi mencionado pela última vez?",a="Uma carta manchada de sangue menciona as Sendas do Rio e Rog'mar, mais ao sul de Loch Modan.",al={"onde está tan'jani","localização de tan'jani","rog'mar"}},{q="O que Tan'jani estava procurando?",a="Tan'jani estava sempre à procura de algo, mas seu irmão não sabe o quê.",al={"o que ele procurava","tan'jani procurando","por que ele partiu"}},{q="O que dizem as mensagens?",a="Um viajante contou que encontrou Tan'jani em algum lugar ao sul de Loch Modan. Uma carta manchada de sangue menciona as Sendas do Rio e Rog'mar, mas quase toda ela está ilegível.",al={"mensagens de tan'jani","carta manchada de sangue","o que aconteceu com a carta"}}},fp="16,147,17.242.0,16.63.0,34.86.0,32.80.0,25.156.0"}
P.entries["quest:95144"] = {n="Overseas Delivery",s="Fizzgrimble pede que você leve uma caixa lacrada pelo mar até Friz Frazzlespark, nas Sendas do Rio. O conteúdo deve continuar sendo uma surpresa até chegar ao Porto Detonapavio.",h="Fizzgrimble pede que você leve uma caixa lacrada pelo mar até Friz Frazzlespark, nas Sendas do Rio.",kw={"fizzgrimble","friz frazzlespark","caixa misteriosa","entrega além-mar","porto detonapavio","sendas do rio","porto de bondebico"},sec={{t="Uma travessia cuidadosa",b="Fizzgrimble envia você para leste, em direção ao Porto de Bondebico, de onde um navio costuma atravessar o mar. A caixa vai para Friz Frazzlespark, no Porto Detonapavio, nas Sendas do Rio. Manuseie-a com cuidado; Fizzgrimble avisa para não abri-la nem sacudi-la."}},faq={{q="Para quem é a encomenda?",a="Friz Frazzlespark está esperando a caixa no Porto Detonapavio, nas Sendas do Rio.",al={"quem recebe a caixa","encomenda para friz frazzlespark"}},{q="Onde devo levar a caixa?",a="Leve-a até Friz Frazzlespark, no Porto Detonapavio, nas Sendas do Rio.",al={"destino da caixa","onde fica o porto detonavapio"}},{q="Onde posso encontrar uma passagem pelo mar?",a="Fizzgrimble recomenda seguir para leste até o Porto de Bondebico, de onde um navio costuma oferecer uma travessia segura.",al={"como atravessar","navio no porto de bondebico"}},{q="O que devo fazer com a caixa no caminho?",a="Mantenha a caixa fechada e evite incliná-la, sacudi-la ou fazer movimentos bruscos com ela.",al={"como carregar a caixa","posso abrir a encomenda"}},{q="O que tem dentro da caixa?",a="Friz Frazzlespark pede que você se vire enquanto abre a caixa, para manter o conteúdo em segredo.",al={"conteúdo da caixa","qual é a surpresa"}}},fp="17,178,18.262.0,23.81.0,30.67.0,40.101.0,43.85.0,25.98.0"}
P.entries["quest:95156"] = {n="Stuff 'Em and Stick 'Em",s="Ember precisa de feno da propriedade de Wheeler para consertar bonecos de treinamento desgastados. Os recrutas precisam de alvos resistentes para treinar para a batalha.",h="Ember precisa de feno da propriedade de Wheeler para consertar bonecos de treinamento desgastados.",kw={"ember","propriedade","feno","recrutas","stuff 'em and stick 'em","bonecos de treinamento","campo de treinamento","wheeler"},sec={{t="Alvos Desgastados",b="No campo de treinamento, Ember precisa de feno para consertar os bonecos usados pelos recrutas. O desgaste deles pode deixar os recrutas despreparados para a batalha. Há uma propriedade fora da fortaleza que pertence a Wheeler, e talvez ele tenha feno sobrando. Ember se oferece para compensá-lo pelos suprimentos que ele puder fornecer."},{t="Alvos Novos",b="Ember espera consertar vários alvos assim que o feno chegar. O treinamento dos recrutas depende de bonecos que resistam à prática."}},faq={{q="Por que Ember precisa de feno?",a="Ember precisa de feno para consertar bonecos de treinamento desgastados no campo de treinamento.",al={"feno para ember","por que feno","feno para bonecos de treinamento"}},{q="Quem é Wheeler?",a="Wheeler é o homem que administra a pequena propriedade fora da fortaleza, onde Ember espera conseguir feno sobrando.",al={"propriedade de wheeler","quem tem feno","homem da propriedade"}},{q="Por que os bonecos estão sendo consertados?",a="Os bonecos estão desgastados, e Ember teme que os recrutas fiquem despreparados para a batalha se eles não forem consertados.",al={"bonecos desgastados","alvos de treinamento quebrados","por que consertar os alvos"}},{q="Wheeler será pago pelo feno?",a="Ember diz que Wheeler será compensado se puder ceder alguns suprimentos.",al={"wheeler será pago","compensação pelo feno","pagamento pelos fardos"}},{q="O que Ember fará com o feno?",a="Ember planeja usar o feno para consertar vários alvos de treinamento imediatamente.",al={"para que serve o feno","consertar alvos","uso do feno"}}},fp="23,134,12.279.0,13.157.1,24.72.0,15.102.0,35.106.0,33.64.0,32.73.0"}
P.entries["quest:95161"] = {n="Lembre-se de que eu te amo",s="Lembre-se de que eu te amo é uma missão da Aliança que começa no Orfanato de Ventobravo e envia viajantes para as florestas sombrias da Floresta do Crepúsculo. Com a tarefa de entregar uma sombria Carta Manchada de Sangue, os aventureiros devem rastrear um órfão recém-adotado chamado Jeremy Tececórdio e sua mãe adotiva, Avette Fellwood.",h="Lembre-se de que eu te amo é uma missão da Aliança que começa no Orfanato de Ventobravo e envia viajantes...",kw={"avette fellwood","carta manchada de sangue","floresta do crepúsculo","jeremy tececórdio","remember that i love you","ventobravo","orfanato de ventobravo"},ang={["faction:Alliance"]="Levar lembranças de parentes caídos ou desaparecidos a órfãos adotados evidencia os contínuos custos pessoais do estado turbulento do reino.",["race:Human"]="Para os humanos de Ventobravo, essa tarefa une o coração relativamente seguro do reino aos assentamentos assombrados e esquecidos da Floresta do Crepúsculo."},sec={{t="Uma Mensagem para um Órfão",b="As crianças do Orfanato de Ventobravo carregam fardos pesados, tendo perdido suas famílias para guerras, dificuldades e o caos que assola o reino. Jeremy Tececórdio era um desses tutelados até ser adotado recentemente por uma mulher chamada Avette Fellwood. Embora a vida nas matas sombrias da Floresta do Crepúsculo seja repleta de perigos e trabalho árduo, as cuidadoras do orfanato acreditavam que isso lhe oferecia a chance de ter uma família em vez de continuar trancado na cidade."},{t="Uma Lembrança Sombria",b="A missão gira em torno de transportar uma Carta Manchada de Sangue destinada a Jeremy, enviada aos cuidados de Avette Fellwood. As informações conduzem os viajantes para o sul, passando pela segurança da Floresta de Elwynn e adentrando as sombras da Floresta do Crepúsculo. A natureza lúgubre do pacote sugere uma tragédia passada que perseguiu o jovem Jeremy para muito além dos portões de Ventobravo."}},faq={{q="Quem é Jeremy Tececórdio?",a="Jeremy Tececórdio é um jovem rapaz criado anteriormente no Orfanato de Ventobravo. Ele foi adotado recentemente por Avette Fellwood, deixando a cidade para viver e trabalhar nas terras sombrias da Floresta do Crepúsculo.",al={"jeremy","quem é jeremy","órfão jeremy"}},{q="Quem é Avette Fellwood?",a="Avette Fellwood é a recém-adotiva mãe de Jeremy, que reside na Floresta do Crepúsculo. As matronas de Ventobravo a consideram uma mulher doce, que provavelmente acolheu Jeremy para conseguir um par extra de mãos em suas tarefas diárias.",al={"avette","quem é avette","mãe adotiva"}},{q="O que é a Carta Manchada de Sangue?",a="A Carta Manchada de Sangue é um item de entrega sombrio destinado a Jeremy Tececórdio e entregue diretamente nas mãos de sua guardiã adotiva, Avette Fellwood, carregando ecos de violência ou tragédia.",al={"carta manchada de sangue","a carta","o que é a carta"}},{q="Onde encontro Avette Fellwood?",a="Avette Fellwood reside na Floresta do Crepúsculo, o território florestal escuro localizado diretamente ao sul da Floresta de Elwynn, do outro lado do rio.",al={"localização de avette fellwood","onde está avette","encontrar avette"}},{q="Por que Jeremy foi enviado para a Floresta do Crepúsculo?",a="Jeremy foi adotado no Orfanato de Ventobravo. Embora a Floresta do Crepúsculo seja uma terra perigosa e ameaçadora, suas cuidadoras acreditavam que viver com uma família e ajudar no trabalho honesto era melhor do que continuar sendo um órfão institucionalizado.",al={"por que floresta do crepúsculo","por que jeremy saiu de ventobravo","orfanato floresta do crepúsculo"}},{q="Qual facção pode fazer esta missão?",a="Esta missão é exclusiva da Aliança, originando-se na capital humana de Ventobravo e seguindo para o território controlado pela Aliança na Floresta do Crepúsculo.",al={"é da aliança","apenas aliança","missão da horda"}}},fp="24,136,23.349.0,12.253.1,26.146.0,23.196.0,33.150.0,32.101.0,32.173.0,34.125.0"}
P.entries["quest:95162"] = {n="Paletusk Harvesting",s="Na'zok pede que você reúna carne de paletusk perto de Bolder'ok. O rancho alimenta os ogros próximos e abastece Rog'mar enquanto a guerra avança.",h="Na'zok pede que você reúna carne de paletusk perto de Bolder'ok.",kw={"carne de javali","bolder'ok","na'zok","ogros","paletusk","coleta de paletusk","rancho","rog'mar"},sec={{t="Carne para o rancho",b="Na'zok precisa de mais carne no rancho perto de Bolder'ok, onde os ogros deixam Na'zok ficar enquanto a carne continuar chegando. Com o avanço da guerra, a necessidade de comida aumenta, e os ogros começam a ver Na'zok como a próxima refeição. Você deve reunir pedaços de carne de javali para os ogros famintos e Rog'mar."}},faq={{q="Quem está pedindo carne?",a="Na'zok pede que você reúna carne de javali perto de Bolder'ok para os ogros e Rog'mar.",al={"quem precisa de carne","pedido de na'zok","quem é na'zok"}},{q="Por que Na'zok precisa da carne?",a="O rancho é uma das poucas fontes de alimento de Na'zok, e os ogros deixam Na'zok ficar enquanto a carne continuar chegando.",al={"por que carne","por que reunir carne de javali","ogros famintos"}},{q="Quem é Rog'mar?",a="Rog'mar é um povoado, não uma pessoa. Na'zok quer que sobre carne suficiente para abastecê-lo.",al={"carne para rog'mar"}},{q="Onde está Na'zok?",a="Na'zok está perto de Bolder'ok.",al={"localização de na'zok","onde fica o rancho"}},{q="Que carne é necessária?",a="Na'zok pede pedaços de carne de javali de paletusk.",al={"carne de javali","carne de paletusk","pedaços de carne"}}},fp="19,126,18.294.0,23.77.0,30.106.0,15.87.0,16.25.0,20.50.0"}
P.entries["quest:95163"] = {n="Drive Them Back",s="Na'zok pede que você leve os Young Paletusks fugidos de volta à fazenda dele, perto de Bolder'ok. Os filhotes cruzaram o rio, e precisam voltar aos chiqueiros.",h="Na'zok pede que você leve os Young Paletusks fugidos de volta à fazenda dele, perto de Bolder'ok.",kw={"bolder'ok","filhotes fugidos","fazenda","gorgegut","na'zok","paletusk","porcos","young paletusks"},sec={{t="Os filhotes fugidos",b="A fazenda de Na'zok, perto de Bolder'ok, tem mais porcos soltos pelo vale do que nos chiqueiros. Gorgegut não tem sido um trabalhador rural ideal, embora mantenha os humanos afastados. Alguns Young Paletusks cruzaram o rio, e são pequenos demais para serem colhidos no campo. Na'zok lhe dá um pedaço de pau para levá-los de volta aos chiqueiros."}},faq={{q="Por que os filhotes saíram dos chiqueiros?",a="Alguns Young Paletusks fugiram da fazenda de Na'zok e cruzaram o rio.",al={"filhotes fugidos","porcos soltos","por que os porcos estão fora"}},{q="Quem é Gorgegut?",a="Gorgegut é trabalhador rural de Na'zok, embora Na'zok diga que ele deixa a desejar.",al={"gorgegut trabalhador rural","quem é gorgegut","homem da fazenda de porcos"}},{q="Por que levar os Young Paletusks de volta?",a="Os Young Paletusks são pequenos demais para serem colhidos no campo, então Na'zok quer que voltem à fazenda.",al={"devolver os filhotes","por que trazer os porcos de volta","young paletusk"}},{q="Onde fica a fazenda de Na'zok?",a="A fazenda de Na'zok fica perto de Bolder'ok.",al={"localização da fazenda de na'zok","fazenda perto de bolder'ok","onde fica a fazenda de porcos"}}},fp="15,148,19.313.0,38.70.0,16.78.0,35.106.0,23.32.0"}
P.entries["quest:95183"] = {n="Step One: Rock",s="Hamur, em Bolder'ok, quer pedras boas do rio próximo. Leve-as até ele para que possa fazer uma arma minúscula para uma criaturinha.",h="Hamur, em Bolder'ok, quer pedras boas do rio próximo.",kw={"bolder'ok","pedras boas","hamur","arma ogra","rio","arma minúscula"},sec={{t="O pedido de Hamur",b="Hamur, em Bolder'ok, diz que você é pequeno demais para empunhar uma boa arma ogra. Ele se oferece para fazer uma arma minúscula para você se trouxer pedras boas. Ele quer pedras do rio que fica fora de Bolder'ok, onde só as melhores servem."}},faq={{q="Quem é Hamur?",a="Hamur fica em Bolder'ok e se oferece para fazer uma arma minúscula para você se trouxer pedras boas.",al={"quem é hamur","quem quer pedras"}},{q="Onde encontro as pedras?",a="Hamur pede pedras boas do rio que fica fora de Bolder'ok.",al={"local das pedras","onde ficam as pedras"}},{q="Por que Hamur quer pedras?",a="Hamur diz que usará as pedras boas para fazer uma arma minúscula para uma criaturinha.",al={"por que pedras","para que servem as pedras"}},{q="Que tipo de pedras Hamur quer?",a="Hamur quer pedras boas do rio que fica fora de Bolder'ok; ele diz que nem toda pedra serve.",al={"pedras boas","quais pedras"}}},fp="14,119,15.217.0,13.87.0,26.59.0,26.80.0,35.92.0"}
P.entries["quest:95184"] = {n="The Sharpest of Blades",s="Ember Bladewhisper quer pedras de amolar para os recrutas de Farholde. Uma lâmina experiente pode fazer a diferença entre a vitória e a morte.",h="Ember Bladewhisper quer pedras de amolar para os recrutas de Farholde.",kw={"ember bladewhisper","farholde","recrutas","pedras de amolar","solid sharpening stones","campos de treinamento"},sec={{t="Lâminas para recrutas",b="Nos campos de treinamento de Farholde, Ember Bladewhisper percebe que os recrutas pouco sabem sobre a diferença entre uma espada de treino e uma lâmina de veterano bem cuidada. Pedem a você que leve pedras de amolar para ela, para que os recrutas aprendam o que significa ter um fio afiado."}},faq={{q="Quem precisa de pedras de amolar?",a="Ember Bladewhisper pede pedras de amolar nos campos de treinamento de Farholde.",al={"quem quer pedras","pedras de ember bladewhisper"}},{q="Por que Ember quer as pedras?",a="Ela quer que os recrutas entendam a diferença entre uma lâmina afiada e uma espada de treino.",al={"por que pedras de amolar","para que servem as pedras"}},{q="Onde devo levar as pedras?",a="Leve as pedras de amolar para Ember Bladewhisper nos campos de treinamento de Farholde.",al={"onde levar as pedras","pedras de farholde"}},{q="De que tipo de pedras Ember precisa?",a="Ember pede Solid Sharpening Stones.",al={"quais pedras","tipo de pedra"}}},fp="22,137,19.258.0,28.79.0,31.89.0,32.83.0,36.39.0"}
P.entries["quest:95189"] = {n="Brasão de Lordaeron",s="O Brasão de Lordaeron é uma relíquia desgastada que ostenta a marca régia do reino caído do norte. Encontradas em meio às ruínas desoladas de Capital City, tais relíquias tornaram-se escassas desde a queda do reino, e alguém em Ventobravo estaria muito interessado em pôr as mãos nesta.",h="O Brasão de Lordaeron é uma relíquia desgastada que ostenta a marca régia do reino caído do norte.",kw={"crest of lordaeron","heraldica","lady dena kennedy","lordaeron","reliquia","ruínas de lordaeron","ventobravo","clareiras de tirisfal"},ang={["faction:Alliance"]="O emblema de Lordaeron representa o pilar fundador da Aliança original, tornando sua recuperação uma vitória simbólica contra o apagamento total causado pelo Flagelo e pelos Renegados.",["race:Human"]="Para os humanos, em particular aqueles cujas famílias antes chamavam o norte de lar, o brasão é uma lembrança tocante do grandioso reino que outrora liderou a Aliança."},sec={{t="Uma Herança Despedaçada",b="Quando o Flagelo assolou o reino de Lordaeron, seus palácios, arquivos e orgulhosas insígnias foram em grande parte obliterados ou deixados para definhar sob a sombra de Cidade Baixa. Artefatos físicos sobreviventes que exibem o brasão real são extremamente raros. Recuperar um brasão intacto ou desgastado das ruínas do norte representa um pedaço tangível da história humana resgatado do esquecimento."},{t="Refúgio no Sul",b="Após a Terceira Guerra, milhares de refugiados do norte fugiram para o sul em direção ao Reino de Ventobravo, levando consigo apenas lembranças de sua terra natal. Em Ventobravo, Lady Dena Kennedy tem grande interesse em adquirir tais vestígios de Lordaeron, tornando relíquias como este brasão profundamente estimadas na capital do sul."}},faq={{q="O que é o Brasão de Lordaeron?",a="É um emblema heráldico desgastado que exibe a marca oficial de Lordaeron. Deixado para trás após o reino cair perante o Flagelo, é uma relíquia histórica valiosa para os sobreviventes humanos.",al={"crest of lordaeron","o que e crest of lordaeron","item crest of lordaeron"}},{q="Quem deseja o Brasão de Lordaeron?",a="O brasão é entregue a Lady Dena Kennedy, uma patrona aristocrática em Ventobravo que busca colecionar e preservar artefatos raros do reino caído do norte.",al={"quem recebe o brasao","onde levar crest of lordaeron","entregar brasao"}},{q="Onde o brasão foi encontrado?",a="Ele foi recuperado das Ruínas de Lordaeron em Clareiras de Tirisfal, a capital arruinada que hoje fica diretamente acima da fortaleza dos Renegados, Cidade Baixa.",al={"localizacao do brasao","brasao das ruinas","onde conseguir o brasao"}},{q="Por que os artefatos de Lordaeron são tão raros?",a="A queda rápida e catastrófica do reino durante a Terceira Guerra resultou no massacre sistemático de seu povo e na ruína de suas propriedades. Raríssimas relíquias de família sobreviveram ao Flagelo e à subsequente ascensão dos Renegados.",al={"por que reliquias de lordaeron sao raras","raridade de artefatos de lordaeron"}},{q="Por que Ventobravo se importa com as relíquias de Lordaeron?",a="Ventobravo acolheu levas de refugiados, cavaleiros e nobres que fugiram da devastação do norte. Preservar relíquias homenageia o reino irmão caído da Aliança e mantém viva a herança dos humanos do norte.",al={"por que ventobravo se importa","reliquias de lordaeron em ventobravo"}},{q="Quem é Lady Dena Kennedy?",a="Lady Dena Kennedy é uma nobre residente em Ventobravo que tem um interesse ativo em resgatar vestígios históricos e relíquias de família originárias de Lordaeron.",al={"lady dena kennedy","quem e dena kennedy"}}},fp="18,193,20.268.0,19.292.0,31.177.0,33.110.0,26.141.0,41.176.0,50.174.0,25.126.0"}
P.entries["quest:95195"] = {n="Insígnia ensanguentada",s="As Insígnia ensanguentadas são vestígios trágicos dos defensores caídos de Lordaeron, espalhadas entre as ruínas assoladas do reino. Ostentando os antigos brasões da Aliança, esses distintivos desgastados representam soldados cujas famílias fugiram para o sul, rumo a Ventobravo, durante a Terceira Guerra.",h="As Insígnia ensanguentadas são vestígios trágicos dos defensores caídos de Lordaeron, espalhadas entre as...",kw={"aliança","bloodied insignia","lordaeron","marcus jonas","refugiados","ruínas de lordaeron","ventobravo","terceira guerra"},ang={["class:Paladin"]="Muitos dos caídos na capital lutaram ao lado dos Cavaleiros do Punho de Prata; recuperar suas medalhas honra os irmãos e irmãs perdidos da sagrada ordem.",["faction:Alliance"]="Entregar essas insígnias ao General Marcus Jonas serve como um ato de dever e lembrança para com os soldados que deram suas vidas defendendo a Aliança original.",["race:Human"]="Para os humanos da Aliança, esses distintivos são lembranças solenes da queda do maior reino humano, conectando os refugiados que vivem em Ventobravo aos seus parentes caídos no norte."},sec={{t="Símbolos dos Caídos",b="Quando o Príncipe Arthas retornou para assolar Lordaeron com o Flagelo, suas grandiosas forças militares foram subjugadas e massacradas. Inúmeros soldados pereceram defendendo a Capital e as terras ao redor, deixando para trás poucos vestígios físicos além de armaduras enferrujadas e latão manchado de sangue. Essas antigas insígnias da Aliança pertenciam aos homens e mulheres que resistiram ao avanço dos mortos-vivos. Pisoteada no solo e nos escombros das ruínas, cada medalha é uma relíquia da última e desesperada resistência do reino."},{t="Um Mensageiro para os Exilados",b="Muitos sobreviventes de Lordaeron fugiram para o sul através do mar, estabelecendo-se como refugiados em Ventobravo. Décadas de aliança e laços de parentesco unem os dois reinos humanos, fazendo com que muitos no sul anseiem por respostas sobre seus entes queridos desaparecidos. O General Marcus Jonas, comandante da guarda da cidade de Ventobravo, recebe a custódia dessas insígnias ensanguentadas para que a memória dos defensores do norte seja preservada e suas famílias sobreviventes possam finalmente conhecer seu destino."}},faq={{q="O que são as Insígnia ensanguentadas?",a="São medalhas militares usadas por soldados do Reino de Lordaeron que lutaram e morreram sob o estandarte da Aliança durante a Terceira Guerra.",al={"item bloodied insignia","o que é esta insígnia","história da insígnia"}},{q="Onde essas insígnias são encontradas?",a="Elas são recuperadas por todas as Ruínas de Lordaeron, em Clareiras de Tirisfal, onde os defensores do reino fizeram sua última resistência contra o Flagelo.",al={"onde caem as insígnias","localização da insígnia","distintivos das ruínas de lordaeron"}},{q="Por que o General Marcus Jonas quer essas insígnias?",a="O General Marcus Jonas supervisiona a defesa em Ventobravo, onde inúmeros refugiados do norte agora habitam. Ele reúne esses vestígios para que os sacrifícios dos guerreiros de Lordaeron sejam honrados e seus parentes vivos no sul possam encontrar paz.",al={"quem é marcus jonas","por que entregar para ventobravo","insígnia de marcus jonas"}},{q="Por que os soldados de Lordaeron usavam insígnias da Aliança?",a="A Aliança original foi forjada em Lordaeron sob o comando do Rei Terenas Menethil II para derrotar a Horda Antiga. Lordaeron foi o coração e líder da Aliança de Lordaeron durante toda a Segunda e a Terceira Guerra.",al={"brasão da aliança de lordaeron","distintivo da aliança de lordaeron"}},{q="O que aconteceu com os soldados que usavam essas medalhas?",a="Eles foram mortos durante a Terceira Guerra, quando o Príncipe Arthas Menethil traiu o reino, assassinou seu pai e libertou o Flagelo dos mortos-vivos sobre a capital.",al={"o que matou os soldados","destino dos soldados de lordaeron"}},{q="Ainda existem parentes vivos desses soldados?",a="Sim. Milhares de cidadãos e soldados evacuaram Lordaeron durante a peste e as invasões do Flagelo, encontrando por fim santuário no Reino de Ventobravo.",al={"refugiados de lordaeron em ventobravo","quem sente falta destes soldados"}}},fp="17,169,20.402.0,26.384.0,32.119.0,32.141.0,43.191.0,55.176.0,52.147.0,51.144.0"}
P.entries["quest:952"] = {n="Bosque dos Ancientes",s="Bosque dos Ancientes é uma missão de entrega da Aliança que leva aventureiros de Darnassus até Costa Negra, do outro lado do mar. Encarregado pelo Arquidruida Fandral Guenelmo, o mensageiro leva uma carta a Onu, um venerável Anciente da Tradição que vive ao sul de Auberdine.",h="Bosque dos Ancientes é uma missão de entrega da Aliança que leva aventureiros de Darnassus até Costa Negra...",kw={"anciente da tradição","auberdine","círculo cenariano","costa negra","darnassus","fandral guenelmo","bosque dos ancientes","onu","clareira do oráculo"},ang={["class:Druid"]="Levar mensagens entre o Arquidruida de Darnassus e Onu apresenta aos jovens druidas as diferenças de temperamento entre os anciãos do Círculo Cenariano, contrastando a determinação de Guenelmo com a paciência serena de um Anciente da Tradição.",["faction:Alliance"]="Para os campeões da Aliança que concluem suas tarefas em Darnassus, essa entrega oferece um motivo para conhecer as rotas de hipogrifos e explorar o território costeiro de Costa Negra.",["race:NightElf"]="Essa tarefa marca a transição natural do abrigo de Teldrassil para as terras selvagens do continente de Kalimdor, destacando o contraste filosófico entre Fandral Guenelmo e os ensinamentos de Malfurion Tempesfúria."},sec={{t="Deixando os galhos para trás",b="Depois de ajudar a resolver questões relativas à Clareira do Oráculo, no alto de Teldrassil, os aventureiros são convocados de forma brusca para outra tarefa pelo Arquidruida Fandral Guenelmo. Sem tolerar a ociosidade, Guenelmo encarrega o mensageiro de levar um comunicado urgente pelo mar até as florestas ancestrais de Costa Negra, instruindo-o a embarcar em um hipogrifo na cidade."},{t="Uma diferença de paciência",b="Ao chegar a Costa Negra e viajar para o sul de Auberdine, até o Bosque dos Ancientes, o mensageiro entrega a carta a Onu. O imponente Anciente da Tradição recebe a correspondência com serena reflexão, observando discretamente a impaciência incessante de Guenelmo. Para Onu e os antigos guardiões da floresta, tudo acontece em seu devido tempo: uma sabedoria tranquila e duradoura que Shan'do Malfurion Tempesfúria compreendia, mas que falta claramente a Guenelmo."}},faq={{q="Quem inicia a missão Bosque dos Ancientes?",a="O Arquidruida Fandral Guenelmo oferece a missão no Enclave Cenariano, em Darnassus, depois que você conclui sua tarefa anterior relativa à Clareira do Oráculo.",al={"quem oferece bosque dos ancientes","quem dá a missão bosque dos ancientes","missão de fandral guenelmo"}},{q="Onde fica o Bosque dos Ancientes?",a="O Bosque dos Ancientes fica no continente, em Costa Negra, diretamente ao sul do porto costeiro de Auberdine.",al={"localização do bosque dos ancientes","onde fica o bosque dos ancientes","localização de onu"}},{q="Quem é Onu?",a="Onu é um sábio e venerável Anciente da Tradição que vive em Costa Negra. Como protetor e guardião da sabedoria da natureza, recebe correspondência da liderança druídica de Darnassus.",al={"quem é onu","onu costa negra","onu anciente da tradição"}},{q="Como chegar a Costa Negra saindo de Teldrassil?",a="Os viajantes costumam descer de Darnassus até a Aldeia de Rut'theran e pegar um hipogrifo pelo mar até o porto de Auberdine, em Costa Negra.",al={"como chegar a costa negra","viajar para auberdine","hipogrifo para costa negra"}},{q="Por que Onu menciona Shan'do Tempesfúria?",a="Ao receber a carta, Onu comenta a pressa inquieta do Arquidruida Guenelmo. Ele observa que a floresta segue seu próprio ritmo, uma paciência atemporal que Shan'do Malfurion Tempesfúria compreendia e respeitava.",al={"comentário de onu sobre malfurion","referência a shan'do tempesfúria","por que mencionar shan'do"}},{q="Quais missões vêm antes desta?",a="Esta missão é a etapa final de uma sequência curta de três partes que começa com A Clareira Encantada, segue com Teldrassil e termina enviando você para Costa Negra.",al={"pré-requisitos de bosque dos ancientes","série de missões do bosque dos ancientes","missões anteriores a onu"}}},fx={["00893f03"]={q="Por que o Arquidruida Fandral Guenelmo quer que esta mensagem seja entregue a Onu?",a="Fandral Guenelmo está ansioso para manter uma comunicação estreita com os protetores antigos do outro lado do mar, em Kalimdor. Onu, um Ancestral do Saber enraizado em Costa Negra, estava aguardando notícias do Arquidruida sobre os assuntos em Teldrassil. Agora que Fandral recebeu os últimos relatórios da Clareira do Oráculo, ele está impaciente para transmitir suas descobertas e instruções sem demora, avançando com seus planos para os elfos noturnos.",al={"por que enviar mensagem a onu","motivo de fandral sobre o bosque dos ancientes","por que fandral precisa disso entregue"}},["658e120a"]={q="Por que Fandral Guenelmo escolhe você para entregar sua mensagem?",a="Tendo visto você levar notícias da Clareira do Oráculo para Darnassus, Fandral imagina que você já é capaz de realizar recados delicados através de distâncias. Em vez de desviar emissários Cenarianos experientes ou Sentinelas de seus deveres, ele simplesmente coloca um mensageiro comprovado em serviço para levar sua missiva para Costa Negra.",al={"por que eu, mensagem de fandral","por que enviar o jogador a onu","por que não enviar uma sentinela"}}},fp="21,226,18.230.0,22.341.0,43.135.0,43.109.0,11.160.0,43.126.0,39.192.0,33.143.0"}
P.entries["quest:95204"] = {n="Crest of Lordaeron",s="O Crest of Lordaeron é um artefato histórico desgastado que traz o emblema do reino caído. Como poucos tesouros desse tipo sobreviveram à destruição causada pelo Flagelo, ele é entregue a Urraca Convulserpe na Cidade Baixa para ajudar a preservar o passado dos Renegados.",h="O Crest of Lordaeron é um artefato histórico desgastado que traz o emblema do reino caído.",kw={"crest of lordaeron","renegados","lordaeron","urraca convulserpe","relíquia","cidade baixa"},ang={["faction:Horde"]="Ajudar arquivistas dos Renegados na Cidade Baixa ajuda a preservar o legado material de Lordaeron em meio às ruínas deixadas pelo Flagelo.",["race:Undead"]="Como antigos cidadãos de Lordaeron, os Renegados valorizam as relíquias sobreviventes de seu reino caído como raros remanescentes de suas vidas passadas e de seu patrimônio."},sec={{t="Um Símbolo Sobrevivente do Reino Caído",b="O reino de Lordaeron foi despedaçado durante a Terceira Guerra, deixando pouco para trás além de cinzas, ruínas e a desolação do Flagelo. Como grande parte da cultura material do reino foi aniquilada, insígnias e emblemas sobreviventes como o Crest of Lordaeron são excepcionalmente raros. Para os Renegados que habitam sob as ruínas da Capital City, esses objetos sobreviventes são elos físicos preciosos com a civilização à qual outrora pertenceram."},{t="Preservando o Patrimônio dos Renegados",b="Quando recuperado em outras partes do mundo, o brasão desgastado é entregue a Urraca Convulserpe na Cidade Baixa. Urraca verifica sua autenticidade — chegando a testar o metal com uma mordida — antes de confirmá-lo como uma relíquia autêntica e quase intacta de sua terra natal. Para Urraca e os arquivistas Renegados, cada peça resgatada ajuda a recompor uma história que o Flagelo tentou apagar por completo."}},faq={{q="O que é o Crest of Lordaeron?",a="O Crest of Lordaeron é um emblema desgastado que traz a marca do reino humano caído. Como pouquíssimas relíquias físicas sobreviveram à destruição do Flagelo, é uma peça de história inestimável para aqueles que tentam preservar o legado de Lordaeron.",al={"o que é crest of lordaeron","missão crest of lordaeron","item brasão"}},{q="Quem quer o brasão na Cidade Baixa?",a="O brasão é levado a Urraca Convulserpe, que vive na Cidade Baixa. Urraca inspeciona cuidadosamente e protege os artefatos recuperados ligados ao antigo reino.",al={"quem recebe o brasão","onde entregar o brasão","entrega do brasão cidade baixa"}},{q="Por que Urraca Convulserpe morde o brasão?",a="Ao receber o brasão, Urraca Convulserpe o morde para verificar sua autenticidade e composição material antes de declará-lo uma relíquia genuína e quase intacta de Lordaeron.",al={"por que morder o brasão","oran morde brasão"}},{q="Por que os Renegados valorizam relíquias de Lordaeron?",a="Os Renegados são os remanescentes mortos-vivos da antiga população de Lordaeron. Apesar da condição de mortos-vivos e de sua nova lealdade, relíquias de sua terra natal destruída representam elos tangíveis com sua história e identidade.",al={"por que renegados se importam com lordaeron","relíquias dos renegados"}},{q="O que acontecerá com o brasão após ele ser entregue?",a="Urraca Convulserpe fica responsável pelo brasão para garantir que ele seja mantido em segurança, tratando-o como um precioso tesouro histórico que ajuda a restaurar e recordar o legado de seu reino.",al={"o que acontece com o brasão","preservação do brasão"}},{q="Quão raras são as relíquias sobreviventes de Lordaeron?",a="Emblemas e relíquias físicas anteriores à Terceira Guerra são excepcionalmente escassos. A maioria dos símbolos de Lordaeron foi destruída, saqueada ou corrompida quando Arthas e o Flagelo assolaram o reino.",al={"o brasão é raro","quantos brasões restam"}}},fp="18,148,40.264.0,28.278.0,31.183.0,33.113.0,41.137.0,46.153.0,52.134.0,45.150.0"}
P.entries["quest:95212"] = {n="Never Saddle on Quality",s="Never Saddle on Quality é uma tarefa da Aliança centrada no Rancho Ambarmanso, em Dun Morogh. Tratadores precisam de peles pristinas de leopardo-das-montanhas para confeccionar selas quentes para carneiros de montaria destinados a reforçar a expedição de Alterac. O esforço garante que montarias e cavaleiros possam suportar o frio congelante das montanhas do norte.",h="Never Saddle on Quality é uma tarefa da Aliança centrada no Rancho Ambarmanso, em Dun Morogh.",kw={"alterac","expedição de alterac","rancho ambarmanso","dun morogh","peles de leopardo","never saddle on quality","peles pristinas de leopardo","carneiros","selas"},ang={["class:Hunter"]="A tarefa convoca rastreadores e caçadores habilidosos a buscarem os leopardos-das-montanhas mais ferozes de Dun Morogh para garantir peles pristinas.",["faction:Alliance"]="Os esforços de criação de carneiros do Rancho Ambarmanso fornecem diretamente reforços de montarias para as forças da Aliança que operam nas alturas congelantes de Alterac.",["race:Dwarf"]="Os resistentes carneiros-das-montanhas de Dun Morogh são montarias anãs emblemáticas, e os criadores do Rancho Ambarmanso se recusam a equipá-los com equipamento inferior."},sec={{t="Montando a Expedição",b="No Rancho Ambarmanso, em Dun Morogh, tratadores estão preparando um novo grupo de robustos carneiros-das-montanhas para reforçar a expedição da Aliança que opera em Alterac. No entanto, os preparativos foram interrompidos devido à escassez de material adequado necessário para confeccionar selas duráveis e resistentes ao frio para as feras."},{t="Calor para as Passagens Altas",b="Para suportar o congelamento implacável das Montanhas de Alterac, as montarias da expedição exigem um isolamento espesso e de alta qualidade. Caçadores são enviados aos despenhadeiros orientais para rastrear os maiores e mais ferozes leopardos-das-montanhas de Dun Morogh e recuperar suas peles pristinas, garantindo que as forças da Aliança recebam equipamentos feitos para sobreviver às passagens altas."}},faq={{q="O que é Never Saddle on Quality?",a="Never Saddle on Quality é uma tarefa baseada no Rancho Ambarmanso, em Dun Morogh. Um criador precisa de peles de leopardo de alta qualidade para confeccionar selas resistentes e quentes para um grupo de carneiros que estão sendo preparados como reforços para a expedição de Alterac.",al={"o que é esta missão","missão never saddle on quality","o que é never saddle on quality"}},{q="Por que peles de leopardo são necessárias?",a="As peles são necessárias para confeccionar selas duráveis e quentes para as montarias da expedição. Os leopardos-das-montanhas de Dun Morogh fornecem uma pelagem espessa e isolante, adequada para proteger cavaleiros e feras contra o frio cortante das montanhas de Alterac.",al={"por que peles de leopardo","para que servem as peles","por que peles pristinas"}},{q="Para onde os carneiros estão sendo enviados?",a="As montarias estão destinadas às forças da Aliança envolvidas na expedição de Alterac. Com o clima severo e as operações em andamento nas passagens altas, carneiros de montaria bem equipados são um apoio essencial.",al={"para onde vão os carneiros","quem recebe os carneiros","reforços de alterac"}},{q="Qual é o papel do Rancho Ambarmanso nisso?",a="O Rancho Ambarmanso está localizado nas colinas nevadas de Dun Morogh, a leste de Kharanos. Ele serve como o principal local de criação e treinamento para os carneiros-das-montanhas dos anões.",al={"onde fica o rancho ambarmanso","localização do rancho ambarmanso"}},{q="Onde os leopardos habitam?",a="Os ferozes leopardos-das-neves habitam as cristas e despenhadeiros nevados a leste do Rancho Ambarmanso, em Dun Morogh, onde os caçadores devem rastrear as maiores feras para recuperar couros pristinos.",al={"onde encontrar leopardos","onde estão os leopardos dun morogh"}},{q="Por que a proteção contra o clima frio é tão importante para a expedição?",a="O reino e os picos de Alterac são notoriamente congelantes e açoitados pelo vento. Sem material grosso e de alta qualidade para as selas, montarias e cavaleiros correm risco de congelamento e exaustão no terreno montanhoso.",al={"alterac é frio","por que selas quentes"}}},fp="23,229,23.201.0,26.290.0,32.198.0,29.181.0,30.175.0,37.125.0,27.157.0,63.166.0"}
P.entries["quest:95213"] = {n="Stolen Blasting Powder",s="Stolen Blasting Powder trata de um barril de explosivo perigoso e vazio descoberto entre troggs perto da Pedreira Gol'Bolar. Levar o recipiente desaparecido ao Mestre da Pedreira Thesten expõe uma perigosa falha na segurança da pedreira e nos depósitos de explosivos.",h="Stolen Blasting Powder trata de um barril de explosivo perigoso e vazio descoberto entre troggs perto da...",kw={"pólvora de detonação","dun morogh","barril de pólvora vazio","pedreira gol'bolar","barril de pólvora","mestre da pedreira thesten","stolen blasting powder","thesten","troggs"},ang={["faction:Alliance"]="Proteger as linhas de suprimento e postos avançados de mineração de Dun Morogh contra incursões de troggs é essencial para as operações da Aliança por toda Khaz Modan.",["profession:Engineering"]="Pólvora de detonação é um material volátil perigoso; engenheiros entendem melhor do que ninguém a destruição que troggs poderiam causar com explosivos não autorizados.",["profession:Mining"]="As operações da pedreira dependem de demolições controladas para extrair pedra, mas barris de pólvora desaparecidos sinalizam grave perigo dentro dos fossos de escavação.",["race:Dwarf"]="A Pedreira Gol'Bolar fornece pedras e recursos vitais para Altaforja, tornando a segurança de seus explosivos de mineração uma preocupação urgente para qualquer anão."},sec={{t="Uma Descoberta Perigosa",b="Um barril vazio estampado com avisos de perigo grave revela que pólvora de detonação perigosa escapou de mãos autorizadas na Pedreira Gol'Bolar. Tais explosivos são estritamente reservados para detonações controladas na pedreira sob a autorização direta do mestre da pedreira. Encontrar o barril entre troggs hostis indica que o local de escavação enfrenta uma ameaça muito mais volátil do que interrupções rotineiras de trabalho."},{t="O Alarme do Mestre da Pedreira",b="Devolver o recipiente vazio ao Mestre da Pedreira Thesten confirma os piores temores dos feitores anões. Thesten fica pálido ao ver o barril, percebendo que a pólvora de detonação desaparecida já foi esvaziada e manuseada pelos troggs subterrâneos que infestam a área. A descoberta deixa a liderança da pedreira correndo para avaliar o que as criaturas pretendem explodir a seguir."}},faq={{q="O que é Stolen Blasting Powder?",a="Stolen Blasting Powder é uma missão iniciada ao descobrir um barril de pólvora de detonação vazio estampado com avisos de perigo nas mãos de troggs perto da Pedreira Gol'Bolar. Ela alerta o Mestre da Pedreira Thesten sobre o roubo de suprimentos de mineração voláteis.",al={"o que é stolen blasting powder","missão barril de pólvora","história do barril de pólvora vazio"}},{q="Quem deve receber o barril de pólvora vazio?",a="O barril de pólvora vazio deve ser levado diretamente ao Mestre da Pedreira Thesten, que supervisiona as operações na Pedreira Gol'Bolar em Dun Morogh.",al={"onde levar o barril","quem é thesten","localização do mestre da pedreira"}},{q="Por que a pólvora de detonação roubada é perigosa?",a="O barril traz claramente avisos de autorização do mestre da pedreira e continha pólvora de detonação perigosa. Troggs possuindo ou detonando explosivos pesados ameaçam toda a escavação da pedreira e os assentamentos próximos.",al={"por que a pólvora é perigosa","troggs com explosivos","por que troggs têm pólvora"}},{q="O que é a Pedreira Gol'Bolar?",a="A Pedreira Gol'Bolar é um local de escavação dos anões situado em Dun Morogh, responsável pela extração de pedras e minerais para Altaforja.",al={"onde fica gol bolar","localização da pedreira","gol bolar dun morogh"}},{q="Por que o Mestre da Pedreira Thesten fica pálido?",a="Ao ver o barril vazio, o Mestre da Pedreira Thesten fica visivelmente pálido e pergunta onde ele foi encontrado, reconhecendo imediatamente que o conteúdo perigoso já caiu em mãos de troggs hostis.",al={"por que thesten fica pálido","reação de thesten","o que thesten diz"}},{q="O que os troggs estão fazendo perto da Pedreira Gol'Bolar?",a="Troggs infestaram as partes inferiores e os arredores da Pedreira Gol'Bolar, perturbando os mineradores anões e saqueando equipamentos e pólvora explosiva do local de escavação.",al={"há troggs na pedreira","infestação de troggs em dun morogh","por que troggs estão pegando pólvora"}}},fp="22,191,21.331.0,24.279.1,31.192.0,40.119.0,44.169.0,25.107.0,40.168.0,44.164.0"}
P.entries["quest:95214"] = {n="Stolen Blasting Powder",s="Stolen Blasting Powder é uma missão na Pedreira Gol'Bolar, em Dun Morogh, onde os aventureiros devem recuperar munições desaparecidas. Troggs primitivos fugiram com pólvora explosiva suficiente para nivelar uma ala inteira de uma fortaleza, forçando o Quarrymaster Thesten a recrutar ajuda discreta antes que ocorra uma catástrofe.",h="Stolen Blasting Powder é uma missão na Pedreira Gol'Bolar, em Dun Morogh, onde os aventureiros devem...",kw={"pólvora de detonação","dun morogh","explosivos","pedreira gol'bolar","altaforja","rei magni","mestre de pedreira thesten","thesten","troggs"},ang={["faction:Alliance"]="As rotas de suprimentos e as obras de pedra de Dun Morogh são vitais para o reduto montanhoso da Aliança. Manter a paz e vigiar munições perigosas garante a segurança da Sala do Trono na vizinha Altaforja.",["profession:Mining"]="A pólvora de detonação é uma ferramenta indispensável para desbastar rochas e abrir veios em escavações profundas, mas manuseá-la exige disciplina — perder barris inteiros para habitantes selvagens das cavernas é o pesadelo de qualquer mestre de pedreira.",["race:Dwarf"]="A Pedreira Gol'Bolar abastece o trabalho em pedra e os esforços de escavação de Altaforja. Permitir que troggs subterrâneos transformem explosivos de mineração em armas bem diante da porta do Rei Magni é uma falha de segurança humilhante para qualquer supervisor anão."},sec={{t="Um carregamento desaparecido",b="Na Pedreira Gol'Bolar, em Dun Morogh, as operações dos anões dependem fortemente de pesadas cargas de detonação para quebrar pedras e abrir veios profundos. No entanto, a segurança falhou quando troggs primitivos à espreita nos penhascos próximos conseguiram fugir com uma remessa inteira de pólvora de detonação de alta qualidade. O Quarrymaster Thesten viu-se obrigado a correr para encontrar mãos capazes antes que o bando de ladrões provocasse uma detonação acidental."},{t="Um barril de pólvora nos penhascos",b="O volume total do material desaparecido é estarrecedor: Thesten observa que o barril continha força explosiva suficiente para transformar a grandiosa sala do trono do Rei Magni Barbabronze em um pátio a céu aberto. Os troggs levaram o saque volátil para o leste, em direção aos seus acampamentos rudimentares nas colinas. Deixados por conta própria, seria apenas uma questão de tempo até que os brutos descobrissem o fogo ou batessem pedra contra pedra gerando faíscas."},{t="Resolução silenciosa",b="Assim que as cargas roubadas são arrancadas dos troggs e devolvidas em segurança ao depósito da pedreira, Thesten solta um profundo suspiro de alívio. O mestre da pedreira recompensa The Adventurer com um pedido discreto para não mencionar o pequeno incidente a ninguém."}},faq={{q="Quem é o Quarrymaster Thesten?",a="O Quarrymaster Thesten supervisiona as operações de escavação na Pedreira Gol'Bolar, em Dun Morogh. Responsável pela segurança e produtividade do local de escavação, ele se vê em uma situação embaraçosa depois que um enorme estoque de pólvora de detonação industrial desaparece sob sua supervisão.",al={"quem é thesten","mestre de pedreira thesten","quem dá esta missão"}},{q="Onde a pólvora de detonação roubada pode ser encontrada?",a="A pólvora foi levada pelos troggs que infestam os penhascos e tocas imediatamente a leste da Pedreira Gol'Bolar. Os aventureiros são enviados a esses afloramentos rochosos para recuperar os barris e sacos voláteis das criaturas antes que ocorra um desastre.",al={"onde fica stolen blasting powder","localização dos troggs","localização da pólvora"}},{q="Por que os troggs roubaram a pólvora de detonação?",a="Os troggs são criaturas primitivas e subterrâneas, movidas por astúcia básica e agressividade territorial. Embora tenham saqueado os barris de pólvora dos trabalhadores da pedreira, o Quarrymaster Thesten teme que até mesmo experimentos desajeitados possam levá-los a acidentalmente detonar os explosivos.",al={"por que troggs roubam pólvora","o que troggs querem com pólvora"}},{q="Quão perigosa é a pólvora de detonação roubada?",a="De acordo com o Quarrymaster Thesten, o barril desaparecido continha pólvora explosiva volátil suficiente para transformar a sala do trono do Rei Magni em um pátio a céu aberto. Se detonada de uma só vez na pedreira fechada ou nas cavernas, a força seria devastadora.",al={"quão poderosa é a pólvora","pólvora na sala do trono de magni","a pólvora é perigosa"}},{q="Por que o Quarrymaster Thesten quer que o incidente seja mantido em segredo?",a="Quando você devolve a pólvora, Thesten paga você e pede que não mencione este pequeno incidente a ninguém. Ele não diz o motivo, mas perder tanto explosivo para os troggs é claramente algo que ele prefere manter em segredo.",al={"por que manter em segredo","segredo de thesten","não mencione o incidente"}},{q="O que é a Pedreira Gol'Bolar?",a="A Pedreira Gol'Bolar é um proeminente local de escavação dos anões no leste de Dun Morogh, responsável pela extração de pedra para projetos de construção e engenharia em todo o reino. Seus poços profundos enfrentam regularmente pragas subterrâneas, como troggs que emergem da rocha.",al={"o que é gol bolar","pedreira gol'bolar","onde fica golbolar"}}},fp="22,183,19.282.0,25.250.0,16.202.1,28.188.0,46.166.0,45.194.0,44.189.0,59.199.0,25.191.0"}
P.entries["quest:95216"] = {n="The New Plague",s="The New Plague é uma iniciativa de pesquisa realizada por Theodore Griffs no Boticarium da Cidade Baixa. Investigando relatos de um artrópode letal nas ruínas acima, cujo veneno consome até mesmo carne de morto-vivo, Griffs busca analisar e fazer engenharia reversa das toxinas mortais do organismo.",h="The New Plague é uma iniciativa de pesquisa realizada por Theodore Griffs no Boticarium da Cidade Baixa.",kw={"boticarium","icor","ruínas de lordaeron","the new plague","theodore griffs","cepa tóxica","cidade baixa","witherfang"},ang={["faction:Horde"]="Embora a Horda tolere os Renegados como aliados táticos nos Reinos do Leste, os sinistros experimentos biológicos preparados no Boticarium frequentemente causam inquietação entre os membros mais honrados.",["race:Undead"]="A Real Sociedade de Boticários busca incessantemente toxinas capazes de ferir tanto os vivos quanto os mortos para assegurar a supremacia dos Renegados e proteger sua jovem nação."},sec={{t="A Ambição do Boticário",b="Nos recessos úmidos do Boticarium, a Real Sociedade de Boticários reúne continuamente agentes virulentos de toda Azeroth. Theodore Griffs, um de seus dedicados pesquisadores, rastreia feras exóticas e contaminantes mortais para abastecer a inovação alquímica dos Renegados. Ouvindo rumores de uma criatura peçonhenta rondando a pedra despedaçada acima, Griffs envia aventureiros para adquirir uma amostra viável antes que a oportunidade escape."},{t="Uma Toxina que Dissolve Carne",b="O alvo da pesquisa é Witherfang, um artrópode peçonhento que espreita as ruínas da superfície de Lordaeron. Seu veneno possui a rara e aterrorizante qualidade de decompor não apenas tecido vivo, mas também carne morta e preservada. Para um boticário trabalhando para aprimorar a guerra biológica e proteger o reino dos Renegados, descobrir como tal toxina ignora a resistência necrótica oferece um conhecimento químico inestimável."},{t="Engenharia Reversa do Icor",b="Embora Griffs expresse frustração quando os aventureiros destroem Witherfang em vez de capturá-lo vivo, o icor coletado fornece material suficiente para análise. Ao decompor os fluidos corporais da criatura, o boticário pretende fazer engenharia reversa dos mecanismos virulentos do veneno, garantindo que até mesmo um artrópode esmagado contribua para a crescente destreza química da Cidade Baixa."}},faq={{q="Quem é Theodore Griffs?",a="Theodore Griffs é um pesquisador boticário que atua no Boticarium na Cidade Baixa. Ele investiga toxinas potentes e espécimes exóticos para sintetizar compostos para os Renegados, demonstrando pouca consideração por qualquer um que não saiba apreciar o delicado ofício alquímico.",al={"quem dá the new plague","theodore griffs","quem é theodore griffs"}},{q="O que é Witherfang?",a="Witherfang é um artrópode letal e peçonhento encontrado à espreita nas Ruínas de Lordaeron, acima da Cidade Baixa. Ele produz uma toxina extraordinariamente corrosiva, capaz de dissolver até mesmo a resistente carne de morto-vivo.",al={"o que é witherfang","onde fica witherfang","artrópode das ruínas de lordaeron"}},{q="Por que Theodore Griffs quer o veneno de Witherfang?",a="Theodore Griffs busca estudar o veneno de Witherfang para determinar como suas toxinas corroem a carne de morto-vivo, esperando fazer engenharia reversa da substância em cepas potentes para o arsenal alquímico dos Renegados.",al={"o que theodore quer com witherfang","por que coletar a cepa altamente tóxica"}},{q="Por que Theodore Griffs fica chateado quando você retorna?",a="Theodore Griffs esperava que o espécime fosse mantido intacto ou cuidadosamente extraído, em vez de morto sumariamente. Embora irritado com a morte de Witherfang, ele ainda conseguiu recuperar icor residual suficiente dos restos mortais para estudar suas propriedades.",al={"por que theodore ficou zangado","estraguei a amostra"}},{q="Qual é o propósito do Boticarium?",a="O Boticarium serve como o centro de pesquisas da Real Sociedade de Boticários sob Lordaeron. Descrito como o bairro mais vital da Cidade Baixa, ele é dedicado a testar cepas virulentas, preparar armas alquímicas e fazer experimentos em criaturas exóticas.",al={"propósito do boticarium","por que o boticarium é importante"}},{q="Como Theodore acredita que as cepas virulentas são melhor transmitidas?",a="Segundo Theodore Griffs, o vetor mais potente e confiável para a transmissão virulenta é sempre através da introdução direta na corrente sanguínea.",al={"como o veneno é transmitido","método de transmissão"}}},fp="14,171,25.338.0,24.301.0,29.280.1,23.260.0,19.139.0,49.156.0,45.172.0,40.236.0,64.109.0"}
P.entries["quest:95217"] = {n="The Quarry's Smith",s="The Quarry's Smith é um acordo oferecido por Frast Dokner, um artesão em atividade estabelecido em um acampamento de pedreira. Isolado sem a entrega de suprimentos prevista, o ferreiro recorre a viajantes dispostos a reunir metal bruto e couro resistente para reparos essenciais no acampamento. Em troca dos materiais necessários, Dokner compartilha técnicas práticas de ferraria com aspirantes a metalúrgicos.",h="The Quarry's Smith é um acordo oferecido por Frast Dokner, um artesão em atividade estabelecido em um...",kw={"ferraria","barras de cobre","dun morogh","anão","frast dokner","pedreira gol'bolar","altaforja","the quarry's smith","couros de javali reforçados"},ang={["faction:Alliance"]="Ajudar Dokner garante que a remota pedreira dos anões permaneça operacional, reforçando a infraestrutura local e a prontidão dos equipamentos na região montanhosa e nevada.",["profession:Blacksmithing"]="Frast Dokner atua como um mentor de campo para aprendizes de ferreiro, negociando suas suadas técnicas de forja com qualquer pessoa disposta a fornecer o metal bruto e o couro necessários para manter sua bigorna aquecida.",["profession:Mining"]="Os mineradores que trabalham nas jazidas ao redor encontrarão um consumidor local imediato para suas barras de cobre fundidas, transformando minério bruto em treinamento prático e reparos no acampamento.",["race:Dwarf"]="A Pedreira Gol'Bolar representa o empreendimento e a indústria dos Barbabronze em Dun Morogh, onde a determinação dos anões mantém as forjas acesas mesmo quando as caravanas de suprimentos atrasam."},sec={{t="Escassez na Pedreira",b="A vida em uma escavação ativa exige manutenção constante, desde afiar picaretas e substituir suportes desgastados até reforçar os equipamentos do acampamento. Quando uma remessa vital de suprimentos não chega no prazo previsto, o trabalho diário quase para por completo. Sem novos estoques vindos das principais rotas comerciais, os artesãos no local são forçados a improvisar e recorrer a aventureiros de passagem para manter o acampamento em funcionamento. Frast Dokner, trabalhando na forja em meio a esses atrasos contínuos, depende de qualquer pessoa disposta a conseguir metais básicos e couros, em vez de esperar inutilmente por carroças de transporte que podem estar irremediavelmente atrasadas."},{t="O Acordo de um Aprendiz",b="As guildas tradicionais de ferraria dos anões valorizam a disciplina e métodos rigorosamente guardados, raramente transmitindo segredos de ofício a andarilhos casuais. Dokner, no entanto, equilibra a necessidade local com a etiqueta formal da guilda. Enfrentando uma escassez imediata de cobre maleável e couro durável necessários para consertar ferramentas e equipamentos do acampamento, ele oferece uma troca pragmática: traga os materiais brutos diretamente à sua bigorna, e ele ensinará você suas técnicas pessoais de ferraria. É um acordo mutuamente vantajoso nascido da necessidade da fronteira, trocando valioso conhecimento vocacional por sobrevivência e manutenção imediatas."}},faq={{q="Quem é Frast Dokner?",a="Frast Dokner é um ferreiro experiente estabelecido em um acampamento de pedreira, responsável por manter ferramentas, encaixes estruturais e equipamentos para os trabalhadores no local. Quando atrasos logísticos cortam sua linha de suprimentos habitual, ele toma a iniciativa ao recrutar aventureiros de passagem para obter os materiais brutos de que necessita desesperadamente.",al={"história de frast dokner","quem é o ferreiro da pedreira","ferreiro da pedreira"}},{q="Por que a pedreira precisa de barras de cobre e couros de javali?",a="A escavação e a manutenção do acampamento consomem quantidades enormes de material resistente. O cobre fornece um metal acessível e maleável, adequado para forjar encaixes de reposição, pregos, fechos e tiras de reforço para Ferramentas Quebradas. Os couros de javali reforçados fornecem um couro resistente necessário para foles, coberturas de ferramentas, correias e aventais de proteção que suportam as faíscas severas e o desgaste pesado do trabalho diário na pedreira.",al={"por que barras de cobre e couros de javali","materiais necessários ferreiro da pedreira","materiais de reparo da pedreira"}},{q="Por que o carregamento de suprimentos está atrasado?",a="Embora Frast Dokner não detalhe o motivo específico do atraso, as rotas terrestres de suprimentos através dos penhascos nevados e passagens montanhosas são frequentemente assoladas por nevascas rigorosas, animais selvagens errantes e emboscadas hostis de troggs ou bandidos. Acampamentos de mineração e pedreiras isolados são frequentemente os primeiros assentamentos a sentir o impacto sempre que as carroças de transporte atrasam.",al={"carregamento de suprimentos atrasado","o que aconteceu com os suprimentos","por que os suprimentos estão atrasados"}},{q="O que Frast Dokner oferece em troca dos materiais?",a="Em vez de oferecer apenas moedas, Frast Dokner promete compartilhar suas técnicas pessoais de ferraria com quem reunir os suprimentos necessários. Para um aspirante a artesão, aprender diretamente com um artífice experiente estabelecido em campo oferece percepções práticas sobre metalurgia e manutenção de equipamentos que os salões formais de guilda nas cidades raramente ensinam a novatos.",al={"história da recompensa do ferreiro da pedreira","o que frast ensina","técnicas de ferraria de frast"}},{q="Onde fica esta pedreira?",a="Frast Dokner trabalha em Dun Morogh na Pedreira Gol'Bolar, um local de escavação dos anões situado no sopé nevado ao sul de Kharanos. A pedreira enfrenta pressões operacionais constantes decorrentes do rigoroso clima de inverno e de troggs subterrâneos agressivos que rotineiramente atacam os mineradores e perturbam os comboios de comércio que viajam a partir de Altaforja.",al={"qual pedreira é esta","onde fica frast dokner","localização do ferreiro da pedreira"}},{q="Frast Dokner é afiliado a Altaforja?",a="Sim, Frast Dokner e o acampamento da pedreira operam sob o domínio do clã Barbabronze e do Reino de Altaforja. A extração de pedra e minério das montanhas de Dun Morogh é vital para os projetos de construção e fortificações defensivas do reino dos anões, tornando ferreiros locais como Dokner essenciais para a força industrial de Altaforja.",al={"frast dokner altaforja","a pedreira faz parte de altaforja","lealdade dos anões da pedreira"}}},fp="18,217,23.504.0,23.468.0,20.252.0,52.315.0,32.278.0,59.287.0,29.246.0,42.258.0"}
P.entries["quest:95219"] = {n="From Port to Port",s="Um vendedor do porto envia você com um barril cuidadosamente embalado ao Domínio de Plumaluna. A longa jornada exige cuidado.",h="Um vendedor do porto envia você com um barril cuidadosamente embalado ao Domínio de Plumaluna.",kw={"barril","entrega","domínio de plumaluna","feralas","de porto em porto","mardrack greenwell","porto detonapavio"},sec={{t="Um cliente distante",b="Um vendedor tem um cliente no Domínio de Plumaluna, em Feralas, e você leva até lá um barril do Porto Detonapavio. O vendedor diz que ele está embalado hermeticamente, mas alerta que algo pode fazê-lo explodir. Manuseie o barril com cuidado no caminho até Mardrack Greenwell."}},faq={{q="O que estou entregando?",a="Você está levando um barril do Porto Detonapavio para Mardrack Greenwell, no Domínio de Plumaluna.",al={"o que há no barril","entrega do porto detonapavio","barril do porto"}},{q="Para onde devo levar o barril?",a="O barril deve ser entregue a Mardrack Greenwell, no Domínio de Plumaluna, em Feralas.",al={"onde entregar","entrega em plumaluna","barril em feralas"}},{q="Por que devo manuseá-lo com cuidado?",a="O vendedor alerta que algo pode fazer o barril embalado hermeticamente explodir.",al={"o barril é perigoso","por que ter cuidado","o que pode fazê-lo explodir"}},{q="Quem embalou o barril?",a="Um dos homens do vendedor embalou o barril hermeticamente.",al={"quem embalou o produto do porto","embalagem hermética","homem do vendedor"}}},fp="17,112,18.250.0,21.91.0,27.78.0,33.71.0,20.49.0"}
P.entries["quest:95250"] = {n="Abominable Creatures",s="Abominable Creatures é uma missão concedida pelo Captain Truman, um lealista humano que aguarda desesperadamente por reforços nos arredores da capital caída de Lordaeron. Acreditando que seu comandante — um reverenciado Grand Marshal — ainda luta bravamente nas Ruínas de Lordaeron próximas, Truman implora a um aventureiro capaz que o encontre. A missão expõe o destino sombrio dos defensores perdidos do reino e a hostilidade amarga que arde entre os lealistas sobreviventes.",h="Abominable Creatures é uma missão concedida pelo Captain Truman, um lealista humano que aguarda...",kw={"abominable creatures","captain truman","grand marshal","head of the baron","lordaeron","ruínas de lordaeron","the baron","true sons of lordaeron"},ang={["faction:Alliance"]="A missão destaca a situação perigosa e isolada dos remanescentes alinhados à Aliança tentando operar dentro das ruínas assoladas do norte de Lordaeron. Ela enfatiza como os destacamentos lealistas remanescentes lutam contra o declínio da esperança e o desgaste psicológico de combater monstruosidades avassaladoras.",["race:Human"]="Aventureiros humanos testemunham o destino desolador da liderança caída de Lordaeron, já que até mesmo um estimado Grand Marshal foi transformado em um grotesco horror morto-vivo. O luto amargo e o fervor nacionalista do Captain Truman refletem o trauma recente carregado pelos sobreviventes humanos desesperados para recuperar seu lar ancestral.",["race:Undead"]="Para os Renegados, a transformação grotesca de the Baron é uma lembrança sombria de como o Flagelo mutilou os melhores defensores de Lordaeron em abominações monstruosas. O juramento do Captain Truman de purgar as ruínas de todas as feras e mortos-vivos reflete a hostilidade implacável que os lealistas vivos guardam contra o povo da Cidade Baixa."},sec={{t="Uma Vigília Desesperada",b="Captain Truman permanece vigilante em seu posto, aguardando ansiosamente por reforços há muito esperados para apoiar a defesa de Lordaeron. Confiante na proeza marcial de seu superior — um renomado Grand Marshal a quem descreve como um herói alto e escultural —, Truman continua preso ao dever após receber ordens de manter a posição enquanto seu comandante avançava para o combate em andamento. Nutrindo profunda desconfiança em relação a forasteiros e desprezando abertamente aqueles que considera raças inferiores, o capitão se recusa a confiar em irregulares locais. Quando um viajante capaz se aproxima, Truman aproveita a oportunidade para pedir ajuda, implorando para que alguém se aventure no território arruinado a fim de verificar o bem-estar de seu mestre e avaliar a batalha."},{t="As Ruínas de Lordaeron",b="A busca direciona os aventureiros diretamente para as perigosas Ruínas de Lordaeron, a capital destruída que caiu para o Flagelo durante a Terceira Guerra. Embora Captain Truman espere que seu glorioso líder esteja triunfante sobre os caídos, a realidade dentro da cidade assolada é muito mais sombria. As ruínas estão tomadas por horrores, remanescentes mortos-vivos e abominações vagando pelas praças de pedra quebradas. Percorrer essas ruas devastadas exige confrontar a verdade brutal do que aconteceu com os defensores que se aventuraram na cidade. Em vez de encontrar um cavaleiro impecável mantendo a posição, os viajantes descobrem que o comandante teve um fim trágico e distorcido entre as monstruosidades que ocupam os pátios."},{t="Uma Revelação Horripilante",b="Ao localizar o comandante desaparecido, designado como the Baron, os aventureiros fazem uma descoberta estarrecedora: o herói outrora escultural foi transformado em uma grotesca monstruosidade morta-viva. Cumprir a sombria tarefa exige matar a criatura e levar a Head of the Baron de volta ao Captain Truman. Ao ser apresentado à cabeça decepada de seu antigo senhor, Truman reage com choque, horror e profunda repulsa. Incapaz de aceitar o terrível destino de seu comandante, o capitão explode em amarga indignação, acusando o aventureiro de estar aliado a monstros e jurando que os verdadeiros filhos de Lordaeron um dia recuperarão sua terra e purgarão todas as feras."}},faq={{q="Quem dá a missão Abominable Creatures?",a="A missão é oferecida pelo Captain Truman, um lealista humano estacionado na região ao redor do reino caído. Mantendo ansiosamente seu posto enquanto aguarda reforços, Truman busca desesperadamente notícias de seu comandante, um reverenciado Grand Marshal que avançou para as Ruínas de Lordaeron próximas.",al={"quem dá abominable creatures","doador da missão abominable creatures","onde começar abominable creatures"}},{q="Onde ocorre a missão Abominable Creatures?",a="A missão direciona os aventureiros para as Ruínas de Lordaeron, a capital devastada e tomada por horrores do Flagelo e remanescentes mortos-vivos. Captain Truman mantém um posto fora da capital assolada, pedindo a viajantes corajosos que se aventurem diretamente nas ruínas perigosas para localizar seu superior desaparecido.",al={"local de abominable creatures","onde abominable creatures é concluída","zona de abominable creatures"}},{q="Quem é o mestre do Captain Truman?",a="Captain Truman refere-se ao seu mestre como o Grand Marshal, elogiando-o como um herói militar alto e escultural. No entanto, os objetivos da missão referem-se a este nobre desaparecido como the Baron, indicando que ele era um aristocrata de alto escalão e comandante militar liderando a defesa do reino.",al={"quem é o comandante de truman","identidade do grand marshal truman","quem é the baron"}},{q="O que aconteceu com o Grand Marshal nas Ruínas de Lordaeron?",a="Em vez de resistir vitoriosamente, o Grand Marshal foi morto e transformado em uma monstruosa criatura morta-viva dentro das Ruínas de Lordaeron. Quando os aventureiros o localizam, encontram uma abominação designada como the Baron, forçando-os a destruí-lo e pegar sua cabeça decepada.",al={"o que aconteceu com the baron","destino do grand marshal","o grand marshal está morto"}},{q="Por que o Captain Truman fica com raiva quando você entrega a missão?",a="Captain Truman esperava que seu comandante escultural estivesse vivo e vitorioso. Quando apresentado à cabeça grotesca e mutante de the Baron, Truman é tomado por horror e repulsa, acusando furiosamente o aventureiro de pregar uma piada de mau gosto e de se associar a feras vis.",al={"por que truman está bravo","reação de truman abominable creatures","por que truman grita com você"}},{q="O que Captain Truman quer dizer com os 'true sons of Lordaeron'?",a="Captain Truman usa o termo para descrever patriotas humanos fervorosos dedicados a recuperar sua terra natal destruída. Suas palavras expressam uma visão feroz e intolerante na qual os legítimos sobreviventes humanos purgarão o reino de todos os mortos-vivos, feras e qualquer um visto como associado a eles.",al={"significado de true sons of lordaeron","quem são os true sons of lordaeron","truman true sons"}},{q="Por que Captain Truman se recusa a confiar em 'half breeds'?",a="Captain Truman demonstra profundo desdém por raças não humanas e aliados irregulares, descartando-os como mestiços não confiáveis e escória. Sua intensa xenofobia o impede de confiar em qualquer um que não considere representantes dignos do reino.",al={"truman half breeds","por que captain truman é racista","xenofobia de truman"}}},fp="20,312,17.524.0,22.516.0,23.483.1,41.230.0,53.227.0,31.222.0,61.182.0,61.234.0,62.233.0,54.218.0"}
P.entries["quest:95254"] = {n="WANTED: Trapclaw",s="Fimbo Greasemitz quer a pinça de Trapclaw depois que o enorme caranguejo rouba iscas e corta linhas de pesca sob as docas. Traga-a para ele, e ele promete uma refeição feita com sua mistura secreta de temperos.",h="Fimbo Greasemitz quer a pinça de Trapclaw depois que o enorme caranguejo rouba iscas e corta linhas de pesca...",kw={"isca","caranguejo","carne de caranguejo","docas","fimbo greasemitz","linhas de pesca","pinça","trapclaw"},sec={{t="Sob as docas",b="Fimbo Greasemitz quer carne de caranguejo, e Trapclaw tem rastejado sob as docas. O grande caranguejo rouba iscas e corta linhas de pesca. Fimbo pede que você traga a pinça de Trapclaw, que pretende usar em uma refeição."}},faq={{q="Quem está pedindo a pinça de Trapclaw?",a="Fimbo Greasemitz quer a pinça de Trapclaw para conseguir carne de caranguejo.",al={"quem quer a pinça","pedido de fimbo greasemitz"}},{q="O que Trapclaw está fazendo?",a="Trapclaw rasteja sob as docas, roubando iscas e cortando linhas de pesca.",al={"por que trapclaw","caranguejo sob as docas"}},{q="Por que Fimbo quer a pinça?",a="Fimbo quer carne de caranguejo e pede a pinça de Trapclaw.",al={"para que serve a pinça","pedido de carne de caranguejo"}},{q="O que Fimbo promete preparar?",a="Fimbo diz que vai preparar um prato com manteiga e sua mistura secreta de temperos.",al={"qual refeição","prato de fimbo"}}},fp="16,188,15.218.0,36.59.0,23.75.0,31.54.0,32.68.0"}
P.entries["quest:95260"] = {n="Terrors From the Deep",s="No Porto Detonapavio, você procura um marinheiro capaz de identificar um monstro marinho pintado em um couro. A imagem estranha pode indicar uma criatura nestas águas.",h="No Porto Detonapavio, você procura um marinheiro capaz de identificar um monstro marinho pintado em um couro.",kw={"tripas de peixe","couro pintado","porto detonapavio","marinheiro","monstro marinho","tinta de lula","terrors from the deep"},sec={{t="Uma criatura pintada",b="Um couro pintado leva você ao Porto Detonapavio, onde um marinheiro talvez reconheça a criatura. Tripas de peixe e tinta de lula formam a figura de algo de pescoço longo que emerge das ondas. Se ela pertence a um monstro real destas águas, alguém que navega por aqui talvez o conheça."}},faq={{q="O que está pintado no couro?",a="O couro mostra um monstro marinho de pescoço longo emergindo das ondas, pintado com tripas de peixe e tinta de lula.",al={"o que há no couro","imagem de monstro marinho"}},{q="Onde alguém pode identificar o monstro?",a="O Porto Detonapavio é o porto mais próximo, e um marinheiro de lá talvez reconheça a criatura.",al={"para onde devo ir","marinheiro do porto detonapavio"}},{q="O monstro marinho é real?",a="A pintura levanta a possibilidade de que um monstro marinho espreite nestas águas, mas você procura um marinheiro capaz de identificá-lo.",al={"criatura marinha real","monstro real?"}}},fp="21,143,15.242.0,28.101.0,39.83.0,24.131.0"}
P.entries["quest:95261"] = {n="It Takes Guts",s="Argo Brinewhistle pede vísceras de feras e cogumelos Rotflesh como isca para uma criatura de pescoço comprido que viu perto das ilhas. Ele espera que a captura faça os outros acreditarem em sua história.",h="Argo Brinewhistle pede vísceras de feras e cogumelos Rotflesh como isca para uma criatura de pescoço comprido...",kw={"argo brinewhistle","isca","vísceras de feras","ilhas","é preciso coragem","monstro de pescoço comprido","cogumelos rotflesh","windstead"},sec={{t="A isca de Argo",b="Argo Brinewhistle diz que viu um monstro de pescoço comprido perto das ilhas, quando estava em seu barco. Ele quer que você reúna vísceras de feras e cogumelos Rotflesh para usar como isca. Os cogumelos crescem em uma caverna perto de Windstead, e Argo espera capturar a criatura."}},faq={{q="Quem é Argo Brinewhistle?",a="Argo Brinewhistle é um pescador que diz ter visto um monstro de pescoço comprido perto das ilhas.",al={"quem é argo","argo pescador","história de argo"}},{q="O que Argo quer para usar como isca?",a="Argo pede que você traga vísceras de feras e cogumelos Rotflesh.",al={"qual isca argo precisa","vísceras para argo","isca fedorenta"}},{q="Onde crescem os cogumelos Rotflesh?",a="Os cogumelos Rotflesh crescem em uma caverna perto de Windstead.",al={"local dos rotflesh","onde crescem os cogumelos","caverna de windstead"}},{q="Por que Argo precisa da isca?",a="Argo quer a isca para capturar a criatura de pescoço comprido que diz ter visto perto das ilhas.",al={"por que precisa de isca","o que argo está tentando capturar","monstro de pescoço comprido"}},{q="Por que ninguém acredita em Argo?",a="Argo diz que as pessoas desprezam sua história porque o veem como um pescador bêbado.",al={"por que duvidam de argo","argo bêbado","quem acredita em argo"}}},fp="13,187,11.250.0,25.95.0,29.65.0,33.47.0,28.94.0,32.80.0"}
P.entries["quest:95284"] = {n="The Elite of the Elite",s="Um fornecedor perto da costa pede que você encontre uma força desaparecida de elite Kor’kron. O rastro leva à Ilha Alcaz, onde algo pode ter dado errado.",h="Um fornecedor perto da costa pede que você encontre uma força desaparecida de elite Kor’kron.",kw={"ilha alcaz","costa","soldados de elite","ilha","kor'kron","kor'kron desaparecidos","fornecedor"},ang={["faction:Horde"]="Como membro da Horda, você recebeu o pedido de encontrar uma força desaparecida de soldados Kor’kron."},sec={{t="Uma trilha preocupante",b="Há alguns dias, soldados Kor’kron pararam aqui para comprar suprimentos e descansar antes de seguir viagem. O fornecedor ouviu um deles falar de uma ilha, e a Ilha Alcaz fica logo ali, perto da costa. Agora, pedem que você encontre os elites desaparecidos e descubra o que aconteceu com eles."}},faq={{q="Quem são os Kor’kron desaparecidos?",a="São uma pequena força de soldados Kor’kron que parou aqui para buscar suprimentos e descansar antes de seguir viagem.",al={"elites kor'kron","soldados desaparecidos","kor kron desaparecidos"}},{q="Para onde os Kor’kron podem ter ido?",a="Um dos soldados mencionou uma ilha, e o fornecedor suspeita que seja a Ilha Alcaz, perto da costa.",al={"qual ilha","ilha kor'kron","para onde eles foram"}},{q="Por que o fornecedor está preocupado?",a="Os Kor’kron seguiram viagem depois de descansar, mas o fornecedor sente que algo deu errado.",al={"o que deu errado","por que procurar os kor'kron","soldados de elite desaparecidos"}},{q="Como é a Ilha Alcaz?",a="O fornecedor descreve a Ilha Alcaz como um lugar muito desagradável.",al={"ilha alcaz","alcaz é perigosa","ilha desagradável"}}},fp="22,157,16.250.0,31.102.0,37.94.0,28.83.0,26.53.0"}
P.entries["quest:95288"] = {n="Smuggler's Paradise",s="No Porto Detonapavio, Friz Frazzlespark manda você atrás dos piratas Eastsea que levaram os bens que ele roubou. Ele chama isso de sua primeira lição sobre lidar com traidores.",h="No Porto Detonapavio, Friz Frazzlespark manda você atrás dos piratas Eastsea que levaram os bens que ele...",kw={"piratas eastsea","friz frazzlespark","goblin","porto detonapavio","bens contrabandeados","paraíso dos contrabandistas","bens roubados"},sec={{t="A lição de Friz",b="Friz Frazzlespark, no Porto Detonapavio, quer que você recupere os bens levados pelos piratas Eastsea. Ele diz que os roubou primeiro e chama retomá-los de sua primeira lição como capanga dele."},{t="Uma primeira lição",b="Friz diz que você aprendeu bem sua primeira lição. Ele oferece sua sabedoria de graça e depois indica outra tarefa."}},faq={{q="Quem é Friz Frazzlespark?",a="Friz Frazzlespark é o goblin que pede que você recupere seus bens roubados dos piratas Eastsea.",al={"friz","quem é friz","goblin no porto detonapavio"}},{q="O que os piratas Eastsea levaram?",a="Os piratas Eastsea levaram uma remessa de bens que Friz diz ter roubado primeiro.",al={"bens dos piratas","o que foi roubado","bens contrabandeados"}},{q="Para onde Friz quer que os bens sejam devolvidos?",a="Friz pede que você recolha os bens para ele no Porto Detonapavio.",al={"onde fica friz","porto detonapavio","onde levar os bens"}},{q="Por que Friz quer os bens de volta?",a="Friz diz que os piratas levaram bens que ele havia roubado primeiro e chama retomá-los de uma lição sobre lidar com traidores.",al={"por que recuperar os bens","por que friz se importa","motivo da traição"}}},fp="19,156,13.178.0,14.130.1,25.94.0,34.80.0,40.62.0,34.119.0"}
P.entries["quest:95293"] = {n="Smuggler's Special",s="Friz manda você levar ao capitão Bentcoin, em Eastwind Shore, uma caixa chamada The Friz Special. A entrega é a resposta dela à tentativa dele de invadir seu território.",h="Friz manda você levar ao capitão Bentcoin, em Eastwind Shore, uma caixa chamada The Friz Special.",kw={"capitão bentcoin","caixa","piratas de eastsea","eastwind shore","friz","especial do contrabandista","the friz special","guerra comercial"},sec={{t="A resposta de Friz",b="O capitão Bentcoin ameaça você quando pisa no navio dele. Friz enviou você com uma caixa chamada The Friz Special, destinada ao capitão em Eastwind Shore. As mercadorias dela deveriam ter sido entregues diretamente a ela, e Friz acredita que Bentcoin está tentando invadir seu território. Ela chama isso de segunda lição e apresenta a caixa como uma resposta à altura da negociação dele."},{t="A caixa",b="Quando Bentcoin recebe a caixa de Friz, ele entende isso como um sinal de que ela sabe que foi derrotada. Então, ouve um ruído de algo contando os segundos."}},faq={{q="Quem é Friz?",a="Friz enviou você até o capitão Bentcoin com uma caixa chamada The Friz Special, depois que mercadorias destinadas a ela foram desviadas.",al={"friz","quem me enviou","quem dá the friz special"}},{q="Quem é o capitão Bentcoin?",a="O capitão Bentcoin é o capitão que Friz manda você encontrar no navio dele, em Eastwind Shore.",al={"bentcoin","quem é o capitão","capitão de eastwind"}},{q="O que estou entregando?",a="Você está levando The Friz Special, uma caixa que Friz preparou para o capitão Bentcoin.",al={"the friz special","a caixa","o que devo levar"}},{q="Por que Friz está enviando um presente?",a="Friz diz que as mercadorias que você conseguiu com os piratas de Eastsea deveriam ser enviadas diretamente a ela, e acredita que Bentcoin está tentando invadir seu território.",al={"por que dar um presente a bentcoin","entrega de friz","guerra comercial"}},{q="Onde encontro o capitão Bentcoin?",a="O capitão Bentcoin está no navio dele, em Eastwind Shore.",al={"localização de bentcoin","onde está o capitão","eastwind shore"}},{q="O que Bentcoin diz quando chego?",a="Bentcoin ameaça fazer você andar na prancha por subir a bordo do navio dele e exige saber por que deveria poupar você.",al={"reação de bentcoin","o que o capitão diz","subir no navio"}}},fp="18,158,13.362.0,9.132.1,12.111.0,24.88.0,21.74.0,27.157.0,33.53.0,37.98.0"}
P.entries["quest:95294"] = {n="Smuggler's Bargain",s="Um pirata Eastsea oferece a Friz Frazzlespark um acordo para deixá-la cuidar dos negócios em paz. Você leva a mensagem dele até ela no Porto Detonapavio.",h="Um pirata Eastsea oferece a Friz Frazzlespark um acordo para deixá-la cuidar dos negócios em paz.",kw={"capitão","piratas eastsea","friz frazzlespark","goblin","pirata","porto detonapavio","acordo do contrabandista"},sec={{t="A oferta de um capitão",b="Friz Frazzlespark chamou a atenção dos piratas Eastsea, e um deles se oferece para impedir que sua tripulação interfira nos negócios dela. Em troca, propõe um acordo lucrativo. Você leva a mensagem dele até Friz no Porto Detonapavio, onde ela saberá quem alega estar no comando."},{t="A lição de Friz",b="Friz responde à oferta do pirata com um aviso sobre o preço de cruzar seu caminho. As palavras dela deixam os termos do acordo em dúvida."}},faq={{q="O que o pirata oferece a Friz?",a="Um pirata Eastsea se oferece para impedir que sua tripulação interfira nos negócios de Friz e propõe um acordo lucrativo.",al={"oferta do pirata eastsea","acordo com friz"}},{q="Para quem devo voltar para relatar?",a="Você volta para Friz Frazzlespark no Porto Detonapavio.",al={"onde voltar","quem recebe a mensagem"}},{q="Que mensagem o capitão envia?",a="Ele quer que Friz saiba que um novo capitão está no comando e prevê uma relação lucrativa.",al={"mensagem do capitão","o que dizer a friz"}},{q="Quem é o novo capitão?",a="Friz questiona quem é o capitão, mas a mensagem não o identifica.",al={"quem é o capitão","chefe dos piratas"}}},fp="18,135,17.279.0,13.124.1,32.118.0,24.51.0,35.93.0,23.69.0"}
P.entries["quest:95295"] = {n="I Know a Guy",s="Friz envia você à Angra do Butim para encontrar seu contato, Ruzzgot. O contato consegue mercadorias com os bucaneiros locais e explicará o que vem a seguir.",h="Friz envia você à Angra do Butim para encontrar seu contato, Ruzzgot.",kw={"angra do butim","contato","bucaneiros","friz","mercadorias","conheço alguém","piratas","ruzzgot"},sec={{t="Um contato em Angra do Butim",b="Friz diz que seu contato é Ruzzgot, que está esperando na Angra do Butim. Ele consegue mercadorias com os piratas de lá, a quem Friz chama de bucaneiros. Encontre Ruzzgot, e ele explicará o resto."}},faq={{q="Quem é o contato de Friz?",a="Friz indica Ruzzgot como seu contato na Angra do Butim.",al={"contato de friz","quem é ruzzgot","contato na angra do butim"}},{q="Para onde Friz me envia?",a="Friz envia você à Angra do Butim para encontrar Ruzzgot.",al={"para onde ir","onde está ruzzgot","angra do butim"}},{q="O que Ruzzgot faz?",a="Ruzzgot consegue mercadorias com os piratas locais da Angra do Butim.",al={"o que o contato faz","mercadorias de ruzzgot","mercadorias piratas"}},{q="Por que Friz chama os piratas de bucaneiros?",a="Friz diz que algumas pessoas chamam piratas de bucaneiros e brinca que a palavra contém “saque grátis”.",al={"significado de bucaneiro","piratas ou bucaneiros","por que bucaneiros"}}},fp="12,141,22.166.0,22.47.0,24.44.0,21.55.0,43.98.0"}
P.entries["quest:953"] = {n="A queda de Ameth'Aran",s="A Sentinela Tysha Lamiluna incumbe os aventureiros de explorar as assombrosas ruínas de Ameth'Aran em Costa Negra para decifrar antigas tabuletas de pedra. Essas inscrições registram a tragédia e a ruína que atingiram a cidade dos Altaneiros durante a Cisão. O conhecimento reunido destina-se ao Círculo dos Anciãos em Auberdine, recuperando uma história amplamente perdida durante a Guerra dos Antigos.",h="A Sentinela Tysha Lamiluna incumbe os aventureiros de explorar as assombrosas ruínas de Ameth'Aran em Costa...",kw={"ameth'aran","auberdine","azshara","círculo dos anciãos","costa negra","altaneiros","cisão","tabuletas","tysha lamiluna"},ang={["class:Mage"]="As tabuletas oferecem um vislumbre sóbrio do ápice da magia élfica antes da Cisão e da terrível ruína causada quando esse poder saiu do controle.",["faction:Alliance"]="Ajudar as Sentinelas a resguardar a história de Costa Negra contribui para preservar um conhecimento crucial para os líderes elfos noturnos que guiam a Aliança em Kalimdor.",["race:NightElf"]="As ruínas de Ameth'Aran são uma lembrança sombria da soberba dos seus ancestrais sob o reinado da Rainha Azshara e das consequências catastróficas da feitiçaria arcana desregulada."},sec={{t="Ecos dos Altaneiros",b="Muito antes de a costa se fragmentar na extensão enevoada de Costa Negra, Ameth'Aran erguia-se como um assentamento próspero onde os feiticeiros de elite da Rainha Azshara praticavam uma poderosa magia arcana. Após a destruição cataclísmica da Nascente da Eternidade, dez mil anos atrás, a cidade foi reduzida a mármore quebrado e pilares rachados. Hoje, permanece assombrada pelos espíritos inquietos e angustiados dos Altaneiros que pereceram quando sua era de ouro ruiu."},{t="Revelando Crônicas Perdidas",b="Como a Guerra dos Antigos mergulhou a civilização dos elfos noturnos em uma luta caótica pela sobrevivência, raríssimos relatos escritos sobreviveram intactos à Grande Cisão. A Sentinela Tysha Lamiluna tentou inspecionar as ruínas pessoalmente, descobrindo duas grandes tabuletas gravadas — Lay of Ameth'Aran e A queda de Ameth'Aran — antes que espectros fantasmagóricos de Altaneiros a forçassem a recuar. Recuperar esses registros garante que as verdades históricas do antigo desastre cheguem aos eruditos do Círculo dos Anciãos em Auberdine."}},faq={{q="O que é Ameth'Aran?",a="Ameth'Aran é uma antiga ruína de elfos noturnos localizada na região central de Costa Negra. Dez mil anos atrás, era uma cidade onde a nobreza dos Altaneiros da Rainha Azshara manipulava e estudava abertamente a grandiosa magia arcana, antes de sucumbir durante a Grande Cisão.",al={"história de ameth'aran","o que era ameth'aran","quem vivia em ameth'aran"}},{q="Por que há fantasmas em Ameth'Aran?",a="Os fantasmas inquietos que assombram as ruínas são os espíritos dos Altaneiros que ali viveram e morreram. Apanhados na catástrofe repentina e violenta que despedaçou a Nascente da Eternidade e fragmentou Kalimdor, seus espíritos permanecem atados às ruínas em tormento eterno.",al={"por que há espíritos em ameth'aran","fantasmas de ameth'aran","altaneiros inquietos"}},{q="Quem é a Sentinela Tysha Lamiluna?",a="A Sentinela Tysha Lamiluna é uma sentinela elfa noturna posicionada ao longo da estrada em Costa Negra. Ela recebeu a missão de explorar sítios antigos e recuperar registros históricos perdidos para o Círculo dos Anciãos em Auberdine.",al={"sentinela tysha lamiluna","quem dá a queda de ameth'aran"}},{q="Por que o Círculo dos Anciãos quer a leitura dessas tabuletas?",a="A destruição da Nascente da Eternidade mergulhou Kalimdor em um imenso caos, obliterando incontáveis bibliotecas e monumentos. Como tão poucos registros escritos sobreviveram à Guerra dos Antigos, as tabuletas fornecem relatos raros e em primeira mão sobre a Cisão sob a perspectiva dos Altaneiros.",al={"por que ler as tabuletas","tabuletas do círculo dos anciãos","significado de lay of ameth'aran"}},{q="Onde as tabuletas estão localizadas?",a="As duas grandes tabuletas — Lay of Ameth'Aran e A queda de Ameth'Aran — estão gravadas em monumentos de pedra erguidos entre os pátios arruinados de Ameth'Aran, cercadas pelos fantasmas errantes dos antigos habitantes da cidade.",al={"onde ficam as tabuletas de ameth'aran","localização das tabuletas","como ler ameth'aran"}},{q="O que aconteceu com os Altaneiros de Ameth'Aran durante a Cisão?",a="Quando a Nascente da Eternidade implodiu no clímax da Guerra dos Antigos, tremores colossais e o ricochete arcano despedaçaram Kalimdor. Ameth'Aran desabou em ruínas, soterrando seus cidadãos e deixando seus fantasmas a vagar pelos escombros.",al={"como ameth'aran caiu","destruição de ameth'aran"}}},fx={["4f4506ec"]={q="Por que a Sentinela Tysha Lamiluna quer que isso seja feito?",a="A Sentinela Tysha Lamiluna foi despachada em nome do Círculo dos Ancestrais para pesquisar as ruínas antigas. Registros da era da Guerra dos Ancestrais e da Ruptura são extremamente raros devido aos cataclismos daquela época. Reunir a história esculpida nas tábuas permite que ela forneça uma contabilidade completa aos druidas e anciãos em Auberdine.",al={"motivo de tysha lamiluna","por que tysha precisa disso","por que estudar as tábuas de ameth'aran"}},["2329a43d"]={q="Por que a Sentinela Tysha Lamiluna precisa da sua ajuda?",a="Tysha aventurou-se anteriormente em Ameth'Aran para examinar as tábuas ela mesma, mas foi emboscada e expulsa pelos espíritos vingativos dos Altaneiros que assombram as ruínas. Incapaz de transcrever as inscrições com segurança por conta própria enquanto sob constante ataque espectral, ela precisa de um aventureiro capaz para invadir as ruínas e decifrar o texto em seu lugar.",al={"por que tysha não consegue ler as tábuas","por que tysha precisa de mim","por que tysha não vai ela mesma"}}},fp="22,278,23.289.0,26.458.0,19.221.0,35.199.0,32.190.0,56.311.0,30.204.0,66.216.0"}
P.entries["quest:95314"] = {n="O elixir verde do Vale das Sombras",s="Carolai Anise em Montalvo busca itens a serem resgatados do povoado abandonado do Vale das Sombras, escondido nas profundezas da isolada Floresta do Sussurro. Antes da queda do reino, a aldeia era famosa por destilar o Whispering Elixir a partir de estranhas ervas locais — um potente preparado que permaneceu valorizado no mercado negro mesmo após ser proibido em Lordaeron.",h="Carolai Anise em Montalvo busca itens a serem resgatados do povoado abandonado do Vale das Sombras, escondido...",kw={"boticário","montalvo","carolai anise","veneno","vale das sombras","tirisfal","whispering elixir","floresta do sussurro"},ang={["class:Rogue"]="O Whispering Elixir foi muito valorizado por envenenadores clandestinos e patifes que agiam longe dos olhos dos antigos magistrados de Lordaeron.",["profession:Herbalism"]="O elixir obtém sua potência a partir de ervas singulares que só vicejam sob a copa sinistra da isolada Floresta do Sussurro.",["race:Undead"]="Para os Renegados, recuperar as destilações esquecidas de Lordaeron serve tanto a um comércio lucrativo quanto aos experimentos de boticários na recém-criada Cidade Baixa."},sec={{t="Uma infusão banida",b="Muito antes da Terceira Guerra e da chegada do Flagelo, os habitantes reclusos do Vale das Sombras preparavam uma mistura peculiar conhecida como Whispering Elixir. Destilada a partir de ervas raras exclusivas das Clareiras de Tirisfal, a poção ganhou notoriedade por todo o norte de Lordaeron. Apesar de ter sido oficialmente banida dentro de Capital City, suas propriedades incomuns faziam com que fosse avidamente procurada por místicos, envenenadores e boticários praticantes dispostos a burlar os decretos reais."},{t="Ruínas na Floresta do Sussurro",b="O Vale das Sombras fica escondido nas profundezas da Floresta do Sussurro, a oeste de Tirisfal. Historicamente, os aldeões eram um povo isolacionista e desconfiado que raramente acolhia forasteiros. Após a invasão do Flagelo, o povoado ruiu, mas estoques esquecidos do antigo elixir verde continuam em meio aos destroços. Carolai Anise opera a partir de Montalvo, aproveitando a persistente demanda do submundo para pagar aventureiros dispostos a encarar o silêncio perturbador da floresta."},{t="A maldição do sussurro",b="Embora Carolai prefira descartar os boatos como mera superstição, a Floresta do Sussurro carrega uma reputação sombria. As lendas locais sugerem que o próprio solo e as raízes da floresta estão contaminados por uma maldição antiga, algo que penetra diretamente na flora colhida pelos destiladores do Vale das Sombras. Seja qual for a malevolência persistente que assombra o vilarejo abandonado, isso pouco fez para diminuir o apetite de compradores distantes em busca de seus frascos restantes."}},faq={{q="O que é o Vale das Sombras?",a="O Vale das Sombras era uma aldeia isolada, oculta na Floresta do Sussurro, a oeste das Clareiras de Tirisfal. Seu povo era formado por isolacionistas sigilosos conhecidos principalmente por destilar misturas raras a partir da vegetação selvagem local antes de o Flagelo assolar a região.",al={"onde fica o vale das sombras","quem vivia no vale das sombras","aldeia vale das sombras"}},{q="O que é o Whispering Elixir?",a="É uma potente poção verde destilada a partir de ervas exclusivas encontradas em Tirisfal. Muito cobiçada por místicos, envenenadores e boticários, a bebida foi banida em Capital City antes da queda de Lordaeron.",al={"o que o elixir faz","história o elixir verde do vale das sombras","whispering elixir"}},{q="Quem é Carolai Anise?",a="Carolai Anise é uma engenhosa Renegada que reside em Montalvo. Ela atua como intermediária de curiosidades valiosas e proibidas, obtendo reagentes ilícitos como o elixir do Vale das Sombras para vender a compradores interessados por todo o reino.",al={"carolai anise","quem dá a missão o elixir verde do vale das sombras","doador de missão montalvo"}},{q="Por que o elixir foi banido em Capital City?",a="Nenhum motivo é apresentado. Carolai diz apenas que o elixir foi proibido na cidade, e que boticários, místicos e envenenadores o procuravam mesmo assim. Alguns acreditam que a Floresta do Sussurro seja amaldiçoada e que o elixir destilado de suas raízes carregue a mesma maldição, mas Carolai rejeita isso como superstição e nunca associa isso à proibição.",al={"por que o whispering elixir era ilegal","o elixir é veneno"}},{q="Por que a Floresta do Sussurro é considerada perigosa?",a="Os bosques isolados a oeste de Plangemortis são amplamente considerados sinistros e amaldiçoados. Aqueles que se aventuram por lá relatam uma profunda malevolência e estranhos fenômenos florestais, que, segundo boatos, contaminaram as ervas que brotam de seu solo.",al={"a floresta do sussurro é amaldiçoada","história da floresta do sussurro"}},{q="Quem são os compradores que querem este elixir?",a="De acordo com Carolai Anise, vários compradores estão ansiosos para obter frascos remanescentes anteriores à guerra, embora ela não revele quem são.",al={"quem compra o elixir","compradores de carolai anise"}}},fx={["4d019fa8"]={q="Por que Carolai Anise quer que o Elixir Sussurrante seja coletado?",a="Carolai Anise trabalha como procuradora de artigos raros em Montalvo, e a demanda pela bebida ilícita nunca morreu de verdade. Com vários compradores ávidos pressionando-a por carregamentos, há um lucro considerável a ser obtido de quaisquer garrafas que restaram intactas entre as ruínas.",al={"por que carolai quer o elixir","motivação de carolai anise","por que coletar elixir sussurrante"}}},fp="28,195,13.300.0,30.405.0,20.331.1,19.190.0,26.192.0,21.142.0,46.280.0,50.204.0,39.105.0"}
P.entries["quest:95315"] = {n="The Riverglades Report",s="A Capitã Nélia envia você ao sul com correspondência para Demar Brant, na Bastilha de Ermoforte. Um batedor relata que uma força inimiga se reúne além do Pantanal, perto de um povoado chamado Farholde.",h="A Capitã Nélia envia você ao sul com correspondência para Demar Brant, na Bastilha de Ermoforte.",kw={"capitã nélia","correspondência","demar brant","farholde","bastilha de ermoforte","relato das sendas do rio","batedor","pantanal"},sec={{t="Relato de um batedor",b="A Capitã Nélia soube que uma grande força inimiga está se reunindo bem ao sul do Pantanal. Talvez haja ali um povoado chamado Farholde, embora ela só conheça esse nome. Ela entrega a você uma correspondência para Demar Brant, que lidera o destacamento na Bastilha de Ermoforte, na costa sudeste das Sendas do Rio."}},faq={{q="O que o batedor relatou?",a="O batedor relatou que uma grande força inimiga está se reunindo bem ao sul, além do Pantanal.",al={"relato do batedor","o que acontece ao sul"}},{q="Para quem a Capitã Nélia está me enviando?",a="Você deve entregar a correspondência da Capitã Nélia a Demar Brant, na Bastilha de Ermoforte.",al={"quem recebe a carta","demar brant"}},{q="Onde fica a Bastilha de Ermoforte?",a="A Bastilha de Ermoforte fica na costa sudeste das Sendas do Rio.",al={"onde fica farholde","localização da bastilha"}},{q="O que é Farholde?",a="A Capitã Nélia ouviu falar de um povoado chamado Farholde perto do local onde a força está se reunindo.",al={"povoado farholde","o que é farholde"}}},fp="22,180,16.302.0,26.80.0,35.83.0,23.67.0,17.81.0"}
P.entries["quest:95327"] = {n="All's Well That Ends Well",s="Friz Frazzlespark diz que a Empreendimentos S.A. pagou sua parte no acordo e que ela recebeu seu saque. Você volta ao Porto Detonapavio enquanto outra remessa se aproxima.",h="Friz Frazzlespark diz que a Empreendimentos S.A.",kw={"acordo","friz frazzlespark","porto detonapavio","sendas do rio","remessa","southsea pirates","empreendimentos s.a."},sec={{t="Outra remessa",b="Uma nova remessa está a caminho do Porto Detonapavio, e Friz Frazzlespark está esperando lá. Você volta até ela nas Sendas do Rio, depois que a Empreendimentos S.A. recebeu o que merecia e Friz recebeu seu saque. Ela diz que a transação foi tranquila. Agora, os Southsea Pirates devem trazer a próxima remessa."}},faq={{q="Quem é Friz Frazzlespark?",a="Friz Frazzlespark está esperando por você no Porto Detonapavio, nas Sendas do Rio.",al={"quem é friz","friz frazzlespark"}},{q="O que aconteceu com a Empreendimentos S.A.?",a="Friz diz que a Empreendimentos S.A. recebeu o que merecia.",al={"acordo com a empreendimentos s.a.","e a empreendimentos s.a."}},{q="Friz recebeu seu saque?",a="Sim. Friz diz que recebeu seu saque.",al={"saque de friz","ela recebeu?"}},{q="O que vem a seguir?",a="Friz espera outra remessa dos Southsea Pirates.",al={"próxima remessa","southsea pirates"}}},fp="25,166,16.302.0,25.75.0,33.46.0,22.41.0,20.56.0"}
P.entries["quest:95328"] = {n="Whispering Horror Residue",s="O Whispering Horror Residue é o resto contorcido de uma estranha fera recuperado de sob a Floresta do Sussurro. Coletados por aventureiros intrépidos, esses restos tocados pelo Vazio são levados a Father Lankester no War Quarter da Cidade Baixa para pesquisas sobre a sombra.",h="O Whispering Horror Residue é o resto contorcido de uma estranha fera recuperado de sob a Floresta do...",kw={"father lankester","sombra","tirisfal","cidade baixa","vazio","war quarter","floresta do sussurro","whispering horror residue"},ang={["class:Priest"]="Sacerdotes das sombras dos Renegados como Father Lankester mantêm um intenso interesse acadêmico e teológico em espécimes do Vazio, considerando restos planares estranhos como objetos de estudo em vez de meras abominações.",["faction:Horde"]="Aventureiros a serviço da Horda recuperam espécimes perturbadores dos ermos ocultos das Clareiras de Tirisfal para abastecer os esforços de pesquisa sob as ruínas de Capital City.",["race:Undead"]="Os Renegados da Cidade Baixa estudam ativamente magias proibidas e corrupções antinaturais por toda Lordaeron, buscando controlar fenômenos sombrios para fortalecer seu domínio precário sobre o reino."},sec={{t="Uma Colheita Perturbadora",b="O Whispering Horror Residue representa os restos bizarros e contorcidos recolhidos de uma fera derrotada que habitava sob a Floresta do Sussurro. Em vez de abandonar tamanha curiosidade antinatural, aventureiros engenhosos recolhem o material palpitante na esperança de que pesquisadores da Cidade Baixa possam fazer bom uso dele."},{t="Estudos na Sombra",b="Os restos da criatura encontram um destinatário ávido em Father Lankester, localizado no War Quarter da Cidade Baixa. Lankester observa que a Floresta do Sussurro há muito tempo é tocada pelo Vazio, acolhendo a oportunidade de examinar vestígios físicos dessa corrupção sombria à medida que se aprofunda nos mistérios da sombra."}},faq={{q="O que é o Whispering Horror Residue?",a="O Whispering Horror Residue consiste nos restos corporais contorcidos colhidos de uma estranha fera derrotada sob a Floresta do Sussurro. Apesar de sua natureza perturbadora, estudiosos de Shadow Magic o consideram valioso para pesquisas arcanas e ocultas.",al={"o que é o resíduo","o que é whispering horror residue","item de resíduo"}},{q="Quem quer o Whispering Horror Residue?",a="O resíduo é entregue a Father Lankester, uma figura dos Renegados localizada no War Quarter da Cidade Baixa. Ele acolhe a oportunidade de explorar os mistérios da sombra e de fenômenos tocados pelo Vazio.",al={"quem recebe o resíduo","quem é father lankester","onde entregar o resíduo"}},{q="De onde veio este espécime?",a="O espécime origina-se de sob a Floresta do Sussurro, uma floresta sinistra localizada a oeste de Plangemortis, nas Clareiras de Tirisfal. Como Father Lankester observa, a área infecta é conhecida por ser tocada pelo Vazio.",al={"de onde vem o horror","história da floresta do sussurro","sob a floresta do sussurro"}},{q="Por que Father Lankester quer o resíduo?",a="Father Lankester busca estudar os mistérios da sombra e do Vazio. Para os praticantes dos Renegados que investigam artes proibidas, restos físicos de criaturas corrompidas pelo Vazio oferecem percepções raras e material de pesquisa.",al={"por que lankester quer isso","pesquisa de sombras cidade baixa","por que estudar o resíduo"}},{q="Onde Father Lankester pode ser encontrado?",a="Father Lankester reside no War Quarter da Cidade Baixa. O War Quarter serve como um centro movimentado para guerreiros, eruditos e estrategistas militares dos Renegados sob as ruínas da capital de Lordaeron.",al={"onde fica o war quarter","onde lankester está localizado","localização de lankester na cidade baixa"}},{q="A Floresta do Sussurro é tocada pelo Vazio?",a="A Floresta do Sussurro há muito mantém uma reputação sinistra entre os habitantes de Tirisfal. Father Lankester observa que não é segredo para ninguém que os bosques infectos e os espaços subterrâneos sob eles são tocados pelo Vazio.",al={"a floresta do sussurro é amaldiçoada","corrupção do vazio floresta do sussurro","o que toca a floresta do sussurro"}}},fp="25,138,21.162.0,17.197.0,38.149.0,40.151.0,34.147.0,43.154.0,36.168.0,45.147.0"}
P.entries["quest:95329"] = {n="Out in the Field",s="Um vigia em Terral's Watch observa as planícies em busca de movimentos da Horda. Você deve buscar o relatório de situação dele.",h="Um vigia em Terral's Watch observa as planícies em busca de movimentos da Horda.",kw={"cornelius","horda","torre de observação","no campo","relatório de situação","terral's watch","vigia"},sec={{t="Uma Vigília Remota",b="Uma torre vigia as planícies do norte a partir de Terral's Watch. O Vigia Cornelius está sozinho no posto, monitorando os movimentos das forças da Horda. Seu posto é isolado, e ele é conhecido por falar pouco. Você deve conversar com ele e trazer um relatório de situação."}},faq={{q="Quem é Cornelius?",a="Cornelius é o vigia que está sozinho em Terral's Watch, onde observa as planícies em busca de movimentos da Horda.",al={"vigia cornelius","quem é o vigia","relatório de cornelius"}},{q="O que é Terral's Watch?",a="Terral's Watch é um posto de observação com vista para as planícies do norte, usado para monitorar os movimentos das forças da Horda.",al={"terral watch","torre de vigia","torre no norte"}},{q="Que relatório devo buscar?",a="Você deve conversar com o Vigia Cornelius em Terral's Watch e buscar um relatório de situação.",al={"relatório de situação","o que cornelius precisa","tarefa de cornelius"}},{q="Por que Cornelius está sozinho?",a="Cornelius está sozinho no posto de vigia isolado. Ele é conhecido por ser taciturno, e esse é o motivo dado para sua designação para lá.",al={"por que ele está sozinho","posto de cornelius","por que foi designado para lá"}}},fp="16,115,14.265.0,17.115.0,23.116.0,30.88.0,33.140.0"}
P.entries["quest:95330"] = {n="Love Thy Neighbor",s="Cassandra Wheeler pede que você leve o excedente da fazenda dela a Halligan Turner, no Turner's Logging Camp. Ela espera que os trabalhadores tenham mais variedade nas refeições.",h="Cassandra Wheeler pede que você leve o excedente da fazenda dela a Halligan Turner, no Turner's Logging Camp.",kw={"cassandra wheeler","farholde","produtos da fazenda","frutas","halligan turner","ame o próximo","turner's logging camp","verduras"},sec={{t="Presente de uma vizinha",b="Cassandra Wheeler cultiva a terra ao norte de Farholde e leva a colheita até lá para vender. Ela separa o que sobra para pessoas que precisam de um incentivo. O acampamento madeireiro fica ao norte da fazenda dela, às margens do rio, e ela acha que os trabalhadores poderiam aproveitar frutas e verduras. Você leva o excedente a Halligan Turner, o capataz do acampamento."},{t="No acampamento",b="Halligan Turner recebe os produtos com gratidão. Os trabalhadores têm pouco além de carne e pão, então ele planeja repartir os produtos entre eles. Ele espera retribuir a gentileza de Cassandra quando puder."}},faq={{q="Quem pediu a entrega?",a="Cassandra Wheeler pede que você leve o excedente da fazenda dela a Halligan Turner.",al={"quem pediu isso","pedido de cassandra","missão dos produtos da fazenda"}},{q="Quem é Halligan Turner?",a="Halligan Turner é o capataz do Turner's Logging Camp.",al={"quem é halligan","capataz do acampamento madeireiro","sujeito turner"}},{q="Onde fica o acampamento madeireiro?",a="O Turner's Logging Camp fica ao norte da fazenda de Cassandra, às margens do rio.",al={"onde fica o acampamento de turner","localização do acampamento","acampamento madeireiro"}},{q="Que produtos Cassandra está enviando?",a="Ela envia frutas e verduras excedentes da fazenda dela.",al={"o que devo entregar","produtos da fazenda","produtos de cassandra"}},{q="Por que Cassandra separa produtos da fazenda?",a="Depois da colheita, Cassandra guarda o que não vende para dar a pessoas que precisam de um incentivo.",al={"por que dar comida","motivo de cassandra","ajudar os vizinhos"}},{q="O que os trabalhadores do acampamento madeireiro costumam comer?",a="Halligan diz que os trabalhadores comem pouco além de carne e pão.",al={"o que os madeireiros comem","comida dos trabalhadores do acampamento","carne e pão"}}},fp="17,168,17.318.0,11.191.1,31.82.0,23.56.0,26.69.0,31.53.0,40.93.0,45.60.0"}
P.entries["quest:95349"] = {n="The Earthen Ring",s="Esta jornada marca a chegada dos Moldavento de Zephras a Azeroth como uma vanguarda avançada após atrasos causados por atividades de sectários em Valanaar. Embarcando em um navio skycutter do lado de fora do pavilhão, os viajantes desembarcam em Mulgore para encontrar Alaana Stormwalker e começar a se aclimatar a um novo mundo vasto e perigoso.",h="Esta jornada marca a chegada dos Moldavento de Zephras a Azeroth como uma vanguarda avançada após atrasos...",kw={"alaana stormwalker","banu-alah","seita","mulgore","skycutter","harmonia telúrica","valanaar","moldavento","zephras"},ang={["class:Shaman"]="Os Moldavento e os Xamãs compartilham uma profunda reverência pelos elementos, confiando no favor dos ventos para guiar sua travessia aérea. Chegar sob o estandarte da Harmonia Telúrica os conecta diretamente às tradições elementais que criam raízes em Mulgore.",["race:Skyborne"]="Para os aventureiros Skyborne que partem de Valanaar, esta jornada marca sua chegada histórica a Azeroth como uma vanguarda avançada. Deixando para trás os problemas causados pela seita em sua terra natal, eles dão seus primeiros passos nos Morros Ondulantes de Mulgore.",["race:Tauren"]="Como zeladores nativos de Mulgore, os Tauren testemunham a chegada de novos viajantes de Zephras descendo sobre suas planícies ancestrais. Acolher esses visitantes vindos dos céus proporciona uma conexão inicial com aliados que estabelecem uma presença em suas terras."},sec={{t="Partida de Valanaar",b="Os viajantes que partem para Azeroth devem ajustar seus planos devido a perturbações recentes causadas por atividades de uma seita em Valanaar. Enquanto os líderes seniores permanecem no pavilhão para concluir assuntos urgentes e conter a ameaça dos sectários, uma pequena vanguarda de Moldavento é enviada à frente. Viajando até as docas do lado de fora do pavilhão, esses pioneiros embarcam em uma embarcação skycutter rumo aos céus. Embora seus comandantes prometam se juntar a eles em breve, a expedição inicial repousa inteiramente sobre os ombros desse grupo avançado, enviado à frente para estabelecer uma presença antes que o restante possa segui-los."},{t="Chegada a Mulgore",b="Ao pousar nos Morros Ondulantes de Mulgore, os aventureiros que chegam de Zephras são recebidos por Alaana Stormwalker. Estabelecer uma presença em Azeroth levará tempo e esforços cuidadosos, incentivando os recém-chegados a fazer o reconhecimento do território ao redor e a se aclimatar ao novo ambiente. Embora os ventos favoreçam a expedição que chega, Azeroth continua sendo um reino desconhecido e perigoso. Familiarizar-se com o terreno local, a vida selvagem e os habitantes vizinhos é um primeiro passo essencial antes que os demais viajantes de Valanaar cheguem para se juntar ao esforço."}},faq={{q="Por que os Moldavento estão viajando para Azeroth?",a="Uma vanguarda de Moldavento é enviada à frente para estabelecer uma presença em Azeroth enquanto seus líderes permanecem em Valanaar. Problemas recentes envolvendo uma seita local desorganizaram os planos originais de viagem, atrasando o restante do grupo. Como resultado, este grupo avançado viaja sozinho para desembarcar e garantir uma posição até que reforços possam segui-los.",al={"por que ir para azeroth","missão dos moldavento","por que os moldavento estão em mulgore"}},{q="Quem é Alaana Stormwalker?",a="Alaana Stormwalker é o contato que aguarda para receber os Moldavento que chegam após o pouso em Mulgore. Ela dá as boas-vindas aos viajantes que chegam de Zephras, observando que estabelecer uma presença segura nestas novas terras exigirá tempo. Enquanto os preparativos começam, ela aconselha os aventureiros recém-chegados a explorar a região ao redor e a se preparar para os perigos de Azeroth.",al={"quem é alaana","papel de alaana stormwalker","onde está alaana stormwalker"}},{q="Por que a partida principal foi adiada?",a="A viagem principal de Valanaar foi adiada devido a eventos preocupantes recentes envolvendo uma seita local. Lidar com essas complicações causadas pelos sectários forçou os líderes da expedição a permanecerem no pavilhão para concluir seus negócios. Em vez de interromper a missão por completo, eles enviaram uma pequena vanguarda de Moldavento a bordo de um skycutter para liderar o caminho até Azeroth.",al={"por que o atraso","qual seita atrasou a viagem","por que ficar em valanaar"}},{q="Como os viajantes vão de Valanaar até Mulgore?",a="Os viajantes fazem a jornada embarcando em um navio skycutter ancorado do lado de fora do pavilhão em Valanaar. Esta embarcação transporta a vanguarda pelos céus até as planícies de Mulgore, servindo como o principal transporte que liga Zephras às terras de Azeroth durante a expedição inicial.",al={"como chegar a mulgore","onde está o navio","como você viaja para azeroth"}},{q="O que é Zephras?",a="Zephras é o lar ou a origem dos aventureiros que chegam a bordo do skycutter. Quando os viajantes chegam a Mulgore, Alaana Stormwalker os identifica como recém-chegados vindos de Zephras, observando que ventos favoráveis guiaram sua travessia para o território desconhecido e perigoso de Azeroth.",al={"onde fica zephras","o que é zephras","história de zephras"}},{q="O que os aventureiros devem fazer ao chegar a Mulgore?",a="Os aventureiros recém-chegados são incentivados a fazer o reconhecimento e explorar as terras ao redor de Mulgore. Como estabelecer uma presença definitiva leva tempo, familiarizar-se com o terreno próximo, as criaturas e as ameaças locais é uma preparação essencial para desbravar este novo mundo empolgante, porém perigoso.",al={"o que fazer em mulgore","próximos passos após chegar","o que fazer a seguir"}}},fp="16,272,23.440.0,18.424.0,45.264.0,26.240.0,35.192.0,50.190.0,16.215.0,52.209.0"}
P.entries["quest:95350"] = {n="Welcome to Azeroth",s="'Boas-vindas a Azeroth' é uma missão introdutória que envia um viajante do Penhasco do Trovão para Orgrimmar em nome dos Moldavento. Guiado pelos laços espirituais da Harmonia Telúrica, o emissário se encontra com o Chefe de Guerra Thrall para forjar laços de sobrevivência e aliança com a Horda.",h="'Boas-vindas a Azeroth' é uma missão introdutória que envia um viajante do Penhasco do Trovão para Orgrimmar...",kw={"harmonia telúrica","horda","orgrimmar","thrall","penhasco do trovão","vale da sabedoria","boas-vindas a azeroth","moldavento"},ang={["class:Shaman"]="Com orientação invocando a Harmonia Telúrica e a bênção dos ventos, esta jornada conecta diretamente parentes espirituais ao coração da liderança xamânica no Vale da Sabedoria.",["faction:Horde"]="Esta missão diplomática oficializa os laços com a Horda, apresentando os recém-chegados diretamente ao Chefe de Guerra Thrall como aliados essenciais para a sobrevivência em Kalimdor.",["race:Skyborne"]="Deixando as grandes altitudes para o mundo da superfície abaixo, os Skyborne Moldavento estendem a mão para o Penhasco do Trovão e Orgrimmar a fim de garantir seu lugar entre novos aliados."},sec={{t="Aliados em um Mundo Mais Amplo",b="Aventureiros que desbravam a vasta extensão de Kalimdor logo descobrem que a sobrevivência depende da fraternidade. Os Moldavento olham além de suas origens isoladas para os povos que caminham abaixo, reconhecendo que o isolamento não oferece defesa contra as ameaças de Azeroth. Ao estender a mão para a cidade tauren vizinha do Penhasco do Trovão e olhar para os bastiões orcs a leste, eles buscam companheiros leais para enfrentar a natureza selvagem juntos."},{t="Uma Audiência com o Chefe de Guerra",b="A jornada conduz os enviados às torres imponentes do Penhasco do Trovão antes de direcioná-los através dos Sertões até Orgrimmar, a poderosa capital da Horda. Aguardando no tranquilo Vale da Sabedoria está o Chefe de Guerra Thrall, o coração que guia a coalizão. Apresentar-se diante de Thrall marca a entrada oficial dos Moldavento no tecido político e espiritual de Kalimdor, unidos por um propósito comum e pelo respeito mútuo pelos elementos."}},faq={{q="Qual é o objetivo da missão Boas-vindas a Azeroth?",a="'Boas-vindas a Azeroth' é uma missão introdutória diplomática que envia um emissário em nome dos Moldavento para se encontrar com o Chefe de Guerra Thrall em Orgrimmar. Ela serve como uma introdução oficial à Horda em geral e ao mundo da superfície de Kalimdor.",al={"o que é esta missão","missão boas-vindas a azeroth","objetivo de boas-vindas a azeroth"}},{q="Quem são os Moldavento?",a="Os Moldavento são um grupo que busca alcançar aliados da superfície a partir de cima, procurando a sobrevivência por meio da irmandade com a Harmonia Telúrica e a Horda. Eles enviam viajantes para falar diretamente com a liderança da Horda em Durotar.",al={"quem são os moldavento","o que são os moldavento"}},{q="Por que você é enviado para falar com Thrall?",a="Como Chefe de Guerra da Horda e um reverenciado líder xamânico, Thrall supervisiona as principais alianças da coalizão a partir do Vale da Sabedoria. Fazer contato com ele oficializa as relações entre os Moldavento e a Horda.",al={"por que visitar thrall","falar com thrall em orgrimmar","por que ir para orgrimmar"}},{q="Como você viaja do Penhasco do Trovão para Orgrimmar?",a="Os viajantes alçam voo a partir do mestre de voo localizado no poleiro central do Penhasco do Trovão, sobrevoando as planícies de Kalimdor para o leste até a fortaleza do desfiladeiro de Orgrimmar.",al={"como chegar a orgrimmar","mestre de voo do penhasco do trovão","como ir do penhasco do trovão a orgrimmar"}},{q="Como a Harmonia Telúrica se encaixa nesta missão?",a="Neste encontro, a Harmonia Telúrica é descrita como alinhada com a coalizão de povos afins da Horda, ajudando a facilitar laços entre facções xamânicas e as nações de Kalimdor.",al={"papel da harmonia telúrica na horda","a harmonia telúrica é da horda"}},{q="Onde Thrall está localizado em Orgrimmar?",a="O Chefe de Guerra Thrall reside no Vale da Sabedoria, um santuário espiritual tranquilo nos limites ocidentais de Orgrimmar onde xamãs e conselheiros tribais se reúnem.",al={"onde está thrall","localização de thrall no vale da sabedoria"}}},fp="18,196,25.303.0,29.350.0,52.156.0,24.200.0,38.208.0,50.154.0,48.142.0,37.139.0"}
P.entries["quest:95384"] = {n="Partial Mystical Notes",s="Um estranho pergaminho mágico traz símbolos que você não consegue ler, mas não contém nenhuma força que pareça volátil. Você o leva a Dudd Fizzlescroll, na Angra do Butim, onde ele vê potencial em sua magia.",h="Um estranho pergaminho mágico traz símbolos que você não consegue ler, mas não contém nenhuma força que...",kw={"angra do butim","dudd fizzlescroll","pergaminho mágico","magia mística","anotações místicas incompletas","pergaminho incompleto","símbolos estranhos"},sec={{t="Símbolos indecifráveis",b="Você encontra um pergaminho mágico coberto de símbolos estranhos, mas não conhece o idioma. A magia parece inofensiva, então você leva o pergaminho incompleto a Dudd Fizzlescroll, na Angra do Butim. Ele reconhece que se trata de uma magia poderosa e planeja traduzi-la para seus registros."}},faq={{q="O que há no pergaminho?",a="O pergaminho mágico traz símbolos estranhos em um idioma que você não fala.",al={"quais símbolos","escrita do pergaminho","anotações místicas"}},{q="O pergaminho parece perigoso?",a="Você não percebe nenhuma força particularmente volátil no pergaminho.",al={"é volátil","o pergaminho é perigoso","magia segura"}},{q="Quem quer o pergaminho?",a="Dudd Fizzlescroll, na Angra do Butim, reconhece a magia do pergaminho e pretende traduzi-lo para seus registros.",al={"quem fica com ele","dudd fizzlescroll","colecionador de pergaminhos"}},{q="Onde devo levar o pergaminho incompleto?",a="Você leva o pergaminho incompleto a Dudd Fizzlescroll, na Angra do Butim.",al={"onde levar o pergaminho","pergaminho da angra do butim","destino do pergaminho"}}},fp="22,180,14.261.0,22.72.0,31.60.0,21.105.0,36.63.0"}
P.entries["quest:95385"] = {n="Torn Mystical Scroll",s="Um pergaminho rasgado traz uma magia tênue e runas desconhecidas. Você o leva a Dudd Fizzlescroll, em Angra do Butim, onde ele vê potencial em sua escrita.",h="Um pergaminho rasgado traz uma magia tênue e runas desconhecidas.",kw={"angra do butim","dudd fizzlescroll","engenharia","magia tênue","pergaminho incompleto","runas","pergaminho místico rasgado"},ang={["profession:Engineering"]="Dudd Fizzlescroll planeja copiar as runas em seu trabalho e fala em se tornar um engenheiro lendário."},sec={{t="Um Fragmento Curioso",b="Uma magia tênue envolve o pergaminho rasgado, e suas runas são estranhas para você. Você não sente perigo nele, embora a maioria chamasse o pergaminho de inútil. Dudd Fizzlescroll, em Angra do Butim, talvez encontre uma utilidade para o fragmento."},{t="O Trabalho de Dudd",b="Dudd Fizzlescroll está ansioso para copiar as runas em seu trabalho. Ele fala em se tornar um engenheiro lendário, depois avisa você para manter distância, para não se machucar."}},faq={{q="O que é o pergaminho rasgado?",a="É um fragmento de pergaminho com magia tênue e runas desconhecidas. Você sente que ele não é perigoso.",al={"pergaminho rasgado","pergaminho místico","o que é este pergaminho"}},{q="Quem quer o pergaminho?",a="Dudd Fizzlescroll, em Angra do Butim, está interessado no pergaminho incompleto.",al={"quem quer o pergaminho","colecionador de pergaminhos","dudd scroll"}},{q="Por que levá-lo a Dudd?",a="Dudd talvez encontre uma utilidade para as runas desconhecidas no pergaminho.",al={"por que dudd","para onde vai o pergaminho","finalidade do pergaminho"}},{q="O pergaminho é perigoso?",a="O pergaminho emana uma magia tênue, mas você intui que ele não é perigoso.",al={"pergaminho seguro","pergaminho perigoso","é mágico"}}},fp="20,139,15.208.0,11.157.1,24.104.0,21.67.0,21.62.0,24.74.0"}
P.entries["quest:954"] = {n="Bashal'Aran",s="Os sátiros demoníacos e os duendes cruéis que infestam a antiga cidade élfica de Bashal'Aran não se aproximam de um santuário banhado por uma aura azul sobrenatural. Trovejius Tecevento, ancião de Auberdine, envia aventureiros para investigar a origem desse refúgio intocado.",h="Os sátiros demoníacos e os duendes cruéis que infestam a antiga cidade élfica de Bashal'Aran não se aproximam...",kw={"astérion","bashal'aran","aura azul","costa negra","duende","ruínas kaldorei","sátiro","trovejius tecevento"},ang={["faction:Alliance"]="Os batedores de Auberdine dependem de aventureiros da Aliança para avançar pelas ruínas disputadas de Costa Negra e neutralizar as ameaças demoníacas antes que cheguem ao litoral.",["race:NightElf"]="Bashal'Aran é um lembrete sombrio das perdas causadas pela Cisão, onde os espíritos remanescentes de seus ancestrais ainda mantêm vigílias solitárias contra a corrupção demoníaca crescente."},sec={{t="Um farol entre as ruínas",b="Bashal'Aran já foi um povoado glorioso do antigo império kaldorei, mas seus mármores despedaçados e arcos cobertos de vegetação agora fervilham de corrupção demoníaca. Sátiros deformados e duendes corrompidos se alimentam avidamente das energias mágicas remanescentes, tornando-se cada vez mais malignos. Apesar do domínio dessas criaturas, Trovejius Tecevento notou algo curioso: no alto de uma elevação a oeste das ruínas, uma aura azul etérea envolve um santuário do qual nenhum demônio se aproxima."},{t="O espectro atormentado",b="Atravessar as patrulhas demoníacas até o santuário elevado revela que a luz azul não é um fenômeno natural. Ela emana de Astérion, um espírito antigo cuja vigília já dura séculos de solidão. Cercado por feras uivantes e demônios vis, o espectro cansado vê até mesmo um viajante desconhecido como um alívio bem-vindo após décadas de isolamento."}},faq={{q="Onde fica a aura azul?",a="A aura azul brilha no topo de uma pequena elevação a oeste das ruínas de Bashal'Aran, a leste de Auberdine, em Costa Negra. O santuário fica um pouco acima das muralhas em ruínas.",al={"encontrar aura azul","onde fica astérion","localização do santuário de bashal'aran"}},{q="Por que os sátiros evitam o santuário?",a="Ninguém sabe ao certo. Uma estranha aura azul envolve o santuário, e os sátiros e duendes demoníacos que infestam as ruínas se recusam a se aproximar. Trovejius Tecevento envia você para descobrir a origem dessa aura.",al={"por que os demônios têm medo","por que os sátiros não se aproximam"}},{q="Quem oferece esta missão?",a="Trovejius Tecevento, um druida elfo noturno e ancião de Auberdine, oferece a missão após observar os movimentos estranhos dos demônios nas ruínas a leste.",al={"quem oferece a missão","quem dá a missão","localização de trovejius tecevento"}},{q="O que é Bashal'Aran?",a="Bashal'Aran é uma antiga ruína kaldorei nas florestas de Costa Negra. Devastada durante a Cisão, ela foi infestada por parasitas mágicos, duendes e sátiros que procuram se alimentar do poder adormecido de seus meridianos mágicos.",al={"o que aconteceu com bashal'aran","história de bashal'aran"}}},fx={["2cba9e48"]={q="Por que Trovejius Tecevento quer que eu investigue Bashal'Aran?",a="Trovejius Tecevento observa as antigas ruínas de Bashal'Aran com um pavor crescente. Espritais e sátiros corrompidos infestam o local, atraindo energias arcanas persistentes para ampliar seu poder demoníaco. No entanto, entre essa infestação, um único santuário envolvido por uma curiosa aura azul permanece totalmente intocado pelos demônios. Trovejius precisa entender qual poder os mantém afastados — e se isso pode ser a chave para repelir a corrupção que avança sobre a Costa Negra.",al={"por que investigar bashal'aran","motivação de thundris","por que me enviar a bashal'aran"}}},fp="11,161,21.382.0,17.245.1,31.192.0,35.147.0,28.136.0,20.171.0"}
P.entries["quest:95417"] = {n="The Purple Ones",s="Clubtoe pede que você procure ogros desaparecidos nas cavernas sob Solclaro. Alguns que voltam estão mudados, e ele quer entender por quê.",h="Clubtoe pede que você procure ogros desaparecidos nas cavernas sob Solclaro.",kw={"cavernas","clubtoe","runas sombrias","ogros desaparecidos","ogros","roxo","solclaro","os roxos","twilight hammer"},sec={{t="A preocupação de Clubtoe",b="Clubtoe viu amigos entrarem nas cavernas sob Solclaro e não voltarem. Alguns retornam roxos e já não agem como seus amigos. Ele pede que você procure os ogros desaparecidos nas cavernas, embora tema que você também volte mudado."},{t="Nas cavernas",b="Sob Solclaro, você encontra um ogro morto entre runas sombrias. Os poderes do ritual do Twilight Hammer o dominaram."}},faq={{q="Quem é Clubtoe?",a="Clubtoe é um ogro cujos amigos desapareceram nas cavernas sob Solclaro.",al={"clubtoe","quem é clubtoe"}},{q="Por que Clubtoe pede que eu procure nas cavernas?",a="Alguns amigos de Clubtoe não voltam das cavernas, e alguns que retornam estão roxos e agem de forma diferente.",al={"ogros desaparecidos","encontrar amigos de clubtoe","ogros das cavernas"}},{q="Onde estão os ogros desaparecidos?",a="Clubtoe pede que você procure os ogros desaparecidos nas cavernas sob Solclaro.",al={"para onde vão os ogros","caverna de solclaro","ogros desaparecidos"}},{q="O que há de estranho nos ogros que voltam?",a="Alguns retornam roxos e já não agem como os amigos de Clubtoe.",al={"ogros roxos","por que roxos","ogros agem estranho"}}},fp="15,138,17.245.0,12.124.1,15.83.0,44.110.0,28.79.0,43.60.0"}
P.entries["quest:95418"] = {n="Spread the Word",s="Clubtoe pede que você leve a cabeça de Chogg'Zac para Tran'gul, em Rog'mar, depois que ele deixar a Twilight's Hammer. A notícia da deserção pode levar mais ogros do culto a se libertarem.",h="Clubtoe pede que você leve a cabeça de Chogg'Zac para Tran'gul, em Rog'mar, depois que ele deixar a...",kw={"chogg'zac","clubtoe","clugfist","deserção de ogro","rog'mar","espalhe a notícia","tran'gul","martelo do crepúsculo"},sec={{t="Uma mensagem para Tran'gul",b="A cabeça de Chogg'Zac deve voltar para seus amigos, e Tran'gul, em Rog'mar, é quem deve recebê-la. Clubtoe diz que rompeu com a Twilight's Hammer e planeja se juntar a Clugfist, o maior ogro que conhece, junto com muitos outros. Clubtoe pretende ficar onde está até que o caminho esteja livre. Agora, Tran'gul precisa saber o que Clubtoe decidiu."},{t="Notícias da caverna",b="Tran'gul fica sabendo que a caverna guardava outra surpresa. Você convenceu um dos ogros do Martelo do Crepúsculo a desertar, e ele falou de outros da sua espécie. Tran'gul diz que precisam agir imediatamente com base nessa notícia."}},faq={{q="Quem é Clubtoe?",a="Clubtoe é um ogro que diz que já cansou do Martelo do Crepúsculo e planeja se juntar aos ogros livres.",al={"clubtoe","ogro clubtoe","quem é clubtoe"}},{q="Quem é Clugfist?",a="Clugfist é o maior ogro que Clubtoe conhece, e Clubtoe diz que ele deixou o Martelo do Crepúsculo com muitos amigos.",al={"clugfist","ogro clugfist","maior ogro"}},{q="O que Clubtoe me pede para levar?",a="Clubtoe pede que você leve a cabeça de Chogg'Zac de volta aos amigos dele.",al={"cabeça de chogg","cabeça de chogg'zac","o que levar"}},{q="Onde devo levar a cabeça de Chogg'Zac?",a="Você deve entregar a cabeça de Chogg'Zac a Tran'gul, em Rog'mar.",al={"onde levar a cabeça","tran'gul","rog'mar"}},{q="Por que Tran'gul está preocupado?",a="Tran'gul fica sabendo que um ogro do Martelo do Crepúsculo desertou e mencionou outros da sua espécie.",al={"reação de tran'gul","caverna do crepúsculo","por que agir agora"}}},fp="15,178,22.329.0,18.202.1,15.99.0,16.109.0,34.62.0,33.59.0,26.94.0"}
P.entries["quest:95420"] = {n="Land of Giants",s="Um orc pede que você leve a cabeça de Chogg a uma cidade ogra nas colinas do norte. A oferenda pode abrir caminho para renovar um antigo vínculo com os ogros.",h="Um orc pede que você leve a cabeça de Chogg a uma cidade ogra nas colinas do norte.",kw={"chogg","chogg’zac","clugfist","terra dos gigantes","colinas do norte","cidade ogra","ogros","aliança orc"},ang={["race:Orc"]="Como orc, você leva uma oferta enraizada na honrada história de orcs lutando ao lado dos ogros."},sec={{t="Um vínculo antigo",b="Os orcs veem uma chance de renovar sua antiga aliança com os ogros. Relatos situam o lar do clã em uma fortaleza entre as colinas do norte, e a cabeça de Chogg deve falar por você. Leve-a à cidade ogra e ofereça-a como símbolo de amizade. O clã talvez ouça sua proposta, se não pisoteá-lo antes."},{t="À porta de Clugfist",b="Na cidade ogra, você apresenta a cabeça de Chogg a Clugfist. Ele reconhece que você derrotou Chogg’Zac e pergunta o que você quer com ele. A oferta de amizade abriu uma oportunidade para falar com o líder do clã."}},faq={{q="Por que estou levando a cabeça de Chogg aos ogros?",a="Os orcs esperam que a cabeça de Chogg sirva como símbolo de amizade e ajude a renovar sua antiga aliança com os ogros.",al={"cabeça de chogg","por que levar a cabeça de chogg","oferenda da cabeça de ogro"}},{q="Onde fica o lar do clã ogro?",a="Relatos situam a fortaleza do clã nas colinas, bem ao norte.",al={"localização da cidade ogra","onde ficam os ogros","ogros das colinas do norte"}},{q="Quem é Clugfist?",a="Clugfist é o enorme ogro que você encontra na cidade ogra. Ele pergunta o que você quer com ele.",al={"quem é clugfist","líder ogro","clug fist"}},{q="Quem é Chogg’Zac?",a="Chogg’Zac é o ogro que Clugfist diz que você derrotou.",al={"chogg zac","história de chogg","quem é chogg"}},{q="O que os orcs querem dos ogros?",a="Os orcs esperam recorrer à sua antiga aliança com os ogros e apresentar uma proposta ao clã.",al={"aliança entre orcs e ogros","o que os orcs querem","amizade com ogros"}}},fp="14,143,11.313.0,20.218.1,46.114.0,32.68.0,16.87.0,19.56.0,37.92.0"}
P.entries["quest:95424"] = {n="Might Makes Right",s="Clugfist desafia você a provar sua força em Bolder'ok. Os ogros do Martelo do Crepúsculo são o teste.",h="Clugfist desafia você a provar sua força em Bolder'ok.",kw={"bolder'ok","clugfist","a força faz o direito","ogros","skyborne","twilight firecallers","twilight maulers","martelo do crepúsculo"},sec={{t="O teste de Clugfist",b="Clugfist mede a força pelo sangue e manda você enfrentar os Twilight Maulers e os Twilight Firecallers em Bolder'ok. Ele duvida do seu tamanho, mas lhe dá a chance de mostrar do que você é capaz. O desafio põe sua força à prova contra os ogros do Crepúsculo."}},faq={{q="Quem é Clugfist?",a="Clugfist é o ogro de Bolder'ok que desafia você a provar sua força.",al={"clugfist","quem é clugfist","cara ogro"}},{q="O que Clugfist quer que eu faça?",a="Clugfist pede que você mate Twilight Maulers e Twilight Firecallers em Bolder'ok.",al={"o que clugfist quer","tarefa de clugfist","o que devo matar"}},{q="Por que Clugfist duvida de mim?",a="Clugfist chama você de minúsculo e questiona se você é forte.",al={"por que duvida de mim","pequeno demais","clugfist me acha fraco"}},{q="Como é Bolder'ok?",a="Bolder'ok é o lugar onde Clugfist diz que os ogros valorizam a força e o sangue.",al={"bolderok","ogros de bolder'ok","o que acontece aqui"}}},fp="17,98,15.248.0,16.76.0,33.81.0,27.61.0,23.64.0"}
P.entries["quest:95425"] = {n="Unworthy Champion",s="Clugfist em Bolder'ok quer que você recupere Skullbasher de Klunk. Ele já não considera Klunk digno da arma.",h="Clugfist em Bolder'ok quer que você recupere Skullbasher de Klunk.",kw={"bolder'ok","caverna","clugfist","klunk","campeão ogro","skullbasher","martelo do crepúsculo"},sec={{t="A exigência de Clugfist",b="Clugfist manda você atrás de Klunk, que deixou Bolder'ok e levou ogros consigo para uma caverna a leste da água. Ele quer sua arma de volta e chama Klunk de fraco. Aos olhos de Clugfist, Skullbasher é a marca de um campeão, e ele pretende escolher outro."}},faq={{q="Quem é Klunk?",a="Klunk já foi o campeão de Clugfist, mas agora Clugfist o considera fraco.",al={"quem é klunk","história de klunk"}},{q="Quem é Clugfist?",a="Clugfist é o ogro que deu uma arma poderosa a Klunk e agora quer recuperá-la.",al={"quem é clugfist","ogro clugfist"}},{q="Por que Clugfist quer Skullbasher?",a="Clugfist diz que Skullbasher pertence a ele e considera Klunk indigno da arma.",al={"por que pegar skullbasher","arma de clugfist"}},{q="Para onde Klunk foi?",a="Klunk saiu de Bolder'ok com ogros e foi para uma caverna a leste da água.",al={"localização de klunk","para onde klunk foi"}},{q="O que é Skullbasher?",a="Skullbasher é a arma poderosa que Clugfist deu a Klunk.",al={"arma skullbasher","arma de klunk"}},{q="O que Clugfist planeja fazer em seguida?",a="Clugfist diz que um dia escolherá um novo campeão.",al={"novo campeão","planos de clugfist"}}},fp="17,117,17.240.0,13.68.0,16.74.0,35.72.0,19.69.0,20.53.0,35.52.0"}
P.entries["quest:95426"] = {n="Rog'mar Supplies",s="Um contato local pede que você atrapalhe Rog'mar roubando remessas de suprimentos dos campos de treinamento ao norte do acampamento. O atraso pode deixar as forças da Horda menos preparadas para a batalha.",h="Um contato local pede que você atrapalhe Rog'mar roubando remessas de suprimentos dos campos de treinamento...",kw={"horda","rog'mar","remessa","suprimentos","entrega de suprimentos","campos de treinamento"},sec={{t="Falta de suprimentos",b="Um contato perto de Rog'mar vê uma chance de desacelerar o crescimento dos orcs. Você deve roubar as remessas de suprimentos dos campos de treinamento ao norte de Rog'mar. As entregas de suprimentos são difíceis por aqui, e o roubo deve atrasar os preparativos da Horda para a batalha."}},faq={{q="O que devo fazer?",a="Você deve roubar as remessas de suprimentos da Horda dos campos de treinamento ao norte de Rog'mar.",al={"suprimentos de rog'mar","roubar remessas","roubo de suprimentos"}},{q="Por que roubar os suprimentos?",a="O roubo pretende atrasar o crescimento de Rog'mar e impedir que as forças da Horda estejam tão preparadas para a batalha.",al={"por que roubar suprimentos","desacelerar rog'mar","suprimentos da horda"}},{q="Onde estão as remessas?",a="As remessas de suprimentos da Horda estão nos campos de treinamento ao norte de Rog'mar.",al={"onde estão os suprimentos","campos de treinamento","ao norte de rog'mar"}}},fp="16,168,17.258.0,28.86.0,22.101.0,24.70.0"}
P.entries["quest:95427"] = {n="Twilight No More!",s="Clubtoe pede que você enfrente Chogg'Zac na caverna de Solclaro. Ele os culpa pela morte dos amigos e pela promessa de fortalecer os ogros.",h="Clubtoe pede que você enfrente Chogg'Zac na caverna de Solclaro.",kw={"caverna","chogg'zac","clubtoe","amigos","ogros","solclaro","crepúsculo"},sec={{t="O apelo de Clubtoe",b="Clubtoe diz que seus amigos morreram e culpa Chogg'Zac. Eles prometeram fortalecer os ogros, mas ele diz que mentiram. Então, pede sua ajuda para se voltar contra eles na caverna de Solclaro. Ele quer as cabeças deles e não vai mais quebrar pedras para eles."},{t="Um novo nome",b="Depois que Chogg'Zac morrem, Clubtoe grita em triunfo. Ele diz que acabou de quebrar pedras para os pequeninos e de perder amigos. Ele se declara livre do Crepúsculo."}},faq={{q="Quem é Clubtoe?",a="Clubtoe é um ogro que diz que Chogg'Zac prometeu fortalecer os ogros. Ele os culpa pela morte dos amigos.",al={"clubtoe","quem é clubtoe","história de clubtoe"}},{q="Por que Clubtoe quer Chogg'Zac mortos?",a="Clubtoe diz que Chogg'Zac mentiu sobre fortalecer os ogros e os culpa pela morte dos amigos.",al={"por que matar chogg'zac","motivo de chogg zac","missão de chogg'zac"}},{q="Onde está Chogg'Zac?",a="Chogg'Zac está na caverna de Solclaro.",al={"localização de chogg'zac","onde fica chogg zac","caverna de solclaro"}},{q="O que Clubtoe quer de você?",a="Clubtoe pede que você mate Chogg'Zac e recolha as cabeças deles.",al={"o que clubtoe quer","o que conseguir para clubtoe","cabeças para clubtoe"}}},fp="17,141,14.247.0,10.155.1,15.108.0,37.94.0,20.37.0,32.59.0"}
P.entries["quest:95428"] = {n="Clugfist's Decree",s="Clugfist permite que você fique em Bolder'ok por enquanto, depois que os Skyborne derrotam a Twilight's Hammer. Ele pede que você avise aos outros que o clã voltará a lutar em breve.",h="Clugfist permite que você fique em Bolder'ok por enquanto, depois que os Skyborne derrotam a Twilight's...",kw={"bolder'ok","bolderok","clugfist","decreto","horda","krom'rosh","rog'mar","skyborne","twilight's hammer"},ang={["faction:Horde"]="Como membro da Horda, você pode ver os Bolder'ok se tornarem aliados poderosos se seu povo continuar conquistando a confiança deles."},sec={{t="Mensagem para Rog'mar",b="Krom'rosh, em Rog'mar, espera notícias suas. Clugfist permite que você fique em Bolder'ok por enquanto e pede que leve a mensagem aos outros Skyborne. O clã espera voltar a derramar sangue em breve."},{t="Confiança e alianças",b="Krom'rosh vê o clã Bolder'ok como um possível aliado da Horda. A recente luta deles por liberdade contra a Twilight's Hammer ecoa a própria história sangrenta da Horda. Seu relato pode ajudar a Horda a continuar conquistando a confiança deles."}},faq={{q="O que Clugfist quer que eu faça?",a="Clugfist pede que você avise aos outros Skyborne que o clã Bolder'ok espera voltar a lutar em breve.",al={"decreto de clugfist","o que devo relatar","ordens de clugfist"}},{q="Onde devo me apresentar?",a="Clugfist orienta você a se apresentar a Krom'rosh, em Rog'mar.",al={"apresentar-se a kromrosh","onde fica krom'rosh","relato para rogmar"}},{q="Posso ficar em Bolder'ok?",a="Clugfist permite que você fique em Bolder'ok por enquanto.",al={"ficar em bolderok","clugfist me deixa ficar","permissão para ficar em bolder'ok"}},{q="Quem são os Bolder'ok?",a="Os Bolder'ok são um clã que lutou recentemente por liberdade contra a Twilight's Hammer.",al={"clã bolder'ok","quem é clugfist","povo de clugfist"}},{q="Por que a Horda se importa com os Bolder'ok?",a="Krom'rosh acredita que os Bolder'ok podem se tornar aliados poderosos se a Horda continuar conquistando a confiança deles.",al={"horda e bolder'ok","aliados bolder'ok","por que kromrosh se importa"}}},fp="17,168,16.182.0,19.225.1,33.97.0,18.55.0,24.52.0,22.85.0,44.105.0"}
P.entries["quest:95432"] = {n="Rise Up!",s="Crag'rog pede que você ajude a libertar ogros da Twilight. Ele quer que eles voltem para casa para comer ensopado.",h="Crag'rog pede que você ajude a libertar ogros da Twilight.",kw={"crag'rog","libertar ogros","mineradores ogros","ogros","ergam-se","ensopado","twilight"},sec={{t="Ogros e Twilight",b="Crag'rog quer libertar os ogros da Twilight e aceita sua ajuda. Juntos, vocês recrutam mineradores ogros para se juntarem à luta. Crag'rog diz que então os ogros poderão voltar para casa para comer ensopado."},{t="A contagem de Crag'rog",b="Crag'rog diz que muitos ogros estão livres e que os ogros fracos e covardes estão mortos. Ele conta apenas um ogro covarde restante."}},faq={{q="Quem é Crag'rog?",a="Crag'rog é um ogro que quer libertar os ogros da Twilight.",al={"cragrog","quem é crag'rog"}},{q="Por que Crag'rog quer libertar os ogros?",a="Ele ouviu dizer que você estava libertando ogros e agora também quer libertá-los.",al={"por que libertar ogros","liberdade dos ogros"}},{q="Ao lado de quem Crag'rog luta?",a="Crag'rog luta contra a Twilight ao seu lado.",al={"quem ajuda crag'rog","classe pequena"}},{q="O que Crag'rog pede que você recrute?",a="Crag'rog pede que você recrute mineradores ogros.",al={"recrutar ogros","mineradores ogros"}},{q="O que Crag'rog diz sobre os ogros depois?",a="Crag'rog diz que muitos ogros estão livres e que resta apenas um ogro covarde.",al={"o que aconteceu com os ogros","conclusão de crag'rog"}}},fp="8,89,18.176.0,16.112.1,16.60.0,37.67.0,34.43.0,38.41.0,49.70.0"}
P.entries["quest:95433"] = {n="Death to the Executioner",s="Clugfist pede que você enfrente Morg, o ogro que guarda a saída de Twilight. Ele quer que a maça de Morg seja devolvida a Bolder’ok.",h="Clugfist pede que você enfrente Morg, o ogro que guarda a saída de Twilight.",kw={"bolder'ok","clugfist","crag'rog","morg carrasco","maça do carrasco","morg","twilight shroud","twilight's hammer"},ang={["race:Tauren"]="Como tauren, Clugfist chama você de tauren minúsculo cheio de truques depois que Morg morre."},sec={{t="Uma saída",b="Clugfist, em Bolder’ok, pede que você enfrente Morg no Twilight Shroud. O carrasco é um ogro quase tão grande quanto Clugfist, e Clugfist diz que conta com aliados menores para protegê-lo. Traga a maça de volta para ele, e Twilight’s Hammer saberá que os ogros não os desafiam mais."},{t="A resposta de Bolder’ok",b="Crag’rog diz que você se juntou a ele na luta, e Clugfist pergunta o que você trouxe. Morg está morto, e Clugfist elogia seus truques. Ele diz que Twilight’s Hammer sucumbiu diante do poder de Bolder’ok, e os ogros estão livres."}},faq={{q="Quem é Morg?",a="Morg é um carrasco no Twilight Shroud, um ogro quase tão grande quanto Clugfist.",al={"quem é morg","morg carrasco","ogro de twilight"}},{q="Por que Clugfist quer Morg morto?",a="Clugfist diz que Morg está no caminho enquanto ele deixa Twilight e que Morg conta com aliados menores para protegê-lo.",al={"por que matar morg","clugfist quer morg","problema com morg"}},{q="O que Clugfist quer que você traga de volta?",a="Clugfist quer que a Maça do Carrasco de Morg seja devolvida a ele em Bolder’ok.",al={"maça de morg","o que trazer de volta","maça do carrasco"}},{q="Onde fica Morg?",a="Morg fica no Twilight Shroud.",al={"localização de morg","onde fica o carrasco","twilight shroud"}}},fp="24,122,9.288.0,22.227.1,12.83.0,33.114.0,42.76.0,14.31.0"}
P.entries["quest:95494"] = {n="Bruised Pride and Lion Hides",s="Bruised Pride and Lion Hides é uma tarefa para ajudar um caçador ou comerciante ferido que precisa de peles cruas de leão para cumprir um acordo comercial com um curtidor local. Incapaz de caçar em segurança devido aos seus ferimentos, ele depende de aventureiros viajantes para entregar os materiais e preservar seu histórico profissional impecável.",h="Bruised Pride and Lion Hides é uma tarefa para ajudar um caçador ou comerciante ferido que precisa de peles...",kw={"bruised pride and lion hides","caça","artigos de couro","couros de leão","curtidor","comércio"},sec={{t="O Dilema de um Caçador",b="Bruised Pride and Lion Hides envolve ajudar um caçador ferido que está impossibilitado de rastrear feras selvagens devido a danos físicos recentes. Para evitar falhar em um acordo comercial contínuo com um artesão da região, ele contrata um aventureiro para caçar leões selvagens e coletar suas peles."},{t="Honrando o Acordo",b="Os couros crus recolhidos são trocados com um curtidor local por equipamentos de couro acabados, necessários para o sustento de quem concedeu a missão. Apesar de estar ferido e ter seu orgulho abalado por precisar de ajuda externa, honrar o trato garante que sua reputação profissional permaneça intacta."}},faq={{q="Sobre o que é esta missão?",a="Os couros de leão são reunidos para um caçador ou comerciante ferido que fornece matérias-primas a um curtidor local. Em troca dos couros, quem concede a missão recebe artigos acabados de couro essenciais para o seu sustento.",al={"o que é bruised pride and lion hides","objetivo da missão","para que servem os couros de leão"}},{q="Por que quem concede a missão precisa de ajuda para coletar couros?",a="Quem concede a missão sofreu um ferimento e não pode caçar os leões por conta própria. Em vez de quebrar um acordo comercial de longa data com um curtidor local, confia em aventureiros para realizar a entrega.",al={"por que precisa de ajuda","por que não pode caçar"}},{q="Quem recebe os couros de leão?",a="Os couros crus são negociados com um curtidor local. O curtidor os transforma em produtos de couro acabados de que quem concedeu a missão precisa para o seu comércio e trabalho regulares.",al={"quem recebe os couros de leão","para onde vão os couros"}},{q="O que significa o nome 'Bruised Pride and Lion Hides'?",a="O título faz um trocadilho com ambos os termos: uma alcatéia ou bando de leões (pride) que deve ser caçado e o orgulho (pride) pessoal do caçador ferido, que nunca falhou em cumprir um contrato, apesar de suas limitações físicas atuais.",al={"significado de bruised pride","por que se chama bruised pride"}},{q="O acordo com o curtidor esteve em risco?",a="Sim. O ferimento impede que quem oferece a missão cace, colocando em risco sua próxima entrega. Coletar os couros de leão permite que a parte dele no acordo seja cumprida sem ficar devendo.",al={"o acordo com o curtidor se mantém","acordo comercial quebrado"}},{q="Como quem concedeu a missão se feriu?",a="Quem concedeu a missão sofreu um ferimento que impede a caça de leões na natureza, embora a causa exata do machucado não seja detalhada. Entregar os couros permite que sua reputação seja preservada.",al={"ferimento de quem concede a missão","o que aconteceu com o caçador"}}},fp="28,174,18.195.0,24.236.0,25.157.0,51.130.0,28.128.0,55.170.0,44.136.0,32.171.0"}
P.entries["quest:95495"] = {n="The Hermit Tanner",s="The Hermit Tanner é uma missão local de entrega nos Sertões, onde aventureiros levam um fardo de couros crus para um artesão recluso que vive no topo de uma crista com vista para os Montes Áridos. A tarefa destaca as parcerias de trabalho remotas da savana e apresenta um eremita isolado e marcante que mantém comércio regular apesar de seu isolamento.",h="The Hermit Tanner é uma missão local de entrega nos Sertões, onde aventureiros levam um fardo de couros crus...",kw={"sertoes","pacote de peles","montes áridos","the hermit tanner","crista","curtidor","vrang"},ang={["faction:Horde"]="Viajantes pela savana central frequentemente ajudam comerciantes locais como Vrang no transporte de mercadorias essenciais pelo terreno acidentado dos Sertões."},sec={{t="Uma Crista nos Sertões",b="A savana acidentada dos Sertões fomenta o comércio entre pessoas resilientes, embora nem todos os artesãos prefiram a atmosfera movimentada de encruzilhadas ou povoados. À sombra dos Montes Áridos, um comerciante chamado Vrang troca mercadorias regularmente com um curtidor recluso que estabeleceu uma propriedade tranquila no topo da crista que se eleva acima da região. Como a subida íngreme pela encosta rochosa é cansativa demais para Vrang realizar, ele conta com aventureiros que passam pelo local para transportar fardos de peles brutas até seu parceiro isolado."},{t="Um Artesão Pouco Convencional",b="Antes de mandar os viajantes a caminho, Vrang faz questão de dar um aviso enfático a respeito do artesão solitário. O eremita possui uma aparência alarmante e incomum que pode assustar visitantes desavisados, embora Vrang insista que o curtidor recluso não representa perigo aos visitantes. Ao receber os couros crus em sua propriedade na crista, o eremita recebe o mensageiro calorosamente, embora lamente que Vrang não tenha conseguido fazer a subida, pois ainda há um assunto que ele esperava discutir pessoalmente com o comerciante."}},faq={{q="Quem envia você nesta entrega?",a="Um comerciante chamado Vrang organiza esta tarefa, pedindo a um viajante que passa por ali que entregue um fardo de couros crus a um parceiro de negócios situado no alto da crista.",al={"quem entrega the hermit tanner","onde comecar missao","entrega de vrang"}},{q="Onde vive o eremita curtidor?",a="O eremita curtidor vive sozinho em uma propriedade isolada no topo da crista alta com vista para os Montes Áridos, nos Sertões.",al={"localizacao de the hermit tanner","onde fica the hermit tanner","eremita da crista"}},{q="Por que Vrang avisa você sobre a aparência do curtidor?",a="Vrang avisa os viajantes com antecedência para não se assustarem com a aparência incomum ou perturbadora do curtidor, jurando que, apesar do seu aspecto, o recluso não representa nenhuma ameaça aos visitantes.",al={"aparencia do eremita","por que eremita assustador","aparência do eremita"}},{q="Por que Vrang não conseguiu fazer a subida?",a="Vrang explica que fazer a subida íngreme pela encosta acidentada é algo que ele não consegue realizar facilmente por conta própria no momento, levando-o a contratar um mensageiro.",al={"por que precisa de entrega","por que vrang nao pode ir"}},{q="Quais itens estão sendo entregues na crista?",a="A entrega consiste em um pacote de peles destinado ao trabalho de curtimento do eremita, um ofício no qual as duas figuras cooperam regularmente.",al={"o que e pacote de peles","itens de missao entregues"}},{q="O que o eremita curtidor deseja discutir com Vrang?",a="Ao receber a entrega, o curtidor lamenta que Vrang não tenha podido subir pessoalmente, ressaltando que há um assunto sobre o qual precisa conversar diretamente com ele.",al={"o que o curtidor quer com vrang","negocios do curtidor com vrang"}}},fp="17,169,22.210.0,27.293.0,31.100.0,34.108.0,54.122.0,42.107.0,44.89.0,55.101.0"}
P.entries["quest:955"] = {n="Bashal'Aran",s="Astérion, um pesaroso fantasma altaneiro que assombra as ruínas antigas de Bashal'Aran, busca uma maneira de desfazer a magia vinculatória que prende sua forma espectral. Acreditando que os travessos grells locais tocaram no selo que o aprisiona, ele encarrega viajantes de coletar seus brincos para rastrear a ressonância mágica residual.",h="Astérion, um pesaroso fantasma altaneiro que assombra as ruínas antigas de Bashal'Aran, busca uma maneira de...",kw={"astérion","bashal'aran","a vinculação","costa negra","fantasma","grell","brinco de capeta","selo"},ang={["class:Mage"]="O método de Astérion de usar adornos encantados para rastrear emanações mágicas residuais reflete práticas antigas de adivinhação arcana dos Altaneiros.",["faction:Alliance"]="Eliminar os caóticos grells ao redor de Bashal'Aran ajuda a pacificar os traiçoeiros trechos do norte de Costa Negra para a Aliança.",["race:NightElf"]="Para os Kaldorei, encontrar Astérion é um lembrete solene da antiga civilização que sucumbiu durante a Cisão, deixando almas torturadas presas em ruínas por milênios."},sec={{t="Um tormento secular",b="Em meio ao mármore despedaçado de Bashal'Aran vaga Astérion, um antigo espírito de Elfo Noturno que suportou séculos de confinamento. Preso entre a vida e a verdadeira morte, sua existência reduziu-se a uma espera agonizante sob a copa de Costa Negra. Preso diretamente ao assentamento em ruínas por feitiçaria arcana, Astérion carece de meios para dispersar seus grilhões sozinho, com a mente desgastada por incontáveis anos de solidão e desespero."},{t="Rastros na natureza",b="Astérion suspeita que a chave para sua libertação seja um selo antigo escondido em algum lugar das ruínas. Embora ele próprio não possa vasculhar fisicamente os arbustos e as pedras desmoronadas, os ferozes grells que infestam Bashal'Aran vasculham e roubam constantemente pequenas quinquilharias. Astérion pede aos viajantes que coletem os brincos usados por essas criaturas, pretendendo ler as impressões mágicas residuais nos adornos e localizar o selo que mantém sua alma em tormento."}},faq={{q="Quem é Astérion?",a="Astérion é um antigo fantasma de Elfo Noturno vinculado às ruínas de Bashal'Aran, em Costa Negra. Aprisionado por séculos por um selo místico, ele viu as eras passarem em tormento enquanto anseia pela libertação de seu estado espectral.",al={"história de astérion","quem é o fantasma em bashal'aran","dador de missões astérion"}},{q="Por que Astérion quer brincos de grell?",a="Grells são carniceiros notórios que acumulam bugigangas brilhantes e joias. Astérion acredita que as criaturas manipularam o selo mágico que o vincula, o que significa que seus brincos usados podem carregar resíduos mágicos suficientes para ajudá-lo a localizá-lo.",al={"por que brincos de grell","propósito do brinco de grell","missão dos brincos costa negra"}},{q="O que é Bashal'Aran?",a="Bashal'Aran é uma antiga ruína de Elfo Noturno localizada ao longo da costa florestal de Costa Negra, datada de antes da Grande Cisão. Ela foi invadida por grells selvagens, sátiros e vestígios espectrais de seus habitantes caídos há muito tempo.",al={"o que é bashal'aran","história de bashal'aran","ruínas de bashal'aran"}},{q="O que acontece após coletar os brincos?",a="Astérion examina os brincos e pressente que, embora os grells não carreguem o selo em si, eles esbarraram nele no que ele considera tempos relativamente recentes. Esse rastro permite que ele diminua as possibilidades de localização dentro das ruínas.",al={"o que os brincos mostram","os grells tinham o selo","resultado do brinco de grell"}},{q="Por que Astérion está preso aqui?",a="Astérion foi vinculado a Bashal'Aran por um antigo selo mágico criado séculos atrás. A vinculação ancora seu espírito ao local físico das ruínas, impedindo-o de seguir em frente para um descanso tranquilo.",al={"quem vinculou astérion","como astérion está vinculado","selo de astérion"}},{q="O que são grells?",a="Grells são pequenas e maliciosas criaturas da floresta nativas das matas de Kalimdor. Conhecidos por sua natureza travessa, garras afiadas e amor por quinquilharias, eles frequentemente infestam ruínas antigas e atacam viajantes que passam.",al={"o que é um grell","história dos grells","grells de costa negra"}}},fx={["99bf1a9e"]={q="Por que Astérion quer que isso seja feito?",a="Astérion está preso em uma forma espectral agonizante, ancorado às ruínas de Bashal'Aran por um antigo selo mágico. Séculos de confinamento corroeram lentamente sua sanidade, e ele anseia por se libertar desse tormento. Ao inspecionar os brincos carregados pelas criaturas locais, ele espera usar a vidência mágica para encontrar a localização exata da barreira que o prende, para que ela possa ser finalmente destruída.",al={"motivação de astérion","por que ajudar astérion","por que astérion quer os brincos"}},a8a71265={q="Por que Astérion precisa da sua ajuda em vez de agir por conta própria?",a="Astérion é um fantasma insubstancial ligado diretamente às ruínas por uma feitiçaria poderosa. Incapaz de se aventurar muito além de seu local de descanso imediato ou de lutar fisicamente contra os grells e espritais, ele depende inteiramente dos mortais que passam pelo local para caçar as criaturas e coletar suas bugigangas para suas adivinhações.",al={"por que astérion precisa de mim","por que astérion não consegue os brincos","por que astérion não pode sair"}}},fp="11,257,23.299.0,18.346.0,16.183.0,38.133.0,20.187.0,43.223.1,29.145.0,16.164.0"}
P.entries["quest:95507"] = {n="Vrang's Game",s="Vrang pede que você verifique suas armadilhas por um vale nos Sertões. A caça pequena que elas capturarem vai ajudá-lo, mas outros animais podem tornar a área perigosa.",h="Vrang pede que você verifique suas armadilhas por um vale nos Sertões.",kw={"sertões","caça pequena","caça capturada","armadilhas","vale","vrang","vida selvagem"},sec={{t="Armadilhas de Vrang",b="Vrang espalhou armadilhas pelo vale e pede que você traga a caça pequena que elas tiverem capturado. Ele avisa que outros animais podem tornar a área perigosa se você perder a atenção."}},faq={{q="O que Vrang quer?",a="Vrang pede que você verifique suas armadilhas e traga a caça pequena que elas tiverem capturado.",al={"armadilhas de vrang","caça de vrang","do que vrang precisa"}},{q="Onde ficam as armadilhas de Vrang?",a="Vrang diz que suas armadilhas estão espalhadas pelo vale nos Sertões.",al={"onde ficam as armadilhas","localização das armadilhas","armadilhas nos sertões"}},{q="O que é perigoso perto das armadilhas?",a="Vrang avisa que outros animais da área podem ser perigosos se você não prestar atenção.",al={"perigo por perto","outros animais","perigo da vida selvagem"}}},fp="12,154,13.185.0,21.82.0,24.59.0,35.81.0"}
P.entries["quest:95508"] = {n="Unwelcome Guests",s="Alguém agradece por você ter ajudado essa pessoa a sobreviver a um encontro com visitantes indesejados. A gratidão é clara, mas o problema que os uniu não é descrito.",h="Alguém agradece por você ter ajudado essa pessoa a sobreviver a um encontro com visitantes indesejados.",kw={"dívida","ajuda","sobreviver","agradecimento","visitantes indesejados"},faq={{q="O que aconteceu aqui?",a="A pessoa diz que você a ajudou a sobreviver, mas não dá detalhes sobre o encontro.",al={"o que aconteceu","visitantes indesejados","problemas com visitantes"}},{q="Quem está me agradecendo?",a="O texto de conclusão não identifica quem está falando.",al={"quem é essa pessoa","quem me agradeceu","doador da missão"}},{q="Por que essa pessoa está em dívida comigo?",a="Ela diz que você a ajudou a sobreviver, mas não explica o que aconteceu.",al={"por que agradecer","por que me deve","ajudei essa pessoa"}}},fp="16,128,19.82.0,19.40.0,24.77.0"}
P.entries["quest:95534"] = {n="Strahnbrad Mystery",s="Um bilhete chamuscado pede que você investigue atividades estranhas perto dos velhos foles em Strahnbrad. Relate o que descobrir em Eira dos Montes.",h="Um bilhete chamuscado pede que você investigue atividades estranhas perto dos velhos foles em Strahnbrad.",kw={"elemental de fogo","magia de fogo","eira dos montes","velhos foles","bilhete chamuscado","strahnbrad","mistério de strahnbrad"},sec={{t="O bilhete chamuscado",b="Um bilhete encontrado em Strahnbrad avisa que os velhos foles parecem se mover quando ninguém está olhando. Quem o escreveu descarta o relato como uma história de fantasmas, mas insiste que você descubra a verdade antes de seu retorno. Essa pessoa acredita que há um grande poder em Strahnbrad, e magia de fogo queimou o restante da mensagem."},{t="Suas descobertas",b="Em Eira dos Montes, os moradores ouvem seu relato sobre os velhos foles em Strahnbrad. Um elemental de fogo vivia dentro deles, mas como foi parar ali continua sendo um mistério."}},faq={{q="O que há de estranho nos velhos foles?",a="Um bilhete chamuscado afirma que os velhos foles em Strahnbrad ganham vida quando ninguém está olhando.",al={"mistério dos velhos foles","foles se movendo","foles de strahnbrad"}},{q="Quem deixou o bilhete?",a="O bilhete não identifica quem o escreveu; diz que essa pessoa voltará.",al={"quem escreveu o bilhete","autor do bilhete chamuscado","bilhete misterioso"}},{q="O que o bilhete diz sobre Strahnbrad?",a="Quem escreveu o bilhete acredita que há um grande poder em Strahnbrad.",al={"poder em strahnbrad","grande poder ali","o que há em strahnbrad"}},{q="Onde devo relatar o que descobrir?",a="Você deve relatar suas descobertas na cidade em Eira dos Montes.",al={"onde relatar descobertas","relato em eira dos montes","relatar na cidade"}}},fp="18,128,15.291.0,13.167.1,38.90.0,18.60.0,40.51.0,30.59.0"}
P.entries["quest:95561"] = {n="Apple of My Eye",s="Na Bastilha de Ermoforte, Tessa Dawnbright pede que você encontre maçãs para a exigente bebê Emma. Ela espera preparar uma papinha para a criança.",h="Na Bastilha de Ermoforte, Tessa Dawnbright pede que você encontre maçãs para a exigente bebê Emma.",kw={"papinha de maçã","maçã dos meus olhos","bebê","emma","bastilha de ermoforte","maçãs frescas","tessa dawnbright"},sec={{t="Uma criança exigente",b="Tessa Dawnbright cuida da bebê Emma na Bastilha de Ermoforte, onde o choro da criança ecoa pela fortaleza. Tessa diz que está com as mãos ocupadas enquanto o marido está fora buscando suprimentos. Ela pede que você encontre maçãs frescas para preparar uma papinha para Emma."}},faq={{q="Quem está pedindo maçãs?",a="Tessa Dawnbright pede que você encontre maçãs para a bebê Emma na Bastilha de Ermoforte.",al={"tessa maçãs","quem precisa de maçãs","doadora da missão das maçãs"}},{q="Por que Tessa precisa de maçãs?",a="Tessa espera preparar uma papinha para a exigente bebê Emma.",al={"por que maçãs","maçãs para bebê","para que servem as maçãs"}},{q="Onde Tessa precisa de ajuda?",a="Tessa pede ajuda na Bastilha de Ermoforte.",al={"onde fica tessa","maçãs da bastilha de ermoforte","local das maçãs"}},{q="Por que Tessa não pode buscar os suprimentos sozinha?",a="Tessa diz que está ocupada demais cuidando de Emma enquanto o marido busca suprimentos.",al={"marido de tessa","onde está o marido dela","por que ela não pode ir"}}},fp="15,115,13.244.0,25.72.0,27.47.0,27.37.0,41.88.0"}
P.entries["quest:95562"] = {n="Cut Off the Heads",s="A aprendiz Claire pede que você acabe com a ameaça sob Solclaro. Chogg'Zac, o mestre da caverna, deve ter a cabeça trazida de volta.",h="A aprendiz Claire pede que você acabe com a ameaça sob Solclaro.",kw={"aprendiz claire","cavernas","chogg'zac","corte as cabeças","lady amberhall","ogros","solclaro"},sec={{t="O pedido de Claire",b="Antes de você entrar nas cavernas sob Solclaro, a aprendiz Claire conta por que veio. Lady Amberhall a enviou para coletar amostras, mas Claire decidiu voltar porque Solclaro já foi seu lar. Monstros ainda corrompem o lugar, e ela quer que o mestre deles seja morto. Chogg'Zac espera lá embaixo, e Claire pede que você traga as cabeças de volta."},{t="Depois da luta",b="Quando você volta, Claire pergunta se Chogg'Zac e os ogros estão mortos. Ela considera que você fez o que era certo e insiste para que parta com ela."}},faq={{q="Quem está me pedindo para ir sob Solclaro?",a="A aprendiz Claire pede que você mate Chogg'Zac nas cavernas sob Solclaro e traga as cabeças de volta.",al={"quem me enviou","tarefa de claire","aprendiz claire"}},{q="Por que Claire veio a Solclaro?",a="Solclaro era o lar de Claire antes de a guerra tirá-lo dela, e ela não conseguia descansar enquanto ainda houvesse monstros por lá.",al={"por que claire está aqui","lar de claire","história de solclaro"}},{q="Quem é Chogg'Zac?",a="Chogg'Zac é o mestre das cavernas sob Solclaro.",al={"chogg zac","mestre da caverna","chefe dos ogros"}},{q="O que Claire quer que eu traga de volta?",a="Claire pede que você traga as cabeças de volta depois de matar Chogg'Zac.",al={"o que trazer de volta","cabeças para claire","o que recuperar"}}},fp="17,139,13.330.0,15.134.1,42.100.0,34.115.0,17.56.0,39.62.0"}
P.entries["quest:956"] = {n="Bashal'Aran",s="Astérion, um espírito de Elfo Noturno preso entre os pilares em ruínas de Bashal'Aran, busca a relíquia que o mantém vinculado a este mundo. Tendo sentido a corrupção de sua prisão entre os grells locais, ele orienta os viajantes a caçar os sátiros que os comandam e recuperar o Selo Antigo de Pedra-da-lua.",h="Astérion, um espírito de Elfo Noturno preso entre os pilares em ruínas de Bashal'Aran, busca a relíquia que o...",kw={"selo antigo de pedra-da-lua","astérion","bashal'aran","costa negra","grell","kaldorei","fantasma de elfo noturno","sátiro"},ang={["class:Druid"]="A influência distorcida dos sátiros continua a corromper a vida selvagem de Costa Negra e a perturbar espíritos ancestrais que deveriam descansar em paz no ciclo da natureza.",["faction:Alliance"]="Purificar as ruínas de Costa Negra da corrupção dos sátiros protege a costa norte de Kalimdor e ajuda os Kaldorei a sepultar seu passado trágico.",["race:NightElf"]="Bashal'Aran é uma lembrança sombria do passado ancestral do seu povo, onde antepassados que ainda resistem permanecem acorrentados à terra por sátiros que personificam a traição demoníaca da Cisão."},sec={{t="Uma Prisão de Pedra Antiga",b="Por bem mais de mil anos, o espírito Astérion permaneceu atado às ruínas caídas de Bashal'Aran. Os pilares de mármore ao redor servem como uma jaula inflexível que nem sua força espiritual decadente nem sua magia ancestral conseguem romper. Preso por uma relíquia amaldiçoada, ele passou séculos contemplando o dossel encoberto pela névoa de Costa Negra, perguntando-se se até mesmo a erosão da pedra ao seu redor lhe concederia a libertação."},{t="Sátiros e o Selo de Pedra-da-lua",b="Após descobrir que os grells próximos traziam vestígios da magia que mantinha seu cativeiro, Astérion deduziu que a fonte do encantamento havia caído nas mãos dos sátiros que comandam essas criaturas caóticas. Vagando pelos bosques ancestrais, esses Elfos Noturnos demoníacos mantêm uma vigilância rígida sobre o Selo Antigo de Pedra-da-lua. Recuperar esse talismã é o passo fundamental para estilhaçar as barras invisíveis que ancoram Astérion ao seu santuário."}},faq={{q="Quem é Astérion?",a="Astérion é um antigo fantasma de Elfo Noturno preso nas ruínas de Bashal'Aran. Confinado por magia ancestral, ele passou mais de mil anos retido nos pilares do santuário, incapaz de seguir em frente ou de vagar além de sua prisão de pedra.",al={"quem é astérion","história de astérion","fantasma em bashal'aran"}},{q="Por que os sátiros possuem o Selo Antigo de Pedra-da-lua?",a="Os sátiros lideram e influenciam os grells selvagens que infestam o norte de Costa Negra. Como os grells carregavam vestígios da magia de aprisionamento, Astérion percebeu que seus perversos mestres sátiros haviam se apoderado do Selo Antigo de Pedra-da-lua para manter os espíritos locais atormentados e aprisionados.",al={"por que sátiros têm o selo","selo de pedra-da-lua do sátiro","selo antigo de pedra-da-lua"}},{q="O que acontece quando o selo é recuperado?",a="Astérion toma posse da própria relíquia que o aprisionou por séculos. Recuperar o Selo Antigo de Pedra-da-lua é o penúltimo passo em sua libertação, permitindo que o selo seja quebrado para que ele possa finalmente caminhar livre pelas florestas outra vez.",al={"o que o selo faz","recuperando o selo"}},{q="O que é Bashal'Aran?",a="Bashal'Aran é uma antiga ruína de Elfo Noturno localizada ao longo das margens encobertas de névoa no norte de Costa Negra. Outrora um assentamento magnífico ou enclave sagrado, hoje jaz em ruínas, assolada por grells, sátiros e espíritos aprisionados de uma era anterior.",al={"história de bashal'aran","o que é bashal'aran"}},{q="Há quanto tempo Astérion está preso aqui?",a="Astérion está aprisionado há mais de mil anos. Sem meios físicos ou magia para desfazer a barreira, ele foi forçado a esperar ao longo dos séculos, incerto se algum dia seria libertado.",al={"quantos anos tem astérion","quanto tempo preso"}},{q="Astérion pode simplesmente se afastar do santuário?",a="Não. O Selo Antigo de Pedra-da-lua mantém uma barreira metafísica ao redor do santuário. Os pilares de pedra funcionam como uma jaula impenetrável que impede sua forma espectral de passar além deles.",al={"astérion pode sair","por que o fantasma está preso"}}},fx={["31aed888"]={q="Por que Astérion quer o selo recuperado?",a="Astérion está desesperado por liberdade. A relíquia antiga serve como a âncora de ligação de sua prisão eterna, mantendo seu espírito preso dentro do santuário arruinado. Por mais de mil anos, ele olhou além dos pilares de pedra, incapaz de romper seu domínio através de força ou feitiçaria. Recuperar o artefato é a única maneira de destruí-lo e finalmente permitir que ele caminhe livremente pelas florestas mais uma vez.",al={"por que astérion quer isso feito","motivação de astérion","por que ajudar astérion"}},["5f1ff286"]={q="O que é o Selo Antigo de Pedra-da-lua?",a="O Selo Antigo de Pedra-da-lua é uma relíquia mágica que atua como a chave do cativeiro de Astérion. Ele cria uma barreira intangível entre os pilares de Bashal'Aran, funcionando como uma cela eterna que nenhum feitiço ou força física dele pode romper. Enquanto o selo perdurar nas mãos das forças corruptas próximas, Astérion permanecerá ligado ao santuário.",al={"o que é o selo antigo de pedra-da-lua","o que o selo de pedra-da-lua faz","objetivo do selo antigo de pedra-da-lua"}},c7650517={q="Por que você é enviado contra os sátiros locais?",a="Os sátiros comandam os vis grells que infestam as ruínas de Bashal'Aran. Como os grells menores carregavam vestígios do encantamento do selo, Astérion deduziu que seus mestres devem ter reivindicado o próprio artefato. Corruptos e atraídos por relíquias mágicas antigas, os sátiros mantêm o selo em seu acampamento, tornando-os seu alvo.",al={"quem são os sátiros em bashal'aran","por que lutar contra os sátiros","quem tem o selo"}},["341831b6"]={q="Por que Astérion não pode recuperar o selo sozinho?",a="Astérion não pode deixar os limites do santuário. A magia do selo o mantém totalmente preso dentro de seu perímetro, tratando os pilares de pedra como grades intransponíveis. Ele não possui a força nem a feitiçaria para romper seu confinamento, deixando-o completamente dependente de um forasteiro para se aventurar nos acampamentos dos sátiros em seu nome.",al={"por que astérion precisa de mim","por que astérion não consegue o selo","por que eu astérion"}}},fp="11,211,25.361.0,29.356.0,16.200.0,50.207.0,40.163.1,20.218.0,40.178.0,46.141.0"}
P.entries["quest:95601"] = {n="The Purple Ones",s="Clubtoe pede que você interrompa os rituais de Twilight's Hammer em Solclaro. Os ritos fortalecem alguns ogros e matam outros.",h="Clubtoe pede que você interrompa os rituais de Twilight's Hammer em Solclaro.",kw={"clubtoe","empowered brutes","ogro","solclaro","the purple ones","twilight ritualists","twilight's hammer"},sec={{t="Rituais em Solclaro",b="Em Solclaro, Clubtoe envia você contra Twilight Ritualists e Empowered Brutes. Um ogro morto parece ser um dos amigos que Clubtoe procurava. Os rituais fortalecem alguns membros e matam outros, então Clubtoe quer deter os ritualistas e suas criações antes que se espalhem."}},faq={{q="Quem é Clubtoe?",a="Clubtoe é quem pede que você detenha os Twilight Ritualists em Solclaro.",al={"clubtoe","quem é clubtoe"}},{q="O que os Purple Ones estão fazendo?",a="Os Twilight Ritualists realizam ritos em seus membros. Alguns são fortalecidos, enquanto outros são mortos.",al={"purple ones","o que os purple ones estão fazendo"}},{q="Por que Clubtoe quer interromper os rituais?",a="Clubtoe teme que os ritualistas e suas monstruosidades se espalhem.",al={"por que interromper os rituais","por que matar ritualistas"}},{q="O que aconteceu com os amigos de Clubtoe?",a="Um ogro morto parece ser um dos amigos que Clubtoe estava procurando.",al={"amigos de clubtoe","onde estão os amigos"}},{q="Onde está Clubtoe?",a="Clubtoe está em Solclaro.",al={"localização de clubtoe","clubtoe em solclaro"}}},fp="15,111,19.274.0,15.76.0,31.98.0,42.65.0,35.71.0,17.25.0"}
P.entries["quest:95602"] = {n="Sickening Lights",s="Clubtoe pede que você destrua os círculos rituais brilhantes sob Solclaro. A luz lhe faz mal, e ele teme a ira de Chogg'Zac se agir sozinho.",h="Clubtoe pede que você destrua os círculos rituais brilhantes sob Solclaro.",kw={"cavernas","chogg'zac","clubtoe","luz","desenhos brilhantes","luzes enjoativas","solclaro","círculos rituais do crepúsculo"},sec={{t="Um brilho enjoativo",b="Clubtoe trabalha nas cavernas sob Solclaro, quebrando pedras para Chogg'Zac. Ele encontra luzes brilhantes na pedra, e os outros fazem desenhos com elas. O brilho faz Clubtoe se sentir mal, embora ele tema que Chogg'Zac vá puni-lo por destruir os desenhos. Pedem que você destrua os Círculos Rituais do Crepúsculo, e Clubtoe espera que a luz não o incomode mais."}},faq={{q="Quem está me pedindo para destruir os círculos?",a="Clubtoe pede que você destrua os Círculos Rituais do Crepúsculo sob Solclaro.",al={"quem é clubtoe","missão de clubtoe","quem quer destruir as luzes"}},{q="Por que Clubtoe quer que as luzes sejam destruídas?",a="A luz faz Clubtoe se sentir mal, e ele quer destruir os desenhos brilhantes.",al={"por que destruir as luzes","as luzes fazem mal a clubtoe","clubtoe odeia a luz"}},{q="Quem é Chogg'Zac?",a="Chogg'Zac é o chefe de Clubtoe, e Clubtoe teme que ele fique furioso se os círculos forem destruídos.",al={"chogg zac","chefe de clubtoe","chefão"}},{q="O que são os desenhos brilhantes?",a="São Círculos Rituais do Crepúsculo encontrados por todas as cavernas sob Solclaro. Clubtoe os chama de desenhos brilhantes.",al={"desenhos brilhantes","círculos do crepúsculo","o que são as luzes"}},{q="O que Clubtoe faz nas cavernas?",a="Clubtoe quebra pedras para Chogg'Zac e encontrou luz brilhante na pedra.",al={"trabalho de clubtoe","quebrando pedras","o que clubtoe está fazendo"}},{q="Clubtoe se sente melhor depois que os círculos são destruídos?",a="Depois que você destrói os círculos, Clubtoe diz que já se sente melhor.",al={"conclusão de clubtoe","destruir ajudou","as luzes fazem ele se sentir melhor"}}},fp="16,147,16.364.0,38.75.0,41.78.0,17.90.0,28.116.0,34.76.0,55.66.0"}
P.entries["quest:95603"] = {n="Bats in the Belfry",s="Sister Rowland pede que você livre Farholde Cathedral dos morcegos. Ela espera que a igreja volte a servir à Light quando os combates terminarem.",h="Sister Rowland pede que você livre Farholde Cathedral dos morcegos.",kw={"morcegos no campanário","brother lowley","igreja","farholde cathedral","light","morcegos do crepúsculo no abrigo","sister rowland"},sec={{t="A catedral",b="Sister Rowland pede sua ajuda em Farholde Cathedral, onde morcegos do crepúsculo se abrigam nos andares superiores. Ela e brother Lowley agora servem a Farholde em uma função mais secular, e a igreja caiu em desuso. Rowland quer mantê-la em funcionamento, embora tema que os combates ainda durem muito tempo."}},faq={{q="Por que há morcegos na catedral?",a="Uma colônia de morcegos fez seu abrigo nos andares superiores de Farholde Cathedral.",al={"morcegos da catedral","morcegos no campanário","por que há morcegos"}},{q="Quem me pede para espantar os morcegos?",a="Sister Rowland pede que você remova os morcegos que se abrigam em Farholde Cathedral.",al={"quem deu esta missão","sister rowland","morcegos de rowland"}},{q="Por que Sister Rowland quer manter a igreja em funcionamento?",a="Sister Rowland espera que a Light possa voltar à igreja quando os combates terminarem.",al={"por que manter a igreja","manutenção da igreja","igreja de rowland"}},{q="O que aconteceu com a igreja?",a="A igreja caiu em desuso desde que Sister Rowland e brother Lowley começaram a servir a Farholde em uma função mais secular.",al={"igreja abandonada","por que caiu em desuso","igreja de farholde"}}},fp="18,134,13.305.0,36.79.0,30.76.0,62.79.0,28.124.0"}
P.entries["quest:95613"] = {n="Keeping the Light On",s="Sister Rowland pede que você leve Holy Candles à Bastilha de Ermoforte. Ela as mantém acesas na cripta da igreja para que os caídos sejam lembrados por seus sacrifícios.",h="Sister Rowland pede que você leve Holy Candles à Bastilha de Ermoforte.",kw={"igreja","cripta","caídos","bastilha de ermoforte","holy candles","mantendo a luz acesa","marla","sister rowland"},sec={{t="Velas para os Caídos",b="Sister Rowland, na Bastilha de Ermoforte, pede Holy Candles a você. Embora não haja mais cerimônias na igreja, ela mantém velas acesas sobre os túmulos dos caídos em sua cripta. As chamas mostram que os mortos são lembrados e que seus sacrifícios não foram em vão. Marla, amiga de Sister Rowland, talvez tenha velas sobrando na casa logo ao lado da igreja."}},faq={{q="Por que Sister Rowland mantém as velas acesas?",a="Sister Rowland mantém velas acesas sobre os túmulos na cripta da igreja para que os caídos sejam lembrados e seus sacrifícios não tenham sido em vão.",al={"por que velas","velas na cripta","velas para os mortos"}},{q="Onde Sister Rowland quer que as velas sejam entregues?",a="Sister Rowland pede que você leve Holy Candles até ela, na Bastilha de Ermoforte.",al={"onde levar velas","entrega de velas","velas de rowland"}},{q="Quem é Marla?",a="Marla é amiga de Sister Rowland. Ela mora na casa logo ao lado da igreja e talvez tenha velas sobrando.",al={"velas de marla","quem tem velas","origem das velas"}},{q="Ainda há cerimônias na igreja?",a="Não há mais cerimônias na igreja, embora Sister Rowland continue mantendo velas acesas em sua cripta.",al={"cerimônia na igreja","igreja fechada","sem cerimônias"}}},fp="20,158,22.365.0,41.133.0,51.70.0,13.113.0,37.107.0"}
P.entries["quest:95615"] = {n="In Memoriam",s="Sister Rowland pede que você reacenda velas memoriais na Bastilha de Ermoforte. Esse pequeno gesto honra os mortos e ajuda a manter a igreja viva.",h="Sister Rowland pede que você reacenda velas memoriais na Bastilha de Ermoforte.",kw={"cemitério da capela","igreja","bastilha de ermoforte","túmulos","em memória","acender","velas memoriais","sister rowland"},sec={{t="Velas para os Caídos",b="Na Bastilha de Ermoforte, Sister Rowland pede que você cuide do cemitério da capela. Coloque velas novas em três túmulos onde as chamas antigas se apagaram e faça uma homenagem silenciosa aos caídos."}},faq={{q="Quem me pede para acender as velas?",a="Sister Rowland, na Bastilha de Ermoforte, pede que você acenda velas memoriais no cemitério da capela.",al={"quem é sister rowland","velas de sister rowland"}},{q="Onde devo colocar as velas?",a="Coloque as velas memoriais nos túmulos do cemitério da capela, na Bastilha de Ermoforte.",al={"local das velas","onde ficam os túmulos"}},{q="Quantos túmulos precisam de velas?",a="Sister Rowland pede que você coloque três velas memoriais nos túmulos.",al={"quantidade de velas","quantas velas"}},{q="Por que acender as velas?",a="As velas honram aqueles que morreram e ajudam a manter a igreja viva.",al={"por que velas","para que serve"}}},fp="11,132,22.184.0,33.91.0,24.78.0,29.66.0,22.69.0"}
P.entries["quest:95621"] = {n="Trouble in the Valley",s="Trouble in the Valley gira em torno de um esquadrão misterioso de soldados kultirenos descobertos vasculhando o fundo do vale. Tropas armadas montaram acampamento perto de uma caravana destruída ao sul, levando batedores locais a buscarem sua eliminação e a descobrirem o propósito por trás de sua busca inesperada.",h="Trouble in the Valley gira em torno de um esquadrão misterioso de soldados kultirenos descobertos vasculhando...",kw={"caravana","kul tiraz","soldados","trouble in the valley","vale","caravana destruída"},ang={["race:Human"]="Ver soldados ostentando o verde-mar e as cores da âncora do reino insular de Kul Tiraz operando no vale marca um encontro raro e inesperado com essa reclusa nação marítima humana."},sec={{t="Atividade Suspeita no Vale",b="Um fuzileiro vigilante observando as terras baixas avistou um esquadrão de soldados humanos vasculhando o fundo do vale. Usando a mira de um rifle para observar de perto, o batedor identificou com clareza a heráldica e a libré da nação marítima de Kul Tiraz. Sua presença inesperada no vale gerou alarme imediato, já que estrangeiros armados raramente operam de forma tão descarada sem chamar a atenção."},{t="A Caravana Destruída",b="Os soldados tomaram posição perto de uma caravana em ruínas situada ao sul. O que os atraiu até a carroça destruída permanece um mistério urgente. Observadores locais consideraram a presença armada invasora uma preocupação imediata, enviando investigadores para eliminar os soldados e desvendar o verdadeiro propósito de sua expedição."}},faq={{q="O que os soldados kultirenos estão fazendo no vale?",a="Um atirador avistou um destacamento de soldados kultirenos procurando por algo no vale abaixo. Eles estabeleceram um acampamento perto de uma caravana destruída ao sul, levando batedores locais a investigarem seus motivos incomuns.",al={"por que kultirenos aqui","soldados de kul tiraz no vale","o que os kultirenos estão fazendo"}},{q="Onde fica o acampamento kultireno?",a="Os soldados estabeleceram seu acampamento perto de uma caravana em ruínas localizada ao sul do ponto de observação dos batedores que tem vista para o vale.",al={"localização da caravana destruída","onde fica o acampamento de kul tiraz","local da caravana"}},{q="Como a presença kultirena foi descoberta?",a="Um batedor que vigiava o vale usou a mira de um rifle para inspecionar o misterioso grupo humano de longe, reconhecendo facilmente o uniforme e as insígnias distintas de Kul Tiraz.",al={"como foram identificados","libré de kul tiraz"}},{q="Qual é o objetivo de investigar o acampamento?",a="A tarefa exige viajar para o sul em direção à caravana destruída, confrontar os soldados kultirenos posicionados no local e descobrir o que os atraiu para vasculhar a área.",al={"qual é o objetivo","objetivos de trouble in the valley"}},{q="Por que os soldados kultirenos são tratados como inimigos?",a="Como um contingente armado de soldados estrangeiros está vasculhando ativamente o território ao redor de uma caravana destruída sem explicação, os batedores os consideram uma ameaça que precisa ser subjugada para desvendar suas intenções.",al={"por que lutar contra kul tiraz","os kultirenos são hostis"}},{q="Quem detectou os soldados no vale?",a="Walton, The Hermit Tanner que vigia o vale, avistou primeiro os soldados pela mira do seu rifle e contratou um aventureiro para eliminá-los e descobrir por que estavam lá.",al={"quem avistou os soldados","quem deu a missão"}}},fp="21,177,33.236.0,19.264.0,48.174.0,36.100.0,42.130.0,48.127.0,50.180.0,40.164.0"}
P.entries["quest:95642"] = {n="Abominable Magics",s="A aprendiz Claire pede que você reúna amostras da magia do Martelo do Crepúsculo numa caverna sob Solclaro. Farholde precisa delas para estudar a feitiçaria do culto.",h="A aprendiz Claire pede que você reúna amostras da magia do Martelo do Crepúsculo numa caverna sob Solclaro.",kw={"magias abomináveis","aprendiz claire","ashe amberhall","crystal catalyst","farholde","sendas do rio","solclaro","martelo do crepúsculo","feitiçaria"},sec={{t="O pedido de Claire",b="Enviada por Ashe Amberhall, Claire investiga o Martelo do Crepúsculo nas Sendas do Rio, onde os cultistas escavam em busca de algo. Ela precisa de uma amostra da feitiçaria deles para entendê-la. Você leva um Crystal Catalyst encantado para absorver o poder do culto de runas ou cultistas, e Claire diz que Farholde precisa urgentemente do que ele reunir."},{t="Uma amostra poderosa",b="Quando você retorna, Claire toca o cristal e recua ao sentir a magia crepitando dentro dele. O poder reunido é mais forte do que ela temia, e ela diz que é preciso manuseá-lo com cuidado."}},faq={{q="Quem está pedindo as amostras?",a="A aprendiz Claire pede que você reúna amostras da magia do Martelo do Crepúsculo para ela.",al={"quem quer amostras","pedido de amostra de claire"}},{q="Por que Claire precisa das amostras?",a="Claire quer estudar a feitiçaria do culto e diz que Farholde precisa urgentemente das amostras.",al={"por que amostras","para que servem as amostras"}},{q="Onde os cultistas estão escavando?",a="O Martelo do Crepúsculo está escavando em busca de algo nas Sendas do Rio.",al={"onde o martelo do crepúsculo está escavando","cultistas escavando"}},{q="O que o Crystal Catalyst faz?",a="O Crystal Catalyst encantado absorve o poder da magia do Martelo do Crepúsculo de runas ou cultistas.",al={"coisa de cristal","função do catalisador"}},{q="Quem enviou Claire para investigar?",a="Ashe Amberhall enviou Claire para investigar o Martelo do Crepúsculo.",al={"quem enviou claire","amberhall"}}},fp="17,168,16.318.0,15.181.1,30.80.0,33.94.0,31.66.0,34.99.0,31.60.0"}
P.entries["quest:95643"] = {n="Indiscriminate Purge",s="Uma aprendiz de Lady Amberhall pede que você enfrente ogros infundidos pelo vazio sob Solclaro. O Martelo do Crepúsculo sentirá as perdas.",h="Uma aprendiz de Lady Amberhall pede que você enfrente ogros infundidos pelo vazio sob Solclaro.",kw={"aprendiz","empowered brutes","purga indiscriminada","lady amberhall","solclaro","twilight ritualists","martelo do crepúsculo","ogros infundidos pelo vazio"},sec={{t="Sob Solclaro",b="A aprendiz de Lady Amberhall foi capturada por ogros e seus mestres nas cavernas sob Solclaro. Ela pede que você elimine os Twilight Ritualists e os Empowered Brutes dali. As perdas atingirão o Martelo do Crepúsculo."}},faq={{q="Quem pede ajuda sob Solclaro?",a="A aprendiz de Lady Amberhall pede que você mate os ogros nas cavernas sob Solclaro.",al={"aprendiz de amberhall","quem está pedindo","missão de lady amberhall"}},{q="O que há nas cavernas?",a="As cavernas sob Solclaro abrigam ogros infundidos pelo vazio e seus mestres.",al={"caverna de solclaro","quais ogros","inimigos da caverna"}},{q="Quem são os mestres dos ogros?",a="A aprendiz identifica os mestres dos ogros como Twilight Ritualists.",al={"mestres dos ogros","twilight ritualists","quem controla os ogros"}},{q="Quais ogros a aprendiz menciona?",a="Ela menciona Empowered Brutes entre as feras nas cavernas.",al={"empowered brutes","quais ogros matar","nomes dos ogros"}},{q="Por que a aprendiz pede que você os mate?",a="Ela diz que nada de bom vem de fanáticos com um propósito, fortalecidos ou não.",al={"por que matar ogros","por que eliminar","por que ajudar amberhall"}},{q="O que a aprendiz diz sobre as próprias habilidades?",a="Ela diz que normalmente consegue cuidar das coisas sozinha, mas os ogros a capturaram.",al={"aprendiz capturada","aprendiz de amberhall capaz","o que aconteceu com ela"}}},fp="20,133,16.224.0,37.89.0,21.71.0,29.70.0,37.57.0,45.86.0,53.90.0"}
P.entries["quest:95646"] = {n="Horrors in the Highland",s="Rethiel, o Verdião pressente uma corrupção vil infiltrando-se por uma ravina da montanha nas águas sem sal acima do Pantanal. Aventureiros devem subir até os locais de escavação para abater um Highland Horror e recuperar seu núcleo de raiz. Rethiel descobre que uma energia ancestral está se agitando, alertando que a escavação contínua ameaça a segurança de todos na região.",h="Rethiel, o Verdião pressente uma corrupção vil infiltrando-se por uma ravina da montanha nas águas sem sal...",kw={"corrupção","locais de escavação","horror das terras altas","horrores nas terras altas","rethiel","rethiel, o verdião","núcleo de raiz","pantanal"},ang={["class:Druid"]="Rethiel pressente o equilíbrio natural mudando através de suas raízes e dos cursos d'água; druidas sintonizados com a terra reconhecerão a súbita vulnerabilidade da vida de água doce à corrupção ancestral.",["faction:Alliance"]="Exploradores da Aliança e Prospectors que operam locais de escavação nas montanhas arriscam perturbar forças ancestrais sepultadas sob a terra.",["race:Dwarf"]="Locais de escavação de Anões nas terras altas desenterraram mais do que relíquias ancestrais, levando Rethiel a instar os escavadores a interromperem suas escavações antes que males piores despertem."},sec={{t="Mácula na Ravina",b="Nas profundezas do Pantanal, Rethiel, o Verdião pressente uma mudança perturbadora na terra. Uma mácula vil infiltra-se por uma ravina da montanha, infectando as criaturas de água doce que habitam as terras altas acima. Ao contrário da vida resistente moldada pelas águas salobras das terras baixas, esses seres de água doce nunca conheceram o sal protetor do mar, ficando inteiramente indefesos contra o mal que se espalha. Rethiel convoca aventureiros a subirem até os locais de escavação, abaterem um Highland Horror e recuperarem seu núcleo de raiz."},{t="Uma Agitação Ancestral",b="Quando o núcleo de raiz do Highland Horror é levado a Rethiel, os temores do guardião se confirmam: uma energia ancestral começou a se agitar. A aflição que assola as criaturas das terras altas não é uma doença comum, mas sim a consequência de escavações recentes. Rethiel adverte com urgência que os escavadores entusiasmados que trabalham nos locais da montanha devem cessar suas escavações imediatamente, antes que sua curiosidade irrefletida liberte algo muito pior sobre o Pantanal."}},faq={{q="Quem oferece a missão Horrors in the Highland?",a="Rethiel, o Verdião, um antigo protetor que vigia o Pantanal, oferece esta missão após pressentir uma corrupção vil infiltrando-se por uma ravina próxima na montanha.",al={"quem dá horrores nas terras altas","concedente da missão horrores nas terras altas","missão de rethiel"}},{q="Onde Highland Horrors podem ser encontrados?",a="Highland Horrors habitam os locais de escavação situados nas terras mais altas acima das baixadas, perto da ravina da montanha por onde a corrupção se infiltra.",al={"onde estão os horrores das terras altas","localização do horror das terras altas","onde encontrar o horror das terras altas"}},{q="Por que as criaturas das terras altas são tão suscetíveis à corrupção?",a="As criaturas de água doce das terras altas carecem da salma enrijecedora e do sal do mar encontrados nas partes baixas do Pantanal, ficando frágeis e especialmente amargas em sua reação à mácula corruptora.",al={"por que as criaturas estão maculadas","por que criaturas das terras altas corrompidas","corrupção na água sem sal"}},{q="O que é o núcleo de raiz de um Highland Horror?",a="O núcleo de raiz é o coração do Highland Horror corrompido. Rethiel precisa dele para inspecionar o poder não natural que se espalha pelos cursos d'água e confirmar a natureza da corrupção.",al={"o que é o núcleo de raiz","núcleo do horror das terras altas","por que pegar o núcleo de raiz"}},{q="O que Rethiel descobre quando você devolve o núcleo de raiz?",a="Ao examinar o núcleo, Rethiel percebe que uma energia ancestral começou a se agitar das profundezas da terra, provavelmente perturbada pelas escavações imprudentes nos locais de escavação.",al={"o que rethiel descobre","energia ancestral pantanal","perigo da escavação"}},{q="Por que Rethiel quer que os escavadores parem de cavar?",a="Rethiel adverte que os escavadores entusiasmados que trabalham nas terras altas devem cessar imediatamente suas escavações para sua própria segurança, pois suas escavações arriscam libertar forças ancestrais perigosas.",al={"parar escavação rethiel","o que os escavadores devem fazer","aviso do local de escavação dos anões"}}},fp="23,266,18.437.0,19.372.1,45.144.0,36.131.0,60.132.0,43.189.0,57.170.0,53.127.0"}
P.entries["quest:95647"] = {n="Lost in the Thicket Things",s="Uma alquimista preocupada pede a viajantes que rastreiem seu marido desaparecido, Ardin Grassman, que sumiu após ir atrás de rumores sobre gramas imponentes e desconhecidas. A curiosidade botânica de Ardin o levou diretamente a um local de escavação próximo, onde a fauna perigosa e ataques de aranhas cercaram a equipe.",h="Uma alquimista preocupada pede a viajantes que rastreiem seu marido desaparecido, Ardin Grassman, que sumiu...",kw={"alquimia","ardin","ardin grassman","excavation sites","herborismo","lost in the thicket things","aranhas","gramas altas"},ang={["class:Druid"]="Druidas sintonizados com o equilíbrio da natureza selvagem podem ter interesse no dom natural de Ardin para pressentir a flora, assim como na agitação antinatural que perturba a fauna perto dos locais de escavação.",["profession:Herbalism"]="Ardin Grassman possui um dom inato para pressentir plantas e ervas, muitas vezes escalando terrenos traiçoeiros para coletar flora rara para alquimia."},sec={{t="O Chamado de um Coletor",b="Em 'Lost in the Thicket Things', uma alquimista busca ajuda para rastrear seu marido desaparecido, Ardin Grassman. Ardin possui uma afinidade instintiva e impressionante com a natureza, rotineiramente desafiando penhascos íngremes e ermos distantes para coletar ervas raras e espécimes botânicos para abastecer seus suprimentos de alquimia. Quando uma equipe de escavação que passava trouxe notícias de gramas bizarras e imponentes, diferentes de tudo o que já se viu, a curiosidade de Ardin falou mais alto, e ele partiu para inspecionar a flora por conta própria."},{t="Emboscada no Local da Escavação",b="Ardin rastreou a expedição em direção ao local da escavação, apenas para caminhar direto para o perigo. Algo nas terras ao redor agitou a fauna local, fazendo com que animais agressivos — principalmente enxames de aranhas hostis — atacassem e dominassem a equipe de escavação. Encurralados pelas feras que se aproximavam, Ardin e a equipe viram-se cercados até que viajantes intervieram para resgatar o botânico ilhado."}},faq={{q="Quem é Ardin Grassman?",a="Ardin Grassman é um coletor com um raro dom natural para pressentir plantas e ervas. Ele percorre regularmente penhascos e picos para abastecer sua esposa com flora selvagem para o ofício de alquimia dela, mas sua curiosidade sobre gramas estranhas e imponentes o atraiu para um local de escavação.",al={"quem é ardin","história de ardin grassman","quem é ardin grassman"}},{q="Por que Ardin vagou pelos ermos?",a="Ardin ouviu por acaso uma equipe de escavação descrevendo gramas imponentes e colossais, diferentes de tudo o que haviam encontrado antes. Atraído por sua afinidade com plantas e flora incomuns, ele se aventurou para ver a vegetação estranha com seus próprios olhos e não retornou para casa.",al={"por que ardin partiu","por que ardin está desaparecido","o que ardin estava procurando"}},{q="Para onde Ardin foi?",a="Ardin aventurou-se em direção aos Excavation Sites próximos após ouvir relatos de uma equipe de expedição que passava. Viajantes à sua procura devem vasculhar os locais de escavação onde a equipe montou suas operações.",al={"onde está ardin","localização de ardin","onde encontrar ardin grassman"}},{q="O que aconteceu com Ardin no local da escavação?",a="Ardin encontrou o acampamento de escavação tomado quando a fauna local se tornou agitada e agressiva. Aranhas gigantes e outras feras enfurecidas emboscaram a expedição, encurralando Ardin e a equipe até que ajuda externa chegasse.",al={"o que aconteceu com ardin","ardin está morto","o que atacou ardin"}},{q="Quem está procurando por Ardin?",a="A busca começa com a esposa de Ardin, uma alquimista que depende das expedições de coleta de ervas dele para abastecer suas prateleiras. Quando ele não retornou de sua investigação sobre os rumores de grama estranha, ela procurou viajantes capazes para trazê-lo de volta.",al={"quem dá lost in the thicket things","quem iniciou esta missão","esposa de ardin"}},{q="Por que a fauna atacou a equipe de escavação?",a="A fauna ao redor dos locais de escavação ficou repentina e violentamente agitada, embora a causa exata de sua aflição permaneça incerta. A perturbação levou criaturas agressivas, especialmente aranhas, a formar enxames e dominar a equipe de escavação.",al={"por que as aranhas estão atacando","o que perturbou os animais","por que as feras estão zangadas"}}},fp="26,183,19.303.0,22.250.1,22.215.0,39.168.0,19.133.0,46.178.0,25.183.0,48.162.0"}
P.entries["quest:95663"] = {n="Dragonmaw Rumors",s="Os Deathstalkers buscam notícias mais claras sobre a suposta magia dos Dragonmaw no Pantanal. Você recebe a missão de encontrar a agente deles nas colinas acima do acampamento do clã.",h="Os Deathstalkers buscam notícias mais claras sobre a suposta magia dos Dragonmaw no Pantanal.",kw={"símbolos quebrados","agente deathstalker","deathstalkers","subjugação de dragões","dragonmaw","acampamento dragonmaw","rumores sobre dragonmaw","pantanal"},sec={{t="Sussurros no Pantanal",b="Um Deathstalker no Pantanal precisa da sua ajuda enquanto rumores cercam o clã Dragonmaw. Dizem que eles dominam uma magia que subjuga dragões, e sussurros afirmam que preparam uma demonstração desse poder. Símbolos quebrados não ofereceram provas concretas, então você recebe a missão de encontrar uma agente nas colinas acima do acampamento deles."}},faq={{q="Segundo os rumores, o que os Dragonmaw estão fazendo?",a="O rumor diz que os Dragonmaw estão preparando uma demonstração de magia forte o bastante para obrigar dragões a servi-los.",al={"rumores sobre dragonmaw","o que os dragonmaw planejam","magia dos dragonmaw"}},{q="Por que os Deathstalkers precisam de ajuda?",a="Os Deathstalkers têm apenas símbolos quebrados e sussurros incertos sobre os Dragonmaw, por isso uma agente precisa de ajuda nas colinas acima do acampamento do clã.",al={"deathstalker precisa de ajuda","por que ajudar os deathstalkers","do que eles precisam"}},{q="Onde está a agente Deathstalker?",a="A agente está nas colinas acima do acampamento Dragonmaw no Pantanal.",al={"localização da agente","onde encontrar a agente","agente deathstalker nas colinas"}},{q="O que os símbolos quebrados revelaram?",a="Os símbolos quebrados traziam apenas sussurros incertos sobre uma suposta demonstração de magia dos Dragonmaw.",al={"símbolos quebrados","o que os símbolos mostraram","símbolos dos dragonmaw"}},{q="O que acontece quando você encontra a agente?",a="A agente Deathstalker revelará os próximos passos quando você a encontrar nas colinas acima do acampamento Dragonmaw.",al={"encontrar a agente","próximos passos","o que a agente diz"}}},fp="16,151,24.300.0,43.98.0,35.151.0,32.67.0,35.94.0,37.106.0"}
P.entries["quest:95664"] = {n="Elder Knowledge",s="Uma estranha Relíquia Titânica dispersa luz como um prisma vivo, mas sua natureza permanece incerta. Você a leva ao Platô dos Anciãos, no Penhasco do Trovão, em busca de alguém que possa explicar seu poder ancestral.",h="Uma estranha Relíquia Titânica dispersa luz como um prisma vivo, mas sua natureza permanece incerta.",kw={"poder ancestral","fragmento composto","elder knowledge","platô dos anciãos","prisma vivo","penhasco do trovão","relíquia titânica"},sec={{t="Um Fragmento de Luz",b="O incomum fragmento composto em sua posse dispersa luz como um prisma vivo. Sua natureza é incerta, embora seu poder pareça ancestral. Você leva a Relíquia Titânica ao Platô dos Anciãos, no Penhasco do Trovão, e procura alguém que possa lhe contar mais."}},faq={{q="O que é a Relíquia Titânica?",a="É um fragmento composto incomum que dispersa luz como um prisma vivo. Sua natureza é incerta, mas seu poder parece ancestral.",al={"relíquia titânica","o que é a relíquia","fragmento de prisma"}},{q="Para onde levo a Relíquia Titânica?",a="Leve a Relíquia Titânica ao Platô dos Anciãos, no Penhasco do Trovão, e procure alguém que possa explicar o que ela é.",al={"para onde levar a relíquia","relíquia do platô dos anciãos","fragmento do penhasco do trovão"}},{q="Por que estou carregando o fragmento?",a="Você está procurando alguém no Platô dos Anciãos que possa lhe contar mais sobre a Relíquia Titânica.",al={"por que esta relíquia","o que fazer com o fragmento","missão elder knowledge"}}},fp="15,186,16.232.0,24.127.0,32.92.0,28.82.0"}
P.entries["quest:95682"] = {n="Open the Maw",s="Um Deathstalker Agent pede que você expulse os Dragonmaw dos Excavation Sites e traga qualquer coisa de interesse. O clã pode estar buscando um caminho de volta ao poder.",h="Um Deathstalker Agent pede que você expulse os Dragonmaw dos Excavation Sites e traga qualquer coisa de...",kw={"dark lady","deathstalker agent","dragonmaw","excavation site","renegados","rabisco órquico","rend"},sec={{t="Uma aproximação discreta",b="Um Deathstalker Agent fora do Excavation Site quer que as forças Dragonmaw sejam expulsas. Os remanescentes do clã domador de dragões acreditam ter encontrado algo que poderia restaurar seu antigo poder. Esse grupo maltrapilho precisa ser removido para que os Deathstalkers possam entrar sem serem vistos. Traga qualquer coisa de interesse que recuperar e mantenha o assunto entre o agente e o comando real."},{t="O rabisco recuperado",b="O Deathstalker Agent reconhece a escrita órquica entre os itens recuperados. Ela mostra que os Dragonmaw esperam apaziguar Rend, seu falso chefe guerreiro. O agente considera o esforço inútil, mas a informação é valiosa para a Dark Lady. O agente deixa os itens recuperados com você e avisa para não dizer nada sobre a missão."}},faq={{q="Quem me enviou ao Excavation Site?",a="Um Deathstalker Agent fora do Excavation Site pede que você expulse os Dragonmaw e traga qualquer coisa de interesse.",al={"quem quer expulsar os dragonmaw","tarefa do deathstalker agent","quem me enviou"}},{q="O que os Dragonmaw esperam fazer?",a="Os remanescentes dos Dragonmaw acreditam ter encontrado algo que poderia restaurar seu antigo poder.",al={"plano dos dragonmaw","por que os dragonmaw estão aqui","dragonmaw de volta ao poder"}},{q="Por que os Deathstalkers querem que o local seja desocupado?",a="Eles querem entrar no Excavation Site sem serem detectados.",al={"por que desocupar o excavation site","entrada dos deathstalkers","do que eles precisam"}},{q="O que devo trazer?",a="Traga ao Deathstalker Agent qualquer coisa de interesse que recuperar dos Dragonmaw.",al={"o que recuperar","itens dos dragonmaw","o que o agente quer"}},{q="Quem é a Dark Lady?",a="O agente usa esse título para se referir a Sylvanas, que lidera os Renegados.",al={"significado de dark lady","quem é a dark lady","título de sylvanas"}}},fp="12,153,16.379.0,20.323.1,35.117.0,36.95.0,47.50.0,25.77.0,21.63.0"}
P.entries["quest:95697"] = {n="Changing Tastes",s="Changing Tastes é uma missão de Orgrimmar relacionada à ambição culinária no Borstan's Firepit. Movido pelos conselhos de Zamja e por relatos de garras gigantes de raptor, Borstan encarrega aventureiros de viajar através do mar até o Pantanal para obter a exótica carne de raptor-do-bosque.",h="Changing Tastes é uma missão de Orgrimmar relacionada à ambição culinária no Borstan's Firepit.",kw={"borstan","borstan's firepit","changing tastes","sítios de escavação","orgrimmar","raptor-do-bosque","carne de raptor-do-bosque","pantanal","zamja"},ang={["faction:Horde"]="Abastecer o Borstan's Firepit significa aventurar-se nas profundezas de terras contestadas através do mar para trazer carnes exóticas até Orgrimmar.",["profession:Cooking"]="Borstan visa elevar as refeições rústicas tradicionais a algo grandioso o suficiente para a capital da Horda, destacando como os gostos culinários e os cardápios de taverna evoluem além dos pratos básicos de aldeia."},sec={{t="Elevando a culinária da capital",b="No coração de Orgrimmar, o Borstan's Firepit busca expandir suas ofertas culinárias. Zamja sugeriu introduzir pratos caseiros de raptor para atrair viajantes que sentem saudades das refeições reconfortantes e familiares de suas aldeias natais. Borstan gostou da ideia de servir raptor para atrair novos clientes, mas achou que simplesmente reproduzir pratos de aldeias rurais não era adequado para a grande capital da Horda. Em vez disso, ele imaginou uma versão mais grandiosa e ousada do clássico alimento básico."},{t="A caçada no Pantanal",b="A inspiração veio quando um caçador retornou a Orgrimmar trazendo uma garra colossal retirada dos raptores-do-bosque que rondam os sítios de escavação do Pantanal. Intrigado com a qualidade e o porte dessas feras, Borstan combina com aventureiros para que cruzem o mar rumo aos Reinos do Leste, enfrentem os locais de escavação e consigam carne de raptor-do-bosque de primeira qualidade para suas chamas ardentes."}},faq={{q="O que é a missão Changing Tastes?",a="Changing Tastes é uma tarefa culinária concedida em Orgrimmar. Borstan, proprietário do Borstan's Firepit, busca carne de raptor-do-bosque do distante Pantanal para elevar o cardápio de sua taverna além da culinária básica de aldeia.",al={"o que é changing tastes","missão changing tastes"}},{q="Quem é Zamja?",a="Zamja é uma colega ou trabalhadora do ramo culinário em Orgrimmar que sugeriu adicionar pratos caseiros de raptor ao Borstan's Firepit para atrair clientes que normalmente não o frequentam.",al={"quem é zamja","zamja culinária"}},{q="O que é o Borstan's Firepit?",a="O Borstan's Firepit é um restaurante localizado na capital da Horda, Orgrimmar, conhecido por servir carnes substanciosas e preparadas no fogo tanto para viajantes quanto para moradores locais.",al={"borstan's firepit","onde fica borstan"}},{q="Por que Borstan quer carne de raptor-do-bosque?",a="Enquanto Zamja propôs pratos caseiros comuns de raptor para atrair clientes, Borstan deseja uma versão mais grandiosa de sabores familiares. Inspirado pelo relato de um caçador sobre garras gigantes, ele escolheu os raptores-do-bosque encontrados no Pantanal.",al={"por que carne de raptor","por que raptor-do-bosque"}},{q="Onde os raptores-do-bosque estão localizados?",a="Os raptores-do-bosque habitam os sítios de escavação situados no Pantanal, uma região de tendência da Aliança localizada do outro lado do Grande Oceano, nos Reinos do Leste.",al={"onde encontro raptores-do-bosque","sítios de escavação do pantanal raptor"}},{q="Quem dá a missão Changing Tastes?",a="Borstan, o proprietário do Borstan's Firepit em Orgrimmar, oferece a missão após se inspirar nos conselhos de Zamja e em um troféu trazido por um caçador aventureiro.",al={"quem dá changing tastes","borstan concedente da missão"}}},fp="15,189,25.341.0,24.317.0,34.184.0,13.162.0,26.124.0,42.179.0,38.130.0,36.162.0"}
P.entries["quest:957"] = {n="Bashal'Aran",s="Esta missão encarrega os aventureiros de ajudar o espírito aprisionado de Astérion nas ruínas de Bashal'Aran. Ao levar o selo que o mantém cativo até as ruínas irmãs de Ameth'Aran, ao sul, os aventureiros procuram um modo de romper seus antigos grilhões.",h="Esta missão encarrega os aventureiros de ajudar o espírito aprisionado de Astérion nas ruínas de Bashal'Aran.",kw={"ameth'aran","astérion","athrikus","azshara","bashal'aran","costa negra","altaneiros","selo de pedra-da-lua"},ang={["class:Mage"]="Os encantamentos duradouros que aprisionam Astérion e as chamas remanescentes de Ameth'Aran oferecem um vislumbre do poder arcano bruto manejado pelos antigos feiticeiros Altaneiros.",["faction:Alliance"]="Romper as maldições ancestrais de Costa Negra ajuda a proteger as fronteiras dos novos assentamentos de elfos noturnos que se expandem a partir de Auberdine.",["race:NightElf"]="Para os elfos noturnos da Kalimdor atual, libertar Astérion é um encontro solene com o passado de seu povo anterior à Cisão e com a corrupção persistente da nobreza altaneira da Rainha Azshara."},sec={{t="Uma prisão de feitiçaria ancestral",b="O espírito de Astérion permanece em Bashal'Aran há milênios, acorrentado mesmo após a morte por um Selo Antigo de Pedra-da-lua. Criado pelas poderosas artes dos Altaneiros antes da Grande Cisão, esse selo não pode ser destruído pela força comum. Para quebrá-lo, é necessária a magia particular de uma chama ancestral que ainda arde entre as ruínas de Ameth'Aran, ao sul."},{t="As ruínas irmãs de Costa Negra",b="Bashal'Aran e Ameth'Aran já foram povoações irmãs e prósperas da civilização kaldorei, quando a Rainha Azshara governava e a Nascente da Eternidade sustentava seu império. Hoje, ambos os locais são ruínas assombradas e tomadas pela vegetação, repletas de fantasmas e energias arcanas instáveis. Sob um pavilhão de pedra em Ameth'Aran, um braseiro místico com uma chama azul-esverdeada oferece o único poder capaz de consumir a relíquia que aprisiona Astérion."},{t="A vingança desperta",b="Com o selo destruído, Astérion finalmente se vê livre e contempla uma Kalimdor despedaçada, profundamente diferente da era dourada que conhecia. Contudo, a liberdade não lhe traz paz. Ao perceber que Athrikus, seu antigo mestre e carcereiro altaneiro, ainda vive, o desespero ancestral de Astérion logo se transforma em um desejo frio e ardente de vingança."}},faq={{q="Quem é Astérion?",a="Astérion é um espírito de elfo noturno aprisionado nas ruínas de Bashal'Aran. Ele viveu há dez mil anos, durante o reinado da Rainha Azshara, e está preso ao local por um selo criado por um dos Altaneiros mais poderosos.",al={"astérion","quem é o fantasma","pnj astérion"}},{q="Onde posso destruir o Selo Antigo de Pedra-da-lua?",a="O selo deve ser levado para o sul, até Ameth'Aran, ruína irmã de Bashal'Aran. Procure um pavilhão de pedra que abriga um grande braseiro cúbico com uma chama mágica ancestral azul-esverdeada.",al={"onde fica a chama","localização da chama ancestral","destruir o selo"}},{q="Qual é a relação entre Bashal'Aran e Ameth'Aran?",a="Eram cidades irmãs do antigo império dos elfos noturnos antes da Cisão. Ambas foram devastadas há dez mil anos, deixando para trás pilares de pedra assombrados, energias arcanas residuais e espíritos inquietos.",al={"ruínas irmãs","relação com ameth'aran","bashal'aran e ameth'aran"}},{q="Quem aprisionou Astérion?",a="Astérion conta que um dos Altaneiros mais poderosos criou o selo que o mantém preso. Mais detalhes sobre seu antigo mestre são revelados ao longo da série de missões.",al={"quem aprisionou astérion","quem é athrikus","mestre de astérion"}},{q="De que época Astérion se lembra?",a="Astérion caminhou livremente pelo mundo quando a Nascente da Eternidade original ainda existia, a Rainha Azshara governava o império e a nobreza altaneira mantinha sua corte majestosa, antes da Cisão.",al={"passado de astérion","época da nascente da eternidade","quantos anos tem astérion"}},{q="Libertar Astérion permite que seu espírito descanse?",a="Destruir o selo deve romper a prisão de Astérion. Você descobrirá como ele reage à liberdade quando retornar para falar com ele.",al={"astérion descansa em paz","o que acontece com astérion","astérion após ser libertado"}}},fx={["8275c861"]={q="Por que Astérion quer que o Selo Antigo de Pedra-da-lua seja destruído?",a="O Selo Antigo de Pedra-da-lua é a âncora que prende o espírito de Astérion em tormento dentro das ruínas de Bashal'Aran. Criado milênios atrás por uma poderosa feitiçaria dos Altaneiros, ele o mantém aprisionado e cego para o mundo além. Destruí-lo na mística chama antiga de Ameth'Aran é a única maneira de romper suas correntes etéreas, concedendo-lhe liberdade e a clareza para testemunhar o que se tornou de Kalimdor.",al={"por que destruir o selo de pedra-da-lua","motivação de astérion","por que astérion quer quebrar o selo"}},["51df5ddd"]={q="Por que Astérion precisa que você leve o selo para Ameth'Aran?",a="Limitado pela antiga magia dos Altaneiros que o ancora a Bashal'Aran, Astérion não pode deixar as ruínas imediatas, muito menos viajar para o sul até Ameth'Aran. Ele precisa de um viajante para levar o selo até a chama antiga.",al={"por que astérion não pode destruir o selo","por que astérion precisa de mim","por que enviar um aventureiro para destruir o selo"}}},fp="11,147,27.134.0,23.371.0,17.273.1,16.195.0,46.180.0,60.221.0,24.132.1,32.178.0,45.113.1"}
P.entries["quest:95737"] = {n="Seeking Caitlin",s="Uma alquimista pede que você encontre Caitlin Grassman no Porto de Menethil. Caitlin talvez saiba por que o marido ainda não voltou com notícias sobre uma erva rara encontrada em um sítio de escavação.",h="Uma alquimista pede que você encontre Caitlin Grassman no Porto de Menethil.",kw={"alquimista","caitlin grassman","escavação","sementes de erva","porto de menethil","erva primordial","seeking caitlin","pantanal"},ang={["profession:Herbalism"]="Como herborista, você recebe a tarefa de verificar como Caitlin está após a equipe do marido dela encontrar sinais de uma erva primordial rara."},sec={{t="Um Relato Ausente",b="A alquimista soube por Caitlin que a equipe de escavação do marido encontrou sinais de uma erva primordial. Ela ainda não sabe quanto foi encontrado nem se é possível chegar até ela. A alquimista pede que você fale com Caitlin no Porto de Menethil, onde as duas aguardam notícias sobre as sementes prometidas."}},faq={{q="Quem é Caitlin Grassman?",a="Caitlin Grassman é uma alquimista no Porto de Menethil. O marido dela fazia parte de uma equipe de escavação que encontrou sinais de uma erva primordial.",al={"caitlin","quem é caitlin","caitlin grassman"}},{q="O que a alquimista quer que eu faça?",a="A alquimista pede que você fale com Caitlin Grassman no Porto de Menethil.",al={"encontrar caitlin","falar com caitlin","missão da caitlin"}},{q="O que a equipe de escavação encontrou?",a="A equipe encontrou sinais de uma erva primordial há muito desaparecida, mas ainda não se sabe quanto há dela nem se é possível alcançá-la.",al={"erva primordial","erva rara","descoberta na escavação"}},{q="Por que elas estão preocupadas?",a="Caitlin prometeu à alquimista que o marido traria sementes da erva, mas elas ainda não chegaram. As duas suspeitam que algo no sítio de escavação esteja causando problemas.",al={"onde estão as sementes","sementes de erva desaparecidas","por que estão preocupadas"}}},fp="15,161,16.313.0,24.130.0,38.73.0,34.117.0,23.151.0"}
P.entries["quest:95748"] = {n="The Gurubashi Legends of Old",s="Um estudioso troll busca um decalque de uma tabuleta antiga ao norte do Arrecife Torpe. Sua lenda pode esclarecer a dimensão da cidade perdida de I'lalai.",h="Um estudioso troll busca um decalque de uma tabuleta antiga ao norte do Arrecife Torpe.",kw={"ruína antiga","gurubashi","i'lalai","lenda","decalque","tabuleta","troll","o arrecife torpe"},ang={["race:Troll"]="Como troll, você recebe um pedido para ajudar um estudioso a pesquisar lendas de uma cidade troll perdida."},sec={{t="Uma Tabuleta à Beira-Mar",b="O estudioso compara um fragmento de tabuleta que você trouxe com as ruínas ao largo do Arrecife Torpe. Essas ruínas parecem pequenas demais para corresponder à vasta civilização descrita no texto. Por isso, o estudioso pede que você faça um decalque de uma tabuleta em uma antiga ruína troll nas colinas costeiras ao norte."},{t="Uma Antiga Lembrança",b="O estudioso recebe o decalque com satisfação e diz que conhece a tabuleta desde a juventude. Muitas luas se passaram desde a última leitura, e a memória do estudioso se apagou."}},faq={{q="O que o estudioso quer?",a="O estudioso quer um decalque de uma tabuleta que contém lendas da cidade troll perdida de I'lalai.",al={"decalque da tabuleta","do que ele precisa","pedido de decalque"}},{q="Onde fica a tabuleta?",a="Ela fica em uma antiga ruína troll nas colinas costeiras ao norte do Arrecife Torpe.",al={"localização da tabuleta","onde fica a tabuleta","ao norte do arrecife"}},{q="Por que o estudioso quer um decalque?",a="Um fragmento de tabuleta que você trouxe descreve I'lalai como uma vasta civilização, mas as ruínas ao largo do Arrecife Torpe parecem pequenas demais para corresponder.",al={"por que fazer decalque","tabuleta de i'lalai","lenda da cidade perdida"}},{q="O que é I'lalai?",a="I'lalai é descrita no fragmento de tabuleta como uma cidade troll perdida e uma vasta civilização.",al={"cidade de i'lalai","cidade troll perdida","ilalai"}},{q="O que o estudioso diz sobre a tabuleta?",a="O estudioso já leu a tabuleta quando era jovem, mas diz que muitas luas se passaram e sua memória se apagou.",al={"memória do estudioso","já leu a tabuleta","antiga lenda troll"}}},fp="28,122,21.278.0,13.159.0,27.93.0,20.71.0,36.128.0,16.91.0,43.105.0"}
P.entries["quest:95770"] = {n="Locating the Lost City",s="Kin'weelay pede que você procure no Arrecife Torpe uma caverna ligada à cidade perdida. Os naga reunidos lá podem ter encontrado algo que valha a pena investigar.",h="Kin'weelay pede que você procure no Arrecife Torpe uma caverna ligada à cidade perdida.",kw={"caverna","i'lalai","kin'weelay","locating the lost city","lost city","murlocs","naga","o arrecife torpe"},sec={{t="Uma caverna no arrecife",b="Kin'weelay se lembra de mergulhar entre as ruínas do Arrecife Torpe antes de os murlocs se estabelecerem lá. Ele se lembra de uma caverna e pede que você explore o arrecife em busca da entrada. Agora os naga se reúnem na região, e ele quer saber o que os atraiu até lá."},{t="Uma possível descoberta",b="Quando você retorna, Kin'weelay ouve seu relato. Os naga entram e saem da caverna em ruínas, mas seu propósito continua incerto. Ele se pergunta se ela tem ligação com I'lalai e a Lost City, há muito considerada um mito entre os trolls. Agora ele quer investigar."}},faq={{q="Quem está me pedindo para vasculhar o Arrecife Torpe?",a="Kin'weelay pede que você explore o Arrecife Torpe e procure a entrada de uma caverna.",al={"quem me enviou","pedido de kin weelay","quem quer isso"}},{q="Por que estou procurando uma caverna?",a="Kin'weelay se lembra de uma caverna entre as ruínas do Arrecife Torpe e suspeita que ela possa ajudar a localizar a Lost City.",al={"por que a caverna","pista da lost city","o que estou procurando"}},{q="Por que os naga estão se reunindo lá?",a="Kin'weelay ouviu dizer que os naga estão se reunindo na região, mas o motivo é desconhecido.",al={"naga no arrecife","por que os naga","motivo dos naga"}},{q="O que aconteceu com as ruínas do Arrecife Torpe?",a="Os murlocs se estabeleceram entre as ruínas do Arrecife Torpe depois da juventude de Kin'weelay, época em que ele costumava mergulhar lá.",al={"ruínas do arrecife torpe","murlocs lá","quem se estabeleceu no arrecife"}},{q="Onde fica a entrada da caverna?",a="A entrada da caverna fica no Arrecife Torpe. Kin'weelay pede que você explore o arrecife à procura dela.",al={"localização da caverna","encontrar entrada","onde fica a caverna"}}},fp="22,146,20.228.0,20.259.1,41.76.0,30.102.0,33.88.0,37.103.0,29.88.0"}
P.entries["quest:95772"] = {n="Songblade Search",s="Songblade Search é uma incumbência anã na qual Dorin Songblade pede aos viajantes que verifiquem como está seu irmão Daewyn no Pantanal. Daewyn partiu com uma equipe arqueológica de Loch Modan para escavar em colinas inexploradas, mas seu silêncio incomum deixou seu irmão temendo o pior.",h="Songblade Search é uma incumbência anã na qual Dorin Songblade pede aos viajantes que verifiquem como está...",kw={"daewyn songblade","dls","dorin songblade","loch modan","songblade search","pantanal","sítio de escavação de whelgar"},ang={["faction:Alliance"]="Viajantes da Aliança que se aventuram entre Loch Modan e o Porto de Menethil frequentemente passam pelos sítios de escavação, prestando ajuda a garimpeiros e artesãos anões retidos.",["race:Dwarf"]="Equipes de expedição anãs e escavações arqueológicas são comuns por toda Khaz Modan, mas aventurar-se além da segurança de Loch Modan rumo ao perigoso Pantanal frequentemente traz graves riscos para os parentes."},sec={{t="A Inquietação de um Irmão",b="Dorin Songblade permaneceu em sua oficina, inundado de pedidos para reajustar cinturões, enquanto seu irmão Daewyn se juntou a uma equipe de escavação anã que partia de Loch Modan. Daewyn aventurou-se para o norte nas colinas acidentadas do Pantanal, ansioso para explorar terras virgens intocadas por picaretas anãs. No entanto, Daewyn costuma enviar cartas logo após chegar, e seu silêncio deixou Dorin profundamente inquieto."},{t="A Escavação no Pantanal",b="Viajantes que viajam para o Pantanal podem localizar Daewyn Songblade entre os escavadores no Sítio de Escavação de Whelgar. Muito parecido com seu irmão Dorin, Daewyn carrega um rifle característico marcado com as iniciais 'DLS' entalhadas na coronha de madeira, provando que ele realmente chegou ao remoto acampamento de escavação nos Pântanos."}},faq={{q="Quem dá a missão Songblade Search?",a="Dorin Songblade dá a missão. Ele é um artesão atualmente sobrecarregado de trabalho reajustando uma pilha de cinturões, o que o impediu de acompanhar seu irmão em uma escavação arqueológica.",al={"quem dá songblade search","concedente da missão songblade search","dorin songblade"}},{q="Quem é Daewyn Songblade?",a="Daewyn Songblade é irmão de Dorin Songblade. Ele partiu ao lado de uma equipe de escavação vinda de Loch Modan com destino às colinas selvagens do Pantanal, mas não enviou notícias como costuma fazer.",al={"quem é o irmão de dorin","anão songblade desaparecido","daewyn songblade"}},{q="Onde Daewyn pode ser encontrado?",a="Daewyn está localizado no Sítio de Escavação de Whelgar, no Pantanal. Ele pode ser identificado por sua forte semelhança familiar com Dorin e por sua arma de fogo, que tem 'DLS' entalhado em sua coronha de madeira.",al={"onde está daewyn","onde encontrar daewyn songblade","localização de songblade search"}},{q="Por que Daewyn viajou para o Pantanal?",a="Daewyn juntou-se a uma expedição de Dwarven Digging vinda de Loch Modan em busca de colinas inexploradas no Pantanal para realizar uma escavação arqueológica.",al={"por que daewyn foi para o pantanal","objetivo da escavação de whelgar","por que os anões foram para o pantanal"}},{q="O que significam as iniciais entalhadas na arma?",a="As iniciais 'DLS' entalhadas na coronha da arma de fogo pertencem a Daewyn Songblade, confirmando que o anão encontrado no sítio de escavação é de fato o irmão desaparecido de Dorin.",al={"o que significa dls","entalhe da arma dls","iniciais dls"}},{q="Por que Dorin estava preocupado com o irmão?",a="Dorin ficou preocupado porque Daewyn costuma escrever prontamente após partir em viagem. Não tendo recebido cartas após a partida para o Pantanal, Dorin teve o pressentimento inquietante de que algo havia dado errado.",al={"por que dorin está preocupado","por que procurar daewyn","motivo de songblade search"}}},fp="16,183,18.330.0,23.239.1,37.155.0,24.160.0,26.152.0,38.111.0,44.147.0,40.170.0"}
P.entries["quest:95773"] = {n="Enemies in the Water",s="Nagas se reúnem perto de antigas ruínas de trolls ao largo da costa, enquanto a Horda já sofre com ataques às suas caravanas. Você recebe a missão de enfrentar essa ameaça e mostrar que está provando seu valor.",h="Nagas se reúnem perto de antigas ruínas de trolls ao largo da costa, enquanto a Horda já sofre com ataques às...",kw={"bloodscalp","brinescale","inimigos na água","grom'gol","horda","nagas","ogros","tridentes","ruínas de trolls"},ang={["faction:Horde"]="A Horda busca proteger suas caravanas enquanto fica atenta a um possível ataque pelo mar."},sec={{t="Relatos da costa",b="A Horda recebeu relatos de nagas se reunindo perto de antigas ruínas de trolls no fundo do mar. Ataques de Bloodscalp e ogros já estão sobrecarregando suas defesas, então uma ameaça vinda da água deixa pouca margem para demora. Você recebe a missão de enfrentar os escaramuçadores Brinescale e trazer seus tridentes como prova."},{t="Uma mensagem em Grom’gol",b="Em Grom’gol, os tridentes que você trouxer serão fincados do lado de fora dos portões. Essa exibição servirá de aviso de que não se deve brincar com a Horda, e seu trabalho recebe os elogios do comandante."}},faq={{q="Por que os nagas estão perto da costa?",a="Os relatos dizem que os nagas estão se reunindo ao redor de antigas ruínas de trolls no fundo do mar.",al={"nagas na costa","nagas na água","por que há nagas aqui"}},{q="Quem são os inimigos aqui?",a="A ameaça vem dos escaramuçadores Brinescale, um grupo de nagas avistado perto da costa.",al={"inimigos na água","quem são os nagas","brinescale"}},{q="Por que a Horda quer que os nagas sejam detidos?",a="A Horda já está no limite ao defender suas caravanas de ataques de Bloodscalp e ogros, e teme um ataque surpresa pelo mar.",al={"por que matar nagas","problema da horda com nagas","ataque pelo mar"}},{q="Que prova é solicitada?",a="Você recebe a missão de trazer tridentes Brinescale como prova do seu sucesso.",al={"tridentes como prova","o que trazer","tridentes brinescale"}},{q="O que acontecerá com os tridentes?",a="Eles serão fincados do lado de fora dos portões de Grom’gol como aviso de que não se deve brincar com a Horda.",al={"mensagem dos tridentes","fincar tridentes","tridentes de gromgol"}},{q="Como isso prova meu valor?",a="O comandante elogia seu trabalho e diz que você está provando rapidamente seu valor à Horda.",al={"provar valor","aprovação da horda","por que estou aqui"}}},fp="20,188,22.299.0,23.197.1,32.74.0,25.86.0,44.135.0,24.73.0,33.104.0,29.89.0"}
P.entries["quest:95774"] = {n="Her Name Is Olgra",s="Ao saber da morte de Olgra em batalha, Mankrik decide homenageá-la com um memorial duradouro. Ele pede que você recupere seus adornos de osso desaparecidos dos saqueadores Razormane das proximidades, para que possam repousar ao lado de seu monumento.",h="Ao saber da morte de Olgra em batalha, Mankrik decide homenageá-la com um memorial duradouro.",kw={"adornos","mankrik","memorial","olgra","osso polido","quilboar","saqueadores razormane"},sec={{t="Honrando os Caídos",b="Embora um curandeiro tenha conseguido salvar Mankrik, Olgra sucumbiu aos ferimentos no campo de batalha. Determinado a garantir que seu nome e sacrifício nunca sejam esquecidos, o guerreiro enlutado se prepara para construir uma homenagem duradoura à sua memória."},{t="Lembranças Perdidas",b="Olgra usava ornamentos queridos de osso polido, mas eles estavam desaparecidos de seu local de repouso. Mankrik quer recuperar esses tesouros pessoais dos saqueadores Razormane das proximidades, para que possam repousar ao lado do monumento que está erguendo para ela."}},faq={{q="Quem é Olgra?",a="Olgra tombou em batalha contra os quilboar. O curandeiro que ajudou Mankrik conseguiu salvá-lo, mas ela não pôde ser resgatada, e Mankrik pretende honrar sua memória para sempre.",al={"quem é olgra","esposa de mankrik","quem morreu"}},{q="O que são os adornos de Olgra?",a="Seus adornos são peças queridas de joalheria artesanal feitas de osso polido, que ela usava antes de ser morta.",al={"o que são os adornos de olgra","joias de olgra","de que são feitos os adornos"}},{q="Por que os saqueadores Razormane estão sendo caçados?",a="Os ornamentos foram levados do corpo de Olgra após sua morte, levando Mankrik a enviar você contra os saqueadores Razormane perto do local onde ela morreu para recuperá-los.",al={"por que matar saqueadores razormane","quem roubou os adornos de olgra","onde estão os adornos"}},{q="O que Mankrik fará com os adornos recuperados?",a="Mankrik planeja colocar as joias de osso recuperadas ao lado de um monumento que está construindo em homenagem a Olgra, para que sua memória nunca se apague.",al={"memorial de mankrik","o que mankrik fará com os adornos","por que mankrik quer os adornos"}}},fp="17,152,19.165.0,14.226.0,13.135.0,28.111.0,43.127.0,51.122.0"}
P.entries["quest:95775"] = {n="The Drowned City",s="Uma pesquisadora pede que você inspecione ruínas guardadas por nagas e copie as inscrições de suas tábuas. A cidade pode ser I’lalai, rica em história esquecida.",h="Uma pesquisadora pede que você inspecione ruínas guardadas por nagas e copie as inscrições de suas tábuas.",kw={"carvão","cidade afogada","couro","i’lalai","história esquecida","nagas","decalques","ruínas","tábuas"},sec={{t="Além da Caverna",b="A pesquisadora está velha demais para entrar nas ruínas, então pede que você vá em seu lugar. Do outro lado da caverna guardada por nagas, ela suspeita que as ruínas possam ser I’lalai. A cidade perdida pode conter um vasto conhecimento histórico. Você deve fazer decalques de quaisquer tábuas que encontrar e trazê-los de volta."}},faq={{q="O que é a Cidade Afogada?",a="Segundo a pesquisadora que enviou você, as ruínas podem ser a cidade perdida de I’lalai.",al={"cidade afogada","que cidade é esta","ruínas de i’lalai"}},{q="Quem quer que eu explore as ruínas?",a="Uma pesquisadora pede que você explore as ruínas porque está velha demais para ir até lá.",al={"quem me enviou","quem quer os decalques","pedido da pesquisadora"}},{q="Por que estou sendo enviado para lá?",a="A pesquisadora espera que as ruínas contenham um vasto conhecimento histórico esquecido.",al={"por que explorar","por que as tábuas","história esquecida"}},{q="O que devo trazer de volta?",a="Faça decalques de quaisquer tábuas que encontrar usando couro e carvão, depois volte para a pesquisadora.",al={"o que trazer de volta","decalques de tábuas","tarefa dos decalques"}},{q="Onde ficam as ruínas?",a="As ruínas ficam do outro lado da caverna guardada por nagas.",al={"onde fica a cidade afogada","caverna dos nagas","local das ruínas"}}},fp="16,132,17.294.0,25.83.0,34.82.0,26.77.0,33.95.0,20.62.0"}
P.entries["quest:95776"] = {n="The Only Good Brinescale...",s="Nagas nas águas perto da costa levantam suspeitas de uma ameaça maior. Você deve encontrar o líder deles na Drowned City.",h="Nagas nas águas perto da costa levantam suspeitas de uma ameaça maior.",kw={"brinescale","costa","drowned city","infiltração","kin'weelay","nagas","var'taka"},sec={{t="Uma ameaça no mar",b="Os nagas perto da costa foram mortos, mas seu número aponta para um perigo maior. Kin'weelay acredita que os nagas Brinescale estão entrando nas ruínas da Drowned City. A presença deles ali sugere que procuram algo capaz de pôr a costa em risco. Você deve matar o líder deles, Var'Taka."},{t="O retorno",b="Quando você volta, quem contratou você toma sua chegada como sinal de que Var'Taka está morto. Com o líder naga fora do caminho, há uma preocupação a menos para a costa."}},faq={{q="Por que os nagas Brinescale estão na Drowned City?",a="Kin'weelay acredita que os nagas Brinescale estão procurando algo na Drowned City, mas não se sabe o que procuram.",al={"por que os nagas estão lá","objetivo dos brinescale","o que os nagas estão procurando"}},{q="Quem é Kin'weelay?",a="Kin'weelay acredita que os nagas Brinescale estão se infiltrando na Drowned City.",al={"kin weelay","quem é kin'weelay","kin"}},{q="Quem é Var'Taka?",a="Var'Taka é o líder dos nagas Brinescale na Drowned City.",al={"var taka","líder dos nagas","líder dos brinescale"}},{q="O que me pedem para fazer?",a="Você deve matar Var'Taka na Drowned City.",al={"o que devo fazer","qual é a tarefa","quem matar"}}},fp="27,126,17.299.0,10.143.1,48.121.0,18.89.0,16.66.0,22.51.0"}
P.entries["quest:95786"] = {n="An Acquaintance in Southshore",s="Irmão Nimetz envia você à Costa Sul com um relatório para o Historiador Dibbs. Trolls agitados e a palavra “I'lalai” podem estar ligados à corrupção do Coronel Kurzen.",h="Irmão Nimetz envia você à Costa Sul com um relatório para o Historiador Dibbs.",kw={"irmão nimetz","coronel kurzen","corrupção","fetiches","i'lalai","historiador dibbs","relatório do batedor","costa sul","selva do espinhaço","lendas trolls"},sec={{t="Uma palavra no relatório",b="Irmão Nimetz envia você da Selva do Espinhaço à Costa Sul com um conjunto de lendas trolls, fetiches e o relatório de um batedor. Os trolls locais estão agitados e falam de “I'lalai”. Nimetz espera que o Historiador Dibbs possa dizer se isso tem relação com a mente corrompida do Coronel Kurzen."},{t="Na Costa Sul",b="O Historiador Dibbs recebe você na Costa Sul e comenta sobre a longa viagem desde a Selva do Espinhaço. Ele pergunta o que trouxe você até lá, com o relatório e os materiais de Nimetz em mãos."}},faq={{q="Quem me enviou à Costa Sul?",a="Irmão Nimetz enviou você da Selva do Espinhaço para falar com o Historiador Dibbs.",al={"quem me enviou","nimetz costa sul","irmão nimetz"}},{q="Por que estou indo à Costa Sul?",a="Nimetz quer que o Historiador Dibbs examine lendas trolls, fetiches e o relatório de um batedor em busca de uma possível ligação com a corrupção do Coronel Kurzen.",al={"por que costa sul","relatório dibbs","o que estou levando"}},{q="Quem é o Historiador Dibbs?",a="O Historiador Dibbs é amigo de Nimetz no Contraforte de Eira dos Montes, onde estuda lendas trolls e magia maligna.",al={"quem é dibbs","dibbs costa sul","historiador"}},{q="O que diz o relatório do batedor?",a="O relatório diz que os trolls locais estão agitados e mencionaram “I'lalai”.",al={"relatório do batedor","trolls agitados","o que é i'lalai"}},{q="Onde encontro o Historiador Dibbs?",a="O Historiador Dibbs está na Costa Sul.",al={"localização de dibbs","encontrar dibbs","costa sul"}}},fp="29,161,20.281.0,13.171.0,26.74.0,29.144.0,24.110.0,33.79.0,33.34.0"}
P.entries["quest:95787"] = {n="Take Two With Water",s="Historiador Dibbs pede que você reúna lendas da Drowned City, onde acredita que a cidade troll perdida de I’lalai ressurgiu. Ele a chama de possivelmente a descoberta arqueológica do século.",h="Historiador Dibbs pede que você reúna lendas da Drowned City, onde acredita que a cidade troll perdida de...",kw={"drowned city","i'lalai","loa","historiador dibbs","decalques de tabuletas","marés","lendas trolls","zandali"},sec={{t="A descoberta de Dibbs",b="Historiador Dibbs leu um relatório de reconhecimento e lendas trolls que sugerem que I’lalai, uma cidade troll perdida, ressurgiu na costa da Selva do Espinhaço. Ele pede que você traga lendas da Drowned City. A descoberta pode mudar o que se sabe sobre as ruínas antigas."},{t="As tabuletas",b="Dibbs recebe você de volta das ruínas trolls e mal pode esperar para saber o que você encontrou. Quatro tabuletas trazem novas lendas, embora seu zandali antigo esteja enferrujado. Ele acha que as palavras podem mencionar um loa desconhecido associado às marés."}},faq={{q="Quem está pedindo essas lendas?",a="Historiador Dibbs pede que você reúna lendas da Drowned City.",al={"quem é dibbs","historiador dibbs","pedido de dibbs"}},{q="O que é a Drowned City?",a="Dibbs acredita que pode ser a cidade troll perdida de I’lalai, ressurgida na costa da Selva do Espinhaço.",al={"drowned city","que cidade","cidade troll submersa"}},{q="O que Dibbs quer que eu traga?",a="Ele pede que você faça decalques a carvão das tabuletas encontradas na Drowned City e traga as lendas.",al={"o que coletar","decalques de tabuletas","pedido da drowned city"}},{q="Por que Dibbs quer as lendas?",a="Ele acredita que o relatório de reconhecimento e as lendas trolls podem indicar a cidade perdida de I’lalai.",al={"por que lendas","pesquisa de dibbs","o que ele estuda"}},{q="Onde I’lalai pode estar?",a="Dibbs acredita que I’lalai ressurgiu logo além da costa da Selva do Espinhaço.",al={"onde fica ilalai","localização de i'lalai","cidade troll perdida"}}},fp="19,194,19.263.0,11.226.1,32.67.0,25.93.0,38.102.0,32.90.0,25.71.0"}
P.entries["quest:95788"] = {n="Magics of the Drowned City",s="Um estudioso pede que você traga fetiches trolls de I'lalai para estudo. O desenho estranho deles pode estar ligado à magia que ergueu a cidade submersa.",h="Um estudioso pede que você traga fetiches trolls de I'lalai para estudo.",kw={"irmão nimetz","magia sombria","cidade submersa","fetiches","i'lalai","naga","piratas","serpente marinha","troll","morto-vivo"},sec={{t="Fetiches para estudo",b="O estudioso que examina os fetiches Rachacrânio do Irmão Nimetz pede que você reúna mais em I'lalai. Rumores dizem que a cidade troll perdida emergiu das profundezas, e que sua elevação pode envolver magia sombria. O estudioso quer comparar esses fetiches com os que já examinou."},{t="Muitas magias",b="Quando você retorna, o estudioso conclui que os fetiches de I'lalai são distintos, com uma construção intrincada, mas simples, e o desenho de uma grande serpente marinha. Seu relato descreve mortos-vivos, piratas, rituais de sangue e forças naga convergindo entre as ruínas. Agora, a cidade reúne muitos tipos de magia, e o estudioso vê motivos para continuar investigando."}},faq={{q="Quem pede os fetiches?",a="O estudioso que examinou os fetiches Rachacrânio do Irmão Nimetz pede que você traga fetiches trolls de I'lalai.",al={"quem quer fetiches","fetiches do estudioso"}},{q="Por que os fetiches estão sendo reunidos?",a="O estudioso quer investigar se os fetiches de I'lalai têm ligação com a magia sombria que, segundo dizem, ergueu a cidade.",al={"por que reunir fetiches","estudo dos fetiches"}},{q="O que é I'lalai?",a="I'lalai é uma cidade troll perdida que, segundo rumores, emergiu das profundezas.",al={"cidade submersa","cidade troll"}},{q="O que chama atenção nos fetiches de I'lalai?",a="Eles têm o desenho de uma grande serpente marinha, e sua construção é mais intrincada em alguns aspectos e mais simples em outros do que a dos fetiches examinados antes.",al={"desenho dos fetiches","fetiche de serpente marinha"}},{q="Que forças estão convergindo para I'lalai?",a="Seu relato descreve mortos-vivos errantes, piratas invasores, rituais de sangue e forças naga entre as ruínas.",al={"quem está em i'lalai","mortos-vivos piratas naga"}}},fp="26,142,18.273.0,11.331.1,26.111.0,36.115.0,16.74.0,43.148.0,38.104.0"}
P.entries["quest:95789"] = {n="Shady Saltseers",s="Um contato do Barão Rezingada envia você à Drowned City atrás dos Saltseers, piratas que colecionam artefatos mágicos. As mercadorias roubadas por eles chamaram atenção agora que a ruína trólica submersa voltou à superfície.",h="Um contato do Barão Rezingada envia você à Drowned City atrás dos Saltseers, piratas que colecionam artefatos...",kw={"barão rezingada","drowned city","artefatos mágicos","piratas","saltseers","shady saltseers","ruína trólica","voodoo infused artifacts"},sec={{t="O pedido de um barão",b="Um contato do Barão Rezingada pede que você recupere artefatos dos Saltseers na Drowned City. Os piratas colecionam objetos mágicos, e o retorno da ruína deixou mercadorias ali ao alcance de quem quiser pegá-las. Os artefatos roubados por eles são o que o contato de Rezingada procura."}},faq={{q="Quem quer os artefatos dos Saltseers?",a="Um contato do Barão Rezingada pede que você recupere os artefatos.",al={"quem me enviou","contato do barão rezingada","quem quer artefatos"}},{q="Quem são os Saltseers?",a="Os Saltseers são piratas que colecionam artefatos mágicos.",al={"piratas saltseer","quem são os saltseers","saltseers"}},{q="Onde estão os Saltseers?",a="Eles estão na Drowned City, uma ruína trólica submersa que voltou à superfície.",al={"onde fica drowned city","localização dos saltseers","drowned city"}},{q="Que artefatos estou procurando?",a="Você recebe o pedido de recuperar Voodoo Infused Artifacts roubados pelos Saltseers.",al={"o que coletar","artefatos de vodu","mercadorias roubadas"}}},fp="15,205,19.255.0,37.62.0,22.56.0,24.71.0,32.74.0"}
P.entries["quest:95791"] = {n="The Saltseer Captain",s="Um caçador rival quer Captain Dreadrise e seus Saltseer Coroners fora de Drowned City. A tripulação deles continua reunindo os artefatos mágicos que ele procura.",h="Um caçador rival quer Captain Dreadrise e seus Saltseer Coroners fora de Drowned City.",kw={"captain dreadrise","drowned city","artefatos mágicos","piratas","saltseer","saltseer coroners"},sec={{t="Um rival na cidade",b="Um caçador rival busca sua ajuda em Drowned City, onde os piratas Saltseer se tornaram uma pedra no sapato dele. Captain Dreadrise e seus Saltseer Coroners reúnem os artefatos mágicos que ele quer. Ele pede que você tire o capitão e três tripulantes de cena."}},faq={{q="Quem é Captain Dreadrise?",a="Captain Dreadrise lidera os piratas Saltseer em Drowned City.",al={"dreadrise","capitão saltseer","sujeito capitão"}},{q="Quem são os Saltseer Coroners?",a="Os Saltseer Coroners são tripulantes com quem Captain Dreadrise trabalha na coleta de artefatos mágicos.",al={"tripulação saltseer","coroners","tripulação de dreadrise"}},{q="Por que o responsável pela missão quer se livrar de Dreadrise?",a="Captain Dreadrise e sua tripulação continuam reunindo artefatos mágicos que o responsável pela missão procura, e ele está cansado da concorrência.",al={"por que matar dreadrise","por que eliminar o capitão","rival de dreadrise"}},{q="Onde estão Captain Dreadrise e os Saltseers?",a="Captain Dreadrise e os piratas Saltseer estão em Drowned City.",al={"onde está dreadrise","localização dos saltseer","piratas de drowned city"}},{q="O que o responsável pela missão pede que eu faça?",a="O responsável pela missão pede que você mate Captain Dreadrise e três Saltseer Coroners em Drowned City.",al={"o que fazer","missão de dreadrise","tarefa saltseer"}}},fp="20,154,19.268.0,25.65.0,30.99.0,39.127.0,46.67.0,33.93.0"}
P.entries["quest:95795"] = {n="Fallen in the Fen",s="Fallen in the Fen é uma jornada sombria que começa ao encontrar um anão caído em meio a um sítio de escavação. Entregar a trágica notícia ao irmão dele, Dorin Songblade em Vila Plácida, traz um encerramento para um artesão desolado que estava forjando presentes para o seu parente falecido.",h="Fallen in the Fen é uma jornada sombria que começa ao encontrar um anão caído em meio a um sítio de escavação.",kw={"ferreiro","dorin","dorin songblade","anão","escavação","locais de escavação","fallen in the fen","vila plácida","songblade"},ang={["faction:Alliance"]="Trazer paz a um artesão em Montanhas Cristarrubra oferece consolo a um morador enlutado da vila durante tempos conturbados para o reino.",["profession:Blacksmithing"]="Dorin dedicou sua perícia a armamentos concebidos como uma surpresa para seu irmão, forjando equipamentos que agora servem apenas como lembrança da morte prematura de seu irmão.",["race:Dwarf"]="O povo anão compreende a dor amarga de perder um irmão para escavações ancestrais e terras ermas indomadas, especialmente quando o metal forjado sobrevive à mão que deveria empunhá-lo."},sec={{t="Tragédia na Escavação",b="Uma tragédia silenciosa se desenrola nos sítios de escavação, onde o corpo sem vida de um anão aventureiro é descoberto. Após cobrir os restos mortais com o próprio manto do anão, um aventureiro leva a terrível notícia de volta a Vila Plácida para encontrar seus parentes."},{t="O Luto de um Irmão",b="Em Vila Plácida, o artesão anão Dorin Songblade desaba ao saber do destino de seu irmão. Dorin havia passado semanas trabalhando em sua forja, criando um conjunto surpresa de equipamentos para seu irmão que não ficou pronto a tempo para a expedição. Tomado pelo remorso de não ter ido junto, Dorin não suporta reforjar nem vender o que criou com as próprias mãos, optando por conceder as peças finalizadas àquele que lhe trouxe paz."}},faq={{q="O que é Fallen in the Fen?",a="Fallen in the Fen é uma tarefa sombria iniciada ao descobrir os restos mortais de um anão caído em um sítio de escavação. Após cobrir o corpo com o manto dele, você viaja até Vila Plácida para informar pessoalmente ao irmão em luto do anão, Dorin Songblade, sobre o destino dele.",al={"o que é fallen in the fen","missão fallen in the fen"}},{q="Quem é Dorin Songblade?",a="Dorin Songblade é um ferreiro anão que reside em Vila Plácida. Ele estivera forjando equipamentos como um presente surpresa para o irmão antes de saber da trágica morte nos sítios de escavação.",al={"quem é dorin songblade","dorin em vila plácida","papel de dorin songblade"}},{q="Quem é o anão morto encontrado na escavação?",a="O anão morto descoberto nos sítios de escavação era irmão de Dorin Songblade. Ele havia passado recentemente por Vila Plácida reunindo suprimentos para sua expedição antes de encontrar seu fim em campo.",al={"quem morreu no pântano","escavação com anão morto","de quem é o corpo na escavação"}},{q="Onde Dorin Songblade pode ser encontrado?",a="Dorin Songblade pode ser encontrado em Vila Plácida, o principal assentamento em Montanhas Cristarrubra, onde ele trabalha em seu ofício na forja.",al={"onde fica dorin songblade","localização de dorin songblade"}},{q="O que Dorin estava forjando para seu irmão?",a="Dorin estava ocupado forjando equipamentos destinados como um presente surpresa para seu irmão. Lamentavelmente, o trabalho não ficou pronto antes de seu irmão partir em sua expedição, deixando Dorin devastado com equipamentos que ele não suporta guardar nem vender.",al={"o que dorin estava forjando","presente surpresa de dorin"}},{q="Por que Dorin doa os itens que criou?",a="Tomado pela tristeza e pelo pesar por não ter acompanhado o irmão, Dorin não tem desejo algum de reforjar ou vender as armas nas quais trabalhou arduamente. Ele abre mão das obras finalizadas em sinal de gratidão ao viajante que lhe trouxe notícias de seu parente.",al={"por que dorin deu os equipamentos","por que dorin dá equipamentos a você"}}},fp="17,175,18.158.0,17.401.1,26.175.0,23.161.0,48.153.0,35.114.0,39.182.0,46.176.0"}
P.entries["quest:95798"] = {n="The Web of Magic",s="Uma pessoa amiga pede que você leve o I'lalai Fetish para Abra Cadabra, em Dalaran. Ela se interessa por magia dos trolls e quer examiná-lo.",h="Uma pessoa amiga pede que você leve o I'lalai Fetish para Abra Cadabra, em Dalaran.",kw={"abra cadabra","magias conflitantes","dalaran","i'lalai fetish","kirin tor","historiador dibbs","magia dos trolls"},sec={{t="Um fetiche para Abra",b="O I'lalai Fetish é destinado a Abra Cadabra, em Dalaran, onde ela poderá examiná-lo. Pedem que você o leve até lá, embora o Kirin Tor possa ser criterioso com quem visita sua cidade."},{t="Descobertas de Abra",b="Abra Cadabra encontra várias magias diferentes agindo sobre o fetiche, algumas em conflito. Ela alerta que ele pode ser perigoso em mãos descuidadas e diz que enviará suas descobertas ao Historiador Dibbs."}},faq={{q="Quem é Abra Cadabra?",a="Abra Cadabra é amiga da pessoa que pede que você leve o I'lalai Fetish até ela. Ela se interessa pelas práticas e pela magia dos trolls.",al={"quem é abra","abra cadabra","abra"}},{q="O que é o I'lalai Fetish?",a="O I'lalai Fetish é um objeto que Abra Cadabra examina por conter magias diferentes e conflitantes.",al={"o que é o fetiche","coisa de i'lalai","fetiche"}},{q="Por que Abra quer examiná-lo?",a="Abra se interessa especialmente pelas práticas e pela magia dos trolls, e o fetiche é uma descoberta que ela pode examinar.",al={"por que abra quer","interesse de abra","magia dos trolls"}},{q="Para onde o fetiche deve ser levado?",a="Pedem que você leve o I'lalai Fetish para Abra Cadabra, em Dalaran.",al={"onde levar o fetiche","entrega em dalaran","local de abra"}},{q="Por que pode ser difícil entrar em Dalaran?",a="O Kirin Tor pode ser criterioso com quem permite entrar em Dalaran, e talvez você precise conquistar sua confiança.",al={"entrar em dalaran","entrada do kirin tor","acesso a dalaran"}}},fp="16,131,17.184.0,15.204.1,20.132.0,27.95.0,33.108.0,33.69.0,38.110.0"}
P.entries["quest:95799"] = {n="Findings for the Explorer's League",s="Historiador Dibbs pede que você leve as traduções das tabuletas de I'lalai a Historiador Karnik, em Altaforja. Karnik vê a descoberta como motivo para enviar uma equipe até a cidade perdida.",h="Historiador Dibbs pede que você leve as traduções das tabuletas de I'lalai a Historiador Karnik, em Altaforja.",kw={"explorer's league","descobertas para a explorer's league","historiador karnik","i'lalai","altaforja","historiador dibbs","tabuletas","traduções","trolls"},sec={{t="Uma carta para Altaforja",b="O Historiador Karnik é colega do Historiador Dibbs na Liga dos Exploradores, em Altaforja. Dibbs fez uma descoberta que considera importante para a história e pede que você leve a Karnik sua carta e uma cópia de suas traduções das tábuas I'lalai."},{t="A resposta de Karnik",b="Karnik recebe com satisfação as traduções de Dibbs e diz que reunirá uma equipe para procurar a cidade perdida de I'lalai. Seus próprios estudos tratam de outros assuntos, mas ele respeita o interesse de Dibbs pelos trolls."}},faq={{q="Quem está me pedindo para levar a carta?",a="Historiador Dibbs pede que você leve a carta dele e uma cópia de suas traduções das tabuletas de I'lalai a Historiador Karnik, em Altaforja.",al={"quem me deu isso","carta de dibbs","quem é historiador dibbs"}},{q="Quem é Historiador Karnik?",a="Historiador Karnik é o colega da Explorer's League em Altaforja que recebe a carta e as traduções de Historiador Dibbs.",al={"quem é karnik","karnik altaforja","aquele historiador"}},{q="O que são as I'lalai Translations?",a="São as traduções de Historiador Dibbs de tabuletas ligadas a I'lalai.",al={"traduções de ilalai","traduções das tabuletas","tabuletas de dibbs"}},{q="Por que Dibbs quer que eu leve a carta?",a="Dibbs diz que a descoberta tem grande importância histórica e quer que seu colega em Altaforja seja informado sem demora.",al={"por que entregar a carta","por que altaforja","o que dibbs precisa"}}},fp="34,175,21.244.0,17.183.1,37.124.0,24.120.0,34.72.0,42.114.0"}
P.entries["quest:95803"] = {n="A Token of Good Faith",s="Danitha pede que você leve a cabeça de Rudolph Gelhardt a Sylvana Correventos, na Cidade Baixa. A entrega deve mostrar aos Renegados que seu povo é dedicado à prosperidade deles.",h="Danitha pede que você leve a cabeça de Rudolph Gelhardt a Sylvana Correventos, na Cidade Baixa.",kw={"a token of good faith","danitha","dama sombria","renegados","luz","rudolph gelhardt","sylvana correventos","cidade baixa"},sec={{t="Uma demonstração de lealdade",b="Danitha diz que Sylvanas desconfia do seu povo e o menospreza abertamente. Pedem que você leve a cabeça de Rudolph Gelhardt como prova de que vocês cuidam dos seus e apoiam os Renegados."},{t="A resposta da Dama Sombria",b="Sylvanas duvida que a ordem de Danitha consiga impedir que mais integrantes voltem a Luz contra o próprio povo. Ela avisa que talvez não tolere mais a ordem se ela deixar de servir aos interesses dos Renegados e diz que eles serão vigiados."}},faq={{q="Quem me pede para levar a cabeça de Rudolph Gelhardt a Sylvanas?",a="Danitha pede que você entregue a cabeça de Rudolph Gelhardt a Sylvana Correventos, na Cidade Baixa.",al={"quem me enviou a sylvanas","entrega da cabeça por danitha","cabeça para a dama sombria"}},{q="Por que Danitha quer que eu leve a cabeça a Sylvanas?",a="Danitha quer que a entrega mostre a Sylvanas que seu povo cuida dos seus e é dedicado à prosperidade dos Renegados.",al={"por que levar a cabeça de rudolph","para que serve esta entrega","provar lealdade"}},{q="Por que Sylvanas desconfia do povo de Danitha?",a="Danitha diz que Sylvanas desconfia muito do seu povo e quase o menospreza abertamente.",al={"por que sylvanas desconfia de nós","desconfiança da dama sombria","por que ela nos menospreza"}},{q="Onde levo a cabeça de Rudolph Gelhardt?",a="Pedem que você leve a cabeça de Rudolph Gelhardt a Sylvana Correventos, na Cidade Baixa.",al={"onde fica sylvanas","local da entrega da cabeça","levar para a cidade baixa"}}},fp="21,186,17.189.0,24.238.1,59.92.0,55.135.0,46.86.0,42.89.0"}
P.entries["quest:95805"] = {n="Grace of An'she and Mu'sha",s="Grace of An'she and Mu'sha é uma peregrinação sagrada dos Tauren realizada na Chapada Nuvem Vermelha para honrar o sol e a lua como os olhos celestiais da Earthmother. Ao carregar um incenso frágil e fumegante até um santuário elevado nas colinas do sudeste, os viajantes demonstram respeito às luzes celestes que trazem calor, vida e direção às planícies.",h="Grace of An'she and Mu'sha é uma peregrinação sagrada dos Tauren realizada na Chapada Nuvem Vermelha para...",kw={"an'she","earthmother","lua","mu'sha","mulgore","chapada nuvem vermelha","santuário","incenso fumegante","sol","tauren"},ang={["class:Druid"]="Os druidas Tauren olham para a dança eterna do sol e da lua como a personificação primordial do equilíbrio, orientando sua compreensão dos ritmos cósmicos da natureza.",["class:Shaman"]="Embora os Xamãs falem diretamente com os espíritos mundanos da terra, do fogo, da água e do ar, eles prestam igual homenagem aos gêmeos celestiais cuja luz sustenta toda a energia viva.",["faction:Horde"]="Os ritos sagrados realizados na chapada mostram a cultura profunda e reverente à natureza que os nômades Tauren trazem aos seus aliados dentro da Horda.",["race:Tauren"]="A reverência por An'she e Mu'sha está no cerne da identidade espiritual dos Tauren, lembrando aos jovens bravos que a vida exige honrar as luzes celestiais gêmeas tão fielmente quanto a própria Earthmother."},sec={{t="Os Olhos da Earthmother",b="No mito Tauren, o sol e a lua são conhecidos como An'she e Mu'sha, reverenciados como os olhos gêmeos da Earthmother. Enquanto os espíritos elementais habitam diretamente as pedras, os ventos e as águas de Azeroth, esses gêmeos celestiais vigiam o mundo das alturas celestes. Sua jornada constante pelo céu marca o ritmo eterno do dia e da noite, concedendo calor, orientação e esperança a todas as criaturas vivas. Honrar os gêmeos é um dever espiritual essencial, ensinando que o equilíbrio exige reverência não apenas pela terra sob os pés, mas também pela luz que brilha do céu."},{t="Uma Oferenda nas Alturas",b="Para honrar os gêmeos celestiais, um peregrino deve carregar incenso fumegante pelas colinas do sudeste que dominam a chapada, situado logo ao sul dos espinhosos campos dos quilboar. A jornada é um exercício de atenção e velocidade: as brasas perfumadas precisam ser entregues antes de se consumirem em cinzas frias, e os viajantes devem cuidar para mantê-las longe da água ao longo da trilha. Ao alcançar o santuário elevado, o peregrino lança as brasas no Sacred Fire, permitindo que a fumaça aromática leve seu respeito para o céu em direção ao sol e à lua."}},faq={{q="Quem são An'she e Mu'sha?",a="An'she e Mu'sha são o sol e a lua na mitologia Tauren, reverenciados como os olhos gêmeos da Earthmother. Ao contrário dos espíritos da terra, do ar, do fogo e da água, eles não habitam diretamente o solo de Azeroth. Em vez disso, iluminam o mundo a partir do firmamento superior, com An'she oferecendo calor e vida, enquanto Mu'sha proporciona guia noturno e consolo.",al={"quem são an'she e mu'sha","história de an'she e mu'sha","deuses tauren do sol e da lua"}},{q="Por que os Tauren fazem oferendas ao sol e à lua?",a="A filosofia Tauren ensina que o equilíbrio é essencial para toda a existência. Enquanto os espíritos terrenos governam a paisagem imediata, a luz de An'she e Mu'sha dá energia vital, visão e esperança a todas as criaturas vivas. Oferecer incenso fumegante em lugares altos é um ato de respeito recíproco, reconhecendo que a vida mortal não pode prosperar sem a contínua benevolência de ambos os corpos celestes.",al={"por que reverenciar o sol e a lua","culto celestial tauren","por que honrar an'she e mu'sha"}},{q="Onde fica o santuário de An'she e Mu'sha?",a="O santuário de An'she e Mu'sha fica situado nas colinas altas ao sudeste da chapada. Ele tem vista para as amplas planícies abaixo e fica logo ao sul dos territórios espinhosos dos quilboar. Sua grande elevação oferece uma visão limpa e desobstruída do céu aberto, tornando-o um local ideal para erguer fumaça em direção aos céus.",al={"onde fica o santuário de an'she","localização do santuário em mulgore","como encontrar o santuário do incenso"}},{q="Qual é o significado do incenso fumegante?",a="O incenso fumegante atua como um condutor físico de prece e respeito. Enquanto suas brasas perfumadas queimam, a fumaça que sobe carrega a devoção do viajante diretamente para o céu em direção ao sol e à lua. Lançar as brasas no fogo do santuário conclui o ritual, recompensando o peregrino com uma sensação tranquila de plenitude espiritual.",al={"o que o incenso faz","significado da oferenda de incenso","por que queimar incenso fumegante"}},{q="Por que o incenso deve ser entregue rapidamente e mantido seco?",a="O ritual exige vigilância, velocidade e cuidado do peregrino. O incenso ainda deve estar fumegante ao ser lançado no Sacred Fire no santuário, o que significa que a jornada precisa ser concluída antes que as brasas se apaguem e virem cinzas frias. Além disso, a imersão na água extinguirá as brasas imediatamente, estragando a oferenda antes que ela consiga alcançar as alturas.",al={"por que o incenso tem tempo limite","não molhe","incenso queimando até o fim"}},{q="Os quilboar ameaçam a peregrinação até o santuário?",a="Tribos quilboar ocupam covis espinhosos fortemente defendidos nas colinas logo ao norte da localização do santuário. Embora o próprio santuário repouse em um mirante tranquilo ao sul de suas terras, os viajantes precisam tomar cuidado para não tropeçar nos espinheiros dos quilboar, pois ataques hostis poderiam facilmente atrasar ou interromper a delicada jornada.",al={"quilboar perto do santuário","os quilboar são uma ameaça aos peregrinos","quilboar ao sul da chapada"}},{q="Como Mu'sha se compara à visão que outras culturas têm da lua?",a="O mito Tauren reconhece a lua como Mu'sha, o amoroso olho esquerdo da Earthmother que contempla a vida mortal. Outras raças em Azeroth, mais notavelmente os elfos da noite, reverenciam a mesma lua branca e luminosa como a deusa Elune, mas a tradição Tauren a vê como inextricavelmente ligada ao seu irmão gêmeo solar, An'she.",al={"mu'sha é elune","lua dos tauren versus elune","mu'sha e os elfos da noite"}}},fp="26,245,27.439.0,26.365.0,26.278.0,53.262.0,49.238.0,51.250.0,55.237.0,54.242.0,61.217.0"}
P.entries["quest:95809"] = {n="Heartwoven",s="Heartwoven é uma missão da Aliança no Pantanal centrada em uma mensagem simples de sobrevivência e afeto. Após liberar uma rota de fuga para um coletor ilhado nos pântanos, aventureiros levam um coração de junco trançado à mão de volta para Caitlin Grassman no Porto de Menethil.",h="Heartwoven é uma missão da Aliança no Pantanal centrada em uma mensagem simples de sobrevivência e afeto.",kw={"caitlin grassman","grassman","heartwoven","porto de menethil","coração de junco","juncos","pantanal"},ang={["faction:Alliance"]="O Porto de Menethil serve como um porto crucial da Aliança no Pantanal, onde cidadãos comuns dependem de viajantes para manter seguras as perigosas rotas do pântano.",["profession:Cooking"]="Ao receber o coração de junco e saber que seu parceiro sobreviveu, Caitlin imediatamente começa a preparar uma refeição quente e farta para recebê-lo em casa."},sec={{t="Um Sinal dos Pântanos",b="Nos pântanos traiçoeiros do Pantanal, a vida e o trabalho trazem perigo constante. Ardin Grassman, que saiu para ver as ervas estranhas nos sítios de escavação, viu-se ilhado em meio aos perigos do pântano até que um viajante que passava liberou um caminho pela natureza selvagem. Exausto, mas determinado, ele faz uma pausa para recuperar o fôlego e proteger sua colheita antes de voltar para a segurança do porto."},{t="Símbolos de Menethil",b="Antes de fazer a caminhada para casa, o coletor pega juncos do pântano de sua mochila e os trança em um coração tecido. Ele confia essa lembrança ao aventureiro para levar adiante até Caitlin Grassman no Porto de Menethil. No movimentado assentamento costeiro, Caitlin espera com profunda preocupação, apertando o coração de junco tecido contra o peito em alívio ao saber que ele sobreviveu e logo retornará para uma refeição quente."}},faq={{q="O que é a missão Heartwoven?",a="Heartwoven é uma missão da Aliança ambientada no Pantanal. Um aventureiro ajuda Ardin Grassman, ilhado nos sítios de escavação nos pântanos, que cria um símbolo trançado de juncos como uma mensagem de sobrevivência e amor para entregar a Caitlin Grassman no Porto de Menethil.",al={"missão heartwoven","o que é heartwoven","pantanal heartwoven"}},{q="Quem é Caitlin Grassman?",a="Caitlin Grassman é uma moradora da Aliança que espera ansiosamente no Porto de Menethil. Ela teme pela vida de seu marido, Ardin, que foi aos sítios de escavação em meio aos perigos do Pantanal, e fica profundamente aliviada quando você lhe traz notícias de sua sobrevivência.",al={"quem é caitlin grassman","caitlin porto de menethil","caitlin grassman"}},{q="O que é o coração tecido de juncos?",a="O coração tecido de juncos é uma lembrança artesanal feita pelo coletor ilhado a partir dos juncos do pântano em sua mochila. Ele o trança rapidamente para servir como prova e garantia de que está vivo e retornando para casa em breve.",al={"o que é o coração de junco","coração tecido de juncos","coração trançado de junco"}},{q="Onde você entrega Heartwoven?",a="A missão termina com Caitlin Grassman, que está esperando na cidade portuária da Aliança de Porto de Menethil, na costa oeste do Pantanal.",al={"onde entregar heartwoven","local de entrega de heartwoven","onde está caitlin grassman"}},{q="Quem dá a você a missão Heartwoven?",a="A missão é oferecida por Ardin Grassman, marido de Caitlin, que sobreviveu ao perigo nos sítios de escavação no Pantanal. Depois que um aventureiro abre um caminho seguro para ele, ele descansa, recolhe seus cestos e envia o aventureiro à frente com um símbolo feito à mão para Caitlin.",al={"quem dá heartwoven","quem faz o coração","o sobrevivente heartwoven"}},{q="O que aconteceu com o coletor ilhado?",a="Ardin foi aos sítios de escavação para ver ervas altas e estranhas e ficou encurralado quando a vida selvagem agitada, principalmente aranhas, dominou a equipe de escavação. Graças a um aventureiro que abriu um caminho através das ameaças ao redor, ele sobreviveu e conseguiu recolher seus cestos com segurança e retornar ao Porto de Menethil.",al={"o que aconteceu com o coletor","ele está vivo","sobrevivente heartwoven"}}},fp="10,154,25.296.0,18.318.0,29.211.0,24.201.0,29.156.0,32.125.0,35.182.0,39.273.0"}
P.entries["quest:95810"] = {n="Lost Relic Carry",s="Lost Relic Carry envolve recuperar um fragmento fraturado de um antigo autômato mecânico de rocha e entregá-lo a Prospector Whelgar, no Pantanal. O material composto desconhecido da relíquia sugere a engenharia sofisticada dos Titãs, despertando grande reverência entre os pesquisadores anões.",h="Lost Relic Carry envolve recuperar um fragmento fraturado de um antigo autômato mecânico de rocha e...",kw={"autômato","sítio de escavação","explorers league","lost relic carry","prospector whelgar","mecânico de pedra","relíquia titânica","pantanal"},ang={["profession:Engineering"]="O material composto e o design intrincado do autômato mecânico de rocha sugerem princípios mecânicos avançados, muito além da engenharia mortal convencional.",["race:Dwarf"]="Exploradores anões da Explorers' League são obcecados em desenterrar relíquias antigas de seus criadores, tornando este fragmento de autômato um achado valioso para a herança dos anões."},sec={{t="Um Fragmento de Ofício Ancestral",b="Nas profundezas de terras ancestrais, aventureiros podem descobrir um componente fraturado de um autômato mecânico de pedra. Longe de ser mero entulho, seu material composto incomum revela a habilidade de um mecanismo avançado e antigo ligado aos Titãs."},{t="Entrega na Escavação",b="O Prospector Whelgar, situado no sítio de escavação do Pantanal, estuda vestígios da antiguidade. Levar a relíquia para fora do perigo e entregá-la a ele fornece valiosas evidências físicas para os estudiosos anões que investigam sua herança ancestral."}},faq={{q="O que é a Relíquia Titânica?",a="A relíquia é um pedaço fraturado de um antigo autômato mecânico de pedra. Em vez de detritos comuns de pedra, consiste em um material composto desconhecido que claramente funcionava como parte de um dispositivo mecânico intrincado.",al={"o que é a relíquia","o que é o item","peça de mecânico de pedra"}},{q="Quem é o Prospector Whelgar?",a="O Prospector Whelgar é um pesquisador anão que supervisiona o sítio de escavação no Pantanal. Ele estuda vestígios terranos antigos e relíquias descobertas em sítios de escavação por toda a região.",al={"quem é whelgar","lore de whelgar","líder da escavação"}},{q="Onde a relíquia precisa ser entregue?",a="A relíquia é levada ao Prospector Whelgar em seu sítio de escavação localizado no Pantanal, onde escavadores anões investigam ruínas antigas.",al={"onde entrego","onde fica a entrega","localização de whelgar"}},{q="O que criou o autômato mecânico de pedra?",a="O fragmento do autômato é identificado como uma relíquia titânica. Na tradição anã, construtos mecânicos antigos e autômatos de pedra estão ligados aos enigmáticos Titãs, que moldaram o mundo.",al={"quem criou o mecânico de pedra","origens do autômato","conexão com os titãs"}},{q="Por que o Prospector Whelgar trata a relíquia com reverência?",a="Aventurar-se nas profundezas onde esses autômatos residem é extremamente perigoso. Whelgar observa que sobreviver à incursão e retornar com uma peça dessas intacta impõe verdadeiro respeito.",al={"por que whelgar está impressionado","incursão perigosa"}},{q="O que há de incomum no material do autômato?",a="O material é um composto único, com uma textura desconhecida e diferente de pedra típica ou metal forjado, demonstrando o ofício sofisticado e misterioso dos antigos construtos dos Titãs.",al={"qual é o material","composto estranho"}}},fp="16,141,27.158.0,26.198.0,24.140.0,26.167.0,42.130.0,37.159.0,59.164.0,47.153.0"}
P.entries["quest:95882"] = {n="WANTED: Scoutmaster Vargas",s="Neza Bloodsnout quer que Scoutmaster Vargas seja detido, pois seu reconhecimento prejudicou a Horda. Ela exige o olho dele como prova de que se foi.",h="Neza Bloodsnout quer que Scoutmaster Vargas seja detido, pois seu reconhecimento prejudicou a Horda.",kw={"batedor da aliança","neza bloodsnout","sendas do rio","rog'mar","grupo de reconhecimento","scoutmaster vargas","olho do batedor-chefe"},ang={["faction:Horde"]="Como membro da Horda, você ajuda Neza a eliminar Scoutmaster Vargas, um batedor da Aliança cuja vigilância prejudicou os movimentos da Horda."},sec={{t="A caçada de Neza",b="Neza Bloodsnout já tomou um dos olhos de Scoutmaster Vargas, mas o humano escapou. O reconhecimento dele dificulta que a Horda acompanhe os movimentos da Aliança. Agora, Neza pede que você traga o outro olho de Vargas como prova de que o batedor-chefe não existe mais."},{t="O relatório",b="Neza fica sabendo que Vargas está morto e diz que as Sendas do Rio estão mais seguras para a Horda. Ela lamenta que, apesar de tudo que viu, ele não tenha vivido cego."}},faq={{q="Quem é Scoutmaster Vargas?",a="Scoutmaster Vargas é um humano que lidera um grupo de reconhecimento da Aliança em uma pequena ilha a nordeste de Rog'mar.",al={"vargas","quem é vargas"}},{q="Por que Neza quer Vargas morto?",a="O reconhecimento de Vargas dificultou que a Horda acompanhasse os movimentos inimigos, e Neza diz que ele sabe que ela está caçando-o.",al={"por que matar vargas","neza e vargas"}},{q="Onde Vargas foi visto?",a="Um grupo de reconhecimento da Aliança liderado por Vargas foi visto em uma pequena ilha a nordeste de Rog'mar.",al={"ilha de vargas","onde está o batedor-chefe"}},{q="O que Neza me pede para trazer?",a="Neza pede que você traga o outro olho de Scoutmaster Vargas como prova de que ele se foi.",al={"olho de vargas","qual é a prova"}},{q="Quem é Neza Bloodsnout?",a="Neza Bloodsnout está em Rog'mar e quer provas de que Scoutmaster Vargas não existe mais.",al={"neza","quem quer vargas"}},{q="O que Neza diz depois que Vargas morre?",a="Neza aceita que Vargas está morto e diz que as Sendas do Rio estão mais seguras para a Horda.",al={"desfecho de vargas","o que acontece depois"}}},fp="26,137,14.255.0,10.142.1,26.104.0,31.119.0,22.89.0,36.83.0,23.81.0,37.82.0"}
P.entries["quest:95883"] = {n="The Tortured Soul",s="Alma Torturada é uma missão centrada em um altar ritualístico montado às pressas em Cilada de Beren, na Floresta de Pinhaprata. Para dar continuidade aos ritos sombrios prescritos por uma nota abandonada, aventureiros precisam recuperar uma alma imersa em sofrimento nos penhascos perigosos das proximidades.",h="Alma Torturada é uma missão centrada em um altar ritualístico montado às pressas em Cilada de Beren, na...",kw={"cilada de beren","energia vil","oferenda de sangue","the offering stone","ritual","floresta de pinhaprata","a alma torturada"},ang={["class:Priest"]="O ritual depende de energia vil arrancada de espíritos em sofrimento, colocando-se em nítida oposição aos princípios restauradores da Holy Light.",["class:Warlock"]="Canalizar almas atormentadas e realizar ritos sombrios em antigas pedras de oferendas refletem a natureza sombria e manipuladora da magia demoníaca e da Shadow Magic.",["race:Undead"]="A Floresta de Pinhaprata é território dos Renegados, onde resquícios de magia sombria e sofrimento persistente ameaçam constantemente as fronteiras de Lordaeron."},sec={{t="Um Rito Apressado",b="Em Cilada de Beren, na Floresta de Pinhaprata, há um altar com os restos de um ritual sombrio montado às pressas. Um bilhete rabiscado deixado em meio à desordem indica que a maioria dos ingredientes já foi reunida, restando apenas uma oferenda de sangue e uma Alma Torturada para concluir o trabalho."},{t="Energias Vis Libertadas",b="Os habitantes que vivem nos penhascos da Cilada de Beren suportam uma agonia severa, tornando-se alvos ideais para a colheita da essência torturada exigida pelo rito. Apresentar a alma colhida à sinistra The Offering Stone atrai uma onda de energia mágica vil, avançando o ritual em direção à sua conclusão."}},faq={{q="O que é The Tortured Soul?",a="Alma Torturada é uma missão ambientada em Cilada de Beren, na Floresta de Pinhaprata. Ela envolve investigar um ritual sombrio inacabado em uma pedra de oferendas e procurar nas proximidades a alma de uma criatura atormentada para completar os componentes do rito.",al={"o que é a missão a alma torturada","alma torturada floresta de pinhaprata","missão cilada de beren"}},{q="Onde ocorre este ritual?",a="O altar do ritual e sua sinistra The Offering Stone estão localizados na Cilada de Beren, um enclave montanhoso e perigoso situado na Floresta de Pinhaprata.",al={"onde fica o ritual","onde fica a cilada de beren","localização de the offering stone"}},{q="Quais componentes são necessários para o ritual?",a="De acordo com um pedaço de bilhete deixado no altar, quase todos os materiais foram reunidos às pressas, exceto por dois componentes vitais: uma oferenda de sangue e uma Alma Torturada.",al={"o que é necessário para o ritual","componentes do ritual cilada de beren"}},{q="Onde você encontra a Alma Torturada?",a="O texto da missão observa que as criaturas próximas que habitam a Cilada de Beren parecem torturadas o suficiente para fornecer a essência necessária para energizar a The Offering Stone.",al={"onde conseguir alma torturada","quem tem a alma"}},{q="O que acontece quando a Alma Torturada é levada ao altar?",a="Levar a alma atormentada até a pedra de oferendas faz com que ela emita uma energia repulsiva, aproximando a cerimônia sombria de sua conclusão.",al={"o que acontece ao trazer a alma","entregar alma torturada"}},{q="Quem criou o ritual na Cilada de Beren?",a="O criador exato do ritual não é mencionado, mas bilhetes e materiais reunidos às pressas indicam que alguém fugiu ou montou o altar com extrema pressa entre os habitantes hostis da Cilada de Beren.",al={"quem criou o ritual","quem escreveu o bilhete"}}},fp="17,163,12.253.0,23.250.1,26.158.0,34.114.0,44.129.0,36.120.0,60.116.0,40.147.0"}
P.entries["quest:95884"] = {n="The Offering Stone",s="The Offering Stone é um altar ritualístico escondido na Cilada de Beren, na Floresta de Pinhaprata. Descoberta por meio de fragmentos de um bilhete desgastado pelo tempo, a pedra está repleta de instrumentos bizarros e itens destinados a uma oferenda desconhecida. Investigar o local revela preparativos rituais ativos acontecendo na vastidão sombria.",h="The Offering Stone é um altar ritualístico escondido na Cilada de Beren, na Floresta de Pinhaprata.",kw={"cilada de beren","instrumentos","the offering stone","ritual","pedaco de bilhete","floresta de pinhaprata"},ang={["class:Warlock"]="A visão de uma pedra de oferendas repleta de instrumentos sombrios aponta para práticas ritualísticas, justificando um estudo atento por parte de praticantes das artes das trevas.",["faction:Horde"]="Aventureiros dos Renegados e da Horda protegendo a Floresta de Pinhaprata devem manter uma vigilância constante diante de rituais suspeitos e atividades de cultistas que persistem nos penhascos sombrios da Cilada de Beren."},sec={{t="Um Bilhete Desgastado",b="Um pedaço de papel desgastado pelo tempo encontrado na Floresta de Pinhaprata fala de estranhos preparativos rituais. Embora o tempo e a umidade tenham tornado a maior parte da escrita ilegível, restam fragmentos suficientes para revelar menções a um ritual e a uma pedra de oferendas situada em algum lugar próximo. Viajantes que seguem essas pistas pelos penhascos da Cilada de Beren podem localizar o altar rústico escondido na vastidão."},{t="O Local do Ritual",b="Ao localizar The Offering Stone na Cilada de Beren, sua superfície áspera revela evidências de atividade recente e perturbadora. Instrumentos estranhos e itens bizarros jazem espalhados pela rocha, confirmando que alguém tem usado ativamente o local para preparar uma oferenda ou rito sombrio longe de olhos curiosos."}},faq={{q="O que é The Offering Stone?",a="The Offering Stone é um altar de pedra desgastado pelo tempo localizado na Cilada de Beren, na Floresta de Pinhaprata. Parece servir como ponto focal para preparativos misteriosos e rituais sombrios, repleto de instrumentos bizarros e itens rituais.",al={"o que e the offering stone","the offering stone floresta de pinhaprata","o que e esta pedra"}},{q="Onde The Offering Stone pode ser encontrada?",a="The Offering Stone está situada na Cilada de Beren, uma área montanhosa e perigosa localizada no sul da Floresta de Pinhaprata.",al={"onde fica the offering stone","localizacao de the offering stone","encontrar the offering stone"}},{q="Quem criou ou usa The Offering Stone?",a="O bilhete danificado recuperado nas proximidades deixa a identidade dos ritualistas incerta, mas as ferramentas e itens deixados na pedra indicam que alguém estava preparando ativamente uma oferenda ou rito sombrio na área.",al={"quem fez the offering stone","quem usa the offering stone","quem esta realizando o ritual"}},{q="O que diz o bilhete misterioso?",a="O pedaço de bilhete está em grande parte desgastado e ilegível, mas fragmentos legíveis detalham claramente preparativos para um próximo ritual e apontam para a presença de uma pedra de oferendas por perto.",al={"qual bilhete","pedaco de bilhete floresta de pinhaprata","o que diz o bilhete"}},{q="O que é encontrado sobre The Offering Stone?",a="A superfície áspera da pedra está repleta de ferramentas estranhas, instrumentos rituais e itens diversos organizados para uma oferenda.",al={"quais itens estao sobre a pedra","quais instrumentos sobre a pedra","itens de the offering stone"}},{q="Que tipo de ritual está sendo realizado aqui?",a="Embora a natureza exata do rito não esteja totalmente detalhada nos fragmentos sobreviventes do bilhete, a pedra está preparada especificamente como um altar onde itens ou sacrifícios são dispostos para um ritual.",al={"qual ritual the offering stone","por que uma the offering stone","qual oferenda floresta de pinhaprata"}}},fp="18,157,15.246.0,15.183.0,27.173.0,38.80.0,39.145.0,34.141.0,36.110.0,44.129.0"}
P.entries["quest:95885"] = {n="The Offering of Blood",s="The Offering of Blood é um ritual misterioso realizado na The Offering Stone em Cilada de Beren. Usando uma Alma Torturada, aventureiros fazem uma oferenda de sangue na pedra, como pedia o pedaço de bilhete.",h="The Offering of Blood é um ritual misterioso realizado na The Offering Stone em Cilada de Beren.",kw={"cilada de beren","ritual de sangue","the offering of blood","the offering stone","sacrifício","floresta de pinhaprata","alma torturada"},ang={["class:Priest"]="Sacerdotes preocupados com o destino dos espíritos que partiram acharão o uso de uma alma torturada em um ritual de sangue sinistro moralmente perturbador, independentemente de isso colocar a entidade em descanso.",["class:Warlock"]="Bruxos estão bem acostumados a ritos sombrios e barganhas com almas, embora até mesmo praticantes experientes do vil possam sentir um calafrio ao realizar um sacrifício de sangue em uma pedra antiga e desconhecida."},sec={{t="O Rito Final",b="Nas profundezas dos penhascos de Cilada de Beren repousa a The Offering Stone, uma relíquia sinistra à espera de uma transação sombria final. Seguindo pistas de pedaços de bilhetes descartados que pedem um sacrifício voluntário, os aventureiros são levados a trazer a oferenda de sangue necessária para satisfazer a magia remanescente do altar. Aproximar-se da pedra com a essência inquieta traz uma sensação avassaladora de pavor."},{t="Rachando a Pedra",b="Oferecer a Alma Torturada à pedra inicia uma reação profunda, drenando o poder remanescente do antigo monumento. Em vez de despertar um terror maior, o ritual de sangue esgota a relíquia por completo. Desprovida de seu propósito arcano, a pedra bruta fratura e desmorona em escombros, revelando uma recompensa cintilante enterrada no interior dos fragmentos despedaçados."}},faq={{q="Onde ocorre este ritual?",a="The Offering of Blood acontece na The Offering Stone localizada em Cilada de Beren, na Floresta de Pinhaprata. A área está repleta de perigos e sombreada por uma magia sombria e persistente.",al={"onde fica esta missão","onde fica the offering of blood","missão em cilada de beren"}},{q="O que é a The Offering Stone?",a="A The Offering Stone é um misterioso monumento antigo situado em Cilada de Beren. Ela exige um ritual sombrio — especificamente uma oferenda de sangue de um sacrifício voluntário — para desbloquear ou drenar o poder que adormece em seu interior.",al={"o que é the offering stone","the offering stone cilada de beren","altar em cilada de beren"}},{q="Para que é usada a Alma Torturada?",a="O ritual exige uma Alma Torturada, atuando como o \"sacrifício voluntário\" mencionado nos pedaços de bilhetes recuperados. A alma é apresentada na The Offering Stone para cumprir a oferenda de sangue exigida pela antiga relíquia.",al={"quem é a alma torturada","o que é alma torturada","qual sacrifício é necessário"}},{q="O que acontece quando a oferenda é concluída?",a="Ao completar o ritual, a energia sombria que anima a The Offering Stone é completamente drenada. Desprovida de propósito, a pedra bruta racha e se desfaz em pedaços, deixando para trás algo cintilante entre seus restos.",al={"o que acontece com a pedra","a pedra quebra","o que acontece após o ritual"}},{q="Quem criou a pedra e por quê?",a="As origens exatas e o propósito final da pedra permanecem um enigma. Embora a conclusão do rito drene com sucesso a energia latente da pedra e a destrua, quem originalmente criou o monumento e para qual grande propósito permanece desconhecido.",al={"quem construiu the offering stone","objetivo de the offering of blood","por que a pedra foi feita"}},{q="O que é Cilada de Beren?",a="Cilada de Beren é um marco rochoso na Floresta de Pinhaprata conhecido por feras selvagens e perigos ocultos. A presença da The Offering Stone revela que ritos sombrios e almas inquietas também deixaram sua marca no local.",al={"o que é cilada de beren","história de cilada de beren","por que se chama cilada de beren"}}},fp="21,114,14.216.0,18.241.1,34.127.0,27.140.0,35.106.0,44.144.0,30.132.0,22.161.0"}
P.entries["quest:959"] = {n="Encrencas nas docas",s="O Operador de Grua Mafuá causou um acidente desastrado com a carga nas docas de Vila Catraca, permitindo que um arruaceiro mesquinho chamado Mad Magglish levasse uma garrafa de safra inestimável. A safra — um Xerez de 99 Anos enviado diretamente do Barão Rezingada para Gasganete — precisa ser recuperada das sombras da Caverna Ululante antes que o mestre das docas demita o operador de grua negligente.",h="O Operador de Grua Mafuá causou um acidente desastrado com a carga nas docas de Vila Catraca, permitindo que...",kw={"mafuá","angra do butim","gasganete","magglish","xerez","vila catraca","rezingada","caverna ululante"},ang={["class:Rogue"]="Caçar Mad Magglish é um exercício de detectar uma ocultação desajeitada, já que o ladrão depende de uma furtividade rudimentar nas frestas das cavernas para escapar da atenção.",["faction:Alliance"]="Embora opere no coração dos Sertões dominados pela Horda, manter-se do lado bom dos operadores portuários de Bondebico garante passagem segura por águas neutras.",["faction:Horde"]="Ajudar os estivadores de Vila Catraca contribui para manter o bom funcionamento do principal porto neutro que liga Kalimdor aos Reinos do Leste."},sec={{t="Um Acidente Desastrado",b="Vila Catraca prospera com o comércio marítimo constante com Angra do Butim através do Grande Oceano, mas sua eficiência gnômica às vezes vacila sob grandes volumes. Quando uma remessa matinal excepcionalmente maciça chegou ao porto, o Operador de Grua Mafuá tentou cortar caminho para acelerar o processo de descarregamento. Ao erguer muito mais peso do que sua grua aguentava, ele derrubou toda a carga pelas docas. No caos resultante, um incômodo local chamado Mad Magglish aproveitou os caixotes espalhados, pegou uma única e valiosa garrafa de bebida alcoólica e fugiu para o interior."},{t="Safra Diplomática",b="A carga roubada era muito mais do que uma ração comum de bebidas do cais. A garrafa era um Xerez de 99 Anos enviado como um presente diplomático pessoal do Barão Rezingada, o notório governante Água Negra de Angra do Butim, para Gasganete, o engenheiro-chefe e supervisor de Vila Catraca. Perder uma oferenda tão suntuosa ameaça humilhar Mafuá e enfurecer ambos os magnatas comerciais. Diante da perda de seu emprego ou pior, Mafuá rastreou o ladrão até a sinistra entrada da Caverna Ululante, embora o medo o tenha impedido de seguir Magglish para dentro."},{t="O Esconderijo na Caverna",b="Em vez de se aventurar pelas profundezas do cenário onírico corrompido da masmorra em si, Mad Magglish preferiu se esconder nos túneis naturais extensos e úmidos do lado de fora do portal interno. Confiando em uma furtividade desajeitada e em recessos escuros, Magglish esgueira-se pelas cavernas subterrâneas na esperança de que os perseguidores desistam. Recuperar o xerez requer expulsar o ladrão dos trechos externos antes que a safra seja desarrolhada ou destruída."}},faq={{q="Por que essa garrafa de xerez é tão importante?",a="O Xerez de 99 Anos não é um grogue comum; trata-se de um presente pessoal extravagante enviado pelo Barão Rezingada de Angra do Butim para Gasganete, o chefe de Vila Catraca. Perdê-lo em um acidente nas docas ameaça irritar profundamente a liderança de Vila Catraca e custar o sustento do Operador de Grua Mafuá.",al={"por que mafuá se importa","o que é o xerez de 99 anos","por que o vinho é importante"}},{q="Quem é Mad Magglish?",a="Mad Magglish é um ladrão oportunista e encrenqueiro que anda por Vila Catraca. Quando Mafuá derrubou uma enorme carga nas docas, Magglish pegou a rara garrafa de xerez e fugiu direto para a Caverna Ululante próxima para se esconder.",al={"quem é magglish","quem roubou o xerez","história de mad magglish"}},{q="Preciso entrar na masmorra da Caverna Ululante para encontrar o ladrão?",a="Não. Mad Magglish se esconde nas passagens sinuosas e públicas das cavernas do lado de fora do portal da masmorra. Ele usa uma furtividade fraca e espreita nos túneis laterais superiores ou perto das câmaras inundadas que levam à entrada principal.",al={"magglish está dentro da masmorra","onde fica mad magglish","encontrar magglish"}},{q="Como ocorreu o derramamento da carga?",a="Uma enorme remessa de carga chegou de Angra do Butim, e o Operador de Grua Mafuá tentou descarregar mais caixotes de uma só vez do que seu equipamento suportava. A grua sobrecarregada deixou a carga cair, espalhando mercadorias valiosas pelas docas de Vila Catraca.",al={"por que os caixotes caíram","o que mafuá fez","acidente da grua em vila catraca"}},{q="Qual é a relação entre Vila Catraca e Angra do Butim?",a="Ambas as cidades portuárias são fortalezas vitais do Cartel Bondebico, unidas pelo comércio e por frotas de corsários. Remessas comerciais regulares e cortesias formais passam entre o Barão Rezingada no sul e Gasganete nos Sertões para manter seu império comercial conjunto.",al={"conexão entre vila catraca e angra do butim","portos de bondebico","rezingada e gasganete"}},{q="Por que Mafuá não recuperou a garrafa ele mesmo?",a="Mafuá perseguiu o ladrão até a entrada da Caverna Ululante, mas a reputação sinistra e os habitantes monstruosos do labirinto subterrâneo aterrorizaram o goblin, fazendo-o parar na entrada.",al={"por que o goblin não pegou","por que mafuá parou de perseguir"}}},fx={b908c2b9={q="Por que o Operador de Grua Mafuá precisa desse vinho de volta?",a="O emprego de Mafuá está na corda bamba. Quando tentou descarregar mais caixotes do que sua grua conseguia aguentar, todo o carregamento da manhã vindo de Angra do Butim desabou. No caos, a premiada garrafa de vinho de noventa e nove anos sumiu, e o mestre do cais não sai de suas costas desde então. Como a safra era um presente pessoal destinado ao engenheiro-chefe de Vila Catraca, Gasganete, falhar em recuperá-la significa que Mafuá enfrenta demissão imediata.",al={"por que mafuá quer o vinho","motivação de mafuá","por que ajudar mafuá"}}},fp="20,185,15.333.0,18.354.0,18.284.0,40.201.0,20.201.0,65.176.0,31.206.0,55.245.0,50.185.0"}
P.entries["quest:95912"] = {n="WANTED: Blademaster Kaijo",s="Ember Bladewhisper procura Blademaster Kaijo em um acampamento de treinamento ao norte do posto avançado da Horda. Seu estandarte deve enfraquecer o moral dos orcs e fortalecer a determinação dos aprendizes de Ember.",h="Ember Bladewhisper procura Blademaster Kaijo em um acampamento de treinamento ao norte do posto avançado da...",kw={"blademaster kaijo","estandarte do mestre das lâminas","ember bladewhisper","bastilha de ermoforte","posto avançado da horda","kaijo","aprendizes orcs","acampamento de treinamento"},sec={{t="Uma luta vacilante",b="Ember Bladewhisper teme que cada orc derrotado seja substituído por um soldado mais capaz. Ela acredita que um mestre das lâminas está treinando esses orcs e diz que Kaijo provavelmente está no acampamento de treinamento ao norte do posto avançado da Horda. Pedem que você leve o estandarte dele à Bastilha de Ermoforte."},{t="O propósito de um estandarte",b="Ember diz que a ameaça dos orcs parece interminável e que a determinação de seus soldados está diminuindo. Ela espera que o estandarte de Kaijo mostre aos aprendizes que a Horda não é motivo para temer."}},faq={{q="Quem é Blademaster Kaijo?",a="Ember Bladewhisper identifica Kaijo como um mestre das lâminas que provavelmente está treinando orcs em um acampamento de treinamento ao norte do posto avançado da Horda.",al={"quem é kaijo","história de kaijo"}},{q="Por que Ember quer encontrar Kaijo?",a="Ember acredita que Kaijo está treinando uma nova geração de soldados orcs capazes e teme que eles recuperem seus números.",al={"por que encontrar kaijo","motivo da recompensa por kaijo"}},{q="Onde Ember acha que Kaijo está?",a="Ember diz que Kaijo provavelmente está no acampamento de treinamento ao norte do posto avançado da Horda.",al={"onde está kaijo","localização de kaijo"}},{q="O que Ember quer que seja levado à Bastilha de Ermoforte?",a="Ember pede que você leve o Estandarte do Mestre das Lâminas até ela, na Bastilha de Ermoforte.",al={"estandarte de kaijo","o que levar à bastilha de ermoforte"}},{q="Por que Ember quer o estandarte?",a="Ember espera que o estandarte enfraqueça o moral dos orcs e tranquilize seus aprendizes, mostrando que a Horda não é motivo para temer.",al={"propósito do estandarte","por que levar o estandarte de kaijo"}},{q="O que preocupa Ember na luta?",a="Ember teme que a ameaça dos orcs não tenha fim e que a determinação de seus soldados esteja vacilando.",al={"ember está preocupada","ameaça dos orcs"}}},fp="25,187,17.254.0,18.164.0,25.126.0,32.111.0,32.74.0,46.75.0,31.106.0,35.84.0"}
P.entries["quest:95913"] = {n="Fit for a Princess",s="Tessa Dawnbright precisa de peles quentes de coiote para o moisés de sua filha Emma, na Bastilha de Ermoforte. Ela espera que uma cama mais macia ajude o bebê a dormir e traga tranquilidade à Bastilha de Ermoforte.",h="Tessa Dawnbright precisa de peles quentes de coiote para o moisés de sua filha Emma, na Bastilha de Ermoforte.",kw={"bebê","moisés","cobertores","peles de coiote","emma","bastilha de ermoforte","tessa dawnbright"},sec={{t="Um pedido de mãe",b="Tessa Dawnbright embala Emma na Bastilha de Ermoforte, na esperança de acalmar a filha que chora. O marido fez um moisés, mas Tessa teme que os cobertores estejam velhos demais. Ela pede que você traga peles de coiote para forrar a cama de Emma, esperando que a roupa de cama mais quente a acalme."},{t="Um retorno bem-vindo",b="Tessa recebe você quando retorna com as peles. Ela as considera quentes e macias e diz que são para Emma. Tessa parece cansada enquanto cuida do bebê."}},faq={{q="Quem é Tessa Dawnbright?",a="Tessa Dawnbright é a mãe de Emma, na Bastilha de Ermoforte.",al={"quem é tessa","tessa dawnbright"}},{q="Quem é Emma?",a="Emma é filha de Tessa Dawnbright.",al={"bebê de tessa","bebê emma"}},{q="Por que Tessa precisa de peles de coiote?",a="Tessa quer forrar o moisés de Emma com peles quentes e macias porque teme que os cobertores estejam velhos demais.",al={"por que peles","peles de coiote para tessa"}},{q="Onde Tessa mora?",a="Tessa está na Bastilha de Ermoforte.",al={"onde está tessa","tessa em farholde"}},{q="O que há de errado com Emma?",a="Emma está chorando, e Tessa tenta ajudá-la a dormir.",al={"por que o bebê está chorando","emma chorando"}}},fp="18,172,18.245.0,16.151.0,24.53.0,12.38.0,33.105.0,22.26.0,24.54.0"}
P.entries["quest:95934"] = {n="Proof of Profit",s="Gelinda Coppergleam encontrou indícios de cubic draconia nas cavernas, mas precisa de um cristal para provar que existe. Ela pede que você traga um para mostrar o valor do mineral aos outros.",h="Gelinda Coppergleam encontrou indícios de cubic draconia nas cavernas, mas precisa de um cristal para provar...",kw={"cavernas","cristal","cubic draconia","dinamite","gelinda coppergleam","mineral","prova do lucro","ferramentas de prospecção"},ang={["profession:Mining"]="Como minerador, você pode levar a Gelinda Coppergleam um cristal de cubic draconia para provar que o mineral existe."},sec={{t="Um Cristal como Prova",b="As ferramentas de prospecção de Gelinda Coppergleam indicam a presença de um novo mineral nas cavernas, que ela chama de cubic draconia. As leituras, por si só, não vão convencer as pessoas, então ela pede que você traga um cristal como prova. Há dragões nas cavernas, e Gelinda diz que talvez haja cristais aparecendo por entre a terra."}},faq={{q="Quem é Gelinda Coppergleam?",a="Gelinda Coppergleam encontrou indícios de cubic draconia nas cavernas usando suas ferramentas de prospecção.",al={"gelinda","quem é gelinda","coppergleam"}},{q="O que é cubic draconia?",a="Cubic draconia é um mineral que Gelinda acredita ter encontrado nas cavernas.",al={"cubic draconia","novo mineral","qual mineral"}},{q="Por que Gelinda quer um cristal?",a="Gelinda quer um cristal para provar que cubic draconia existe, pois as pessoas preferem ver um cristal a examinar as leituras dela.",al={"por que o cristal","prova do lucro","qual é a prova"}},{q="Onde posso encontrar cubic draconia?",a="Gelinda diz que talvez haja cristais aparecendo por entre a terra nas cavernas.",al={"onde está draconia","local do cristal","encontrar cubic draconia"}},{q="Há dragões nas cavernas?",a="Sim. Gelinda avisa que há dragões nas cavernas.",al={"dragões na caverna","perigo na caverna","dragões"}},{q="E se eu não conseguir tirar um cristal?",a="Gelinda se oferece para emprestar dinamite caso você tenha dificuldade para tirar cubic draconia do solo.",al={"não consigo cavar","preciso de dinamite","cristal preso"}}},fp="15,171,19.293.0,27.93.0,23.72.0,32.125.0,32.73.0,31.49.0,34.97.0"}
P.entries["quest:95935"] = {n="Hail the Dragonslayer",s="Cedric Dalton, na Southern Watch, pede que você leve a cabeça de Scaldaron até ele. A ameaça do dragão acabou, e as sentinelas devem saber o que aconteceu.",h="Cedric Dalton, na Southern Watch, pede que você leve a cabeça de Scaldaron até ele.",kw={"cedric dalton","dragão","gnolls","head of scaldaron","scaldaron","sentinelas","southern watch"},sec={{t="Notícias na Watch",b="A cabeça de Scaldaron é um sinal horrendo do perigo que passou. Na Southern Watch, Cedric Dalton fica sabendo o que aconteceu quando você a leva até ele. As sentinelas de lá pensavam que os gnolls nas colinas eram sua única preocupação."}},faq={{q="Quem está pedindo a cabeça de Scaldaron?",a="Cedric Dalton, na Southern Watch, pede que você leve a Head of Scaldaron até ele.",al={"quem quer a cabeça do dragão","pedido de cedric dalton"}},{q="Onde devo levar a Head of Scaldaron?",a="Leve a Head of Scaldaron até Cedric Dalton, na Southern Watch.",al={"onde levar a cabeça","local da cabeça do dragão"}},{q="Quem era Scaldaron?",a="Scaldaron era um dragão cuja ameaça acabou.",al={"dragão scaldaron","o que é scaldaron"}},{q="Por que as sentinelas devem saber o que aconteceu?",a="As sentinelas da Southern Watch devem saber o que aconteceu depois que a ameaça de Scaldaron acabou.",al={"por que contar às sentinelas","notícias da southern watch"}}},fp="21,152,17.226.0,37.80.0,42.66.0,18.48.0,43.87.0"}
P.entries["quest:95951"] = {n="Fetch 'n' Fletch",s="Tan’jani oferece ensinar você a fazer lanças para os caçadores de cabeças da Horda. Você é enviado ao Turner's Logging Camp para buscar madeira e transformá-la em lanças.",h="Tan’jani oferece ensinar você a fazer lanças para os caçadores de cabeças da Horda.",kw={"fetch 'n' fletch","caçadores de cabeças","horda","lanças improvisadas","tan’jani","turner's logging camp","feixes de madeira"},sec={{t="Madeira para lanças",b="Tan’jani, um caçador de cabeças, pede que você reúna madeira no Turner's Logging Camp, o acampamento humano a oeste. Com uma faca, você pode afiar a madeira e transformá-la em lanças para atingir humanos antes que percebam sua aproximação. Tan’jani quer que você leve as lanças de volta."}},faq={{q="Quem é Tan’jani?",a="Tan’jani é um caçador de cabeças que oferece ensinar você a fazer lanças.",al={"quem é tan’jani"}},{q="O que Tan’jani quer que eu busque?",a="Tan’jani pede que você reúna madeira das pilhas dos camponeses no Turner's Logging Camp e a transforme em lanças improvisadas.",al={"qual madeira","buscar lanças"}},{q="Onde está a madeira?",a="A madeira está nas pilhas dos camponeses no Turner's Logging Camp, o acampamento humano a oeste.",al={"local da madeira","onde fica a madeira"}},{q="Por que Tan’jani quer lanças?",a="Tan’jani diz que os caçadores de cabeças usam lanças para atingir humanos antes que percebam sua aproximação.",al={"por que lanças","lanças dos caçadores de cabeças"}}},fp="16,149,15.251.0,18.66.0,36.118.0,18.86.0,32.84.0"}
P.entries["quest:95955"] = {n="Stick 'Em",s="Tan'jani, em Rog'mar, ensina você a arremessar lanças praticando nas Sendas do Rio. Freshwater Crocolisks servem de alvo, e ele espera que a lição faça de você um caçador de cabeças.",h="Tan'jani, em Rog'mar, ensina você a arremessar lanças praticando nas Sendas do Rio.",kw={"freshwater crocolisk","caçador de cabeças","sendas do rio","rog'mar","arremesso de lanças","lanças","acerte eles","tan'jani","tran'jani"},sec={{t="Um alvo Crocolisk",b="Tan'jani, em Rog'mar, tem lanças para você e quer que aprenda a arremessá-las. As Sendas do Rio estão cheias de Freshwater Crocolisks, que ele considera perigosos. Ele os usa como alvos para sua prática."},{t="A promessa de um caçador de cabeças",b="Depois do treino, Tan'jani elogia seu desempenho e diz que você tem potencial para ser um verdadeiro caçador de cabeças. Ele pede que você se lembre dele caso fique famoso."}},faq={{q="Quem é Tan'jani?",a="Tan'jani é quem entrega lanças a você e ensina a arremessá-las em Rog'mar.",al={"tran'jani","quem é tran'jani","troll velho"}},{q="Por que Tan'jani me manda atrás de crocoliscos?",a="Tan'jani usa os Freshwater Crocolisks das Sendas do Rio como alvos para a prática de arremesso de lanças.",al={"por que crocoliscos","treino com crocoliscos","acerte os crocs"}},{q="O que Tan'jani quer que eu faça?",a="Tan'jani quer que você pratique arremessar lanças contra Freshwater Crocolisks nas Sendas do Rio.",al={"o que eu faço","acerte eles","alvos para lanças"}},{q="Onde isso acontece?",a="Tan'jani entrega as lanças a você em Rog'mar e indica as Sendas do Rio para o treino.",al={"onde fica tran'jani","missão das sendas do rio","rog'mar"}},{q="O que Tan'jani diz sobre os crocoliscos?",a="Tan'jani avisa que os Freshwater Crocolisks são perigosos e podem engolir você se não for rápido.",al={"crocs são perigosos","perigo dos crocoliscos","engolir você"}}},fp="9,179,18.199.0,22.153.1,16.82.0,43.98.0,33.91.0,24.92.0,44.101.0"}
P.entries["quest:95961"] = {n="Stepped Out",s="Tessa pede que você encontre Gray no Porto Detonapavio. Ele está fora há mais tempo que o esperado, e ela quer que volte para casa, para ficar com ela e Emma.",h="Tessa pede que você encontre Gray no Porto Detonapavio.",kw={"emma","família","gray dawnbright","marido desaparecido","porto detonapavio","saiu","tessa"},sec={{t="Pedido de Tessa",b="A bebê de Tessa, Emma, está chorando enquanto Tessa pede que você procure Gray. Ele saiu há algum tempo e ainda não voltou. Ela diz que ele costuma ir ao Porto Detonapavio, onde sua aparência brilhante deve torná-lo fácil de reconhecer."}},faq={{q="Quem Tessa está procurando?",a="Tessa pede que você encontre Gray, pai de Emma, no Porto Detonapavio.",al={"quem é gray","encontrar o marido de tessa","onde está gray de tessa"}},{q="Por que Tessa quer Gray em casa?",a="Tessa diz que Emma se ilumina quando vê o pai e que quer saber por que ele ainda não voltou.",al={"por que tessa está preocupada","por que ela precisa de gray","pai de emma"}},{q="Para onde Tessa acha que Gray foi?",a="Tessa diz que Gray parece ir com frequência ao Porto Detonapavio.",al={"localização de gray","onde está gray","porto detonapavio"}},{q="Como posso reconhecer Gray?",a="Tessa diz que Gray brilha tanto quanto o sol.",al={"qual é a aparência de gray","aparência de gray","quem brilha intensamente"}}},fp="11,128,15.214.0,25.63.0,30.99.0,33.53.0,25.46.0"}
P.entries["quest:95981"] = {n="Watching the Roads",s="Watching the Roads é uma missão dos Renegados na Floresta de Pinhaprata sob a liderança do Sacerdote Sombrio Allister d'O Sepulcro. Ela encarrega aventureiros de atacar os Dalaran Wizards e Watchers ao longo das estradas perto de Lenhâmbar para interromper as remessas do Kirin Tor em território dos Renegados.",h="Watching the Roads é uma missão dos Renegados na Floresta de Pinhaprata sob a liderança do Sacerdote Sombrio...",kw={"lenhâmbar","dalaran watcher","dalaran wizard","kirin tor","pingentes","relíquias","o sepulcro","sacerdote sombrio allister","floresta de pinhaprata","watching the roads"},ang={["class:Mage"]="Os magos e vigias de Dalaran dependem de relíquias especializadas e patrulhas mágicas para garantir a passagem, tornando-se alvos primordiais para conjuradores rivais.",["class:Priest"]="O Sacerdote Sombrio Allister comanda essa ofensiva a partir d'O Sepulcro, demonstrando o papel ativo do clero dos Renegados na defesa de fronteiras.",["faction:Horde"]="Interromper as linhas de suprimento de Dalaran ao redor de Lenhâmbar ajuda a manter o domínio da Horda na região contra enclaves humanos hostis.",["race:Undead"]="Garantir as rotas de trânsito pela Floresta de Pinhaprata é vital para que os Renegados defendam suas fronteiras e detenham as incursões mágicas de Dalaran."},sec={{t="Tensões ao longo da Estrada de Lenhâmbar",b="Ao longo das vias que contornam Lenhâmbar, o Kirin Tor mantém uma presença agressiva. Após o colapso da barreira que cercava Dalaran, seus magos e sentinelas vigilantes intensificaram o controle sobre o trânsito através das fronteiras da Floresta de Pinhaprata. De sua base n'O Sepulcro, os Renegados observam essa mobilização com crescente preocupação, reconhecendo que os magos humanos estão usando essas estradas abertas para transportar relíquias perigosas e pingentes encantados para o interior de terras disputadas."},{t="Cortando a Linha de Suprimentos",b="O Sacerdote Sombrio Allister vê o confisco de pingentes individuais apenas como o tratamento de um sintoma. Para deter o fluxo de artefatos mágicos de Dalaran, ele envia agentes para caçar os escoltas do Kirin Tor diretamente ao longo da estrada. Ao abater tanto Dalaran Wizards quanto Dalaran Watchers perto de Lenhâmbar, os Renegados buscam quebrar o controle implacável do Kirin Tor sobre o trânsito regional e selar sua fronteira oriental contra a interferência arcana externa."}},faq={{q="Quem dá a missão Watching the Roads?",a="A missão é concedida e concluída pelo Sacerdote Sombrio Allister, localizado n'O Sepulcro, na Floresta de Pinhaprata. Ele encarrega os campeões de atacar as patrulhas do Kirin Tor que operam ao longo das vias comerciais locais.",al={"quem dá watching the roads","concedente da missão watching the roads","onde entregar watching the roads"}},{q="Por que os Renegados estão atacando patrulhas de Dalaran perto de Lenhâmbar?",a="O Sacerdote Sombrio Allister quer cortar o fluxo constante de relíquias mágicas e pingentes que estão sendo transportados de Dalaran para a Floresta de Pinhaprata. Eliminar os magos e vigias ao longo das estradas perto de Lenhâmbar priva Dalaran de seu acesso fácil através das fronteiras dos Renegados.",al={"por que matar dalaran wizards","por que atacar as estradas de lenhâmbar","objetivo do kirin tor na floresta de pinhaprata"}},{q="Qual é a situação da barreira ao redor de Dalaran?",a="De acordo com o Sacerdote Sombrio Allister, a barreira protetora que cercava Dalaran caiu. Em resposta, o Kirin Tor apertou o controle sobre as estradas ao redor, demonstrando uma paranoia perceptível enquanto patrulha a região de Lenhâmbar.",al={"o que aconteceu com a barreira de dalaran","cúpula de dalaran caiu","barreira de dalaran destruída"}},{q="Onde os Dalaran Wizards e Watchers podem ser encontrados?",a="Tanto Dalaran Wizards quanto Dalaran Watchers podem ser encontrados patrulhando as estradas ao redor da vila de Lenhâmbar, na Floresta de Pinhaprata. Eles monitoram o trânsito para proteger a movimentação de membros do Kirin Tor e de itens encantados.",al={"onde estão os dalaran watchers","locais de patrulha de lenhâmbar","onde encontrar dalaran wizards"}},{q="Que tipo de itens Dalaran está transportando por essas estradas?",a="O Kirin Tor tem transportado pingentes encantados e outras relíquias mágicas para fora de Dalaran e para dentro da Floresta de Pinhaprata. Allister busca interromper essa rota de suprimentos na fonte antes que os artefatos possam se espalhar ainda mais pelo território.",al={"quais relíquias dalaran está transportando","o que são os pingentes","pingentes de lenhâmbar"}},{q="Por que o Kirin Tor está tão vigilante ao longo das estradas de Lenhâmbar?",a="Desde que a barreira mágica ao redor de Dalaran caiu, o Kirin Tor mantém uma vigilância agressiva nas vias que levam à Floresta de Pinhaprata. Embora Allister observe sua profunda suspeita e vigilância, seus motivos exatos permanecem não confirmados para os Renegados n'O Sepulcro.",al={"por que o kirin tor está paranoico","por que os guardas de dalaran estão patrulhando","controle de estradas pelo kirin tor"}}},fp="18,228,33.326.0,24.339.0,39.144.0,62.207.0,54.143.0,52.161.0,57.187.0,60.210.0"}
P.entries["quest:95982"] = {n="Not My Circus",s="Jasper Geartoggle pede sua ajuda para manter alimentados os animais abandonados no Porto Detonapavio. Ele precisa de Briny Seafood Stew antes que as feras famintas causem problemas.",h="Jasper Geartoggle pede sua ajuda para manter alimentados os animais abandonados no Porto Detonapavio.",kw={"briny seafood stew","cavalos","animais famintos","jasper geartoggle","não é meu circo","porto detonapavio","lobos"},sec={{t="Feras famintas",b="No Porto Detonapavio, Jasper Geartoggle pede sua ajuda com os animais deixados sob seus cuidados. Os donos o culpam quando um cavalo, lobo ou outra fera morre ou foge. Ele precisa de Briny Seafood Stew para mantê-los sob controle, antes que a fome os faça sair em disparada."}},faq={{q="Quem está pedindo ajuda?",a="Jasper Geartoggle pede sua ajuda para alimentar os animais deixados sob seus cuidados.",al={"quem precisa de ajuda","quem é jasper","jasper geartoggle"}},{q="Do que Jasper precisa?",a="Jasper precisa de Briny Seafood Stew para os animais sob seus cuidados.",al={"que comida ele quer","que ensopado","ensopado briny"}},{q="Por que Jasper precisa de ensopado?",a="Jasper diz que os animais estão com fome e que precisa de comida para mantê-los sob controle.",al={"por que ensopado","animais famintos","animais em apuros"}},{q="Onde devo levar o ensopado?",a="Leve Briny Seafood Stew para Jasper Geartoggle no Porto Detonapavio.",al={"onde fica jasper","onde levar o ensopado","porto detonapavio"}},{q="Por que estão deixando animais com Jasper?",a="As pessoas continuam deixando seus cavalos, lobos e outros animais com Jasper.",al={"animais abandonados","quem deixou os animais","por que há animais aqui"}}},fp="13,149,13.261.0,23.69.0,22.60.0,26.75.0,30.69.0,39.72.0"}
P.entries["quest:95991"] = {n="WANTED: Ghostmaw",s="Wheatley teme que um crocolisco fantasma chamado Ghostmaw esteja levando seus pôneis mais valiosos dos rios. Ele espera na Bastilha de Ermoforte até que alguém lhe traga a presa da criatura.",h="Wheatley teme que um crocolisco fantasma chamado Ghostmaw esteja levando seus pôneis mais valiosos dos rios.",kw={"crocolisco","presa","bastilha de ermoforte","ghostmaw","bosques","pôneis","rios","wheatley"},sec={{t="A preocupação de Wheatley",b="Wheatley parou de levar seus cavalos pelos bosques por causa dos relatos de Ghostmaw nos rios. Dizem que o crocolisco tem três vezes o tamanho de um comum e é duas vezes mais feroz. Leve a presa de Ghostmaw para Wheatley, para que ele saiba que é seguro voltar a viajar."}},faq={{q="Quem é Ghostmaw?",a="Ghostmaw é um misterioso crocolisco fantasma avistado nos rios, que dizem ser muito maior e mais feroz que um crocolisco comum.",al={"ghostmaw","crocolisco ghostmaw","crocolisco fantasma"}},{q="Por que Wheatley parou de levar seus cavalos?",a="Wheatley teme que Ghostmaw devore seus pôneis mais valiosos, então está parado até que a criatura seja eliminada.",al={"por que wheatley parou","cavalos parados","wheatley assustado"}},{q="O que Wheatley quer que tragam para ele?",a="Wheatley pede a presa de Ghostmaw como prova de que o crocolisco não representa mais perigo para quem viaja.",al={"presa de ghostmaw","o que levar para wheatley","presa"}},{q="Onde devo levar a presa de Ghostmaw?",a="Leve a presa de Ghostmaw para Wheatley, na Bastilha de Ermoforte.",al={"onde fica wheatley","bastilha de ermoforte","local da presa"}}},fp="16,167,20.269.0,16.130.0,43.106.0,39.96.0,39.53.0"}
P.entries["quest:95992"] = {n="WANTED: Ghostmaw",s="Tan'jani propõe uma competição para capturar Ghostmaw, um crocolisco branco que ronda os rios. Leve sua presa a Rog'mar para ficar com o prêmio.",h="Tan'jani propõe uma competição para capturar Ghostmaw, um crocolisco branco que ronda os rios.",kw={"crocolisco","presa","ghostmaw","caçador de cabeças","rios","rog'mar","tan'jani"},sec={{t="Competição à Beira do Rio",b="Tan'jani, em Rog'mar, propõe uma competição para você. Um crocolisco branco chamado Ghostmaw ronda os rios, e nem os caçadores de cabeças conseguiram capturá-lo. Leve Ghostmaw's Fang a Tan'jani; o vencedor fica com o prêmio."}},faq={{q="Quem é Ghostmaw?",a="Ghostmaw é um crocolisco branco que ronda os rios.",al={"ghostmaw","crocolisco branco","crocolisco ghostmaw"}},{q="Quem quer a presa de Ghostmaw?",a="Tan'jani, em Rog'mar, pede que você traga Ghostmaw's Fang.",al={"presa de tan'jani","quem quer a presa","presa para quem"}},{q="O que Tan'jani quer que eu traga?",a="Tan'jani quer Ghostmaw's Fang.",al={"presa de ghostmaw","o que trazer","presa"}},{q="Qual é o objetivo da competição?",a="Tan'jani diz que o vencedor da competição para capturar Ghostmaw fica com o prêmio.",al={"competição de tan'jani","o prêmio","por que capturar ghostmaw"}}},fp="16,136,17.206.0,16.53.0,26.54.0,36.31.0,30.77.0"}
P.entries["quest:95998"] = {n="The Great Outdoors",s="The Great Outdoors é uma missão introdutória de sobrevivência na natureza, na qual o viajante Sam ensina aventureiros novatos a arte de acampar ao ar livre. Ao parar para descansar ao lado de uma fogueira básica, os viajantes aprendem a se sustentar na estrada antes de buscar perícias especializadas.",h="The Great Outdoors é uma missão introdutória de sobrevivência na natureza, na qual o viajante Sam ensina...",kw={"fogueira básica","descanso aprimorado","instalação de acampamento","técnicas de acampamento","sobrevivente","sam","the great outdoors","perícia"},ang={["class:Hunter"]="Viver dos recursos da terra e descansar ao lado de uma chama aberta é algo natural para os rastreadores da natureza, mas até mesmo batedores experientes se beneficiam de dominar técnicas de acampamento.",["profession:Cooking"]="Fogueiras são um elemento essencial da culinária de campo, e aprender as técnicas adequadas de acampamento na natureza fornece a base para o preparo de refeições sob o céu aberto."},sec={{t="Lições ao Lado do Fogo",b="As vastas terras de Azeroth chamam incontáveis almas inquietas em busca de fortuna, perigo e renome. Contudo, a ambição pura e simples não consegue proteger um aventureiro novato do frio cortante ou da exaustão da estrada aberta. Dominar a arte básica da vida ao ar livre — saber quando parar, acender uma fogueira e recuperar as forças — é a base silenciosa sobre a qual toda jornada lendária é construída. O convite de Sam oferece aos recém-chegados a chance de fazer uma pausa e aprender esses hábitos essenciais de sobrevivência ao ar livre."},{t="Técnicas de Campo e Ofício",b="Abrigar-se ao lado de uma fogueira aquecida faz mais do que afastar o frio da noite; proporciona um momento vital de recuperação conhecido como descanso aprimorado. Sobreviventes experientes reconhecem que a resistência na natureza depende de descansar adequadamente entre expedições. Uma vez compreendidos esses fundamentos de sobrevivência, artesãos e coletores podem voltar sua atenção para as perícias, aprendendo a montar instalações de acampamento dedicadas e adaptadas ao seu trabalho específico em campo."}},faq={{q="Quem é Sam?",a="Sam é um experiente sobrevivente e viajante tarimbado que assume a tarefa de ensinar a aventureiros novatos os fundamentos da sobrevivência na natureza. Ele acolhe almas errantes para compartilhar o calor de sua fogueira enquanto transmite conhecimentos práticos de vida ao ar livre.",al={"quem é sam","missão da fogueira de sam","concessor da missão"}},{q="Qual é o objetivo de sentar-se junto à fogueira?",a="O Descanso Aprimorado representa o efeito rejuvenescedor de repousar ao lado de uma fogueira adequada na natureza. Reservar um tempo para sentar-se no calor e no conforto permite que aventureiros cansados recuperem sua vitalidade e permaneçam revigorados para a estrada à frente.",al={"o que é descanso aprimorado","bônus de descanso aprimorado","descansando perto do fogo"}},{q="Por que as habilidades na natureza são importantes para aventureiros?",a="O mundo além dos muros dos assentamentos é vasto e perigoso, exigindo que qualquer viajante em busca de fortuna e glória aprenda a se sustentar. As técnicas de campo adequadas garantem que os viajantes resistam a longas jornadas sem sucumbir à fadiga.",al={"por que aprender habilidades de sobrevivente","por que prosperar na natureza","habilidades de sobrevivência"}},{q="Qual é a relação entre as perícias e o acampamento na natureza?",a="Depois de aprender a estabelecer um acampamento básico, os mestres de perícias podem ensinar você a criar instalações de acampamento especializadas e adaptadas à sua profissão escolhida, aprimorando suas capacidades enquanto estiver em campo.",al={"acampamento de perícias","instalações de acampamento","profissões depois disso"}},{q="O que um aventureiro deve fazer após concluir esta lição?",a="Assim que você descansar junto ao fogo de Sam e compreender as técnicas básicas de acampamento, Sam incentiva você a procurar instrutores de profissão. Progredir em um ofício prático permite que você construa postos de campo personalizados e adequados ao seu ofício.",al={"próximos passos","o que fazer depois de the great outdoors","depois da missão da fogueira"}},{q="Quem pode realizar The Great Outdoors?",a="A missão está aberta a qualquer alma inquieta que parta em direção ao mundo afora, independentemente de sua origem ou lealdade, servindo como uma lição introdutória para sobreviver à vida na estrada.",al={"qualquer um pode fazer isso","quem pode aceitar the great outdoors","esta missão é geral"}}},fp="18,117,19.257.0,20.322.0,11.166.0,47.169.0,52.162.0,48.128.0,58.167.0,37.111.0"}
P.entries["quest:95999"] = {n="PROCURADO: Incinerador Gar'im",s="PROCURADO: Incinerador Gar'im é uma recompensa publicada pelas autoridades de Vila Plácida contra um comandante orc hostil entrincheirado no Vale dos Laceradores. Gar'im comanda um perigoso contingente de conjuradores das sombras e supostamente trabalha com o clã Blackrock que domina a Bastilha Mirante de Pedra. O Magistrado Salomão oferece uma generosa recompensa por uma Prova da morte dele.",h="PROCURADO: Incinerador Gar'im é uma recompensa publicada pelas autoridades de Vila Plácida contra um...",kw={"blackrock","recompensa","gar'im","incinerador","vila plácida","vale dos laceradores","conjurador das sombras","salomão"},ang={["class:Mage"]="Gar'im e seus conjuradores das sombras representam uma exibição corrompida de magia arcana ofensiva e Magia Sombria que requer uma rápida contraofensiva de feitiçaria.",["faction:Alliance"]="Abater o Incinerador Gar'im protege diretamente os cidadãos vulneráveis de Vila Plácida do líder de uma incursão de orcs e de seus extremamente perigosos Conjuradores das Sombras."},sec={{t="Fogo no Vale dos Laceradores",b="As Montanhas Cristarrubra tornaram-se cada vez mais perigosas à medida que os orcs Blackrock avançam a partir de seus bastiões nas montanhas. No Vale dos Laceradores, o Incinerador Gar'im lidera uma incursão ativa, comandando feitiçaria sombria ao lado de leais conjuradores das sombras. Com a guarda da cidade local sobrecarregada e os exércitos da coroa praticamente ausentes, o Magistrado Salomão recorreu a mercenários independentes para eliminar Gar'im, que supostamente trabalha com os Blackrock da Bastilha Mirante de Pedra."},{t="Prova da morte",b="Gar'im é famoso por sua magia destrutiva e pelo comando sobre conjuradores que tecem sombras. Para reivindicar a recompensa do vilarejo, os caçadores devem se aventurar profundamente em território inimigo, derrotar o incinerador e levar seu cajado estilhaçado à prefeitura de Vila Plácida como prova física de que a ameaça foi eliminada."}},faq={{q="Quem é o Incinerador Gar'im?",a="O Incinerador Gar'im é um senhor da guerra e conjurador orc que lidera uma incursão no Vale dos Laceradores. Ele supostamente trabalha com os orcs Blackrock da Bastilha Mirante de Pedra e comanda perigosos conjuradores das sombras.",al={"quem é gar'im","garim","incinerador garim"}},{q="Onde o Incinerador Gar'im pode ser encontrado?",a="Gar'im estabeleceu seu acampamento entre as forças orcs hostis no Vale dos Laceradores, situado no sudeste das Montanhas Cristarrubra.",al={"localização de gar'im","onde fica garim","localização do vale dos laceradores"}},{q="Quem publicou a recompensa por Gar'im?",a="A recompensa foi publicada em nome de Vila Plácida pelo Magistrado Salomão, que está desesperado para conter as incursões de orcs que pressionam a cidade sitiada.",al={"quem ofereceu a recompensa","recompensa de salomão"}},{q="Qual prova é necessária para reivindicar a recompensa?",a="O Magistrado Salomão exige o Cajado Quebrado do Incinerador Gar'im para confirmar a morte do conjurador antes de pagar a recompensa.",al={"prova de garim","item de missão cajado quebrado"}},{q="Qual ameaça Gar'im e seus seguidores representam?",a="Gar'im empunha uma magia destrutiva letal e é acompanhado por conjuradores das sombras. A presença deles fortalece o domínio do clã Blackrock em Cristarrubra e ameaça sobrecarregar Vila Plácida se nada for feito.",al={"habilidades de gar'im","conjuradores das sombras cristarrubra"}},{q="Por que Vila Plácida depende de recompensas em vez do exército de Ventobravo?",a="Ventobravo deixou Cristarrubra praticamente por conta própria em meio a disputas políticas e à escassez de tropas, forçando o Magistrado Salomão a contratar aventureiros dispostos a assassinar os líderes inimigos.",al={"por que recompensas vila plácida","onde está o exército de ventobravo"}}},fp="26,235,25.404.0,15.259.0,26.193.0,38.97.0,33.128.0,43.128.0,45.190.0,68.170.0"}
P.entries["quest:96"] = {n="Clamor da água",s="Esta tarefa marca o ponto culminante da árdua peregrinação do xamã para se sintonizar com o elemento da água. Ao devolver um Estilhaço de Água purificado a Islen Vidente da Água ao longo da costa dos Sertões, o iniciado prova sua harmonia com as energias restauradoras e conquista seu Totem da Água.",h="Esta tarefa marca o ponto culminante da árdua peregrinação do xamã para se sintonizar com o elemento da água.",kw={"clamor da água","islen vidente da água","manifestação menor da água","estilhaço de água","floresta de pinhaprata","sertões","totem da água"},ang={["class:Shaman"]="Este rito de passagem concede seu Totem da Água, liberando as fontes restauradoras e as fontes purificadoras centrais para o seu papel como curador espiritual.",["faction:Horde"]="A provação demonstra a responsabilidade espiritual da Horda, convocando jovens xamãs a purificar terras assoladas em Kalimdor e nos Reinos do Leste."},sec={{t="Uma Longa Viagem de Volta",b="A busca pela água exige que o iniciado atravesse continentes, viajando até as margens contaminadas de Floresta de Pinhaprata para confrontar a corrupção diretamente. A água representa a vida, a adaptabilidade e a cura, mas sua natureza maleável a deixa singularmente vulnerável à praga e à magia sombria. Após ficar diante da Manifestação Menor da Água e testemunhar a pura vontade elemental, o iniciado é agraciado com uma dádiva singular: o Estilhaço de Água. Levar essa lembrança de volta pelo mar até os ensolarados Sertões é uma recordação física de que a água conecta todos os cantos distantes do mundo."},{t="O Totem da Água",b="Quando Islen Vidente da Água recebe o estilhaço, ela não se limita a examinar a prova de uma tarefa concluída; ela testa se o xamã internalizou o equilíbrio entre a preservação e a renovação. A podridão invasora de Lordaeron muitas vezes mascara vitórias sutis, mas purificar até mesmo uma nascente isolada é importante para os espíritos. Com essa oferenda reconhecida, Islen concede o Totem da Água ao xamã. Esse foco físico permite que o praticante canalize correntes purificadoras, de cura e restauradoras de mana para o reino mortal, consolidando sua comunhão permanente com as marés."}},faq={{q="O que é o Estilhaço de Água?",a="O Estilhaço de Água é um resquício elemental concentrado concedido pela Manifestação Menor da Água. Ele serve como evidência tangível de que o iniciado compreendeu o papel da água como uma força geradora de vida e se opôs com sucesso à corrupção que ameaça as correntes elementais.",al={"estilhaço de água","fragmento de água","o que é o estilhaço"}},{q="Onde devo levar o Estilhaço de Água?",a="O estilhaço deve ser levado de volta a Islen Vidente da Água, que reside em um acampamento isolado ao longo da costa leste dos Sertões, ao sul de Vila Catraca.",al={"onde entregar","quem recebe o estilhaço","local de entrega"}},{q="O que recebo ao concluir esta provação?",a="A conclusão desta provação final concede ao xamã seu Totem da Água, o canal vital necessário para evocar totens elementais baseados em água para feitiços de cura e magia restauradora.",al={"recompensa da missão","recompensa do totem","o que eu ganho"}},{q="Por que a provação foi realizada em Floresta de Pinhaprata?",a="As águas de Floresta de Pinhaprata sofrem intensa corrupção pela peste e pela Magia Sombria. Enviar o xamã até lá o forçou a testemunhar a fragilidade da água e a defender ativamente sua pureza natural contra a decadência.",al={"por que pinhaprata","por que reinos do leste","água de pinhaprata"}},{q="Quem é Islen Vidente da Água?",a="Islen Vidente da Água é uma xamã tauren situada ao longo da costa leste dos Sertões. Ela supervisiona as provações xamânicas da água, ensinando os iniciados a comungar com os espíritos fluídos e a dominar as artes restauradoras.",al={"islen","quem é islen vidente da água"}}},fx={["352084e3"]={q="Por que a Manifestação Menor da Água envia você de volta para Islen?",a="A manifestação elemental serve como a voz viva da água pura, testada e invocada através de seus rituais. Ao conceder a você o Estilhaço de Água, ela lhe confia a verdade fundamental de sua natureza: a água traz vida, enquanto a corrupção a extingue. Ela o envia de volta para Islen Vidente da Água para que a xamã possa confirmar sua comunhão com os espíritos, reconhecer seu sucesso em confrontar a corrupção e conceder-lhe o Totem da Água que você provou ser digno de empunhar.",al={"motivação da manifestação menor","por que levar o estilhaço para islen","por que a manifestação da água quer isso"}}},fp="13,155,19.504.0,15.455.0,27.198.0,35.113.0,44.121.0,43.166.0,23.188.0"}
P.entries["quest:960"] = {n="Onu está meditando",s="Ao investigar o Glaive do Mestre no sul de Costa Negra, o ancestral do saber Onu entra em um transe profundo para contemplar a ameaça crescente. Jogadores que perderem seu Frasco de Vidência místico podem falar com o ancestral meditando para receber uma reposição. Seus pensamentos centram-se na aliança sinistra e nas motivações do culto Twilight's Hammer e das naga serpentinas.",h="Ao investigar o Glaive do Mestre no sul de Costa Negra, o ancestral do saber Onu entra em um transe profundo...",kw={"costa negra","bosque dos ancientes","glaive do mestre","meditando","onu","frasco de vidência","bacia de vidência","twilight's hammer"},ang={["class:Druid"]="Druidas compartilham um vínculo natural profundo com ancestrais do saber. Manter a comunicação via rituais de vidência reflete o método do Círculo Cenariano de examinar solo contaminado à distância.",["faction:Alliance"]="Garantir a segurança de Costa Negra contra cultistas e invasores aquáticos é crítico para viajantes da Aliança que viajam entre Teldrassil e Vale Gris.",["race:NightElf"]="Como guardiões do equilíbrio de Kalimdor, os elfos noturnos reverenciam ancestrais do saber como Onu, confiando em sua sabedoria atemporal para interpretar distúrbios nas terras selvagens de Costa Negra."},sec={{t="Uma Mente em Profunda Contemplação",b="Onu é um Ancestral do Saber enraizado no Bosque dos Ancientes de Costa Negra, servindo como um repositório vivo da história de Kalimdor. Quando relatos sinistros surgem sobre escavações sombrias na Glaive do Mestre, Onu volta sua imensa consciência para dentro. Ele medita profundamente sobre o que poderia atrair tanto os cultistas fanáticos do Twilight's Hammer quanto as naga insidiosas aos restos petrificados de um antigo gigante. Para aventureiros realizando seu reconhecimento, ele permanece como uma âncora acessível, oferecendo frascos de vidência de reposição caso os deles sejam perdidos na natureza selvagem."},{t="Perscrutando as Profundezas",b="Para monitorar as ruínas sem arriscar a presença física do ancestral, Onu conta com a adivinhação sintonizada com a natureza. Aventureiros recebem um Frasco de Vidência, destinado a conjurar uma bacia de vidência diretamente dentro do local da escavação para que Onu possa comungar à distância. Como a jornada para o sul através de Costa Negra é perigosa e cheia de vida selvagem hostil e patrulhas de cultistas, Onu antecipa contratempos. Seu transe não é um sono ininterrupto, mas uma vigília atenta; ele prontamente fornece outro frasco de águas sagradas para garantir que a investigação da Glaive do Mestre continue sem demora."}},faq={{q="Por que Onu está meditando?",a="Onu é um ancestral do saber ponderando sobre a presença perturbadora tanto do culto Twilight's Hammer quanto das naga na Glaive do Mestre. Ele usa esta meditação para perceber suas motivações e guiar aventureiros que investigam o local.",al={"por que onu está meditando","transe de onu","o que onu está fazendo"}},{q="Qual é o propósito desta interação?",a="Serve como um mecanismo de segurança para jogadores na missão 'Glaive do Mestre'. Se você perder, destruir ou usar prematuramente seu Frasco de Vidência, falar com o Onu meditando fornece a você um frasco de reposição para que você possa completar o ritual.",al={"perdi o frasco de vidência","obter outro frasco","reposição de frasco de onu"}},{q="Onde Onu está localizado?",a="Onu está enraizado no Bosque dos Ancientes, localizado no centro-sul de Costa Negra, logo após a estrada principal.",al={"localização de onu","onde encontrar onu"}},{q="O que faço com o Frasco de Vidência?",a="Leve o frasco até a Glaive do Mestre e use-o para criar uma bacia de vidência. Onu poderá então se comunicar com você através da bacia.",al={"como usar o frasco de vidência","bacia de vidência costa negra","propósito do frasco de vidência"}},{q="O que é a Glaive do Mestre?",a="A Glaive do Mestre é um enorme e antigo local de escavação no sul de Costa Negra onde o crânio colossal e petrificado de uma entidade esquecida jaz perfurado por uma lâmina gigantesca. Cultistas e naga convergiram para lá com propósitos malignos desconhecidos.",al={"o que é a glaive do mestre","monumento no sul de costa negra"}},{q="Jogadores da Horda podem interagir com Onu aqui?",a="Não. Onu é aliado estritamente dos elfos noturnos e da Aliança. Aventureiros da Horda invadindo as proximidades do Bosque dos Ancientes encontrarão Onu e seus protetores hostis ou não cooperativos.",al={"onu é apenas da aliança","horda onu meditando"}}},fx={["72a6a09e"]={q="Por que Onu precisa da sua ajuda em vez de investigar por conta própria?",a="Onu permanece no Bosque dos Ancientes para meditar sobre o Martelo do Crepúsculo e os nagas. Ele depende de viajantes para investigar The Master's Glaive e entrar em contato com ele através de uma bacia de vidência.",al={"por que me enviar","por que onu não vai","por que onu precisa de você"}}},fp="17,243,28.421.0,18.499.0,22.187.0,40.184.0,21.97.0,39.127.0,28.238.0,41.169.0"}
P.entries["quest:96009"] = {n="High Stakes",s="Bertrand Ironbrow precisa que feixes de madeira sejam levados do Turner's Logging Camp à Bastilha de Ermoforte. A madeira ajudará a fortaleza a terminar seu portão enquanto os orcs ficam mais agressivos.",h="Bertrand Ironbrow precisa que feixes de madeira sejam levados do Turner's Logging Camp à Bastilha de...",kw={"bertrand ironbrow","bastilha de ermoforte","portão","altas apostas","madeira","murlocs","turner's logging camp","feixes de madeira"},sec={{t="Madeira para a fortaleza",b="Bertrand Ironbrow precisa de madeira para a Bastilha de Ermoforte, onde as pessoas constroem em meio a uma zona de guerra cheia de orcs e cultistas. Pedem que você leve feixes do Turner's Logging Camp, pois estradas perigosas atrasaram as remessas. O portão da fortaleza ainda está em construção, e os orcs estão ficando mais agressivos."}},faq={{q="Quem precisa da madeira?",a="Bertrand Ironbrow precisa da madeira na Bastilha de Ermoforte.",al={"quem quer madeira","madeira bertrand","feixes de madeira para quem"}},{q="De onde vêm os feixes?",a="Os feixes vêm do Turner's Logging Camp, a noroeste da Bastilha de Ermoforte.",al={"onde fica a madeira","madeira do acampamento turner","acampamento de madeira"}},{q="Por que a madeira está atrasada?",a="Estradas perigosas atrasaram as remessas de madeira da serraria a noroeste.",al={"por que as remessas atrasam","estradas perigosas","atraso na madeira"}},{q="Para que serve a madeira?",a="A madeira será usada na Bastilha de Ermoforte e talvez ajude a terminar o portão.",al={"por que precisam de madeira","madeira para o portão","construção na fortaleza"}},{q="O que torna as estradas perigosas?",a="Há crocodilos e murlocs pelo caminho entre a fortaleza e a serraria.",al={"crocodilos e murlocs","o que há na estrada","perigo na estrada"}}},fp="11,161,17.306.0,19.50.0,31.72.0,27.80.0,21.65.0,31.67.0"}
P.entries["quest:96010"] = {n="Fragments of the Pylons",s="Mordent Evenshade pede que você recupere fragmentos de pilone nas aldeias Magram e Gelkis, em Shen'dralas. As peças são necessárias para seu trabalho nos pilones danificados.",h="Mordent Evenshade pede que você recupere fragmentos de pilone nas aldeias Magram e Gelkis, em Shen'dralas.",kw={"centauro","cristais","fragmentos dos pilones","gelkis","magram","mana","mordent evenshade","pilone","lascas","shen'dralas"},sec={{t="Pilones Quebrados",b="Mordent Evenshade acredita que as investidas dos centauros danificaram os dois pilones em Shen'dralas. Ele suspeita que os Magram e os Gelkis levaram as lascas espalhadas para suas aldeias como troféus. Você deve recuperar os fragmentos protegidos lá e levá-los até ele."},{t="Os Cristais",b="Mordent recebe os fragmentos e diz que os cristais estão mais quebrados do que esperava. Ele vai guardá-los por enquanto. Seu próximo passo é reunir mana maleável, que pode unir as peças e permitir que o poder das linhas ley passe por elas."}},faq={{q="Quem pede os fragmentos dos pilones?",a="Mordent Evenshade pede que você recupere lascas e fragmentos nas aldeias Magram e Gelkis e os leve de volta para ele.",al={"quem é mordent","mordent evenshade","quem quer os cristais"}},{q="Onde estão os fragmentos dos pilones?",a="Mordent acredita que os Magram e os Gelkis levaram os fragmentos dos pilones para suas aldeias em Shen'dralas.",al={"onde estão as lascas","localização das peças do pilone","encontrar fragmentos"}},{q="Por que os pilones estão danificados?",a="Mordent acredita que a atividade imprudente dos centauros danificou os dois pilones.",al={"o que quebrou os pilones","dano dos centauros","por que o pilone está quebrado"}},{q="O que Mordent planeja fazer com os fragmentos?",a="Mordent planeja unir as peças quebradas com mana maleável e usar essa mana como condutor para as linhas ley.",al={"para que servem os cristais","como reparar os pilones","plano de mordent"}}},fp="23,163,13.254.0,12.222.1,33.118.0,30.97.0,27.63.0,48.106.0"}
P.entries["quest:96018"] = {n="Powering the Pylons",s="Mordent Evenshade pede que você restaure os pilares danificados em Shen'dralas. Mana flutuante surgiu por lá, e ele precisa que você a reúna e a devolva aos pilares.",h="Mordent Evenshade pede que você restaure os pilares danificados em Shen'dralas.",kw={"ancient mana crystals","mana flutuante","mana sieve","mordent evenshade","pilares","shen'dralas"},sec={{t="Reunindo Mana",b="Dentro do templo de Shen'dralas, você procura o Mana Sieve, um artefato cujo empréstimo pode desagradar os habitantes do local. Mordent Evenshade precisa que você reúna a mana dispersa em forma semicristalizada. Com Ancient Mana Crystals suficientes, você pode energizar os pilares danificados e levar o resultado do trabalho do artefato até ele."},{t="Os Pilares",b="Mordent Evenshade vê os pilares restaurados e gesticula em direção ao céu. Ao se voltar para você, ele percebe sua reação contida."}},faq={{q="Por que Mordent precisa de mana?",a="Mordent precisa que você reúna mana na forma de Ancient Mana Crystals para energizar os pilares danificados em Shen'dralas.",al={"por que mana","mana de mordent"}},{q="Onde encontro o Mana Sieve?",a="O Mana Sieve fica dentro do templo em Shen'dralas.",al={"localização do mana sieve","onde fica o sieve"}},{q="O que está acontecendo com a mana em Shen'dralas?",a="Centelhas de mana flutuantes surgiram por Shen'dralas, provavelmente porque os pilares foram danificados.",al={"mana flutuante","orbes de mana"}},{q="O que o Mana Sieve faz?",a="Você usa o Mana Sieve para reunir mana flutuante na forma de Ancient Mana Crystals.",al={"função do sieve","reunir mana"}},{q="Quem pediu que os pilares fossem energizados?",a="Mordent Evenshade pede que você reúna mana e energize os pilares.",al={"quem é mordent","mordent evenshade"}}},fp="19,159,14.294.0,10.129.1,27.98.0,31.51.0,45.105.0,28.72.0,45.65.0"}
P.entries["quest:96026"] = {n="Step Two: More Rock",s="Hamur em Bolder'ok quer Heavy Weightstones para reforçar uma arma. Ele diz que rocha fortalece rocha e pede que você traga mais.",h="Hamur em Bolder'ok quer Heavy Weightstones para reforçar uma arma.",kw={"bolder'ok","hamur","heavy weightstones","mais rocha","rocha","arma","pedras de amolar"},sec={{t="Pedido de Hamur",b="Hamur em Bolder'ok diz que falta um toque final na arma: mais rocha. Ele viu gente pequena fazer Heavy Weightstones e pede que você os traga para reforçar a arma."}},faq={{q="Quem quer Heavy Weightstones?",a="Hamur em Bolder'ok pede que você traga Heavy Weightstones.",al={"quem precisa de pedras de amolar","pedido de hamur"}},{q="Para que Hamur quer as pedras?",a="Hamur diz que vai usar Heavy Weightstones para reforçar uma arma.",al={"por que heavy weightstones","para que servem"}},{q="O que Hamur diz que fortalece a rocha?",a="Hamur diz que só a rocha pode fortalecer a rocha.",al={"como fortalecer rocha","mais rocha"}}},fp="19,129,15.176.0,33.56.0,30.69.0,40.49.0"}
P.entries["quest:96031"] = {n="Camping 101: Leatherworking",s="Camping 101: Leatherworking orienta os artesãos a utilizarem couros tratados para criar seu próprio abrigo portátil na natureza selvagem. O texto enfatiza as necessidades de sobreviver longe da civilização, lembrando aos aventureiros que um verdadeiro acampamento requer tanto uma barraca armada na natureza quanto uma fogueira de acampamento ardente ensinada por instrutores de culinária.",h="Camping 101: Leatherworking orienta os artesãos a utilizarem couros tratados para criar seu próprio abrigo...",kw={"barraca de acampamento","fogueira de acampamento","acampamento","culinária","couraria","abrigo","barraca","natureza selvagem"},ang={["profession:Cooking"]="A fogueira de acampamento é a peça central indispensável de qualquer acampamento na natureza selvagem. Aprender culinária básica garante que o aventureiro consiga acender chamas para manter um acampamento nas terras selvagens."},sec={{t="Armando Abrigo na Natureza Selvagem",b="Criar um abrigo pessoal é um marco essencial para qualquer artesão que trabalhe com peles e couro. Uma barraca de couro resistente oferece aos viajantes uma barreira confiável contra o clima severo, o vento e o frio da noite ao viajar por terrenos abertos. No entanto, os habitantes locais não veem com bons olhos abrigos pessoais armados em ruas movimentadas ou praças de mercado, o que significa que o aventureiro deve ir além dos portões da cidade, adentro da natureza selvagem, para armar seu abrigo."},{t="O Calor de uma Fogueira de Acampamento",b="Uma barraca armada é apenas metade do que compõe um acampamento sustentável. Um acampamento adequado requer uma fogueira ardente para afastar a escuridão, repelir os ventos frios e oferecer um refúgio acolhedor em terras perigosas. Como acender e cuidar do fogo é fundamental para preparar refeições em campo, os aventureiros são orientados a buscar instrução com mestres da culinária e instrutores de culinária para aprender a acender uma fogueira antes de estabelecer o acampamento."}},faq={{q="Onde você pode armar uma barraca de acampamento?",a="Os habitantes locais desaprovam a montagem de barracas de acampamento no meio de ruas ou praças da cidade. O aventureiro deve se aventurar pela natureza selvagem, onde há bastante espaço aberto para armar uma barraca adequadamente.",al={"uso da barraca de acampamento","onde armar barraca","posso acampar na cidade"}},{q="O que mais é necessário além de uma barraca para montar um acampamento?",a="Apenas uma barraca de acampamento não faz um acampamento funcional. Você também precisa de uma fogueira de acampamento adequada queimando ao lado da barraca antes que um acampamento de verdade possa ser estabelecido.",al={"precisa de fogueira para acampar","requisitos para acampar","como acampar"}},{q="Onde os aventureiros aprendem a fazer uma fogueira de acampamento?",a="Instrutores versados nas artes culinárias ensinam o básico do preparo de alimentos, o que inclui como acender e manter uma fogueira básica. Procurar um instrutor de culinária proporciona o conhecimento necessário para acender fogo em qualquer lugar.",al={"aprender fogueira de acampamento","quem ensina fogueira de acampamento","fogo de culinária"}},{q="Como a couraria se relaciona com a criação de barracas de acampamento?",a="Os coureiros usam couros tratados, peles e costuras resistentes para confeccionar coberturas de abrigo duráveis, capazes de suportar os elementos hostis da natureza selvagem. Esse ofício prático permite que os viajantes montem um abrigo confiável a partir de peles de animais.",al={"camping 101 leatherworking","barraca de acampamento de couro","criação de barraca couraria"}},{q="Por que os aventureiros estabelecem acampamentos na natureza selvagem?",a="Aventurar-se muito além dos postos avançados habitados expõe os viajantes aos elementos e a terrenos perigosos. Ter um abrigo portátil e um fogo acolhedor oferece um refúgio seguro para descansar e se recuperar quando se está longe de estalagens e povoados.",al={"por que acampar fora","propósito do acampamento","acampamento de sobrevivência na selva"}},{q="Por que os habitantes locais se opõem à montagem de barracas dentro da cidade?",a="Povoados e cidades têm estalagens estabelecidas e hospedagens privadas para viajantes. Erguer barracas em vias públicas obstrui a passagem e causa transtornos, de modo que os habitantes locais insistem que os acampamentos fiquem na natureza selvagem.",al={"regras de acampamento na cidade","proibido barracas na cidade","por que não posso armar barraca na cidade"}}},fp="27,193,28.361.0,24.324.0,32.125.0,53.76.0,47.139.0,54.205.0,53.213.0,56.202.0"}
P.entries["quest:96044"] = {n="Camping 101: Blacksmithing",s="Camping 101: Blacksmithing é uma tarefa introdutória que orienta os ferreiros até Tognus Flintfire em Kharanos. Por meio dele, os artesãos aprendem a construir uma roda de afiar portátil para manter as armas afiadas em acampamentos na natureza selvagem.",h="Camping 101: Blacksmithing é uma tarefa introdutória que orienta os ferreiros até Tognus Flintfire em...",kw={"ferraria","lâminas","acampamento","camping 101","dun morogh","kharanos","roda de afiar","tognus flintfire","armas"},ang={["class:Rogue"]="Uma adaga afiada é uma ferramenta indispensável do ofício para ladinos, tornando a roda de afiar do acampamento uma visão bem-vinda entre contratos em campo.",["class:Warrior"]="Os guerreiros dependem de gumes afiados no calor do combate e se beneficiam diretamente quando ferreiros trazem rodas de afiar para o acampamento de uma expedição.",["profession:Blacksmithing"]="Ferreiros aspirantes podem aprender a fabricar utilitários de campo, como a roda de afiar, expandindo seu ofício além das forjas das cidades para apoiar aliados no ermo.",["race:Dwarf"]="Com Kharanos aninhada nas colinas nevadas de Dun Morogh, os ferreiros anões se orgulham de manter o aço frio afiado e pronto para qualquer estrada."},sec={{t="Manutenção de Campo para a Estrada Aberta",b="Camping 101: Blacksmithing direciona ferreiros novatos a aprender a arte da utilidade de campo. Embora qualquer forja da cidade possa moldar um peitoral ou uma espada, aventureiros em viagem precisam de manutenção muito além do conforto das muralhas da cidade. Os ferreiros que comprovam sua proficiência básica são encaminhados a Kharanos, onde mestres artesãos compartilham métodos para transformar metal bruto em ferramentas portáteis de acampamento que mantêm as lâminas afiadas em longas jornadas."},{t="O Mestre de Kharanos",b="No assentamento nevado de Kharanos, Tognus Flintfire ensina ferreiros capacitados a construir a roda de afiar. Montar uma dessas pedras de amolar em um acampamento transforma um local comum de descanso em um armazém temporário de armas, atraindo guerreiros e ladinos ansiosos por remover mossas e o embotamento do seu aço antes da próxima marcha."}},faq={{q="Quem é Tognus Flintfire?",a="Tognus Flintfire é um instrutor de ferraria situado na cidade de Kharanos, em Dun Morogh. Ele treina ferreiros que demonstraram proficiência suficiente em seu ofício, ensinando-os a fabricar equipamentos especializados de acampamento.",al={"quem é tognus flintfire","onde fica tognus","localização de tognus flintfire"}},{q="O que é uma Roda de Afiar?",a="A roda de afiar é um item utilitário de acampamento criado por ferreiros. Quando montada no acampamento de um aventureiro, oferece uma estação de trabalho dedicada onde aliados armados, como guerreiros e ladinos, podem afiar e manter os gumes das suas lâminas em campo.",al={"o que a roda de afiar faz","acampamento com roda de afiar","objetivo da roda de afiar"}},{q="Por que os guerreiros e ladinos se importam com a Roda de Afiar?",a="Guerreiros e ladinos são os que mais se beneficiam de ter uma roda de afiar no acampamento, pois sua eficácia em combate depende muito de manter o corte afiado de suas lâminas, machados e adagas durante viagens prolongadas longe das forjas das cidades.",al={"quem precisa da roda de afiar","guerreiros roda de afiar","ladinos roda de afiar"}},{q="Onde fica Kharanos?",a="Kharanos é um movimentado assentamento anão localizado a sudoeste de Altaforja, nos picos nevados de Dun Morogh. Serve como um entreposto de comércio e ponto de apoio vital para viajantes, mineradores e artesãos que percorrem os desfiladeiros montanhosos.",al={"onde fica kharanos","localização de kharanos","como encontrar kharanos"}},{q="O que é necessário para aprender este item de acampamento?",a="Os ferreiros precisam primeiro demonstrar proficiência básica em seu ofício antes que Tognus Flintfire os instrua na fabricação de equipamentos de acampamento. Depois de praticar os fundamentos em uma bigorna, ele ensinará você a forjar a roda portátil.",al={"requisito de camping 101: blacksmithing","quando aprender roda de afiar","treinamento de acampamento de ferraria"}},{q="Por que os ferreiros criam itens de acampamento?",a="Os itens de acampamento permitem que os ferreiros prestem suporte a grupos de aventureiros fora das cidades povoadas. Em vez de forçar os companheiros a retornar a uma forja completa da cidade para a manutenção básica de armas, um utilitário portátil como a roda de afiar oferece manutenção essencial sob o céu aberto.",al={"por que criar itens de acampamento","itens de acampamento de ferraria","utilidade da ferraria no ermo"}}},fp="26,170,35.181.0,22.211.0,24.162.0,27.161.0,59.157.0,18.177.0,44.137.0,39.202.0"}
P.entries["quest:96045"] = {n="Camping 101: Alchemy",s="Camping 101: Alchemy apresenta aos alquimistas iniciantes em Altaforja habilidades práticas de campo sob a orientação de Vosur Brakthel. Ao aprender a construir um Poço de Mana para seus acampamentos na natureza, os alquimistas podem fornecer um rejuvenescimento vital para conjuradores e curadores na estrada.",h="Camping 101: Alchemy apresenta aos alquimistas iniciantes em Altaforja habilidades práticas de campo sob a...",kw={"alquimia","fogueira básica","acampamento","camping 101: alchemy","altaforja","poço de mana","vosur brakthel"},ang={["faction:Alliance"]="Aspirantes a alquimista que visitam a fortaleza anã de Altaforja podem consultar Vosur Brakthel para aprender como aprimorar suas expedições com misturas restauradoras.",["profession:Cooking"]="Um acampamento adequado requer uma fogueira básica, uma habilidade prática ensinada por instrutores de culinária por todos os reinos para complementar as técnicas especializadas de acampamento."},sec={{t="Preparando Poções para a Estrada",b="Para os alquimistas que desbravam os confins indomados de Azeroth, preparar frascos em um laboratório tranquilo é apenas metade do ofício. Na grandiosa capital dos anões, Altaforja, o alquimista Vosur Brakthel ensina aos praticantes como adaptar seu delicado trabalho aos rigores da sobrevivência na selva. Ao demonstrar proficiência em alquimia, o aventureiro aprende a destilar seus conhecimentos na criação de um Poço de Mana — uma instalação portátil de acampamento projetada para sustentar companheiros em campo."},{t="Acampamentos na Natureza Selvagem",b="Embora o Poço de Mana proporcione um benefício revigorante para curadores e conjuradores exaustos, ele não pode ser colocado sozinho no meio de uma rua de paralelepípedos. Os habitantes da cidade não veem com bons olhos viajantes armando tendas dentro de centros urbanos, o que significa que tais estruturas devem ser levadas para a natureza. Além disso, nenhum acampamento está completo sem as brasas quentes de uma fogueira básica apropriada, levando os aspirantes a montadores de acampamento a buscar orientação com cozinheiros locais antes de partirem para a vida selvagem."}},faq={{q="Quem é Vosur Brakthel?",a="Vosur Brakthel é um instrutor de alquimia que reside na cidade montanhosa de Altaforja. Ele ensina novos alquimistas a aplicar seus conhecimentos de fabricação de poções na criação de um Poço de Mana para apoiar aventureiros em campo.",al={"quem ensina camping 101 alchemy","função de vosur brakthel","quem é vosur brakthel"}},{q="O que é um Poço de Mana?",a="Um Poço de Mana é uma instalação de acampamento desenvolvida por um alquimista para restaurar conjuradores e curadores. Quando colocado em um acampamento na natureza, ele oferece aos conjuradores uma bebida refrescante para restaurar suas energias místicas durante longas jornadas.",al={"o que faz um poço de mana","objetivo do poço de mana","por que criar um poço de mana"}},{q="É possível montar um acampamento dentro de Altaforja?",a="Os habitantes da cidade geralmente desaprovam a montagem de acampamentos nas ruas urbanas. Os alquimistas que desejam construir um acampamento e posicionar seu Poço de Mana devem viajar para além das muralhas da cidade, em direção à natureza selvagem.",al={"posso acampar em altaforja","acampar na cidade","onde colocar o poço de mana"}},{q="O que mais é necessário para montar um acampamento?",a="Todo acampamento requer uma fogueira básica como núcleo. Aventureiros que ainda não sabem como fazer fogo são aconselhados a procurar um instrutor de culinária para aprender as técnicas básicas de fogo culinário antes de partir.",al={"requisito de fogueira básica","preciso de culinária para acampar","como montar um acampamento"}},{q="Quando um alquimista pode aprender a criar um Poço de Mana?",a="Vosur Brakthel se disponibiliza a ensinar os alquimistas assim que eles adotam a profissão e demonstram certo nível de proficiência em seu ofício. Uma vez experientes o suficiente, os segredos para montar um Poço de Mana são revelados.",al={"quando posso aprender poço de mana","requisitos do poço de mana","requisitos de camping 101"}},{q="Quem mais se beneficia de um Poço de Mana no acampamento?",a="O Poço de Mana beneficia principalmente conjuradores e curadores, como magos, sacerdotes e druidas, que dependem fortemente da reposição de suas reservas de mana enquanto se aventuram longe das tavernas da cidade e das pedras de regresso.",al={"quem se beneficia do poço de mana","classes para poço de mana","quem usa poço de mana"}}},fp="20,167,20.280.0,20.267.0,22.140.0,20.117.0,39.118.0,37.108.0,48.152.0,43.146.0"}
P.entries["quest:96046"] = {n="Camping 101: Mining",s="Além das estradas vigiadas, mineradores aprendem a fazer uma pedra-ímã para um acampamento na natureza. O trabalho combina conhecimento de pedras com as técnicas para fazer fogo necessárias à vida ao ar livre.",h="Além das estradas vigiadas, mineradores aprendem a fazer uma pedra-ímã para um acampamento na natureza.",kw={"fogueira","acampamento","camping 101: mining","área de acampamento","culinária","pedra-ímã","mineração","natureza selvagem"},ang={["profession:Cooking"]="Como cozinheiro, você aprende com instrutores de culinária as técnicas para fazer fogo de que um acampamento precisa.",["profession:Mining"]="Como minerador, você aprende a moldar terra e minério para criar uma pedra-ímã que ancora um acampamento na natureza."},sec={{t="Habilidade de Campo para Mineradores",b="Além das estradas vigiadas, um minerador precisa confiar em seus conhecimentos de sobrevivência. O conhecimento de minerais dá a você os meios para moldar uma pedra-ímã, a âncora de um acampamento na natureza."},{t="Regras da Natureza",b="Um acampamento fica além dos limites da cidade, onde viajantes podem montar seus abrigos sem incomodar quem vive por ali. Escolha um lugar em meio à natureza. Um acampamento também precisa de uma fogueira para afastar o frio da noite. Aprender a fazer uma faz parte dos mesmos conhecimentos de sobrevivência usados para trabalhar com pedras."}},faq={{q="Para que serve uma pedra-ímã?",a="Uma pedra-ímã ancora um acampamento na natureza.",al={"propósito da pedra-ímã","para que serve a pedra-ímã","por que criar pedra-ímã"}},{q="Posso montar acampamento dentro de uma vila ou cidade?",a="Os moradores e as autoridades locais desaprovam tendas em praças e ruas públicas. Monte seu acampamento além dos limites da cidade.",al={"posso acampar na cidade","acampar na cidade","acampar dentro do assentamento"}},{q="O que é necessário antes de montar um acampamento?",a="Um acampamento precisa de uma fogueira acesa por perto.",al={"preciso de fogueira","como montar acampamento","pré-requisitos do acampamento"}},{q="Onde aprendo a criar uma fogueira?",a="Instrutores de culinária e cozinheiros de toda Azeroth ensinam as técnicas básicas para acender o fogo usadas na culinária.",al={"onde aprender fogueira","quem ensina fogueira","instrutor de fogueira"}},{q="Como a mineração se relaciona com a criação de uma pedra-ímã?",a="A mineração ensina você a trabalhar os minerais e as pedras necessários para fazer uma pedra-ímã.",al={"por que mineradores acampam","relação entre mineração e pedra-ímã","criar pedra-ímã"}},{q="Onde devo ir para testar meu novo acampamento?",a="Vá além dos portões da cidade, para a natureza aberta, onde você encontra espaço para acampar longe dos moradores.",al={"onde testar o acampamento","testando a pedra-ímã","acampar ao ar livre"}}},fp="19,163,21.153.0,17.270.0,29.49.0,40.120.0,42.40.0,41.98.0,48.77.0,38.103.0"}
P.entries["quest:96047"] = {n="Acampamento 101: Primeiros Socorros",s="Esta tarefa orienta médicos novatos em Dun Morogh a expandirem suas habilidades de sobrevivência além de simples bandagens. Ao procurarem Thamner Pol em Kharanos, os aventureiros aprendem a montar um Kit de Primeiros Socorros específico para manter os campistas vivos em campo.",h="Esta tarefa orienta médicos novatos em Dun Morogh a expandirem suas habilidades de sobrevivência além de...",kw={"bandagens","camping 101","dun morogh","primeiros socorros","kit de primeiros socorros","kharanos","sobrevivencia","thamner pol"},ang={["faction:Alliance"]="Recrutas da Aliança que treinam no coração congelado de Khaz Modan aprendem cedo que a autossuficiência e a medicina de campo são trunfos vitais para qualquer unidade militar ou de exploração.",["race:Dwarf"]="Montanhistas anões dependem fortemente de equipamentos robustos e práticos ao patrulhar as passagens nevadas e elevadas de Dun Morogh, tornando o kit de primeiros socorros de acampamento um item básico e essencial de sobrevivência.",["race:Gnome"]="Refugiados e andarilhos gnômicos operando a partir de Kharanos consideram a medicina de campo eficiente inestimável para sobreviver fora dos salões perdidos de Gnomeregan."},sec={{t="Cuidando de Ferimentos na Natureza",b="Aventureiros que desafiam as extensões congeladas de Dun Morogh logo descobrem que pedaços de linho e pontos rápidos são apenas o começo da medicina de sobrevivência. A verdadeira sobrevivência na natureza costuma depender de ter suprimentos estabelecidos em um local de descanso. Aqueles que mostram aptidão no tratamento básico são direcionados aos instrutores de ofício locais em Kharanos, que podem ensiná-los a transformar suprimentos médicos brutos em kits completos adaptados para a sobrevivência em acampamentos."},{t="As Lições de Kharanos",b="No movimentado vilarejo de Kharanos, Thamner Pol transmite técnicas práticas para equipar locais de expedição com suprimentos de emergência. Saber como construir um kit de campo adequado garante que um grupo inteiro possa enfaixar lacerações e recuperar o vigor em conjunto ao redor da fogueira antes de se aventurar novamente no frio cortante."}},faq={{q="Qual é o objetivo desta tarefa?",a="A tarefa guia médicos de campo recém-treinados até Thamner Pol em Kharanos, que os ensina a criar Kits de Primeiros Socorros funcionais projetados para acampamentos de aventureiros.",al={"por que fazer camping 101 primeiros socorros","o que esta missao faz","objetivo de camping 101"}},{q="Quem é Thamner Pol?",a="Thamner Pol é um instrutor localizado na cidade de Kharanos, em Dun Morogh. Ele ensina sobrevivencialistas habilidosos a criar equipamentos relacionados à profissão para aprimorar seus acampamentos na natureza.",al={"quem e thamner pol","localizacao de thamner pol","onde fica thamner pol"}},{q="Onde ocorre este treinamento?",a="O treinamento ocorre em Kharanos, o principal assentamento situado na região central de Dun Morogh, ao sul de Altaforja.",al={"para onde vou","localizacao de camping 101","primeiros socorros em kharanos"}},{q="Por que um kit de primeiros socorros de acampamento é importante?",a="Ferimentos são comuns durante expedições em regiões selvagens implacáveis. Um Kit de Primeiros Socorros dedicado fornece aos aventureiros em repouso recursos de cura essenciais, permitindo que os viajantes cuidem de feridas e se recuperem em segurança entre as batalhas.",al={"o que faz o kit de primeiros socorros","por que criar um kit de primeiros socorros","utilidade dos primeiros socorros de acampamento"}},{q="É necessário ter treinamento médico prévio antes de procurar Thamner Pol?",a="Sim. Espera-se que os aventureiros já conheçam o básico de Primeiros Socorros e demonstrem competência inicial no ofício antes que Thamner Pol lhes ensine receitas avançadas de acampamento.",al={"requisitos para camping 101","pericia de primeiros socorros necessaria","preciso de primeiros socorros antes"}},{q="Essa busca está aberta a qualquer aventureiro?",a="Qualquer aventureiro pode aprender Primeiros Socorros, independentemente de sua vocação, tornando a medicina de acampamento uma habilidade pragmática para todos os viajantes que percorrem Dun Morogh.",al={"qualquer um pode fazer isso","requisitos de classe","quem pode aprender primeiros socorros de acampamento"}}},fp="22,147,26.230.0,23.212.0,33.112.0,19.85.0,36.100.0,38.110.0,62.130.0,39.113.0"}
P.entries["quest:96050"] = {n="Camping 101: Fishing",s="Camping 101: Fishing orienta os amantes da vida ao ar livre nos ofícios essenciais e na etiqueta de sobrevivência na natureza selvagem. Ensina os aventureiros a criar um Aquário decorativo para seu acampamento e enfatiza a necessidade de aprender a arte da fogueira com um instrutor de culinária antes de partir para a natureza.",h="Camping 101: Fishing orienta os amantes da vida ao ar livre nos ofícios essenciais e na etiqueta de...",kw={"acampamento","fogueira","acampar","culinária","aquário","pesca","natureza selvagem"},ang={["profession:Cooking"]="Aprender o básico de culinária é essencial para montar um acampamento, pois os instrutores culinários ensinam os viajantes a construir a fogueira necessária."},sec={{t="Etiqueta na Natureza Selvagem",b="A vida na estrada por toda Azeroth exige conhecimento prático da fronteira. Para aspirantes a pescadores e viajantes, montar um local organizado requer a compreensão da etiqueta básica ao ar livre. Os habitantes e guardas das cidades desaprovam viajantes armando tendas e espalhando equipamentos no centro dos povoados; portanto, quem desejar descansar deve levar seus suprimentos para além dos limites da cidade e adentrar a natureza selvagem aberta."},{t="Os Confortos do Acampamento",b="Um local de expedição adequado exige várias comodidades essenciais. Acima de tudo, nenhum acampamento é considerado funcional sem uma fogueira aconchegante, uma habilidade tradicionalmente ensinada por instrutores culinários. Uma vez aceso o fogo, viajantes experientes podem dispor apetrechos especiais, como um Aquário artesanal, transformando um simples ponto de descanso em um refúgio de pescador totalmente equipado."}},faq={{q="O que você aprende em Camping 101: Fishing?",a="Esta lição ensina os aventureiros a criar um Aquário para mobiliar seu acampamento. Ela cobre os fundamentos da montagem de um refúgio na natureza selvagem, adequado para pescar e relaxar longe de povoados civilizados.",al={"o que esta missão ensina","criar aquário","recompensa de camping fishing"}},{q="Onde você pode montar um acampamento?",a="Acampamentos não podem ser montados no meio da cidade, pois os moradores locais se incomodam com viajantes se espalhando pelas vias públicas. Você deve se aventurar pela natureza selvagem para montar seu local.",al={"onde montar acampamento","posso acampar na cidade","regras de local de acampamento"}},{q="Do que você precisa antes de montar um acampamento?",a="Nenhum acampamento na natureza selvagem é considerado completo sem uma fogueira. Antes de começar a armar seu acampamento, você deve ter uma fogueira pronta para servir de base ao local e fornecer calor.",al={"como começar acampamento","preciso de uma fogueira","requisitos de acampamento"}},{q="Como você aprende a fazer uma fogueira?",a="Instrutores culinários e treinadores de culinária ensinam a arte básica de acender uma fogueira. Aqueles que ainda não aprenderam o básico de culinária devem procurar um cozinheiro para aprender a fazer uma.",al={"como fazer fogueira","onde aprender fogueira","quem ensina fogo"}},{q="Qual é a finalidade do Aquário?",a="O Aquário é uma adição decorativa criada para um acampamento ao ar livre, proporcionando um toque apropriado para qualquer pescador viajante que deseje montar um posto avançado à beira d'água.",al={"para que serve o aquário","uso de aquário em acampamento","história do aquário"}},{q="Por que lições de acampamento são ensinadas aos aventureiros?",a="Mentores da natureza selvagem oferecem orientações práticas sobre a vida na fronteira, garantindo que os andarilhos saibam como se sustentar adequadamente, acender fogueiras e respeitar os limites dos povoados antes de partir para a natureza.",al={"quem oferece camping 101","por que lições de acampamento","guia de sobrevivência em acampamento"}}},fp="20,140,20.280.0,20.210.0,44.111.0,28.126.0,40.70.0,37.126.0,37.85.0,46.142.0"}
P.entries["quest:96055"] = {n="Camping 101: Herbalism",s="Camping 101: Herbalism direciona herboristas promissores a Reyna Stonebranch em Altaforja para expandir seu ofício prático. Os coletores aprendem a combinar ervas selvagens em calmantes Velas de Incenso para a vida no acampamento. Essas criações aromáticas de campo elevam o ânimo e ajudam conjuradores durante expedições exigentes pela natureza selvagem.",h="Camping 101: Herbalism direciona herboristas promissores a Reyna Stonebranch em Altaforja para expandir seu...",kw={"acampamento","camping 101","herborismo","ervas","vela de incenso","altaforja","reyna stonebranch"},ang={["faction:Alliance"]="Herboristas da Aliança são direcionados à cidade anã de Altaforja para procurar Reyna Stonebranch e receber instrução em habilidades especializadas de campo.",["profession:Herbalism"]="Coletores que aprimoram seu ofício floral podem criar Velas de Incenso, transformando ervas selvagens colhidas em auxílios aromáticos de acampamento para aliados conjuradores.",["race:Dwarf"]="O conhecimento para criar esses auxílios herbais de acampamento está em Altaforja com a instrutora de herborismo Reyna Stonebranch."},sec={{t="Botânica Prática de Campo",b="Coletar ervas pela natureza selvagem vai muito além de simplesmente colher flores. Botânicos habilidosos descobrem que a flora colhida pode ser voltada para a sobrevivência prática ao ar livre, fornecendo aos grupos de viagem artesanatos valiosos para o acampamento. Para coletores que buscam expandir sua utilidade além da colheita básica de reagentes, aprender técnicas especializadas na natureza transforma plantas silvestres em itens essenciais de suporte."},{t="Aromáticos para o Lar",b="Herboristas proficientes são orientados a procurar Reyna Stonebranch na cidade montanhosa de Altaforja. Ao comprovarem sua capacidade no ofício, os herboristas podem aprender a moldar uma Vela de Incenso. Essas velas aromáticas trazem um alívio bem-vindo aos acampamentos, elevando o ânimo dos companheiros de viagem e proporcionando um ambiente tranquilo que conjuradores e curadores apreciam especialmente durante longas expedições."}},faq={{q="O que é Camping 101: Herbalism?",a="Camping 101: Herbalism é uma diretriz instrutiva que orienta coletores habilidosos a aprenderem como aplicar seu ofício botânico na sobrevivência ao ar livre e em acampamentos na natureza.",al={"o que é camping 101 herbalism","missão de acampamento de herborismo","guia de acampamento de herborismo"}},{q="Quem é Reyna Stonebranch?",a="Reyna Stonebranch é uma instrutora de herborismo situada na grande cidade anã de Altaforja que ensina herboristas proficientes a criar itens de acampamento.",al={"quem ensina vela de incenso","onde fica reyna stonebranch","localização de reyna stonebranch"}},{q="O que faz uma Vela de Incenso?",a="Uma Vela de Incenso é um item aromático de acampamento criado por herboristas que eleva o ânimo no acampamento, oferecendo um reforço revigorante especialmente apreciado por curadores e conjuradores.",al={"o que faz a vela de incenso","acampamento com vela de incenso","objetivo da vela de incenso"}},{q="Por que as Velas de Incenso são úteis para conjuradores?",a="O ânimo elevado ajuda a manter o vigor, tornando o aroma calmante de uma Vela de Incenso particularmente benéfico para curadores e usuários de magia que se recuperam entre viagens.",al={"quem se beneficia da vela de incenso","vela de incenso é para conjuradores"}},{q="Para onde os herboristas devem viajar para receber essa instrução?",a="A missão instrui os herboristas a viajar para Altaforja, em Khaz Modan, para se encontrar com Reyna Stonebranch assim que demonstrarem proficiência adequada na colheita.",al={"onde ir para acampamento de herborismo","qual cidade para camping 101 herbalism"}},{q="O que é necessário antes de aprender a criar a vela?",a="Os herboristas devem demonstrar proficiência e habilidade prática suficientes na coleta de ervas antes que Reyna Stonebranch ensine as técnicas para criar incensos de acampamento.",al={"quando posso aprender vela de incenso","requisito de acampamento de herborismo"}}},fp="22,167,22.148.0,24.263.0,31.111.0,25.98.0,31.85.0,47.94.0,50.102.0,53.115.0"}
P.entries["quest:96056"] = {n="Camping 101: Skinning",s="Em Altaforja, esfoladores habilidosos aprendem a fazer uma Cadeira de Acampamento com peles de animais. Balthus Stoneflayer ensina o ofício depois que eles comprovam sua habilidade.",h="Em Altaforja, esfoladores habilidosos aprendem a fazer uma Cadeira de Acampamento com peles de animais.",kw={"balthus stoneflayer","cadeira de acampamento","acampamento","camping 101: skinning","pelegos","altaforja","esfolamento"},ang={["class:Hunter"]="Como caçador, você pode esfolar suas presas na natureza e fazer uma Cadeira de Acampamento para descansar entre longos rastreamentos.",["faction:Alliance"]="Seu caminho para fazer uma Cadeira de Acampamento leva a Altaforja, a cidade dos anões nas montanhas e capital da Aliança.",["race:Dwarf"]="Como anão, você pode encontrar Balthus Stoneflayer em Altaforja e aprender como esfoladores habilidosos transformam peles em confortos para o acampamento."},sec={{t="Coletando na Natureza",b="Esfolar feras abatidas fornece couro para fabricantes de armaduras e artesãos trabalharem. Peles de felinos, ursos e outras feras também têm utilidade em campo. Você recebe a tarefa de transformar esses materiais em algo útil no acampamento em vez de vendê-los."},{t="O Artesão de Altaforja",b="Balthus Stoneflayer ensina esfoladores em Altaforja a fazer uma Cadeira de Acampamento com peles preparadas. Primeiro, você precisa mostrar a ele que sabe esfolar feras. Só então ele compartilhará seus métodos de fabricação."},{t="Descanso e Prontidão",b="Uma Cadeira de Acampamento oferece um lugar para você se sentar junto à fogueira e relaxar durante suas viagens. Descanse ali, e você poderá enfrentar o próximo perigo com os sentidos aguçados e as forças restauradas."}},faq={{q="O que é Camping 101: Skinning?",a="Esfoladores habilidosos vão a Altaforja para aprender a fazer uma Cadeira de Acampamento com peles de animais.",al={"o que é camping 101 skinning","objetivo da missão","missão camping 101 skinning"}},{q="Quem ensina você a criar o item de acampamento?",a="Balthus Stoneflayer ensina você a fazer uma Cadeira de Acampamento em Altaforja. Primeiro, mostre a ele que você sabe esfolar feras.",al={"com quem falar","quem ensina cadeira de acampamento","quem é balthus stoneflayer"}},{q="Onde você precisa ir para concluir esta missão?",a="Vá a Altaforja, a capital dos anões nos picos nevados de Dun Morogh. Balthus Stoneflayer ensina os esfoladores que comprovam sua habilidade por lá.",al={"para onde ir","localização de balthus","instrutor de altaforja"}},{q="Que item os esfoladores aprendem a criar para o seu acampamento?",a="Você aprende a fazer uma Cadeira de Acampamento com peles de animais, garantindo um lugar para descansar em campo entre um perigo e outro.",al={"o que você cria","utilidade da cadeira de acampamento","criação de acampamento de esfolamento"}},{q="Por que criar uma cadeira de acampamento é útil para um aventureiro?",a="Uma Cadeira de Acampamento oferece um lugar para descansar em longas jornadas por terras selvagens e recuperar a concentração antes que o perigo encontre você.",al={"por que criar uma cadeira","o que a cadeira de acampamento faz","benefício da cadeira de acampamento"}},{q="Que proficiência é necessária antes que Balthus ensine você?",a="Balthus Stoneflayer ensina você depois que você comprova sua habilidade em esfolar feras.",al={"requisitos","quando posso aprender","proficiência necessária"}}},fp="21,144,20.234.0,24.194.0,18.173.0,30.85.0,42.103.0,47.136.0,52.106.0,54.111.0,59.78.0"}
P.entries["quest:96057"] = {n="Camping 101: Tailoring",s="Um alfaiate pode aprender com Uthrar Threx em Altaforja a fazer um Rallying Banner para um acampamento. O estandarte serve para elevar o moral, e é preciso uma fogueira para iniciar um acampamento.",h="Um alfaiate pode aprender com Uthrar Threx em Altaforja a fazer um Rallying Banner para um acampamento.",kw={"acampamento","fogueira","acampamento para iniciantes","altaforja","moral","rallying banner","alfaiataria","uthrar threx"},ang={["profession:Cooking"]="Um cozinheiro pode ensinar você a fazer a fogueira necessária antes de montar acampamento.",["profession:Tailoring"]="Como alfaiate, você pode aprender a fazer um Rallying Banner para seu acampamento depois que demonstrar proficiência em sua habilidade."},sec={{t="Um estandarte para o acampamento",b="Um instrutor em Altaforja pode ensinar você a fazer um estandarte para seu acampamento depois que você demonstrar sua habilidade em alfaiataria. O estandarte se chama Rallying Banner. Ele pode ajudar a manter sua energia, e você precisará de uma fogueira antes de montar acampamento."}},faq={{q="Quem ensina alfaiataria para acampar?",a="Uthrar Threx em Altaforja pode ensinar você a confeccionar um item de acampamento depois que você demonstrar proficiência em alfaiataria.",al={"quem ensina isso","instrutor de alfaiataria","uthrar threx"}},{q="O que posso fazer com alfaiataria?",a="Você pode aprender a confeccionar um Rallying Banner para seu acampamento.",al={"item de acampamento de alfaiataria","qual estandarte","confeccionar estandarte"}},{q="O que o Rallying Banner faz?",a="Um estandarte inspirador pode ajudar a manter sua energia, e o moral é importante para o sucesso no campo de batalha.",al={"função do estandarte","por que usar estandarte","estandarte de mobilização"}},{q="Do que preciso antes de iniciar um acampamento?",a="Você precisa de uma fogueira antes de montar acampamento. Um cozinheiro pode ensinar você a fazer uma.",al={"fogueira necessária","como iniciar acampamento","requisitos para acampar"}}},fp="22,172,17.238.0,34.109.0,31.55.0,33.105.0,38.77.0"}
P.entries["quest:96058"] = {n="Camping 101: Engineering",s="Um engenheiro em Kharanos pode aprender a fabricar um Reagent Bot para um acampamento. O robô ajuda a manter seu estoque de materiais para feitiços.",h="Um engenheiro em Kharanos pode aprender a fabricar um Reagent Bot para um acampamento.",kw={"bronk guzzlegear","acampamento","fogueira","camping 101","engenharia","kharanos","reagent bot","materiais para feitiços"},ang={["profession:Cooking"]="Como cozinheiro, você pode ensinar outras pessoas a fazer a fogueira necessária para um acampamento.",["profession:Engineering"]="Como engenheiro, você pode aprender com Bronk Guzzlegear a fabricar um Reagent Bot para seu acampamento."},sec={{t="Suprimentos do acampamento",b="Um engenheiro pode aprender com Bronk Guzzlegear em Kharanos a fabricar um Reagent Bot. Você precisa demonstrar proficiência em engenharia antes que ele ensine você. O robô ajuda a fornecer os materiais de que você e seus aliados precisam para lançar feitiços."},{t="Pronto para os ermos",b="Agora você pode fabricar um Reagent Bot. Para testá-lo, saia da cidade e siga para os ermos, onde você pode montar acampamento. Leve também uma fogueira; cozinheiros podem ensinar você a fazer uma."}},faq={{q="Quem me ensina a fabricar um Reagent Bot?",a="Bronk Guzzlegear em Kharanos pode ensinar você a fabricar um Reagent Bot depois que você demonstrar proficiência em engenharia.",al={"aula de robô com bronk","quem é bronk guzzlegear","instrutor de reagent bot"}},{q="O que um Reagent Bot faz?",a="Um Reagent Bot ajuda a manter você e seus aliados abastecidos com os materiais necessários para lançar feitiços.",al={"para que serve reagent bot","robô suprimentos para feitiços","robô de acampamento"}},{q="Do que preciso antes de aprender isso?",a="Você precisa demonstrar proficiência em engenharia antes que Bronk Guzzlegear ensine você a fabricar um Reagent Bot.",al={"proficiência em engenharia","como aprender reagent bot","camping 101 engenharia"}},{q="Onde posso testar o Reagent Bot?",a="Você pode testar o Reagent Bot nos ermos, já que a maioria das pessoas não quer acampamentos montados no centro da cidade.",al={"onde testar robô","local de acampamento","reagent bot nos ermos"}},{q="Preciso de uma fogueira?",a="Sim. Um acampamento precisa de uma fogueira, e a maioria dos cozinheiros pode ensinar você a fazer uma.",al={"fogueira necessária","como fazer fogueira","culinária de acampamento"}}},fp="24,127,17.233.0,19.175.1,37.107.0,27.87.0,39.114.0,36.111.0,21.71.0"}
P.entries["quest:96059"] = {n="Camping 101: Enchanting",s="Um encantador em Altaforja pode aprender a criar um Alaúde Encantado para acampar após demonstrar habilidade. Sua magia oferece entretenimento durante as pausas na trilha.",h="Um encantador em Altaforja pode aprender a criar um Alaúde Encantado para acampar após demonstrar habilidade.",kw={"item de acampamento","noções básicas de acampamento","alaúde encantado","encantamento","altaforja","thonys pillarstone"},ang={["profession:Engineering"]="Como encantador, você pode aprender com Thonys Pillarstone a criar um Alaúde Encantado para acampar depois de demonstrar proficiência na sua habilidade."},sec={{t="Um alaúde para acampar",b="Sua próxima lição trata de uma melodia para a trilha. Em Altaforja, Thonys Pillarstone pode ensinar você a criar um Alaúde Encantado depois que você demonstrar proficiência em encantamento. A magia oferece uma forma de se entreter durante as pausas antes de pegar a estrada novamente."}},faq={{q="Quem pode me ensinar a criar um Alaúde Encantado?",a="Thonys Pillarstone, em Altaforja, pode ensinar você a criar um Alaúde Encantado depois que você demonstrar proficiência em encantamento.",al={"thonys pillarstone","quem ensina item de acampamento de encantamento"}},{q="Para que serve o Alaúde Encantado?",a="O Alaúde Encantado é um item de acampamento feito para proporcionar entretenimento durante as pausas.",al={"utilidade do alaúde","alaúde encantado acampamento"}},{q="Por que preciso de habilidade em encantamento?",a="Você pode aprender a criar o item de acampamento depois de demonstrar proficiência em encantamento.",al={"proficiência em encantamento","como aprender a criar alaúde"}}},fp="23,149,15.267.0,43.114.0,31.84.0,31.86.0"}
P.entries["quest:96063"] = {n="Gaseous Gold",s="Sleebo Fizzlespout quer gás do pântano das lagoas a sudoeste daqui. Ele espera usá-lo para abastecer um novo motor.",h="Sleebo Fizzlespout quer gás do pântano das lagoas a sudoeste daqui.",kw={"motor","frascos de gás","ouro gasoso","indústria","gás do pântano","ciência","sleebo fizzlespout","fendas"},sec={{t="Um novo combustível",b="Sleebo Fizzlespout vê gás subindo de fendas perto da água nas lagoas pantanosas a sudoeste. Ele está desenvolvendo um motor movido a gás e pede que você reúna frascos de gás do pântano. O trabalho pode ajudar a colocar esse combustível em uso na ciência e na indústria."}},faq={{q="Quem está pedindo gás do pântano?",a="Sleebo Fizzlespout pede que você reúna frascos de gás do pântano para ele.",al={"quem quer gás","sleebo fizzlespout"}},{q="Por que Sleebo quer o gás?",a="Sleebo está desenvolvendo um novo tipo de motor movido a gás do pântano.",al={"para que serve o gás","motor a gás"}},{q="De onde vem o gás do pântano?",a="O gás sobe de fendas perto da água em lagoas pantanosas a sudoeste de Sleebo.",al={"onde fica o gás","fendas de gás"}},{q="Para que serve o gás do pântano?",a="Sleebo espera usar o gás do pântano como combustível para seu novo motor.",al={"utilidade do gás do pântano","combustível a gás"}}},fp="12,109,10.260.0,28.62.0,29.65.0,35.76.0,27.57.0"}
P.entries["quest:96067"] = {n="Rock 'em and Sock 'em",s="Sleebo pede que você teste G45-B4G, seu protótipo de motor a gás. O teste vai ajudá-lo a decidir o que consertar e alterar.",h="Sleebo pede que você teste G45-B4G, seu protótipo de motor a gás.",kw={"g45-b4g","gás","motor a gás","companheiro mecânico","protótipo","sleebo","teste de resistência"},sec={{t="Um teste mecânico",b="Sleebo tem um protótipo funcional de seu motor a gás, guardado no baú de estopa de G45-B4G. Ele pode abastecer o companheiro mecânico com o gás que você coletou. Você deve testar a máquina em uma luta para que Sleebo veja seu desempenho."},{t="As anotações de Sleebo",b="Depois do teste, Sleebo fica satisfeito com o espetáculo e com as anotações que reuniu. Ele planeja consertar G45-B4G e ajustar o motor antes do próximo teste."}},faq={{q="Quem é G45-B4G?",a="G45-B4G é o companheiro mecânico de Sleebo e guarda o protótipo funcional de seu motor a gás em um baú de estopa.",al={"g45-b4g","quem é g45","companheiro mecânico"}},{q="O que Sleebo quer que seja testado?",a="Sleebo quer que você teste G45-B4G, o protótipo funcional de seu motor a gás, em uma luta.",al={"teste de sleebo","testar o motor","o que estou testando"}},{q="O que abastece G45-B4G?",a="Sleebo pode abastecer G45-B4G com o gás que você coletou.",al={"robô a gás","combustível do motor","o que abastece g45"}},{q="G45-B4G sente dor?",a="Não. Sleebo diz que G45-B4G não consegue sentir nada.",al={"g45 sente dor","machucar a máquina","dor de robô"}},{q="Por que Sleebo está testando sua invenção?",a="Sleebo quer testar os limites do protótipo de motor a gás e reunir anotações sobre seu desempenho.",al={"por que testar g45","teste de resistência do motor","invenção de sleebo"}}},fp="21,121,18.240.0,14.150.1,15.118.0,29.94.0,20.53.0,22.45.0,36.97.0"}
P.entries["quest:96078"] = {n="A Tale Spun Around the Fire",s="Kin'weelay pede que você leve as inscrições da tabuleta ao Mestre Gadrin, na Aldeia Sen'jin. Os Lançanegra preservam tradições por meio de histórias, e Gadrin quer ouvir este conto.",h="Kin'weelay pede que você leve as inscrições da tabuleta ao Mestre Gadrin, na Aldeia Sen'jin.",kw={"lançanegra","gurubashi","i'lalai","kin'weelay","mestre gadrin","histórias contadas oralmente","aldeia sen'jin","inscrições da tabuleta"},ang={["race:Troll"]="Como troll, você leva ao Mestre Gadrin um conto sobre a tradição dos Lançanegra. Ele valoriza a preservação e a descoberta do legado ancestral."},sec={{t="Um Conto Compartilhado",b="Kin'weelay preparou outra cópia do conto caso a sua se perca. As histórias dos Lançanegra transmitem lendas aos jovens, ensinando lições e alertas por meio de palavras ditas em voz alta. Leve as inscrições ao Mestre Gadrin, líder espiritual dos Lançanegra na Aldeia Sen'jin, para que ele ouça o conto."},{t="Os Agradecimentos de Gadrin",b="Depois que você explica como as inscrições da tabuleta I'lalai chegaram às suas mãos, o Mestre Gadrin escuta com atenção. Ele fica contente por Kin'weelay se importar em preservar e revelar o legado dos Lançanegra, perdido ao longo dos séculos. Gadrin observa que os Lançanegra se separaram dos Gurubashi há pouco tempo, considerando a longa história, e então lhe entrega algo que Kin'weelay pediu que ele passasse como agradecimento."}},faq={{q="Quem quer as inscrições?",a="Kin'weelay pede que você leve as inscrições da tabuleta ao Mestre Gadrin, na Aldeia Sen'jin.",al={"quem me enviou","conto de kin'weelay","kin'weelay"}},{q="Por que levá-las ao Mestre Gadrin?",a="O Mestre Gadrin é o líder espiritual dos Lançanegra, e Kin'weelay diz que ele vai querer ouvir o conto.",al={"por que gadrin","para onde vão as inscrições","inscrições da tabuleta"}},{q="Como os Lançanegra preservam as tradições?",a="Os Lançanegra transmitem lendas à próxima geração por meio de histórias contadas oralmente, ensinando lições e contos de advertência.",al={"histórias dos lançanegra","tradição oral","contos de trolls"}},{q="De onde são as inscrições?",a="São inscrições da tabuleta I'lalai.",al={"tabuleta il'alai","i'lalai","história da tabuleta"}},{q="Onde fica o Mestre Gadrin?",a="O Mestre Gadrin fica na Aldeia Sen'jin, em Durotar.",al={"localização de gadrin","aldeia sen'jin","onde fica gadrin"}}},fp="27,168,13.283.0,15.381.1,23.84.0,31.99.0,41.115.0,27.42.0,23.47.0"}
P.entries["quest:96081"] = {n="Wound Dressings",s="O irmão Lowley, na Bastilha de Ermoforte, precisa de tecido para fazer bandagens. Farholde não tem um meio constante de produzir tecido, e o estoque está acabando.",h="O irmão Lowley, na Bastilha de Ermoforte, precisa de tecido para fazer bandagens.",kw={"bandagens","irmão lowley","tecido","farholde","bastilha de ermoforte","goblins","mageweave cloth","orcs"},sec={{t="Pouco tecido",b="Na Bastilha de Ermoforte, o irmão Lowley pede sua ajuda, pois o tecido de qualidade está escasso. A bastilha depende de importações dos goblins ou de tecidos tomados dos orcs. Sem mais tecido, Lowley talvez precise fazer bandagens com camisas velhas, enquanto as tropas precisam delas para salvar vidas."}},faq={{q="Por que o irmão Lowley precisa de tecido?",a="Farholde precisa de tecido para fazer bandagens, e seu estoque de tecido de qualidade está acabando.",al={"por que tecido","bandagens de lowley","precisa de tecido"}},{q="Por que Farholde não consegue produzir o próprio tecido?",a="Farholde não tem um meio confiável de fabricar tecido, então depende de importações dos goblins ou de tecidos tomados dos orcs.",al={"estoque de tecido de farholde","não produz tecido","de onde vem o tecido"}},{q="O que acontece se o tecido acabar?",a="O irmão Lowley talvez precise fazer bandagens com camisas velhas.",al={"sem bandagens","camisas velhas","falta de tecido"}},{q="Quem pede o tecido?",a="O irmão Lowley, na Bastilha de Ermoforte, pede que você reúna Mageweave Cloth.",al={"quem precisa de tecido","irmão lowley","pedido de tecido"}}},fp="15,130,14.261.0,35.86.0,38.114.0,35.57.0,23.67.0"}
P.entries["quest:96101"] = {n="The Great Outdoors",s="The Great Outdoors é uma missão introdutória oferecida pelo homem do campo Raan, que ensina a aventureiros novatos os fundamentos da sobrevivência na natureza selvagem. Ao descansar ao lado de uma fogueira básica para obter Boosted Rest, os andarilhos aprendem técnicas essenciais de acampamento antes de se aventurarem em direção aos instrutores de profissão próximos para aprender profissões práticas.",h="The Great Outdoors é uma missão introdutória oferecida pelo homem do campo Raan, que ensina a aventureiros...",kw={"fogueira básica","boosted rest","estrutura de acampamento","fogueira","raan","the great outdoors","perícia profissional","sobrevivência na selva"},ang={["class:Hunter"]="A sobrevivência na natureza selvagem começa com os fundamentos das técnicas de acampamento, uma disciplina essencial para rastreadores e patrulheiros acostumados a viver sob céu aberto.",["profession:Cooking"]="Reunir-se ao redor de uma fogueira básica para descansar e se recuperar é natural para cozinheiros de acampamento, que dependem do fogo aberto para sustentar grupos viajantes na natureza selvagem."},sec={{t="Lições na Natureza Selvagem",b="The Great Outdoors serve como uma lição introdutória sobre como sobreviver além da segurança dos muros dos assentamentos. Oferecida por um viajante experiente da natureza selvagem chamado Raan, a tarefa lembra aos aventureiros errantes que a ambição bruta e o aço são inúteis sem as técnicas práticas de acampamento necessárias para suportar intempéries severas. Raan dá as boas-vindas aos aspirantes a andarilhos nas fileiras das almas inquietas que buscam fortuna e glória, oferecendo orientação prática àqueles dispostos a aprender."},{t="O Calor do Lar",b="O requisito principal da lição é enganosamente simples: sentar-se ao lado da fogueira básica de Raan até que o calor conceda o efeito Boosted Rest. Lá fora, nos vastos e indomados territórios de Azeroth, saber como fazer uma pausa, montar acampamento e se recuperar pode significar a diferença entre a vida e a morte. Uma vez dominados os fundamentos do acampamento, Raan direciona os novatos aos instrutores do vilarejo local para adotar um ofício e aprender a criar estruturas de acampamento especializadas."}},faq={{q="Quem dá a missão The Great Outdoors?",a="A missão é oferecida por Raan, um viajante experiente que reconhece o potencial de aventureiros errantes e lhes ensina os fundamentos de sobreviver na natureza aberta.",al={"quem oferece the great outdoors","quem dá a missão the great outdoors","missão da fogueira de raan"}},{q="Qual é o objetivo de The Great Outdoors?",a="Ela apresenta aos aventureiros os fundamentos de sobrevivência na natureza selvagem, demonstrando como descansar ao lado de uma fogueira básica proporciona conforto, recuperação e o descanso reforçado necessário antes de empreender jornadas perigosas.",al={"o que the great outdoors ensina","objetivo de the great outdoors","o que aprendo com raan"}},{q="Como a missão é concluída?",a="Para concluir a lição, sente-se ao lado da fogueira básica de Raan e descanse ali até receber o bônus de Boosted Rest, mostrando que você compreende como se restabelecer em campo.",al={"como concluir the great outdoors","objetivo da fogueira de raan","objetivo de boosted rest"}},{q="O que Raan sugere fazer após concluir a missão?",a="Ao terminar a lição na fogueira, Raan incentiva você a visitar instrutores no vilarejo próximo para aprender uma profissão, ressaltando que artesãos podem criar estruturas de acampamento adaptadas ao seu ofício.",al={"o que raan aconselha a seguir","para onde ir depois de the great outdoors","depois de concluir the great outdoors"}},{q="O que é Boosted Rest?",a="Boosted Rest é o efeito restaurador obtido ao fazer uma pausa ao lado de uma fogueira estabelecida, concedendo aos aventureiros viajantes uma recuperação aprimorada enquanto enfrentam os elementos.",al={"o que é boosted rest","bônus de boosted rest da fogueira"}},{q="As profissões permitem que aventureiros criem estruturas de acampamento?",a="Sim, instrutores locais de profissão podem ensinar artesãos a criar estruturas de acampamento funcionais apropriadas para o ofício escolhido, permitindo que viajantes mantenham acampamentos especializados ao ar livre.",al={"profissões podem criar fogueiras","estruturas de acampamento de profissão","itens de profissão para acampamento"}}},fp="18,180,19.275.0,24.350.0,39.99.0,42.116.0,27.70.0,56.166.0,21.141.0,60.144.0"}
P.entries["quest:96102"] = {n="Camping 101: Tailoring",s="O treinamento de Alfaiataria ensina você a fazer um Estandarte de Reunião. Para testá-lo, você precisa de um acampamento na natureza e de uma fogueira.",h="O treinamento de Alfaiataria ensina você a fazer um Estandarte de Reunião.",kw={"fogueira","acampamento","culinária","estandarte de reunião","alfaiataria","natureza"},ang={["profession:Cooking"]="Como cozinheiro, você pode ensinar outras pessoas a fazer uma fogueira.",["profession:Tailoring"]="Como alfaiate, você pode fabricar um Estandarte de Reunião para seu acampamento."},sec={{t="Primeiro, uma fogueira",b="Agora você pode fabricar seu próprio Estandarte de Reunião, mas a nota de conclusão diz para testá-lo na natureza, e não na cidade. Um acampamento também precisa de uma fogueira antes de ser montado. A maioria dos cozinheiros pode ensinar você a fazer uma, então um instrutor de Culinária pode ensinar o básico caso você ainda não tenha aprendido."}},faq={{q="O que posso fabricar depois disso?",a="Você pode fabricar seu próprio Estandarte de Reunião.",al={"o que fabricar","receita de estandarte","estandarte de alfaiataria"}},{q="Onde devo testar o estandarte?",a="Vá para a natureza para testar seu Estandarte de Reunião; a nota de conclusão diz que, em geral, os habitantes não gostam de acampamentos no centro da cidade.",al={"onde testar","onde acampar","testar estandarte"}},{q="Do que um acampamento precisa?",a="Um acampamento precisa de uma fogueira antes de ser montado.",al={"do que o acampamento precisa","precisa de fogueira","noções básicas de acampamento"}},{q="Quem pode me ensinar a fazer uma fogueira?",a="A maioria dos cozinheiros pode ensinar você a fazer uma fogueira. Um instrutor de Culinária pode ensinar o básico.",al={"instrutor de fogueira","quem ensina a fazer fogo","fogueira de culinária"}}},fp="22,119,16.287.0,27.39.0,31.144.0,22.45.0,36.84.0"}
P.entries["quest:96103"] = {n="A Feast for Buzzards",s="Um esqueleto castigado nas planícies traz marcas que podem revelar a um caçador o que aconteceu. Você leva o crânio a Neza Bloodsnout em Rog'mar para que ela o examine.",h="Um esqueleto castigado nas planícies traz marcas que podem revelar a um caçador o que aconteceu.",kw={"um banquete para abutres","marcas de garras","crânio roído","neza bloodsnout","rog'mar","esqueleto","marcas de dentes"},sec={{t="Um Crânio nas Planícies",b="Os ossos jazem castigados sob o sol, com formas que lembram dentes e garras marcadas em sua superfície pálida. Os danos não revelam quem foi a vítima. Você leva o crânio a Neza Bloodsnout em Rog'mar, onde uma caçadora pode interpretar as marcas."}},faq={{q="O que aconteceu com o esqueleto?",a="Seus membros têm marcas que lembram dentes e garras, mas não está claro quem o atacou.",al={"esqueleto nas planícies","o que o matou"}},{q="Por que levar o crânio a Neza?",a="Neza é uma caçadora em Rog'mar que talvez reconheça o significado das marcas.",al={"por que levar o crânio a neza","neza bloodsnout"}},{q="Quem foi a vítima?",a="O esqueleto está muito danificado, e sua identidade é desconhecida até Neza examinar o crânio.",al={"de quem é o esqueleto","quem é a pessoa morta"}},{q="Onde fica Neza Bloodsnout?",a="Neza Bloodsnout fica em Rog'mar.",al={"localização de neza","onde fica rog'mar"}}},fp="20,151,21.235.0,30.82.0,28.69.0,19.90.0,25.30.0"}
P.entries["quest:96104"] = {n="Song of the Strider",s="Neza Bloodsnout encontra sinais de um grande leão perto de Rog'mar e se oferece para ajudar a atraí-lo. Você leva a ela um bico de tallstrider para que possa moldar um apito de caça.",h="Neza Bloodsnout encontra sinais de um grande leão perto de Rog'mar e se oferece para ajudar a atraí-lo.",kw={"bico","leão","neza bloodsnout","rog'mar","canção do strider","tallstrider","apito"},sec={{t="Um apito de Caçador",b="Em Rog'mar, Neza Bloodsnout interpreta as marcas como sendo de um leão, provavelmente o líder de um bando que vive por perto. Ela oferece a você a primeira chance de caçá-lo e vai ajudar a atrair a fera. Para isso, precisa de um bico de tallstrider para moldar um apito que imite o som de um tallstrider ferido."}},faq={{q="Quem é Neza Bloodsnout?",a="Neza Bloodsnout é uma caçadora em Rog'mar que sabe fazer apitos e imitar chamados de animais.",al={"neza","quem é neza","neza bloodsnout"}},{q="O que Neza acha que fez as marcas?",a="Neza acha que as marcas foram feitas por um leão, provavelmente o líder de um bando que vive por perto.",al={"o que fez estas marcas","pegadas de leão","marcas em rog'mar"}},{q="Por que Neza precisa de um bico de tallstrider?",a="Neza precisa de um bico de tallstrider para moldar um apito que imite o chamado de um tallstrider ferido.",al={"por que o bico","para que serve o bico de tallstrider","bico para apito"}},{q="Para que serve o apito?",a="O apito deve atrair o leão ao imitar o som de um tallstrider ferido.",al={"o que o apito faz","atrair leão","apito de leão"}},{q="Onde Neza pede que você leve o bico?",a="Leve o bico intacto de tallstrider para Neza Bloodsnout em Rog'mar.",al={"onde levar o bico","localização de neza","entregar o bico"}}},fp="19,157,18.271.0,23.78.0,39.79.0,38.90.0,24.81.0,42.64.0"}
P.entries["quest:96105"] = {n="King of the Wild Plains",s="Neza Bloodsnout, em Rog'mar, envia você atrás do líder de uma alcateia de leões. Um Tallstrider Call invocará a fera no morro ao sul, onde os leões vivem.",h="Neza Bloodsnout, em Rog'mar, envia você atrás do líder de uma alcateia de leões.",kw={"pele","colina","rei das planícies selvagens","líder","bando de leões","neza bloodsnout","rog'mar","tallstrider call"},sec={{t="O Chamado",b="Neza Bloodsnout, em Rog'mar, tem um Tallstrider Call preparado para você. Leve-o ao topo do morro ao sul, onde os leões vivem, e use-o quando estiver preparado para enfrentar o líder da alcateia. Neza pede que você traga de volta a pele da fera, e a caçada testará sua força nestas planícies."}},faq={{q="Quem quer a pele do leão?",a="Neza Bloodsnout em Rog'mar pede que você traga a pele do líder do bando de leões.",al={"quem me enviou","neza bloodsnout","pele para neza"}},{q="O que o Tallstrider Call faz?",a="Quando usado, o Tallstrider Call atrai o líder do bando de leões.",al={"para que serve o apito","apito de chamado","atrair leão"}},{q="Onde devo usar o Tallstrider Call?",a="Use o Tallstrider Call no topo do morro ao sul, onde os leões vivem.",al={"onde fica a colina","colina dos leões","onde usar o chamado"}},{q="O que estou caçando?",a="Você está caçando o líder do bando de leões.",al={"qual fera","rei das planícies selvagens","líder dos leões"}}},fp="23,159,8.293.0,26.86.0,34.68.0,40.83.0,18.45.0"}
P.entries["quest:96107"] = {n="Feathers for Fletching",s="Neza Bloodsnout, em Rog'mar, faz as próprias flechas e pede penas de Plains Buzzard. A textura áspera delas é útil para emplumar flechas.",h="Neza Bloodsnout, em Rog'mar, faz as próprias flechas e pede penas de Plains Buzzard.",kw={"flechas","penas","emplumação","caçador","neza bloodsnout","plains buzzard","rog'mar"},ang={["class:Hunter"]="Como caçador, você sabe que flechas são uma necessidade frequente; Neza faz as próprias e confia no trabalho manual."},sec={{t="Flechas de Neza",b="Em Rog'mar, Neza Bloodsnout pede que você recolha penas dos buzzards próximos. Ela faz as próprias flechas à mão e confia no próprio trabalho. As penas ásperas são adequadas para emplumar flechas, as aletas que ajudam a flecha a voar em linha reta."}},faq={{q="Por que Neza quer penas de buzzard?",a="Neza usa as ásperas Plains Buzzard Feathers para emplumar as flechas que faz à mão.",al={"motivo das penas de buzzard","por que penas","penas de neza"}},{q="Quem é Neza Bloodsnout?",a="Neza Bloodsnout é uma fabricante de flechas em Rog'mar que prefere fazer as próprias flechas à mão.",al={"quem é neza","neza bloodsnout","neza em rog'mar"}},{q="Onde posso encontrar Neza?",a="Neza Bloodsnout fica em Rog'mar.",al={"onde fica neza","localização de neza","rog'mar neza"}}},fp="22,139,13.215.0,36.91.0,23.84.0,22.30.0"}
P.entries["quest:96108"] = {n="Poison Tips",s="Neza Bloodsnout quer veneno de Glade Viper das poças ao sul de Rog'mar. Ela planeja revestir flechas com ele, embora o veneno estrague a carne.",h="Neza Bloodsnout quer veneno de Glade Viper das poças ao sul de Rog'mar.",kw={"glade viper","neza bloodsnout","flechas envenenadas","pontas envenenadas","rog'mar","veneno de víbora"},sec={{t="Um revestimento letal",b="O veneno pode tornar uma flecha mais potente, embora estrague a carne. Neza Bloodsnout, em Rog'mar, acredita que você pode coletar veneno das víboras perto das poças ao sul. O veneno delas é perigoso de manusear, então é preciso ter cuidado ao coletá-lo."}},faq={{q="Quem quer o veneno das víboras?",a="Neza Bloodsnout, em Rog'mar, quer veneno de Glade Viper.",al={"quem pediu veneno","veneno de neza bloodsnout","quem é neza"}},{q="Para que serve o veneno?",a="Neza planeja usar o veneno para revestir flechas.",al={"por que veneno","flechas envenenadas","para que serve"}},{q="De onde vem o veneno?",a="As Glade Vipers perto das poças ao sul produzem o veneno.",al={"onde estão as víboras","localização do veneno das víboras","víboras nas poças"}},{q="Por que revestir flechas com veneno?",a="O revestimento venenoso torna as flechas mais potentes contra as presas, mas estraga a carne.",al={"por que envenenar flechas","por que pontas envenenadas","fortalecer flechas"}},{q="É perigoso coletar veneno de Glade Viper?",a="Sim. Neza avisa que você pode sucumbir ao veneno das víboras enquanto o coleta.",al={"o veneno pode me ferir","perigo do veneno das víboras","aviso sobre veneno"}}},fp="11,140,16.235.0,26.51.0,22.59.0,31.61.0,28.72.0,41.79.0"}
P.entries["quest:96109"] = {n="A Hunter's Quiver",s="Neza Bloodsnout, em Rog'mar, precisa de couros de leão para uma aljava de caçador. Você coleta peles dos leões no morro ao sul.",h="Neza Bloodsnout, em Rog'mar, precisa de couros de leão para uma aljava de caçador.",kw={"flechas","caçador","aljava de caçador","couros de leão","leões","neza bloodsnout","valiosos couros de leão","rog'mar"},ang={["class:Hunter"]="Como caçador, você precisa de uma aljava que carregue muitas flechas sem atrapalhar seus movimentos."},sec={{t="Equipamento de caçador",b="As armas de um caçador precisam de uma aljava que comporte muitas flechas sem atrapalhar quem a carrega. Neza Bloodsnout, em Rog'mar, pede que você colete valiosos couros de leão para fazer uma. Os leões caçam em bandos, então Neza avisa que você deve tomar cuidado para não ser cercado."}},faq={{q="Quem precisa dos couros de leão?",a="Neza Bloodsnout, em Rog'mar, precisa de valiosos couros de leão para uma aljava de caçador.",al={"quem quer os couros","couros para neza bloodsnout"}},{q="Para que servem os couros?",a="Os couros de leão são material para uma aljava resistente, que se ajusta bem e comporta muitas flechas sem atrapalhar quem a carrega.",al={"para que serve o couro de leão","couros para aljava"}},{q="Onde estão os leões?",a="Os leões se reúnem em um morro ao sul, visível de Rog'mar.",al={"morro dos leões","onde estão os leões"}},{q="Por que Neza quer peles de leão?",a="Neza diz que as peles de leão são muito adequadas à vida de caçador nas planícies.",al={"por que querem couros de leão","leões para aljava"}},{q="Que aviso Neza dá?",a="Neza avisa que os leões caçam em bandos e podem cercar você.",al={"aviso sobre os leões","bandos"}}},fp="17,120,15.230.0,25.73.0,23.118.0,20.62.0,30.71.0,28.61.0"}
P.entries["quest:96125"] = {n="In Need of Relief",s="Um guarda em Bolder'ok precisa ser rendido após reunirem as peles de leão e eliminarem os saqueadores orcs. Dunston Willis não voltou do assentamento dos ogros, e pedem que você o encontre.",h="Um guarda em Bolder'ok precisa ser rendido após reunirem as peles de leão e eliminarem os saqueadores orcs.",kw={"bolder'ok","demar","dunston willis","precisa de substituto","peles de leão","ogros","saqueadores orcs","vigília"},sec={{t="Um substituto desaparecido",b="Em Bolder'ok, a guarda continua sem o substituto prometido. Dunston Willis, um explorador, foi investigar o assentamento dos ogros ao norte há alguns dias e deveria voltar para assumir o posto. O guarda pede que você o encontre entre os ogros. Se Dunston estiver vivo, traga-o de volta; caso contrário, traga uma prova para que Demar possa enviar outra pessoa."}},faq={{q="Quem é Dunston Willis?",a="Dunston Willis é um explorador que foi investigar o assentamento dos ogros ao norte de Bolder'ok.",al={"dunston","quem é dunston","explorador willis"}},{q="Por que o guarda está procurando Dunston?",a="Esperava-se que Dunston voltasse para assumir o posto do guarda, mas ele não retornou.",al={"por que encontrar dunston","substituto desaparecido","guarda precisa de ajuda"}},{q="Para onde Dunston foi?",a="Dunston foi investigar o assentamento dos ogros em Bolder'ok.",al={"localização de dunston","onde está willis","assentamento dos ogros"}},{q="O que o guarda pede que eu faça?",a="Pedem que você encontre Dunston entre os ogros. Se ele estiver vivo, traga-o de volta; caso contrário, traga uma prova para que Demar possa enviar outro guarda.",al={"o que devo fazer","encontrar dunston","pedido de substituição"}},{q="O que aconteceu antes do desaparecimento de Dunston?",a="As peles de leão foram coletadas e os saqueadores orcs foram eliminados antes que o guarda esperasse que Dunston assumisse a vigília.",al={"peles de leão","saqueadores eliminados","o que aconteceu primeiro"}}},fp="17,188,16.339.0,22.100.0,37.88.0,21.61.0,33.134.0,42.121.0"}
P.entries["quest:96130"] = {n="Chakuyak",s="Chakuyak é uma loba-da-pradaria excepcionalmente agressiva que espreita nos bosques a oeste do Lago da Ferradura, em Mulgore. Representando uma ameaça crescente para os viajantes que passam por ali, ela foi marcada para a caça pelos membros da tribo local, que procuram proteger a região ao mesmo tempo em que honram a pele da fera abatida.",h="Chakuyak é uma loba-da-pradaria excepcionalmente agressiva que espreita nos bosques a oeste do Lago da...",kw={"chakuyak","mulgore","lobo-da-pradaria","lago da ferradura","caça tauren","viajantes","pele de lobo"},ang={["class:Hunter"]="Rastrear uma loba alfa solitária e extraordinariamente feroz pelas colinas arborizadas exige paciência, sentidos aguçados e respeito pelos predadores selvagens.",["race:Tauren"]="A caçada reflete a filosofia dos taurens de equilibrar a reverência pelas criaturas da natureza com o dever prático de proteger a tribo e honrar as feras abatidas aproveitando suas peles."},sec={{t="A Sombra do Lago da Ferradura",b="Entre os lobos-da-pradaria que vagam pelos platôs verdejantes e colinas ondulantes de Mulgore, uma fêmea alfa excepcionalmente feroz conhecida como Chakuyak destacou-se por sua agressividade implacável. Espreitando nos bosques a oeste do Lago da Ferradura, ela deixou de ser uma presa comum para se tornar um perigo direto para os viajantes que chegam de terras distantes, levando os caçadores locais a marcá-la para eliminação antes que andarilhos inocentes sejam feridos."},{t="Reverência e Necessidade",b="Para as tribos locais, ceifar a vida de um predador magnífico como Chakuyak é encarado com solene reverência, e não com crueldade arrogante. Abatê-la é visto como um ato necessário de proteção tanto para viajantes quanto para aldeões. De acordo com os costumes nômades, sua pele espessa é levada de volta para ser cuidadosamente tratada e aproveitada, para que o espírito e o sacrifício da grande loba sejam honrados e não desperdiçados."}},faq={{q="Quem ou o que é Chakuyak?",a="Chakuyak é uma loba-da-pradaria incomumente grande e agressiva que espreita as colinas perto do Lago da Ferradura, em Mulgore. Ela ganhou um nome próprio devido à ameaça que representa para os viajantes que passam pela região.",al={"o que é chakuyak","quem é chakuyak","chakuyak é um lobo"}},{q="Onde Chakuyak fica localizada?",a="Chakuyak espreita o terreno arborizado diretamente a oeste do Lago da Ferradura, vagando furtivamente entre os arvoredos ao longo das colinas.",al={"onde encontrar chakuyak","localização de chakuyak","onde chakuyak vaga"}},{q="Por que Chakuyak precisa ser caçada?",a="Embora os lobos-da-pradaria locais sejam uma parte natural da fauna de Mulgore, Chakuyak tornou-se extraordinariamente ousada e agressiva, ameaçando diretamente os viajantes que entram no território vindos de fora.",al={"por que matar chakuyak","ameaça de chakuyak"}},{q="O que acontece com a pele de Chakuyak após a caçada?",a="O concedente da missão garante que tirar a vida de uma fera tão magnífica não seja em vão; sua pele é preservada e bem aproveitada para que nada seja desperdiçado.",al={"o que acontece com a pele de chakuyak","pele de chakuyak"}},{q="Preciso de um grupo para caçar Chakuyak?",a="Chakuyak é excepcionalmente feroz e perigosa em comparação com lobos comuns, e os viajantes frequentemente se reúnem em pequenos grupos de caça para rastreá-la e derrotá-la em segurança.",al={"devo formar grupo para chakuyak","é difícil derrotar chakuyak sozinho"}},{q="Quem reconhece sua vitória sobre Chakuyak?",a="O caçador que atribui a tarefa promete fazer grandes elogios ao seu feito diretamente ao chefe da tribo após a derrota da fera e a entrega de sua pele.",al={"quem recompensa a caça a chakuyak","chefe chakuyak"}}},fp="8,179,28.287.0,23.239.0,24.90.0,26.79.0,33.94.0,47.59.0,35.112.0,44.119.0"}
P.entries["quest:96137"] = {n="Ira's Dagger",s="Sirra Von'Indi pede que você investigue a adaga de Ira e os worgs que ainda atacam viajantes. O espírito de Ira pode ter assuntos pendentes na floresta.",h="Sirra Von'Indi pede que você investigue a adaga de Ira e os worgs que ainda atacam viajantes.",kw={"black ravager","vila sombria","ira","adaga de ira","patrulheira","sirra von'indi","espírito","worg","young black ravager"},sec={{t="A adaga de uma patrulheira",b="Sirra Von'Indi, em Vila Sombria, pede que você enfrente os worgs que continuam fazendo vítimas na floresta. Ira era uma patrulheira autoproclamada que mantinha a floresta segura, impedindo que feras atacassem viajantes. Seu espírito ainda vaga por lá, e a adaga pertencia a ela. Sirra busca mais informações sobre a lâmina."}},faq={{q="Quem foi Ira?",a="Ira era uma patrulheira autoproclamada que mantinha a floresta segura, impedindo que feras atacassem viajantes.",al={"história de ira","quem é ira"}},{q="Por que o espírito de Ira vaga pela floresta?",a="O espírito de Ira ainda vaga pela floresta, e ela pode ter assuntos pendentes por lá.",al={"por que ira é fantasma","por que ira é um fantasma"}},{q="O que é a adaga de Ira?",a="É uma pequena adaga que pertencia a Ira.",al={"adaga de ira","história da adaga"}},{q="Por que você está enfrentando worgs?",a="Os worgs continuam fazendo vítimas por toda a floresta, e o assunto pendente de Ira pode ser eliminá-los.",al={"worgs na floresta","missão de ira com worgs"}},{q="Quem pergunta sobre a adaga?",a="Sirra Von'Indi, em Vila Sombria, pede que você volte até ela com a adaga para obter mais informações.",al={"adaga sirra","quem quer a adaga de ira"}}},fp="12,145,17.316.0,12.103.0,40.81.0,21.42.0,31.114.0,26.91.0"}
P.entries["quest:96138"] = {n="Merrick's Bow",s="Sirra Von'Indi pede que você investigue os ogros que afligem o espírito de Merrick Valor perto do Monte Corvo. O arco de Merrick pode ajudar a esclarecer a história do lugar.",h="Sirra Von'Indi pede que você investigue os ogros que afligem o espírito de Merrick Valor perto do Monte Corvo.",kw={"vila sombria","merrick valor","arco de merrick","ogros","monte corvo","sirra von'indi","splinter fist","watcher"},sec={{t="A preocupação de um espírito",b="Perto do Monte Corvo, o espírito de Merrick Valor ainda vaga pelas estradas. Você tem um arco que ele deixou para trás, e suas pendências podem envolver os ogros ao sul da cidade. Sirra Von'Indi, na Vila Sombria, pode contar mais sobre o arco e o passado de Merrick."},{t="O passado de Merrick",b="Sirra Von'Indi diz que Merrick sempre quis provar seu valor e que algo aconteceu com ele e sua família. Ela agradece por você ter trazido o arco e espera que ele ajude a esclarecer melhor a história do Monte Corvo."}},faq={{q="Quem foi Merrick Valor?",a="Merrick Valor foi um renomado Watcher que se orgulhava de manter as estradas a salvo dos inimigos que avançavam.",al={"merrick","merrick valor"}},{q="Por que o espírito de Merrick está vagando?",a="O espírito de Merrick ainda vaga pelas estradas. Suas pendências podem estar ligadas aos ogros ao sul do Monte Corvo.",al={"fantasma de merrick","por que o espírito vaga"}},{q="O que o arco de Merrick tem a ver com o Monte Corvo?",a="Sirra Von'Indi espera que o arco de Merrick ajude a esclarecer melhor a história do Monte Corvo.",al={"arco de merrick","arco monte corvo"}},{q="Quem é Sirra Von'Indi?",a="Sirra Von'Indi está na Vila Sombria e pode contar mais sobre o arco de Merrick.",al={"sirra","sirra von indi"}},{q="O que aconteceu com Merrick e sua família?",a="Sirra Von'Indi diz que algo aconteceu com Merrick e sua família, mas não dá mais detalhes.",al={"família de merrick","o que aconteceu com merrick"}}},fp="13,154,18.240.0,14.205.1,22.96.0,34.111.0,51.79.0,22.73.0,40.95.0"}
P.entries["quest:96139"] = {n="The Valor Family",s="Sirra Von'Indi pede que você procure em Monte Corvo registros de seu povo desaparecido. Vila Sombria se lembra da coragem deles, mas pouco da história de Monte Corvo resta em sua biblioteca.",h="Sirra Von'Indi pede que você procure em Monte Corvo registros de seu povo desaparecido.",kw={"vila sombria","floresta do crepúsculo","história","lady althea","monte corvo","sirra von'indi","tomo","família valor"},sec={{t="Uma história perdida",b="Sirra Von'Indi diz que Vila Sombria deve sua sobrevivência a pessoas corajosas, incluindo Lady Althea e aqueles que morreram em Monte Corvo. Ela pede que você procure qualquer coisa que possa preservar a memória deles."},{t="O tomo",b="O livro que você traz de volta é sobre a família Valor. Sirra se oferece para copiá-lo e recebe de bom grado outros materiais sobre eles."}},faq={{q="Quem está me pedindo para procurar em Monte Corvo?",a="Sirra Von'Indi, cuja biblioteca fica em Vila Sombria, pede que você procure materiais sobre Monte Corvo.",al={"quem quer o livro","sirra monte corvo","quem é sirra"}},{q="Por que Sirra quer registros de Monte Corvo?",a="Sirra diz que a história de Monte Corvo se perdeu junto com seu povo e quer que seus feitos sejam lembrados.",al={"por que procurar em monte corvo","história de monte corvo","lembrar de monte corvo"}},{q="Quem Sirra diz ter ajudado a manter Vila Sombria de pé?",a="Sirra cita Lady Althea e aqueles que perderam a vida em Monte Corvo como pessoas corajosas cujas ações ajudaram Vila Sombria a resistir.",al={"heróis de vila sombria","lady althea","quem salvou vila sombria"}},{q="Como é a história de Monte Corvo?",a="Sirra diz que a história de Monte Corvo foi apagada junto com seu povo, e que sua biblioteca guarda pouco sobre o lugar.",al={"o que aconteceu com monte corvo","passado de monte corvo","monte corvo perdido"}}},fp="16,162,14.194.0,8.118.1,38.107.0,44.95.0,50.123.0,34.98.0"}
P.entries["quest:962"] = {n="Ofídeas",s="Ofídeas é uma tarefa de coleta oferecida pela Boticária Zaqueia, emissária da Real Sociedade de Boticários que reside no Penhasco do Trovão. Zaqueia procura exemplares de uma erva rara encontrada nas profundezas subterrâneas da Caverna Ululante para auxiliar as pesquisas dos Renegados.",h="Ofídeas é uma tarefa de coleta oferecida pela Boticária Zaqueia, emissária da Real Sociedade de Boticários...",kw={"boticária","sertões","sociedade real dos boticários","ofídeas","chapada dos espíritos","penhasco do trovão","cidade baixa","caverna ululante","zaqueia"},ang={["faction:Horde"]="Essa tarefa fortalece a aliança operacional inicial entre a Cidade Baixa e as tribos de Kalimdor, que compartilham recursos e reagentes raros através do oceano.",["profession:Herbalism"]="O ambiente alterado da Caverna Ululante favorece uma flora singular, ausente da superfície dos Sertões castigada pelo sol.",["race:Tauren"]="Acolher boticários Renegados sob a Chapada dos Espíritos demonstra a hospitalidade da Horda, embora o interesse deles em misturas letais contraste com as práticas tradicionais de cura da terra.",["race:Undead"]="Contribuir com Ofídeas apoia diretamente as pesquisas alquímicas da Real Sociedade de Boticários em Lordaeron, sob as ordens da Dama Sombria."},sec={{t="Os olhos da boticária",b="Instalada nas Poças das Visões, abaixo da Chapada dos Espíritos, no Penhasco do Trovão, a Boticária Zaqueia atua como emissária da Real Sociedade de Boticários, vinda da Cidade Baixa. Enquanto seus anfitriões taurens se concentram no equilíbrio espiritual e na cura da terra ferida, Zaqueia busca materiais raros e virulentos. Após isolar uma amostra de uma planta incomum chamada ofídea, ela procura grandes quantidades para avançar nas pesquisas conduzidas sob as ordens da Senhora Sylvana Correventos e dos Renegados."},{t="As profundezas das cavernas",b="A ofídea não cresce sob o sol dos Sertões, mas prospera nas grutas úmidas e sinuosas da Caverna Ululante. Adaptada ao clima subterrâneo abafado, alterado pelos druidas corrompidos da Presa, a planta é difícil de alcançar e ferozmente protegida pelos habitantes serpentinos da caverna. Zaqueia admite que muitos batedores enviados antes não retornaram, deixando a coleta para aventureiros mais experientes."}},faq={{q="Quem é a Boticária Zaqueia?",a="A Boticária Zaqueia é uma pesquisadora que representa a Real Sociedade de Boticários da Cidade Baixa. Instalada nas Poças das Visões, sob a Chapada dos Espíritos, no Penhasco do Trovão, ela serve de ligação entre os alquimistas Renegados e as demais regiões de Kalimdor.",al={"zaqueia","história da boticária zaqueia","quem oferece ofídeas"}},{q="Por que a Real Sociedade de Boticários quer Ofídeas?",a="Zaqueia acredita que a erva possui um grande potencial químico quando refinada em grandes quantidades. A Sociedade procura ativamente plantas raras e potentes por Kalimdor para auxiliar os experimentos alquímicos dos Renegados.",al={"por que ofídeas","pesquisa dos renegados sobre ervas","finalidade de ofídeas"}},{q="Onde cresce Ofídeas?",a="Ofídeas cresce nas profundezas da Caverna Ululante, entre corredores úmidos de pedra e passagens subterrâneas escavadas sob os Sertões Setentrionais.",al={"onde encontrar ofídeas","localização de ofídeas"}},{q="Por que os batedores anteriores não voltaram?",a="A Caverna Ululante está infestada de feras degeneradas, raptores e Druidas da Presa corrompidos. Coletores menos experientes enviados aos túneis labirínticos foram rapidamente dominados pela fauna predatória e pelos defensores venenosos do local.",al={"batedores desaparecidos","batedores de zaqueia","caverna ululante é perigosa"}},{q="Os taurens aprovam as pesquisas de Zaqueia?",a="Os taurens do Penhasco do Trovão acolheram os Renegados por compaixão e pelo desejo de ajudá-los a se curar, mas as práticas alquímicas da Real Sociedade de Boticários frequentemente se aproximam de experimentos antinaturais que incomodam xamãs e druidas tradicionais.",al={"reação dos taurens","boticários na chapada dos espíritos"}},{q="É necessário ter Herborismo para colher Ofídeas?",a="Não. Embora seja um espécime botânico, qualquer aventureiro disposto a enfrentar as profundezas da Caverna Ululante pode colher as plantas diretamente do chão, sem treinamento formal em Herborismo.",al={"preciso de herborismo","profissão para colher ofídeas"}}},fx={["962715c8"]={q="Por que Apothecary Zamah quer que Ofídea seja coletada?",a="Apothecary Zamah foi enviada ao Penhasco do Trovão pela Real Sociedade de Boticários em uma missão específica para promover os interesses dos Renegados e da Grande Dama, Grande Dama Sylvana Correventos. Tendo analisado uma amostra rara de Ofídea, Zamah vê um imenso potencial em suas propriedades se obtida em quantidades substanciais. Garantir espécimes suficientes permite que sua pesquisa avance nas ambições científicas e alquímicas da Cidade Baixa.",al={"motivação de apothecary zamah","por que zamah precisa de ofídea","por que coletar ofídea"}},["92b49307"]={q="Por que Apothecary Zamah envia um aventureiro em vez de coletar Ofídea ela mesma?",a="Zamah não pode abandonar facilmente seu posto no Penhasco do Trovão, e colher a erva exige aventurar-se nas profundezas traiçoeiras e corrompidas da Caverna Ululante. Ela já enviou vários batedores e agentes para o sistema de cavernas em seu nome, mas nenhum deles retornou vivo. Ela precisa de aventureiros experientes e capazes dispostos a enfrentar esses recessos sombrios onde os batedores comuns falharam.",al={"por que me enviar para ofídea","por que zamah não coleta ofídea","por que aventureiros para ofídea"}}},fp="12,168,22.387.0,25.307.0,24.232.0,56.188.0,29.123.0,37.206.0,42.221.0,54.126.0"}
P.entries["quest:96204"] = {n="The Windshaper's Wrath",s="Lumina Windsinger pede sua ajuda para escapar do Castelo Fenris. Sua ajuda lhe dá motivos para confiar nos paladinos.",h="Lumina Windsinger pede sua ajuda para escapar do Castelo Fenris.",kw={"fuga","castelo fenris","lumina windsinger","paladino","trevan","moldavento"},ang={["class:Paladin"]="Como paladino, Lumina ouviu coisas desagradáveis sobre os de sua classe, mas sua ajuda lhe dá motivos para receber você como amigo."},sec={{t="Uma saída",b="Lumina Windsinger está livre dentro do Castelo Fenris, mas quer sair com você. Ela pretende fazer as criaturas que a aprisionaram se arrependerem de enfrentar uma Moldavento. Fique com ela durante a fuga."},{t="Uma nova amizade",b="No Castelo Fenris, Lumina conta que conheceu Trevan e soube que ele enviou você para encontrá-la. Ela ouviu coisas desagradáveis sobre paladinos, mas sua ajuda mudou a opinião dela. Os Moldavento consideram você e os seus amigos."}},faq={{q="Quem é Lumina Windsinger?",a="Lumina Windsinger é uma Moldavento que foi aprisionada no Castelo Fenris e busca sua ajuda para escapar.",al={"lumina","quem é lumina","windsinger"}},{q="De onde Lumina está tentando escapar?",a="Lumina Windsinger está tentando escapar do Castelo Fenris.",al={"fuga de lumina","castelo fenris","tirar lumina de lá"}},{q="Quem me enviou para encontrar Lumina?",a="Lumina diz que Trevan enviou você para seguir o rastro dela.",al={"quem me enviou","trevan","rastro de lumina"}},{q="Por que Lumina menciona paladinos?",a="Lumina ouviu coisas desagradáveis sobre paladinos, mas diz que essas alegações se mostraram infundadas depois da sua ajuda.",al={"assunto dos paladinos","lumina paladinos","ela confia nos paladinos"}},{q="O que Lumina acha de mim?",a="Lumina diz que você e os seus têm uma amiga entre os Moldavento.",al={"lumina gosta de mim","amigo dos moldavento","o que lumina diz"}}},fp="22,103,9.192.0,12.220.1,25.91.0,38.50.0,27.44.0,33.102.0,29.66.0"}
P.entries["quest:96222"] = {n="Khan Hratha",s="Umarak quer um Maraudine Key Fragment de Khan Hratha como poder de barganha numa negociação. Você deve desafiar Hratha no pico mais alto do Vale das Lanças.",h="Umarak quer um Maraudine Key Fragment de Khan Hratha como poder de barganha numa negociação.",kw={"centauros","desolação","fragmento da chave","khan hratha","maraudino","umarak","vale das lanças","trompa de guerra"},sec={{t="A preocupação de Umarak",b="A guerra assola a Desolação, mas os centauros Maraudino continuam sem ser desafiados no Vale das Lanças. Umarak teme que a inação dos outros clãs os torne mais ousados e provoque ainda mais tumulto. Ele quer o fragmento que Khan Hratha carrega como moeda de troca e pede que você o traga de volta."}},faq={{q="Quem está pedindo o Maraudine Key Fragment?",a="Umarak quer o Maraudine Key Fragment de Khan Hratha como recurso para uma negociação.",al={"quem quer o fragmento da chave","fragmento de umarak"}},{q="Onde estão os centauros Maraudino?",a="Os centauros Maraudino continuam sem ser desafiados no Vale das Lanças, na Desolação.",al={"onde ficam os maraudino","centauros no vale"}},{q="Por que Umarak quer o fragmento?",a="Umarak quer o Maraudine Key Fragment como poder de barganha numa negociação.",al={"por que querem o fragmento da chave","para que serve"}},{q="O que Umarak teme?",a="Umarak teme que os Maraudino se tornem indiferentes e provoquem ainda mais tumulto se os outros clãs continuarem ignorando sua presença.",al={"por que se preocupar com os maraudino","que tumulto"}},{q="O que Khan Hratha está carregando?",a="Khan Hratha possui um Maraudine Key Fragment.",al={"item de hratha","o que khan tem"}},{q="O que Umarak pede que você traga de volta?",a="Umarak pede que você lhe traga o Maraudine Key Fragment.",al={"o que trazer para umarak","pedido do fragmento"}}},fp="11,164,18.276.0,45.76.0,32.78.0,34.70.0,22.116.0,29.47.0,39.56.0"}
P.entries["quest:96241"] = {n="Talkin' bout Toxins, Mon",s="Mazu'kon quer que você colete amostras de veneno dos Gnawed Corpses em Penumbrascente. As estranhas toxinas despertaram a curiosidade dele.",h="Mazu'kon quer que você colete amostras de veneno dos Gnawed Corpses em Penumbrascente.",kw={"extrator","penumbrascente","amostras de toxina de penumbrascente","gnawed corpses","mazu'kon","toxina","veneno"},sec={{t="Em Penumbrascente",b="Mazu'kon ouviu falar de novas criaturas estranhas rastejando por Penumbrascente. O veneno delas pode ter propriedades incomuns, então ele pede que você colete amostras dos Gnawed Corpses com o extrator dele. Ele está curioso para descobrir o que torna a toxina diferente."},{t="As amostras",b="Mazu'kon agradece por você trazer as amostras de toxina de Penumbrascente. Ele diz que as propriedades incomuns do veneno não eram brincadeira e observa que você parece ter saído ileso."}},faq={{q="Quem está pedindo as amostras de toxina?",a="Mazu'kon pede que você colete amostras de veneno dos Gnawed Corpses em Penumbrascente.",al={"quem quer toxinas","mazu'kon toxina"}},{q="Por que Mazu'kon quer o veneno?",a="Ele ouviu dizer que o veneno das criaturas pode ter propriedades incomuns, e isso despertou a curiosidade dele.",al={"por que toxinas","sobre o que ele está curioso"}},{q="Onde consigo as amostras?",a="As amostras vêm dos Gnawed Corpses em Penumbrascente.",al={"onde encontrar amostras de toxina","cadáveres de penumbrascente"}},{q="O que Mazu'kon dá a você?",a="Mazu'kon dá a você um extrator para coletar o veneno.",al={"extrator","como coletar toxina"}},{q="De quantas amostras de toxina ele precisa?",a="Mazu'kon pede cinco Gloomrise Toxin Samples.",al={"quantidade de amostras","quantas toxinas"}}},fp="24,127,12.244.0,11.153.1,36.80.0,33.91.0,27.50.0,28.52.0,36.47.0"}
P.entries["quest:96243"] = {n="Call of Earth",s="Call of Earth é uma convocação introdutória que chama um iniciado para se sintonizar com os espíritos da pedra. Direcionado ao Vale Cristálgida, o viajante deve procurar Teo Hammerstorm dentro da fortaleza anã de Sidermar.",h="Call of Earth é uma convocação introdutória que chama um iniciado para se sintonizar com os espíritos da...",kw={"sidermar","call of earth","vale cristálgida","dun morogh","totem da terra","elementos","xamã","teo hammerstorm"},ang={["class:Shaman"]="Atender ao chamado da terra é um passo fundamental para trilhar o caminho xamânico, vinculando o iniciado à pedra profunda e aos espíritos resolutos da terra.",["faction:Alliance"]="Xamãs da Aliança em Dun Morogh começam sua jornada elemental a partir da fortaleza anã ancestral de Sidermar.",["race:Dwarf"]="Os anões compartilham um elo inerente com a pedra e a terra, fazendo com que a comunhão com esses espíritos terrestres pareça natural em meio às profundas abóbadas de Dun Morogh."},sec={{t="A Voz da Pedra",b="Para um iniciado que trilha o caminho dos elementos, o chamado da terra é a primeira comunhão vital. Embora as energias elementais já possam se agitar sobre a pele, aprender a falar diretamente com a pedra estabelece um equilíbrio inabalável. Isso ensina ao espírito como encontrar uma força inamovível, firmando passos sólidos sob as botas e dentro do próprio espírito."},{t="A Fortaleza de Sidermar",b="Iniciados nas extensões nevadas de Dun Morogh são direcionados para o abrigo de Sidermar, uma enorme fortaleza forjada por martelo, fogo e vontade. Dentro deste venerável reduto no Vale Cristálgida aguarda Teo Hammerstorm, que instrui xamãs novatos sobre como atender ao estrondo da terra e iniciar seus deveres elementais."}},faq={{q="O que é Call of Earth?",a="Call of Earth é uma convocação introdutória que orienta um aspirante a xamã a iniciar a comunhão com os espíritos da terra. Ela instrui o iniciado a buscar orientação e a se firmar no poder da pedra viva.",al={"o que é call of earth","missão call of earth","o que é esta missão"}},{q="Quem é Teo Hammerstorm?",a="Teo Hammerstorm é um mentor localizado dentro da fortaleza anã de Sidermar, no Vale Cristálgida. Ele orienta os iniciados a comungar com a terra e a compreender sua força constante.",al={"quem é teo hammerstorm","onde fica teo hammerstorm","localização de teo hammerstorm"}},{q="O que é Sidermar?",a="Sidermar é uma fortaleza resistente forjada por martelo, fogo e vontade, situada na extensão nevada do Vale Cristálgida em Dun Morogh. Ela serve como reduto central e campo de treinamento para jovens heróis.",al={"onde fica sidermar","o que é sidermar","localização de sidermar"}},{q="Por que um xamã deve atender ao chamado da terra?",a="Comungar com a terra permite que o xamã firme sua essência espiritual, estabelecendo passos sólidos tanto sob suas solas quanto dentro de sua alma, para que possa canalizar o poder constante da pedra.",al={"por que falar com a terra","objetivo de call of earth","conexão do xamã com a terra"}},{q="Quem assume esta convocação?",a="A missão é voltada para o desenvolvimento de xamãs iniciantes em Dun Morogh, direcionando-os a procurar treinadores elementais experientes que possam guiar sua conexão com os espíritos.",al={"quem envia call of earth","quem aceita call of earth","quem faz esta missão"}},{q="Para onde esta missão leva?",a="A jornada leva a Sidermar, aninhada no Vale Cristálgida, no reino nevado de Dun Morogh. Os iniciados devem se aventurar dentro da fortaleza para encontrar seu mentor.",al={"onde ocorre call of earth","zona de call of earth","para onde ir"}}},fp="13,156,18.294.0,24.275.0,22.177.0,23.171.0,17.163.0,41.157.0,28.155.0,27.130.0"}
P.entries["quest:96259"] = {n="Defending the Dead",s="Em Gloomrise, aranhas ameaçam o povo de Mulgore e um antigo cemitério tauren. Você recebe um pedido para ajudar a conter a infestação.",h="Em Gloomrise, aranhas ameaçam o povo de Mulgore e um antigo cemitério tauren.",kw={"defendendo os mortos","gloomrise","filhotes","mulgore","soldados","aranhas","cemitério tauren"},ang={["race:Tauren"]="Para você, como tauren, Gloomrise é importante por ser um antigo cemitério que muitos de seu povo consideram sagrado."},sec={{t="O cemitério",b="Um acampamento pede que você proteja Gloomrise, um antigo cemitério tauren a noroeste do acampamento. Aranhas ferozes infestam o local, ameaçando o povo de Mulgore e danificando um lugar que muitos taurens consideram sagrado."},{t="Uma base de apoio",b="Seus esforços ajudam o povo de Mulgore a estabelecer uma base de apoio contra as aranhas. Eliminar a infestação por completo pode levar tempo, então o cemitério continua em risco."}},faq={{q="O que é Gloomrise?",a="Gloomrise é um antigo cemitério tauren a noroeste do acampamento.",al={"cemitério de gloomrise","onde fica gloomrise"}},{q="Por que Gloomrise está em perigo?",a="Aranhas ferozes infestam Gloomrise, ameaçando o povo de Mulgore e danificando o cemitério sagrado.",al={"aranhas em gloomrise","por que defender os mortos"}},{q="Por que o cemitério é sagrado?",a="Muitos taurens consideram Gloomrise sagrado.",al={"local sagrado tauren","por que cemitério tauren"}},{q="Quem pede ajuda?",a="Um acampamento pede que você ajude a proteger Gloomrise da infestação de aranhas.",al={"quem precisa de ajuda","quem deu isso"}},{q="A infestação foi eliminada?",a="Não. Seus esforços estabelecem uma base de apoio, mas eliminar a infestação por completo pode levar tempo.",al={"as aranhas se foram","infestação em gloomrise"}}},fp="18,133,17.202.0,10.170.1,18.67.0,27.103.0,32.38.0,18.70.0,33.90.0"}
P.entries["quest:96260"] = {n="Stronger than Steel",s="Em Penumbrascente, um pesquisador busca seda cristalina das aranhas gigantes que se espalham pelo local. A seda pode render um tecido leve com grande capacidade de defesa.",h="Em Penumbrascente, um pesquisador busca seda cristalina das aranhas gigantes que se espalham pelo local.",kw={"capa","tecido","seda cristalina","penumbrascente","aranhas","mais forte que aço","veneno"},sec={{t="Seda para estudo",b="Um pesquisador pede a você mais seda cristalina depois que um batedor voltou de Penumbrascente coberto dela. Aranhas gigantes se espalharam pelo cemitério, e dizem que seu veneno desperta os mortos. A resistência da seda pode torná-la útil para tecidos com grande capacidade de defesa."},{t="Uma nova trama",b="As amostras se mostram suficientes para as necessidades do pesquisador. Uma capa tecida com a seda que ele já tinha é oferecida a você, na esperança de ajudar em suas viagens."}},faq={{q="O que o pesquisador quer?",a="O pesquisador quer mais seda cristalina das aranhas de Penumbrascente para estudo.",al={"amostras de seda","seda cristalina","qual seda"}},{q="Onde a seda é encontrada?",a="A seda cristalina vem das aranhas gigantes de Penumbrascente.",al={"onde encontrar seda","seda de penumbrascente","local da seda de aranha"}},{q="Por que estudar a seda?",a="A seda pode ser transformada em tecido leve e durável com propriedades defensivas.",al={"uso da seda","o que a seda pode fazer","por que seda"}},{q="O que dizem sobre o veneno das aranhas?",a="Dizem que o veneno das aranhas é forte o bastante para despertar os mortos.",al={"veneno de aranha","despertar os mortos","rumor sobre o veneno"}},{q="O que o batedor trouxe?",a="Um batedor voltou de uma investigação em Penumbrascente coberto de seda de aranha cristalina e resistente.",al={"relato do batedor","seda do batedor","o que aconteceu com o batedor"}}},fp="19,138,14.273.0,11.152.1,30.80.0,24.59.0,19.79.0,41.67.0,30.94.0"}
P.entries["quest:96261"] = {n="The Broodmother",s="Em Penumbrascente, a Harmonia Telúrica pede que você detenha a infestação de aranhas enfrentando a matriarca delas. A ameaça põe o povo de Mulgore em risco.",h="Em Penumbrascente, a Harmonia Telúrica pede que você detenha a infestação de aranhas enfrentando a matriarca...",kw={"matriarca","harmonia telúrica","penumbrascente","infestação","mulgore","forma de elfa noturna","aranhas","valraxx"},sec={{t="O ninho de Penumbrascente",b="A Harmonia Telúrica acredita que uma matriarca poderosa está causando a infestação de aranhas em Penumbrascente. Você recebe a missão de encontrar Broodmother Valraxx e destruí-la. As aranhas parecem diferentes das aranhas comuns, então a Harmonia avisa você para se preparar para qualquer coisa."},{t="Sinais inquietantes",b="Depois, a Harmonia Telúrica relata mortos reanimados e uma matriarca com a forma de uma elfa noturna. Essas descobertas preocupam seus membros, embora deixem de lado a questão do que elas significam. Eles agradecem a você por ajudar a Harmonia e o povo de Mulgore."}},faq={{q="O que está acontecendo em Penumbrascente?",a="Uma infestação de aranhas está se espalhando em Penumbrascente, e a Harmonia Telúrica acredita que uma matriarca poderosa está no comando.",al={"aranhas de penumbrascente","infestação de aranhas","o que há em penumbrascente"}},{q="Quem é Broodmother Valraxx?",a="Broodmother Valraxx é a matriarca em Penumbrascente que a Harmonia Telúrica pede que você destrua.",al={"valraxx","matriarca","matriarca das aranhas"}},{q="Por que a Harmonia Telúrica quer eliminar a matriarca?",a="A Harmonia acredita que a matriarca está levando a população de aranhas hostis a se espalhar.",al={"por que matar a matriarca","por que valraxx","deter as aranhas"}},{q="Onde está a matriarca?",a="Broodmother Valraxx está em Penumbrascente.",al={"localização de valraxx","onde está a matriarca","localização de penumbrascente"}},{q="O que a Harmonia Telúrica diz sobre essas aranhas?",a="A Harmonia Telúrica diz que essas aranhas parecem não ser aranhas comuns.",al={"aranhas estranhas","aranhas comuns","aranhas esquisitas"}}},fp="15,149,18.247.0,15.238.1,31.113.0,27.94.0,52.85.0,25.36.0,51.59.0"}
P.entries["quest:96264"] = {n="Elemental Aid",s="Um xamã recebe o pedido de investigar os javatuscos que se reúnem no Urzal dos Tuscos. A terra alerta sobre um ritual, e os elementos precisam de ajuda contra aqueles que abusam de seu poder.",h="Um xamã recebe o pedido de investigar os javatuscos que se reúnem no Urzal dos Tuscos.",kw={"charlga talhaflanco","terra","ajuda elemental","elementos","javatuscos","urzal dos tuscos","ritual","xamã"},ang={["class:Shaman"]="Como xamã, você dominou os elementos, e este pedido convoca você a retribuir a ajuda deles."},sec={{t="O alerta da terra",b="A terra leva um aviso a um xamã: os javatuscos estão se reunindo no Urzal dos Tuscos para um ritual de poder terrível. Sua tarefa é investigar o covil deles e voltar com informações sobre seus planos. Os elementos oferecem ajuda a você e agora precisam da sua."}},faq={{q="Sobre o que a terra alerta?",a="A terra alerta que os javatuscos estão se reunindo para um ritual de poder terrível.",al={"alerta da terra","o que está retumbando","ritual dos javatuscos"}},{q="Onde os javatuscos estão se reunindo?",a="Os javatuscos estão se reunindo no Urzal dos Tuscos.",al={"onde investigar","localização dos javatuscos","localização do covil"}},{q="Por que o xamã precisa ajudar os elementos?",a="Os elementos ajudam o xamã, e ele recebe o pedido de retribuir essa ajuda, auxiliando-os contra aqueles que abusam de seu poder.",al={"ajudar os elementos","elemental aid motivo","por que ajudar os elementos"}},{q="Quais informações são necessárias?",a="Você recebe o pedido de investigar o Urzal dos Tuscos e trazer informações sobre os planos dos javatuscos.",al={"o que encontrar","planos dos javatuscos","informações necessárias"}},{q="Quem faz o pedido?",a="O pedido vem de alguém que chama você de xamã e diz que os elementos precisam de ajuda.",al={"quem pede","quem dá a missão","quem precisa de ajuda"}}},fp="13,166,21.259.0,31.79.0,33.45.0,46.124.0,27.95.0,22.88.0"}
P.entries["quest:96294"] = {n="A Darker Truth",s="Muln Earthfury pede que você lhe traga uma carta recuperada em Penumbrascente. Ela pode esclarecer a presença das aranhas por lá.",h="Muln Earthfury pede que você lhe traga uma carta recuperada em Penumbrascente.",kw={"a darker truth","broodmother valraxx","círculo cenariano","penumbrascente","muln earthfury","druida elfo noturno","pact","platô do vigia dos céus","aranhas","wild king"},sec={{t="Uma carta em Penumbrascente",b="Em Penumbrascente, você descobriu que a Broodmother era uma druida Elfa Noturna em uma forma animal distorcida. Ainda há dúvidas sobre as aranhas e seu propósito. Um bilhete encontrado na veste dela pode conter respostas, então você o leva a Muln Earthfury no Platô do Vigia dos Céus."},{t="A preocupação de Muln",b="Muln Earthfury acha a carta perturbadora. Ela fala de um “Wild King” e de um “Pact”, mas ele não sabe quem ou o que são. Ele planeja consultar o Círculo Cenariano, mas se conforta por saber que quem controlava as aranhas já se foi."}},faq={{q="Quem era a Broodmother?",a="A Broodmother era uma druida Elfa Noturna que havia assumido uma forma animal distorcida.",al={"identidade da broodmother","quem é valraxx","aranha elfa?"}},{q="O que levo para Muln Earthfury?",a="Você leva a Muln Earthfury a carta recuperada da veste de Broodmother Valraxx.",al={"qual carta","carta de muln","levar o quê?"}},{q="Para onde levo a carta?",a="Você leva a carta a Muln Earthfury no Platô do Vigia dos Céus.",al={"localização de muln","onde fica o platô do vigia dos céus","destino da carta"}},{q="O que Muln acha da carta?",a="Muln a considera perturbadora e se pergunta sobre as referências a um “Wild King” e a um “Pact”.",al={"reação de muln","por que é perturbadora","o que diz a carta"}},{q="Quem Muln vai consultar?",a="Muln planeja falar com os druidas do Círculo Cenariano.",al={"carta do círculo cenariano","a quem ele vai perguntar","conselho de druidas?"}}},fp="14,109,21.247.0,14.246.1,24.74.0,34.78.0,27.60.0,34.96.0,22.59.0"}
P.entries["quest:963"] = {n="Por amor eterno",s="\"Por amor eterno\" é uma missão trágica concedida por Cerellean Garralva em Auberdine. Atormentado pelas lembranças de sua amada perdida, Anaya Dawnrunner, Cerellean pede a um aventureiro que viaje até as ruínas despedaçadas de Ameth'Aran para libertar seu espírito inquieto de uma eternidade de tormento.",h="\"Por amor eterno\" é uma missão trágica concedida por Cerellean Garralva em Auberdine.",kw={"ameth'aran","anaya dawnrunner","pingente de anaya","auberdine","cerellean garralva","costa negra","for love eternal","cisão"},ang={["class:Druid"]="O destino de Cerellean reflete o custo pessoal pago pelos druidas que entraram em milhares de anos de sono ao lado de Shan'do Tempesfúria, apenas para encontrar o mundo desperto ainda marcado por suas perdas antigas.",["faction:Alliance"]="Ajudar Cerellean oferece aos heróis da Aliança um vislumbre das vidas trágicas de seus aliados elfos noturnos, que abrangem milênios, enquanto eles se ajustam ao mundo desperto.",["race:NightElf"]="Para os elfos noturnos de Costa Negra, ajudar Cerellean é uma lembrança tocante das cicatrizes duradouras deixadas pela Grande Cisão e pela queda de suas cidades antigas."},sec={{t="Um Sono Repleto de Pesar",b="Dez mil anos atrás, durante a Guerra dos Antigos, a catástrofe envolvendo a Nascente da Eternidade despedaçou a antiga Kalimdor. Entre as baixas estava a cidade de Ameth'Aran, onde Cerellean Garralva perdeu sua amada, Anaya Dawnrunner. Tomado pelo desespero, Cerellean seguiu Shan'do Malfurion Tempesfúria no longo descanso dos druidas, na esperança de que os milênios caminhando pelo Sonho Esmeralda acalmassem seu coração dolorido. Em vez disso, sua dor apenas persistiu, acompanhando-o através das eras."},{t="O Fantasma de Ameth'Aran",b="Ao despertar nos tempos recentes, Cerellean vagou por Costa Negra em torpor até que seus passos o levaram de volta às melancólicas ruínas de Ameth'Aran. Lá, perambulando entre as pedras antigas, ele contemplou o fantasma torturado de Anaya. Incapaz de suportar empunhar uma arma contra a mulher que amava, ele implora aos viajantes que passam que destruam a manifestação atormentada dela, recuperem seu pingente e finalmente concedam paz à sua alma atribulada."},{t="Despedida Através do Véu",b="Quando o pingente de Anaya é devolvido a Auberdine, um resquício espectral de Anaya aparece diante de Cerellean uma última vez. Liberta da angústia persistente que a prendia às ruínas, ela se despede brevemente antes de desaparecer no éter, deixando o druida em luto chorando em um consolo agridoce à beira-mar."}},faq={{q="Quem é Cerellean Garralva?",a="Cerellean Garralva é um druida elfo noturno que repousa em Auberdine. Depois de perder sua amada Anaya durante a Cisão, dez mil anos atrás, ele entrou no longo descanso druídico ao lado de Shan'do Malfurion Tempesfúria, carregando sua dor incurável através dos milênios.",al={"cerellean garralva","quem dá for love eternal","história de cerellean"}},{q="Quem foi Anaya Dawnrunner?",a="Anaya Dawnrunner era uma elfa noturna que vivia na cidade de Ameth'Aran antes da Grande Cisão. Ela foi morta quando a cidade caiu durante o rescaldo da Guerra dos Antigos, e seu fantasma permaneceu aprisionado nas ruínas desde então.",al={"anaya dawnrunner","quem é anaya","anaya costa negra"}},{q="Onde fica o espírito de Anaya?",a="Seu espírito vaga entre as antigas ruínas infestadas de fantasmas de Ameth'Aran, localizadas no sul de Costa Negra, a leste da estrada principal.",al={"localização de anaya","onde fica anaya dawnrunner","localização do pingente de anaya"}},{q="Por que Cerellean não pôde libertar Anaya ele mesmo?",a="Apesar da passagem de dez mil anos, o amor de Cerellean por Anaya era tão profundo que ele não suportava a dor no coração de erguer a própria mão ou lançar um feitiço contra a aparição dela, mesmo que fosse para pôr fim ao seu sofrimento.",al={"por que cerellean não mata anaya","por que cerellean pede ajuda"}},{q="O que aconteceu com Ameth'Aran?",a="Ameth'Aran era um antigo assentamento de elfos noturnos destruído há dez milênios durante a Cisão que se seguiu à Guerra dos Antigos. Suas ruínas em Costa Negra permanecem repletas de fantasmas persistentes e ecos arcanos remanescentes.",al={"história de ameth'aran","queda de ameth'aran","o que é ameth'aran"}},{q="O que acontece quando você devolve o pingente de Anaya?",a="Leve o pingente de Anaya para Cerellean em Auberdine após libertar o espírito atribulado dela. O resultado da entrega é revelado quando você retornar.",al={"entrega da missão anaya","final de cerellean","final de for love eternal"}}},fx={dc23d6a3={q="Por que Cerellean Garralva quer o espírito de Anaya liberto?",a="Cerellean acreditava que seu amor, Anaya, tinha perecido milênios atrás, quando Ameth'Aran foi estilhaçada durante a Cisão. Descobrir seu fantasma inquieto e atormentado vagando pelas ruínas partiu seu coração. Sabendo que ela sofre presa a este reino, ele não suporta a ideia de ela permanecer em angústia, mas não consegue levantar a mão contra ela.",al={"por que cerellean quer isso feito","motivação de cerellean","por que destruir o espírito de anaya"}},ed60ea9d={q="Para que serve o Pingente de Anaya?",a="O Pingente de Anaya é a lembrança que Cerellean pede que você traga de volta após libertar seu espírito conturbado em Ameth'Aran.",al={"uso do pingente de anaya","o que faz o pingente de anaya","propósito do pingente de anaya"}}},fp="16,134,23.358.0,23.321.0,23.274.1,27.233.0,25.183.0,32.116.0,42.162.0,28.184.0,45.128.1"}
P.entries["quest:96339"] = {n="Legacy Reward: Replica Ironforge Air Rifle",s="Legacy Reward: Replica Ironforge Air Rifle marca o resgate de um pacote misterioso guardado em seu nome. Deixada para trás por um mensageiro não identificado, a encomenda foi salva por pouco de ser jogada no mar antes de chegar às suas mãos.",h="Legacy Reward: Replica Ironforge Air Rifle marca o resgate de um pacote misterioso guardado em seu nome.",kw={"rifle de ar","altaforja","rifle de ar de altaforja","recompensa de legado","pacote misterioso","réplica de rifle de ar de altaforja"},ang={["profession:Engineering"]="Geringonqueiros e armeiros vão gostar de receber um modelo intrincado de arma de fogo, mesmo que tenha chegado por meio de um mensageiro indiferente e quase tenha ido parar no fundo do oceano.",["race:Dwarf"]="A encomenda guarda uma réplica de um rifle de ar de Altaforja, uma homenagem comemorativa às famosas armas de fogo e à perícia mecânica de Khaz Modan."},sec={{t="Um Pacote Aguardando Coleta",b="Uma encomenda misteriosa endereçada especificamente a você foi deixada com um zelador relutante. O mensageiro desconhecido insistiu que você chegaria para buscá-la, saindo tão depressa que o destinatário nem sequer pôde recusar a entrega. Felizmente, você chegou pouco antes de a caixa não resgatada ser jogada no oceano junto com o lixo da noite."},{t="Engenharia Anã em Miniatura",b="Dentro da encomenda entregue está uma Réplica de Rifle de Ar de Altaforja, uma lembrança em homenagem às renomadas tradições de armas de fogo da capital anã. Enquanto montanheses e atiradores anões carregam um poder de fogo mortal por Dun Morogh, réplicas como esta celebram o trabalho intrincado nos canos e os mecanismos pneumáticos aperfeiçoados pelos artesãos de Altaforja."}},faq={{q="Quem enviou este pacote?",a="O mensageiro ou remetente original nunca deixou um nome ou explicação. De acordo com o destinatário que o guardava, alguém simplesmente entregou o pacote endereçado especificamente a você, insistiu que você eventualmente chegaria para buscá-lo e desapareceu antes que qualquer pergunta pudesse ser feita.",al={"quem enviou o pacote","remetente do rifle de ar","quem deixou o rifle"}},{q="O que quase foi feito com o pacote?",a="Se você não tivesse chegado a tempo, o pacote teria sido jogado no mar junto com o lixo da noite. O zelador admitiu que não administra um serviço de armazenamento e rotineiramente descarta entulhos indesejados no oceano.",al={"o que ia acontecer com o pacote","lixo no mar","pacote jogado fora"}},{q="O que há dentro da encomenda?",a="O pacote contém uma Réplica de Rifle de Ar de Altaforja, entregue como um item de legado destinado especificamente a você. Ele serve como uma peça comemorativa representando o design anão de armas de fogo.",al={"o que há dentro do pacote","conteúdo da réplica do rifle","recompensa do pacote"}},{q="Por que o zelador estava guardando o pacote?",a="Quem o guardava deixou claro que não oferece serviços de retenção de correspondência ou armazenamento. A encomenda só foi guardada porque o mensageiro misterioso saiu com tanta pressa que não houve oportunidade de recusar a entrega antes que ele desaparecesse.",al={"por que guardaram","guardar correspondência","este lugar guarda pacotes"}},{q="Por que isso é considerado uma recompensa de legado?",a="As recompensas de legado em WoW Forever representam reconhecimentos especiais e encomendas deixadas por benfeitores misteriosos para aventureiros experientes, aguardando em postos avançados designados para serem resgatadas após a sua chegada.",al={"por que se chama recompensa de legado","história da recompensa de legado","o que significa legado aqui"}},{q="O rifle de réplica é uma arma funcional?",a="É especificamente mencionado como uma réplica de um rifle de ar de Altaforja, criado à semelhança das armas de longo alcance anãs finamente projetadas, em vez de ser um rifle de batalha de linha de frente.",al={"o rifle é uma arma de verdade","é possível atirar com ele","função da réplica"}}},fp="42,168,29.255.0,32.291.0,22.195.0,36.168.0,26.103.0,42.125.0,39.132.0,41.142.0"}
P.entries["quest:96390"] = {n="Cortando o mal pela raiz",s="Cortando o mal pela raiz é uma missão sob a direção de Earthseer Farsen para eliminar espiões Ferro Negro infiltrados em Dun Morogh. Os agentes clandestinos foram vistos à espreita perto do Complexo de Bandaferro, ameaçando a segurança da terra natal dos Barbabronze.",h="Cortando o mal pela raiz é uma missão sob a direção de Earthseer Farsen para eliminar espiões Ferro Negro...",kw={"mapa ferro negro","espião ferro negro","dun morogh","earthseer farsen","salão dos thanes","complexo de bandaferro","cortando o mal pela raiz","underground map"},ang={["faction:Alliance"]="Neutralizar batedores inimigos em Dun Morogh mantém as linhas vitais de suprimento de Altaforja e os postos avançados vizinhos a salvo de sabotagens.",["race:Dwarf"]="Para os anões Barbabronze, expurgar infiltrados Ferro Negro de suas montanhas ancestrais é uma questão de defesa do lar e de vingança duradoura entre clãs."},sec={{t="Olhos no Frio",b="Dun Morogh há muito tempo serve como um santuário fortificado para os anões de Altaforja, mas a antiga inimizade entre os clãs anões nunca dorme de verdade. Infiltrados Ferro Negro passaram pelas passagens altas e pelos penhascos nevados, rondando suspeitosamente perto de escavações e assentamentos vitais. Earthseer Farsen reconhece que mesmo alguns observadores ocultos podem prenunciar um ataque devastador, convocando defensores convictos da Aliança para erradicá-los antes que seus planos se concretizem."},{t="Ameaça Perto do Complexo de Bandaferro",b="Os espiões concentraram sua vigilância ao redor do Complexo de Bandaferro, um local importante no leste de Dun Morogh. Embora Farsen não consiga discernir de imediato os motivos exatos deles, abater os agentes secretos revela provas físicas de seus planos mais amplos. Vasculhar os batedores derrotados revela um Underground Map, confirmando que a invasão não é uma simples expedição de reconhecimento, mas uma preparação ligada a antigos segredos subterrâneos como o Salão dos Thanes."}},faq={{q="Quem oferece a missão Cortando o mal pela raiz?",a="A missão é oferecida por Earthseer Farsen após a tarefa Farsen's Watch, pedindo ajuda para lidar com invasores em Dun Morogh.",al={"quem dá a missão cortando o mal pela raiz","quem começa cortando o mal pela raiz","missão de farsen"}},{q="Por que há espiões Ferro Negro em Dun Morogh?",a="O clã Ferro Negro trama constantemente contra seus primos Barbabronze. Infiltrar-se no leste de Dun Morogh permite que seus agentes vigiem assentamentos e escavem ou façam o reconhecimento de passagens subterrâneas sepultadas perto do Complexo de Bandaferro.",al={"por que espiões ferro negro estão aqui","o que os ferro negro estão fazendo em dun morogh","espiões ferro negro de bandaferro"}},{q="Onde estão localizados os espiões Ferro Negro?",a="Eles estão concentrados a leste, perto do Complexo de Bandaferro, na parte oriental de Dun Morogh, vigiando a partir do perímetro nevado.",al={"localização dos espiões","onde estão os espiões ferro negro","onde encontrar espiões"}},{q="O que leva a esta tarefa?",a="Esta incumbência vem logo após você se apresentar para Farsen's Watch, elevando as medidas defensivas da mera observação para a erradicação ativa.",al={"pré-requisito da missão","o que vem antes de cortando o mal pela raiz","pré-missão cortando o mal pela raiz"}},{q="O que é descoberto ao caçar esses espiões?",a="Espiões abatidos concedem um Mapa Ferro Negro, que inicia a missão Underground Map e aponta para segredos mais profundos ligados ao Salão dos Thanes.",al={"o que cai dos espiões","saque mapa ferro negro","próxima missão depois de cortando o mal pela raiz"}},{q="Quem é Earthseer Farsen?",a="Earthseer Farsen é um anão atento posicionado em Dun Morogh que monitora movimentos sísmicos incomuns e atividades hostis de clãs pelas montanhas nevadas.",al={"quem é farsen","história de earthseer farsen"}}},fx={bdd12e65={q="Por que o Vidente da Terra Farsen quer que os espiões Ferro Negro sejam tratados?",a="O Vidente da Terra Farsen sabe que qualquer ponto de apoio Ferro Negro em Dun Morogh significa perigo para Altaforja e as terras ao redor. Embora seus motivos precisos permaneçam obscuros para ele, permitir que infiltrados operem sem controle convida a uma sabotagem maior ou a um ataque aberto. Ele quer esmagar a presença deles imediatamente antes que qualquer esquema que estejam preparando crie raízes.",al={"por que farsen quer os espiões mortos","motivação do vidente da terra farsen","por que impedir no início"}}},fp="18,154,16.267.0,31.310.1,40.98.0,38.177.0,38.99.0,26.113.0,44.122.1,24.127.0"}
P.entries["quest:96391"] = {n="Mapa subterrâneo",s="Recuperado de espiões infiltrados perto do Complexo de Bandaferro, o Mapa subterrâneo revela redes clandestinas de túneis que se abrem caminho em direção às raízes de Altaforja. Suas runas irregulares de Ferro Negro delineiam uma rota subterrânea furtiva perfurando diretamente em direção a câmaras antigas sob a montanha. Entregá-lo ao Clarividente Farsen marca o primeiro passo para desvendar uma invasão iminente por baixo.",h="Recuperado de espiões infiltrados perto do Complexo de Bandaferro, o Mapa subterrâneo revela redes...",kw={"mapa ferro negro","dun morogh","clarividente farsen","salão dos thanes","complexo de bandaferro","altaforja","underground map"},ang={["class:Shaman"]="A sutil rajada de vento que guia você até o Clarividente Farsen sugere espíritos elementais alertando sobre escavações subterrâneas anormais sob Dun Morogh.",["faction:Alliance"]="Neutralizar esta rota de infiltração subterrânea é essencial para preservar a segurança de Altaforja e o ponto de apoio setentrional da Aliança.",["race:Dwarf"]="Para os anões Barbabronze, descobrir túneis dos Ferro Negro cortando diretamente em direção aos alicerces de Altaforja é uma violação grave da integridade territorial da capital."},sec={{t="Uma Planta da Infiltração",b="O pergaminho recuperado dos espiões Ferro Negro perto do Complexo de Bandaferro exibe um labirinto complexo de caminhos subterrâneos. Inscritos em runas ríspidas e irregulares exclusivas do clã Ferro Negro, os diagramas mapeiam passagens subterrâneas profundas que convergem diretamente sob Altaforja. As passagens convergentes sugerem uma possível ameaça sob a capital Barbabronze, mas as anotações em Ferro Negro do mapa permanecem incertas."},{t="Sussurros ao Vento",b="Ao estudar a cartografia rudimentar, uma rajada de vento anormal carrega o murmúrio tênue de uma voz anã, incitando uma ação rápida. A indicação mística aponta direto para o Clarividente Farsen. Relatar essa informação expõe movimentações iniciais em direção aos salões antigos selados nas profundezas sob a cidade, ameaçando o santuário do reino da montanha."}},faq={{q="De onde veio este mapa subterrâneo?",a="O mapa é carregado por espiões Ferro Negro que vigiam o perímetro do Complexo de Bandaferro em Dun Morogh. Ele pode ser encontrado ao lidar com seus batedores nas encostas.",al={"saque do mapa","onde encontrar mapa","como obter underground map"}},{q="O que o mapa mostra?",a="Ele delineia uma complexa rede de rotas subterrâneas e túneis que serpenteiam pela terra, todos convergindo diretamente sob a cidade de Altaforja.",al={"o que está no mapa","detalhes do mapa","objetivo do mapa ferro negro"}},{q="Quem é o Clarividente Farsen?",a="O Clarividente Farsen é um clarividente da terra anão do Ninho da Águia sintonizado com as rochas profundas e com os espíritos da montanha. Sentindo os movimentos subterrâneos anormais, ele precisa do mapa para avaliar a brecha sob Altaforja.",al={"onde fica farsen","quem é farsen","clarividente da terra"}},{q="Por que os Ferro Negro estão cavando túneis sob Altaforja?",a="O mapa sugere uma possível rota sob Altaforja, mas suas anotações em Ferro Negro não foram decifradas. O Clarividente Farsen precisa examiná-lo antes que o plano possa ser estabelecido.",al={"por que ferros negros cavam túneis","trama ferro negro dun morogh"}},{q="A que leva esta missão?",a="Entregar este mapa ao Clarividente Farsen dá início ao esforço de investigação nas profundezas sob a cidade, levando diretamente à Incursão na Antiga Altaforja e abrindo acesso ao Salão dos Thanes.",al={"continuação de underground map","próxima missão após underground map"}},{q="Em que idioma estão escritas as runas do mapa?",a="O mapa utiliza a escrita rúnica irregular dos anões Ferro Negro. A pessoa que o encontra não pode ter certeza do que dizem as anotações.",al={"runas do mapa","idioma ferro negro"}}},fx={["1c73103d"]={q="Por que o Mapa Ferro Negro deve ser levado ao Vidente da Terra Farsen?",a="O mapa detalha uma rede alarmante de túneis e estradas subterrâneas que convergem diretamente abaixo de Altaforja. Suas runas Ferro Negro irregulares exigem tradução, e a voz anã sinistra carregada pelo vento deixa claro que o Vidente da Terra Farsen deve inspecionar a possível ameaça subterrânea imediatamente para alertar o reino montanhoso sobre a ameaça subterrânea.",al={"por que levar mapa para farsen","motivação do mapa ferro negro","por que entregar o mapa"}}},fp="15,270,27.360.0,20.309.1,41.148.0,23.127.0,24.205.0,49.168.0,29.182.1,45.115.0"}
P.entries["quest:96392"] = {n="A visão de Farsen",s="A visão de Farsen é uma tarefa de observação concedida pelo Vidente da Terra Farsen, um xamã Martelo Feroz visitante posicionado bem acima da Pedreira Gol'Bolar. Usando a clarividência xamânica do vidente da terra, os aventureiros testemunham em primeira mão a crescente infiltração dos anões Ferro Negro no coração de Dun Morogh. Esta vigilância crucial marca um passo inicial no caminho em direção ao Salão dos Thanes.",h="A visão de Farsen é uma tarefa de observação concedida pelo Vidente da Terra Farsen, um xamã Martelo Feroz...",kw={"ninho da águia","ferro negro","dun morogh","vidente da terra","farsen","clarividência","gol'bolar","salão dos thanes","martelo feroz"},ang={["class:Shaman"]="Os videntes da terra dos Martelo Feroz demonstram a visão telúrica e espiritual de sua tradição, oferecendo um vislumbre do xamanismo anão enraizado nos penhascos do Ninho da Águia.",["faction:Alliance"]="Descobrir as tramas dos Ferro Negro em Dun Morogh é vital para preservar a segurança de Altaforja e das passagens montanhosas circundantes para todas as viagens da Aliança.",["race:Dwarf"]="Para os defensores Barbabronze, receber um aviso de um primo do Ninho da Águia destaca o quão descarada se tornou a infiltração dos Ferro Negro em sua terra natal."},sec={{t="Olhos Através da Crista",b="Empoleirado acima da escavação castigada pela neve da Pedreira Gol'Bolar, o Vidente da Terra Farsen mantém uma vigilância atenta sobre os trechos inferiores de Dun Morogh. Tendo viajado para o sul a partir dos penhascos do Ninho da Águia, o visitante Martelo Feroz traz uma profunda percepção espiritual para terras normalmente patrulhadas por montanheses de Altaforja. Em vez de depender de batedores comuns, Farsen usa as artes tradicionais de seu clã para monitorar estrondos subterrâneos e movimentações inesperadas ao longo das encostas."},{t="Uma Visão Emprestada",b="Para convencer os viajantes do perigo iminente, Farsen lhes empresta sua clarividência — uma dádiva xamânica que projeta a consciência de alguém por vastas distâncias. Olhando através da lente espiritual, torna-se evidente que os problemas de Dun Morogh vão muito além de troggs indisciplinados e feras selvagens. Anões Ferro Negro esgueiraram-se para perto do centro industrial de Altaforja, entrincheirando-se para uma operação que exige confronto imediato antes que crie raízes."}},faq={{q="Quem é o Vidente da Terra Farsen?",a="O Vidente da Terra Farsen é um anão Martelo Feroz que visita Dun Morogh vindo do Ninho da Águia, nas Terras Agrestes. Como vidente da terra, ele domina a magia xamânica que lhe permite sentir perturbações na terra e observar ameaças de longe.",al={"vidente da terra farsen","quem é farsen","farsen martelo feroz"}},{q="Onde essa vigilância está acontecendo?",a="O Vidente da Terra Farsen está posicionado com vista para a Pedreira Gol'Bolar, uma importante escavação mineradora dos Barbabronze localizada no leste de Dun Morogh.",al={"localização de farsen","onde fica farsen","mirante da pedreira"}},{q="Qual ameaça Farsen revela?",a="Através de sua clarividência xamânica, Farsen revela que anões Ferro Negro hostis estabeleceram uma posição estratégica nas proximidades, representando uma ameaça ativa e perigosa para a região.",al={"o que a clarividência mostra","ameaça ferro negro","visão de farsen"}},{q="Como isso se conecta ao Salão dos Thanes?",a="Investigar a presença dos Ferro Negro identificada durante A visão de Farsen dá início à cadeia maior de tarefas necessárias para os aventureiros que buscam entrar no Salão dos Thanes.",al={"harmonização do salão dos thanes","série de missões do salão dos thanes"}},{q="Por que um anão Martelo Feroz está envolvido na defesa de Dun Morogh?",a="Embora os Martelo Feroz chamem as Terras Agrestes de lar, laços de parentesco e a inimizade compartilhada contra os Ferro Negro ocasionalmente trazem viajantes como Farsen às terras ancestrais dos Barbabronze em Dun Morogh.",al={"por que o martelo feroz está aqui","anão de ninho da águia em dun morogh"}},{q="O que vem logo após a conclusão de A visão de Farsen?",a="Depois de você testemunhar a infiltração dos Ferro Negro através de sua visão, Farsen o impulsiona a seguir em frente com a tarefa 'Nip 'Em in the Bud' para reprimir ativamente o avanço inimigo.",al={"próxima missão","o que vem depois de farsen's watch","nip em in the bud"}}},fx={["73fc96dc"]={q="Por que o Vidente da Terra Farsen quer que isso seja feito?",a="Enquanto viajava por Dun Morogh vindo do Ninho da Águia, o Vidente da Terra Farsen avistou sinais de agressão dos anões Ferro Negro se aproximando perto da Pedreira Gol'Bolar. Antes de agir ou levantar alarmes, o xamã quer que você testemunhe o perigo iminente em primeira mão através de sua magia de visão distante, garantindo que os defensores de Altaforja compreendam a verdadeira extensão da infiltração hostil antes que ela saia do controle.",al={"por que a vigília de farsen","motivação de farsen","por que farsen quer que eu observe"}}},fp="14,184,21.288.0,17.291.0,24.181.0,33.98.0,31.105.0,44.136.0,59.184.0,52.143.0"}
P.entries["quest:96393"] = {n="Old Ironforge Incursion",s="Sob Altaforja, Earthseer Farsen envia você ao Salão dos Thanes para a última parte da investigação. Lá, você enfrenta a ameaça dos Ferro Negro e se apresenta ao Rei Magni Barbabronze.",h="Sob Altaforja, Earthseer Farsen envia você ao Salão dos Thanes para a última parte da investigação.",kw={"ferro negro","dirgehammer","farsen","incursão","altaforja","kharanos","magni","thanes"},ang={["faction:Alliance"]="Como membro da Aliança, você ajuda a deter uma incursão que ameaça lançar um ataque surpresa devastador contra a principal fortaleza da sua facção nos Reinos do Leste.",["race:Dwarf"]="Como anão, você sabe que infiltrados dos Ferro Negro violaram sua fortaleza ancestral nas câmaras esquecidas sob a Sala do Trono."},sec={{t="Invadindo as Câmaras",b="O mapa subterrâneo revela os movimentos dos Ferro Negro, e Earthseer Farsen identifica o mentor da invasão. A entrada do Salão dos Thanes fica nas profundezas dos antigos salões de pedra da Antiga Altaforja. Enquanto a cidade acima cuida dos assuntos da superfície, forças dos Ferro Negro se infiltram em cavernas adormecidas sob o reino."},{t="O comandante Durgen Dirgehammer",b="Earthseer Farsen traduz documentos capturados dos Ferro Negro e revela o nome do comandante: Durgen Dirgehammer. Nas profundezas das câmaras inferiores, Durgen ameaça o coração do reino montanhoso dos Bronzebeard. Encontre-o, derrote-o e leve sua cabeça decepada ao Rei Magni Barbabronze, na cidade acima."},{t="Audiência com o Rei",b="A cabeça de Durgen Dirgehammer confirma ao Rei Magni Barbabronze a ameaça dos Ferro Negro sob as antigas raízes da cidade. Você leva a prova da vitória e uma saudação pessoal de Farsen, velho amigo de Magni. A investigação termina com Magni ciente do que espreita nas profundezas."}},faq={{q="O que é Old Ironforge Incursion?",a="Earthseer Farsen envia você ao Salão dos Thanes, sob a Antiga Altaforja, para enfrentar o comandante dos Ferro Negro, Durgen Dirgehammer. É a última etapa de uma investigação sobre a atividade dos Ferro Negro sob Dun Morogh.",al={"missão old ironforge incursion","missão durgen dirgehammer"}},{q="Onde acontece esta missão?",a="Você entra no Salão dos Thanes, uma câmara antiga nas profundezas da rocha sob a Antiga Altaforja e a capital montanhosa.",al={"onde fica o salão dos thanes","localização do salão dos thanes"}},{q="Quem é Durgen Dirgehammer?",a="Durgen Dirgehammer comanda a incursão dos Ferro Negro no Salão dos Thanes, sob a Antiga Altaforja. Earthseer Farsen descobriu seu nome em documentos recuperados dos Ferro Negro.",al={"quem é dirgehammer","durgen dirgehammer"}},{q="Quem oferece a missão e quem a recebe?",a="Depois que você recupera o Underground Map, Earthseer Farsen envia você ao Rei Magni Barbabronze em Altaforja.",al={"quem oferece old ironforge incursion","quem entrega old ironforge incursion"}},{q="Como começo a sequência de missões que leva a esta?",a="Comece com A Visitor to Dun Morogh, oferecida por Beldin Gradaço nos arredores de Kharanos, em Dun Morogh.",al={"como começar a missão do salão dos thanes","início de a visitor to dun morogh"}},{q="Qual é a ligação entre Earthseer Farsen e o Rei Magni?",a="Earthseer Farsen se considera um velho amigo do Rei Magni Barbabronze. Ele pede que você transmita suas saudações pessoais ao apresentar a cabeça de Durgen Dirgehammer na sala do trono.",al={"farsen e magni","história de earthseer farsen"}}},fx={bdae81a8={q="Por que o Vidente da Terra Farsen quer que Durgen Dirgehammer seja morto?",a="Farsen descobriu movimentos inimigos abaixo da montanha e decifrou ordens que apontam Durgen Dirgehammer como o comandante liderando a incursão na Antiga Altaforja. A presença dos Ferro Negro no antigo Salão dos Thanes ameaça diretamente a capital anã por baixo. Ao enviar você para derrotar o líder deles, Farsen pretende destruir o ataque antes que os Ferro Negro consigam se entrincheirar, enquanto envia uma prova inegável da ameaça diretamente ao Rei Magni Barbabronze.",al={"motivo de farsen","por que matar durgen dirgehammer","por que farsen envia você"}},["664606f0"]={q="Para que serve a Cabeça de Durgen Dirgehammer?",a="Você precisa da Cabeça de Durgen Dirgehammer como prova absoluta para o Rei Magni Barbabronze de que o comandante do ataque subterrâneo foi eliminado. Entregar o troféu macabro diretamente na sala do trono confirma que a força de ataque hostil dos Ferro Negro no Salão dos Thanes perdeu seu líder e carrega o aviso pessoal do Vidente da Terra Farsen ao rei.",al={"uso da cabeça de durgen dirgehammer","por que levar a cabeça de durgen","cabeça de durgen dirgehammer"}}},fp="23,182,20.333.0,18.279.1,22.260.1,32.210.0,33.116.0,26.168.0,41.105.0,50.96.0,63.179.0"}
P.entries["quest:96394"] = {n="The Restless Dead",s="The Restless Dead aborda uma perturbação alarmante nas criptas do Salão dos Thanes, onde antigos espíritos de anões foram despertados de seu descanso. Com os zeladores apavorados demais para entrar nas câmaras subterrâneas, um aventureiro deve descer às catacumbas para fazer os fantasmas enfurecidos e o espírito de Sidermar voltarem a dormir.",h="The Restless Dead aborda uma perturbação alarmante nas criptas do Salão dos Thanes, onde antigos espíritos de...",kw={"sidermar","tumbas dos anões","espíritos dos anões","enraged apparitions","fantasmas","salão dos thanes","espírito de sidermar","the restless dead","tormented souls"},ang={["class:Priest"]="Espíritos que permanecem em tormento ou ira são um chamado direto ao dever para aqueles que comungam com almas e guiam mortos perturbados rumo ao descanso pacífico.",["faction:Alliance"]="Proteger as criptas ancestrais sob Altaforja garante que os guardiões possam manter seus deveres sagrados sem medo de serem subjugados por aparições vingativas.",["race:Dwarf"]="O Salão dos Thanes abriga os mortos honrados e os ancestrais do povo anão, tornando sua agitação repentina e violenta uma perturbação inquietante bem no coração de sua herança."},sec={{t="Perturbação nas Câmaras Profundas",b="Nas profundezas abaixo da superfície, no Salão dos Thanes, criptas ancestrais abrigam gerações de mortos honrados. Normalmente descansando em um sono tranquilo, os espíritos foram violentamente agitados por uma perturbação invisível nas câmaras subterrâneas. Ruídos estranhos ecoando lá de baixo assustaram os zeladores do local, que se recusam a entrar nas câmaras inferiores para cumprir seus deveres até que a ordem seja restaurada. Aventureiros são convocados a descer aos salões sombrios de pedra e acalmar as almas agitadas."},{t="Acalmando os Ancestrais",b="Os espíritos que descansam no Salão dos Thanes têm um sono notoriamente leve. Qualquer que tenha sido o evento ou presença que abalou as tumbas inferiores, agitou ondas de Enraged Apparitions e Tormented Souls, transformando solo sagrado em um refúgio perigoso. Entre os despertados está o reverenciado espírito de Sidermar, exigindo uma mão respeitosa, porém firme, para conter a fúria dos ancestrais despertados e devolver a paz às catacumbas."}},faq={{q="Sobre o que é a missão The Restless Dead?",a="The Restless Dead é uma tarefa concedida para investigar e conter uma onda de perturbações fantasmagóricas sob o Salão dos Thanes. Alguém ou algo assustou os espíritos sepultados, deixando os guardiões apavorados demais para entrar nas câmaras subterrâneas até que se lide com as aparições.",al={"o que é the restless dead","o que é esta missão","visão geral da missão the restless dead"}},{q="Por que os espíritos despertaram?",a="Uma perturbação desconhecida nas profundezas das câmaras subterrâneas acordou os mortos sepultados. Como os espíritos no Salão dos Thanes são descritos como tendo sono leve, o que quer que tenha acontecido lá embaixo nas tumbas os assustou, lançando-os em um frenesi de raiva e tormento.",al={"por que os fantasmas estão com raiva","quem perturbou as tumbas","por que as aparições estão acordadas"}},{q="Onde ocorre essa perturbação?",a="O distúrbio está concentrado nas profundezas das criptas e câmaras do Salão dos Thanes, um local de descanso ancestral sob Altaforja onde antigos espíritos anões jazem sepultados.",al={"onde fica o salão dos thanes","onde os restless dead surgem","localização do salão dos thanes"}},{q="Quem é o espírito de Sidermar?",a="O espírito de Sidermar é uma alma antiga e proeminente que descansa nas tumbas profundas do Salão dos Thanes. Ao lado de aparições menores, esse grande espírito foi despertado de seu sono e deve ser devolvido ao descanso pacífico.",al={"quem é o espírito de sidermar","história do espírito de sidermar","quem é o fantasma de sidermar"}},{q="Por que os guardiões precisam da ajuda de um aventureiro?",a="Os guardiões são zeladores encarregados de cuidar das criptas e desempenhar suas funções habituais no Salão dos Thanes. Com espíritos furiosos vagando pelos corredores, eles se recusam a descer às câmaras subterrâneas inferiores até que a ameaça seja eliminada.",al={"quem são os guardiões","por que os guardiões precisam de ajuda","guardiões do salão dos thanes"}},{q="Quais espíritos assombram o Salão dos Thanes?",a="As câmaras subterrâneas perturbadas são assombradas por Enraged Apparitions, Tormented Souls e pelo próprio venerável espírito de Sidermar, todos sobressaltados em uma vigília agressiva dentro das câmaras fúnebres.",al={"que tipos de fantasmas estão lá embaixo","aparições no salão dos thanes","tipos de restless dead"}}},fp="17,207,30.381.0,22.328.1,38.153.0,30.187.0,39.152.0,30.182.0,45.190.0,38.169.0"}
P.entries["quest:96395"] = {n="Uma mágoa ancestral",s="Nas profundezas do histórico Salão dos Thanes, um assistente etéreo suplica pelo fim do tormento de um governante caído. O espírito de Faldrim Sidermar permanece, consumido por um antigo ressentimento e privado da paz eterna. Os aventureiros recebem a missão de conceder o descanso ao thane inquieto.",h="Nas profundezas do histórico Salão dos Thanes, um assistente etéreo suplica pelo fim do tormento de um...",kw={"uma mágoa ancestral","sidermar","fantasma de anão","faldrim sidermar","assistente fantasmagórico","salão dos thanes","espírito inquieto","thane"},ang={["class:Paladin"]="Dar descanso a uma alma atormentada é um dever solene para guerreiros sagrados que juraram trazer paz aos mortos que sofrem.",["class:Priest"]="Sacerdotes compreendem que mágoas persistentes e pesares não redimidos podem prender um espírito mortal ao reino físico muito depois de o corpo ter virado pó.",["race:Dwarf"]="Para os anões, confrontar um thane inquieto de seu próprio povo é um lembrete austero de que uma mágoa ancestral pode durar mais do que a própria morte."},sec={{t="Um apelo vindo do túmulo",b="Dentro das abóbadas de pedra do Salão dos Thanes, a morte não oferece alívio imediato. Um assistente fantasmagórico de Faldrim Sidermar permanece ali, mal conseguindo reunir forças para falar através do véu mortal. Em vez de buscar a própria libertação, a única preocupação do fantasma é seu mestre, implorando aos viajantes que acalmem o espírito turbulento do thane."},{t="O peso do passado",b="A morte não libertou Faldrim Sidermar do passado. Preso ao mundo físico por uma mágoa ancestral e consumidora, o fantasma de Faldrim continua agitado e hostil, incapaz de encontrar o repouso até receber uma libertação forçada."}},faq={{q="Quem é Faldrim Sidermar?",a="Faldrim Sidermar foi um thane anão cuja aparição inquieta agora assombra o Salão dos Thanes. Seu Assistente Fantasmagórico afirma que ele está consumido por uma mágoa ancestral e não consegue descansar. A missão não diz mais nada sobre sua vida ou linhagem.",al={"história de faldrim sidermar","quem é faldrim","thane sidermar"}},{q="Onde fica o Salão dos Thanes?",a="O Salão dos Thanes fica nas cavernas sob Antiga Altaforja, dentro da capital anã de Altaforja.",al={"localização do salão dos thanes","onde fica o salão dos thanes","entrada do salão dos thanes"}},{q="Por que o fantasma de Faldrim Sidermar é hostil?",a="Segundo o assistente fantasmagórico, o antigo thane está consumido por uma mágoa ancestral. A história dos anões é repleta de séculos de rivalidades entre clãs, e o ódio persistente de Faldrim impede que seu espírito parta para um repouso tranquilo.",al={"por que faldrim está com raiva","por que o thane está atacando","explicação de mágoa ancestral"}},{q="Quem concede a missão Uma mágoa ancestral?",a="A missão é concedida por um Assistente Fantasmagórico encontrado dentro do Salão dos Thanes. Preso em servidão mesmo após a morte, o assistente busca apenas a paz para seu antigo mestre.",al={"quem inicia uma mágoa ancestral","missão do assistente fantasmagórico","concedente da missão"}},{q="O que você deve fazer para completar a missão?",a="Você deve confrontar o espírito de Faldrim Sidermar dentro do Salão dos Thanes, derrotar seu fantasma inquieto em combate para libertá-lo de seu tormento e prestar contas ao Assistente Fantasmagórico.",al={"como terminar uma mágoa ancestral","dar descanso a faldrim","objetivo de uma mágoa ancestral"}},{q="Faldrim tem relação com o vilarejo de Sidermar?",a="Isso ainda não se sabe. Faldrim compartilha seu nome com o assentamento de Sidermar no Vale Cristálgida, mas a missão não menciona nada sobre sua família ou qualquer ligação com o vilarejo.",al={"faldrim é de sidermar","conexão entre sidermar e vale cristálgida","família sidermar"}}},fp="17,147,21.261.0,22.169.1,24.167.0,36.98.0,45.151.0,38.91.0,39.160.0,43.164.0"}
P.entries["quest:96403"] = {n="Important Heirlooms",s="Important Heirlooms é uma missão em que um aventureiro ajuda um gnomo nervoso chamado Thom, que foi flagrado à espreita no Salão dos Thanes quando anões Ferro Negro invadiram os cofres em máquinas-toupeira subterrâneas. A tarefa envolve recuperar relíquias anãs espalhadas sob o pretexto duvidoso de preservação histórica.",h="Important Heirlooms é uma missão em que um aventureiro ajuda um gnomo nervoso chamado Thom, que foi flagrado...",kw={"ferrostil","relíquias de família dos anões","gnomo","salão dos thanes","important heirlooms","máquina-toupeira","thom","cofres"},ang={["class:Rogue"]="Um ladino percebe facilmente a desculpa esfarrapada de Thom de \\\"patrulhar\\\" os cofres, reconhecendo um colega saqueador pego de surpresa por uma invasão subterrânea.",["race:Dwarf"]="Aventureiros anões podem encarar o repentino interesse de Thom em resgatar relíquias ancestrais com profundo ceticismo, especialmente considerando seus atos falhos a respeito de saques e avaliações.",["race:Gnome"]="A natureza oportunista de Thom e seus disfarces desajeitados evidenciam um lado pouco erudito da curiosidade dos gnomos quando relíquias valiosas estão em jogo."},sec={{t="Problemas nos cofres",b="Ao explorar os cofres subterrâneos do Salão dos Thanes, um gnomo empreendedor chamado Thom foi interrompido pela chegada repentina de anões Ferro Negro que cavavam para a superfície em máquinas-toupeira. Incapaz de proteger a área sozinho, Thom recruta aventureiros que passam pelo local para desbravar o sítio de escavação hostil e recuperar relíquias anãs valiosas espalhadas pelas câmaras antes que os invasores as tomem ou destruam."},{t="Preservação cultural ou pilhagem lucrativa?",b="Apesar da insistência de Thom de que estava apenas patrulhando e deseja catalogar as relíquias para preservação, seus constantes deslizes ao falar em \\\"saque de valor inestimável\\\" e \\\"avaliar a pilhagem\\\" sugerem motivos muito mais egoístas. Os aventureiros são generosamente compensados por sua bravura, embora continue sendo uma incógnita se esses antigos tesouros anões algum dia verão um museu ou um leilão."}},faq={{q="Quem é Thom?",a="A missão é concedida por Thom, um gnomo empreendedor encontrado perto dos cofres. Seus deslizes nervosos ao falar sugerem que ele está muito mais interessado em pilhagens lucrativas do que na segurança legítima dos cofres.",al={"quem dá a missão","quem é thom","dador da missão"}},{q="O que é o Salão dos Thanes?",a="O Salão dos Thanes é um cofre subterrâneo anão que contém relíquias culturais e heranças antigas, recentemente invadido por forças subterrâneas Ferro Negro.",al={"o que é salão dos thanes","onde fica salão dos thanes"}},{q="Por que anões Ferro Negro estão nos cofres?",a="Uma força de ataque de anões Ferro Negro invadiu os cofres diretamente das profundezas usando máquinas-toupeira escavadoras, mergulhando a área no caos por motivos desconhecidos.",al={"por que ferrostil está lá","máquinas-toupeira ferrostil"}},{q="Thom está realmente devolvendo as relíquias de família?",a="Thom se trai constantemente, referindo-se a esgueirar-se como \\\"patrulhar\\\", a relíquias de família como \\\"saque\\\" e \\\"pilhagem\\\", e a catalogar como \\\"avaliar\\\". Embora ele pague a recompensa prometida, suas alegações de devolver as relíquias a locais de honra são altamente suspeitas.",al={"thom está mentindo","thom rouba","thom é confiável"}},{q="O que são as Dwarven Heirlooms?",a="São antigas relíquias culturais anãs abrigadas no Salão dos Thanes, consideradas tesouros de valor inestimável por historiadores — e saques lucrativos por oportunistas como Thom.",al={"o que são as relíquias de família","história das relíquias de família dos anões"}},{q="Por que Thom não consegue recuperar as relíquias de família sozinho?",a="Thom foi pego de surpresa pela chegada repentina de máquinas-toupeira Ferro Negro enquanto estava à espreita nos cofres, deixando-o incapaz de saquear as relíquias sozinho com segurança sem a proteção de um aventureiro.",al={"por que thom precisa de ajuda","por que ajudar thom"}}},fp="19,189,21.287.0,43.264.1,12.166.0,27.132.0,40.97.0,39.165.0,31.151.0,46.152.0"}
P.entries["quest:96408"] = {n="Um visitante em Dun Morogh",s="Um visitante em Dun Morogh é uma tarefa investigativa oferecida por Beldin Gradaço nos arredores de Kharanos. Os montanhistas relataram uma fogueira desconhecida no alto dos penhascos com vista para a Pedreira Gol'Bolar, levando um batedor a verificar se o estranho representa uma ameaça aos anões locais.",h="Um visitante em Dun Morogh é uma tarefa investigativa oferecida por Beldin Gradaço nos arredores de Kharanos.",kw={"beldin gradaço","dun morogh","earthseer farsen","farsen's watch","pedreira gol'bolar","salão dos thanes","kharanos","visitante"},ang={["class:Shaman"]="Encontrar Earthseer Farsen conecta-se diretamente à comunhão espiritual com as pedras da montanha, uma visão rara nas terras altas nevadas de Dun Morogh.",["faction:Alliance"]="Ajudar os montanhistas locais nos arredores de Kharanos garante que as linhas de suprimento e os trabalhadores da pedreira permaneçam a salvo de ameaças imprevistas.",["race:Dwarf"]="Para os anões Barbabronze, monitorar observadores indesejados com vista para grandes locais de mineração como Gol'Bolar é uma segurança padrão para proteger as fronteiras de Khaz Modan."},sec={{t="Uma Coluna de Fumaça nas Alturas",b="Os montanhistas de Dun Morogh mantêm vigilância constante sobre os penhascos e vales nevados que cercam Altaforja. Quando uma fogueira surgiu repentinamente bem acima da Pedreira Gol'Bolar, isso chamou a atenção em Kharanos. Beldin Gradaço, preocupado com o acampamento incomum situado diretamente acima de uma escavação anã vital, recruta viajantes para subir as cordilheiras e determinar se o viajante misterioso é benigno ou um invasor."},{t="O Encontro com o Vidente da Terra",b="Investigar a cordilheira revela que o viajante é Earthseer Farsen, um místico que montou acampamento nas alturas varridas pelo vento. Longe de ser um trogg saqueador ou um espião abertamente hostil, esse observador misterioso possui laços espirituais profundos com a terra. Sua presença no precipício com vista para a pedreira dá início a uma jornada para desvendar perturbações mais profundas ocultas sob Khaz Modan, conectando-se, em última análise, ao mistério do Salão dos Thanes."}},faq={{q="Quem envia você para investigar o visitante?",a="Beldin Gradaço, posicionado nos arredores de Kharanos em Dun Morogh, dá a missão depois que montanhistas relatam um fogo desconhecido nas colinas.",al={"quem dá esta missão","início da missão","missão beldin gradaço"}},{q="Onde fica o acampamento misterioso?",a="A fogueira fica no alto das cordilheiras nevadas a leste de Kharanos, empoleirada diretamente com vista para a escavação da Pedreira Gol'Bolar.",al={"localização do acampamento","onde está o visitante","local do visitante"}},{q="Quem é o visitante com vista para a pedreira?",a="O visitante é Earthseer Farsen, um observador espiritual que reside em um acampamento isolado nas alturas acima da pedreira.",al={"quem é farsen","quem é o visitante","earthseer farsen"}},{q="Por que os anões desconfiaram da fogueira?",a="A Pedreira Gol'Bolar é uma operação anã crucial já sob pressão de troggs locais. Qualquer acampamento desconhecido no alto do fosso poderia facilmente pertencer a batedores ou forças hostis observando os movimentos dos anões.",al={"por que suspeito","por que investigar","por que me enviar"}},{q="A que esta missão leva?",a="Apresentar-se a Earthseer Farsen leva diretamente à missão 'Farsen's Watch' e serve como o início da sequência de harmonização do Salão dos Thanes.",al={"o que vem depois","missão seguinte","introdução ao salão dos thanes"}},{q="É preciso lutar contra o estranho no acampamento?",a="Não. Embora Beldin Gradaço prepare você para a possibilidade de violência, o visitante é Earthseer Farsen, um observador pacífico disposto a conversar com você.",al={"o visitante é hostil","devo matar o visitante","luta contra o visitante"}}},fx={["3b0d76fb"]={q="Por que Beldin Gradaço pede a um aventureiro em vez dos Montanhistas?",a="Os Montanhistas locais avistaram a fogueira na encosta de longe, mas suas fileiras estão reduzidas enquanto protegem as estradas, assentamentos e operações de mineração contra troggs e feras selvagens. Como o fogo provavelmente é inofensivo, Beldin confia em um viajante capaz que esteja passando por Kharanos para inspecionar rapidamente a crista, em vez de tirar guardas de seu posto.",al={"por que enviar a mim","por que não enviar guardas","beldin gradaço por que eu"}}},fp="23,167,28.237.0,21.242.1,41.119.0,41.85.0,42.89.1,48.207.0,31.102.1,46.135.1"}
P.entries["quest:965"] = {n="A Torre de Althalaxx",s="Encarregada da defesa de Auberdine, a Sentinela Elissa Brisastral suspeita de transações obscuras nas antigas ruínas ao norte. Ela encarrega aventureiros de encontrar Balthule Umbrataque, um batedor enviado para vigiar a enigmática Torre de Althalaxx que não enviou relatórios conforme o planejado.",h="Encarregada da defesa de Auberdine, a Sentinela Elissa Brisastral suspeita de transações obscuras nas antigas...",kw={"althalaxx","auberdine","balthule umbrataque","costa negra","elissa brisastral","batedor","sentinela","torre"},ang={["faction:Alliance"]="Auberdine serve como o principal ponto de entrada da Aliança no norte de Kalimdor, tornando a defesa de suas estradas e fronteiras ao redor essencial para todos os aliados visitantes.",["race:NightElf"]="As ruínas de Althalaxx permanecem como um lembrete do passado dos altaneiros caídos da antiga Kalimdor, e preservar Auberdine da corrupção que se prolifera naquelas pedras é um dever vital para as sentinelas elfas noturnas."},sec={{t="Um Batedor Desaparecido",b="As sentinelas de Auberdine devem permanecer sempre vigilantes contra os perigos rastejantes de Costa Negra. A Sentinela Elissa Brisastral notou atividades suspeitas ao redor da Torre de Althalaxx, nos confins ao norte da floresta. Ela enviou Balthule Umbrataque para examinar a antiga ruína. Dias se passaram sem notícias do batedor, fazendo com que Elissa procure um viajante disposto a seguir para o norte, localizar Balthule e garantir que ele não tenha encontrado um fim trágico."},{t="Olhos sobre a Ruína",b="A estrada ao norte de Auberdine passa por antigas ruínas Kaldorei e sobre o Rio Fontescarpa antes de alcançar a extensão sombria da torre. Embora impossibilitado de enviar notícias de volta a Auberdine, Balthule sobreviveu à sua vigilância inicial. Ao ser localizado nos bosques ao redor, ele confirma que os instintos de Elissa estavam corretos: eventos sombrios e perturbadores estão em pleno andamento dentro da agulha de pedra em ruínas."}},faq={{q="Quem é a Sentinela Elissa Brisastral?",a="Elissa Brisastral é uma Sentinela elfa noturna posicionada em Auberdine. Ela é encarregada de proteger o assentamento contra ameaças externas em Costa Negra e monitora perigos regionais como a Torre de Althalaxx.",al={"elissa brisastral","quem dá a missão","dador de missões de auberdine"}},{q="Quem é Balthule Umbrataque?",a="Balthule Umbrataque é um batedor enviado pela Sentinela Elissa Brisastral para espionar as misteriosas atividades ao redor da Torre de Althalaxx. Ele mantém uma vigília nos arredores da ruína para acompanhar forças hostis.",al={"balthule","quem é o batedor","umbrataque"}},{q="Onde fica a Torre de Althalaxx?",a="A torre fica no nordeste de Costa Negra. Os viajantes podem chegar até ela seguindo para o leste saindo de Auberdine, seguindo pela estrada do norte após Bashal'Aran e atravessando a ponte sobre o Rio Fontescarpa até que a agulha fique visível.",al={"localização da torre de althalaxx","onde fica a torre","como encontrar althalaxx"}},{q="Por que um batedor foi enviado à torre em primeiro lugar?",a="Elissa enviou Balthule para observar acontecimentos estranhos ao redor da Torre de Althalaxx enquanto cumpria seu dever de proteger Auberdine.",al={"por que vigiar a torre","o que há de errado em althalaxx","por que balthule foi enviado"}},{q="Por que Balthule não retornou a Auberdine?",a="Elissa não recebeu o relatório de Balthule e pede que você vá averiguar o estado dele. Balthule pode explicar sua situação quando você o encontrar.",al={"por que balthule sumiu","balthule está preso","por que balthule ficou"}},{q="Esta série de missões continua?",a="Sim. Localizar Balthule Umbrataque dá início a uma investigação em várias partes sobre as forças sombrias que ocupam a Torre de Althalaxx e suas ambições sinistras em Costa Negra.",al={"esta é uma série de missões","qual missão vem a seguir","série de althalaxx"}}},fx={["895f5562"]={q="Por que a Sentinela Elissa Brisastral quer que isso seja feito?",a="Como uma Sentinela encarregada da defesa de Auberdine, Elissa Brisastral é responsável por proteger a Costa Negra de ameaças invasoras. Ela enviou Balthule Umbrataque para investigar ocorrências suspeitas perto da Torre de Althalaxx, mas ele está muito atrasado. Temendo que ele tenha caído em um perigo inesperado, ela precisa que alguém o localize e confirme que ele está em segurança.",al={"por que encontrar balthule","motivo de elissa brisastral","por que me enviar para a torre de althalaxx"}}},fp="22,173,23.345.0,18.352.1,34.188.0,29.184.0,40.211.0,53.118.0,42.129.0,31.156.0"}
P.entries["quest:966"] = {n="A Torre de Althalaxx",s="Ao investigar atividades suspeitas ao redor da Torre de Althalaxx, no norte de Costa Negra, o batedor Balthule Umbrataque pede ajuda para reunir informações sobre bruxos que estão se agrupando ali. Recuperando pedaços de pergaminhos descartados pelos fanáticos acampados fora das ruínas, ele tenta descobrir a identidade dos sectários e suas intenções sinistras.",h="Ao investigar atividades suspeitas ao redor da Torre de Althalaxx, no norte de Costa Negra, o batedor...",kw={"althalaxx","auberdine","balthule","linhagem das trevas","costa negra","dinis","fanáticos","pergaminho","purificador","umbrataque","bruxos"},ang={["class:Paladin"]="A descoberta de uma seita sombria organizada no norte de Costa Negra ajuda diretamente a cruzada de Dinis, o Purificador, aliado dedicado a expurgar a corrupção vil e demoníaca.",["class:Warlock"]="A Seita da Linhagem das Trevas demonstra que círculos de bruxos sem alinhamento com facções podem ocupar ruínas ancestrais para realizar evocações longe dos olhos vigilantes das autoridades da Aliança e da Horda.",["race:NightElf"]="A profanação da Torre de Althalaxx por sectários sombrios representa mais um ultraje contra o patrimônio ancestral dos elfos noturnos na costa de Kalimdor."},sec={{t="Olhos atentos na costa",b="Balthule Umbrataque vigia o litoral enevoado do norte de Costa Negra, mantendo os olhos na antiga ruína conhecida como Torre de Althalaxx. Enviado para observar o local em nome de Auberdine e alertar Dinis, o Purificador, caso surja algum perigo, Balthule hesita em abandonar seu posto para relatar o que viu. Temendo perder movimentos importantes dos conjuradores sombrios que ocupam as ruínas, ele recorre a viajantes para explorar os acampamentos ao redor."},{t="Decifrando os planos do culto",b="Os seguidores menores que rondam as ruínas carregam pergaminhos e anotações fragmentados. Ao juntar vários pedaços de pergaminhos gastos recuperados desses sectários, Balthule descobre um nome inquietante: Seita da Linhagem das Trevas. Sem nunca ter ouvido falar dessa organização sombria, o batedor percebe que o perigo é mais organizado do que um simples bando de bruxos renegados e exige que Dinis seja avisado imediatamente."}},faq={{q="Quem é Balthule Umbrataque?",a="Balthule Umbrataque é um batedor da Aliança posicionado na estrada perto da Torre de Althalaxx, no norte de Costa Negra. Ele foi enviado para vigiar reuniões suspeitas na torre em nome da liderança de Auberdine e do paladino Dinis, o Purificador.",al={"história de balthule umbrataque","quem é balthule","balthule costa negra"}},{q="O que é a Torre de Althalaxx?",a="A Torre de Althalaxx é uma antiga ruína élfica no norte de Costa Negra. Recentemente, bruxos sinistros e seus seguidores sectários ocuparam os arredores e o interior da torre, realizando rituais sombrios longe da vigilância de Auberdine.",al={"torre de althalaxx","o que é althalaxx","torre em ruínas de costa negra"}},{q="Quem são os sectários ao redor da torre?",a="Eles pertencem à Seita da Linhagem das Trevas, uma organização secreta de bruxos e fanáticos reunidos nas antigas ruínas élficas para realizar rituais sombrios de evocação.",al={"quem são os bruxos","seita da linhagem das trevas","fanáticos da linhagem das trevas"}},{q="Por que Balthule alerta para não entrar na torre?",a="Balthule observa que os bruxos instalados nas partes superiores da torre são muito mais poderosos e perigosos do que os fanáticos acampados do lado de fora, entre as ruínas. Ele recomenda coletar informações nos arredores antes de tentar invadir a fortaleza.",al={"posso entrar na torre","bruxos perigosos da torre","interior da torre"}},{q="O que os pergaminhos gastos revelam?",a="Os fragmentos carregados pelos fanáticos oferecem a primeira confirmação clara do nome do grupo: Seita da Linhagem das Trevas. Assim, Balthule descobre que os ocupantes são uma seita organizada cuja presença ameaça imediatamente a região.",al={"o que dizem os pergaminhos","história dos pergaminhos gastos","anotações dos sectários"}},{q="Quem é Dinis, o Purificador?",a="Dinis, o Purificador, é um paladino da Aliança situado no Entreposto de Maestra, no Vale Gris, que combate influências demoníacas e corruptoras. Ele suspeitava que atividades malignas estavam se instalando na Torre de Althalaxx e depende de batedores como Balthule para obter informações.",al={"dinis","quem é dinis","dinis o purificador"}}},fx={bc625320={q="Por que Balthule Umbrataque quer que isso seja feito?",a="Balthule Umbrataque teme que forças sombrias estejam se reunindo em segredo bem nas fronteiras da Costa Negra. Embora Delgren suspeitasse que bruxos estavam se congregando nas ruínas antigas, nenhum deles sabe quem são ou que ritual vil pretendem realizar. Balthule precisa de evidências escritas suficientes para montar suas identidades e motivos antes de tomar uma atitude decisiva para proteger a região.",al={"por que balthule quer pergaminhos","motivo de balthule","por que investigar althalaxx"}},["151da73d"]={q="Por que Balthule Umbrataque envia você em vez de ir ele mesmo?",a="Balthule está posicionado em uma vigia de reconhecimento solitária fora das ruínas. Ele não pode deixar seu posto para vasculhar os campos dos cultistas ao redor ou retornar a Auberdine para relatar, aterrorizado que qualquer ausência possa fazê-lo perder movimentos críticos do inimigo. Ao ter você enfrentando os cultistas externos e recuperando seus escritos, ele pode manter vigilância contínua sobre a torre.",al={"por que balthule precisa de ajuda","por que não balthule","por que balthule pede a você"}}},fp="22,252,20.370.0,20.280.1,29.215.0,31.218.0,43.179.0,50.225.0,35.185.0,28.262.0"}
P.entries["quest:96604"] = {n="The Great Outdoors",s="The Great Outdoors é uma missão introdutória de sobrevivência na natureza oferecida por Brakk a aspirantes a aventureiros. Ao aprender a descansar ao lado de uma fogueira básica, os viajantes descobrem os fundamentos para se sustentarem na vida selvagem antes de buscarem profissões práticas.",h="The Great Outdoors é uma missão introdutória de sobrevivência na natureza oferecida por Brakk a aspirantes a...",kw={"boosted rest","brakk","instalacao de acampamento","fogueira","the great outdoors","pericia profissional","sobrevivencia na natureza"},ang={["faction:Horde"]="Recebida com o tradicional \"Lok-tar\" órfico, esta lição de sobrevivência oferece aos aventureiros novatos da Horda uma base fundamental antes de partirem por territórios traiçoeiros."},sec={{t="Lições na Natureza",b="Aventurar-se pelos confins indomados de Azeroth exige mais do que determinação marcial; requer o conhecimento básico para suportar as intempéries. Brakk cumprimenta os aspirantes a aventureiros com um vigoroso \"Lok-tar\", reconhecendo o espírito inquieto daqueles que buscam fortuna e glória. Para sobreviver à longa estrada à frente, todo viajante deve primeiro dominar a arte de montar acampamento e recuperar suas forças em meio à natureza."},{t="Do Lar ao Ofício",b="Sentar-se ao lado da Basic Campfire de Brakk transmite o essencial sobre recuperação, concedendo um descanso revigorante ao ar livre. Uma vez compreendidos esses fundamentos de sobrevivência, os aventureiros novatos são direcionados aos artesãos da aldeia local. Lá, eles podem aprender perícias profissionais e descobrir como construir instalações funcionais de acampamento adequadas ao ofício escolhido."}},faq={{q="O que é The Great Outdoors?",a="The Great Outdoors é uma missão introdutória de sobrevivência oferecida por Brakk, destinada a ensinar novos aventureiros a prosperar na natureza descansando perto de uma fogueira antes de escolher uma profissão.",al={"o que e the great outdoors","missao the great outdoors"}},{q="Quem é Brakk?",a="Brakk é um experiente sobrevivente ao ar livre que acolhe viajantes inquietos, oferecendo lições práticas sobre sobrevivência na natureza e descanso junto a uma fogueira.",al={"quem e brakk","concessor da missao"}},{q="O que é o bônus Boosted Rest?",a="Descansar perto da Basic Campfire de Brakk concede o bônus Boosted Rest, demonstrando como se abrigar e se recuperar junto a uma chama aberta revitaliza um aventureiro na vida selvagem.",al={"buff boosted rest","buff de fogueira"}},{q="O que você deve fazer após concluir a missão?",a="Ao aprender os fundamentos do descanso na natureza, Brakk aconselha os aventureiros a visitarem instrutores na aldeia próxima para estudar uma perícia profissional e aprender como construir instalações de acampamento adaptadas ao seu ofício.",al={"proximo passo apos a missao","o que fazer apos a fogueira"}},{q="O que são instalações de acampamento?",a="Instalações de acampamento são estruturas especializadas ensinadas por instrutores de profissão em aldeias próximas, permitindo que os viajantes adaptem seus acampamentos para apoiar suas perícias profissionais escolhidas.",al={"instalacoes de acampamento","o que sao instalacoes de acampamento"}},{q="A quem se destina este treinamento?",a="Qualquer alma inquieta que busca fortuna e glória na natureza se beneficia desta lição, particularmente aqueles que estão apenas começando sua jornada e se preparando para escolher um ofício.",al={"quem deve fazer esta missao","isso e para a horda"}}},fp="18,131,19.303.0,20.303.0,27.97.0,13.133.0,30.138.0,46.153.0,23.164.0,34.151.0"}
P.entries["quest:96605"] = {n="The Great Outdoors",s="The Great Outdoors é uma missão introdutória que ensina aspirantes a aventureiro as artes fundamentais da sobrevivência na natureza selvagem. Guiados pelo viajante Kaga, os novatos aprendem a se recuperar ao lado de uma fogueira básica antes de avançarem para aprender perícias de profissão e criar estruturas de acampamento especializadas.",h="The Great Outdoors é uma missão introdutória que ensina aspirantes a aventureiro as artes fundamentais da...",kw={"boosted rest","estrutura de acampamento","fogueira","kaga","sobrevivência","the great outdoors","perícia de profissão","natureza selvagem"},ang={["profession:Cooking"]="Fogueiras e sobrevivência na natureza selvagem formam a base da culinária em campo, tornando as habilidades de acampamento um complemento natural para o preparo de refeições sob o céu aberto."},sec={{t="Lições da Natureza Selvagem",b="Todo aventureiro que dá passos além da segurança da civilização rapidamente descobre que coragem pura não basta para sobreviver na fronteira. The Great Outdoors apresenta aos novatos a necessidade vital de aclimação à natureza selvagem. Ensinada pelo experiente viajante Kaga, esta breve lição lembra aos heróis novatos que prosperar em territórios inexplorados começa sabendo como estabelecer um acampamento e suportar os elementos a céu aberto."},{t="O Lar e o Ofício",b="Uma fogueira simples é frequentemente tudo o que se interpõe entre um explorador e a exaustão da natureza indômita. Ao se sentar ao lado do fogo de Kaga e obter o bônus Boosted Rest, os aventureiros descobrem o poder restaurador da vida no acampamento. Assim que os fundamentos do descanso na natureza selvagem são compreendidos, Kaga incentiva os viajantes a visitarem artesãos em assentamentos próximos para aprenderem perícias de profissão e dominarem a criação de estruturas de acampamento profissionais."}},faq={{q="O que é The Great Outdoors?",a="The Great Outdoors é uma missão introdutória de sobrevivência na natureza selvagem oferecida por Kaga. Ela apresenta aos aventureiros novatos os fundamentos de sobreviver na natureza, descansar junto a uma fogueira e se preparar para profissões especializadas.",al={"o que é the great outdoors","missão the great outdoors"}},{q="Quem oferece esta missão?",a="Kaga é um viajante experiente e mentor ao ar livre que guia aspirantes a aventureiro nos princípios básicos da sobrevivência na natureza selvagem. Ele mantém uma fogueira básica onde novatos podem aprender a descansar e se recuperar.",al={"quem é kaga","kaga concessor de missões"}},{q="O que é o bônus Boosted Rest?",a="Boosted Rest é o estado benéfico de relaxamento obtido ao sentar-se pacificamente ao lado da Basic Campfire de Kaga. Representa o efeito rejuvenescedor de descansar adequadamente em um acampamento na natureza selvagem.",al={"boosted rest","o que é o bônus boosted rest"}},{q="O que são estruturas de acampamento?",a="Após dominar o descanso básico na natureza selvagem, instrutores de perícias de profissão em assentamentos próximos podem ensinar os aventureiros a construir estruturas de acampamento especializadas, adaptadas aos seus ofícios escolhidos.",al={"lore de estruturas de acampamento","estruturas de acampamento de profissão"}},{q="Por que Kaga faz você se sentar junto à fogueira?",a="Sobreviver fora de cidades civilizadas exige aprender a montar acampamento e recuperar o vigor. Sentar-se junto a uma fogueira permite que os aventureiros obtenham calor, foco e recuperação descansada entre jornadas perigosas.",al={"por que descansar na fogueira","descanso na fogueira"}},{q="O que você deve fazer após concluir esta lição?",a="Ao aprender a descansar adequadamente na natureza selvagem, Kaga aconselha procurar instrutores de profissão no vilarejo próximo para aprender um ofício e obter receitas de estruturas de acampamento específicas para a profissão.",al={"o que fazer depois de the great outdoors","após a missão de kaga"}}},fp="18,162,19.184.0,24.259.0,27.125.0,22.128.0,30.141.0,23.140.0,43.158.0,48.161.0"}
P.entries["quest:96606"] = {n="The Great Outdoors",s="The Great Outdoors é uma lição introdutória de sobrevivência na natureza oferecida a Caçadores por uma batedora experiente chamada Lyreena. Ela enfatiza a importância de descansar ao lado de uma fogueira para se recuperar e obter o bônus de Descanso Aprimorado enquanto viaja pelas terras selvagens e indomadas.",h="The Great Outdoors é uma lição introdutória de sobrevivência na natureza oferecida a Caçadores por uma...",kw={"aventureiro","descanso aprimorado","fogueira","caçador","lyreena","sobrevivencia","the great outdoors","terras selvagens"},ang={["class:Hunter"]="Oferecida diretamente aos Caçadores, esta lição reforça a necessidade de sobrevivência na natureza e de habilidades de acampamento ao rastrear pelas terras indomadas."},sec={{t="Lições da Natureza",b="Aventurar-se além das fronteiras da civilização exige mais do que pontaria afiada e sentidos aguçados; exige respeito pelos elementos puros e indomados. Uma batedora experiente chamada Lyreena oferece orientação a Caçadores errantes, convidando-os a pausar sua caminhada e encontrar conforto junto à sua fogueira. Nas perigosas terras selvagens de Azeroth, saber como estabelecer um refúgio e recuperar as forças entre as caçadas é tão crítico quanto saber rastrear a presa."},{t="Alívio na Fogueira",b="Uma fogueira crepitante proporciona conforto contra o frio noturno, oferecendo um momento de calma onde viajantes exaustos podem afastar o cansaço. Sentar-se perto das chamas permite que os aventureiros obtenham Descanso Aprimorado, revitalizando sua energia e preparando-os para os rigores da exploração. Reservar um tempo para sentar-se junto às brasas ensina aos jovens aventureiros que paciência e descanso são pilares duradouros da sobrevivência na natureza."}},faq={{q="Quem é Lyreena?",a="Lyreena é uma mentora experiente da natureza selvagem que ensina aventureiros e Caçadores novatos a descansar e sobreviver adequadamente ao ar livre, expostos aos elementos. Ela oferece conselhos práticos ao redor de sua fogueira.",al={"quem e lyreena","fogueira de lyreena","concedente da missao"}},{q="O que é The Great Outdoors?",a="The Great Outdoors é uma tarefa introdutória de sobrevivência na natureza na qual uma experiente mulher da natureza chamada Lyreena convida Caçadores a se sentarem junto à sua fogueira e aprenderem a se sustentar durante longas expedições.",al={"o que e the great outdoors","o que e esta missao","missao the great outdoors"}},{q="O que é Descanso Aprimorado?",a="Sentar-se próximo a uma fogueira básica permite que viajantes cansados se recuperem da fadiga da viagem e ganhem o efeito de Descanso Aprimorado, revitalizando seus espíritos para as próximas jornadas.",al={"buff descanso aprimorado","fogueira descanso aprimorado","como obter descanso aprimorado"}},{q="Por que você precisa descansar perto de uma fogueira?",a="Fogueiras fornecem calor vital e alívio na natureza implacável. Descansar perto de uma permite que um aventureiro recupere o fôlego, clareie a mente e se prepare para travessias perigosas por terras indomadas.",al={"proposito da fogueira","por que sentar perto do fogo","descansando na fogueira"}},{q="Por que a sobrevivência ao ar livre é crucial para os Caçadores?",a="Os Caçadores passam a maior parte de suas vidas atravessando territórios isolados sem tavernas ou cidades seguras por perto. Dominar técnicas básicas de acampamento garante que um Caçador possa suportar ambientes hostis sem sucumbir à exaustão.",al={"habilidades de sobrevivencia de cacador","sobrevivencia ao ar livre","por que missao de cacador"}},{q="O que você deve fazer para concluir a tarefa?",a="Para concluir a tarefa, você simplesmente precisa se sentar perto da fogueira básica de Lyreena e esperar um pouco até que o calor da fogueira conceda o bônus de Descanso Aprimorado.",al={"objetivo da missao","como concluir the great outdoors","objetivos de the great outdoors"}}},fp="18,127,19.247.0,16.179.0,15.123.0,27.80.0,21.130.0,38.127.0,44.153.0,38.75.0"}
P.entries["quest:96607"] = {n="Vida ao ar livre",s="Vida ao ar livre é uma lição introdutória de sobrevivência oferecida por viajantes experientes a andarilhos recém-formados por toda Azeroth. Ao tirar um momento para descansar junto a uma fogueira acolhedora, os novatos aprendem como se manter bem descansados e preparados mantém um aventureiro vivo além dos muros da cidade. Isso marca o primeiro passo para dominar a sobrevivência na natureza e acampamentos de campo especializados.",h="Vida ao ar livre é uma lição introdutória de sobrevivência oferecida por viajantes experientes a andarilhos...",kw={"aventureiro","boosted rest","fogueira","acampamento","eleanor shackleton","floresta de elwynn","sam sarsaparilla","sobrevivência","perícia"},ang={["faction:Alliance"]="Na segurança da Floresta de Elwynn, os viajantes humanos aprendem estes princípios básicos de sobrevivência com andarilhos experientes antes de enfrentar as ameaças mais severas que espreitam em Cerro Oeste e nas Montanhas Cristarrubra.",["faction:Horde"]="Seja cruzando as planícies áridas de Durotar ou as colinas açoitadas pelo vento de Mulgore, os sobrevivencialistas da Horda ensinam a arte do fogo e a disciplina ao ar livre a cada jovem guerreiro.",["profession:Cooking"]="Todo acampamento na natureza começa com fogo, tornando a culinária a companheira natural da sobrevivência ao ar livre. Após esta lição, os mestres do acampamento o direcionam imediatamente à instrução culinária à beira da trilha."},sec={{t="Lições da Trilha",b="Não importa quão afiada seja a sua lâmina ou quão potente seja a sua magia, as terras ermas de Azeroth desgastam rapidamente qualquer um que negligencie os fundamentos da sobrevivência. Andarilhos experientes posicionados perto de clareiras à beira da estrada oferecem esta lição simples aos viajantes que partem de seus vales natais. Tirar um tempo para descansar junto a uma fogueira faz mais do que aliviar as botas cansadas: acalma a mente e prepara o espírito para a estrada rigorosa à frente. Apenas aqueles que dominam a disciplina do descanso regular e da preparação têm a chance de sobreviver tempo suficiente para conquistar fortuna e glória."},{t="Um Lar Longe de Casa",b="Assim que o aventureiro compreende o valor de uma fogueira crepitante e do descanso adequado, os instrutores o direcionam diretamente aos artesãos da cidade. Um acampamento no campo raramente está completo apenas com uma brasa e um saco de dormir; a sobrevivência exige ofícios práticos. Seja forjando rebites de reposição, cozinhando rações de trilha ou remendando equipamentos rasgados sob as estrelas, cada profissão oferece estruturas de acampamento exclusivas para transformar uma encosta estéril em um entreposto autossuficiente."}},faq={{q="Quem oferece esta lição aos novos andarilhos?",a="Uma variedade de viajantes veteranos oferece essa orientação, dependendo de onde você estiver. Na Floresta de Elwynn, o experiente andarilho Sam Sarsaparilla se apresenta, enquanto em outros lugares figuras como Eric Brighthammer, Lyreena Duskblade, Brakk, Eleanor Shackleton, Kaga Wildhoof e Raan Wildwind compartilham sua vivência na natureza.",al={"quem dá vida ao ar livre","quem começa vida ao ar livre","iniciador da missão vida ao ar livre"}},{q="Qual é o propósito de sentar-se junto à fogueira?",a="Sentar-se tranquilamente perto de uma fogueira ardente permite que o aventureiro recupere o fôlego e ganhe o efeito Boosted Rest. Fazer pausas deliberadas no campo é essencial para manter suas forças durante longas expedições pelas terras ermas.",al={"por que sentar perto do fogo","o que a fogueira faz","bônus de boosted rest"}},{q="Para onde este treinamento leva a seguir?",a="Depois de terminar de descansar junto ao fogo, seu mentor o direcionará a assentamentos próximos para aprender perícias práticas. A partir daí, você começará a aprender Introdução ao Acampamento: Cozinha, bem como lições específicas de acampamento de campo adaptadas a qualquer profissão que decidir seguir.",al={"o que vem depois de vida ao ar livre","próxima missão de vida ao ar livre","missões de acampamento"}},{q="Aventureiros da Horda também podem realizar esta lição?",a="Sim. Sobreviver na natureza implacável é uma necessidade, independentemente da lealdade. Instrutores veteranos tanto da Aliança quanto da Horda — como Brakk, Eleanor Shackleton e Kaga Wildhoof — ensinam exatamente as mesmas técnicas fundamentais de acampamento aos iniciados de sua facção.",al={"é apenas da aliança","vida ao ar livre horda","orcs podem fazer esta missão"}},{q="Por que os instrutores dizem para você falar com instrutores de profissão?",a="Sobreviver exige mais do que apenas sentar-se perto do fogo; um aventureiro precisa de autossuficiência. Instrutores de perícia ensinam você a criar estruturas de acampamento especializadas que permitem exercer o seu ofício, seja cozinhando rações de trilha, consertando armaduras ou preparando remédios a céu aberto.",al={"por que aprender profissões","estruturas de acampamento instrutores de profissão","conexão entre profissão e acampamento"}},{q="Qual experiência prévia é esperada antes de aceitar esta missão?",a="Aventureiros normalmente recebem esta lição logo após 'The Adventurer', depois de terem provado sua ambição básica e dado os primeiros passos além de seus enclaves iniciais rumo à região mais ampla.",al={"pré-requisitos para vida ao ar livre","como desbloquear vida ao ar livre","antes de vida ao ar livre"}}},fp="18,163,20.367.0,21.304.0,40.260.0,47.178.0,35.203.0,52.194.0,61.225.0,59.144.0"}
P.entries["quest:96608"] = {n="The Great Outdoors",s="Eric espera junto à sua fogueira para ensinar viajantes a descansar na natureza.",h="Eric espera junto à sua fogueira para ensinar viajantes a descansar na natureza.",kw={"descanso aprimorado","estrutura de acampamento","fogueira","eric","sobrevivência","the great outdoors","perícia profissional","natureza selvagem"},ang={["class:Priest"]="Como sacerdote, você pode encontrar sua vocação em santuários sagrados e capelas. Mas a vida na estrada exige habilidades práticas de sobrevivência, além de orações e bênçãos."},sec={{t="Lições da Natureza Selvagem",b="Longe dos povoados, ambição e uma arma ou símbolo sagrado não bastam. Você precisa saber como descansar em meio às intempéries. Eric já viajou para longe e recebe você junto à sua fogueira. Ali, ele ensina por que descansar direito é importante antes de enfrentar terras selvagens."},{t="Da Fogueira ao Ofício",b="Uma fogueira é o primeiro passo para montar um acampamento útil em uma longa jornada. Depois de aprender a se recuperar na natureza, visite os instrutores de profissões nos povoados próximos. Eles podem ensinar você a criar equipamentos de acampamento para sua profissão. Assim, seu ofício pode ajudar nas suas viagens, aonde quer que a estrada leve."}},faq={{q="Quem é Eric?",a="Eric é um viajante experiente que ensina os novatos a sobreviver na natureza. Ele recebe você junto à sua fogueira e compartilha conselhos para a vida além das muralhas da cidade.",al={"quem dá esta missão","quem é eric","quem ensina ar livre"}},{q="O que é o bônus de Descanso Aprimorado?",a="Descansar junto à fogueira de Eric concede a você o efeito Boosted Rest. Ele ajuda você a se recuperar e se preparar para as provações que virão, a salvo das intempéries.",al={"o que é descanso aprimorado","como a fogueira ajuda","bônus de descanso no acampamento"}},{q="O que são estruturas de acampamento?",a="Equipamentos de acampamento são estruturas ou ferramentas práticas para profissões específicas que você pode montar na natureza. Os instrutores nos povoados próximos explicam como sua profissão permite montar um acampamento de trabalho.",al={"o que são estruturas de acampamento","estruturas de profissão","item de acampamento de perícia profissional"}},{q="Por que você precisa se sentar perto da fogueira de Eric?",a="Sentar junto à fogueira de Eric dá a você tempo para fazer uma pausa, se aquecer e ouvir suas orientações sobre sobrevivência na natureza. Descansar ali permite que você aproveite todos os benefícios de um abrigo ao ar livre.",al={"por que sentar na fogueira","sentar perto da fogueira","objetivo da fogueira"}},{q="Para onde um aventureiro deve ir após concluir esta lição?",a="Depois que você aprende a descansar no acampamento, Eric sugere visitar a aldeia próxima. Os instrutores locais podem ensinar uma profissão a você e depois mostrar como criar equipamentos de acampamento adequados ao seu ofício.",al={"o que fazer depois","para onde ir a seguir","depois de the great outdoors"}},{q="A quem se destina esta lição de sobrevivência?",a="Eric recebe aventureiros de passagem que têm um espírito inquieto e disposição para buscar fortuna e glória pelo mundo. Suas orientações sobre a vida na natureza podem ajudar você a deixar a segurança para trás e se aventurar em terras selvagens.",al={"quem pode fazer esta missão","apenas sacerdote","isso é para aventureiros"}}},fp="18,70,19.256.0,22.277.0,12.165.0,30.144.0,23.199.0,44.176.0,59.179.0,41.199.0"}
P.entries["quest:96626"] = {n="Camping 101: Cooking",s="Em Vila d'Ouro, Cook Tomas ensina novos viajantes a acender uma fogueira por meio da culinária. Com esse fogo, eles podem montar um acampamento simples na natureza.",h="Em Vila d'Ouro, Cook Tomas ensina novos viajantes a acender uma fogueira por meio da culinária.",kw={"fogueira","acampamento","camping 101: cooking","local de acampamento","culinária","mobílias","vila d'ouro","tomas"},ang={["faction:Alliance"]="Como aventureiro da Aliança recém-chegado à Floresta de Elwynn, você é encaminhado a Cook Tomas na Estalagem do Leão Orgulhoso, em Vila d'Ouro, para aprender culinária e a fazer fogueiras.",["profession:Cooking"]="A culinária ensina você a fazer fogueiras básicas no centro dos seus acampamentos na natureza."},sec={{t="A Lareira na Natureza",b="Uma fogueira oferece a você um lugar para preparar comida e começar um acampamento nos ermos de Azeroth. Aprenda a cozinhar e você aprenderá a acender essa fogueira. Assim, uma área aberta na natureza pode se tornar um lugar para acampar."},{t="Instrução em Vila d'Ouro",b="Na Floresta de Elwynn, novos viajantes encontram Cook Tomas em Vila d'Ouro e aprendem culinária. Seus ensinamentos dão a você a habilidade de montar um acampamento básico na natureza. No início, seu acampamento tem poucos móveis. Uma habilidade maior em culinária permite que você faça fogueiras maiores, enquanto outras profissões de criação oferecem mais maneiras de mobiliar e organizar seu acampamento."}},faq={{q="O que é a missão Camping 101: Cooking?",a="A culinária ensina você a fazer uma fogueira básica para um acampamento na natureza.",al={"o que é camping 101 cooking","o que camping 101 ensina","objetivo de camping 101"}},{q="Quem é Tomas e onde ele pode ser encontrado?",a="Tomas ensina culinária em Vila d'Ouro, na Floresta de Elwynn. Encontre-o na Estalagem do Leão Orgulhoso, onde ele ensina os fundamentos da culinária e como acender uma fogueira.",al={"quem é tomas","onde fica tomas","tomas vila d'ouro"}},{q="Por que a culinária é necessária para estabelecer um acampamento?",a="A culinária ensina você a fazer a fogueira que ocupa o centro de um acampamento na natureza, onde você pode descansar e organizar móveis.",al={"por que culinária é necessária para acampar","culinária é necessária para acampar","relação entre culinária e fogueira"}},{q="Você pode fazer fogueiras maiores à medida que sua habilidade melhora?",a="Uma habilidade maior em culinária permite que você faça fogueiras maiores e mais resistentes para seu acampamento na natureza.",al={"como aprimorar a fogueira","como fazer fogueiras maiores","fogueiras maiores culinária"}},{q="Como você adquire mobílias para o seu acampamento?",a="Instrutores de outras profissões ensinam você a fazer móveis para acampamentos. Diferentes profissões de criação permitem que você crie itens para decorar e melhorar um acampamento na natureza.",al={"como adicionar mobílias ao acampamento","de onde vêm as mobílias do acampamento","criar itens de acampamento"}},{q="Onde um aventureiro pode montar acampamento?",a="Quando você souber cozinhar e fazer uma fogueira, poderá montar acampamento em uma área aberta na natureza. Seus primeiros acampamentos são modestos e têm apenas alguns móveis até que você aprimore suas habilidades.",al={"é possível acampar em qualquer lugar","regras de acampamento na natureza","limites de posicionamento do acampamento"}}},fp="20,133,22.193.0,24.328.0,39.73.0,39.151.0,48.120.0,53.86.0,49.161.0,36.183.0"}
P.entries["quest:96627"] = {n="O aventureiro",s="O aventureiro é uma missão introdutória concedida pelo Major Belmonte no Vale de Vila Norte. Reconhecendo sua competência inicial, Belmonte direciona você para além dos limites reclusos da abadia em direção a Vila d'Ouro para averiguar a situação de um recém-chegado chamado Sam Sarsaparilla.",h="O aventureiro é uma missão introdutória concedida pelo Major Belmonte no Vale de Vila Norte.",kw={"floresta de elwynn","vila d'ouro","major belmonte","vila norte","sam sarsaparilla","o aventureiro"},ang={["faction:Alliance"]="Para os novos recrutas da Aliança que concluem seu serviço em Vila Norte, isso marca o primeiro passo oficial em direção ao território mais amplo da Floresta de Elwynn.",["race:Human"]="Defensores humanos que deixam a Abadia de Vila Norte dão seus primeiros passos em direção a Vila d'Ouro, o movimentado coração de Elwynn."},sec={{t="Deixando o Vale",b="Assim que os recrutas limpam o Vale de Vila Norte de ameaças imediatas, como os Defias locais e pragas, o Major Belmonte começa a olhar mais adiante na estrada. Com a presença militar regular de Ventobravo sobrecarregada por todo o reino, a guarnição local precisa contar com combatentes promissores para ficar de olho em viajantes e andarilhos que percorrem os bosques ao redor."},{t="Um recém-chegado curioso",b="Em vez de uma ordem militar ou de uma caçada a recompensas, Belmonte encarrega você de uma tarefa incomum: verificar um novo aventureiro específico avistado perto de Vila d'Ouro, chamado Sam Sarsaparilla. O pedido serve como uma transição do vale isolado de Vila Norte para a extensão mais ampla e perigosa da Floresta de Elwynn."}},faq={{q="Quem me envia nesta tarefa?",a="O Major Belmonte, comandante da guarnição de Ventobravo estacionada no Vale de Vila Norte, oferece esta tarefa assim que você comprova seu valor defendendo a abadia.",al={"concedente da missão","quem concede o aventureiro","missão do major belmonte"}},{q="Quem é Sam Sarsaparilla?",a="Sam Sarsaparilla é um aventureiro que se encontra ao longo da estrada perto de Vila d'Ouro. O Major Belmonte fica sabendo de sua presença e pede que você investigue o que ele está tramando.",al={"sam sarsaparilla","quem é sam","aventureiro de vila d'ouro"}},{q="Onde encontro Sam Sarsaparilla?",a="Ele está localizado descendo a estrada principal que sai de Vila Norte em direção à cidade de Vila d'Ouro, na Floresta de Elwynn.",al={"localização de sam sarsaparilla","onde está sam","encontrar sam sarsaparilla"}},{q="Por que o Major Belmonte se importa com um aventureiro qualquer?",a="Vila Norte permanece em alerta máximo contra bandidos e invasores. Belmonte prefere ficar atento a mercenários e andarilhos desconhecidos que passam pela região, aproveitando talentos locais confiáveis para fazer o contato inicial.",al={"por que me enviar","motivos de belmonte","por que procurar sam"}},{q="Preciso sair do Vale de Vila Norte para concluir isso?",a="Sim. Esta tarefa direciona você pelos portões do sul do Vale de Vila Norte até a estrada da floresta que leva a Vila d'Ouro.",al={"fora de vila norte","isso sai de vila norte","ir para vila d'ouro"}},{q="Isso faz parte da cadeia de comando militar normal de Ventobravo?",a="Embora tenha sido emitida por um oficial de Ventobravo, Belmonte a define explicitamente como uma tarefa incomum, em vez de um dever de guarda padrão, confiando no seu discernimento como protetor independente em vez de no protocolo militar formal.",al={"exército de ventobravo","isso é dever padrão","assunto oficial"}}},fx={dd262048={q="Por que o Major Belmonte escolhe a mim para investigar Sam?",a="O Major Belmonte considera esta uma tarefa incomum, e não um dever padrão da guarnição. Tendo observado você lidar com as ameaças locais de Vila Norte, ele o vê como um protetor capaz que pode operar discretamente fora dos portões da abadia. Com sua própria guarnição sobrecarregada lidando com problemas locais, enviar um recruta de confiança para investigar rumores na estrada faz muito mais sentido do que despachar guardas regulares.",al={"por que eu major belmonte","por que belmonte me envia","por que não enviar um guarda para sam"}}},fp="14,186,18.198.0,18.232.0,26.131.0,24.138.0,33.96.0,56.182.0,52.100.0,63.202.0"}
P.entries["quest:96628"] = {n="O aventureiro",s="O aventureiro é uma incumbência local concedida pelo Montanhista Thalos no portão sul de Dun Morogh. Antes de enviar os viajantes pelo túnel na montanha em direção a Kharanos, Thalos pede que levem um pacote de suprimentos para Eric Brighthammer, um recém-chegado acampado logo nos arredores da vila.",h="O aventureiro é uma incumbência local concedida pelo Montanhista Thalos no portão sul de Dun Morogh.",kw={"caminho de cristálgida","dun morogh","eric brighthammer","kharanos","montanhista thalos","pacote de suprimentos","o aventureiro"},ang={["faction:Alliance"]="Os Montanhistas contam com recrutas da Aliança para transportar suprimentos vitais pelas estradas geladas, garantindo que os aliados errantes nos arredores de Kharanos permaneçam abastecidos.",["race:Dwarf"]="Para os jovens anões que deixam o Vale Cristálgida, levar mantimentos a Eric Brighthammer marca seu primeiro ato de cooperação com os Montanhistas nas vastidões de Dun Morogh."},sec={{t="Um favor para os montanhistas",b="Guardar as passagens altas e os túneis entre o Vale Cristálgida e as vastas extensões nevadas de Dun Morogh é um trabalho exigente para os Montanhistas de Altaforja. Posicionado no portão da fronteira, o Montanhista Thalos fica atento tanto aos perigos locais quanto aos viajantes que passam pela trilha batida. Quando chegam notícias ao posto sobre um aventureiro solitário que chegou perto de Kharanos, Thalos recorre a transeuntes de confiança para transportar os suprimentos necessários e apoiar os recém-chegados que se aventuram pelos penhascos congelados."},{t="Suprimentos para Kharanos",b="A estrada que desce da passagem sul serpenteia até o povoado de Kharanos, o principal centro de viagens e artesanato dos anões no centro de Dun Morogh. Eric Brighthammer se estabeleceu recentemente nos arredores da vila. Ao entregar o pacote de provisões dos Montanhistas a ele, os viajantes ajudam a criar um vínculo vital entre as sentinelas dos cumes remotos e aqueles que exploram ativamente as terras ermas."}},faq={{q="Quem inicia a missão O aventureiro?",a="O Montanhista Thalos oferece esta missão. Ele vigia o portão da passagem da montanha que conecta a trilha do Vale Cristálgida ao restante de Dun Morogh.",al={"iniciador da missão","quem dá o aventureiro","missão do thalos"}},{q="Quem é Eric Brighthammer?",a="Eric Brighthammer é um aventureiro que chegou recentemente aos arredores da cidade anã de Kharanos. O Montanhista Thalos encarrega os viajantes de levar a ele um pacote essencial de suprimentos.",al={"onde fica eric brighthammer","quem é o aventureiro","brighthammer"}},{q="Onde essa entrega acontece?",a="A entrega ocorre logo nos arredores de Kharanos, em Dun Morogh, ao norte do túnel do Caminho de Cristálgida onde o Montanhista Thalos está de guarda.",al={"onde entregar suprimentos","localização de eric brighthammer","entrega do pacote de suprimentos"}},{q="Por que o Montanhista Thalos está enviando suprimentos?",a="Os Montanhistas monitoram os viajantes por toda Dun Morogh. Ao saber que um aventureiro acampou perto de Kharanos, Thalos organiza o envio de mantimentos para apoiá-lo no frio.",al={"por que enviar suprimentos","objetivo de thalos","motivo do pacote"}},{q="Qual item você está carregando?",a="Você carrega um Pacote de Suprimentos fornecido diretamente pelo Montanhista Thalos para entregar a Eric Brighthammer.",al={"quais suprimentos","item pacote de suprimentos"}},{q="Esta missão está disponível para jogadores da Horda?",a="Não. O Montanhista Thalos é um guarda anão alinhado à Aliança em Dun Morogh, tornando esta tarefa exclusiva para a Aliança.",al={"horda pode fazer","é apenas da aliança","missão o aventureiro horda"}}},fx={["95095969"]={q="Por que o Montanhista Thalos pede a você para entregar os suprimentos?",a="O Montanhista Thalos e sua patrulha estão estacionados na passagem, encarregados de vigiar a estrada e proteger o túnel contra perigos locais. Como você já está viajando pela passagem em direção a Kharanos, ele pede que você leve a entrega durante seu trajeto, em vez de tirar seus montanhistas de seus postos de guarda.",al={"por que eu the adventurer","por que thalos precisa de mim","por que enviar jogador para eric brighthammer"}}},fp="14,201,28.398.0,21.296.0,36.135.0,25.142.0,36.164.0,43.175.0,27.71.0,41.107.0"}
P.entries["quest:96629"] = {n="Camping 101: Cooking",s="Camping 101: Cooking apresenta aos aventureiros em Dun Morogh a habilidade essencial de sobrevivência da culinária. Além de preparar provisões, aprender esse ofício permite que os viajantes acendam fogueiras que servem como fundação para acampamentos na natureza selvagem.",h="Camping 101: Cooking apresenta aos aventureiros em Dun Morogh a habilidade essencial de sobrevivência da...",kw={"fogueira","acampamento","culinária","dun morogh","mobílias","gremlock pilsnor","kharanos","natureza selvagem"},ang={["class:Priest"]="Até mesmo praticantes espirituais devotos da Luz precisam dominar habilidades básicas de sobrevivência, como acender fogueiras, ao viajar para longe de templos e povoados.",["faction:Alliance"]="Aventureiros da Aliança que começam perto de Dun Morogh aprendem os fundamentos da sobrevivência na selva e da culinária com os instrutores anões de Kharanos.",["profession:Cooking"]="A culinária fornece a fogueira fundamental necessária para estabelecer acampamentos na natureza selvagem e posicionar decorações e mobílias."},sec={{t="O Lar nas Terras Ermas",b="Para qualquer viajante que enfrenta a natureza selvagem, estabelecer um acampamento confiável começa com uma chama. Em Dun Morogh, aventureiros novatos são direcionados a Kharanos para aprender os fundamentos da culinária com Gremlock Pilsnor. Cozinhar não se resume a sustentar a si mesmo com refeições quentes pela estrada; uma fogueira resistente serve como a âncora literal e prática de qualquer acampamento ao ar livre."},{t="Expandindo o Acampamento",b="Uma fogueira recém-aprendida permite que um aventureiro monte um acampamento modesto em qualquer lugar da natureza selvagem aberta. Embora fogueiras rudimentares suportem apenas decorações mínimas, aprimorar a proficiência em culinária desbloqueia a capacidade de construir labaredas maiores. Além disso, artesãos habilidosos em outros ofícios de produção podem criar mobílias adicionais para transformar uma simples parada de descanso em um acampamento totalmente equipado."}},faq={{q="O que é a missão Camping 101: Cooking?",a="Camping 101: Cooking é uma missão instrutiva que apresenta aos aventureiros o ofício essencial da culinária como pilar da sobrevivência na natureza selvagem e da montagem de acampamentos.",al={"o que é camping 101 cooking","objetivo da missão","fundamentos de acampamento culinária"}},{q="Quem é Gremlock Pilsnor?",a="Gremlock Pilsnor é o instrutor de culinária local situado em Kharanos, em Dun Morogh, que ensina novatos a preparar comida e a fazer fogueiras.",al={"quem ensina culinária em kharanos","localização de gremlock pilsnor","instrutor de culinária dun morogh"}},{q="Por que a culinária é necessária para acampar?",a="A culinária permite que os aventureiros construam uma fogueira básica, que serve como fundação essencial para montar um acampamento na natureza selvagem e colocar mobílias ao redor dele.",al={"por que preciso de culinária para acampar","propósito da fogueira","culinária e acampamentos"}},{q="Onde é possível estabelecer um acampamento?",a="Depois de aprender a fazer fogo, você pode montar um acampamento básico na natureza selvagem, oferecendo um local de descanso durante suas jornadas.",al={"onde posso montar um acampamento","regras do acampamento","montando acampamento"}},{q="Como você melhora ou expande um acampamento?",a="Avançar na sua habilidade de culinária permite construir fogueiras maiores, e aprender outros ofícios de produção possibilita fabricar e posicionar mobílias adicionais para o acampamento.",al={"como aprimorar acampamento","fogueiras maiores","mais decorações de acampamento"}},{q="Outras profissões podem contribuir para o acampamento?",a="Outros instrutores de perícias podem ensinar o básico da criação de mobílias para o seu acampamento caso você tenha habilidade nas respectivas profissões.",al={"quem oferece mobília de acampamento","itens de profissão para acampamento","outros instrutores de acampamento"}}},fp="20,225,22.208.0,22.298.0,39.91.0,24.79.0,37.91.0,36.115.0,40.122.0,44.105.0"}
P.entries["quest:96630"] = {n="O aventureiro",s="O aventureiro é uma breve missão em Teldrassil que começa com a descoberta de um diário abandonado na mata. O caderno simples relata as viagens modestas e os acampamentos de um viajante desconhecido e deve ser entregue a Lyreena Duskblade, perto de Dolanaar.",h="O aventureiro é uma breve missão em Teldrassil que começa com a descoberta de um diário abandonado na mata.",kw={"acampamento","dolanaar","diário","diário perdido","lyreena duskblade","teldrassil","o aventureiro"},ang={["faction:Alliance"]="Para os iniciantes da Aliança que dão seus primeiros passos sob a Árvore do Mundo, devolver pertences perdidos a outros viajantes ajuda a manter a ordem nos bosques.",["race:NightElf"]="Jovens elfos noturnos que patrulham Teldrassil frequentemente encontram vestígios de viajantes e entregam objetos pessoais perdidos a andarilhos como Lyreena Duskblade."},sec={{t="O diário de um andarilho",b="Entre os galhos densos e as raízes emaranhadas de Teldrassil, viajantes às vezes encontram objetos pessoais abandonados. Este diário singelo narra as andanças modestas, porém sinceras, de um aventureiro sem nome. Em vez de grandes feitos heroicos ou caçadas perigosas, suas páginas registram com entusiasmo os pequenos prazeres de acampar sob a copa crepuscular das árvores."},{t="Entrega em Dolanaar",b="Em vez de deixar a lembrança pessoal se deteriorar na mata úmida, quem a encontra decide levá-la a Dolanaar. Lyreena Duskblade, que fica perto do povoado dos elfos noturnos, é a destinatária do diário e talvez possa esclarecer a quem pertenciam aqueles relatos de viagem."}},faq={{q="O que é o diário mencionado na missão?",a="É um caderno pessoal simples, encontrado na mata de Teldrassil. Suas anotações descrevem a vida tranquila e as viagens de alguém desconhecido, destacando aventuras cotidianas e um gosto especial por acampar ao ar livre.",al={"diário perdido","que livro é esse","diário do aventureiro"}},{q="Quem é Lyreena Duskblade?",a="Lyreena Duskblade é uma elfa noturna encontrada perto de Dolanaar. É a destinatária do diário perdido descoberto na floresta.",al={"lyreena","onde fica lyreena duskblade","pnj para entregar a missão"}},{q="Onde se passa esta missão?",a="A missão se passa em Teldrassil, a grande árvore dos elfos noturnos, mais especificamente nas matas que cercam a vila de Dolanaar.",al={"onde fica a missão o aventureiro","região da missão"}},{q="O diário descreve monstros perigosos ou batalhas?",a="Não. O texto é bastante simples e se concentra na vida e nas andanças despretensiosas de uma pessoa desconhecida, dando destaque especial ao prazer de acampar.",al={"história do diário","o que há no diário","o que diz o diário"}},{q="Quem pode concluir esta tarefa?",a="Esta tarefa é exclusiva dos membros da Aliança que percorrem a região inicial de Teldrassil, especialmente os elfos noturnos iniciantes que se aventuram perto de Dolanaar.",al={"a horda pode fazer","missão da aliança"}},{q="Por que entregar o diário em Dolanaar?",a="Dolanaar é o principal ponto de encontro e entroncamento daquela região de Teldrassil, sendo o lugar mais adequado para entregar pertences perdidos. Lyreena Duskblade aguarda nas proximidades para receber o diário.",al={"por que dolanaar","por que lyreena"}}},fp="14,156,20.179.0,20.163.0,43.152.0,25.83.0,33.65.0,56.125.0,27.106.0,36.135.0"}
P.entries["quest:96634"] = {n="Camping 101: Cooking",s="Camping 101: Cooking é uma missão introdutória que ensina aos aventureiros o essencial sobre acampar na natureza por meio da arte da culinária. Ao aprender a acender uma fogueira básica com instrutores locais como Zarrin em Dolanaar, os viajantes estabelecem o ponto de apoio necessário para montar acampamentos nos ermos. Ela marca o primeiro passo para dominar a sobrevivência ao ar livre e equipar acampamentos pessoais.",h="Camping 101: Cooking é uma missão introdutória que ensina aos aventureiros o essencial sobre acampar na...",kw={"fogueira","camping 101","acampamento","culinária","dolanaar","mobílias","sobrevivência nos ermos","zarrin"},ang={["profession:Cooking"]="A culinária é a disciplina fundamental para a sobrevivência na natureza, fornecendo a fogueira necessária para sustentar qualquer acampamento ao ar livre. Avançar na arte culinária permite que os aventureiros construam fogueiras maiores e mais resistentes.",["race:NightElf"]="Aventureiros elfos noturnos novatos que passam por Dolanaar frequentemente aprendem os fundamentos das técnicas de sobrevivência e de como fazer fogo com Zarrin antes de se aventurarem mais a fundo nos ermos de Teldrassil."},sec={{t="O Lar dos Ermos",b="Toda longa jornada pelos ermos começa com a habilidade de acender um fogo acolhedor. Em Camping 101: Cooking, aventureiros novatos são orientados a buscar treinamento culinário como sua lição inicial de técnicas de sobrevivência. Aprender a cozinhar é mais do que preparar refeições a partir de caça selvagem; a habilidade essencial de acender uma fogueira básica serve como o ponto de apoio físico e prático para qualquer acampamento ao ar livre. Sem uma fogueira para afastar o frio e manter a escuridão sob controle, estabelecer um acampamento confiável nos ermos é impossível."},{t="Expandindo o Acampamento",b="Aprender a acender uma fogueira básica concede a habilidade de estabelecer acampamentos modestos por toda a natureza. Embora um acampamento de nível inicial possa suportar apenas algumas mobílias rudimentares, aventureiros dedicados podem expandir suas capacidades. À medida que um aventureiro aprimora sua proficiência em culinária, ele desbloqueia métodos para acender fogueiras maiores e mais resistentes. Além disso, artesãos versados em outras profissões podem consultar seus respectivos instrutores para aprender a criar mobílias e melhorias para enriquecer seus acampamentos."}},faq={{q="Qual é o propósito de Camping 101: Cooking?",a="Camping 101: Cooking introduz os aventureiros aos fundamentos da sobrevivência na natureza, orientando-os a aprender a profissão de culinária. Estabelecer uma fogueira serve como o alicerce principal para montar um acampamento em qualquer lugar nos ermos.",al={"o que esta missão faz","objetivo de camping 101 cooking","por que fazer camping 101"}},{q="Quem é Zarrin?",a="Zarrin é um instrutor de culinária localizado em Dolanaar, em Teldrassil. Ele ensina aos aventureiros novatos o básico das artes culinárias e como construir uma fogueira básica.",al={"quem é zarrin","zarrin dolanaar","onde fica o instrutor de culinária de dolanaar"}},{q="Como você monta um acampamento nos ermos?",a="Montar um acampamento começa com a criação de uma fogueira básica aprendida através da profissão de culinária. Embora o treinamento básico permita que você monte acampamento nos ermos com mobílias modestas, avançar em suas habilidades possibilita fogueiras maiores e melhorias adicionais para o acampamento.",al={"como montar acampamento","como funciona o acampamento","montar um acampamento"}},{q="Você pode adicionar mobílias ao seu acampamento?",a="Enquanto a culinária fornece a fogueira que serve de base para o seu acampamento, outros instrutores de profissões por toda Azeroth podem ensinar artífices habilidosos a mobiliar e aprimorar seus acampamentos com equipamentos e decorações especializados.",al={"mobiliar acampamento","decorações de acampamento","mobílias de acampamento outras profissões"}},{q="Por que a culinária é necessária para acampar?",a="A culinária ensina os aventureiros a construir e manter uma fogueira a céu aberto nos ermos. Como o fogo é a peça central essencial de qualquer acampamento ao ar livre, aprender culinária é o primeiro passo necessário para acampar adequadamente na natureza.",al={"por que precisa de culinária para acampar","ligação da culinária com acampamento"}},{q="Você pode fazer fogueiras maiores?",a="Sim. À medida que você pratica sua arte culinária e aumenta sua perícia em culinária, você pode aprender a construir fogueiras maiores para dar melhor suporte aos seus acampamentos nos ermos.",al={"posso fazer fogueiras maiores","como aprimorar a fogueira"}}},fp="20,180,22.333.0,22.297.0,44.101.0,14.121.0,44.196.0,41.154.0,36.163.0,30.87.0"}
P.entries["quest:96638"] = {n="O aventureiro",s="“O aventureiro” é uma missão introdutória de viagem na Ilha de Zephras. Concedida por Aetheen of the Gales, no Bosque Thendal, ela encaminha andarilhos recém-iniciados para o sudoeste, rumo à Aldeia de Shen'dar, onde devem encontrar Raan Wildwind, um campista veterano que conhece as terras selvagens.",h="“O aventureiro” é uma missão introdutória de viagem na Ilha de Zephras.",kw={"aetheen of the gales","raan wildwind","aldeia de shen'dar","o aventureiro","bosque thendal","ilha de zephras"},ang={["race:Skyborne"]="Para os jovens Skyborne que deixam a copa protetora do Bosque Thendal, conhecer Raan Wildwind representa o primeiro passo verdadeiro rumo às terras mais vastas e selvagens de sua ilha natal."},sec={{t="Deixando o bosque",b="Embora o Bosque Thendal ofereça abrigo e tranquilidade, as vastidões da Ilha de Zephras continuam selvagens e perigosas. Aetheen of the Gales cuida dos iniciados e percebe quando um aspirante a viajante está pronto para ir além dos lugares conhecidos. Para quem busca fama, fortuna ou propósito, permanecer nos limites protegidos do bosque já não basta."},{t="Um guia na estrada",b="A sudoeste do bosque, na estrada para a Aldeia de Shen'dar, outro viajante já montou acampamento. Raan Wildwind conhece os perigos além daquele refúgio seguro. Procurá-lo oferece aos andarilhos iniciantes uma introdução prática à sobrevivência fora do Bosque Thendal, com os ensinamentos de alguém que já enfrentou as estradas selvagens."}},faq={{q="Quem envia você para encontrar Raan Wildwind?",a="Aetheen of the Gales concede a missão no Bosque Thendal. Depois que você prova seu valor nas matas próximas, ela incentiva você a procurar alguém que conhece os perigos do restante da ilha.",al={"quem oferece o aventureiro","quem inicia a missão o aventureiro","missão de aetheen"}},{q="Onde fica Raan Wildwind?",a="Raan Wildwind montou acampamento a sudoeste do Bosque Thendal, junto à estrada principal que leva à Aldeia de Shen'dar.",al={"localização de raan wildwind","onde fica raan","como encontrar raan wildwind"}},{q="Qual é o objetivo desta tarefa?",a="Ela orienta os viajantes a deixar a segurança do Bosque Thendal e os coloca em contato com mentores e desafios nas regiões mais distantes da Ilha de Zephras.",al={"por que fazer o aventureiro","objetivo da missão o aventureiro","o que raan ensina"}},{q="Qual missão é preciso concluir antes desta?",a="Você precisa concluir a tarefa relacionada à Foul Matriarch para Aetheen of the Gales antes que ela encaminhe você pela estrada até Raan Wildwind.",al={"pré-requisito de o aventureiro","requisitos para o aventureiro"}},{q="A Aldeia de Shen'dar é segura para os viajantes?",a="A Aldeia de Shen'dar fica pouco depois do acampamento de Raan, no fim da estrada que segue a sudoeste do Bosque Thendal. Embora seja um povoado importante da ilha, suas estradas e matas próximas exigem cautela dos jovens aventureiros.",al={"shen'dar é segura","o que é a aldeia de shen'dar"}},{q="Quem é Raan Wildwind?",a="Raan Wildwind é um andarilho aventureiro que deixou o Bosque Thendal e montou acampamento perto da Aldeia de Shen'dar. Ele oferece conselhos e tarefas aos recém-chegados que seguem pela estrada.",al={"história de raan","quem é raan wildwind"}}},fx={dc12ab9c={q="Por que Aetheen of the Gales envia você para encontrar Raan Wildwind?",a="Aetheen reconhece que mais andarilhos estão se aventurando além da segurança do Bosque Thendal em busca de glória e fortuna. Sabendo que a natureza selvagem apresenta grande perigo para os inexperientes, Aetheen quer que você procure Raan Wildwind — um companheiro de viagem acampado perto da Aldeia de Shen'dar — para aprender sabedoria prática e lições de sobrevivência que manterão você vivo durante suas jornadas pela ilha.",al={"por que aetheen envia você","motivo de aetheen of the gales","por que encontrar raan wildwind"}}},fp="14,209,17.275.0,19.252.0,36.189.0,31.96.0,33.100.0,64.113.0,39.179.0,21.174.0"}
P.entries["quest:96646"] = {n="Camping 101: Cooking",s="Camping 101: Cooking é uma missão introdutória que ensina aos aventureiros as artes culinárias como a base vital para a sobrevivência na natureza selvagem. Ao aprender a acender uma fogueira com Zerril Softbreeze na Aldeia de Shen'dar, os viajantes desbloqueiam a habilidade de montar seus próprios acampamentos na natureza.",h="Camping 101: Cooking é uma missão introdutória que ensina aos aventureiros as artes culinárias como a base...",kw={"fogueira","acampamento","local de acampamento","culinaria","mobilia","aldeia de shen'dar","zerril softbreeze"},ang={["profession:Cooking"]="Aprender a culinária básica fornece o conhecimento fundamental necessário para construir uma fogueira, estabelecendo a âncora central para qualquer acampamento na natureza."},sec={{t="O Lar da Natureza Selvagem",b="Para um aventureiro que viaja por terras selvagens, compreender a sobrevivência começa com o lar. Camping 101: Cooking apresenta aos andarilhos a arte do ofício culinário, não apenas para preparar refeições, mas porque dominar um fogo básico é o primeiro passo essencial para estabelecer um local seguro de descanso na natureza."},{t="Bases do Acampamento",b="Os aspirantes a campistas são orientados a falar com Zerril Softbreeze na Aldeia de Shen'dar para aprender os fundamentos do ofício da culinária. Assim que um aventureiro entende como acender uma fogueira, ele obtém a habilidade de estabelecer um pequeno acampamento em qualquer lugar da natureza selvagem. Embora acampamentos rudimentares suportem apenas mobílias mínimas, aprimorar seu ofício permite fogueiras maiores e arranjos mais ricos, criados com a ajuda de outras perícias."}},faq={{q="O que é Camping 101: Cooking?",a="É uma instrução introdutória sobre a vida selvagem que ensina aos aventureiros como a arte da culinária e o ato de acender fogueiras básicas servem de base para a montagem de um acampamento.",al={"o que e camping 101 cooking","missao de culinaria de acampamento"}},{q="Quem é Zerril Softbreeze?",a="Zerril Softbreeze é um instrutor de culinária situado na Aldeia de Shen'dar que instrui novatos nas artes culinárias básicas e em como acender uma fogueira.",al={"quem e zerril softbreeze","instrutor de culinaria shen'dar"}},{q="Por que a culinária é necessária para montar um acampamento?",a="A culinária ensina aos aventureiros como construir e manter uma fogueira, que atua como a base central ao redor da qual qualquer acampamento na natureza é estabelecido.",al={"por que aprender culinaria para acampar","por que precisa de culinaria para acampamento"}},{q="Onde Zerril Softbreeze está localizado?",a="Zerril Softbreeze pode ser encontrado ensinando profissões na Aldeia de Shen'dar.",al={"onde fica zerril softbreeze","localizacao da aldeia de shen'dar"}},{q="Como os acampamentos podem ser mobiliados?",a="Os novatos podem colocar mobílias básicas ao redor de suas fogueiras, mas aprender perícias de outros instrutores de profissão permite que os aventureiros criem e instalem mobílias adicionais no acampamento.",al={"mobilia de acampamento","como mobiliar o acampamento"}},{q="As fogueiras podem ser aprimoradas?",a="Ao avançar sua habilidade de culinária, você pode aprender a acender fogueiras ainda maiores para melhorar seus acampamentos na natureza selvagem.",al={"fogueiras maiores","melhorar acampamento"}}},fp="20,166,22.159.0,27.323.0,29.97.0,25.74.0,41.81.0,35.41.0,31.82.0,26.64.0"}
P.entries["quest:96652"] = {n="O aventureiro",s="Ao explorar as terras áridas e acidentadas de Durotar, viajantes encontram um diário simples e abandonado que registra as andanças tranquilas de alguém desconhecido. Suas páginas falam com carinho da vida ao ar livre e de acampar sob as estrelas. O diário deve ser entregue a Brakk, perto do Monte Navalha.",h="Ao explorar as terras áridas e acidentadas de Durotar, viajantes encontram um diário simples e abandonado que...",kw={"aventureiro","brakk","acampamento","durotar","diário","diário perdido","monte navalha"},ang={["class:Hunter"]="Caçadores acostumados a sobreviver do que a terra oferece certamente se identificam com as frequentes anotações do diário sobre os prazeres de acampar na natureza.",["faction:Horde"]="Muitos recrutas percorrem as trilhas áridas de Durotar. Recolher pertences perdidos e entregá-los a andarilhos como Brakk, perto do Monte Navalha, ajuda a manter a ordem na região."},sec={{t="Anotações de um andarilho",b="Durotar é uma terra implacável, onde sobreviver costuma ser mais importante do que viajar por prazer. Por isso, encontrar o diário de um andarilho é algo incomum. Abandonado na terra vermelha, o caderno modesto contém reflexões e aventuras de alguém completamente desconhecido dos heróis da Horda. Em vez de batalhas sangrentas ou grandes campanhas, suas páginas celebram os prazeres simples de dormir sob o céu aberto e acampar na natureza."},{t="Entrega para Brakk",b="Quem escreveu aquelas páginas deixou pistas ou algum vínculo que aponta para Brakk, um aventureiro acampado perto do Monte Navalha. Levar pertences de viajantes desaparecidos a quem conhece as estradas muitas vezes é a única maneira de reuni-los a seus donos ou, pelo menos, preservar sua lembrança entre os que percorrem os caminhos poeirentos."}},faq={{q="O que há no diário perdido?",a="O caderno é bastante comum, repleto de anotações cotidianas sobre as aventuras tranquilas de um viajante desconhecido. Acima de tudo, destaca repetidamente a alegria de montar acampamento na natureza.",al={"o que diz o diário","conteúdo do diário perdido","texto do diário"}},{q="Quem escreveu o diário?",a="O autor não é identificado nas páginas recuperadas. O diário descreve a vida e as viagens de alguém de quem você nunca tinha ouvido falar antes de encontrar o caderno na mata.",al={"quem é o aventureiro","autor do diário perdido","quem escreveu este livro"}},{q="Quem é Brakk?",a="Brakk é um aventureiro acampado perto do Monte Navalha, no centro de Durotar, que recebe o diário perdido.",al={"brakk monte navalha","quem é brakk","onde fica brakk"}},{q="Onde o diário é encontrado?",a="O diário simples é encontrado abandonado em Durotar, à espera de que algum viajante da Horda o recolha.",al={"onde encontro o diário","localização do diário perdido","início da missão o aventureiro"}},{q="Por que Brakk se interessa por esse diário?",a="A missão não explica. Brakk é um aventureiro experiente que acampa perto do Monte Navalha e ensina aos recém-chegados os fundamentos de acampar. Por isso, um diário cheio de histórias sobre acampamentos acaba sendo bem-vindo em suas mãos.",al={"por que levar o diário a brakk","objetivo de brakk","diário de brakk"}},{q="O aventureiro que escreveu o diário está em perigo?",a="As páginas recuperadas não indicam que tenha ocorrido algum crime; contêm apenas boas lembranças de acampamentos. Contudo, deixar um diário de viagem na poeira vermelha de Durotar sugere que o autor o perdeu sem querer ou partiu inesperadamente.",al={"o autor está vivo","o aventureiro morreu","paradeiro do aventureiro perdido"}}},fp="14,158,18.287.0,17.206.0,32.121.0,22.106.0,13.99.0,27.95.0,39.185.0,41.136.0"}
P.entries["quest:96655"] = {n="Camping 101: Cooking",s="Camping 101: Cooking apresenta aos aventureiros o ofício essencial de sobrevivência na natureza. Ao direcionar os viajantes até a Cozinheira Torka em Monte Navalha, ensina os fundamentos da culinária e da criação de fogueiras necessárias para estabelecer acampamentos pessoais na vida selvagem.",h="Camping 101: Cooking apresenta aos aventureiros o ofício essencial de sobrevivência na natureza.",kw={"fogueira","camping 101","camping 101: cooking","acampamento","cozinheira torka","culinária","durotar","mobílias","monte navalha"},ang={["faction:Horde"]="Aventureiros iniciantes por toda Durotar podem se apresentar à Cozinheira Torka em Monte Navalha para aprender o ofício fundamental da culinária.",["profession:Cooking"]="A culinária é o requisito principal para construir uma fogueira básica, formando a base indispensável para a sobrevivência na natureza e para a montagem de acampamentos."},sec={{t="O Fogo da Natureza Selvagem",b="Para qualquer andarilho que dê passos além dos portões dos povoados, sobreviver na natureza exige mais do que aço afiado e armadura resistente. A missão Camping 101: Cooking direciona aventureiros iniciantes à Cozinheira Torka em Monte Navalha para aprenderem as artes culinárias. Nas terras ermas abertas de Durotar e além, cozinhar representa muito mais do que preparar uma refeição quente — é a disciplina basilar necessária para acender uma fogueira confiável, que serve como o coração de qualquer acampamento."},{t="Construindo e Mobiliando um Acampamento",b="Dominar o básico permite que os viajantes montem um acampamento modesto em quase qualquer lugar da fronteira. Enquanto uma fogueira de principiante comporta apenas um punhado de mobílias essenciais, maior dedicação ao ofício abre novas possibilidades. Aprofundar os conhecimentos em culinária possibilita a construção de chamas maiores, enquanto dedicar-se a outras profissões concede a perícia necessária para mobiliar e aprimorar acampamentos, transformando-os em bastiões confiáveis contra a natureza indomada."}},faq={{q="O que é a missão Camping 101: Cooking?",a="Camping 101: Cooking é uma missão introdutória que ensina aos aventureiros os fundamentos da sobrevivência ao ar livre. Ao aprenderem culinária e a criação de fogueiras, os aventureiros adquirem a capacidade de estabelecer seus próprios acampamentos em qualquer lugar da natureza selvagem.",al={"o que é camping 101 cooking","missão camping 101 cooking","o que esta missão faz"}},{q="Quem é a Cozinheira Torka?",a="O Cozinheiro Torka é o instrutor de culinária da Horda localizado em Monte Navalha, em Durotar. Ele ensina aos aspirantes a aventureiros o básico da profissão de culinária e como acender uma fogueira básica.",al={"quem ensina culinária em monte navalha","quem é a cozinheira torka","onde fica a cozinheira torka"}},{q="Por que a culinária é necessária para acampar?",a="A culinária não serve apenas para preparar alimentos; a fogueira construída por meio da culinária atua como o ponto de sustentação fundamental para montar um acampamento. Sem uma fogueira, um acampamento adequado não pode ser mantido na natureza.",al={"por que preciso de culinária para acampar","relação entre culinária e fogueira","acampar exige culinária"}},{q="Onde um aventureiro pode montar um acampamento?",a="Depois de aprender o básico sobre culinária e criação de fogueiras, você é capaz de montar um pequeno acampamento em praticamente qualquer lugar na imensidão da natureza. Os acampamentos iniciais são básicos e não suportam muitas mobílias.",al={"onde posso acampar","como funciona o acampamento","posicionamento do acampamento"}},{q="Como você aprimora sua fogueira?",a="Conforme você eleva sua proficiência na profissão de culinária, pode aprender a construir fogueiras maiores e mais duradouras, permitindo maiores recursos para o acampamento.",al={"fogueiras maiores","aprimorar fogueira","como melhorar o acampamento"}},{q="Como você obtém mobílias para um acampamento?",a="Embora a culinária forneça a base da fogueira, outros instrutores de profissões pelo mundo podem ensinar os aventureiros a criar e posicionar mobílias adicionais para personalizar e expandir seus acampamentos.",al={"decorações de acampamento","mobiliar acampamento","instrutores de mobília de acampamento"}}},fp="20,131,22.315.0,30.329.0,39.148.0,18.139.0,36.149.0,42.177.0,33.133.0,45.155.0"}
P.entries["quest:96656"] = {n="O aventureiro",s="O aventureiro é uma tarefa introdutória concedida pelo Executor Arren a jovens campeões experientes dos Renegados, nos arredores de Plangemortis. Depois de provar seu valor contra a Cruzada Escarlate, você é enviado pela estrada rumo a Montalvo para investigar uma desconhecida que permanece perto do povoado. Em vez de revelar outra espiã fanática, a missão apresenta Eleanor Shackleton, uma viajante independente disposta a ensinar técnicas práticas de sobrevivência na natureza.",h="O aventureiro é uma tarefa introdutória concedida pelo Executor Arren a jovens campeões experientes dos...",kw={"montalvo","acampamento","plangemortis","eleanor shackleton","executor arren","cruzada escarlate","o aventureiro","a vida ao ar livre","clareiras de tirisfal"},ang={["faction:Horde"]="Enquanto o Executor Arren protege as fronteiras ainda frágeis do território dos Renegados, estabelecer contato pacífico com viajantes experientes em sobrevivência proporciona habilidades valiosas aos iniciados da Horda.",["race:Undead"]="Para os novos Renegados que partem de Plangemortis, conhecer uma aventureira Renegada como Eleanor é uma das primeiras lições de que nem todo estranho perto de Montalvo é um espião escarlate."},sec={{t="Uma vigilância desconfiada",b="O Executor Arren mantém vigilância constante sobre Plangemortis e seus acessos. Com os cruzados escarlates espionando a região e se infiltrando no norte de Lordaeron, qualquer recém-chegado visto nas proximidades de Montalvo desperta suspeitas. Depois que você demonstra dedicação eliminando ameaças da Cruzada na fronteira, Arren confia a você a investigação discreta daquela figura desconhecida para descobrir se ela representa algum perigo oculto aos Renegados."},{t="Uma viajante na floresta",b="Ao encontrar Eleanor Shackleton perto da estrada para Montalvo, fica claro que suas intenções nada têm a ver com as conspirações fanáticas da Cruzada ou a necromancia do Flagelo. Eleanor é apenas uma aventureira Renegada que descansa antes de outra jornada pela natureza. Ela reconhece o espírito aventureiro de quem foi enviado para investigá-la e se oferece para ensinar os fundamentos práticos de sobrevivência e de como montar acampamento."}},faq={{q="Por que o Executor Arren quer investigar Eleanor?",a="Plangemortis e Montalvo sofrem ameaças constantes de infiltrados da Cruzada Escarlate e espiões hostis. Qualquer estranho que permaneça nas proximidades da estrada principal é tratado com desconfiança até que suas intenções se mostrem inofensivas.",al={"por que investigar eleanor","quem me enviou até eleanor","tarefa de arren sobre eleanor"}},{q="Quem é Eleanor Shackleton?",a="Eleanor Shackleton é uma aventureira independente que acampa à beira da estrada perto de Montalvo. Não tem ligação com a Cruzada Escarlate e se dedica a explorar a natureza e compartilhar conhecimentos de sobrevivência com outros viajantes.",al={"quem é eleanor","história de eleanor shackleton","quem é a pnj aventureira"}},{q="Eleanor tem ligação com a Cruzada Escarlate?",a="Não. Ao chegar ao acampamento dela, Eleanor esclarece rapidamente que não tem qualquer relação com os cruzados fanáticos que ameaçam as Clareiras de Tirisfal.",al={"eleanor é da cruzada escarlate","eleanor é inimiga","eleanor é espiã"}},{q="Aonde esta missão leva?",a="Falar com Eleanor libera a missão “A vida ao ar livre”, na qual ela começa a ensinar os fundamentos de sobrevivência na natureza e de montagem de acampamentos.",al={"o que vem depois de o aventureiro","próxima missão após o aventureiro","continuação de eleanor shackleton"}},{q="Onde posso encontrar Eleanor Shackleton?",a="Ela monta acampamento perto da estrada principal que segue para leste, rumo a Montalvo, nas Clareiras de Tirisfal.",al={"localização de eleanor","onde fica eleanor shackleton","acampamento de eleanor em tirisfal"}},{q="Por que o Executor Arren escolheu você para esta missão?",a="Você conquistou a confiança de Arren ao ajudar a eliminar agentes e mensageiros da Cruzada Escarlate perto de Plangemortis, demonstrando capacidade para realizar missões delicadas de reconhecimento.",al={"por que me escolher","confiança de arren","por que o executor arren me envia"}}},fp="14,219,18.368.0,23.319.0,50.157.0,26.158.0,44.87.0,27.123.0,38.74.0,51.154.0"}
P.entries["quest:96658"] = {n="Introdução ao acampamento: Culinária",s="Introdução ao acampamento: Culinária ensina aos aventureiros iniciantes a arte essencial de acender uma fogueira e preparar alimentos na natureza. Encontrada nos povoados iniciais da Aliança e da Horda, essa lição apresenta a fogueira como o ponto central de qualquer acampamento improvisado ao ar livre.",h="Introdução ao acampamento: Culinária ensina aos aventureiros iniciantes a arte essencial de acender uma...",kw={"fogueira","introdução ao acampamento","culinária","vila d'ouro","shackleton","tomas","natureza","zarrin"},ang={["faction:Alliance"]="Novatos partindo de Vila Norte, Dun Morogh ou Teldrassil são guiados para cidades como Vila d'Ouro, Kharanos e Dolanaar para aprenderem autossuficiência antes de desbravar a natureza.",["faction:Horde"]="A sobrevivência é uma segunda natureza para a Horda, e jovens combatentes em Durotar, Mulgore e Tirisfal são direcionados diretamente para as fogueiras em Monte Navalha, Aldeia Casco Sangrento e Montalvo.",["profession:Cooking"]="A culinária é a faísca literal da vida de acampamento, fornecendo tanto o sustento vital para recuperar as forças quanto a fogueira central necessária para montar um bivaque ao ar livre."},sec={{t="O fogo que aquece a natureza",b="Para sobreviver fora das muralhas de uma cidade, todo viajante precisa saber como acender uma fogueira. Além de permitir ferver água e assar carne, uma fogueira simples serve de base para montar acampamento em território inexplorado. É o elemento central do acampamento apresentado nesta lição."},{t="Das Brasas aos Acampamentos",b="Enquanto cozinheiros aprendizes só conseguem manter um fogo modesto com arredores mínimos, dominar as artes culinárias desbloqueia a habilidade de acender labaredas maiores capazes de sustentar acampamentos mais elaborados. Além disso, aventureiros que se dedicam a outras profissões práticas descobrem maneiras de criar mobílias úteis para complementar seus acampamentos."}},faq={{q="Qual é o propósito desta missão?",a="A missão orienta os novos aventureiros a procurar um instrutor de Culinária nos povoados próximos, para aprender os fundamentos da profissão e a acender a fogueira necessária para montar um acampamento ao ar livre.",al={"por que fazer introdução ao acampamento","objetivo de introdução ao acampamento cooking","o que esta missão faz"}},{q="Quem oferece esta missão aos viajantes?",a="Vários guias experientes da natureza e aventureiros oferecem este treinamento em ambas as facções, incluindo Eleanor Shackleton, Eric Brighthammer, Lyreena Duskblade, Sam Sarsaparilla, Brakk, Kaga Wildhoof e Raan Wildwind.",al={"quem oferece introdução ao acampamento","concedente de missão de acampamento"}},{q="Onde os jogadores da Aliança entregam isso?",a="Aventureiros da Aliança se apresentam a instrutores como Tomas em Vila d'Ouro, Gremlock Pilsnor em Kharanos ou Zarrin em Dolanaar, dependendo de seu território de origem.",al={"onde entregar aliança","instrutor de culinária da aliança"}},{q="Onde os jogadores da Horda entregam isso?",a="Aventureiros da Horda podem concluir o treinamento com Cook Torka em Monte Navalha, William Pickman em Montalvo ou Pyall Silentstride na Aldeia Casco Sangrento.",al={"instrutor de culinária da horda","onde entregar horda"}},{q="O tamanho do acampamento pode ser expandido mais tarde?",a="Sim. Conforme você aumenta sua perícia em culinária, você pode aprender a acender fogueiras maiores que podem suportar mais mobílias de acampamento na natureza.",al={"fogueira maior","melhorar acampamento"}},{q="Outras profissões podem contribuir para o acampamento?",a="Sim. Enquanto a Culinária fornece a fogueira que sustenta o acampamento, instrutores de outras profissões ensinam a confeccionar itens úteis para o local, desde que você pratique esses ofícios.",al={"profissões de acampamento","mobílias de acampamento"}}},fp="39,310,28.300.0,27.380.0,35.219.0,40.225.0,44.172.0,41.160.0,55.165.0,55.198.0"}
P.entries["quest:96659"] = {n="O aventureiro",s="Enquanto os jovens taurens se preparam para deixar seus campos de treinamento ancestrais na Chapada Nuvem Vermelha, o Chefe Vento do Falcão pede a eles um último favor. Ele lhes confia um pacote de suprimentos essenciais destinados a Kaga Wildhoof, uma andarilha experiente acampada perto da Aldeia Casco Sangrento que outrora ajudou o próprio chefe no passado.",h="Enquanto os jovens taurens se preparam para deixar seus campos de treinamento ancestrais na Chapada Nuvem...",kw={"aldeia casco sangrento","aldeia narache","chefe vento do falcão","kaga wildhoof","mulgore","chapada nuvem vermelha","pacote de suprimentos","o aventureiro"},ang={["faction:Horde"]="O Chefe Vento do Falcão garante que os aliados viajantes da Horda que deixam a chapada inicial criem laços precoces com os andarilhos experientes e postos avançados de Mulgore.",["race:Tauren"]="Para os jovens taurens que saem da Aldeia Narache pela primeira vez, entregar o pagamento da dívida de honra de Vento do Falcão a Kaga Wildhoof representa seu primeiro serviço prestado aos seus semelhantes nas amplas planícies de Mulgore."},sec={{t="O Retorno de um Chefe",b="Antes que os viajantes desçam o caminho da chapada rumo às planícies mais amplas de Mulgore, o Chefe Vento do Falcão faz uma pausa para resolver dívidas pessoais pendentes. Muito antes de guiar novas gerações de caçadores e xamãs na Aldeia Narache, Vento do Falcão cruzou caminhos com Kaga Wildhoof. Descrita pelo chefe como uma aventureira talentosa, Wildhoof prestou ajuda vital quando ele mais precisava. Ao saber que ela acampou nos arredores da Aldeia Casco Sangrento, Vento do Falcão aproveita a partida dos novatos recém-provados para enviar provisões à sua antiga benfeitora."},{t="Deixando a Chapada",b="Esta incumbência marca um rito de passagem crucial para os jovens campeões da Horda que deixam a Chapada Nuvem Vermelha. A trilha descendo o platô leva diretamente à Aldeia Casco Sangrento, o coração cultural e logístico da região central de Mulgore. Levar o Pacote de Suprimentos através das planícies une a vida protegida de treinamento da chapada às lutas mais amplas e ferozes das Tribos Unidas dos Taurens."}},faq={{q="Quem é Kaga Wildhoof?",a="Kaga Wildhoof é uma experiente aventureira tauren que recentemente montou acampamento nos arredores da Aldeia Casco Sangrento. Ela tem uma longa história de amizade com o Chefe Vento do Falcão, a quem prestou grande ajuda em anos anteriores.",al={"kaga wildhoof","quem e wildhoof","onde esta kaga"}},{q="Por que o Chefe Vento do Falcão envia esses suprimentos?",a="Vento do Falcão vê a partida dos jovens campeões em direção à Aldeia Casco Sangrento como a oportunidade ideal para retribuir um antigo favor a Wildhoof, garantindo que sua companheira de aventuras tenha suprimentos novos para suas viagens.",al={"divida de vento do falcao","por que enviar suprimentos","proposito do pacote de suprimentos"}},{q="Onde fica o acampamento de Kaga Wildhoof?",a="O acampamento dela fica nas planícies, nos arredores da Aldeia Casco Sangrento, descendo o caminho sinuoso do sul que sai da Chapada Nuvem Vermelha em direção ao centro de Mulgore.",al={"localizacao do acampamento de kaga","encontrar kaga","acampamento da aldeia casco sangrento"}},{q="Quando esta missão fica disponível?",a="O Chefe Vento do Falcão oferece a tarefa assim que o viajante prova seu valor na Chapada Nuvem Vermelha e está pronto para se aventurar pelos territórios mais amplos de Mulgore.",al={"quando pego o aventureiro","momento da missao de vento do falcao","missao de saida da chapada"}},{q="Esta missão leva você para longe da Aldeia Narache?",a="Sim. Levar os suprimentos serve como um incentivo direto para deixar a Aldeia Narache para trás e seguir pela trilha em direção à Aldeia Casco Sangrento.",al={"deixando a chapada nuvem vermelha","jornada para casco sangrento"}},{q="O que está contido no Pacote de Suprimentos?",a="O pacote consiste em provisões essenciais reunidas pelas tribos da Aldeia Narache para sustentar uma aventureira que sobrevive fora de assentamentos organizados.",al={"o que sao os suprimentos","conteudo do pacote de suprimentos"}}},fx={["2c6e5885"]={q="Por que o Chefe Vento do Falcão pede a você para entregar os suprimentos?",a="Você completou seus ritos iniciais na Chapada Nuvem Vermelha e está se preparando para deixar a Aldeia Narache para se aventurar nas planícies mais amplas de Mulgore. Como sua partida já o leva pela Aldeia Casco Sangrento, o Chefe Vento do Falcão confia a você este recado, em vez de despachar bravos que são necessários para proteger a chapada e resguardar os jovens tauren que treinam lá.",al={"por que eu hawkwind","por que me enviar com suprimentos","por que hawkwind escolhe a mim"}}},fp="14,173,23.296.0,16.244.0,21.122.0,44.92.0,38.111.0,38.117.0,48.86.0,43.94.0"}
P.entries["quest:96661"] = {n="Camping 101: Cooking",s="Na Aldeia Casco Sangrento, Pyall Silentstride inicia suas lições de culinária e fogueiras. Por toda Kalimdor, essas habilidades ajudam você a montar um acampamento e preparar refeições com carne de caça.",h="Na Aldeia Casco Sangrento, Pyall Silentstride inicia suas lições de culinária e fogueiras.",kw={"aldeia casco sangrento","fogueira","camping 101","acampamento","culinária","mobílias","pyall silentstride","natureza selvagem"},ang={["faction:Horde"]="Como viajante da Horda em Mulgore, você começa seu treinamento de sobrevivência na Aldeia Casco Sangrento, onde artesãos e cozinheiros taurens podem orientar você.",["profession:Cooking"]="Como cozinheiro, você aprende a acender a fogueira no centro de um acampamento e preparar comida para a vida na natureza."},sec={{t="O Lar da Natureza Selvagem",b="Quando a noite cai, uma fogueira oferece um lugar para onde voltar. Por toda Kalimdor, os fundamentos da culinária ensinam você a acender uma fogueira na natureza. Também mostram como preparar refeições nutritivas com carne de caça, tornando a culinária parte da sobrevivência ao ar livre."},{t="Construindo o Acampamento",b="Na Aldeia Casco Sangrento, em Mulgore, Pyall Silentstride ensina os fundamentos da culinária. Com esse treinamento, você pode acender uma fogueira e montar um acampamento simples em meio à natureza. Conforme sua habilidade em culinária aumenta, você aprende a fazer fogueiras maiores. Outros ofícios podem fornecer mobília para seu posto avançado."}},faq={{q="O que é Camping 101: Cooking?",a="A culinária ensina você a acender uma fogueira e estabelecer um acampamento em meio à natureza.",al={"o que é camping 101 cooking","missão de culinária acampamento","básicos de acampamento culinária"}},{q="Quem é Pyall Silentstride?",a="Pyall Silentstride ensina culinária na Aldeia Casco Sangrento, em Mulgore. Ele mostra a aventureiros iniciantes como cozinhar e fazer fogueiras simples.",al={"quem é pyall silentstride","localização de pyall silentstride","instrutor de culinária casco sangrento"}},{q="Por que a culinária é necessária para aprender a acampar?",a="A culinária ensina você a acender uma fogueira, o centro prático de um acampamento, e preparar refeições.",al={"por que precisa de culinária para acampar","por que aprender culinária para acampar","conexão fogueira acampamento"}},{q="É possível fazer fogueiras maiores conforme sua perícia melhora?",a="Conforme sua habilidade em culinária melhora, você aprende a fazer fogueiras maiores para acampamentos mais estruturados.",al={"posso aprimorar fogueiras","fogueiras maiores","como fazer fogueiras maiores"}},{q="Como mobiliar um acampamento?",a="Outros ofícios podem fornecer mobília para seu acampamento. Você pode fabricar esses móveis se tiver aprendido esses ofícios.",al={"como funcionam as mobílias de acampamento","decorações de acampamento","mobiliar acampamentos profissões"}},{q="Onde você pode montar um acampamento?",a="Depois que a culinária ensinar você a acender uma fogueira, você poderá estabelecer um acampamento simples em plena natureza por onde viajar.",al={"onde montar acampamento","posso acampar em qualquer lugar","restrições de acampamento"}}},fp="20,177,22.243.0,17.274.0,29.84.0,26.132.0,42.95.0,53.95.0,30.107.0,28.125.0"}
P.entries["quest:967"] = {n="A Torre de Althalaxx",s="Esta missão conecta a investigação da Seita da Linhagem das Trevas no norte de Costa Negra com a defesa mais ampla do norte de Kalimdor. Balthule Umbrataque envia um mensageiro da Aliança para o sul, rumo ao Entreposto de Maestra no Vale Gris, para alertar seu mentor, Dinis, o Purificador, sobre a sinistra reunião do culto na Torre de Althalaxx.",h="Esta missão conecta a investigação da Seita da Linhagem das Trevas no norte de Costa Negra com a defesa mais...",kw={"vale gris","balthule umbrataque","linhagem das trevas","costa negra","dinis, o purificador","luz sagrada","entreposto de maestra","torre de althalaxx"},ang={["class:Paladin"]="Encontrar Dinis oferece aos paladinos um exemplo inspirador de seu chamado sagrado em terras desconhecidas: um cruzado humano empunhando a Luz para conquistar a profunda confiança dos reclusos elfos noturnos de Kalimdor.",["faction:Alliance"]="A cooperação entre Balthule em Costa Negra e Dinis no Vale Gris demonstra as linhas de comunicação vitais que mantêm unidas as guarnições dispersas da Aliança no norte de Kalimdor.",["race:NightElf"]="Para os elfos noturnos, esta missão destaca a parceria prática e crescente entre suas Sentinelas e as raças orientais que vieram para ajudar a erradicar resquícios demoníacos de suas florestas."},sec={{t="Um Pedido de Reforços",b="Após confrontos iniciais com os cultistas da Linhagem das Trevas ao redor da Torre de Althalaxx, o batedor elfo noturno Balthule Umbrataque reconhece que a ameaça supera sua vigília solitária. Para organizar uma resposta decisiva, ele escreve um relatório detalhado e o confia a um mensageiro da Aliança destinado a seu mestre, Dinis, o Purificador. Como os invocadores do culto estão ficando mais ousados a cada hora, a notícia precisa chegar a uma liderança experiente capaz de coordenar um esforço de erradicação."},{t="A Estrada para o Vale Gris",b="Levar o despacho de Balthule exige uma travessia por toda a extensão de Costa Negra, seguindo a longa estrada costeira para o sul, saindo da névoa e cruzando a fronteira arborizada rumo ao Vale Gris. Estacionado no Entreposto de Maestra ao longo da estrada oeste, Dinis, o Purificador, dedicou-se a purificar demônios e mortos-vivos que assolam a floresta. Embora inicialmente não fosse familiarizado com os costumes dos elfos noturnos, o paladino humano forjou um profundo respeito mútuo com as Sentinelas como um aliado indispensável."},{t="Um Guerreiro Sagrado Desperto",b="Dinis recebe a carta urgente de Balthule com sombria determinação. Como um guerreiro devoto da Luz Sagrada, ele vê a presença de cultistas sombrios, corrupção de almas e demônios nessas florestas ancestrais como uma praga intolerável. Ao ler sobre a base consolidada do Linhagem das Trevas na torre arruinada dos altaneiros, Dinis imediatamente se prepara para assumir o comando da operação e contra-atacar."}},faq={{q="Quem é Dinis, o Purificador?",a="Dinis, o Purificador, é um paladino humano estacionado no Entreposto de Maestra, no Vale Gris. Devoto da Luz Sagrada, ele oferece seus conhecimentos marciais e espirituais às Sentinelas elfas noturnas para purificar demônios e mortos-vivos que avançam sobre suas florestas ancestrais.",al={"dinis, o purificador","quem é dinis","história de dinis"}},{q="Por que Balthule Umbrataque está enviando um mensageiro para o Vale Gris?",a="Balthule é um batedor posicionado perto da Torre de Althalaxx que vem estudando a Seita da Linhagem das Trevas. Reconhecendo que os rituais sombrios e o contingente do culto estão aumentando rapidamente, ele envia suas descobertas ao seu mentor Dinis para que um ataque organizado possa ser preparado.",al={"por que enviar carta a dinis","motivo da carta de balthule"}},{q="Qual é a relação entre Balthule e Dinis?",a="Dinis é o mestre de Balthule. O paladino humano instruiu o elfo noturno na arte da batalha e o apresentou aos ensinamentos da Luz Sagrada, nutrindo um vínculo extraordinariamente próximo em meio às suas diferenças culturais.",al={"balthule e dinis","como balthule e dinis se conhecem"}},{q="Onde fica o Entreposto de Maestra?",a="O Entreposto de Maestra é um entreposto da Aliança situado no oeste do Vale Gris, ao longo da estrada principal que leva ao sul a partir de Costa Negra. Ele serve como um posto avançado de vigia para viajantes que transitam entre Costa Negra e as profundezas da floresta.",al={"localização do entreposto de maestra","onde fica o entreposto de maestra"}},{q="O que a Seita da Linhagem das Trevas está fazendo na Torre de Althalaxx?",a="A Seita da Linhagem das Trevas é uma organização que atua a partir da Torre de Althalaxx em ruínas, no norte de Costa Negra. Seus membros praticam artes sombrias, fazem pactos com poderes demoníacos e ameaçam espalhar a corrupção por todo o litoral.",al={"seita linhagem das trevas althalaxx","cultistas da torre de althalaxx"}},{q="Como Dinis vê sua aliança com os elfos noturnos?",a="Dinis admitiu que inicialmente não estava acostumado aos costumes e ao estilo de vida dos elfos noturnos quando chegou a Kalimdor. Com o tempo, no entanto, lutar ao lado deles contra males em comum o levou a desenvolver um imenso respeito pelas Sentinelas.",al={"dinis elfos noturnos","paladino humano elfos noturnos"}}},fx={["4ad41352"]={q="Por que Balthule escolhe você como mensageiro em vez de ir ele mesmo?",a="Balthule precisa permanecer perto da Torre de Althalaxx para vigiar os cultistas da Linhagem das Trevas e acompanhar a ameaça crescente que representam. Como a viagem atravessa toda a extensão de Costa Negra até o Vale Gris, ele precisa de alguém capaz e bem armado para sobreviver às estradas perigosas e garantir que o aviso urgente chegue em segurança às mãos de Dinis.",al={"por que me enviar para dinis","por que mensageiro de balthule","por que balthule não pode entregar a carta"}}},fp="22,206,25.325.0,21.382.0,23.356.1,28.234.0,62.216.0,54.179.0,24.149.0,61.217.0,56.159.0"}
P.entries["quest:96770"] = {n="The Witch Doctor's Head",s="O arquimago Lan'dalock pede que você mate o médico-feiticeiro Sandfury Zum'rah, em Zul'Farrak, e traga sua cabeça intacta. O pedido se baseia na história que Lan'dalock tem com o troll.",h="O arquimago Lan'dalock pede que você mate o médico-feiticeiro Sandfury Zum'rah, em Zul'Farrak, e traga sua...",kw={"dalaran","lan'dalock","sandfury","tanaris","troll","médico-feiticeiro","zul'farrak","zum'rah","zumrah"},sec={{t="O pedido de Lan'dalock",b="O arquimago Lan'dalock, em Dalaran, quer Zum'rah morto. O médico-feiticeiro está em Zul'Farrak, reduto dos Sandfury nas profundezas de Tanaris. Lan'dalock diz que tem uma história com Zum'rah e pede que você volte com a cabeça do troll intacta. Seu pedido se baseia nessa antiga desavença."}},faq={{q="Quem é Zum'rah?",a="Zum'rah é um médico-feiticeiro troll que está em Zul'Farrak, reduto dos Sandfury em Tanaris.",al={"zumrah","médico-feiticeiro zum'rah","médico-feiticeiro sandfury"}},{q="Quem quer Zum'rah morto?",a="O arquimago Lan'dalock, em Dalaran, pede que você mate Zum'rah. Ele diz que tem uma história com o troll.",al={"quem deu isso","lan'dalock","por que matar zumrah"}},{q="Onde está Zum'rah?",a="Zum'rah está em Zul'Farrak, nas profundezas dos desertos de Tanaris.",al={"onde encontrar zumrah","zul'farrak","troll de tanaris"}},{q="Por que Lan'dalock quer que ele seja morto?",a="Lan'dalock diz que tem uma história com Zum'rah, mas não dá mais detalhes.",al={"desavença de lan'dalock","por que o arquimago quer zumrah morto","história com zumrah"}},{q="O que Lan'dalock pede que você traga?",a="Lan'dalock pede que você traga a cabeça de Zum'rah intacta.",al={"o que trazer de volta","cabeça de zumrah","cabeça intacta"}}},fp="23,181,20.267.0,15.86.0,23.95.0,17.61.0,36.73.0,43.55.0"}
P.entries["quest:96771"] = {n="Vengeance of the Highborne",s="Um patrono pede que você encontre Zalfan Moonshadow na Fortaleza de Krol'Dok, nas Sendas do Rio. Ele condena os laços de Zalfan com o Martelo do Crepúsculo e o uso de conhecimento arcano roubado.",h="Um patrono pede que você encontre Zalfan Moonshadow na Fortaleza de Krol'Dok, nas Sendas do Rio.",kw={"highborne","fortaleza de krol'dok","sendas do rio","conhecimento arcano roubado","martelo do crepúsculo","vingança dos highborne","zalfan moonshadow"},sec={{t="Um Highborne nas Glades",b="Um patrono indica a você a Fortaleza de Krol'Dok, a sudeste, nas Sendas do Rio, onde Zalfan Moonshadow foi visto com o Martelo do Crepúsculo. Ele chama Zalfan de vergonha para os Highborne e o acusa de servir a fanáticos com conhecimento arcano roubado. O patrono oferece uma generosa recompensa pela morte de Zalfan."}},faq={{q="Quem é Zalfan Moonshadow?",a="Zalfan Moonshadow é um Highborne visto na Fortaleza de Krol'Dok com o Martelo do Crepúsculo.",al={"zalfan","quem é zalfan"}},{q="Onde está Zalfan?",a="Zalfan foi visto na Fortaleza de Krol'Dok, nas Sendas do Rio, a sudeste daqui.",al={"onde está zalfan","localização de kroldok"}},{q="Por que o patrono quer Zalfan morto?",a="O patrono diz que Zalfan envergonha os Highborne ao se associar ao Martelo do Crepúsculo e usar conhecimento arcano roubado a serviço deles.",al={"por que matar zalfan","problema com zalfan"}},{q="O que o patrono oferece?",a="O patrono oferece uma generosa recompensa a quem matar Zalfan Moonshadow.",al={"recompensa por zalfan","prêmio por zalfan"}}},fp="26,173,25.297.0,25.88.0,16.82.0,37.145.0,27.69.0"}
P.entries["quest:96773"] = {n="The Coldbringer's Eye",s="O Kirin Tor busca o Coldbringer’s Eye, um orbe de vidência usado por um servo do Lich King no Urzal dos Mortos. Pedem que você o recupere para que o artefato possa ser estudado.",h="O Kirin Tor busca o Coldbringer’s Eye, um orbe de vidência usado por um servo do Lich King no Urzal dos...",kw={"coldbringer","coldbringer's eye","kirin tor","lich king","quilboar","urzal dos mortos","orbe de vidência","servo"},sec={{t="Um pedido do Kirin Tor",b="Um servo do Lich King vive no Urzal dos Mortos, onde o covil dos quilboar lhe serve de abrigo. O Kirin Tor diz que ele usa o Coldbringer’s Eye para comandar lacaios inferiores em outros lugares. Pedem que você recupere o orbe para que possam estudá-lo."}},faq={{q="O que é o Coldbringer’s Eye?",a="O Coldbringer’s Eye é um orbe de vidência usado por um servo do Lich King no Urzal dos Mortos.",al={"coldbringer eye","o que é o olho","orbe de vidência"}},{q="Quem quer o Coldbringer’s Eye?",a="O Kirin Tor quer o Coldbringer’s Eye para estudar o artefato e entender como ele funciona.",al={"quem quer o orbe","olho do kirin tor","quem pediu"}},{q="Onde está o Coldbringer’s Eye?",a="O Coldbringer’s Eye está no Urzal dos Mortos.",al={"onde está o olho","orbe do urzal dos mortos","localização do olho"}},{q="Quem usa o orbe?",a="Um servo do Lich King no Urzal dos Mortos usa o orbe para comandar lacaios inferiores em outros lugares.",al={"quem tem o olho","servo do lich king","usuário de coldbringer"}}},fp="21,172,19.228.0,32.94.0,34.101.0,33.45.0,17.93.0"}
P.entries["quest:96775"] = {n="Zum'rah's Head",s="Mazu'kon pede que você cace Zum'rah em Zul'Farrak, onde o médico-feiticeiro pratica vodu. Ele quer que você traga a cabeça de Zum'rah para Mulgore.",h="Mazu'kon pede que você cace Zum'rah em Zul'Farrak, onde o médico-feiticeiro pratica vodu.",kw={"cabeça","mazu'kon","mulgore","sandfury","tanaris","médico-feiticeiro","zul'farrak","zum'rah"},sec={{t="Uma caçada em Tanaris",b="Mazu'kon, em Mulgore, envia você para o sul, até Zul'Farrak, uma cidade Sandfury em Tanaris. Zum'rah é um médico-feiticeiro que pratica vodu por lá, e Mazu'kon quer que você o mate. Você deve trazer a cabeça do médico-feiticeiro de volta para Mulgore."}},faq={{q="Quem é Zum'rah?",a="Zum'rah é um médico-feiticeiro que pratica vodu na cidade Sandfury de Zul'Farrak.",al={"quem é zumrah","médico-feiticeiro zumrah"}},{q="Onde posso encontrar Zum'rah?",a="Zum'rah está em Zul'Farrak, uma cidade Sandfury em Tanaris.",al={"localização de zumrah","onde fica zumrah"}},{q="Quem me pede para caçar Zum'rah?",a="Mazu'kon, em Mulgore, pede que você mate Zum'rah e traga a cabeça dele de volta.",al={"missão de mazu'kon","quem quer zumrah morto"}},{q="O que Mazu'kon quer que eu traga de volta?",a="Mazu'kon quer que você leve a cabeça de Zum'rah até ele, em Mulgore.",al={"cabeça de zumrah","trazer a cabeça dele"}}},fp="14,142,17.220.0,15.82.0,25.53.0,28.69.0,41.58.0"}
P.entries["quest:96781"] = {n="What's the Big Idea?",s="Myrokos Silentform, na Mansão de Corvoforte, pede que você descubra o que a Camarilha procura nas Ruínas de Alterac. Barton está com os relatórios de reconhecimento que podem revelar seus planos.",h="Myrokos Silentform, na Mansão de Corvoforte, pede que você descubra o que a Camarilha procura nas Ruínas de...",kw={"barton","myrokos silentform","mansão de corvoforte","ruínas de alterac","relatório de reconhecimento","strahnbrad","camarilha"},ang={["class:Rogue"]="Como ladino, você deve pegar o relatório de Barton sem matá-lo."},sec={{t="Relatório de Barton",b="Na Mansão de Corvoforte, Myrokos Silentform precisa do relatório de reconhecimento de Barton. Um grupo da Camarilha liderado por Barton ronda as Ruínas de Alterac em busca de algo. Você deve pegar o relatório sem matá-lo, para que a Camarilha não saiba que seus planos foram descobertos."}},faq={{q="Quem é Barton?",a="Barton lidera um grupo de reconhecimento da Camarilha que ronda as Ruínas de Alterac.",al={"barton","quem é barton","batedor da camarilha"}},{q="O que a Camarilha está procurando?",a="O grupo da Camarilha procura algo nas Ruínas de Alterac, mas Myrokos precisa do relatório de reconhecimento de Barton para descobrir o quê.",al={"o que a camarilha procura","o que estão procurando","busca da camarilha"}},{q="Por que Myrokos quer o relatório?",a="Myrokos Silentform quer o relatório para descobrir o que a Camarilha está procurando.",al={"por que pegar o relatório","relatório de barton","grande ideia"}},{q="Por que não matar Barton?",a="Se Barton morrer, a Camarilha perceberá que está sendo observada e poderá tentar encobrir seus rastros.",al={"não matar barton","bater carteira de barton","por que roubar o relatório"}},{q="Onde Barton pode ser encontrado?",a="É provável que Barton esteja entre os membros da Camarilha em Strahnbrad.",al={"onde está barton","encontrar barton","batedor em strahnbrad"}},{q="Para quem vai o relatório?",a="O relatório de reconhecimento de Barton deve ser entregue a Myrokos Silentform, na Mansão de Corvoforte.",al={"quem recebe o relatório","onde levar o relatório","myrokos"}}},fp="20,173,17.280.0,14.77.0,36.129.0,33.81.0,20.107.0,26.56.0,25.77.0"}
P.entries["quest:96782"] = {n="Covert Extraction",s="Myrokos Silentform procura duas relíquias da família Perenolde nas Ruínas de Alterac. A Camarilha também está atrás delas.",h="Myrokos Silentform procura duas relíquias da família Perenolde nas Ruínas de Alterac.",kw={"alterac","blade of house perenolde","extração encoberta","myrokos silentform","ogros","royal aegis of perenolde","camarilha"},sec={{t="As relíquias",b="Nas Ruínas de Alterac, Myrokos Silentform quer que você recupere duas relíquias da House Perenolde. Segundo um relatório, a Blade of House Perenolde e a Royal Aegis of Perenolde estão em duas torres. A Camarilha também as procura, enquanto ogros ocupam as ruínas. Myrokos pede que você leve as duas relíquias até ele."}},faq={{q="Quem quer as relíquias de Perenolde?",a="Myrokos Silentform quer que você recupere a Blade of House Perenolde e a Royal Aegis of Perenolde.",al={"quem me enviou","quem quer estas relíquias"}},{q="Quais são as duas relíquias?",a="São a Blade of House Perenolde, uma espada, e a Royal Aegis of Perenolde, um escudo.",al={"relíquias de perenolde","espada e escudo"}},{q="Onde estão as relíquias?",a="Um relatório situa a Blade of House Perenolde e a Royal Aegis of Perenolde em duas torres entre as Ruínas de Alterac.",al={"onde estão as relíquias","localização das relíquias de perenolde"}},{q="Por que Myrokos as quer?",a="A Camarilha também está atrás das duas relíquias de Perenolde, então Myrokos quer que você as obtenha primeiro.",al={"por que recuperar as relíquias","por que ele precisa delas"}},{q="Quem ocupa as ruínas?",a="Ogros ocupam as Ruínas de Alterac.",al={"ogros em alterac","o que há nas ruínas"}}},fp="17,106,13.312.0,34.103.0,27.91.0,24.119.0,27.100.0,23.34.0"}
P.entries["quest:96783"] = {n="A Way In",s="Uma negociação da Camarilha leva você à Bastilha de Stromgarde, no Planalto Arathi. Você precisa de um disfarce da Casa Grande do Norte para entrar sem levantar suspeitas.",h="Uma negociação da Camarilha leva você à Bastilha de Stromgarde, no Planalto Arathi.",kw={"uma forma de entrar","planalto arathi","casa grande do norte","bastilha de stromgarde","camarilha","negociação","uniforme"},sec={{t="Uma negociação oculta",b="Um contato envia você à Bastilha de Stromgarde, no Planalto Arathi, onde a Camarilha conduz negócios importantes dentro de suas muralhas. O contato recebeu notícias de uma negociação entre membros da Camarilha, e os detalhes podem estar dentro da bastilha. Para entrar sem levantar suspeitas, você precisa de um uniforme da Camarilha da Casa Grande do Norte."}},faq={{q="O que está acontecendo na Bastilha de Stromgarde?",a="A Camarilha usa a Bastilha de Stromgarde como uma de suas maiores fortalezas, e uma negociação entre seus membros está acontecendo em algum lugar do Planalto Arathi.",al={"negociação em stromgarde","o que há em stromgarde","bastilha da camarilha"}},{q="Por que estou indo à Casa Grande do Norte?",a="Você está procurando um uniforme da Camarilha na Casa Grande do Norte para se disfarçar antes de entrar na Bastilha de Stromgarde.",al={"casa grande do norte","por que northfold","conseguir disfarce"}},{q="Do que preciso para entrar na bastilha?",a="Você precisa de um uniforme da Camarilha da Casa Grande do Norte para entrar na Bastilha de Stromgarde sem levantar suspeitas.",al={"uniforme","disfarce da camarilha","como entrar em stromgarde"}},{q="Do que se trata a negociação da Camarilha?",a="A negociação ocorre entre membros da Camarilha em algum lugar do Planalto Arathi. Os detalhes podem ser encontrados dentro da Bastilha de Stromgarde.",al={"acordo da camarilha","qual negociação","detalhes da negociação"}}},fp="8,144,14.314.0,37.152.0,34.112.0,33.102.0,34.122.0"}
P.entries["quest:96785"] = {n="Ain't No Telling",s="Anastasia, na Bastilha de Stromgarde, não falará sobre o acordo secreto de seus superiores sem um motivo. Você precisa de algo valioso o bastante para fazê-la falar.",h="Anastasia, na Bastilha de Stromgarde, não falará sobre o acordo secreto de seus superiores sem um motivo.",kw={"não dá para saber","anastasia","superiores","acordo secreto","bastilha de stromgarde","valioso"},sec={{t="Um motivo para falar",b="Na Bastilha de Stromgarde, Anastasia se recusa a contar a um recém-chegado o que seus superiores estão fazendo. Ela pede algo importante ou valioso antes de falar. Você precisa encontrar algo na bastilha que a convença a dar detalhes sobre o acordo secreto."},{t="A barganha",b="Anastasia reage quando você mostra o que encontrou. Ela concorda em contar sobre o acordo se você devolver o objeto a ela."}},faq={{q="Quem é Anastasia?",a="Anastasia pode dar detalhes sobre o acordo secreto de seus superiores.",al={"anastasia","quem é anastasia","acordo de anastasia"}},{q="Por que Anastasia não quer falar?",a="Anastasia diz que não vai contar sobre os assuntos de seus superiores sem um bom motivo.",al={"por que ela não quer falar","anastasia não conta","por que tanto segredo"}},{q="O que Anastasia quer?",a="Anastasia pede algo importante ou valioso antes de discutir o acordo.",al={"o que ela quer","dar algo a anastasia","barganha de anastasia"}},{q="Onde procuro algo para convencê-la?",a="Anastasia pede que você encontre algo na Bastilha de Stromgarde para convencê-la.",al={"onde procurar","encontrar algo para anastasia","item da bastilha de stromgarde"}}},fp="16,145,16.257.0,11.116.1,17.84.0,25.82.0,25.84.0,46.76.0"}
P.entries["quest:968"] = {n="Ferramentas dos Altaneiros",s="Ferramentas dos Altaneiros é uma missão da Aliança oferecida por Trovejius Tecevento em Auberdine. Os viajantes são enviados ao sul, às ruínas de Ameth'Aran, para recuperar relíquias mágicas que ainda estão nas mãos de aparições inquietas dos Altaneiros. O objetivo é simples: recolher os artefatos antigos antes que sua magia latente cause mais danos a Kalimdor.",h="Ferramentas dos Altaneiros é uma missão da Aliança oferecida por Trovejius Tecevento em Auberdine.",kw={"ameth'aran","auberdine","costa negra","altaneiros","relíquias","grande cisão","trovejius tecevento"},ang={["class:Druid"]="Remover os vestígios arcanos corrompidos de Ameth'Aran ajuda a curar as feridas espirituais que perturbam o equilíbrio natural das terras selvagens de Costa Negra.",["class:Mage"]="Enquanto os kaldorei procuram destruir esses artefatos por medo, estudiosos do arcano os reconhecem como exemplos raros e bem preservados do artesanato dos Altaneiros anterior à Grande Cisão.",["faction:Alliance"]="Ajudar os elfos noturnos a proteger seus territórios assombrados fortalece a presença e a solidariedade da Aliança nas florestas ancestrais do norte de Kalimdor.",["race:NightElf"]="Para os kaldorei, enfrentar os fantasmas de Ameth'Aran é uma lembrança sombria da arrogância dos antepassados e da cisão catastrófica de seu antigo império."},sec={{t="Ecos nas ruínas",b="Ao sul de Auberdine, a leste da estrada costeira, ficam os alicerces de pedra de Ameth'Aran, cobertos pela vegetação. Dez mil anos atrás, esse povoado foi um bastião dos Altaneiros, a aristocracia privilegiada do antigo império dos elfos noturnos. Quando seus experimentos arcanos desenfreados culminaram na Grande Cisão, Ameth'Aran foi destruída. Seus habitantes, porém, nunca partiram de verdade. As Sentinelas que patrulham Costa Negra relatam que os fantasmas desses aristocratas ainda assombram as praças arruinadas, segurando as ferramentas e os adornos encantados que possuíam em vida."},{t="Purificando o passado arcano",b="Para a sociedade kaldorei atual, a magia arcana não é apenas um conhecimento proibido, mas uma ameaça à própria existência que quase exterminou a vida em Azeroth. Trovejius Tecevento sabe que deixar os instrumentos dos Altaneiros nas mãos dos fantasmas abre caminho para mais corrupção. Ao enviar aventureiros para arrancar essas relíquias dos espíritos inquietos, ele pretende garantir sua destruição definitiva, impedindo que a magia maculada e adormecida cause outro desastre."}},faq={{q="Onde encontro as relíquias dos Altaneiros?",a="As relíquias estão nas ruínas de Ameth'Aran, ao sul de Auberdine, a leste da estrada principal de Costa Negra. Os espíritos que vagam pelos pátios de pedra carregam esses instrumentos antigos.",al={"onde ficam as relíquias","localização de ameth'aran","onde encontrar as relíquias"}},{q="Quem é Trovejius Tecevento?",a="Trovejius Tecevento é um estudioso e ancião elfo noturno que vive na cidade portuária de Auberdine. Em colaboração com as Sentinelas locais, ele coordena esforços para proteger Costa Negra das antigas maldições e da magia corrompida deixadas pela Grande Cisão.",al={"trovejius tecevento","quem oferece ferramentas dos altaneiros"}},{q="Por que Trovejius quer destruir essas relíquias?",a="A sociedade dos elfos noturnos rejeita a magia arcana por causa da devastadora Grande Cisão, provocada pela feitiçaria irresponsável dos Altaneiros. Trovejius teme que o poder arcano remanescente nesses objetos desperte antigos males se não for contido.",al={"por que destruir as relíquias","objetivo de ferramentas dos altaneiros"}},{q="Que espíritos assombram Ameth'Aran?",a="São os restos espectrais da elite dos Altaneiros que pereceu durante a Guerra dos Antigos. Mesmo após a morte, esses espíritos se agarram ao antigo orgulho, poder e artefatos mágicos, repetindo suas vidas passadas entre as pedras em ruínas.",al={"fantasmas de ameth'aran","que espíritos são esses"}},{q="Por que os Altaneiros ainda estão presos às ruínas?",a="Trovejius não explica. Ele sabe apenas o que as Sentinelas lhe contaram: os espíritos dos Altaneiros continuam nas ruínas de Ameth'Aran e ainda empunham seus antigos instrumentos mágicos.",al={"por que são fantasmas","maldição dos altaneiros"}},{q="O que acontece com as relíquias depois da entrega?",a="Trovejius Tecevento recolhe as relíquias com o propósito declarado de desmontá-las e destruí-las definitivamente, para que sua magia arcana corrompida nunca mais seja utilizada ou libertada.",al={"o que trovejius faz com as relíquias","destino das relíquias"}}},fx={df86da6d={q="O que são as Relíquias dos Altaneiros?",a="Estas relíquias são antigos instrumentos mágicos preservados de antes da Grande Cisão, outrora usados pelos feiticeiros da elite da corte da Rainha Azshara. Mesmo após dez mil anos, eles retêm a mancha persistente da imprudente manipulação arcana que despedaçou a antiga Kalimdor. Deixados nas mãos de fantasmas persistentes, eles permanecem condutores de poder adormecido e perigoso.",al={"o que são relíquias dos altaneiros","o que é relíquia dos altaneiros","lore de relíquia dos altaneiros"}}},fp="22,167,19.507.0,23.350.0,37.149.0,27.204.0,46.169.0,38.187.0,47.192.0,50.176.0"}
P.entries["quest:96800"] = {n="Past Due",s="Um estudioso pede que você recupere um tomo desaparecido do Monastério Escarlate. O livro é necessário para pesquisar os antigos mestres de runas Martelo Feroz de Grim Batol.",h="Um estudioso pede que você recupere um tomo desaparecido do Monastério Escarlate.",kw={"arcanista doan","biblioteca de dalaran","grim batol","past due","monastério escarlate","a magia perdida dos mestres de runas","mestres de runas martelo feroz"},sec={{t="Um livro atrasado",b="O estudioso está escrevendo uma tese sobre os antigos mestres de runas Martelo Feroz de Grim Batol. Os registros da antiga biblioteca de Dalaran dizem que Doan pegou o tomo emprestado antes da Terceira Guerra e nunca o devolveu. Ele está agora no Monastério Escarlate, nas Clareiras de Tirisfal, e o livro pode ser recuperado lá."}},faq={{q="Quem precisa do livro?",a="Um estudioso que escreve uma tese sobre os antigos mestres de runas Martelo Feroz de Grim Batol precisa dele para concluir a pesquisa.",al={"quem quer o tomo","pesquisa do estudioso"}},{q="Que livro foi emprestado?",a="O livro se chama A Magia Perdida dos Mestres de Runas.",al={"qual tomo","livro perdido dos mestres de runas"}},{q="Quem pegou o livro emprestado?",a="Os registros da antiga biblioteca de Dalaran dizem que um mago chamado Doan pegou o livro emprestado antes da Terceira Guerra.",al={"quem pegou emprestado","livro de doan"}},{q="Onde está o livro?",a="O livro está no Monastério Escarlate, nas Clareiras de Tirisfal, onde Arcanista Doan está agora.",al={"onde está o tomo","localização do livro"}},{q="Sobre o que é a pesquisa?",a="O estudioso está pesquisando os antigos mestres de runas Martelo Feroz de Grim Batol.",al={"mestres de runas martelo feroz","tese sobre grim batol"}}},fp="8,113,15.121.0,19.112.0,23.62.0,22.97.0,18.84.0,27.76.0"}
P.entries["quest:96821"] = {n="Legging It",s="Legging It é uma missão focada em desobstruir um perigoso caminho ao sul para proteger peões trabalhadores. Ameaças ao longo da estrada assustaram a força de trabalho a ponto de interromper suas viagens, paralisando tarefas essenciais. Ao repelir os perigos, os aventureiros restauram a passagem segura e permitem que os trabalhadores retornem às suas atribuições.",h="Legging It é uma missão focada em desobstruir um perigoso caminho ao sul para proteger peões trabalhadores.",kw={"desobstruiu o caminho","trabalho da horda","legging it","feitor","trabalho dos peões","peões","caminho do sul"},ang={["faction:Horde"]="O trabalho e as linhas de suprimento órcicas dependem fortemente dos peões, tornando a segurança das rotas vital para a construção e a coleta de recursos da Horda.",["race:Orc"]="Os peões formam a espinha dorsal dos assentamentos órcicos, e os feitores confiam em guerreiros para manter os caminhos livres de ameaças para que o trabalho possa continuar."},sec={{t="Garantindo a Linha",b="Legging It aborda uma interrupção nas operações locais de trabalho, onde peões ficaram assustados demais para viajar rumo ao sul. Em vez de realizarem suas tarefas designadas, os trabalhadores se recusaram a arriscar a viagem pela estrada devido a perigos iminentes. Ao intervir para repelir ameaças ao longo do caminho, os viajantes restauram a segurança suficiente para que os feitores enviem suas equipes de volta ao trabalho."},{t="Trabalho e Segurança de Rota",b="Os peões representam a espinha dorsal da infraestrutura da Horda, responsáveis pela extração de madeira, trabalho em pedreiras e construção de postos avançados. Como os peões possuem pouca aptidão marcial, até mesmo pequenos predadores de beira de estrada ou batedores hostis podem paralisar as cadeias de suprimentos. Garantir que os corredores de trânsito permaneçam desobstruídos é essencial para manter os assentamentos abastecidos e produtivos."}},faq={{q="O que é Legging It?",a="Legging It é uma tarefa realizada para proteger uma rota de trânsito ao sul para equipes de trabalhadores. Ameaças ao longo da estrada intimidaram os peões locais, interrompendo suas tarefas diárias até que um aventureiro interveio para desobstruir o caminho.",al={"o que é legging it","informações da missão legging it","missão legging it"}},{q="Por que os peões estavam com medo de viajar para o sul?",a="Os peões temiam se aventurar rumo ao sul devido a perigos ativos ao longo da estrada. Sem proteção ou um caminho desobstruído, os trabalhadores se recusavam a arriscar viajar para suas atribuições, levando as operações locais a uma paralisação total.",al={"por que os peões estavam com medo","medo dos peões","por que os peões pararam de trabalhar"}},{q="O que é alcançado ao completar a tarefa?",a="Com a rota do sul desobstruída e os perigos imediatos contidos, os feitores conseguem enviar a força de trabalho dos peões com segurança de volta a campo para retomar o trabalho e a coleta de recursos.",al={"o que acontece após legging it","desfecho de legging it","resultado de desobstruir o caminho"}},{q="Quem são os peões mencionados na tarefa?",a="Os peões são a força de trabalho básica da Horda, responsáveis pelo trabalho pesado, extração de madeira, mineração e construção de fortificações. Embora essenciais para as operações dos assentamentos, eles não são adequados para o combate e recuam facilmente diante do perigo.",al={"quem são os peões","papel dos peões","o que os peões fazem"}},{q="Para onde os peões estavam viajando?",a="O caminho leva para o sul em direção a áreas de trabalho periféricas e jazidas de recursos que exigem manutenção regular dos peões, embora a jornada tenha se tornado perigosa o suficiente para interromper todo o tráfego antes que a rota fosse desobstruída.",al={"para onde o caminho leva","caminho do sul","indo para o sul"}},{q="Por que os peões precisam que aventureiros desobstruam suas rotas?",a="Os peões não possuem treinamento militar formal nem equipamento de combate, o que os torna vulneráveis a predadores selvagens e forças hostis. Os feitores precisam confiar em aventureiros experientes para eliminar ameaças perimetrais e manter corredores de trabalho seguros.",al={"por que os peões precisam de proteção","segurança dos peões","protegendo peões"}}},fp="10,121,17.210.0,24.276.0,19.112.0,42.162.0,44.139.0,40.185.0,31.177.0,55.199.0"}
P.entries["quest:96822"] = {n="For Honor",s="For Honor é uma missão dedicada a homenagear guerreiros caídos para que seus feitos não sejam esquecidos. Ao completar a tarefa, um aventureiro garante que os sacrifícios desses combatentes permaneçam na memória.",h="For Honor é uma missão dedicada a homenagear guerreiros caídos para que seus feitos não sejam esquecidos.",kw={"guerreiros caídos","for honor","honra","memorial","missão","lembrança","guerreiro"},ang={["class:Warrior"]="Esta tarefa concentra-se diretamente em honrar combatentes caídos, ressoando fortemente com guerreiros que valorizam o sacrifício no campo de batalha e a memória duradoura."},sec={{t="Um Dever de Memória",b="A missão For Honor é uma missão solene focada em homenagear combatentes caídos. Em um mundo continuamente testado por conflitos, garantir que os soldados que deram tudo de si não sejam esquecidos permanece como um dever vital para aqueles que sobrevivem a eles."},{t="Preservando o Legado",b="Ao cumprir a tarefa, o concedente da missão confirma que os combatentes caídos permanecerão na memória graças aos seus esforços. O feito completado garante que seus sacrifícios continuem reconhecidos e respeitados, em vez de caírem no esquecimento."}},faq={{q="Sobre o que é a missão For Honor?",a="For Honor é uma missão focada em homenagear combatentes caídos. Ao aceitar e concluir a tarefa, você ajuda a garantir que os sacrifícios desses guerreiros sejam reconhecidos e não se percam na história.",al={"o que é for honor","visão geral da missão for honor"}},{q="Quem são os guerreiros mencionados após a conclusão?",a="O texto da missão homenageia especificamente guerreiros caídos cujos feitos e memória são preservados através de suas ações. Seu serviço e sacrifício são mantidos vivos por aqueles que levam a tarefa até o fim.",al={"quem são os guerreiros","quem é lembrado"}},{q="Por que é importante honrar esses guerreiros?",a="O propósito da tarefa é a memória. Em um mundo assolado por guerras e conflitos constantes, honrar a memória daqueles que tombaram em batalha confere dignidade e garante que sua coragem seja reconhecida.",al={"por que fazer esta missão","significado de for honor"}},{q="Quem pede para que esta tarefa seja realizada?",a="A tarefa é solicitada por alguém que busca homenagear camaradas caídos. Ao retornar, a pessoa verifica se o feito foi realizado e reconhece que os guerreiros serão lembrados para sempre.",al={"quem dá for honor"}},{q="Esta missão leva a outras tarefas?",a="Nada na missão indica uma tarefa posterior. Ela é independente como um ato de homenagem aos combatentes caídos, consolidando seu legado para que seus sacrifícios nunca sejam esquecidos.",al={"for honor faz parte de uma série","o que vem depois de for honor"}},{q="O que significa o título For Honor?",a="O nome reflete o tema central de honrar soldados caídos. Ele ressalta que reconhecer o sacrifício e manter viva a memória do campo de batalha está entre os deveres mais solenes que um combatente pode cumprir.",al={"o que a torna honrosa","significado de for honor"}}},fp="9,117,21.110.0,21.114.0,34.95.0,47.119.0,41.95.0,34.140.0,36.86.0,38.143.0"}
P.entries["quest:96825"] = {n="This Fruit Could Bite Back",s="This Fruit Could Bite Back é uma missão de coleta focada em colher figos-da-índia selvagens nas terras áridas próximas a Orgrimmar. Os frutos são preparados para consumo enquanto suas sementes são guardadas para plantio futuro, com o objetivo de cultivar uma plantação resiliente no deserto para alimentar a capital da Horda.",h="This Fruit Could Bite Back é uma missão de coleta focada em colher figos-da-índia selvagens nas terras áridas...",kw={"fruto de cacto","durotar","fruto","orgrimmar","figo-da-índia","figos-da-índia","sementes","this fruit could bite back"},ang={["faction:Horde"]="Garantir fontes sustentáveis de alimento como frutas resistentes do deserto é vital para sustentar a capital órquica e alimentar a crescente população da Horda.",["profession:Cooking"]="Os figos-da-índia oferecem potencial culinário no clima árido de Durotar, servindo como ingredientes para pratos saborosos e provisões para os moradores da cidade.",["profession:Herbalism"]="Colhedores e botânicos entendem a rusticidade da flora do deserto e o esforço necessário para coletar frutos silvestres espinhosos para o cultivo."},sec={{t="Colhendo nos Ermos Áridos",b="Durotar é uma paisagem acidentada e castigada pelo sol onde a agricultura tradicional é quase impossível. Para sustentar a crescente capital de Orgrimmar, habitantes engenhosos recorrem à flora nativa do deserto. O figo-da-índia, um fruto resistente de cacto munido de espinhos protetores, prospera no solo árido e fornece um sustento muito necessário quando colhido com cuidado."},{t="Cultivo e Sustento",b="Coletar figos-da-índia não se resume apenas a fornecer uma refeição imediata. Enquanto a polpa do fruto é preparada em pratos saborosos, as sementes colhidas são cuidadosamente preservadas para cultivo. A ambição é plantar essas colheitas resilientes ao redor de Orgrimmar, estabelecendo uma fonte de alimento acessível e duradoura logo do lado de fora das muralhas da fortaleza."}},faq={{q="O que é This Fruit Could Bite Back?",a="This Fruit Could Bite Back é uma tarefa focada na colheita de figos-da-índia selvagens em Durotar. O fruto coletado destina-se tanto à culinária imediata quanto à preservação de sementes para propagação pelo terreno seco que cerca Orgrimmar.",al={"o que é this fruit could bite back","missão this fruit could bite back","missão fruta que morde de volta"}},{q="Por que os figos-da-índia estão sendo coletados?",a="Os figos-da-índia coletados servem a um duplo propósito: preparar refeições deliciosas para consumo local e colher sementes viáveis. O objetivo de longo prazo é cultivar amplamente figos-da-índia por toda a terra árida ao redor de Orgrimmar.",al={"por que colher figos-da-índia","propósito do figo-da-índia","para que servem figos-da-índia"}},{q="Onde as sementes serão plantadas?",a="As sementes salvas da colheita reunida estão destinadas ao plantio por todos os arredores e terras que cercam Orgrimmar, ajudando a estabelecer um suprimento alimentar resiliente e autossustentável no solo rigoroso do deserto.",al={"onde crescem figos-da-índia","plantio de figos-da-índia em orgrimmar"}},{q="Quem deseja que esses frutos sejam coletados?",a="Um residente local que busca melhorar os estoques locais de alimento e cultivar plantações no clima árido do deserto de Durotar solicita a colheita para alimentar viajantes e desenvolver futuras colheitas.",al={"quem quer os figos-da-índia","concedente da missão bite back"}},{q="Por que o fruto 'morde de volta'?",a="Os figos-da-índia são cobertos por espinhos pontiagudos e agulhas típicos de cactos resistentes do deserto, tornando sua colheita perigosa sem os devidos cuidados.",al={"por que morde de volta","por que o fruto morde de volta"}},{q="Por que plantar frutos ao redor de Orgrimmar é importante?",a="Durotar é predominantemente árida e rochosa, tornando a agricultura convencional difícil. Estabelecer plantações tolerantes à seca como figos-da-índia ajuda a fornecer sustento sustentável para a capital.",al={"orgrimmar tem falta de comida","agricultura de orgrimmar","agricultura em durotar"}}},fp="26,174,26.262.0,26.288.0,35.120.0,37.146.0,32.166.0,32.137.0,31.103.0,49.159.0"}
P.entries["quest:96873"] = {n="A Pain in the Neck",s="Pa'zula pede que você remova a magia de vínculo dos pingentes usados por Zalazane para controlar trolls nas Ilhas do Eco. O resíduo pode libertar seus espíritos do domínio do médico-bruxo.",h="Pa'zula pede que você remova a magia de vínculo dos pingentes usados por Zalazane para controlar trolls nas...",kw={"uma dor de cabeça","feitiços de vínculo","ilhas do eco","hexed pendants","resíduo luminoso","pa'zula","aldeia sen'jin","zalazane"},ang={["profession:Tailoring"]="Como encantador, você pratica seu ofício removendo a magia de vínculo dos Hexed Pendants para Pa'zula."},sec={{t="Pedido de Pa'zula",b="Pa'zula, na Aldeia Sen'jin, precisa do resíduo dos Hexed Pendants. Zalazane usa feitiços de vínculo nos pingentes para manter seus prisioneiros sob controle. Você deve remover essa magia e levar o que restar a Pa'zula. A liberdade dos trolls está em jogo."},{t="Os pingentes",b="Pa'zula diz que os feitiços de vínculo prendem a mente dos trolls e alerta você para não usar um pingente. Quando você volta com o resíduo, Pa'zula diz que os feitiços foram removidos e que os espíritos dos trolls mortos podem descansar."}},faq={{q="Quem está pedindo o resíduo?",a="Pa'zula, na Aldeia Sen'jin, pede que você traga o resíduo dos Hexed Pendants.",al={"quem quer o resíduo","pedido de pa'zula"}},{q="O que Zalazane faz com os pingentes?",a="Zalazane usa feitiços de vínculo nos pingentes para manter a mente de seus prisioneiros sob controle.",al={"pingentes de zalazane","hexed pendants"}},{q="Onde encontrar os Hexed Pendants?",a="Trolls nas Ilhas do Eco carregam os Hexed Pendants.",al={"local dos pingentes","onde encontrar pingentes"}},{q="O que é Resíduo Luminoso?",a="O Resíduo Luminoso é obtido ao remover a magia dos Hexed Pendants.",al={"resíduo dos pingentes","coisa luminosa"}},{q="Por que Pa'zula quer que a magia dos pingentes seja removida?",a="Pa'zula diz que remover os feitiços de vínculo permite que os espíritos dos trolls mortos descansem.",al={"por que desencantar pingentes","libertar espíritos trolls"}}},fp="18,175,17.241.0,12.215.1,30.77.0,40.88.0,35.59.0,25.72.0,48.77.0"}
P.entries["quest:96874"] = {n="This Is Spinal Axe",s="Ug’thok, em Orgrimmar, pede que você reúna espinhas das enormes feras do Desfiladeiro do Trovão. Ele espera usá-las na cabeça de um machado, como parte das suas lições de ferraria.",h="Ug’thok, em Orgrimmar, pede que você reúna espinhas das enormes feras do Desfiladeiro do Trovão.",kw={"cabeça de machado","orgrimmar","pedras ásperas de amolar","saru","ferraria","desfiladeiro do trovão","ug’thok","weathered spines"},ang={["profession:Blacksmithing"]="Como aprendiz de ferraria, você ajuda Ug’thok a reunir materiais para uma cabeça de machado que ele espera fabricar."},sec={{t="Uma ideia de ferreiro",b="Ug’thok quer cinco Weathered Spines e cinco Rough Grinding Stones. Ele acha que as espinhas podem formar uma ótima cabeça de machado, embora Saru tenha rido da ideia."},{t="Material resistente",b="As espinhas se mostram mais resistentes do que Ug’thok esperava, e talvez seja difícil trabalhar com elas. Ele planeja continuar trabalhando no projeto."}},faq={{q="Quem está pedindo as espinhas?",a="Ug’thok, em Orgrimmar, pede que você reúna Weathered Spines e Rough Grinding Stones.",al={"quem quer espinhas","machado de ugthok","lição de ferraria"}},{q="O que Ug’thok quer fazer?",a="Ug’thok espera fabricar a cabeça de um machado com as espinhas das feras.",al={"machado de espinhas","o que ele está fabricando","ideia para cabeça de machado"}},{q="De onde vêm as espinhas?",a="As Weathered Spines vêm das enormes feras do Desfiladeiro do Trovão.",al={"onde ficam as espinhas","feras do desfiladeiro do trovão","local das espinhas"}},{q="Do que mais Ug’thok precisa?",a="Além das espinhas, ele pede Rough Grinding Stones.",al={"pedras de amolar necessárias","quais materiais","pedras ásperas"}},{q="Por que Ug’thok quer os materiais?",a="Ele quer tentar fazer uma cabeça de machado com as espinhas, como parte das suas lições de ferraria.",al={"por que as espinhas","para que servem","materiais de ugthok"}}},fp="18,154,16.165.0,14.123.1,29.85.0,33.62.0,30.64.0,30.63.0,38.91.0"}
P.entries["quest:96875"] = {n="Beasts of Thunder Ridge",s="Beasts of Thunder Ridge é uma missão em Orgrimmar concedida pelo correeiro Kamari, que apoia a expansão contínua da capital da Horda. Aventureiros são enviados aos penhascos do Desfiladeiro do Trovão para obter couros duráveis de lagarto e fornecer peles tratadas para reforçar as estruturas recém-erguidas da cidade.",h="Beasts of Thunder Ridge é uma missão em Orgrimmar concedida pelo correeiro Kamari, que apoia a expansão...",kw={"beasts of thunder ridge","pele leve tratada","durotar","kamari","couraria","orgrimmar","peões","couro áspero de lagarto","desfiladeiro do trovão"},ang={["faction:Horde"]="À medida que a Horda estabelece sua presença em Durotar, os suprimentos recolhidos na natureza ao redor alimentam diretamente a fortificação e o crescimento de Orgrimmar.",["race:Orc"]="A construção orca depende de materiais rústicos e duráveis coletados por caçadores e trabalhadores para resistir aos elementos de Durotar."},sec={{t="Uma Capital em Crescimento",b="À medida que a Horda constrói seu lar nas terras áridas de Durotar, a capital de Orgrimmar permanece em constante expansão. Novas habitações, oficinas e fortificações defensivas exigem um fluxo contínuo de madeira, pedra e peles de animais. Embora a madeira precise ser transportada de locais mais distantes, a fauna local de Durotar fornece um suprimento resistente de couros duráveis para os peões e construtores da cidade."},{t="Feras do Cânion",b="Nas profundezas do Desfiladeiro do Trovão, os lagartos nativos desenvolvem couros resistentes e desgastados pelo tempo. Embora essas peles sejam geralmente grossas e rígidas demais para serem transformadas em armaduras de couro utilizáveis, sua resistência as torna um material de construção excepcional. Quando obtidas adequadamente, servem para forrar os tetos e paredes das estruturas de madeira e pedra de Orgrimmar, protegendo os interiores do sol causticante e dos ventos repentinos do cânion."}},faq={{q="Por que Orgrimmar precisa de couros de lagarto do Desfiladeiro do Trovão?",a="Os couros ásperos de lagarto obtidos no Desfiladeiro do Trovão são grossos e rígidos demais para a confecção de armaduras utilizáveis, mas sua resistência os torna ideais para fins estruturais. Os peões em Orgrimmar os utilizam para forrar as paredes e telhados de edifícios recém-construídos, protegendo-os contra as intempéries rigorosas.",al={"para que servem os couros","por que couro áspero de lagarto","para que servem os couros do desfiladeiro do trovão"}},{q="Quem é Kamari?",a="Kamari é um correeiro na capital da Horda, Orgrimmar, que fornece aos construtores e peões da cidade as peles e couros resistentes necessários para os projetos de construção em andamento.",al={"quem é kamari","kamari orgrimmar","quem dá beasts of thunder ridge"}},{q="Onde fica o Desfiladeiro do Trovão?",a="O Desfiladeiro do Trovão é um desfiladeiro acidentado localizado no território árido de Durotar, conhecido pelos lagartos cujos couros grossos Kamari deseja para as novas construções da cidade.",al={"onde fica o desfiladeiro do trovão","localização do desfiladeiro do trovão","desfiladeiro do trovão durotar"}},{q="Por que peles leves tratadas são solicitadas junto com os couros de lagarto?",a="Juntamente com os pesados couros de lagarto, Kamari exige peles leves tratadas para complementar os materiais mais densos, testando a familiaridade mais ampla e a habilidade do aventureiro com o processamento de couro.",al={"por que peles leves tratadas","para que servem as peles tratadas"}},{q="Por que Orgrimmar está se expandindo tão rapidamente?",a="Como a recém-estabelecida capital da Horda, Orgrimmar está em contínua construção e expansão para abrigar um número crescente de orcs e seus aliados, gerando uma demanda constante por matérias-primas.",al={"por que orgrimmar está em obras","expansão de orgrimmar"}},{q="Os couros de lagarto do Desfiladeiro do Trovão podem ser transformados em armadura?",a="Os couros ásperos de lagarto do Desfiladeiro do Trovão geralmente são grossos e rígidos demais para serem moldados em armaduras flexíveis, fazendo com que seu principal valor prático seja estrutural em vez de vestível.",al={"é possível vestir couros de lagarto","couro áspero de lagarto é armadura"}}},fp="23,157,17.236.0,20.266.0,56.205.0,14.155.0,31.119.0,60.180.0,38.186.0,59.126.0"}
P.entries["quest:96876"] = {n="Ukor's Lost Pack",s="Ukor's Lost Pack é um item dropado encontrado nas terras selvagens do sul de Durotar, ostentando o nome de seu dono costurado de forma rústica. Ele foi descartado às pressas quando Ukor fugiu de um encontro aterrorizante com uma aranha enorme nativa da região.",h="Ukor's Lost Pack é um item dropado encontrado nas terras selvagens do sul de Durotar, ostentando o nome de...",kw={"durotar","horda","mochila perdida","sul de durotar","aranha","ukor","ukor's lost pack"},ang={["faction:Horde"]="Jovens aventureiros da Horda que se aventuram pelo sul de Durotar frequentemente ajudam habitantes locais como Ukor, provando seu valor e confiabilidade ao recuperar pertences pessoais perdidos da fauna perigosa."},sec={{t="Um Pertence Perdido",b="Ao atravessar a vastidão árida do sul de Durotar, um aventureiro se depara com uma bolsa de viagem abandonada com o nome \\\"Ukor\\\" costurado de forma rústica em sua aba. Sobreviver nas terras inóspitas de Durotar deixa pouco espaço para descuidos, e encontrar equipamentos descartados geralmente indica um encontro infeliz por perto."},{t="Fugindo das Terras Selvagens",b="Ao devolver a mochila para Ukor no sul de Durotar, a história por trás de seu abandono vem à tona. Ukor largou a bolsa em pânico quando foi emboscado por uma aranha gigantesca nativa da região, convencido de que nunca mais veria seus mantimentos. Encontrar sua bolsa intacta rende ao viajante sincera gratidão e elogios."}},faq={{q="Quem é Ukor?",a="Ukor é um habitante que reside no sul de Durotar. Ao ser confrontado por uma aranha enorme nas terras áridas, ele foi forçado a abandonar seus pertences em uma tentativa desesperada de escapar em segurança.",al={"quem é ukor","ukor durotar"}},{q="Por que Ukor perdeu sua mochila?",a="Ukor largou sua mochila enquanto fugia para salvar a vida de uma aranha enorme à espreita em Durotar. Ele presumiu que seus pertences estavam perdidos para sempre até que um aventureiro localizou a bolsa.",al={"por que a mochila foi perdida","onde ukor perdeu a mochila"}},{q="Para onde a mochila precisa ser levada?",a="A mochila recuperada pertence a Ukor, que pode ser encontrado esperando no sul de Durotar, pronto para saudar os viajantes que retornam.",al={"onde devolver a mochila","entregar para ukor"}},{q="Como a mochila é identificada?",a="A mochila é facilmente identificada pelo nome de Ukor, que está costurado de forma rústica na aba da bolsa.",al={"como a mochila é identificada","costura da mochila"}},{q="Que tipo de criatura perseguiu Ukor?",a="Ukor foi emboscado por uma aranha enorme vagando pelo terreno do sul de Durotar, o que o aterrorizou a ponto de largar todos os seus bens e correr para um local seguro.",al={"aranha em durotar","qual aranha atacou ukor"}},{q="O que acontece quando você devolve a mochila a Ukor?",a="Ukor fica surpreso e profundamente grato ao ver seus pertences perdidos novamente, declarando que o aventureiro que resgatou sua bolsa é um verdadeiro herói.",al={"recompensa de ukor","como ukor reage"}}},fp="16,125,16.162.0,17.222.0,12.118.0,27.131.0,37.97.0,27.54.0,34.106.0,46.116.0"}
P.entries["quest:96877"] = {n="Halikor's Hoof",s="Halikor's Hoof é uma missão focada em reivindicar uma prova física após abater o poderoso lagarto Halikor. Levar o enorme casco decepado à capital da Horda, Orgrimmar, honra o triunfo do caçador sobre uma fera formidável da natureza selvagem.",h="Halikor's Hoof é uma missão focada em reivindicar uma prova física após abater o poderoso lagarto Halikor.",kw={"halikor","halikor's hoof","horda","caçada","lagarto","orgrimmar","troféu"},ang={["class:Hunter"]="Derrubar uma fera enorme e formidável como Halikor exemplifica a arte do rastreador e a emoção da caçada.",["faction:Horde"]="Trazer a prova da derrota de uma fera poderosa para Orgrimmar honra as tradições de força e proeza de caça da Horda."},sec={{t="Troféu de uma Fera Poderosa",b="Halikor's Hoof é um troféu tangível retirado dos restos mortais de Halikor, um lagarto extraordinariamente gigantesco. Entre caçadores e guerreiros que atravessam fronteiras selvagens, reivindicar um símbolo físico de uma criatura tão formidável é um costume antigo para comprovar o abate. O mero tamanho do casco não deixa dúvidas sobre a imensa escala e o poder da fera em vida."},{t="Prova para a Capital",b="Levar o pesado casco de volta aos portões fortificados de Orgrimmar serve para anunciar a derrota da fera à Horda. Em uma sociedade de guerreiros que valoriza a força bruta e a sobrevivência contra os predadores implacáveis da terra, apresentar tal troféu traz honra ao caçador e tranquiliza a capital de que uma criatura perigosa foi derrubada."}},faq={{q="O que é Halikor?",a="Halikor é uma criatura lagarto poderosa e formidável. Seu tamanho imenso é demonstrado pela pura escala de seu casco decepado, que os caçadores reivindicam como prova irrefutável de sua queda.",al={"o que é halikor","quem é halikor","lagarto halikor"}},{q="Por que o casco deve ser entregue em Orgrimmar?",a="O casco é levado à capital da Horda, Orgrimmar, para servir como prova física da derrota da fera, exibindo o triunfo do caçador para a cidade.",al={"por que levar casco para orgrimmar","entregar casco de halikor","para onde vai o casco"}},{q="Como Halikor's Hoof é obtido?",a="Halikor's Hoof é reivindicado diretamente do corpo de Halikor após rastrear e abater o gigantesco lagarto em combate.",al={"como conseguir halikor's hoof","saque de halikor"}},{q="Por que um lagarto tem um casco?",a="Halikor não é um lagarto comum, mas sim uma fera poderosa das selvas, e seu casco enorme é o troféu que prova que você a derrotou. Por que ela possui um casco, ninguém jamais explicou.",al={"halikor tem cascos","por que um lagarto tem cascos"}},{q="Quem em Orgrimmar quer Halikor's Hoof?",a="Você leva o casco de volta para Orgrimmar como prova de sua vitória; nenhum caçador ou oficial específico é designado para recebê-lo.",al={"quem aceita halikor's hoof em orgrimmar","entregar casco de halikor em orgrimmar"}},{q="Qual é a história por trás da missão Halikor's Hoof?",a="Halikor's Hoof é uma missão centrada na derrota do colossal lagarto Halikor. Levar seu enorme casco decepado a Orgrimmar demonstra a proeza marcial do caçador e leva à Horda a notícia do fim da fera.",al={"o que é a missão halikor's hoof","história de halikor's hoof"}}},fp="14,166,24.231.0,21.278.0,16.113.0,44.89.0,31.93.0,30.126.0,38.114.0,50.176.0"}
P.entries["quest:96895"] = {n="The Argent Emissary",s="The Argent Emissary marca a chegada de dois representantes Renegados da Aurora Argêntea rastreando membros da seita do Flagelo perto da Cidade Baixa. Sua presença ressalta tanto a luta conjunta contra o Flagelo quanto a tensão latente entre a ordem neutra e as autoridades dos Renegados.",h="The Argent Emissary marca a chegada de dois representantes Renegados da Aurora Argêntea rastreando membros da...",kw={"aurora argêntea","emissário argênteo","membros da seita","renegados","membros da seita do flagelo","clareiras de tirisfal","cidade baixa"},ang={["faction:Horde"]="Embora a Aurora Argêntea seja neutra, as autoridades da Horda mantêm um olhar atento sobre suas operações independentes perto da Cidade Baixa.",["race:Undead"]="Ver companheiros Renegados escolherem a Aurora Argêntea em vez da Cidade Baixa serve como um lembrete contundente das lealdades divididas entre os mortos-vivos livres."},sec={{t="Boas-vindas cautelosas",b="Dois emissários Renegados da Aurora Argêntea chegaram recentemente às Clareiras de Tirisfal, deixando as autoridades locais em alerta. Embora a Aurora Argêntea se oponha ao Flagelo, os Renegados locais continuam desconfiados de qualquer ordem armada e neutra operando sem monitoramento dentro de seu território soberano. Mesmo a herança compartilhada dos emissários faz pouco para abrandar sua vigilância."},{t="Membros da seita nos portões",b="Os emissários não vieram para admirar as Ruínas de Lordaeron; eles estão perseguindo um grupo de membros da seita do Flagelo descobertos à espreita a sudeste, nos arredores da Cidade Baixa. Determinados a erradicar os agentes do Lich Rei antes que estabeleçam uma base, um dos emissários assumiu posição perto dos portões da cidade para monitorar os movimentos do inimigo."}},faq={{q="Quem são os emissários argênteos?",a="Dois emissários representando a Aurora Argêntea viajaram recentemente para as Clareiras de Tirisfal. Notavelmente, ambos os emissários são Renegados que se alinharam com a ordem sagrada e neutra em vez de servir unicamente à Cidade Baixa.",al={"quem são os emissários","visitantes da aurora argêntea","quem veio a tirisfal"}},{q="Por que a Aurora Argêntea está operando perto da Cidade Baixa?",a="Eles estão rastreando membros da seita do Flagelo avistados rondando os arredores a sudeste da Cidade Baixa. A Aurora Argêntea está empenhada em caçar remanescentes do Flagelo onde quer que apareçam, mesmo perto de grandes assentamentos da Horda.",al={"por que eles estão perto da cidade baixa","missão da aurora argêntea em tirisfal","o que os emissários estão fazendo"}},{q="Por que os Renegados locais desconfiam dos emissários?",a="Ainda que a Aurora Argêntea lute contra o inimigo comum no Flagelo, os Renegados locais não gostam de organizações armadas neutras operando sem supervisão nas Clareiras de Tirisfal, independentemente de esses emissários compartilharem ou não de sua condição de morto-vivo.",al={"por que apreensão com a aurora argêntea","podemos confiar na aurora argêntea","visão dos renegados sobre a aurora argêntea"}},{q="Qual é a ameaça representada pelos membros da seita?",a="Uma célula de membros da seita do Flagelo foi avistada à espreita a sudeste, perto dos arredores da cidade. Por causa da ameaça persistente que o Lich Rei representa para os mortos-vivos livres, sua presença atraiu imediatamente a atenção tanto dos batedores locais quanto da Aurora Argêntea.",al={"seitas fora da cidade baixa","flagelo em tirisfal","quem são os membros da seita"}},{q="Para onde foi o emissário?",a="Um dos emissários seguiu para o sudeste em direção à entrada da Cidade Baixa, vigiando os passos dos membros da seita do Flagelo que operavam logo fora das muralhas da cidade.",al={"onde encontrar o emissário","localização do emissário","encontrar membro da aurora argêntea"}},{q="Os Renegados servem na Aurora Argêntea?",a="Sim. Diferente da Cruzada Escarlate, a Aurora Argêntea acolhe todos os dispostos a lutar contra o Flagelo, incluindo mortos-vivos de livre-arbítrio que se dedicam à causa.",al={"renegados são permitidos na aurora argêntea","mortos-vivos da aurora argêntea","mortos-vivos podem se juntar à aurora argêntea"}}},fp="19,181,12.319.0,21.231.0,30.157.0,52.185.0,46.173.0,41.187.0,26.111.0,41.161.0"}
P.entries["quest:96896"] = {n="A Righteous Cause",s="A Righteous Cause testemunha uma conversa entre Leonid Barthalomew the Revered e Danitha Morr enquanto refletem sobre a defesa da Cidade Baixa contra Naxxramas. A troca de palavras destaca a memória de Garek Bandarion, um herói morto-vivo que redescobriu como canalizar a Luz Sagrada como um paladino. A missão lança luz sobre os raros Renegados que se esforçam para manter sua conexão com a Luz, apesar do ceticismo de seus semelhantes.",h="A Righteous Cause testemunha uma conversa entre Leonid Barthalomew the Revered e Danitha Morr enquanto...",kw={"danitha morr","renegados","garek bandarion","leonid barthalomew","capela esperança da luz","naxxramas","paladino","a righteous cause","flagelo","cidade baixa"},ang={["class:Paladin"]="Garek Bandarion e a comitiva de Danitha representam um desenvolvimento extraordinário: Renegados redescobrindo como canalizar a Luz Sagrada como paladinos, apesar de seu estado de mortos-vivos.",["faction:Horde"]="A presença de Leonid Barthalomew destaca os laços entre os defensores da Cidade Baixa e a Aurora Argêntea sediada na Capela Esperança da Luz, nas Terras Pestilentas.",["race:Undead"]="Enquanto Leonid e Danitha se esforçam para se reconectar com a Luz, a maioria dos Renegados permanece distante ou hostil ao caminho sagrado em sua não-vida."},sec={{t="Reunião de Veteranos",b="A Righteous Cause centra-se em uma comovente reunião entre dois veteranos defensores de Lordaeron: Leonid Barthalomew the Revered e Danitha Morr. Tendo sobrevivido ao terrível ataque quando Naxxramas lançou o Flagelo sobre a Cidade Baixa, os dois refletem sobre seus camaradas caídos e o árduo caminho percorrido pelos Renegados que ainda veneram a Luz Sagrada."},{t="O Legado de Garek Bandarion",b="O ponto central de sua memória compartilhada é Garek Bandarion, o herói caído que deu nome à fortaleza. De acordo com Leonid, Garek pode ter sido o primeiríssimo dentre os Renegados a redescobrir como canalizar a Luz Sagrada como um verdadeiro paladino. Enquanto a maioria dos Renegados se afastou completamente da Luz, Danitha e sua comitiva dedicam-se a preservar o legado de Garek e a explorar o potencial da não-vida sagrada."},{t="Retorno às Terras Pestilentas",b="Após sua conversa com Danitha, Leonid se prepara para deixar a fortaleza. Sua lealdade pertence à luta contínua contra o Flagelo no leste devastado, onde ele se estabelece na Capela Esperança da Luz, nas Terras Pestilentas Orientais, acolhendo quaisquer aventureiros aptos dispostos a pegar em armas pela causa."}},faq={{q="Quem é Leonid Barthalomew the Revered?",a="Leonid Barthalomew the Revered é um proeminente membro morto-vivo da Aurora Argêntea. Embora atue a partir da Capela Esperança da Luz, nas Terras Pestilentas Orientais, ele mantém laços com antigos camaradas de Lordaeron que lutaram ao seu lado contra o Flagelo.",al={"quem é leonid barthalomew","leonid the revered","história de leonid barthalomew"}},{q="Quem é Danitha Morr?",a="Danitha Morr é uma líder dos Renegados que lutou ao lado de Leonid Barthalomew durante o ataque do Flagelo à Cidade Baixa. Hoje, ela lidera uma comitiva dedicada a levar adiante os ensinamentos e o sagrado legado de Garek Bandarion.",al={"quem é danitha morr","danitha","história de danitha morr"}},{q="Quem foi Garek Bandarion?",a="Garek Bandarion foi um heroico guerreiro Renegado que caiu durante a defesa da Cidade Baixa quando Naxxramas atacou. Leonid observa que ele pode ter sido o primeiríssimo Renegado a redescobrir como canalizar a Luz Sagrada como um paladino.",al={"quem é garek bandarion","história de garek bandarion","fortaleza batizada em homenagem a"}},{q="O que aconteceu durante o ataque à Cidade Baixa?",a="Quando a necrópole Naxxramas lançou um ataque contra a Cidade Baixa, campeões Renegados, incluindo Danitha Morr, Leonid Barthalomew e Garek Bandarion, uniram-se para defender a cidade contra a investida do Flagelo, sofrendo pesadas baixas no combate.",al={"ataque de naxxramas à cidade baixa","defesa da cidade baixa","ataque do flagelo à cidade baixa"}},{q="Os Renegados podem canalizar a Luz como paladinos?",a="Embora canalizar a Luz cause uma dor excruciante à carne morta-viva e seja rejeitado pela maioria dos Renegados, Garek Bandarion demonstrou que é possível para um guerreiro morto-vivo canalizar a Luz Sagrada como um paladino, uma prática que Danitha e sua comitiva continuam a estudar.",al={"renegados podem ser paladinos","história do paladino morto-vivo","renegados canalizadores da luz"}},{q="Para onde Leonid Barthalomew vai depois disso?",a="Após visitar seus amigos e conversar com Danitha Morr, Leonid planeja retornar à Capela Esperança da Luz, nas Terras Pestilentas Orientais, de onde a Aurora Argêntea coordena sua cruzada contra o Flagelo.",al={"para onde leonid vai","encontrar leonid mais tarde","capela esperança da luz leonid"}}},fp="17,257,19.268.0,29.329.0,25.260.0,38.223.0,20.194.0,24.192.0,49.211.0,45.214.0,44.197.0"}
P.entries["quest:96897"] = {n="The Cult of the Damned",s="A Seita dos Malditos é uma tarefa que confronta servos mortais do Flagelo ativos nas Clareiras de Tirisfal. Ao abater Dark Neophytes e Dark Enforcers, os defensores impedem que os insidiosos agentes vivos do Lich King repitam as traições que originalmente despedaçaram Lordaeron.",h="A Seita dos Malditos é uma tarefa que confronta servos mortais do Flagelo ativos nas Clareiras de Tirisfal.",kw={"seita dos malditos","dark enforcers","dark neophytes","servos vivos","lordaeron","necromancia","flagelo","clareiras de tirisfal"},ang={["class:Paladin"]="Paladinos fizeram juramentos para erradicar a sombra que destruiu Lordaeron, tornando cultistas vivos dedicados ao Flagelo inimigos jurados da Luz.",["class:Priest"]="Sacerdotes de todas as disciplinas reconhecem a perversão da fé representada pela Seita dos Malditos, que trocam a devoção sagrada por necromancia sombria.",["race:Undead"]="Os Renegados sabem muito bem como os cultistas vivos devastaram Lordaeron e causaram sua morte-viva. Deter novas células da Seita em Tirisfal é vital para assegurar o novo reino."},sec={{t="Agentes Mortais do Flagelo",b="A Seita dos Malditos representa a face mortal do Flagelo. Composta por homens e mulheres vivos que juraram lealdade ao Lich King, esses cultistas agem onde mortos irracionais não conseguem. Nas Clareiras de Tirisfal, onde os habitantes já enfrentam mortos-vivos errantes e fanáticos implacáveis da Cruzada Escarlate, células recém-descobertas de Dark Neophytes e Dark Enforcers sinalizam uma tentativa insidiosa do Flagelo de restabelecer uma base de apoio."},{t="Lições da Queda",b="Lordaeron foi levada à ruína não apenas pela marcha de legiões dos mortos, mas por vizinhos que traíram vizinhos. A Seita dos Malditos originalmente se infiltrou em aldeias, envenenou celeiros e orquestrou o colapso do reino a partir das sombras. Manter a vigilância contra novas atividades da Seita em Tirisfal é essencial para garantir que a história não se repita nas terras marcadas do norte."}},faq={{q="O que é a Seita dos Malditos?",a="A Seita dos Malditos é uma organização de mortais que servem de bom grado ao Lich King e ao Flagelo. Em vez de serem erguidos como mortos-vivos irracionais, esses acólitos vivos deliberadamente espalham a peste, sabotam defesas e praticam necromancia a serviço da morte.",al={"o que é a seita dos malditos","quem são os cultistas","quem são os dark neophytes"}},{q="Por que membros da Seita estão operando nas Clareiras de Tirisfal?",a="As Clareiras de Tirisfal continuam sendo uma região fronteiriça disputada, assombrada por mortos-vivos irracionais, fanáticos da Cruzada Escarlate e bolsões sobreviventes de influência do Flagelo. A Seita opera secretamente na região para minar a resistência local e avançar os planos sombrios do Flagelo.",al={"por que há cultistas em tirisfal","seita nas clareiras de tirisfal"}},{q="Quem são os Dark Neophytes e os Dark Enforcers?",a="Dark Neophytes são iniciados recentes aprendendo artes e rituais sombrios, enquanto Dark Enforcers atuam como a força física que protege as operações da seita e impõe disciplina entre suas fileiras. Juntos, eles formam células operacionais ativas em solo.",al={"quem são os dark enforcers","papel dos dark neophytes"}},{q="Por que servos vivos são considerados piores do que mortos-vivos irracionais?",a="Mortos-vivos irracionais agem puramente por instinto ou comando direto, mas cultistas vivos escolheram a traição com plena consciência. Sua capacidade de se misturar às sociedades mortais e se infiltrar em povoados os torna muito mais insidiosos do que carniçais ou esqueletos errantes.",al={"por que cultistas vivos são piores","servos vivos do flagelo"}},{q="O que a missão quer dizer com não deixar a história de Lordaeron se repetir?",a="Lordaeron não caiu apenas por uma invasão externa aberta, mas porque a Seita dos Malditos envenenou silenciosamente os suprimentos de grãos e traiu seus concidadãos a partir de dentro. Permitir que cultistas ganhem uma base de apoio atrai a mesma catástrofe.",al={"história de lordaeron se repetir","queda de lordaeron seita"}},{q="Como a Seita se relaciona com a Cruzada Escarlate em Tirisfal?",a="A Cruzada Escarlate caça fanaticamente qualquer coisa maculada pela morte-viva, tornando tanto o Flagelo quanto a Seita alvos primários. Esse conflito contínuo deixa os habitantes locais presos entre horrores irracionais, cruzados fanáticos e cultistas disfarçados.",al={"relação com a cruzada escarlate","seita vs cruzada escarlate"}}},fp="22,219,28.323.0,19.316.0,31.229.0,57.215.0,46.182.0,62.226.0,74.194.0,60.224.0"}
P.entries["quest:96898"] = {n="Remnants of War",s="Remnants of War incumbe aventureiros de recuperar estilhaços despedaçados do cristal de foco necrótico arrancado de Naxxramas durante seu ataque à Cidade Baixa. Tanto os Renegados quanto a Aurora Argêntea sofreram pesadas perdas ao repelir a cidadela, e recolher esses fragmentos perigosos impede que cultistas do Flagelo recuperem sua magia sombria.",h="Remnants of War incumbe aventureiros de recuperar estilhaços despedaçados do cristal de foco necrótico...",kw={"aurora argêntea","cultistas","renegados","naxxramas","fragmentos de cristal necrótico","remnants of war","flagelo","clareiras de tirisfal","cidade baixa"},ang={["class:Mage"]="Mesmo quebrados e amplamente esgotados, os cristais de foco necrótico de Naxxramas retêm uma energia mágica instável que exige extrema cautela.",["class:Priest"]="A corrupção profana residual presente nos estilhaços necróticos representa uma praga perigosa que precisa ser contida antes que profane ainda mais a terra.",["faction:Horde"]="Proteger as Clareiras de Tirisfal da magia residual do Flagelo ajuda a salvaguardar a Cidade Baixa e garante o ponto de apoio vital da Horda no norte de Lordaeron.",["race:Undead"]="O ataque de Naxxramas ameaçou a própria existência da Cidade Baixa. Recuperar esses fragmentos protege o seu povo de um ressurgimento do Flagelo à sua porta."},sec={{t="A Sombra Sobre a Cidade",b="Não muito tempo atrás, a temível cidadela Naxxramas pairava diretamente sobre as Clareiras de Tirisfal, buscando aniquilar a Cidade Baixa e erradicar os Renegados por completo. Em uma defesa desesperada, os Renegados e a Aurora Argêntea repeliram a fortaleza flutuante a um grande custo. Durante o confronto, o imenso cristal de foco necrótico montado no topo de Naxxramas foi destruído, espalhando fragmentos pelas clareiras abaixo."},{t="Necromancia Dispersa",b="Embora a cidadela tenha sido repelida, os resíduos permanecem incrustados no solo. Cultistas do Flagelo avançaram para recuperar os fragmentos de cristal necrótico, esperando controlar a magia sombria que ainda perdura dentro deles. Coletar esses estilhaços priva o Flagelo de poder profano bruto, embora retirar cada pedaço de Tirisfal vá levar anos."}},faq={{q="O que são os fragmentos de cristal necrótico?",a="Eles são pedaços despedaçados do enorme cristal de foco necrótico que outrora ficava no topo da temível cidadela flutuante Naxxramas. Quando o cristal foi destruído durante o ataque à Cidade Baixa, estilhaços choveram sobre as Clareiras de Tirisfal.",al={"o que são fragmentos de cristal necrótico","o que são os cristais","cristais necróticos"}},{q="Por que Naxxramas atacou a Cidade Baixa?",a="Naxxramas desceu sobre as Clareiras de Tirisfal com o objetivo direto de obliterar a Cidade Baixa e varrer os Renegados do mapa. Uma defesa combinada dos Renegados e da Aurora Argêntea repeliu a cidadela, embora ambas as facções tenham sofrido pesadas perdas.",al={"por que naxxramas atacou","ataque de naxxramas à cidade baixa","o que naxxramas fez aqui"}},{q="Por que os cultistas do Flagelo estão coletando os fragmentos de cristal?",a="Cultistas do Flagelo estão vasculhando as Clareiras de Tirisfal para recuperar os fragmentos despedaçados. Mesmo quebrados e esgotados, os cristais guardam resquícios de magia necrótica que o Flagelo poderia recuperar ou reaproveitar para seus rituais profanos.",al={"por que os cultistas querem os cristais","o que os cultistas querem com os estilhaços","cristais dos cultistas do flagelo"}},{q="Manipular os cristais necróticos é perigoso?",a="Sim. Apesar de estarem quebrados e amplamente drenados de sua carga primária, os fragmentos ainda abrigam uma energia necrótica potente e volátil, tornando o contato físico direto perigoso.",al={"os cristais são perigosos ao toque","contato físico com cristal","cristais necróticos podem ferir"}},{q="Quem ajudou os Renegados a repelir Naxxramas?",a="Na batalha para defender a Cidade Baixa, os Renegados lutaram lado a lado com a Aurora Argêntea contra as forças de Naxxramas, sofrendo pesadas baixas para garantir a sobrevivência dos Renegados.",al={"quem lutou em naxxramas","quem defendeu a cidade baixa","defesa da cidade baixa pela aurora argêntea"}},{q="Todos os cristais necróticos serão removidos de Tirisfal algum dia?",a="É improvável que a área seja limpa rapidamente. Como o enorme cristal se despedaçou bem acima das clareiras, os fragmentos se espalharam por toda parte, o que significa que os habitantes provavelmente estarão retirando estilhaços da terra pelos próximos anos.",al={"tirisfal ficará livre dos cristais","eles conseguem limpar todos os fragmentos","cristais restantes em tirisfal"}}},fp="15,287,24.346.0,20.278.0,40.203.0,39.168.0,58.160.0,44.144.0,44.124.0,61.182.0"}
P.entries["quest:96899"] = {n="Bastilha de Bandarion",s="Bastilha de Bandarion é uma missão nas Clareiras de Tirisfal que orienta os aventureiros a encontrar o Comandante da Aurora Argêntea Leonid Barthalomew em uma fortaleza isolada. Antes uma base de operações da Aurora Argêntea contra o Flagelo, a fortaleza agora é mantida por Danitha e sua ordem de paladinos.",h="Bastilha de Bandarion é uma missão nas Clareiras de Tirisfal que orienta os aventureiros a encontrar o...",kw={"aurora argêntea","bastilha de bandarion","seita dos malditos","danitha","leonid barthalomew","paladino","flagelo","clareiras de tirisfal"},ang={["class:Paladin"]="A Bastilha de Bandarion serve como fortaleza sob a administração de Danitha e seus companheiros paladinos, mantendo um bastião sagrado contra as forças das trevas nas Clareiras de Tirisfal."},sec={{t="Uma Convocação à Bastilha",b="Bastilha de Bandarion é uma missão da Aurora Argêntea que orienta os aventureiros a atravessar as Clareiras de Tirisfal para encontrar o Comandante Leonid Barthalomew. Depois de ajudar a Aurora contra as atividades da Seita dos Malditos, os viajantes são direcionados ao noroeste, rumo à fortaleza, para se encontrar com o comandante e saber mais sobre a cruzada contínua da ordem contra as trevas."},{t="História e Tutela",b="A fortaleza serviu outrora como um posto avançado vital para a Aurora Argêntea enquanto combatiam as incursões do Flagelo por todas as Clareiras de Tirisfal. Quando a Aurora mudou seu foco para as Terras Pestilentas Orientais e Ocidentais, o forte foi deixado para trás e ameaçou decair em ruínas, até que a paladina Danitha e seus companheiros assumiram a tutela de suas muralhas."},{t="Memórias de um Amigo Mútuo",b="Ao se reunir com Leonid Barthalomew na fortaleza, o comandante reflete sobre a memória das batalhas travadas a partir de suas muralhas. Embora aliviado por a fortaleza não ter caído no abandono, ele observa que Danitha atribuiu seu nome em homenagem a um amigo mútuo."}},faq={{q="Quem é Leonid Barthalomew?",a="Leonid Barthalomew é um comandante da Aurora Argêntea. Ele já usou a Bastilha de Bandarion como base durante incursões anteriores do Flagelo nas Clareiras de Tirisfal e retornou ao local para se encontrar com Danitha e seus paladinos.",al={"quem é leonid barthalomew","onde fica leonid barthalomew","leonid bastilha de bandarion"}},{q="O que é a Bastilha de Bandarion?",a="A Bastilha de Bandarion é uma fortaleza localizada no oeste das Clareiras de Tirisfal. Originalmente um posto avançado da Aurora Argêntea durante os ataques do Flagelo, ela se deteriorou quando a ordem recuou para as Terras Pestilentas, até ser restaurada e ocupada pelos paladinos de Danitha.",al={"o que é a bastilha de bandarion","história da bastilha de bandarion","quem ocupa a bastilha de bandarion"}},{q="Quem é Danitha?",a="Danitha é uma paladina que assumiu a administração da Bastilha de Bandarion junto com sua ordem depois que a Aurora Argêntea recuou para leste, rumo às Terras Pestilentas. Ela também deu esse nome à fortaleza em homenagem a um amigo em comum com Leonid Barthalomew.",al={"quem é danitha","danitha paladina","quem administra a bastilha de bandarion"}},{q="Por que ela se chama Bastilha de Bandarion?",a="A fortaleza foi batizada por Danitha em homenagem a um amigo mútuo conhecido tanto por ela quanto pelo Comandante Leonid Barthalomew.",al={"por que recebeu o nome bastilha de bandarion","quem é bandarion","significado do nome bandarion"}},{q="Por que a Aurora Argêntea está interessada na Bastilha de Bandarion?",a="Membros da Aurora Argêntea viajam até a Bastilha de Bandarion para coordenar ações com os paladinos de Danitha e manter a vigilância contra as forças do Flagelo e as atividades da Seita dos Malditos nas Clareiras de Tirisfal.",al={"por que ir à bastilha de bandarion","aurora argêntea clareiras de tirisfal","bastilha de bandarion aurora argêntea"}},{q="Por que a Aurora Argêntea abandonou anteriormente a bastilha?",a="A Aurora Argêntea retirou-se da fortaleza quando deslocou suas forças principais para o leste a fim de combater o Flagelo nas Terras Pestilentas, deixando a estrutura vazia até que Danitha e seus paladinos intervieram para mantê-la.",al={"o que aconteceu com a bastilha após a guerra","por que a aurora argêntea deixou a bastilha de bandarion"}}},fp="14,214,21.234.0,23.298.0,27.172.1,26.184.0,23.226.0,15.205.0,32.93.0,52.180.0,52.183.0"}
P.entries["quest:96984"] = {n="Heart of Disruption",s="Magus Ordínio Olharvazio permite que você atravesse suas barreiras e entre em Dalaran para buscar uma Partícula Arcana. Ele teme que a queda da cidade também traga uma catástrofe à Cidade Baixa.",h="Magus Ordínio Olharvazio permite que você atravesse suas barreiras e entre em Dalaran para buscar uma...",kw={"partícula arcana","dalaran","heart of disruption","magus ordínio olharvazio","serraria tarren","cidade baixa","violet citadel","barreiras"},sec={{t="Uma chave pelas barreiras",b="Magus Ordínio Olharvazio, na Serraria Tarren, envia você a Dalaran com uma chave que ele imbuiu de magia para atravessar suas barreiras. Ele teme que, se a cidade cair, a Cidade Baixa também fique ameaçada. Encontre a Partícula Arcana e reúna-se com ele em Violet Citadel, onde tudo começou; evitar uma catástrofe vem primeiro."}},faq={{q="Quem me envia a Dalaran?",a="Magus Ordínio Olharvazio, na Serraria Tarren, envia você a Dalaran para encontrar uma Partícula Arcana.",al={"quem me deu isto","ordínio olharvazio","quem é o mago"}},{q="Por que estou indo a Dalaran?",a="Você recebe a missão de encontrar uma Partícula Arcana. Ordínio teme que a queda de Dalaran leve a Cidade Baixa à ruína também.",al={"por que dalaran","o que estou procurando","tarefa em dalaran"}},{q="Como atravesso as barreiras de Ordínio?",a="Ordínio imbui sua chave de magia para que ela atravesse suas barreiras e permita que você entre na cidade.",al={"a chave","chave de dalaran","atravessar barreiras"}},{q="Onde devo encontrar Ordínio?",a="Ordínio pede que você se reúna com ele em Violet Citadel, em Dalaran, onde tudo começou.",al={"encontrar o mago","violet citadel","onde está ordínio"}},{q="Qual é a maior prioridade de Ordínio?",a="Ordínio diz que evitar uma catástrofe vem primeiro.",al={"evitar catástrofe","o que mais importa","maior prioridade"}}},fp="19,161,23.287.0,24.85.0,26.107.0,34.76.0,28.80.0,33.50.0"}
P.entries["quest:96986"] = {n="The Grave Knight",s="Melisara, na Serraria Tarren, pede que você enfrente Atrexis, um necromante que ergue os mortos sob Dalaran. Ela considera o trabalho dele uma afronta aos Renegados.",h="Melisara, na Serraria Tarren, pede que você enfrente Atrexis, um necromante que ergue os mortos sob Dalaran.",kw={"atrexis","dalaran","renegados","cavaleiro da sepultura","melissara","necromante","serraria tarren","exército de mortos-vivos"},ang={["faction:Alliance"]="Melisara diz que pouco se importa com o destino de Dalaran ao mandar você atrás de Atrexis.",["race:Undead"]="Melisara chama Atrexis de traidor dos Renegados e diz que o exército de mortos-vivos dele vai contra tudo o que eles defendem."},sec={{t="A ordem de Melisara",b="Melisara diz que Atrexis é um traidor dos Renegados e ergue um exército de mortos-vivos sob Dalaran. Ela pede que você derrote o Cavaleiro da Sepultura; pouco lhe importa o destino da cidade dos magos, mas, segundo ela, ninguém escapa ao alcance da Dama Sombria."}},faq={{q="Quem é o Cavaleiro da Sepultura?",a="Atrexis é um necromante em Dalaran a quem Melisara chama de Cavaleiro da Sepultura.",al={"atrexis","atrexis cavaleiro da sepultura","quem é o cavaleiro da sepultura"}},{q="Quem me mandou atrás de Atrexis?",a="Melisara, na Serraria Tarren, pede que você derrote Atrexis.",al={"quem deu a missão do cavaleiro da sepultura","melisara atrexis","quem quer atrexis morto"}},{q="Por que Melisara quer que Atrexis seja derrotado?",a="Melisara diz que Atrexis é um traidor dos Renegados que ergue um exército de mortos-vivos sob Dalaran.",al={"por que matar atrexis","por que cavaleiro da sepultura","motivo dos renegados contra atrexis"}},{q="Onde está Atrexis?",a="Atrexis está na cidade de Dalaran.",al={"localização de atrexis","localização do cavaleiro da sepultura","onde fica o cavaleiro da sepultura"}}},fp="16,135,17.210.0,24.74.0,26.51.0,40.98.0,17.34.0"}
P.entries["quest:96987"] = {n="Opportunistic Education",s="Rexxie Copperclutch pede que você busque um tomo na biblioteca de Dalaran enquanto os magos estão ocupados. Ela espera vender o livro e dividir o lucro com você.",h="Rexxie Copperclutch pede que você busque um tomo na biblioteca de Dalaran enquanto os magos estão ocupados.",kw={"dalaran","founding of dalaran","library","magos","opportunistic education","rexxie copperclutch","tomo","morto-vivo"},ang={["race:Undead"]="Por você ser um morto-vivo, Rexxie diz que você pensa como ela e acolhe você em seu esquema."},sec={{t="Um livro para Rexxie",b="Rexxie Copperclutch, perto da entrada dos esgotos, vê uma chance de lucrar com a biblioteca de Dalaran. Enquanto os magos estão ocupados, ela pede que você traga o tomo chamado Founding of Dalaran. Ela oferece dividir o valor da venda."},{t="O valor do livro",b="Rexxie avalia que o livro que você trouxe vale pouco. Ela pensa em disfarçá-lo com tinta dourada em spray e afirmar que pertenceu a um arquimago."}},faq={{q="Quem está pedindo o livro?",a="Rexxie Copperclutch, perto da entrada dos esgotos de Dalaran, pede que você traga um tomo da biblioteca da cidade.",al={"quem quer o tomo","rexxie copperclutch","quem é rexxie"}},{q="Qual livro Rexxie quer?",a="Rexxie pede Founding of Dalaran.",al={"qual livro","founding of dalaran","nome do tomo"}},{q="Por que Rexxie quer o tomo?",a="Rexxie espera vender o tomo e dividir o lucro com você.",al={"por que roubar o livro","para que serve o livro"}},{q="De onde deve vir o livro?",a="Rexxie pede que você encontre Founding of Dalaran em Dalaran.",al={"onde conseguir o tomo","biblioteca de dalaran","localização do livro"}},{q="O que está acontecendo com os magos de Dalaran?",a="Rexxie diz que os magos estão ocupados enquanto pede que você procure um livro.",al={"magos ocupados","por que oportunista","magos de dalaran"}},{q="O que Rexxie acha do livro que você traz?",a="Rexxie avalia que o livro vale pouco e pensa em borrifá-lo com tinta dourada para fazê-lo parecer valioso.",al={"o livro é valioso","o que acontece com o tomo","reação de rexxie"}}},fp="23,157,17.231.0,18.142.1,27.109.0,28.36.0,30.60.0,40.67.0,41.73.0,45.103.0"}
P.entries["quest:96988"] = {n="Source of Power",s="Source of Power é uma missão da Cidade Baixa encomendada pelo Doutor Martin Felben, que busca tirar proveito da agitação em Dalaran. Enquanto a cidade mágica está sob cerco de seus próprios constructos rebeldes, Felben incumbe os aventureiros de protegerem seus núcleos arcanos. Sua ambição é sintetizar a tecnologia mágica de Dalaran com a modelagem de carne dos Renegados para criar abominações imbuídas de magia arcana e chamar a atenção da Dama Sombria.",h="Source of Power é uma missão da Cidade Baixa encomendada pelo Doutor Martin Felben, que busca tirar proveito...",kw={"abominações","constructos arcanos","núcleo de sentinela rachado","dalaran","doutor martin felben","real sociedade de boticários","source of power","sylvana correventos","cidade baixa"},ang={["class:Mage"]="Os magos verão uma ironia sombria no fato de os constructos mágicos de Dalaran se voltarem contra seus mestres, apenas para terem suas sofisticadas fontes de poder arcano saqueadas para experimentos alquímicos macabros na Cidade Baixa.",["faction:Horde"]="Aventureiros da Horda que operam em Lordaeron apoiam os esforços dos Renegados para garantir recursos militares avançados contra seus rivais ao redor enquanto Dalaran está paralisada por suas próprias criações rebeldes.",["profession:Engineering"]="Engenheiros podem apreciar o trabalho intrincado por trás das sentinelas autônomas de Dalaran, mesmo quando seus delicados núcleos de poder arcano são arrancados para abastecer horríveis abominações de modelagem de carne.",["race:Undead"]="Os Renegados dependem fortemente das inovações implacáveis da Real Sociedade de Boticários para garantir sua sobrevivência em Lordaeron. Ajudar o Doutor Felben avança as pesquisas da facção em modelagem de carne arcana sob o olhar da Dama Sombria."},sec={{t="Uma Colheita Oportunista",b="O caos na cidade mágica de Dalaran criou uma oportunidade que os Renegados estão ansiosos para explorar. Com os próprios constructos arcanos de Dalaran em fúria desenfreada e sitiando os magos, o Doutor Martin Felben vê uma oportunidade de ouro em meio ao tumulto. Em vez de oferecer ajuda aos feiticeiros sitiados, o boticário procura recolher os núcleos arcanos que alimentam esses guardiões rebeldes. Dalaran há muito tempo protege ferozmente suas pesquisas mágicas, mas sua vulnerabilidade atual deixa suas sentinelas encantadas prontas para serem colhidas por pesquisadores oportunistas que operam a partir da Cidade Baixa."},{t="Ambição na Sociedade dos Boticários",b="O interesse do Doutor Felben pelos núcleos de sentinela rachados é inteiramente movido por ambição pessoal dentro da Real Sociedade de Boticários. Ao imbuir abominações dos Renegados com a volátil magia dos constructos de Dalaran, Felben sonha em erguer um exército devastador de bestas de carne movidas a poder arcano. Esse avanço terrível, calcula ele, chamaria a total atenção da Grande Dama Sylvana Correventos e demonstraria sua genialidade alquímica inigualável. Em última análise, Felben espera que essa criação possa elevar dramaticamente sua posição, talvez até garantindo a ele a liderança da própria Real Sociedade de Boticários, uma facção onde a astúcia implacável e resultados potentes ditam a sobrevivência e a hierarquia."}},faq={{q="Quem dá a missão Source of Power?",a="A missão é dada pelo Doutor Martin Felben, um boticário residente na Cidade Baixa, a capital dos Renegados. Felben é um pesquisador ambicioso que busca provar seus talentos alquímicos à Real Sociedade de Boticários e à Grande Dama Sylvana Correventos desenvolvendo monstruosidades militares inéditas.",al={"quem dá source of power","concedente da missão source of power","missão de martin felben"}},{q="O que está acontecendo em Dalaran durante esta missão?",a="Dalaran está atualmente sob cerco de seus próprios constructos arcanos, que se voltaram contra seus criadores. O caos e os combates resultantes na cidade mágica criam uma rara oportunidade para que pessoas de fora entrem sorrateiramente em Dalaran e resgatem os poderosos componentes mágicos que movem essas sentinelas rebeldes.",al={"o que aconteceu em dalaran","dalaran sob cerco","por que os constructos estão atacando dalaran"}},{q="Por que o Doutor Felben quer os núcleos dos constructos?",a="O Doutor Felben pretende aproveitar a energia arcana dentro dos núcleos de sentinela de Dalaran para aprimorar as abominações dos Renegados. Ao sintetizar o maquinário arcano bruto com a modelagem de carne, ele espera criar um exército de abominações movidas a poder arcano que provará seu domínio alquímico à Grande Dama Sylvana Correventos.",al={"por que coletar núcleos de sentinela","para que felben precisa de núcleos","plano de felben com núcleos de sentinela"}},{q="Quais são os objetivos de Source of Power?",a="Os aventureiros têm a tarefa de viajar até a cidade de Dalaran para confrontar os constructos rebeldes e reunir seis Núcleos de Sentinela Rachados. Uma vez adquiridas, essas relíquias mágicas voláteis devem ser transportadas de volta ao Doutor Martin Felben na Cidade Baixa para abastecer seus experimentos contínuos.",al={"objetivos de source of power","de quantos núcleos eu preciso","o que coletar para source of power"}},{q="Qual é o objetivo do Doutor Felben dentro da Real Sociedade de Boticários?",a="O Doutor Martin Felben busca reconhecimento e rápida ascensão na hierarquia dos Renegados. Ao apresentar à Grande Dama Sylvana Correventos uma força formidável de abominações imbuídas de magia arcana, ele espera impressionar a Dama Sombria o suficiente para ser nomeado líder da Real Sociedade de Boticários.",al={"objetivo de felben com os boticários","quem lidera a real sociedade de boticários","reconhecimento da dama sombria para felben"}},{q="Por que os Renegados estão saqueando a tecnologia de Dalaran?",a="A Real Sociedade de Boticários e os Renegados buscam constantemente armas e fontes de poder não convencionais para garantir sua sobrevivência em Lordaeron. Explorar a cidade mágica de Dalaran enquanto suas defesas entram em colapso por dentro permite que os boticários dos Renegados adquiram componentes arcanos sofisticados sem envolver formalmente os magos em guerra aberta.",al={"por que os renegados querem a magia de dalaran","constructos de dalaran cidade baixa","interesse dos renegados em dalaran"}},{q="Onde são encontrados os Núcleos de Sentinela Rachados?",a="Os Núcleos de Sentinela Rachados são coletados dos constructos rebeldes que estão atualmente sitiando a cidade de Dalaran. Os jogadores devem combater esses guardiões encantados hostis por toda a cidade mágica para extrair os componentes intactos necessários para as pesquisas do Doutor Felben na Cidade Baixa.",al={"onde encontrar núcleos de sentinela rachados","localização do núcleo de sentinela rachado","saques de núcleo de sentinela de dalaran"}}},fp="15,210,24.393.0,34.472.0,36.238.0,47.222.0,48.276.0,44.181.0,65.242.0,53.298.0,41.186.0"}
P.entries["quest:96996"] = {n="Your First Riding Galestrider",s="Após o treinamento, seu treinador pede que você escolha sua primeira montaria galestrider. A montaria escolhida viajará com você para longe de Zephras.",h="Após o treinamento, seu treinador pede que você escolha sua primeira montaria galestrider.",kw={"ancestrais","primeira montaria","galestrider","montaria","montaria strider","treinamento","zephras"},sec={{t="Uma escolha a fazer",b="O treinamento terminou, e as montarias galestrider aguardam você em Zephras. Seu treinador diz que seus ancestrais montam essas criaturas esguias e diáfanas há gerações. Apesar da aparência, elas são firmes e ferozes. Examine as montarias e escolha uma para acompanhar você."},{t="Uma lembrança de casa",b="Depois que você escolhe, seu treinador percebe que a montaria já parece gostar de você. Esse vínculo leva consigo uma lembrança de Zephras enquanto suas aventuras levam você para longe de casa. Seu treinador espera que você cuide da montaria e que ela cuide de você."}},faq={{q="O que é um galestrider?",a="Um galestrider é uma montaria usada por seus ancestrais há gerações. Embora sejam esguios e diáfanos, os galestriders são firmes e ferozes.",al={"montaria galestrider","montaria strider","o que é esse strider"}},{q="Por que estou escolhendo uma montaria?",a="Seu treinamento terminou, e seu treinador pede que você escolha uma montaria galestrider para acompanhar você em suas viagens.",al={"por que escolher um strider","primeira escolha de montaria","escolher minha montaria"}},{q="Onde estão as montarias strider?",a="As montarias strider estão em Zephras, onde seu treinador pede que você as examine.",al={"onde ficam os striders","localização dos galestriders","striders em zephras"}},{q="Minha montaria vai viajar comigo?",a="Sim. A montaria que você escolher acompanhará você enquanto suas aventuras o levam para longe de Zephras.",al={"strider vem comigo","viagem com montaria","levar strider comigo"}},{q="O que meu treinador diz sobre a montaria que escolho?",a="Seu treinador diz que a montaria parece gostar de você e espera que vocês cuidem um do outro.",al={"resposta do treinador sobre a escolha","strider gosta de mim","strider escolhido"}}},fp="29,154,16.281.0,18.248.1,22.131.0,28.117.0,30.80.0,31.89.0,52.88.0"}
P.entries["quest:96997"] = {n="A Steed in Death as They Were in Life",s="Um Renegado oferece a você um corcel que o serve na morte como servia em vida. Resta apenas um eco de vida, mas o vínculo entre cavaleiro e cavalo ainda pode ser real.",h="Um Renegado oferece a você um corcel que o serve na morte como servia em vida.",kw={"vínculo","renegados","cavalo","lordaeron","corcel","cavalo morto-vivo","não vida","corcel profano"},ang={["race:Undead"]="Como Renegado, você recebe um companheiro que compartilha sua não vida. O vínculo do corcel com você é real, e ambos precisam encontrar um propósito."},sec={{t="Um corcel Renegado",b="Um Renegado oferece a você uma escolha entre cavalos que já estiveram entre os melhores de Lordaeron. Eles mantêm suas próprias personalidades, embora reste neles apenas um eco de vida. Não fogem do perigo e permanecem ao seu lado até sua morte definitiva."},{t="Um vínculo real",b="O corcel que você escolher não precisa de descanso nem de alimento. O vínculo dele com você é real, embora esteja morto, e pedem a você que cuide dele como ele cuida de você. Mesmo na não vida, você e seu companheiro precisam encontrar um propósito."}},faq={{q="Que tipo de cavalos são esses?",a="Eles já estiveram entre os melhores cavalos de Lordaeron. Na morte, servem aos Renegados como serviam em vida.",al={"cavalo morto-vivo","corcel renegado","cavalos mortos"}},{q="Os cavalos ainda têm personalidade?",a="Sim. Os cavalos mantêm suas próprias personalidades, embora reste neles apenas um eco de vida.",al={"personalidade do cavalo","cavalos mortos-vivos pensam","como eles são"}},{q="O corcel fugirá do perigo?",a="Não. O corcel permanecerá ao seu lado até sua morte definitiva.",al={"cavalo foge","ele foge","corcel assustado"}},{q="Um corcel profano precisa de alimento ou descanso?",a="Não. Um corcel profano não precisa de alimento nem de descanso.",al={"alimentar cavalo morto-vivo","cavalo precisa descansar","alimento para corcel"}},{q="O vínculo com um cavalo morto é real?",a="Sim. Embora o corcel esteja morto, o vínculo entre ele e seu cavaleiro é real.",al={"vínculo com cavalo morto-vivo","vínculo com corcel morto","ele é apegado"}},{q="Por que esses cavalos são companheiros dos Renegados?",a="Eles são companheiros adequados para os Renegados porque servem na morte como serviam em vida.",al={"por que cavalos renegados","propósito do cavalo morto-vivo","corcel para renegados"}}},fp="37,170,16.246.0,11.205.0,30.107.0,39.92.0,31.58.0,39.48.0,35.73.0,49.93.0"}
P.entries["quest:97"] = {n="A lenda de Galvão",s="Esta etapa da investigação finalmente confirma a verdade sinistra que liga o antigo tutor aos registros de Vila Sombria. O Tabelião Azambuja compara com sucesso a caligrafia dos documentos recuperados à de Galvão Brumanto, motivando um relato imediato à Comandante Althea Ebonlocke. É o momento em que as suspeitas da Vigília Noturna se transformam em fatos incontestáveis.",h="Esta etapa da investigação finalmente confirma a verdade sinistra que liga o antigo tutor aos registros de...",kw={"althea ebonlocke","tabelião azambuja","vila sombria","floresta do crepúsculo","caligrafia","brumanto","vigília noturna","galvão"},ang={["faction:Alliance"]="Para os investigadores da Aliança, desvendar o rastro de Galvão mostra a importância da cooperação entre a liderança sobrecarregada de Vila Sombria e aventureiros itinerantes para proteger os territórios meridionais do reino.",["race:Human"]="Jogadores humanos veem aqui um reflexo da decadência trágica de sua sociedade: tutores respeitados e cidades rurais que, pouco a pouco, deixam a civilização para trás e mergulham na loucura e no isolamento."},sec={{t="Uma correspondência nos registros",b="Depois de vasculhar mansões, estalagens e arquivos municipais em vários reinos humanos, as pistas dispersas levam de volta à prefeitura de Vila Sombria. O Tabelião Azambuja compara a página ensanguentada do diário às assinaturas do registro municipal. O resultado não deixa dúvidas: a caligrafia pertence a Galvão Brumanto, fornecendo à Vigília Noturna a prova concreta necessária para tratar o caso como uma ameaça urgente à cidade."},{t="As suspeitas da Vigília Noturna",b="A Comandante Althea Ebonlocke tinha maus pressentimentos sobre Galvão desde o início da investigação. A Floresta do Crepúsculo já sofre com worgens selvagens, mortos-vivos esqueléticos e necromantes à espreita. Um assassino escondido nas sombras da mata é um perigo que ela não pode ignorar. A confirmação de Azambuja valida seus piores temores e leva a Vigília Noturna a procurar o eremita e neutralizá-lo de uma vez por todas."}},faq={{q="O que o Tabelião Azambuja descobriu?",a="O Tabelião Azambuja comparou a página ensanguentada do diário às assinaturas do registro municipal de Vila Sombria e confirmou que a caligrafia correspondia exatamente à de Galvão Brumanto, como a Comandante Ebonlocke suspeitava.",al={"o que azambuja descobriu","comparação da caligrafia de azambuja","prova da letra de galvão"}},{q="Por que a Comandante Althea Ebonlocke se preocupa tanto com Galvão?",a="A Comandante Althea Ebonlocke lidera a Vigília Noturna, a milícia sobrecarregada de Vila Sombria. Numa terra já assolada por horrores, ela não pode permitir que uma figura violenta e misteriosa, com um passado sombrio, continue à solta na Floresta do Crepúsculo.",al={"por que althea se preocupa","investigação de ebonlocke","vigília noturna galvão"}},{q="Onde se passa esta etapa?",a="Toda esta etapa acontece em Vila Sombria. O Tabelião Azambuja fica na prefeitura, enquanto a Comandante Althea Ebonlocke pode ser encontrada patrulhando as ruas centrais próximas.",al={"onde fica esta missão","localização da missão","entrega da missão de galvão em vila sombria"}},{q="O que acontece depois de informar sobre a caligrafia?",a="Depois que a Comandante Ebonlocke recebe a confirmação do Tabelião Azambuja, a investigação passa a se concentrar na busca pelo paradeiro atual de Galvão nas matas assombradas da Floresta do Crepúsculo.",al={"próxima etapa de galvão","depois da confirmação de azambuja","continuação da série de galvão"}},{q="Quem era Galvão Brumanto originalmente?",a="Galvão Brumanto já lecionou no liceu de Arroio da Lua e, depois, trabalhou como tutor particular dos filhos da família Petracume. As pistas em suas cartas e páginas de diário vão de Arroio da Lua e Vila d'Ouro até a Floresta do Crepúsculo, onde agora vive como um eremita perigoso.",al={"quem é galvão","passado de galvão","história de galvão brumanto"}},{q="Por que foi necessário comparar as caligrafias?",a="Como os acontecimentos e as acusações envolvendo Galvão se espalharam por várias regiões, incluindo Arroio da Lua e Vila d'Ouro, os registros oficiais estavam fragmentados. O registro municipal de Vila Sombria continha amostras locais verificadas que permitiam associar definitivamente as pistas externas àquele homem.",al={"por que comparar as letras","por que azambuja examinou a escrita","como provar a identidade de galvão"}}},fx={cc1b58e5={q="Por que o Tabelião Azambuja está tão ansioso para que você se reporte ao Comandante Ebonlocke?",a="O Tabelião Azambuja é um escrivão da cidade, não um oficial da Vigia Noturna, e confirmar que a letra pertence a Galvão Brumanto valida as graves suspeitas do Comandante Ebonlocke. Azambuja reconhece que uma investigação oficial de assassinato requer autoridade armada imediata, tornando urgente que Althea receba provas definitivas sem demora.",al={"por que daltry quer que isso seja feito","motivo de daltry","por que se reportar a althea"}}},fp="21,137,22.323.0,28.315.1,31.183.0,63.224.0,32.159.0,51.128.0,38.255.0,39.225.0"}
P.entries["quest:970"] = {n="A Torre de Althalaxx",s="Esta missão marca uma virada importante na investigação da sinistra Seita da Linhagem das Trevas. A busca começa na Torre de Althalaxx, em Costa Negra, e segue pela fronteira até o Entreposto de Maestra, no Vale Gris. Dinis, o Purificador, envia aventureiros aos acampamentos próximos de cultistas para recuperar uma poderosa Gema Anímica Faiscante. Ao desvendar os segredos do artefato, ele espera revelar a magia sombria que sustenta a influência do culto nas florestas do norte.",h="Esta missão marca uma virada importante na investigação da sinistra Seita da Linhagem das Trevas.",kw={"althalaxx","vale gris","linhagem das trevas","costa negra","dinis","dinis, o purificador","gema anímica faiscante","entreposto de maestra","ordil'aran"},ang={["class:Paladin"]="Purificar receptáculos sombrios de almas e passar cultistas corrompidos pela espada alinha-se estreitamente com o dever do paladino de expurgar a corrupção profana do mundo.",["class:Priest"]="Examinar um receptáculo sombrio de alma reflete o chamado do sacerdote de se opor à corrupção e trazer alívio a almas atormentadas.",["faction:Alliance"]="Coordenar entre postos avançados na Costa Negra e no Vale Gris protege a fronteira norte contra praticantes sombrios que ameaçam os viajantes da Aliança.",["race:NightElf"]="Ver cultistas vis profanando ruínas antigas como Ordil'Aran e corrompendo os bosques do norte torna a eliminação da Seita da Linhagem das Trevas uma prioridade urgente para qualquer elfo noturno."},sec={{t="Um Apelo Além da Fronteira",b="Depois que atividades sinistras são descobertas nas proximidades da Torre de Althalaxx, no norte de Costa Negra, as investigações conduzem ao sul, até Dinis, o Purificador, no Vale Gris. Estabelecido no Entreposto de Maestra, Dinis enfrenta há muito tempo os cultistas da Linhagem das Trevas que invadem as antigas florestas élficas. Sabendo que a ameaça se estende por ambos os territórios, ele decide atacar a origem de sua magia perversa."},{t="Os Segredos de Ordil'Aran",b="A nordeste do Entreposto de Maestra encontram-se as ruínas de Ordil'Aran, agora dominadas por cultistas fanáticos da Linhagem das Trevas. Dinis identifica que seus agentes carregam gemas anímicas faiscantes — receptáculos sombrios encantados com magia sinistra que sustentam o poder do culto. Ao caçar os cultistas entre as ruínas e recuperar uma dessas gemas, Dinis pretende quebrar o encantamento e expor a verdadeira fonte por trás de seu rito malévolo."},{t="Um Espírito Aprisionado",b="Ao decifrar os vis encantamentos vinculados à gema anímica faiscante, Dinis não apenas desenterra encantamentos sombrios; ele desvenda um receptáculo de tormento. Quebrar as proteções da gema liberta o espírito de Sargath, um dos elfos de Ameth'Aran a quem Athrikus Narassin aprisionou em gemas anímicas durante a Cisão e vem drenando lentamente desde então. A aparição nomeia o tenente de Athrikus, Ilkrud Magthrull, cujo tomo pode revelar onde as gemas anímicas restantes estão guardadas."}},faq={{q="Onde encontro a Gema Anímica Faiscante?",a="A Gema Anímica Faiscante é mantida por membros da Seita da Linhagem das Trevas localizados a nordeste do Entreposto de Maestra nas ruínas de Ordil'Aran no Vale Gris. Vários cultistas à espreita nas ruínas a carregam, embora possa levar alguma persistência para recuperar uma.",al={"localização da gema anímica","onde cai a gema anímica","gema anímica linhagem das trevas"}},{q="Quem é Dinis, o Purificador?",a="Dinis, o Purificador, é um campeão da Aliança que atua no Entreposto de Maestra, no norte do Vale Gris. Ele combate as forças sombrias que invadem a floresta, especialmente a Seita da Linhagem das Trevas.",al={"dinis","quem é dinis"}},{q="O que é a Seita da Linhagem das Trevas?",a="A Seita da Linhagem das Trevas é uma organização malévola que opera a partir da Torre de Althalaxx na Costa Negra e antigas ruínas élficas como Ordil'Aran no Vale Gris. Eles praticam feitiçaria sombria, aprisionamento de almas e rituais necromânticos.",al={"seita linhagem das trevas","quem são os membros da linhagem das trevas"}},{q="Por que uma missão da Costa Negra está me enviando ao Vale Gris?",a="Embora a investigação comece na Torre de Althalaxx na Costa Negra, a rede do culto se estende ao sul pela fronteira até o Vale Gris. Dinis, o Purificador no Entreposto de Maestra possui a perícia necessária para combater a magia de aprisionamento de almas do culto.",al={"por que entreposto de maestra","por que ir para o vale gris"}},{q="O que acontece quando a gema anímica é decifrada?",a="Dinis pretende decifrar o encantamento sombrio na Gema Anímica Faiscante. O que ele descobre é revelado após você trazer a gema para ele.",al={"o que há na gema anímica","fantasma da gema anímica"}},{q="Onde Ordil'Aran está localizada?",a="Ordil'Aran é uma antiga ruína élfica situada logo a nordeste do Entreposto de Maestra, no norte do Vale Gris, atualmente infestada pela Seita da Linhagem das Trevas.",al={"localização de ordil'aran","onde fica ordilaran"}}},fx={a63b3648={q="Por que Dinis, o Purificador quer que isso seja feito?",a="Dinis vem enfrentando a Seita da Linhagem das Trevas, cujos membros se entrincheiraram a nordeste do Entreposto de Maestra. Para ele, representam uma ameaça que precisa ser eliminada. Os avisos preocupantes na carta de Balthule Umbrataque confirmam que sua influência corruptora está crescendo. Dinis acredita que os segredos aprisionados na gema anímica encantada podem ajudá-lo a revelar e destruir o poder do culto.",al={"motivo de dinis","por que dinis quer a gema anímica","por que lutar contra a seita da linhagem das trevas"}},c112c454={q="Para que serve a Gema Anímica Faiscante?",a="A Gema Anímica Faiscante é um artefato sombrio e encantado carregado pela Seita da Linhagem das Trevas em Ordil'Aran. Dinis acredita que ela guarda o segredo da magia perversa do culto e do poder que seus membros utilizam. Ao levar a gema até ele, você permite que Dinis decifre os encantamentos que envolvem a pedra e descubra qual essência ou entidade está aprisionada ali.",al={"o que é gema anímica faiscante","propósito da gema anímica faiscante","gema anímica linhagem das trevas"}},d0742ede={q="Contra quem você é enviado em Ordil'Aran?",a="Você é enviado para enfrentar a Seita da Linhagem das Trevas que ocupa as ruínas de Ordil'Aran, a nordeste do Entreposto de Maestra. Cultistas, fanáticos, acólitos e conjuradores adeptos se reuniram entre as ruínas élficas para realizar ritos proibidos. Um dos membros carrega uma gema anímica encantada que Dinis precisa para desbloquear os segredos do culto, exigindo que você abra caminho por entre as fileiras deles até que a relíquia seja recuperada.",al={"quem está em ordil'aran","linhagem das trevas em ordil'aran","quem segura a gema anímica"}}},fp="22,227,24.334.0,25.322.0,16.347.1,37.199.0,28.173.0,36.214.0,49.182.0,45.126.1,28.130.0"}
P.entries["quest:97003"] = {n="Chol'aruk the Ravener",s="Chol'aruk the Ravener é uma caçada nos Sertões visando um javatusco colossal que, segundo rumores, habita uma caverna no Morro dos Espinhos. Acreditando nos contos terríveis após encontros passados com feras semelhantes, o orc Gur'ak encarrega aventureiros de desafiar o covil da criatura e trazer de volta sua cabeça.",h="Chol'aruk the Ravener é uma caçada nos Sertões visando um javatusco colossal que, segundo rumores, habita uma...",kw={"sertões","chol'aruk","cholaruk","gur'ak","gurak","quilboar","razormane","the ravener","morro dos espinhos"},ang={["class:Hunter"]="Rastrear uma fera monstruosa que, segundo rumores, é cinco vezes maior do que javatuscos comuns exige os instintos aguçados de um caçador e preparação para enfrentar uma presa formidável.",["class:Warrior"]="Enfrentar uma criatura brutal conhecida por uma sede insaciável de sangue requer guerreiros na linha de frente prontos para resistir a uma fúria física avassaladora.",["faction:Horde"]="O orc Gur'ak faz este Call to Arms sob o brado de guerra tradicional da Horda, 'Sangue e trovão', encarregando aventureiros de abater uma ameaça perigosa à espreita nos Sertões."},sec={{t="A Lenda do Ravener",b="Na extensão árida dos Sertões, sussurros entre os javatuscos Razormane falam de Chol'aruk, um terror gigantesco apelidado de 'The Ravener'. Segundo rumores regionais, este bruto aterrorizante faz seu covil nas profundezas de uma caverna no Morro dos Espinhos, a nordeste das trilhas locais. Os javatuscos afirmam que ele tem cerca de cinco vezes o tamanho de um javatusco comum, impulsionado por uma sede de sangue violenta e insaciável. Embora muitos descartem tais histórias como contos exagerados de fogueira, Gur'ak sabe bem a verdade por conta de batalhas passadas com monstruosidades semelhantes."},{t="O Aviso de Gur'ak",b="Reconhecendo o perigo real representado por uma fera de tal magnitude, Gur'ak orienta viajantes capazes a rastrear a criatura até seu covil subterrâneo no Morro dos Espinhos. Suas instruções são diretas: dar um fim ao bruto monstruoso e retornar com sua cabeça como prova incontestável. Diante dos rumores sobre a ferocidade e a escala colossal de Chol'aruk, Gur'ak faz uma severa advertência de que apenas grupos bem preparados devem ousar entrar na caverna para confrontar o Ravener."}},faq={{q="Quem é Chol'aruk the Ravener?",a="Chol'aruk, também chamado de The Ravener pela tribo Razormane, é um javatusco lendário e monstruoso. Com rumores de ter cinco vezes o tamanho de um javatusco comum, ele possui uma sede insaciável de sangue e vive em uma caverna profunda nos Sertões.",al={"quem é cholaruk","o que é cholaruk","the ravener"}},{q="Onde Chol'aruk pode ser encontrado?",a="Chol'aruk habita as profundezas de uma caverna no Morro dos Espinhos, situada a nordeste do acampamento de Gur'ak nos Sertões. Aventureiros devem se aventurar nas cavernas do Morro dos Espinhos para encontrar seu covil.",al={"onde fica cholaruk","localização de cholaruk","onde fica a caverna do morro dos espinhos"}},{q="Quem oferece a caçada por Chol'aruk?",a="Gur'ak, um orc posicionado nos Sertões, oferece a tarefa. Ao contrário de outros que descartam as histórias da fera gigante como mera conversa de taverna, Gur'ak acredita nos rumores porque já enfrentou monstruosidades semelhantes antes.",al={"quem dá a missão de cholaruk","quem é gurak","gurak sertões"}},{q="Por que Gur'ak está caçando Chol'aruk?",a="Gur'ak quer Chol'aruk destruído para eliminar uma ameaça selvagem que aterroriza a região e exige a cabeça decepada da fera como prova de que o Ravener foi derrotado.",al={"por que matar cholaruk","motivo da recompensa por cholaruk"}},{q="Devo enfrentar Chol'aruk sozinho?",a="Gur'ak adverte explicitamente os viajantes a não procurarem Chol'aruk sozinhos. Devido ao seu tamanho colossal relatado e sua ferrenha sede de sangue, abater o Ravener é planejado como um desafio formidável que requer um grupo de caça preparado.",al={"posso fazer cholaruk sozinho","cholaruk é difícil","levar grupo para cholaruk"}},{q="Qual é a ligação entre Chol'aruk e os javatuscos Razormane?",a="Javatuscos são humanoides semelhantes a javalis nativos das planícies do centro de Kalimdor, com a tribo Razormane habitando partes dos Sertões. Os próprios Razormane falam de Chol'aruk com pavor, atribuindo à fera o título de 'The Ravener'.",al={"o que são javatuscos","razormane cholaruk","por que os razormane o temem"}}},fp="21,155,25.395.0,16.307.0,29.209.0,29.149.0,34.130.0,32.141.0,31.151.0,68.209.0"}
P.entries["quest:97005"] = {n="Chol'aruk, o Rapinante",s="Chol'aruk, o Rapinante, é uma temível abominação monstruosa escondida numa caverna do Morro dos Espinhos, nos Sertões. Os javatuscos Crinavalha locais o chamam de Chol'aruk ou “o Rapinante”, e rumores afirmam que a criatura é grande o bastante para engolir um orc inteiro. Bainham quer sua cabeça para vingar companheiros mortos por horrores semelhantes.",h="Chol'aruk, o Rapinante, é uma temível abominação monstruosa escondida numa caverna do Morro dos Espinhos, nos...",kw={"abominação","bainham","sertões","chol'aruk","crinavalha","o rapinante","morro dos espinhos"},ang={["class:Hunter"]="Enfrentar um predador alfa lendário que dizem engolir guerreiros totalmente protegidos inteiros é o teste definitivo da perícia e da coragem de um rastreador.",["class:Warrior"]="O apelo de Bainham toca diretamente no credo de um guerreiro: vingar camaradas caídos confrontando um horror colossal frente a frente em seu covil subterrâneo.",["faction:Horde"]="Monstros vagando livremente pelos altos platôs ameaçam viajantes e caravanas que cruzam os Sertões, tornando a erradicação da fera uma questão de segurança regional."},sec={{t="Terror do Morro dos Espinhos",b="A noroeste de onde Bainham aguarda nos Sertões fica o platô conhecido como Morro dos Espinhos, há muito disputado pelas tribos nativas dos Crinavalha. Recentemente, rumores sussurrados falaram de uma presença aterrorizante entrincheirada dentro de uma de suas cavernas: uma abominação monstruosa que os Crinavalha chamam de Chol'aruk, ou \"o Rapinante\". Embora muitos viajantes descartem relatos de uma fera capaz de engolir um orc de armadura em um único bocado como lendas de fogueira, aqueles que testemunharam o massacre de perto sabem que a ameaça é real demais."},{t="Um Rancor Quitado",b="Para Bainham, a existência de Chol'aruk está longe de ser um mito. Tendo enfrentado horrores semelhantes no passado, ele carrega cicatrizes pessoais e lamenta camaradas caídos para tais feras. Sabendo do perigo que uma abominação voraz representa para todos que vagam pela Savana, ele encarrega campeões experientes de escalar o platô, invadir seu covil subterrâneo e abater Chol'aruk para reivindicar sua enorme cabeça."}},faq={{q="Que tipo de criatura é Chol'aruk?",a="Chol'aruk é descrito como uma abominação monstruosa à espreita dentro de uma caverna no Morro dos Espinhos. Relata-se que ele é tão gigantesco que pode engolir um orc adulto inteiro, o que lhe rendeu o aterrorizante título de \"o Rapinante\" entre os Crinavalha locais.",al={"o que e cholaruk","tipo de monstro cholaruk","quem e o rapinante"}},{q="Onde fica o covil de Chol'aruk?",a="Chol'aruk faz seu covil dentro de uma caverna no alto platô do Morro dos Espinhos, localizado a noroeste nos Sertões.",al={"onde fica cholaruk","localizacao de cholaruk","caverna do morro dos espinhos"}},{q="Quem é Bainham e por que ele quer a morte de Chol'aruk?",a="Bainham, encontrado nos Sertões, tem um histórico pessoal de luta contra tais feras. Tendo perdido aliados para abominações semelhantes no passado, ele busca a ruína de Chol'aruk por honra e por vingança em nome de seus camaradas caídos.",al={"quem dá a missao de cholaruk","por que matar cholaruk","historia de bainham"}},{q="O que significa o título “Rapinante”?",a="Os javatuscos Crinavalha deram esse título a Chol'aruk por sua voracidade insaciável. Segundo rumores, ele devora guerreiros adultos inteiros sem hesitar.",al={"significado de cholaruk","por que chamado ravener","crinavalha cholaruk"}},{q="Os javatuscos Crinavalha veneram ou temem Chol'aruk?",a="Isso ainda não se sabe. Os Crinavalha chamam a criatura de Chol'aruk ou \"o Rapinante\", mas a missão não diz se eles temem ou veneram a abominação monstruosa que habita uma caverna no Morro dos Espinhos.",al={"javatuscos gostam de cholaruk","crinavalha e cholaruk"}},{q="Que prova é necessária para confirmar a morte de Chol'aruk?",a="Bainham pede que você retorne com a cabeça decepada de Chol'aruk como prova irrefutável de que a abominação foi erradicada.",al={"entregar missao de cholaruk","o que levar para bainham"}}},fp="21,141,20.371.0,15.372.0,35.145.0,34.81.0,51.134.0,29.135.0,52.198.0,52.78.0"}
P.entries["quest:97048"] = {n="Returning to Port",s="Um cozinheiro resgatado pede que você fale com Captain Aransas em Angra do Butim. O retorno dele importa para a capitã, que perdeu um membro da tripulação.",h="Um cozinheiro resgatado pede que você fale com Captain Aransas em Angra do Butim.",kw={"angra do butim","captain aransas","cozinheiro","tripulação","complexo do kurzen","mathers","voltando ao porto"},sec={{t="De volta à capitã",b="Captain Aransas espera em Angra do Butim, onde você leva o cozinheiro de volta ao navio dela. Ele promete falar bem de você quando voltar e diz que a capitã ficará feliz em tê-lo de volta. Ela dá as boas-vindas a você e ouve o que Mathers contou sobre sua fuga do Complexo do Kurzen."},{t="O agradecimento da capitã",b="Captain Aransas sabe que a história de Mathers sobre uma luta ousada com espadas é mentira. Ela diz que o cozinheiro só sabe usar uma faca de cozinha. Ainda assim, agradece por você ter salvado um membro da tripulação. Um bom cozinheiro é precioso a bordo do navio dela."}},faq={{q="Quem é Captain Aransas?",a="Captain Aransas comanda o navio cujo cozinheiro você leva de volta para ela em Angra do Butim.",al={"captain aransas","aransas"}},{q="Quem é Mathers?",a="Mathers é o cozinheiro de Captain Aransas e um membro da tripulação dela.",al={"mathers","cozinheiro mathers"}},{q="Onde encontro Captain Aransas?",a="Captain Aransas está em Angra do Butim.",al={"localização de aransas","capitã em angra do butim"}},{q="Por que a capitã me agradece?",a="Ela agradece por você ter salvado um membro da tripulação dela.",al={"por que agradece","cozinheiro salvo"}},{q="O que Mathers contou sobre a fuga?",a="Mathers contou a Captain Aransas que vocês dois escaparam juntos do Complexo do Kurzen.",al={"história de mathers","o que ele contou a aransas"}}},fp="17,137,19.272.0,20.212.1,23.76.0,15.58.0,32.32.0,30.47.0,38.85.0"}
P.entries["quest:971"] = {n="Conhecimento nas Profundezas",s="Conhecimento nas Profundezas é uma missão da Aliança oferecida por Gerrig Agarrosso na Caverna Esquecida de Altaforja. Ele encarrega os aventureiros de atravessar o mar rumo às ruínas submersas de Profundezas Negras, no Vale Gris, para recuperar o antigo Manuscrito de Lorgalis. Sob a fachada de estudioso de Agarrosso, esconde-se um plano sinistro ligado a entidades sombrias e a uma profecia apocalíptica.",h="Conhecimento nas Profundezas é uma missão da Aliança oferecida por Gerrig Agarrosso na Caverna Esquecida de...",kw={"vale gris","profundezas negras","caverna esquecida","gerrig agarrosso","altaforja","conhecimento nas profundezas","manuscrito de lorgalis"},ang={["class:Warlock"]="Agarrosso trabalha ao lado dos bruxos escondidos na Caverna Esquecida, em Altaforja, compartilhando com eles a sede por textos proibidos capazes de transpor as barreiras entre os planos.",["faction:Alliance"]="Embora ajudar um estudioso da Aliança pareça inofensivo, os verdadeiros motivos e associados sombrios de Agarrosso insinuam planos mais obscuros agindo dentro dos muros de Altaforja.",["race:NightElf"]="O manuscrito fica em Profundezas Negras, um santuário elfo noturno submerso agora ocupado por cultistas e outros invasores."},sec={{t="Um Estudioso nas Sombras",b="Escondido nos recantos úmidos da Caverna Esquecida, em Altaforja, Gerrig Agarrosso se apresenta como um colecionador dedicado de textos antigos. Contudo, seus interesses acadêmicos têm um caráter nitidamente sinistro. Agarrosso não procura histórias banais ou registros municipais: busca conhecimentos esquecidos capazes de abrir portais e despertar “Aqueles Que Dormem”. Suas palavras sobre sobreviver ao “fim dos dias” revelam um excêntrico — ou um perigoso devoto de poderes sombrios e adormecidos."},{t="A Ruína Submersa de Lorgalis",b="Agarrosso envia os exploradores ao outro lado de Azeroth, até as costas sombrias do Vale Gris, onde o antigo santuário elfo noturno de Profundezas Negras jaz submerso. Antes de a Grande Cisão despedaçar Kalimdor, estudiosos elfos noturnos reuniam imenso conhecimento mágico em seus templos costeiros. Em meio aos corredores inundados, agora infestados de nagas, sátiros e cultistas do Martelo do Crepúsculo, repousa o Manuscrito de Lorgalis — um texto de conhecimento proibido guardado em um Pitted Iron Chest."},{t="Irmãos e Irmãs",b="Ao receber o manuscrito encharcado, Agarrosso não faz nenhum esforço para arquivá-lo no Salão dos Exploradores de Altaforja. Em vez disso, ele se alegra abertamente com o fato de que cópias serão produzidas e disseminadas entre seus misteriosos \"irmãos e irmãs\". Embora seja grato ao aventureiro da Aliança que o recuperou, a lealdade de Agarrosso claramente pertence a uma seita clandestina ávida por usar o conhecimento recuperado em ritos esotéricos que alteram o mundo. Agarrosso é associado ao Martelo do Crepúsculo, cujos seguidores buscam o conhecimento proibido dos Deuses Antigos."}},faq={{q="Quem concede a missão Conhecimento nas Profundezas?",a="A missão é oferecida por Gerrig Agarrosso, um anão em busca de conhecimentos antigos que vive na Caverna Esquecida, um local pouco iluminado de Altaforja.",al={"concedente da missão","onde pegar a missão","quem inicia conhecimento nas profundezas"}},{q="O que é o Manuscrito de Lorgalis?",a="O Manuscrito de Lorgalis é um texto que Gerrig Agarrosso quer recuperar de Profundezas Negras. Ele é guardado em um Pitted Iron Chest entre as ruínas inundadas.",al={"o que é o manuscrito de lorgalis","história de lorgalis","qual livro eu encontro"}},{q="Onde fica o Manuscrito de Lorgalis?",a="O manuscrito repousa nas profundezas da masmorra de Profundezas Negras, localizada ao longo da Praia de Zoram, na costa noroeste do Vale Gris, em Kalimdor.",al={"localização do manuscrito de lorgalis","onde está o livro em profundezas negras","localização do livro em profundezas negras"}},{q="Quem são \"Aqueles Que Dormem\" mencionados por Gerrig Agarrosso?",a="Agarrosso usa esse nome enigmático para os poderes adormecidos descritos no conhecimento proibido que ele coleta. As seções protegidas da missão exploram suas conexões mais sombrias.",al={"aqueles que dormem","de quem agarrosso está falando","o que gerrig adora"}},{q="Quem são os \"irmãos e irmãs\" com quem Gerrig planeja compartilhar o manuscrito?",a="Os associados de Agarrosso compartilham seu interesse por conhecimentos proibidos. Recuperar o manuscrito pode revelar mais sobre a quem ele serve.",al={"irmãos e irmãs de gerrig","para quem gerrig trabalha","facção de agarrosso"}},{q="Por que uma missão em Altaforja envia os jogadores até o Vale Gris?",a="A Caverna Esquecida, em Altaforja, atrai praticantes de magia não autorizados, bruxos e ladinos em busca de segredos ocultos. Agarrosso coleciona conhecimentos antigos e poderosos. Segundo rumores, o Manuscrito de Lorgalis que ele procura está nas profundezas das Profundezas Negras, no Vale Gris, antiga morada de elfos que possuíam grande sabedoria.",al={"por que ir ao vale gris","missão de altaforja para profundezas negras","viajar para profundezas negras"}}},fx={["32faf93b"]={q="Por que Gerrig Agarrosso quer o Manuscrito de Lorgalis?",a="Gerrig Agarrosso coleciona textos antigos e poderosos capazes de abrir portais esquecidos e despertar Aqueles Que Dormem. Ele acredita que o Manuscrito de Lorgalis contém segredos há muito perdidos dos antigos elfos noturnos das Profundezas Negras. Antes da chegada do fim dos dias, pretende copiar e distribuir esses conhecimentos sombrios entre seus misteriosos irmãos e irmãs.",al={"motivo de gerrig agarrosso","por que gerrig quer o manuscrito","motivo da missão de gerrig agarrosso"}}},fp="22,175,24.364.0,27.407.0,20.458.1,43.110.0,32.145.0,41.129.0,55.102.0,77.123.1,68.305.0"}
P.entries["quest:97130"] = {n="Ancient Gurubashi Secrets",s="Lan'dalock e um companheiro pedem que você recupere um ídolo de uma antiga ruína Gurubashi que ressurgiu recentemente ao largo da Selva do Espinhaço. O local pode conter pistas valiosas sobre a magia de sangue Gurubashi.",h="Lan'dalock e um companheiro pedem que você recupere um ídolo de uma antiga ruína Gurubashi que ressurgiu...",kw={"ancient gurubashi idol","segredos gurubashi ancestrais","magia de sangue","drowned city","gurubashi","lan'dalock","mares do sul","selva do espinhaço","médicos bruxos"},sec={{t="Uma ruína que emergiu",b="Lan'dalock e um companheiro têm conversado sobre uma mudança estranha nos Mares do Sul. Uma antiga ruína Gurubashi surgiu ao largo da costa da Selva do Espinhaço. Seu retorno repentino desperta o interesse de quem estuda o passado."},{t="Um ídolo dos Gurubashi",b="A Drowned City guarda artefatos de grande valor arqueológico. Lan'dalock procura um ídolo que certos médicos bruxos Gurubashi usavam como foco para magia de sangue. Pedem que você traga um para estudo."}},faq={{q="Quem quer o ídolo?",a="Lan'dalock e um companheiro procuram um Ancient Gurubashi Idol na Drowned City.",al={"quem me enviou","ídolo de lan'dalock","quem quer o ídolo"}},{q="Onde surgiu a ruína Gurubashi?",a="A ruína Gurubashi ancestral surgiu na costa da Selva do Espinhaço, nos Mares do Sul.",al={"onde fica a drowned city","local da ruína","cidade gurubashi"}},{q="Por que querem um ídolo?",a="Certos médicos bruxos Gurubashi ancestrais usavam ídolos como focos para magia de sangue, e Lan'dalock quer um para estudo.",al={"por que o ídolo","para que serve o ídolo","para que serve"}},{q="O que é a Drowned City?",a="É uma ruína Gurubashi ancestral que surgiu na costa da Selva do Espinhaço.",al={"drowned city","ruínas gurubashi submersas","ruínas ancestrais"}}},fp="25,179,12.220.0,24.204.0,19.80.0,36.90.0,25.114.0,25.81.0"}
P.entries["quest:97196"] = {n="The Coldbringer's Eye",s="Um servo do Lich King observa tudo pelo Coldbringer’s Eye, em Urzal dos Mortos. Você deve recuperar o orbe para que agentes secretos do Flagelo em Kalimdor possam ser caçados.",h="Um servo do Lich King observa tudo pelo Coldbringer’s Eye, em Urzal dos Mortos.",kw={"amnennar","coldbringer","coldbringer's eye","death's head quilboar","lich king","urzal dos mortos","flagelo","orbe de vidência"},sec={{t="Um orbe no covil",b="Um orbe de vidência permite que Amnennar the Coldbringer observe e comande lacaios em outros lugares. Ele vive nas profundezas de Urzal dos Mortos, covil dos quilboars Death's Head. Você deve recuperar o Coldbringer's Eye, que pode ajudar a caçar agentes secretos do Flagelo em Kalimdor."}},faq={{q="Quem é Amnennar the Coldbringer?",a="Amnennar the Coldbringer é um servo do Lich King que vive em Urzal dos Mortos.",al={"amnennar","quem é coldbringer"}},{q="O que é o Coldbringer's Eye?",a="O Coldbringer's Eye é um orbe de vidência que Amnennar usa para observar e comandar seus lacaios em outros lugares.",al={"coldbringers eye","o orbe do olho"}},{q="Onde está o Coldbringer's Eye?",a="O Coldbringer's Eye fica em Urzal dos Mortos, no covil de Amnennar the Coldbringer.",al={"onde fica o olho","orbe em urzal dos mortos"}},{q="Por que querem o orbe?",a="O orbe pode ajudar a caçar agentes secretos do Flagelo em Kalimdor e acabar com a ameaça que representam.",al={"por que obter o olho","agentes do flagelo"}}},fp="21,172,18.262.0,32.84.0,30.97.0,31.79.0,22.94.0"}
P.entries["quest:972"] = {n="Sapta da Água",s="Sapta da Água é uma tarefa de transição concedida aos jovens xamãs da Horda por Islen Vidente da Água, na costa dos Sertões. Com uma poção ritual em mãos, o xamã é enviado através do Grande Oceano até as terras assoladas da Floresta de Pinhaprata, onde deve enfrentar uma fonte corrompida.",h="Sapta da Água é uma tarefa de transição concedida aos jovens xamãs da Horda por Islen Vidente da Água, na...",kw={"clamor da água","islen vidente da água","teste de xamã","floresta de pinhaprata","sertões","missão de totem","sapta da água"},ang={["class:Shaman"]="A Sapta da Água marca um ponto de virada crítico em seus testes elementais, abrindo seus olhos para o mundo espiritual antes de conceder o comando sobre seu Totem da Água de cura.",["faction:Horde"]="O teste demonstra a unidade transcontinental da Nova Horda, enviando iniciados das planícies ensolaradas de Kalimdor para os bosques assombrados de Lordaeron."},sec={{t="Uma Visão da Água",b="Nas tradições elementais dos xamãs da Horda, uma sapta é uma poção alquímica criada para sintonizar os sentidos diretamente com os espíritos do mundo. Enquanto olhos comuns percebem apenas riachos tranquilos ou poças estagnadas, beber uma sapta rompe o véu do plano físico, revelando os seres elementais que habitam a correnteza."},{t="A Estrada para Pinhaprata",b="Tendo demonstrado sua dedicação aos espíritos, o xamã recebe a mistura diretamente de Islen Vidente da Água, uma eremita que vive ao longo da costa desolada ao sul de Vila Catraca. Em vez de testar a sapta nos vales áridos de Kalimdor, Islen ordena que o iniciado viaje para longe, através do Grande Oceano, até os bosques sombrios e abandonados da Floresta de Pinhaprata para confrontar uma corrupção elemental que envenena os riachos de Lordaeron."}},faq={{q="O que é uma sapta da água?",a="Uma sapta é um elixir cerimonial preparado por mentores xamânicos. Quando consumido, ele aumenta a percepção espiritual, permitindo que quem o bebe veja e se comunique diretamente com espíritos elementais que são invisíveis para olhos mortais.",al={"o que é sapta","significado de sapta da água","o que a sapta faz"}},{q="Quem é Islen Vidente da Água?",a="Islen Vidente da Água é uma xamã mestre que vive em contemplação solitária ao longo da costa leste dos Sertões, ao sul da Costa dos Mercadores. Ela guia jovens xamãs da Horda ao longo do árduo caminho para comungar e vincular o elemento da água.",al={"história de islen vidente da água","quem é islen"}},{q="Por que o xamã deve viajar para a Floresta de Pinhaprata?",a="Os espíritos elementais da água estão sofrendo com uma aflição generalizada na Floresta de Pinhaprata. Para completar sua iniciação, o xamã deve levar a sapta através do oceano para contemplar uma fonte de água corrompida em primeira mão e purificar a mácula.",al={"por que pinha prata","por que ir para os reinos do leste"}},{q="O que acontece depois de beber a sapta?",a="Consumir a Sapta da Água permite ao xamã testemunhar os elementais da água corrompidos que espreitam nas poças contaminadas de Pinhaprata, abrindo o caminho para confrontar a fonte da decadência.",al={"beber sapta","efeito da sapta"}},{q="Este teste é necessário para todos os xamãs da Horda?",a="Sim. Xamãs orcs, taurens e trolls devem igualmente atender ao Clamor da Água, recebendo esta sapta como um rito de passagem essencial antes de poderem ganhar seu Totem da Água.",al={"quem faz esta missão","isso é missão de classe"}},{q="Onde na Floresta de Pinhaprata está localizada a poça corrompida?",a="A fonte corrompida fica na costa da Floresta de Pinhaprata, a oeste do Sepulcro.",al={"localização da poça em pinha prata","onde fica a poça de água"}}},fx={c8d11240={q="Por que Islen Vidente da Água envia você para a Floresta de Pinhaprata?",a="Islen Vidente da Água busca guiá-lo através de seu rito de passagem espiritual, ajudando você a sintonizar-se com as forças elementais da água. Para ganhar a comunhão com os espíritos da água e completar o Clamor da Água, você deve enfrentar e limpar a mancha que assola os cursos d'água do mundo. Ela confiou a você um sapta de água preparado para que você possa perceber a corrupção elemental oculta em primeira mão e provar sua devoção como um xamã em ascensão.",al={"por que islen quer que isso seja feito","motivo de islen vidente da água","por que limpar a água corrompida"}}},fp="11,195,17.259.0,22.331.0,22.160.0,23.207.0,48.216.0,38.157.0,44.138.0,50.78.0"}
P.entries["quest:97205"] = {n="Learning to Ride",s="Genn Fairweather oferece ensinar você a montar um galestrider por uma taxa. O treinamento prepara você para viajar com uma montaria, e ele fornece uma depois que você aprender.",h="Genn Fairweather oferece ensinar você a montar um galestrider por uma taxa.",kw={"apprentice riding","galestrider","genn fairweather","aprendendo a montar","montaria","treinador de montaria"},sec={{t="Mãos firmes",b="Quando tiver moedas suficientes, Genn Fairweather poderá ensinar a habilidade Apprentice Riding. Ele diz que montar um galestrider exige paciência e mãos firmes. Ele fornece uma montaria depois que você treinar, para que possa partir preparado para o que você e sua montaria talvez enfrentem."}},faq={{q="Quem me ensina a montar um galestrider?",a="Genn Fairweather ensina a habilidade Apprentice Riding para galestriders.",al={"montaria de genn","treinador de galestrider"}},{q="Preciso pagar pelas aulas de montaria?",a="Genn cobra uma taxa e diz para falar com ele quando você tiver moedas suficientes.",al={"custo da montaria","quantas moedas"}},{q="Vou ganhar uma montaria depois do treinamento?",a="Genn fornece uma montaria grátis depois que você treinar com ele.",al={"montaria grátis","montaria após treinamento"}},{q="Também posso montar outras criaturas?",a="Genn diz que muitas criaturas exigem uma habilidade de montaria própria, e você precisará encontrar treinadores para cada uma.",al={"outras montarias","habilidades de montaria diferentes"}},{q="O que é preciso para montar um galestrider?",a="Genn diz que montar um galestrider muitas vezes exige paciência e mãos firmes.",al={"montar galestrider","paciência para montar"}}},fp="16,158,13.259.0,37.74.0,36.73.0,32.67.0,31.101.0,36.70.0"}
P.entries["quest:97220"] = {n="Philmor's Favor",s="Philmor's Favor é uma tarefa de entrega em Ventobravo motivada por uma escassez contínua de estivadores locais. Mensageiros são solicitados a transportar uma remessa delicada destinada à Gatehouse até uma entrada isolada de depósito situada no segundo andar da loja Trias' Cheese, no Distrito Comercial.",h="Philmor's Favor é uma tarefa de entrega em Ventobravo motivada por uma escassez contínua de estivadores...",kw={"elaine","portaria","remessa da portaria","philmor","favor de philmor","ventobravo","distrito comercial","queijo trias"},ang={["faction:Alliance"]="Ajudar com entregas por todo o Distrito Comercial de Ventobravo mantém a logística da cidade fluindo sem problemas enquanto os estivadores continuam em falta."},sec={{t="Logística Sobrecarregada em Ventobravo",b="Uma escassez persistente de estivadores por toda Ventobravo sobrecarregou as operações de frete rotineiras da cidade. Para evitar que os cronogramas locais de carga fiquem atrasados, os encarregados procuram viajantes confiáveis dispostos a transportar caixotes delicados diretamente para o bairro comercial."},{t="Entregas Discretas na Trias' Cheese",b="A remessa está marcada para a Gatehouse, mas sua entrega é tudo menos convencional. Em vez de passar pela entrada principal da guarita, o caixote é levado até o segundo andar da loja Trias' Cheese, no Distrito Comercial. A loja oculta uma entrada de depósito usada para transportar silenciosamente suprimentos e presentes cerimoniais destinados aos oficiais da guarda, longe de olhares curiosos."}},faq={{q="Quem precisa de ajuda com esta entrega?",a="A missão é oferecida para ajudar a desafogar o cronograma de carga em Ventobravo quando as operações locais sofrem com a falta de estivadores.",al={"quem dá o favor de philmor","doador da missão philmor"}},{q="Onde fica o destino da entrega?",a="A remessa deve ser levada até a entrada do depósito da Gatehouse, que é acessada através do segundo andar da loja Trias' Cheese, no Distrito Comercial de Ventobravo.",al={"onde levo o pacote","entrega queijo trias","onde fica a entrada da portaria"}},{q="Quem recebe a remessa?",a="Elaine é a senhora na loja Trias' Cheese acostumada a lidar com remessas discretas de carga destinadas ao depósito adjacente da Gatehouse.",al={"quem é elaine","elaine queijo trias"}},{q="O que há dentro da remessa da Gatehouse?",a="A remessa contém mercadorias delicadas destinadas à Gatehouse. De acordo com encarregados locais, as entregas costumam chegar com discrição especial para facilitar surpresas cerimoniais preparadas para os oficiais da guarda.",al={"o que há no pacote","conteúdo da entrega da portaria"}},{q="Por que um depósito militar é acessado através de uma loja de queijos?",a="O andar superior da loja Trias' Cheese abriga um ponto de acesso ao depósito da Gatehouse, permitindo uma passagem discreta e entregas de carga sem desfile de mercadorias pela entrada militar principal.",al={"por que queijo trias portaria","entrada secreta queijo trias"}},{q="Por que os estivadores estão em falta?",a="A falta de pessoal deixou os manipuladores de carga e das docas com poucos funcionários ao longo da semana, forçando os coordenadores de logística a recorrer a viajantes que passam para manter as entregas no prazo.",al={"por que faltam estivadores","falta de estivadores em ventobravo"}}},fp="15,191,31.219.0,36.281.0,34.99.0,34.121.0,26.99.0,38.147.0,59.142.0,34.141.0"}
P.entries["quest:97222"] = {n="Gatehouse Goods",s="Gatehouse Goods é uma tarefa local de Ventobravo que envolve o transporte de uma remessa escada acima dentro da Trias' Cheese. Como a queijaria compartilha um andar com a guarita adjacente, as mercadorias podem ser deixadas discretamente do lado de fora da porta do depósito para que os guardas as recolham. O arranjo destaca o projeto urbano integrado e compacto dos distritos comercial e defensivo de Ventobravo.",h="Gatehouse Goods é uma tarefa local de Ventobravo que envolve o transporte de uma remessa escada acima dentro...",kw={"entrega","elling trias","gatehouse goods","remessa da guarita","depósito","ventobravo","trias cheese"},ang={["class:Rogue"]="Operar silenciosamente ao redor da Trias' Cheese e atentar-se a detalhes arquitetônicos sutis, como portas que abrem para dentro, é algo natural para quem preza pela discrição.",["faction:Alliance"]="Ajudar a organizar entregas discretas através da Trias' Cheese mantém as mercadorias fluindo sem problemas entre os lojistas locais de Ventobravo e o pessoal da guarita adjacente."},sec={{t="Distritos Compartilhados e Andares Compartilhados",b="Gatehouse Goods envolve uma tarefa de entrega simples em meio às ruas movimentadas de Ventobravo. O trabalho exige transportar uma remessa da guarita pelas escadas internas da Trias' Cheese. Embora a famosa queijaria seja um negócio totalmente distinto com seu próprio inventário separado, sua estrutura física compartilha um andar com as instalações vizinhas da guarita. Essa peculiaridade arquitetônica faz do patamar superior da loja uma passagem prática para transportar suprimentos entre distritos vizinhos sem perturbar as avenidas principais."},{t="Uma Entrega Prática",b="O protocolo de entrega é preciso: os entregadores devem deixar o caixote diretamente do lado de fora da porta do depósito em vez de levá-lo para dentro. Os guardas regulares da guarita ficam atentos ao movimento e destacam pessoal para recolher os pacotes ao retornarem aos seus postos. Além disso, a porta do depósito é deliberadamente construída com dobradiças que abrem para dentro, garantindo que as mercadorias empilhadas do lado de fora nunca bloqueiem a entrada nem impeçam quem está dentro de se movimentar livremente."}},faq={{q="O que é Gatehouse Goods?",a="Gatehouse Goods é uma tarefa de entrega local em Ventobravo que envolve a Trias' Cheese e a guarita adjacente. Um entregador é encarregado de levar uma remessa escada acima e deixá-la do lado de fora da porta do depósito da guarita.",al={"o que é gatehouse goods","missão gatehouse goods"}},{q="Onde a remessa deve ser entregue?",a="A entrega é feita subindo as escadas dentro da loja Trias' Cheese. Embora a Trias' Cheese seja um negócio independente, seu edifício compartilha um andar com a guarita, permitindo entregas diretas bem do lado de fora do depósito deles.",al={"trias cheese guarita","para onde vai a entrega"}},{q="Por que o caixote é deixado do lado de fora da porta em vez de ser levado para dentro?",a="O destinatário instrui especificamente o entregador a deixar o caixote do lado de fora da porta do depósito em vez de levá-lo para dentro. Os guardas da guarita percebem a chegada e enviam alguém em serviço regular de recolhimento para levá-lo para dentro ao retornarem ao posto.",al={"por que não entregar dentro","quem pega o caixote"}},{q="Por que a porta do depósito se abre para dentro?",a="A dobradiça da porta do depósito se abre para dentro especificamente para que pacotes e mercadorias deixados do lado de fora da entrada não bloqueiem a porta nem prendam as pessoas lá dentro.",al={"porta que abre para dentro trias","dobradiça da porta do depósito"}},{q="A Trias' Cheese é afiliada à guarita?",a="Não, a Trias' Cheese não faz parte da guarita e não compartilha estoque de mercadorias. No entanto, os dois estabelecimentos compartilham o andar de um edifício, tornando a escadaria superior um ponto de transferência conveniente.",al={"a trias cheese faz parte da guarita","estoque da trias cheese"}},{q="Quem supervisiona a entrega das mercadorias?",a="A tarefa é organizada por operadores locais que esperam respeito profissional e discrição mútua, reconhecendo entregadores confiáveis assim que a entrega é realizada com sucesso sem obstruir a passagem.",al={"quem dá gatehouse goods","quem aceita a entrega"}}},fp="15,269,33.307.0,20.281.0,24.184.0,47.186.0,65.171.0,40.106.0,47.109.0,39.181.0"}
P.entries["quest:97223"] = {n="Bloodtalon Matriarch",s="A Matriarca Bloodtalon é a formidável líder de um bando de raptores velozes e astutos perto da Aldeia Sen'jin. Após provar ser perigosa e obstinada demais para ser domada quando adulta, ela deve ser enfrentada para que seus filhotes possam ser criados desde o ovo como companheiros leais para a tribo Lançanegra.",h="A Matriarca Bloodtalon é a formidável líder de um bando de raptores velozes e astutos perto da Aldeia Sen'jin.",kw={"garra-de-sangue","lançanegra","matriarca","raptor","ovos de raptor","raptores","aldeia sen'jin","sen'jin","montarias de trolls"},ang={["class:Hunter"]="Os caçadores compreendem a dificuldade de domar feras adultas experientes e a necessidade de criar predadores desde o nascimento para forjar um vínculo verdadeiro.",["faction:Horde"]="Criar predadores locais como aliados leais ajuda a proteger o assentamento dos Lançanegra e fortalece a presença da Horda na costa de Durotar.",["race:Troll"]="Os trolls Lançanegra da Aldeia Sen'jin valorizam os raptores como companheiros ágeis e montarias de guerra, prezando a linhagem Bloodtalon por sua astúcia e rapidez."},sec={{t="A Linhagem Bloodtalon",b="O bando Bloodtalon é famoso ao longo da costa de Durotar por sua velocidade notável e astúcia aguçada. Os tratadores da Aldeia Sen'jin valorizam esses traços acima de tudo ao buscar montarias confiáveis e companheiros para a tribo Lançanegra. No entanto, raptores adultos possuem instintos obstinados e violentos, tornando-os quase impossíveis de domesticar depois de adaptados à vida selvagem."},{t="Preservando a Linhagem",b="Apesar de várias tentativas de capturar e treinar a Matriarca diretamente, sua agressividade crescente a transformou em uma ameaça direta ao território ao redor. Para proteger a tribo e garantir que sua linhagem excepcional não fosse perdida, os trolls decidiram subjugar a mãe perigosa e resgatar sua ninhada, assegurando que a próxima geração possa ser criada desde o ovo como aliados leais."}},faq={{q="Quem é a Matriarca Bloodtalon?",a="A Matriarca Bloodtalon é uma raptor feroz e adulta cujo bando é famoso pela velocidade e astúcia. Embora esforços anteriores tenham sido feitos para capturá-la e treiná-la, ela acabou se tornando perigosa demais para lidar, levando os trolls Lançanegra a proteger seus ovos em vez disso.",al={"quem é a matriarca garra-de-sangue","matriarca raptor garra-de-sangue","matriarca raptor"}},{q="Por que a Matriarca Bloodtalon deve ser enfrentada?",a="Raptores adultos são notoriamente difíceis de domar, e a Matriarca se tornou um perigo grande demais para o assentamento local. Ao subjugá-la e recolher sua ninhada, os tratadores na Aldeia Sen'jin podem neutralizar o perigo enquanto preservam sua linhagem.",al={"por que matar a matriarca","por que capturar ovos","por que caçar a matriarca"}},{q="Por que não domar a Matriarca em vez disso?",a="Raptores adultos possuem instintos ferozes e indomáveis que tornam seu treinamento quase impossível depois de crescidos. Os tratadores obtêm muito mais sucesso pegando ovos e criando os filhotes diretamente ao lado de seus futuros companheiros.",al={"é possível domar raptores adultos","treinar raptor adulto"}},{q="O que acontecerá com a prole da Matriarca?",a="A ninhada capturada é levada de volta à Aldeia Sen'jin para ser incubada e criada. Os trolls pretendem treinar os jovens raptores desde a infância para que se tornem aliados e montarias confiáveis para a tribo.",al={"o que acontece com os ovos","filhotes da matriarca","raptores em sen'jin"}},{q="Onde se concentra esta missão?",a="A missão se concentra ao redor da Aldeia Sen'jin, o refúgio litorâneo dos trolls Lançanegra no sul de Durotar, onde tratadores trabalham para reproduzir e criar raptores leais para seu povo.",al={"onde esta missão é entregue","missão dos raptores da aldeia sen'jin"}},{q="O que torna o bando Bloodtalon especial?",a="Os raptores Bloodtalon são valorizados especificamente por sua rapidez e inteligência. Essas características tornam sua linhagem excepcionalmente desejável como companheiros e montarias, desde que sejam treinados antes que seus instintos selvagens assumam o controle.",al={"características dos raptores garra-de-sangue","por que raptores garra-de-sangue"}}},fp="20,247,22.284.0,24.325.0,32.216.0,48.223.0,35.154.0,46.178.0,29.131.0,39.156.0"}
P.entries["quest:97225"] = {n="Forgotten Loa Idols",s="Forgotten Loa Idols gira em torno da recuperação de efígies religiosas sagradas para os trolls Lançanegra. Essas relíquias perdidas são necessárias com urgência para retomar cerimônias espirituais vitais e preservar o duradouro laço de reverência da tribo com seus espíritos selvagens patronos.",h="Forgotten Loa Idols gira em torno da recuperação de efígies religiosas sagradas para os trolls Lançanegra.",kw={"lançanegra","ídolos dos orixás esquecidos","ídolos","orixás","reverência","rituais","espíritos","troll"},ang={["class:Priest"]="Sacerdotes e médicos-bruxos trolls dependem diretamente de rituais e itens sagrados ancestrais para canalizar poder espiritual e honrar os loas.",["class:Shaman"]="Embora as práticas xamânicas invoquem forças elementais, os espiritualistas trolls têm profunda reverência pelos deuses selvagens e loas ancestrais ligados à sobrevivência de sua tribo.",["faction:Horde"]="Os Lançanegra são membros fundamentais da Horda, e ajudar seus santos anciãos na preservação de artefatos religiosos vitais fortalece a unidade tribal dentro da facção.",["race:Troll"]="Para os trolls Lançanegra, a comunhão com os loas é central para a vida espiritual. Recuperar ídolos perdidos garante que rituais vitais possam continuar e que a tribo permaneça nas boas graças dos espíritos."},sec={{t="Vestígios Sagrados dos Loas",b="Para os trolls Lançanegra, o equilíbrio espiritual está inextricavelmente ligado à sua conexão com os loas — os espíritos animais primitivos e deuses selvagens de sua herança ancestral. Forgotten Loa Idols envolve recuperar relíquias religiosas deslocadas, essenciais para a realização de cerimônias tribais. Sem esses objetos sagrados, os líderes espirituais não podem realizar os ritos necessários para manter a harmonia com seus guardiões divinos."},{t="O Laço dos Lançanegra",b="Enquanto diversas facções hostis de trolls por toda Azeroth praticam sacrifícios de sangue ou buscam subjugar espíritos à força, os Lançanegra se orgulham de manter um laço de respeito mútuo e humilde reverência. Para os Lançanegra, perder o favor de seus patronos é uma grave catástrofe, tornando a restauração desses ídolos perdidos um ato vital de preservação tribal."}},faq={{q="Qual é o propósito de Forgotten Loa Idols?",a="Forgotten Loa Idols é uma tarefa realizada para os trolls Lançanegra a fim de recuperar efígies sagradas desaparecidas. Os ídolos são necessários para retomar rituais tribais cruciais e manter a honra perante seus reverenciados espíritos selvagens.",al={"ídolos dos orixás esquecidos","o que é esta missão","o que é ídolos dos orixás esquecidos"}},{q="O que são loas?",a="Os loas são espíritos primitivos antigos e poderosos e divindades animais reverenciadas pelos trolls. A cultura dos trolls os homenageia por meio de oferendas, preces e cerimônias rituais em troca de proteção, favor e orientação espiritual.",al={"o que são os orixás","deuses dos trolls","quem são os orixás"}},{q="Como os Lançanegra veem seus loas em comparação com outras tribos de trolls?",a="Ao contrário de tribos de trolls mais brutais que tentam subordinar divindades sombrias ou fazer sacrifícios a elas, os Lançanegra veem seu parentesco com os loas como uma relação de profunda reverência, respeito mútuo e dever espiritual. Eles acreditam que sua sobrevivência depende de permanecer no favor dos espíritos.",al={"relação dos lançanegra com os orixás","por que reverenciar os orixás","orixás de outras tribos"}},{q="Por que os ídolos são necessários para rituais tribais?",a="Os ídolos servem como focos consagrados para rituais tribais. Sem eles, os anciãos e líderes espirituais não podem realizar adequadamente os ritos necessários para comungar com seus espíritos patronos e honrá-los.",al={"por que precisa dos ídolos","propósito dos ídolos dos orixás","por que os ídolos são importantes"}},{q="Por que manter o favor dos loas é tão vital para os Lançanegra?",a="Os anciãos Lançanegra temem que, sem os ritos e oferendas adequados, sua tribo possa perder o favor e as bênçãos protetoras dos loas, deixando a tribo vulnerável em um mundo que já é perigoso.",al={"o que acontece se não forem devolvidos","cair em desgraça","favor dos orixás para os lançanegra"}},{q="Quem busca o retorno de Forgotten Loa Idols?",a="A missão é concedida por um guia espiritual troll Lançanegra que está ansioso para retomar cerimônias comunitárias e assegurar as bênçãos dos patronos ancestrais da tribo.",al={"quem dá ídolos dos orixás esquecidos","concedente da missão","quem pede os ídolos"}}},fp="19,142,26.307.0,18.305.0,43.117.0,13.198.0,67.163.0,44.157.0,57.159.0,48.157.0"}
P.entries["quest:97234"] = {n="Reading Room",s="Reading Room gira em torno de uma troca entre o Roy's Book Club e a Stormwind library. Aventureiros ajudam o clube levando um pacote embrulhado de literatura mais antiga até a biblioteca a fim de obter textos modernos para as discussões dos membros.",h="Reading Room gira em torno de uma troca entre o Roy's Book Club e a Stormwind library.",kw={"livros","lendas","bibliotecária","reading room","clube do livro do roy","stormwind library","tomos"},ang={["faction:Alliance"]="Viajantes da Aliança frequentemente visitam a Royal Library dentro da Bastilha Ventobravo, onde trocas cívicas e acadêmicas mantêm a vida intelectual da cidade."},sec={{t="Buscas Literárias em Ventobravo",b="Na movimentada capital de Ventobravo, amantes da literatura se reúnem sob a bandeira do Roy's Book Club para dissecar lendas clássicas e debater obras provocantes. O clube mantém seus debates empolgantes alternando os textos, trocando obras mais antigas ou menos populares por volumes mais recentes e envolventes do vasto repositório da cidade."},{t="A Troca da Biblioteca",b="Para manter sua lista de leituras atualizada, o clube conta com um acordo de empréstimo firmado com a Stormwind library. Roy empacota os volumes devolvidos pelo clube usando uma técnica de embrulho característica, permitindo que aventureiros entreguem os pacotes diretamente ao bibliotecário em troca de uma nova lista de tomos modernos."}},faq={{q="O que é a missão Reading Room?",a="Reading Room é uma tarefa que envolve o Roy's Book Club, uma reunião de leitores que debatem lendas consagradas e literatura. A missão pede a um aventureiro que leve um pacote embrulhado de obras menos populares até a Stormwind library para trocá-las por tomos mais modernos.",al={"missão reading room","o que é reading room","história de reading room"}},{q="Quem é Roy?",a="Roy comanda um ativo clube de leitura onde os membros se reúnem para debater os significados mais profundos de lendas consagradas e da literatura. Ele mantém um arranjo com a Stormwind library para renovar o material de leitura, devolvendo tomos emprestados em perfeito estado.",al={"quem é roy","clube do livro do roy","líder do clube do livro"}},{q="Para onde os livros estão sendo levados?",a="O material de leitura embrulhado é entregue diretamente à biblioteca em Ventobravo. A bibliotecária local reconhece a técnica de embrulho distinta usada pelo clube de Roy e aceita prontamente a troca por textos modernos recém-chegados.",al={"para onde vão os livros","entrega na stormwind library","entrega de material de leitura embrulhado"}},{q="Por que os livros estão sendo trocados?",a="O clube está substituindo parte de sua literatura menos popular por textos mais modernos e instigantes, recorrendo a um acordo de empréstimo já estabelecido com a biblioteca da cidade.",al={"por que trocar livros","por que devolver tomos","trocar material de leitura"}},{q="Como a bibliotecária de Ventobravo vê o clube do livro?",a="A bibliotecária de Ventobravo fica muito satisfeita com o acordo, observando que o clube de Roy sempre devolve os materiais emprestados em excelentes condições e trata todos os textos com cuidado, por mais provocante que seja o tema abordado.",al={"o que a bibliotecária acha","o clube do livro é permitido","acordo com a biblioteca"}},{q="Quais são os lanches do clube mencionados?",a="O clube oferece lanches de cortesia aos frequentadores e ajudantes que colaboram com o transporte de suas trocas de livros entre o local de leitura e os arquivos da cidade.",al={"lanches de cortesia do clube","vantagens do clube","quais lanches"}}},fp="12,163,30.238.0,20.236.0,31.161.0,11.185.0,32.154.0,34.135.0,52.182.0,41.136.0"}
P.entries["quest:97236"] = {n="Fang of Githyiss",s="A Fang of Githyiss é um espécime raro e formidável retirado de um aracnídeo gigante que espreita as florestas próximas a Aldrassil. Entregar a presa a um naturalista no santuário permite que os estudiosos examinem a criatura monstruosa e monitorem as ameaças predatórias que fazem ninhos em Umbravale.",h="A Fang of Githyiss é um espécime raro e formidável retirado de um aracnídeo gigante que espreita as florestas...",kw={"aldrassil","fang of githyiss","githyiss","umbravale","aranha","estudo de aranhas","teldrassil"},ang={["class:Druid"]="Os druidas vigiam atentamente o equilíbrio natural em Teldrassil, estudando predadores incomuns e aracnídeos gigantescos para monitorar a saúde das florestas ao redor.",["faction:Alliance"]="O estudo da fauna perigosa por toda Teldrassil ajuda a Aliança, garantindo que novos recrutas e pesquisadores compreendam as ameaças corruptoras que se aninham perto de Aldrassil.",["race:NightElf"]="Como defensores de Teldrassil, jovens aventureiros elfos noturnos em Umbravale ajudam a proteger os galhos de Aldrassil, eliminando monstruosidades perigosas e auxiliando os pesquisadores locais."},sec={{t="Um Espécime Monstruoso",b="A Fang of Githyiss é um troféu e uma amostra biológica colhida da aranha gigante Githyiss, que espreita nas selvas de Umbravale. Uma fera de porte tão notável representa uma ameaça clara para os jovens viajantes que se aventuram a partir de Aldrassil, tornando a recuperação de sua presa tanto uma questão de segurança quanto de interesse científico. Em vez de deixar os restos da criatura apodrecerem na vegetação rasteira, batedores engenhosos levam o espécime de volta ao santuário da grande árvore."},{t="Pesquisa em Aldrassil",b="Em Aldrassil, naturalistas e estudiosos elfos noturnos acompanham de perto a vida selvagem que vagueia pelo chão da floresta. Apresentar uma presa fresca e intacta de uma criatura da magnitude de Githyiss fornece informações cruciais sobre as populações de aracnídeos que prosperam sob a copa de Teldrassil. Os pesquisadores locais acolhem tais descobertas inesperadas, utilizando a enorme presa para aprofundar seus estudos contínuos sobre a fauna agressiva da clareira."}},faq={{q="O que é a Fang of Githyiss?",a="A Fang of Githyiss é um espécime fresco retirado da grande aranha Githyiss. Recuperar uma presa tão colossal fornece material de pesquisa raro sobre os predadores aracnídeos que habitam as florestas ao redor de Aldrassil.",al={"o que é fang of githyiss","missão fang of githyiss","item fang of githyiss"}},{q="Quem ou o que é Githyiss?",a="Githyiss é uma aranha notavelmente grande e perigosa que ronda as florestas perto de Aldrassil, em Umbravale. Seu tamanho faz dela uma ameaça para os viajantes e um tema intrigante para os naturalistas locais.",al={"quem é githyiss","aranha githyiss","onde fica githyiss"}},{q="Quem quer a Fang of Githyiss?",a="A presa é levada a um estudioso em Aldrassil especializado no estudo de aranhas. Tais pesquisadores recebem espécimes frescos de bom grado para aprimorar sua compreensão sobre a biologia dos aracnídeos locais.",al={"quem entrega fang of githyiss","onde levo a presa","pesquisador de aranhas aldrassil"}},{q="Onde fica Aldrassil?",a="Aldrassil é o grande ramo e santuário central de Umbravale, localizado na copa da árvore do mundo Teldrassil. Ele serve como área de treinamento e refúgio para jovens elfos noturnos.",al={"onde fica aldrassil","localização de aldrassil"}},{q="Por que os estudiosos em Aldrassil estão estudando presas de aranha?",a="Estudiosos e naturalistas em Aldrassil estudam aracnídeos locais para compreender melhor a ecologia de Umbravale e monitorar as feras agressivas e gigantescas que habitam sob a copa de Teldrassil.",al={"por que estudam aranhas em aldrassil","por que estudar presas de aranha"}},{q="Jogadores da Horda podem entregar a Fang of Githyiss?",a="Não. A missão se passa em Umbravale, o enclave inicial dos Elfos Noturnos no topo de Teldrassil, tornando-a acessível apenas a aventureiros da Aliança que começam sua jornada em Aldrassil.",al={"esta missão é apenas da aliança","a horda pode fazer fang of githyiss"}}},fp="16,158,20.218.0,21.285.0,29.145.0,24.165.0,31.125.0,19.157.0,52.169.0,47.133.0"}
P.entries["quest:97237"] = {n="Shelf Picked",s="Em Ventobravo, Roy Lewells envia um mensageiro para buscar livros para um grupo de leitura no Parque.",h="Em Ventobravo, Roy Lewells envia um mensageiro para buscar livros para um grupo de leitura no Parque.",kw={"clube do livro","mensageiro","library","park","roy lewells","shelf picked","ventobravo"},ang={["faction:Alliance"]="Levar livros entre as bibliotecas de Ventobravo e os locais de encontro da cidade faz parte do cotidiano na capital, mesmo em meio às tensões maiores no reino."},sec={{t="Uma Incumbência para as Estantes",b="Roy Lewells enviou um bilhete pedindo vários livros da biblioteca de Ventobravo. A bibliotecária confere a lista e confirma que todos os títulos estão disponíveis. Os livros estão nas estantes para você encontrá-los e retirá-los. A bibliotecária permanece no balcão para manter os registros do acervo."},{t="O Clube de Leitura do Porão",b="O bilhete de Roy Lewells faz de você um mensageiro oficial, então você não é responsável por devolver os livros emprestados. Essa obrigação cabe ao estabelecimento de Lewells. Quando você leva os volumes ao Parque, Roy os prepara para animadas discussões após o expediente em um porão. Os livros têm um cheiro exótico."}},faq={{q="Quem dá a missão Shelf Picked?",a="Uma bibliotecária responsável pela biblioteca de Ventobravo lhe passa a tarefa após receber o bilhete de Roy Lewells. Ela confirma que os livros solicitados estão disponíveis e pede que você os retire das estantes.",al={"quem dá shelf picked","dador da missão shelf picked","onde começa shelf picked"}},{q="Quem é Roy Lewells?",a="Roy Lewells organiza um grupo de leitura local que se reúne no Parque de Ventobravo. Ele envia mensageiros para buscar livros na biblioteca para as discussões após o expediente do grupo em um porão.",al={"quem é roy lewells","roy lewells park","quem é lewells"}},{q="Onde ocorre a coleta dos livros?",a="Os livros são retirados em uma biblioteca de Ventobravo. A bibliotecária mantém os registros do acervo enquanto você procura nas estantes os títulos pedidos por Roy Lewells.",al={"que biblioteca é esta","onde os livros são pegos","qual biblioteca shelf picked"}},{q="Por que Roy Lewells precisa desses livros?",a="Roy Lewells precisa dos livros para um clube do livro informal, cujos membros se reúnem para animadas discussões após o expediente em um porão.",al={"por que pegar livros para lewells","o que é o clube do livro de lewells","clube do livro no porão após o expediente"}},{q="Você é responsável por devolver os livros emprestados?",a="Não. Com o bilhete de Roy Lewells, você atua como mensageiro oficial. O estabelecimento dele é responsável por devolver os livros emprestados.",al={"sou responsável pela devolução dos livros","quem devolve os livros de shelf picked","responsabilidade pela devolução de livros da biblioteca"}},{q="Para onde você leva os livros após recuperá-los?",a="Você leva os livros recolhidos para Roy Lewells, no Parque de Ventobravo.",al={"onde você entrega shelf picked","onde encontrar roy lewells","entrega de shelf picked"}}},fp="12,89,24.274.0,23.294.0,33.201.0,19.175.0,42.154.0,38.122.0,53.127.0,44.65.0"}
P.entries["quest:97242"] = {n="Yelmak's Medley",s="Yelmak's Medley é uma missão de Orgrimmar focada em aliviar tensões dentro da Yelmak's Alchemy and Potions no Vale da Honra. O mestre alquimista Yelmak busca conter o desajeito destrutivo e o orgulho teimoso de seu aprendiz Whuut preparando uma mistura caseira suavizante feita a partir de plantas aquáticas locais.",h="Yelmak's Medley é uma missão de Orgrimmar focada em aliviar tensões dentro da Yelmak's Alchemy and Potions no...",kw={"alquimia","taboa","kor'geld","orgrimmar","capim-lança","vale da honra","whuut","yelmak","yelmak's medley"},ang={["faction:Horde"]="Esta tarefa ocorre diretamente dentro do Vale da Honra de Orgrimmar, ajudando a manter a ordem e a acalmar ânimos exaltados dentro do comércio alquímico da capital.",["profession:Herbalism"]="Coletar taboas frescas e capim-lança ao longo dos cursos d'água da cidade destaca como a flora local bem no interior de Orgrimmar pode ser usada para poções e infusões de ervas."},sec={{t="Problemas no Laboratório",b="Dentro da Yelmak's Alchemy and Potions no Vale da Honra de Orgrimmar, a vida é complicada pelo orgulho obstinado do jovem aprendiz da loja, Whuut. Em vez de pedir ajuda ou admitir que está além de sua capacidade, o misturador novato passou a quebrar equipamentos da loja em frustração. Para conter os danos e acalmar o temperamento volátil do jovem sem ferir seu ego frágil, o mestre alquimista Yelmak bola uma mistura caseira calmante."},{t="Flora Local Suavizante",b="A receita requer uma colheita fresca de mudas selvagens de taboas e capim-lança que prosperam ao longo dos cursos d'água sinuosos pelo Vale da Honra. Kor'geld não pode se afastar da loja sem alertar o aprendiz desconfiado, exigindo um terceiro discreto para coletar as plantas ribeirinhas. Uma vez reunida, a mistura botânica é preparada para sutilmente controlar a atitude de Whuut e restaurar a paz na loja de alquimia."}},faq={{q="Quem oferece a missão Yelmak's Medley?",a="Kor'geld, localizado na Yelmak's Alchemy and Potions no Vale da Honra de Orgrimmar, oferece a tarefa em nome do mestre alquimista da loja.",al={"quem dá yelmaks medley","quem oferece a missão yelmak medley"}},{q="Quem é Whuut?",a="Whuut é um aprendiz de misturador treinando sob a tutela de Yelmak no Vale da Honra. Conhecido por seu orgulho teimoso, ele tem quebrado equipamentos em vez de admitir que precisa de orientação ou assistência.",al={"quem é whuut","aprendiz de yelmak","whuut orgrimmar"}},{q="Qual é o propósito da mistura caseira?",a="É uma mistura especial caseira preparada pelo mestre alquimista Yelmak usando mudas frescas de taboa e capim-lança para acalmar ou abrandar sutilmente o mau humor de seu orgulhoso aprendiz.",al={"qual é a receita de yelmak's medley","o que yelmak quer preparar"}},{q="Onde os ingredientes são coletados?",a="As taboas selvagens e o capim-lança crescem diretamente ao longo dos riachos de água doce e lagos que fluem pelo Vale da Honra em Orgrimmar.",al={"onde encontrar taboas e capim-lança","mudas do vale da honra"}},{q="Por que Kor'geld não colhe as mudas pessoalmente?",a="Kor'geld não pode sair da Yelmak's Alchemy and Potions porque Whuut perceberia imediatamente que os funcionários da loja estavam secretamente se desdobrando para acomodar seu temperamento difícil.",al={"por que korgeld precisa de ajuda","por que korgeld não pode colher plantas"}},{q="Onde fica a Yelmak's Alchemy and Potions?",a="A Yelmak's Alchemy and Potions fica situada no Vale da Honra, um distrito a leste da capital da Horda, Orgrimmar, conhecido por seus cursos d'água, quartéis de guerreiros e lojas de artesãos.",al={"onde fica yelmak alchemy and potions","localização da loja de yelmak"}}},fp="15,228,25.302.0,20.325.0,37.142.0,13.167.0,46.140.0,35.117.0,52.131.0,46.149.0"}
P.entries["quest:97243"] = {n="Call of Fire",s="Call of Fire envia um iniciado através dos ventos da Muralha Celeste para procurar Olariaan Swiftburn, um Moldavento shen'dorei sintonizado com o elemento do fogo. Ao levar a Torch of Dormant Flame ao Shrine of Flames nos Baixios dos Lufopomos, o viajante começa a aprender a atender ao chamado da chama mesmo dentro do domínio do ar.",h="Call of Fire envia um iniciado através dos ventos da Muralha Celeste para procurar Olariaan Swiftburn, um...",kw={"call of fire","plano elemental","baixios dos lufopomos","olariaan swiftburn","shen'dorei","shrine of flames","muralha celeste","torch of dormant flame","valanaar","moldavento"},ang={["class:Shaman"]="Atender ao chamado dos elementos é fundamental para o treinamento xamânico e, mesmo na Muralha Celeste, comungar com o fogo exige orientação dedicada e reverência ancestral.",["race:Skyborne"]="Embora nativos dos ventos da Muralha Celeste, viajantes Skyborne e Moldavento reconhecem que o equilíbrio exige reconhecer todos os quatro elementos primordiais."},sec={{t="Vozes Através do Plano Elemental",b="Mesmo dentro da Muralha Celeste, o domínio governado pelos elementais do ar, as correntes mais amplas do Plano Elemental permanecem conectadas. Os espíritos da terra, da água e do fogo ainda falam com aqueles que têm a sensibilidade para ouvi-los. Os Moldavento contam entre seus membros indivíduos unicamente receptivos a essas outras forças, incluindo Olariaan Swiftburn, um shen'dorei que desenvolve uma profunda sintonização com o elemento do fogo."},{t="O Shrine of Flames",b="Os iniciados são incumbidos com a Torch of Dormant Flame e direcionados aos Baixios dos Lufopomos. Bem longe ao longo da borda da ilha, aninhado a oeste de Valanaar, fica o Shrine of Flames. Lá, Olariaan Swiftburn recebe a chama dormente, oferecendo-se para instruir estudantes aspirantes a atender ao exigente chamado do fogo em meio às correntes agitadas do reino do ar."}},faq={{q="Quem é Olariaan Swiftburn?",a="Olariaan Swiftburn é um membro shen'dorei dos Moldavento que possui uma sintonização inata com o fogo. Ele reside no Shrine of Flames, situado ao longo da borda dos Baixios dos Lufopomos, a oeste de Valanaar.",al={"quem dá call of fire","para quem levo a tocha","olariaan swiftburn"}},{q="Onde fica o Shrine of Flames?",a="O Shrine of Flames está localizado nos Baixios dos Lufopomos, dentro da Muralha Celeste. Ele fica isolado ao longo da borda da extensão da ilha flutuante, diretamente a oeste de Valanaar.",al={"onde fica shrine of flames","localização dos baixios dos lufopomos","como encontrar olariaan"}},{q="Por que o fogo está sendo estudado na Muralha Celeste?",a="Embora a Muralha Celeste seja predominantemente o domínio elemental do ar, ela permanece como parte integrante do Plano Elemental mais amplo. Os espíritos de todos os quatro elementos ainda ressoam por toda a sua extensão para aqueles sintonizados o suficiente para ouvir.",al={"por que fogo na muralha celeste","plano elemental fogo","a muralha celeste não é só ar"}},{q="O que é a Torch of Dormant Flame?",a="A Torch of Dormant Flame é um foco elemental levado a Olariaan Swiftburn, servindo como canal para um iniciado que busca instrução em comunhão com o fogo.",al={"o que é a chama dormente","torch of dormant flame","qual item eu carrego"}},{q="Quem são os Moldavento?",a="Os Moldavento são praticantes dentro da Muralha Celeste que navegam e moldam forças elementais, contando em suas fileiras indivíduos de origens variadas, como os shen'dorei.",al={"quem são os moldavento","facção dos moldavento"}},{q="A que esta missão leva?",a="Olariaan Swiftburn instrui discípulos sobre como atender ao chamado do fogo, enfatizando que dominar as forças primordiais dentro do exigente domínio da Muralha Celeste exige grande perseverança.",al={"o que olariaan ensina","treinamento de fogo muralha celeste"}}},fp="12,133,33.297.0,20.312.0,26.163.0,30.145.0,37.152.0,35.145.0,24.146.0,29.142.0"}
P.entries["quest:97244"] = {n="Call of Fire",s="Call of Fire é uma missão dos Moldavento que ordena a execução do Skypriest Faladiel, um antigo irmão que traiu sua ordem em troca de poder. Os aventureiros devem rastrear o skypriest ladino até os Baixios dos Lufopomos e recuperar seu coração para alimentar um poderoso ritual elemental.",h="Call of Fire é uma missão dos Moldavento que ordena a execução do Skypriest Faladiel, um antigo irmão que...",kw={"al'aketh","call of fire","faladiel","coração de faladiel","baixios dos lufopomos","santuário de akir","skypriest faladiel","valanaar","moldavento"},ang={["class:Priest"]="Sacerdotes podem achar notável a corrupção e a queda em desgraça do Skypriest Faladiel, já que seu sagrado chamado foi distorcido da invocação da chama para a traição e o assassinato de sua própria ordem.",["class:Shaman"]="Xamãs sintonizados com o fogo e com ritos elementais reconhecerão a natureza severa e primordial de alimentar as chamas com a essência de um traidor para intensificar seu sagrado poder."},sec={{t="Um Traidor Entre a Chama",b="Call of Fire encarrega os aventureiros de caçar o Skypriest Faladiel, um antigo Moldavento que abandonou suas lealdades para se juntar aos Al'Aketh. Outrora um dedicado invocador da chama, Faladiel escolheu o poder em vez da lealdade, voltando-se contra seus companheiros de ordem e manchando suas mãos com o sangue deles. Os Moldavento enviam um agente para aplicar seu julgamento inflexível sobre ele."},{t="Acerto de Contas nos Baixios",b="Faladiel se isolou em uma fazenda nos Baixios dos Lufopomos, situada a nordeste, além de Valanaar, e logo ao sul do Santuário de Akir. Abater o skypriest ladino serve a mais do que mera vingança; os Moldavento precisam de seu coração como um componente macabro para um ritual iminente, acreditando que consumir o coração de um traidor permite que suas chamas sagradas queimem com uma intensidade inigualável."},{t="Sangue Pago com Sangue",b="Ao receber o coração, os Moldavento reafirmam seu credo de que sangue deve responder por sangue. No entanto, a morte de Faladiel marca apenas uma fase de seu trabalho, já que o coração é apenas uma parte do que deve alimentar seu fogo cerimonial antes que seus ritos possam ser concluídos."}},faq={{q="Quem é o Skypriest Faladiel?",a="O Skypriest Faladiel foi outrora um dedicado invocador da chama e um membro valoroso dos Moldavento. Como muitos entre os Al'Aketh, ele negociou suas lealdades em busca de poder, voltando-se contra seus parentes e manchando suas mãos com o sangue deles.",al={"quem é faladiel","história de faladiel","história do skypriest faladiel"}},{q="Por que os Moldavento querem Faladiel morto?",a="Os Moldavento buscam retribuição porque Faladiel os traiu por poder e assassinou seus antigos irmãos e irmãs. Sob o credo dos Moldavento, sangue se paga com sangue, tornando sua execução tanto justiça quanto retribuição.",al={"por que matar faladiel","por que os moldavento querem faladiel morto","traição de faladiel"}},{q="Por que os Moldavento precisam do coração de Faladiel?",a="O coração de Faladiel serve como um potente reagente ritualístico. Os Moldavento acreditam que as chamas devoram avidamente a oferenda do coração de um traidor, tornando-se mais quentes e queimando com muito mais intensidade ao serem alimentadas com ele.",al={"por que o coração de faladiel","para que serve o coração","coração reagente de ritual"}},{q="Onde o Skypriest Faladiel pode ser encontrado?",a="O Skypriest Faladiel refugiou-se em uma fazenda nos Baixios dos Lufopomos, localizada a nordeste, além de Valanaar, logo ao sul do Santuário de Akir.",al={"onde está faladiel","localização do skypriest faladiel","encontrar faladiel"}},{q="Qual é o credo dos Moldavento?",a="Os Moldavento são uma ordem unida por um credo rigoroso e inflexível, onde a traição nunca é esquecida e o sangue é sempre pago com sangue. Eles praticam a invocação da chama e rituais elementais sagrados.",al={"quem são os moldavento","credo dos moldavento","facção dos moldavento"}},{q="Qual é a ligação dos Al'Aketh com esta missão?",a="Os Al'Aketh são uma facção ou grupo conhecido por ter membros que trocaram suas antigas lealdades e honra por poder pessoal, sendo Faladiel um exemplo proeminente entre seus skypriests.",al={"o que são os al'aketh","faladiel al'aketh","traidores dos al'aketh"}}},fp="12,165,25.301.0,25.282.0,21.176.1,26.207.0,44.181.0,45.145.0,38.123.0,37.122.0,50.127.0"}
P.entries["quest:97245"] = {n="Call of Fire",s="Call of Fire é uma missão na qual os aventureiros são encarregados por Olariaan Swiftburn de localizar e confrontar a antiga fada da floresta Kuramaa no Planalto de Shen'dar. Ao invocar a fada de seu toco e derrotá-la com chamas, os viajantes obtêm sua poderosa máscara de madeira. A relíquia é então levada aos Baixios dos Lufopomos para acender uma chama eterna e comungar com os espíritos do fogo.",h="Call of Fire é uma missão na qual os aventureiros são encarregados por Olariaan Swiftburn de localizar e...",kw={"anchor pylon","call of fire","fada da floresta","baixios dos lufopomos","kuramaa","máscara de kuramaa","olariaan swiftburn","planalto de shen'dar"},ang={["class:Mage"]="Kuramaa é extremamente resistente à maioria das disciplinas mágicas, forçando os conjuradores a depender estritamente da magia de fogo para superar a fada.",["class:Shaman"]="Embora compartilhe o nome com os tradicionais testes xamânicos de fogo, este rito concentra-se em subjugar um espírito resiliente do planalto com chamas para reunir poder para a comunhão com espíritos do fogo."},sec={{t="A Fada do Planalto",b="No Planalto de Shen'dar, os moradores locais sussurram contos sobre Kuramaa, uma antiga fada da floresta que habita o interior de um toco de árvore retorcido no cume de uma colina perto do Anchor Pylon regional. Para atrair a entidade reclusa para fora, o desafiante deve golpear a casca de seu lar de madeira com o punho nu, exigindo sua presença e testando sua coragem em combate."},{t="Fogo e Madeira",b="Superar Kuramaa não é tarefa simples para os praticantes do arcano ou do divino, já que a fada possui profundas proteções naturais contra a maioria das formas de magia. Apenas chamas abrasadoras podem perfurar sua casca ancestral e subjugá-la. Derrotar a criatura concede a máscara de madeira de Kuramaa, um artefato imbuído de grande poder. Mesmo assim, Kuramaa é eterno, fadado a se recompor e a se manifestar novamente quando for chamado."},{t="A Chama Eterna",b="Lá embaixo, nos Baixios dos Lufopomos, Olariaan Swiftburn aguarda a recuperação da máscara de Kuramaa. A relíquia de madeira encantada serve como catalisador para uma cerimônia esotérica: acender uma chama eterna para comungar diretamente com os espíritos do fogo, liberando a antiga comunhão elemental por meio da derrota de espíritos da natureza das terras altas."}},faq={{q="Quem é Kuramaa?",a="Kuramaa é uma antiga fada da floresta que habita o Planalto de Shen'dar. Segundo os moradores locais do planalto, ele faz seu lar dentro de um toco de árvore retorcido situado no cume de uma colina perto do Highlands Anchor Pylon.",al={"quem é kuramaa","história de kuramaa","o que é kuramaa"}},{q="Quem é Olariaan Swiftburn?",a="Olariaan Swiftburn é o ritualista que encarrega os aventureiros de confrontar Kuramaa. Localizado nos Baixios dos Lufopomos, Olariaan precisa da máscara de madeira de Kuramaa para realizar um rito sagrado de fogo.",al={"quem dá call of fire","quem é olariaan swiftburn","onde entregar call of fire"}},{q="Como evocar Kuramaa?",a="Kuramaa vive dentro de um toco de árvore retorcido no topo de uma colina perto do Anchor Pylon no Planalto de Shen'dar. Para chamar o espírito para o combate, deve-se bater firmemente com o punho na casca de seu toco.",al={"como evocar kuramaa","onde fica o toco de kuramaa","evocar fada da floresta"}},{q="A que Kuramaa é vulnerável em combate?",a="Kuramaa possui uma resistência natural excepcional à maioria das formas de magia. Apenas o toque das chamas pode superar suas defesas e abater a antiga fada da floresta na batalha.",al={"fraquezas de kuramaa","como derrotar kuramaa","kuramaa imune a magia"}},{q="Por que Olariaan Swiftburn precisa da máscara de Kuramaa?",a="A máscara de madeira de Kuramaa é reconhecida como um receptáculo de poder substancial. Olariaan Swiftburn utiliza esta relíquia potente como um componente essencial para acender uma chama eterna e comungar diretamente com espíritos do fogo.",al={"por que coletar a máscara de kuramaa","o que a máscara faz","propósito da máscara de kuramaa"}},{q="Kuramaa é destruído permanentemente quando derrotado?",a="Kuramaa é um espírito da floresta eterno, em vez de uma criatura mortal. Embora sua manifestação física seja derrotada para que sua máscara seja obtida, o espírito perdura e se manifestará novamente quando necessário.",al={"kuramaa está morto","eu matei kuramaa","história do renascimento de kuramaa"}}},fp="12,243,27.254.0,13.259.0,17.259.1,15.169.0,26.161.0,26.171.0,40.113.0,48.113.0,47.113.0"}
P.entries["quest:97246"] = {n="Meal Appeal",s="Meal Appeal é uma tarefa de Orgrimmar concedida por Thatog, um orc preso às suas obrigações diárias que se preocupa com seu jovem filho Migi pulando refeições para brincar. Os viajantes são solicitados a pegar um almoço preparado em Borstan's Firepit e rastrear Migi brincando atrás de Grommash Hold. Ela oferece um vislumbre autêntico da vida familiar doméstica dentro da capital da Horda.",h="Meal Appeal é uma tarefa de Orgrimmar concedida por Thatog, um orc preso às suas obrigações diárias que se...",kw={"borstan","borstan's firepit","grommash hold","entrega de almoço","meal appeal","migi","orgrimmar","thatog"},ang={["faction:Horde"]="A vida dentro das muralhas de Orgrimmar não se resume apenas a guerras e defesas; questões cotidianas como alimentar crianças correndo pelo Vale da Força mantêm viva a comunidade da cidade.",["race:Orc"]="Mesmo na cultura rigorosa dos orcs, pais como Thatog se preocupam com seus filhos negligenciando refeições para brincar nas ruas da capital de Durotar."},sec={{t="O dever de um pai em Orgrimmar",b="Nas movimentadas avenidas de pedras vermelhas de Orgrimmar, a rotina doméstica diária continua em meio aos treinamentos de guerreiros soldados e às maquinações da Horda. Thatog, preso ao seu posto diário pelo dever, não consegue manter vigilância sobre seu jovem e agitado filho, Migi. Deixado por conta própria, Migi passa do amanhecer ao anoitecer correndo pelas ruas da cidade com seus amigos, negligenciando consistentemente seu estômago até retornar para casa faminto."},{t="Entrega atrás do bastião",b="Em vez de deixar o garoto passar fome mais uma tarde, Thatog providencia uma refeição quente em Borstan's Firepit. Como Migi não para suas brincadeiras para ir buscar o almoço pessoalmente, Thatog pede aos aventureiros que passam por ali para servirem de mensageiros pessoais. A tarefa leva os viajantes do fogo culinário de Borstan ao pátio aberto atrás de Grommash Hold, onde Migi e o restante dos jovens da vizinhança quase sempre podem ser encontrados absortos em suas brincadeiras de infância."}},faq={{q="Quem é Thatog?",a="Thatog é um ocupado pai orc alocado em Orgrimmar, cujas responsabilidades diárias o impedem de se afastar para supervisionar seu jovem filho, Migi. Preocupado com o fato de Migi estar pulando refeições enquanto brinca com os amigos, Thatog recruta um aventureiro disposto para pegar e entregar comida para o garoto.",al={"quem é thatog","thatog doador da missão","thatog orgrimmar"}},{q="Onde Migi pode ser encontrado?",a="Migi passa os dias em brincadeiras com seus amigos na capital. Thatog observa que as crianças quase certamente podem ser encontradas se divertindo e brincando atrás de Grommash Hold em Orgrimmar.",al={"onde está migi","localização de migi","encontrar migi"}},{q="O que é Borstan's Firepit?",a="Borstan administra Borstan's Firepit, um estabelecimento local de alimentação em Orgrimmar. Thatog pede aos viajantes que façam uma parada lá primeiro e informem a Borstan que vieram buscar um almoço combinado com antecedência para entregar pessoalmente a Migi.",al={"onde fica borstan's firepit","localização de borstan's firepit","almoço de borstan"}},{q="Por que Migi se esquece de comer?",a="Como muitos jovens orcs cheios de energia, Migi fica tão absorto brincando o dia todo com seus amigos atrás de Grommash Hold que se esquece ou decide não passar em Borstan's Firepit para comer, frequentemente chegando em casa ao final do dia completamente faminto.",al={"por que migi pula o almoço","migi faminto","por que migi não está comendo"}},{q="Quem é Migi?",a="Migi é o jovem filho de Thatog. Ele percorre Orgrimmar brincando com um grupo de amigos, priorizando a diversão em vez de voltar para casa ou buscar suas refeições preparadas.",al={"quem é migi","migi criança orc","filho de thatog"}},{q="Qual é o objetivo de Meal Appeal?",a="A tarefa exige que você passe em Borstan's Firepit para avisar a Borstan que Thatog o enviou para buscar o almoço de Migi e, em seguida, entregue a comida diretamente a Migi atrás de Grommash Hold para que o menino não passe fome durante as brincadeiras.",al={"objetivo da missão meal appeal","o que fazer em meal appeal","tarefa de meal appeal"}}},fp="11,160,28.244.0,24.234.0,14.203.0,24.115.0,26.132.0,28.130.0,12.137.0,37.121.0"}
P.entries["quest:97249"] = {n="Favorite Food",s="Favorite Food é uma missão de Orgrimmar centrada em Migi, um jovem brincalhão atrás de Grommash Hold cujos pais temem que ele não esteja comendo o suficiente. Para expandir seu paladar sem deixá-lo com fome, Borstan, da Borstan's Meats, prepara um almoço variado temperado com os adorados torresmos glaceados de Migi. A entrega garante que o menino e seus amigos façam uma pausa nas brincadeiras para desfrutar de uma refeição saudável.",h="Favorite Food é uma missão de Orgrimmar centrada em Migi, um jovem brincalhão atrás de Grommash Hold cujos...",kw={"borstan","borstan's meats","favorite food","grommash hold","barriga de porco","almoço","migi","orgrimmar","glacê doce"},ang={["faction:Horde"]="Esta missão oferece um vislumbre da vida doméstica cotidiana em Orgrimmar, mostrando como os comerciantes e as famílias locais garantem que as crianças da capital sejam alimentadas e cuidadas.",["profession:Cooking"]="A tarefa ilustra a habilidade culinária prática na capital da Horda, reaproveitando torresmos crocantes de barriga de porco defumada como um tempero saboroso para as refeições diárias."},sec={{t="Apetite para Brincar",b="Atrás da sede do poder da Horda em Grommash Hold, o jovem Migi e seus amigos passam as tardes brincando pelas trilhas empoeiradas de Orgrimmar. Os pais de Migi, no entanto, temem que o menino frequentemente negligencie suas refeições enquanto brinca e acabe não se alimentando direito. Para garantir que ele receba nutrição regular, recorreram à Borstan's Meats para preparar marmitas diárias. Contudo, seus pais impuseram uma condição rigorosa: Borstan não deve servir exatamente a mesma refeição todos os dias, insistindo para que Migi desenvolva apreço por alimentos variados em vez de depender de um único prato favorito."},{t="O Acordo Glaceado",b="Borstan enfrentou um desafio culinário, pois Migi era notoriamente devoto de sanduíches de barriga de porco caramelizada e só comparecia pontualmente para o almoço quando o defumador estava repleto de seu aroma adocicado. Para atender à exigência de variedade dos pais e, ao mesmo tempo, manter o menino bem alimentado, o açougueiro elaborou uma solução engenhosa. Ao preparar a carne de porco caramelizada, os pedaços crocantes e glaceados restantes são esfarelados em um tempero saboroso que pode ser salpicado sobre qualquer prato. Entregue atrás de Grommash Hold, a cobertura aromática convenceu Migi e seus companheiros a interromperem as brincadeiras e almoçarem juntos."}},faq={{q="Quem é Migi?",a="Migi é um jovem morador de Orgrimmar que passa os dias brincando com amigos atrás de Grommash Hold. Por ficar profundamente absorto em suas brincadeiras, seus pais temem que ele se esqueça de comer o suficiente para encher a barriga, levando-os a organizar entregas diárias de almoço feitas pela Borstan's Meats.",al={"migi orgrimmar","quem é a criança atrás de grommash hold","almoço de migi"}},{q="Quem oferece a missão Favorite Food?",a="A missão é oferecida por Borstan, da Borstan's Meats, em Orgrimmar. Ao tomar conhecimento das preocupações dos pais com a nutrição e os hábitos alimentares de Migi, Borstan prepara uma refeição especial para expandir o paladar do jovem.",al={"quem dá a missão favorite food","quem inicia favorite food","borstan favorite food"}},{q="Onde Migi pode ser encontrado?",a="Migi fica atrás de Grommash Hold em Orgrimmar, onde se reúne com outras crianças locais para brincar. Os jovens passam frequentemente pelo caminho até a fortaleza, reconhecendo os pratos especiais diários de Borstan apenas pelo aroma.",al={"localização de migi","onde está migi","onde entregar o almoço de migi","encontrar migi orgrimmar"}},{q="Qual é a comida favorita de Migi?",a="A comida favorita de Migi é o sanduíche de barriga de porco caramelizada preparado no defumador da Borstan's Meats. Sempre que o defumador está funcionando, é certo que Migi aparecerá prontamente para o almoço, atraído pelo aroma característico que sopra em direção a Grommash Hold.",al={"o que migi gosta de comer","refeição favorita de migi","barriga de porco caramelizada migi"}},{q="Por que os pais de Migi pedem refeições diferentes?",a="Os pais de Migi pediram a Borstan que não preparasse exatamente a mesma refeição todos os dias para que o filho criasse gosto por mais de um prato. Embora queiram que ele coma o suficiente, desejam que ele desenvolva um apetite equilibrado em vez de viver exclusivamente de carne de porco caramelizada.",al={"por que mudar o almoço de migi","pedido dos pais de migi","por que não sanduíches caramelizados todo dia"}},{q="Como Borstan faz Migi comer alimentos diferentes?",a="Borstan esfarela os pedaços crocantes caramelizados que sobram da barriga de porco defumada, transformando-os em uma cobertura que pode ser salpicada sobre diferentes pratos. Esse sabor marcante e familiar de glacê doce permite que Borstan sirva refeições variadas que Migi ainda comerá com prazer até a última mordida.",al={"truque de borstan","como borstan faz migi comer","migalhas caramelizadas"}},{q="O que é a Borstan's Meats?",a="A Borstan's Meats é um defumador e açougue localizado em Orgrimmar, conhecido por defumar sanduíches de barriga de porco e preparar refeições embaladas para os moradores da cidade. Borstan usa seus talentos culinários para manter os jovens da vizinhança bem nutridos.",al={"borstan's meats orgrimmar","onde fica borstan's meats","o que é borstan"}}},fp="13,185,20.349.0,25.403.0,12.215.0,34.147.0,24.188.0,29.167.0,46.167.0,49.153.0,24.171.0"}
P.entries["quest:97250"] = {n="Wrongly Blamed, Justly Corrected",s="Wrongly Blamed, Justly Corrected concentra-se nas crescentes tensões costeiras entre a Horda e a Aliança após a destruição suspeita de uma taverna à beira da estrada. O incidente envia um firme aviso às forças da Aliança, ao mesmo tempo em que deixa perguntas sem resposta sobre quem verdadeiramente ameaçou uma rota comercial civil vital.",h="Wrongly Blamed, Justly Corrected concentra-se nas crescentes tensões costeiras entre a Horda e a Aliança após...",kw={"aviso para a aliança","rota de civis","costa leste","comércio da horda","taverna","conflito territorial","wrongly blamed, justly corrected"},ang={["faction:Alliance"]="O desfecho serve como um severo aviso das forças da Horda contra a crescente presença e provocações da Aliança ao longo da costa leste.",["faction:Horde"]="A missão marca uma vitória notável e uma afirmação defensiva contra as invasões da Aliança, ao mesmo tempo em que levanta preocupações quanto à proteção de rotas comerciais e de civis vitais para a Horda."},sec={{t="Atrito na Costa",b="À medida que o atrito entre a Horda e a Aliança aumenta de forma constante ao longo da costa leste, escaramuças começaram a avançar diretamente para territórios disputados. A destruição de uma taverna local ao longo de uma via importante levou essas tensões ao ápice, ameaçando viagens comuns e a estabilidade regional."},{t="Dúvida e Perturbação",b="Embora as suspeitas inicialmente apontassem para a agressão da Horda, a liderança local duvida que suas próprias forças tenham sido responsáveis pela ruína da taverna. A via serve como uma artéria crítica para civis e mercadores da Horda no transporte de mercadorias, dando à Horda todos os motivos para manter o caminho aberto e motivando pedidos por uma análise mais aprofundada sobre quem realmente a destruiu."},{t="Um Aviso para a Aliança",b="Apesar das persistentes dúvidas em relação à taverna em si, a conclusão do caso representa uma vitória decisiva para as forças da Horda na área. O desfecho serve como um aviso explícito para a Aliança de que qualquer invasão territorial ao longo da costa encontrará resistência imediata."}},faq={{q="Sobre o que é Wrongly Blamed, Justly Corrected?",a="Wrongly Blamed, Justly Corrected é uma tarefa da Horda que envolve o crescente atrito entre facções ao longo da costa leste, após a destruição de uma taverna à beira da estrada em uma rota de viagem vital.",al={"o que é esta missão","história de wrongly blamed justly corrected","o que aconteceu em wrongly blamed"}},{q="A Horda destruiu a taverna?",a="A liderança da Horda permanece bastante cética de que forças da Horda tenham sido responsáveis. Civis demais da Horda dependem dessa rota para o comércio e a passagem cotidiana, tornando sua destruição contraproducente.",al={"a horda destruiu a taverna","quem incendiou a taverna","quem destruiu a taverna"}},{q="Por que a taverna destruída importa para a Horda?",a="A taverna fica ao longo de uma via importante da qual viajantes civis e mercadores dependem fortemente para comércio e deslocamento, tornando sua perturbação uma preocupação estratégica.",al={"por que a rota da taverna é importante","por que a taverna importa"}},{q="O que causou tensões na costa leste?",a="O que causou as tensões inicialmente não está claro. O atrito entre a Horda e a Aliança vem aumentando ao longo da costa leste há algum tempo, com o conflito agora alcançando o território da Horda.",al={"por que lutar na costa leste","conflito na costa leste"}},{q="Que mensagem esse desfecho envia para a Aliança?",a="A ação representa uma vitória tática que envia um severo aviso à Aliança, demonstrando que incursões territoriais contra os interesses da Horda não ficarão sem resposta.",al={"o que a horda conquistou","por que aviso para a aliança"}},{q="Há mais investigações sobre a destruição da taverna?",a="Como as circunstâncias em torno da ruína da taverna continuam suspeitas e a passagem de civis está ameaçada, busca-se uma investigação mais aprofundada para descobrir quem realmente causou a destruição.",al={"o que investigar","a taverna será investigada"}}},fp="32,254,21.212.0,20.248.1,25.211.0,47.160.0,33.171.0,50.162.0,42.162.0,52.105.0,61.139.0"}
P.entries["quest:97253"] = {n="Parts and Pieces",s="Parts and Pieces é uma missão de recuperação oferecida por Wrenix, o Ignóbil na cidade portuária de Vila Catraca. Após vários mercenários falharem em sobreviver a encontros com os piratas locais, Wrenix enviou uma engenhoca mecânica para lidar com a ameaça, apenas para os saqueadores a desmontarem em sucata. Os aventureiros têm a tarefa de ir até o acampamento superior dos piratas para recuperar o maquinário espalhado antes que mais danos sejam causados.",h="Parts and Pieces é uma missão de recuperação oferecida por Wrenix, o Ignóbil na cidade portuária de Vila...",kw={"peças complicadas","máquina","parts and pieces","pirata","piratas","vila catraca","cimitarras","acampamento superior dos piratas","wrenix, o ignóbil"},ang={["profession:Engineering"]="Engenhocas e engenheiros podem apreciar a ironia de uma engenhoca mecânica sofisticada se tornar vítima de pirataria rude. Resgatar as peças complicadas de Wrenix oferece um lembrete em primeira mão dos perigos de enviar protótipos automatizados para acampamentos hostis sem proteções físicas adequadas."},sec={{t="Uma Solução Mecânica",b="A atividade pirata ao longo da costa ao sul de Vila Catraca tornou-se cada vez mais problemática para os moradores e comerciantes do porto. Buscando lidar com os saqueadores sem arriscar mais moedas com capangas descartáveis, o engenhoqueiro Wrenix, o Ignóbil resolveu agir por conta própria. Após enviar cinco ou seis mercenários que não conseguiram retornar vivos, Wrenix bolou o que parecia ser uma alternativa brilhante: enviar uma máquina automatizada para lidar com os saqueadores. Em vez de colocar outra alma viva em risco, o construto mecânico foi enviado para resolver o problema do acampamento de forma autônoma."},{t="Cimitarras e Chaves de Fenda",b="A engenhosa mobilização não correu tão tranquilamente quanto planejado. Os piratas que ocupavam os acampamentos ao sul da cidade revelaram-se surpreendentemente engenhosos com suas lâminas, descobrindo rapidamente que cimitarras curvas podiam servir como chaves de fenda improvisadas. Antes que Wrenix pudesse enviar instruções orientando a máquina a recuar de volta para Vila Catraca, os saqueadores desmontaram o mecanismo e espalharam seus componentes delicados por todo o acampamento superior. Agora, em vez de eliminar a presença pirata, o inventor precisa de um batedor audacioso para entrar furtivamente no acampamento e recolher cinco punhados das peças mecânicas complicadas deixadas na terra."}},faq={{q="Quem é Wrenix, o Ignóbil?",a="Wrenix, o Ignóbil é um engenhoqueiro excêntrico que reside na cidade portuária neutra de Vila Catraca. Enfrentando um bando agressivo de saqueadores ao longo da costa ao sul, Wrenix tentou resolver o problema dos piratas por meio da inovação tecnológica. Depois que vários mercenários contratados não conseguiram sobreviver às suas missões, ele construiu e enviou uma máquina automatizada para lidar com a ameaça, apenas para vê-la ser rapidamente desmontada.",al={"quem é wrenix","história de wrenix, o ignóbil","vila catraca wrenix"}},{q="O que aconteceu com os mercenários que Wrenix contratou anteriormente?",a="Antes de recorrer à automação mecânica, Wrenix contratou cinco ou seis aventureiros diferentes para eliminar a ameaça pirata ao sul de Vila Catraca. Nenhum desses agentes retornou vivo, provando o quão letais e bem defendidos os acampamentos piratas realmente são. Seu fim trágico levou Wrenix a concluir que depender de mercenários de carne e osso era ineficiente e fatal.",al={"mercenários anteriores de wrenix","o que aconteceu com os outros aventureiros","quem wrenix enviou primeiro"}},{q="Por que Wrenix enviou uma máquina para lutar contra os piratas?",a="Wrenix construiu e enviou um dispositivo mecânico porque suas tentativas anteriores com mercenários vivos resultaram em fracasso total e perda de vidas. Acreditando que uma criação de engrenagens poderia ter sucesso onde lutadores mortais tombaram — ou ao menos evitar mais baixas —, ele enviou a máquina diretamente para o acampamento, esperando que a engenhosidade mecânica superasse os piratas.",al={"por que enviar uma máquina","plano do robô de wrenix","por que wrenix usou uma engenhoca"}},{q="Como os piratas desmontaram a máquina de Wrenix?",a="Os piratas se mostraram surpreendentemente inventivos quando confrontados com o construto de Wrenix. Usando suas cimitarras curvas como chaves de fenda improvisadas, os saqueadores rapidamente desmontaram a máquina antes que Wrenix pudesse transmitir comandos redirecionando-a de volta para Vila Catraca. Eles desmontaram a engenhoca até a carcaça e espalharam seus componentes intrincados por todo o acampamento.",al={"como a máquina foi destruída","como os piratas desmontaram o robô","cimitarras como chaves de fenda dos piratas"}},{q="Onde estão localizadas as peças complicadas?",a="Os componentes da máquina estilhaçada de Wrenix estão localizados no acampamento superior dos piratas, situado ao longo da costa ao sul de Vila Catraca. Depois de desmantelar o dispositivo com suas cimitarras, os piratas deixaram suas peças intrincadas espalhadas pelo chão por todo o acampamento no topo da colina. Os aventureiros devem entrar furtivamente no acampamento e coletar cinco punhados dessas peças complicadas.",al={"onde estão as peças","localização do acampamento superior dos piratas","localização das braçadas de peças complicadas"}},{q="Por que Wrenix acredita que esta missão de recuperação é mais segura?",a="Wrenix acredita que esta tarefa oferece chances de sobrevivência muito melhores porque se trata puramente de uma operação de resgate, e não de um ataque direto. Os mercenários anteriores foram instruídos a erradicar a presença dos piratas diretamente, enquanto esta missão de recuperação requer simplesmente entrar furtivamente no acampamento superior, recolher cinco punhados de componentes espalhados da máquina na terra e retornar a Vila Catraca.",al={"parts and pieces é segura","por que wrenix acha que você vai sobreviver","chances de sobrevivência de wrenix"}},{q="Para que são necessárias as Peças Complicadas?",a="As peças complicadas são as engrenagens especializadas, molas e encaixes mecânicos de precisão que moviam o construto automatizado de Wrenix. Como sua tentativa de neutralizar o problema dos piratas terminou com a máquina sendo desmontada, Wrenix precisa que essas peças delicadas sejam recuperadas para que sua valiosa perícia de engenharia e materiais não sejam completamente desperdiçados.",al={"o que são peças complicadas","por que wrenix precisa das peças","o que wrenix faz com as peças"}}},fp="16,217,21.426.0,26.363.0,27.277.0,54.135.0,51.180.0,47.262.0,40.206.0,56.254.0,42.154.0"}
P.entries["quest:97257"] = {n="Call of Fire",s="Call of Fire é um rito de passagem xamânico supervisionado pelos Moldavento dentro da Muralha Celeste. Os iniciados devem ajudar a invocar espíritos das chamas, capturar a Eternal Flame e correr contra o tempo para acender o braseiro em Valanaar. Concluir o teste com sucesso prova o respeito de alguém pelos elementos e concede ao iniciado o seu Totem do Fogo.",h="Call of Fire é um rito de passagem xamânico supervisionado pelos Moldavento dentro da Muralha Celeste.",kw={"call of fire","eternal flame","totem do fogo","firelands","olariaan","muralha celeste","valanaar","moldavento"},ang={["class:Shaman"]="Este rito marca uma iniciação crucial para xamãs, concedendo-lhes domínio sobre o fogo e outorgando-lhes o seu Totem do Fogo após a conclusão.",["race:Skyborne"]="Administrado pelos Moldavento na Muralha Celeste, este teste reflete as tradições xamânicas de Skyborne que honram os planos elementais."},sec={{t="O Ritual das Chamas",b="Call of Fire é um teste sagrado de harmonização elemental realizado dentro da Muralha Celeste. Liderados por Olariaan dos Moldavento, os iniciados se reúnem no Brazier of Offering para invocar os espíritos das chamas das Firelands. Se as oferendas forem consideradas dignas, os espíritos acendem o altar com a sagrada Eternal Flame, pronta para ser aproveitada por um aspirante valoroso."},{t="A Jornada para Valanaar",b="Uma vez acesa, a Eternal Flame deve ser capturada em uma tocha e levada rapidamente pela Muralha Celeste até Valanaar. Como as energias das Firelands enfraquecem e se dispersam naturalmente na atmosfera revolta do reino elemental do ar, o iniciado enfrenta uma corrida contra o tempo para alcançar o Brazier of Eternal Flames antes que a chama se apague."},{t="O Totem do Fogo",b="Reacender o braseiro em Valanaar prova a disciplina e a reverência do iniciado para com os elementos. Em reconhecimento a essa conquista, os Moldavento concedem ao iniciado o seu Totem do Fogo. Conforme ensinado pelos anciãos, o poder elemental prontamente serve àqueles que o respeitam, mas consumirá impiedosamente aqueles que não o fizerem."}},faq={{q="O que é Call of Fire?",a="Call of Fire é um rito de passagem sagrado no qual um aspirante a xamã ajuda a invocar espíritos das chamas e a capturar a Eternal Flame. Levar este fogo sagrado até Valanaar prova o respeito do iniciado pelo plano elemental e concede a ele o seu Totem do Fogo.",al={"o que é call of fire","missão call of fire","sobre o que é esta missão"}},{q="Quem é Olariaan?",a="Olariaan é o líder ritual que conduz a cerimônia no Brazier of Offering. Ele coloca os materiais necessários sobre o altar e conclama os espíritos das chamas para acender a Eternal Flame.",al={"quem é olariaan","papel de olariaan","quem inicia o ritual"}},{q="O que é a Eternal Flame?",a="A Eternal Flame é uma manifestação dos espíritos das chamas conclamados das Firelands durante o ritual dos Moldavento. Os iniciados devem capturá-la em uma tocha e acender o Brazier of Eternal Flames em Valanaar.",al={"o que é a eternal flame","eternal flame muralha celeste"}},{q="Por que a chama deve ser levada rapidamente para Valanaar?",a="O fogo elemental bruto invocado origina-se das Firelands, e seu calor intenso se dissipa rapidamente dentro do reino dominado pelo ar da Muralha Celeste. Os iniciados devem mover-se com rapidez para garantir que a tocha não se apague antes de chegar a Valanaar.",al={"por que a eternal flame se dissipa","por que correr para valanaar","chamas das firelands muralha celeste"}},{q="Quem são os Moldavento?",a="Os Moldavento são uma ordem residente na Muralha Celeste que guia os iniciados através de testes elementais. Eles honram o equilíbrio e o poder dos planos elementais e supervisionam a concessão de totens.",al={"quem são os moldavento","facção moldavento"}},{q="Qual é a recompensa por concluir o teste?",a="Concluir o ritual e reacender com sucesso o braseiro em Valanaar concede ao iniciado o seu Totem do Fogo, uma ferramenta vital e foco para canalizar poderes elementais ígneos.",al={"recompensa de call of fire","recompensa do totem do fogo","o que você ganha com call of fire"}}},fp="12,164,19.298.0,23.246.0,14.247.0,25.197.0,16.148.0,26.201.0,50.148.0,24.178.0,44.140.0"}
P.entries["quest:97263"] = {n="Your Package Has Arrived",s="\"Your Package Has Arrived\" é uma tarefa urgente de mensageiro sobre correspondência extraviada destinada à entrega em Altaforja. Um caixote de mensageiro enviado desde a fortaleza Wildhammer de Ninho da Águia foi deixado abandonado ao lado de uma caixa de correio, endereçado especificamente a Eldrun Stormbreaker. Viajantes que descobrem o pacote têm a tarefa de concluir sua jornada e garantir que ele chegue ao seu devido dono.",h="\"Your Package Has Arrived\" é uma tarefa urgente de mensageiro sobre correspondência extraviada destinada à...",kw={"ninho da águia","eldrun stormbreaker","altaforja","caixa de correio","pacote extraviado","entrega urgente","wildhammer","your package has arrived"},ang={["faction:Alliance"]="Manter rotas de comunicação abertas e confiáveis entre as Terras Agrestes e Altaforja é vital para os interesses da Aliança por Khaz Modan e territórios do norte.",["race:Dwarf"]="Os anões reconhecerão os fortes laços entre os Bronzebeard de Altaforja e seus primos Wildhammer em Ninho da Águia, tornando a chegada segura deste pacote uma questão de respeito entre clãs."},sec={{t="Carga Extraviada",b="Um contratempo postal deixa vários pacotes perdidos abandonados ao lado de uma caixa de correio da cidade, deixados ao ar livre em vez de serem transportados com segurança aos seus destinos. Em meio a esse monte desordenado de carga negligenciada repousa um pacote urgente marcado para entrega vindo desde Ninho da Águia, o reduto montanhoso dos anões Wildhammer nas Terras Agrestes. Transportar mercadorias entre postos avançados distantes por Khaz Modan e Lordaeron pode ser perigoso e caótico, o que significa que pacotes extraviados ocasionalmente exigem que um transeunte atento intervenha e conclua o trajeto de entrega adequadamente."},{t="Um Pacote para Eldrun Stormbreaker",b="O pacote extraviado traz uma identificação clara indicando Altaforja como seu destino e Eldrun Stormbreaker como seu destinatário final. Marcado explicitamente com um aviso de urgência, qualquer que seja a carga contida no embrulho, ela foi considerada importante o bastante para ser despachada dos picos rústicos das Terras Agrestes para os salões subterrâneos da capital dos anões. Apanhar o caixote significa assumir a responsabilidade do serviço postal, garantindo que Eldrun receba o que foi enviado através de cordilheiras e colinas selvagens antes que seja roubado ou totalmente esquecido."}},faq={{q="O que é o pacote encontrado perto da caixa de correio?",a="O pacote é uma entrega urgente enviada de Ninho da Águia, nas Terras Agrestes, endereçada a um destinatário chamado Eldrun Stormbreaker em Altaforja. Ele parece ter sido extraviado junto com vários outros pacotes perto de uma caixa de correio em vez de chegar ao seu destino final por meio do manuseio normal de mensageiros.",al={"o que é o pacote","pacote extraviado","o que foi deixado perto da caixa de correio","pacote da caixa de correio"}},{q="Quem é Eldrun Stormbreaker?",a="Eldrun Stormbreaker é o destinatário designado do pacote extraviado dentro da capital dos anões de Altaforja. Embora o próprio pacote esteja claramente marcado com seu nome e indicado como urgente, pouco mais é revelado na etiqueta de envio até que a entrega seja colocada com segurança em suas mãos.",al={"quem é eldrun stormbreaker","eldrun stormbreaker","quem recebe o pacote","destinatário do pacote"}},{q="De onde o pacote foi enviado?",a="A remessa originou-se em Ninho da Águia, o proeminente assentamento e fortaleza do clã Wildhammer situado no alto das montanhas das Terras Agrestes. A etiqueta mostra que ela viajou através de regiões em direção a Altaforja antes de ser extraviada perto de uma caixa de correio local ao longo do trajeto.",al={"de onde veio o pacote","origem do pacote","de onde foi enviado","entrega de ninho da águia"}},{q="Por que o pacote foi marcado como urgente?",a="A etiqueta de envio traz uma marcação de urgência porque quem enviou o caixote de Ninho da Águia considerou seu conteúdo ou prazo de chegada de grande importância. Dada a distância entre territórios entre as terras altas Wildhammer e a cidade de Altaforja, uma carga atrasada poderia causar problemas significativos para Eldrun Stormbreaker.",al={"por que é urgente","entrega urgente","o que há dentro do pacote","por que urgente"}},{q="Por que o pacote foi deixado junto a uma caixa de correio?",a="Vários pacotes foram inexplicavelmente deixados abandonados perto da caixa de correio em vez de serem separados e distribuídos por mensageiros locais. Tráfego intenso de entregas, confusão logística ou simples negligência frequentemente levam cargas a serem temporariamente extraviadas em trânsito, cabendo a aventureiros prestativos resolver o descuido.",al={"por que foi abandonado","por que o pacote foi deixado","correspondência perdida","pacotes extraviados"}},{q="Onde este pacote precisa ser entregue?",a="O pacote está marcado para entrega em Altaforja, direcionado especificamente às mãos de Eldrun Stormbreaker. Qualquer um que descubra a carga extraviada deve assumir o papel de mensageiro e levar o embrulho urgente diretamente a Eldrun dentro da cidade-fortaleza subterrânea dos anões.",al={"onde entregar","destino do pacote","local de entrega","para quem levar o pacote"}},{q="Que ligação existe entre Ninho da Águia e Altaforja?",a="Ninho da Águia serve como o coração dos anões Wildhammer, enquanto Altaforja é a grandiosa sede do clã Bronzebeard. Embora os clãs mantenham costumes e lares distintos, correspondência regular, comércio e laços de parentesco fluem entre os penhascos das Terras Agrestes e a Grande Forja sob a montanha.",al={"ninho da águia e altaforja","comércio entre wildhammer e bronzebeard","conexão entre altaforja e ninho da águia","por que enviar correspondência de ninho da águia"}}},fp="24,144,17.359.0,32.258.0,41.199.0,27.195.0,31.198.0,33.183.0,46.149.0,45.138.0,56.245.0"}
P.entries["quest:97265"] = {n="Hate the Hatefury",s="Aka'rai, na Aldeia Pescassombra, pede que você ataque os sátiros Hatefury em Sargeron. Seu ressentimento vem de uma barganha que o deixou em busca de vingança.",h="Aka'rai, na Aldeia Pescassombra, pede que você ataque os sátiros Hatefury em Sargeron.",kw={"aka'rai","desolação","hate the hatefury","hatefury","sargeron","sátiro","aldeia pescassombra","pedra da alma"},sec={{t="O ressentimento de Aka'rai",b="Aka'rai fala de uma barganha com um sátiro que lhe prometeu poder e conhecimento. Ele diz que os Hatefury o descartaram, deixando-o com menos do que tinha antes. Agora ele pede que você ataque o acampamento deles a nordeste da Aldeia Pescassombra, em Sargeron. O sangue deles é o preço que ele exige por sua vingança."},{t="A barganha de sangue",b="Depois da luta, Aka'rai diz que um Hatefury escapou do seu ataque. Ele identifica esse sátiro como aquele que participou com ele de um ritual marcado por sangue derramado. O sátiro está com a pedra da alma de Aka'rai, por isso Aka'rai teme sair da Aldeia Pescassombra enquanto ela permanecer nas mãos dele. Por ora, ele diz que seu trabalho está concluído."}},faq={{q="Quem está pedindo ajuda?",a="Aka'rai, na Aldeia Pescassombra, pede que você ataque os sátiros Hatefury em Sargeron.",al={"quem é aka'rai","aka rai","quem oferece hatefury"}},{q="Por que Aka'rai quer que os Hatefury sejam atacados?",a="Aka'rai diz que os Hatefury o descartaram depois de uma barganha que prometia poder e conhecimento.",al={"por que hatefury","vingança de aka'rai","rancor contra sátiros"}},{q="Onde estão os Hatefury?",a="O acampamento dos Hatefury fica em Sargeron, em Desolação, a nordeste da Aldeia Pescassombra.",al={"localização dos hatefury","sátiros de sargeron","onde fica o acampamento"}},{q="O que Aka'rai buscava com a barganha?",a="Aka'rai diz que a barganha prometia poder, conhecimento além dos tomos comuns e um lacaio cheio de disposição.",al={"acordo de aka'rai","barganha com sátiro","acordo por poder"}}},fp="17,149,19.285.0,17.298.1,23.80.0,44.91.0,23.78.0,29.94.0"}
P.entries["quest:97275"] = {n="Whuut's the Rush",s="Whuut's the Rush é uma tarefa alquímica que destaca a tensão entre o talento bruto e o ofício disciplinado. Yelmak encarrega um aventureiro de entregar um tônico humilde e cuidadosamente preparado ao seu jovem prodígio Whuut, demonstrando que a verdadeira maestria começa com plantas comuns em vez de desperdiçar reagentes raros.",h="Whuut's the Rush é uma tarefa alquímica que destaca a tensão entre o talento bruto e o ofício disciplinado.",kw={"alquimia","lótus preto","taboa","herborismo","sálvia-prata-da-montanha","poção","capim-lança","whuut","yelmak"},ang={["faction:Horde"]="Yelmak orienta aspirantes a alquimista nos caminhos da paciência, do engenho e do respeito pelos ingredientes locais de Kalimdor, em vez de desperdiçar suprimentos preciosos.",["profession:Herbalism"]="Coletores e herboristas apreciarão a lição central desta tarefa: compreender as propriedades de plantas comuns, como capim-lança e taboa, pode ser tão vital para o ofício quanto caçar flores lendárias."},sec={{t="O Prodígio Ansioso",b="Na agitação da loja de alquimia, o talento bruto frequentemente colide com a ambição imprudente. Whuut é reconhecido como um autêntico prodígio, possuindo um instinto natural no manuseio da haste de mistura. No entanto, sua impaciência o leva a esgotar os reagentes mais raros da loja sem antes estabelecer um domínio sólido sobre as técnicas fundamentais de preparo. Antes mesmo de aprender o equilíbrio sutil das ervas comuns, ele busca plantas lendárias, tratando a alquimia como uma corrida em vez de uma disciplina."},{t="Uma Lição em um Frasco",b="Para conter seu aprendiz sem sufocar sua paixão, Yelmak elabora uma lição em um frasco. Em vez de repreender Whuut, Yelmak prepara uma poção refinada usando apenas capim-lança e taboa comuns por meio de um método de tônico rápido. Entregue nas mãos de Whuut enquanto o jovem sonha acordado com Lótus Preto e Sálvia-prata-da-montanha, a mistura humilde revela que a verdadeira maestria alquímica vem da técnica, da paciência e do respeito pela flora comum."}},faq={{q="Quem é Whuut?",a="Whuut é um jovem prodígio da alquimia que está ansioso para experimentar as ervas mais raras que existem. Embora seja inegavelmente talentoso, sua pressa em preparar poções com reagentes exóticos o leva a negligenciar os fundamentos do ofício alquímico.",al={"quem é whuut","história de whuut","sobre whuut"}},{q="Quem é Yelmak?",a="Yelmak é um alquimista experiente que atua como mentor na loja. Preocupado com o desperdício de suprimentos preciosos por parte de Whuut, Yelmak prepara um tônico simples para demonstrar que a verdadeira maestria começa com ingredientes locais e humildes.",al={"quem dá esta missão","papel de yelmak","quem é yelmak"}},{q="Por que Yelmak envia você com uma poção para Whuut?",a="Yelmak quer ensinar a Whuut paciência e respeito pelos fundamentos da alquimia. Ao mostrar que uma poção eficaz pode ser preparada usando uma flora comum como capim-lança e taboa, ele espera conter o hábito de Whuut de correr diretamente atrás de ervas raras e desconhecidas.",al={"qual é a lição de yelmak","por que yelmak envia a poção","objetivo da missão"}},{q="Quais ingredientes Yelmak usou em sua poção?",a="Yelmak prepara o tônico de demonstração usando nada mais do que capim-lança e taboa comuns, provando ao seu aprendiz que a vegetação comum à beira da estrada pode produzir resultados notáveis quando preparada com um toque cuidadoso.",al={"o que há na poção","reagentes da poção de yelmak","ingredientes do tônico rápido"}},{q="Com quais reagentes raros Whuut estava tentando trabalhar?",a="Antes de ser interrompido, Whuut tentava avidamente alcançar algumas das espécies de flora mais preciosas e lendárias de Azeroth, especificamente Lótus Preto e Sálvia-prata-da-montanha, ignorando completamente os ingredientes do cotidiano.",al={"o que whuut estava preparando","ervas raras que whuut quer","quais reagentes whuut usou"}},{q="Whuut aprende a lição?",a="Ao provar o tônico e conhecer sua humilde receita, Whuut fica perplexo ao ver que plantas comuns puderam produzir tal poção. Ele humildemente admite que Yelmak está certo e decide prestar mais atenção à flora comum que antes menosprezava.",al={"whuut muda de ideia","reação de whuut à poção","desfecho de whuut's the rush"}}},fp="16,161,17.283.0,18.341.0,13.140.0,14.131.0,49.165.0,46.106.0,50.130.0,28.213.0"}
P.entries["quest:97277"] = {n="Grund and Gozwin",s="Grund and Gozwin relata uma emboscada em um acampamento nas colinas nevadas do noroeste, onde um anão e um gnomo foram atacados por um leopardo-das-neves predador. Embora o gnomo tenha sobrevivido graças à espingarda de seu parceiro, seu precioso registro de mecânico foi deixado para trás no tumulto. Aventureiros são enviados para as colinas para recuperar as anotações delicadas e abater a fera à espreita.",h="Grund and Gozwin relata uma emboscada em um acampamento nas colinas nevadas do noroeste, onde um anão e um...",kw={"anão","engenheiro gnomo","gozwin","grund","mecha-walker","registro de mecânico","snow leopard prowler"},ang={["profession:Engineering"]="A ansiedade de Gozwin por perder seu registro de mecânico mostra como os inventores são cautelosos em relação aos seus projetos de mecha-walker e anotações proprietárias.",["race:Dwarf"]="A reação rápida de Grund com uma espingarda e a obstinada camaradagem ao redor da fogueira refletem a lealdade constante que os anões trazem ao viajar ao lado de seus aliados gnomos.",["race:Gnome"]="Gozwin personifica o típico gnomo inventor cujo primeiro instinto após sobreviver ao ataque violento de um predador é se preocupar com a segurança de seus esquemas de mecanostruz."},sec={{t="Uma Emboscada junto ao Fogo",b="Enquanto viajavam juntos pelas colinas nevadas, o anão Grund e seu companheiro gnomo Gozwin montaram um acampamento para a noite. Quando Grund virou as costas para preparar um javali sobre o fogo, um snow leopard prowler saltou dos arbustos e agarrou Gozwin em suas mandíbulas. Reagindo instantaneamente, Grund pegou sua fiel espingarda e disparou um tiro sobre a cabeça da fera, assustando o predador a ponto de fazê-lo soltar o gnomo e fugir para os penhascos gelados."},{t="O Trabalho Perdido de um Inventor",b="Embora Gozwin tenha escapado das mandíbulas do felino com arranhões profundos em vez de ferimentos fatais, o acampamento deles ficou completamente desorganizado. No caos da retirada, Gozwin deixou cair seu precioso Registro de Mecânico de Gozwin — um caderno técnico contendo esquemas essenciais para seu mecha-walker. Terrivelmente ansioso com a possibilidade de alguém descobrir seus segredos de engenharia, o gnomo ferido não conseguiu descansar até que um aventureiro concordou em se aventurar a noroeste pelas colinas para recuperar seu livro e abater o predador à espreita."}},faq={{q="Quem são Grund and Gozwin?",a="Grund é um anão campista armado com uma espingarda, e Gozwin é seu companheiro engenheiro gnomo. Enquanto montavam acampamento nas colinas nevadas para assar um javali, foram emboscados por um leopardo-das-neves à espreita, deixando Gozwin ferido e seus equipamentos espalhados.",al={"quem são grund e gozwin","grund gozwin"}},{q="O que atacou Gozwin no acampamento?",a="Um feroz snow leopard prowler emboscou Gozwin por trás enquanto Grund preparava o jantar. A fera cravou os dentes no gnomo e tentou arrastá-lo antes que Grund disparasse um tiro de advertência que espantou o felino.",al={"o que atacou gozwin","quem atacou gozwin"}},{q="Por que o Registro de Mecânico de Gozwin é tão importante para ele?",a="O Registro de Mecânico de Gozwin contém esquemas técnicos e anotações vitais sobre seu mecha-walker. Gozwin temia que, se qualquer outra pessoa pusesse as mãos em suas anotações pessoais de engenharia, seu projeto seria completamente arruinado.",al={"por que o registro é importante","registro de mecânico gozwin"}},{q="Quão gravemente ferido Gozwin ficou no ataque?",a="Sim, Gozwin sobreviveu à emboscada graças ao tiro rápido de espingarda de Grund. Ele escapou com arranhões profundos e em estado grave de choque, embora esteja se recuperando em segurança enquanto Grund cuida dele.",al={"gozwin está bem","gozwin sobreviveu"}},{q="Onde fica o acampamento de Grund and Gozwin?",a="O acampamento da dupla fica aninhado nas colinas a noroeste. Aventureiros são enviados ao acampamento para recuperar o livro de registros perdido e eliminar o leopard prowler que ronda a área.",al={"onde fica o acampamento","localização do acampamento de grund"}},{q="O que aconteceu com a refeição que Grund estava preparando?",a="Após se assustar e largar Gozwin devido aos disparos de Grund, o leopardo-das-neves predador retornou ao acampamento abandonado e devorou o javali assado que Grund estava preparando para o jantar.",al={"o que aconteceu com o javali assado","leopardo comendo javali"}}},fp="16,180,21.316.0,22.332.0,25.181.0,29.176.0,51.147.0,40.146.0,41.123.0,46.118.0"}
